INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 1, 'Kwa jina la Mwenyezi Mungu, Mwingi wa rehema, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 2, 'Sifa njema zote ni za Mwenyezi Mungu, Mola Mlezi wa walimwengu.[1]', '[1] Mola Mlezi ni yule anayewalea walimwengu wote. Nao walimwengu ni kila kisichokuwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 3, 'Mwingi wa rehema, Mwenye kurehemu.[1]', '[1] Katika misingi waliyokubaliana juu yake watangulizi wema wa umma huu na maimamu wake ni kuamini kwamba Mwenyezi Mungu ana majina na sifa nzuri nzuri.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 4, 'Mmiliki wa Siku ya Malipo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 5, 'Ni Wewe tu tunayeabudu, na ni Wewe tu tunayeomba msaada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 6, 'Tuongoe kwenye njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 7, 'Njia ya wale uliowaneemesha. Siyo ya wale waliokasirikiwa, wala waliopotea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 1, 'Alif Lam Mim.[1]', '[1] Herufi hizi "Alif Lam Mim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 2, 'Hiki ni Kitabu kisichokuwa na shaka yoyote ndani yake; ni uongofu kwa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 3, 'Ambao huyaamini ya ghaibu na hudumisha Sala, na hutoa katika yale tuliyowaruzuku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 4, 'Na ambao wanayaamini yaliyoteremshwa kwako, na yaliyoteremshwa kabla yako, na Akhera wana yakini nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 5, 'Hao wako kwenye uongofu utokao kwa Mola wao Mlezi, na hao ndio waliofaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 6, 'Hakika, wale waliokufuru ni sawa kwao uwaonye au usiwaonye, hawaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 7, 'Mwenyezi Mungu ameziziba nyoyo zao na kusikia kwao, na juu ya kuona kwao kuna pazia. Nao wana adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 8, 'Na katika watu, kuna wale wanaosema, "Tumemwamini Mwenyezi Mungu na Siku ya Mwisho", wala wao si Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 9, 'Wanamhadaa Mwenyezi Mungu na wale walioamini, lakini hawahadai ila nafsi zao; nao hawatambui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 10, 'Nyoyoni mwao kuna maradhi[1], na Mwenyezi Mungu amewazidishia maradhi. Basi watakuwa na adhabu chungu kwa sababu ya kusema kwao uongo.', '[1] Kilichokusudiwa na maradhi hapa ni maradhi ya shaka, dhana potovu na unafiki.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 11, 'Na wanapoambiwa: Msifanye uharibifu katika ardhi. Husema: "Bali sisi ni watengenezaji."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 12, 'Tambueni! Kwa hakika, wao ndio waharibifu, lakini hawatambui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 13, 'Na wanapoambiwa: Aminini kama walivyoamini watu. Husema: "Tuamini kama walivyoamini wapumbavu?" Hakika wao ndio wapumbavu, lakini hawajui tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 14, 'Na wanapokutana na walioamini, husema: ''Tumeamini.'' Na wanapokuwa peke yao na mashetani wao, husema: ''Hakika sisi tu pamoja nanyi. Hakika sisi tunafanya dhihaka tu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 15, 'Mwenyezi Mungu atawadhihaki na atawaacha katika upotovu wao wakitangatanga ovyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 16, 'Hao ndio walioununua upotovu kwa uongofu; lakini biashara yao haikupata faida, wala hawakuwa wenye kuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 17, 'Mfano wao ni kama mfano wa aliyekoka moto, na ulipoangaza vile vilivyo kandokando yake, Mwenyezi Mungu aliiondoa nuru yao na akawaacha katika viza mbalimbali, hawaoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 18, 'Ni viziwi, mabubu, vipofu; kwa hivyo hawatarejea.[1]', '[1] Ni viziwi kwa sababu hawaisikii heri. Ni mabubu kwa sababu hawaitamki heri. Na ni vipofu kwa sababu hawaioni haki. Kwa hivyo, hawatarejea katika haki kwa kuwa waliiacha baada ya kuijua. Tofauti na mwenye kuiacha haki kwa ujinga na upotovu, yeye yuko karibu zaidi na kurudi katika haki.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 19, 'Au ni kama mvua kubwa itokayo mbinguni, ina viza mbalimbali, na radi, na umeme; wakawa wanatia vidole vyao katika masikio yao kwa sababu ya mapigo ya radi, kwa kuogopa kufa. Na Mwenyezi Mungu amewazingira makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 20, 'Unakaribia umeme huo kunyakua kuona kwao. Kila ukiwatolea mwangaza, wanatembea ndani yake. Na linapowawia giza, wanasimama. Na angelitaka Mwenyezi Mungu, angeliondoa kusikia kwao na kuona kwao. Hakika Mwenyezi Mungu ni Muweza mno wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 21, 'Enyi watu! Muabuduni Mola wenu Mlezi aliyekuumbeni nyinyi na wale wa kabla yenu, ili mpate kucha (Mwenyezi Mungu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 22, '(Mwenyezi Mungu) ambaye alikufanyieni ardhi hii kuwa kama tandiko, na mbingu kama paa. Na akateremsha maji kutoka mbinguni, na kwayo akatoa mazao yawe riziki zenu. Basi msimfanyie Mwenyezi Mungu wenza, na hali nyinyi mnajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 23, 'Na ikiwa mna shaka kwa hayo tuliyomteremshia mja wetu, basi leteni sura moja ya mfano wake, na muwaite mashahidi wenu kando na Mwenyezi Mungu, ikiwa nyinyi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 24, 'Na ikiwa hamtafanya - na wala hamtofanya kamwe - basi uogopeni Moto ambao kuni zake ni watu na mawe, umeandaliwa makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 25, 'Na wabashirie walioamini na wakatenda mema kwamba watapata mabustani yapitayo mito chini yake; kila watakapopewa matunda humo, watasema: ''Haya ndiyo kama tuliyopewa mbele.'' Na wataletewa matunda yaliyofanana; na humo watakuwa na wake waliotakaswa; na wao humo watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 26, 'Hakika Mwenyezi Mungu haoni haya kutoa mfano hata wa mbu na ulio wa zaidi yake. Ama wale walioamini hujua ya kwamba hiyo ni haki iliyotoka kwa Mola wao Mlezi. Lakini wale waliokufuru, husema: ''Ni nini analokusudia Mwenyezi Mungu kwa mfano huu?'' Kwa mfano huu huwapoteza wengi na huwaongoa wengi; lakini hawapotezi kwa huo ila wale wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 27, 'Wale wanaovunja agano la Mwenyezi Mungu baada ya kwishalifunga, na wakayakata aliyoamrisha Mwenyezi Mungu kuungwa, na wakafanya uharibifu katika ardhi; hao ndio wenye hasara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 28, 'Vipi mnamkufuru Mwenyezi Mungu na hali mlikuwa wafu, akakufufueni! Kisha atakufisheni, tena atakufufueni, kisha kwake mtarejeshwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 29, 'Yeye ndiye aliyekuumbieni vyote vilivyo katika ardhi, kisha akaelekea kuziumba mbingu, na akazifanya kuwa mbingu saba, naye ndiye ajuaye mno kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 30, 'Na pale Mola wako Mlezi alipowaambia Malaika: ''Hakika Mimi nitamweka katika ardhi Khalifa (mfwatizi)'', wakasema: Utaweka humo atakayefanya uharibifu humo na kumwaga damu, hali sisi tunakutakasa kwa sifa zako na tunakutaja kwa utakatifu wako? Akasema: ''Hakika Mimi nayajua msiyoyajua.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 31, 'Na akamfundisha Adam majina ya vitu vyote, kisha akaviweka mbele ya Malaika, na akasema: Niambieni majina ya hivi ikiwa nyinyi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 32, 'Wakasema: Subhanaka (Wewe umetakasika!) Hatuna elimu isipokuwa yale uliyotufunza Wewe. Hakika Wewe ndiye ajuaye zaidi, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 33, 'Akasema: ''Ewe Adam! Waambie majina yake.'' Basi alipowaambia majina yake alisema: Sikukwambieni kwamba Mimi ninajua siri za mbinguni na za duniani, na ninayajua mnayoyadhihirisha na mliyokuwa mnayaficha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 34, 'Na tulipowaambia Malaika: ''Msujudieni Adam'', wakamsujudia wote isipokuwa Iblis, alikataa na akajivuna na akawa katika makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 35, 'Na tulisema: Ewe Adam! Kaa wewe na mkeo katika Bustani, na kuleni humo maridhawa popote mpendapo, lakini msiukaribie mti huu tu; mkawa katika wale waliodhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 36, 'Lakini Shetani aliwatelezesha hao wawili na akawatoa katika waliyokuwamo, na tukasema: Shukeni, nanyi ni maadui nyinyi kwa nyinyi. Katika ardhi yatakuwa makazi yenu na starehe kwa muda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 37, 'Kisha Adam akapokea maneno kutoka kwa Mola wake Mlezi, na Mola wake Mlezi akamkubalia toba yake; Hakika Yeye ndiye Mwingi wa kukubali toba, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 38, 'Tukasema: Shukeni nyote kutoka humo; na kama ukikufikieni uongofu utokao kwangu, basi watakaofuata uongofu wangu huo, haitakuwa hofu juu yao wala hawatahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 39, 'Na wenye kukufuru na kuzikanusha ishara zetu, hao ndio watu wa Motoni, wao watadumu humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 40, 'Enyi Wana wa Israili! Kumbukeni neema yangu niliyokuneemesheni, na timizeni agano langu, na Mimi nitatimiza agano lenu, na niogopeni Mimi tu.[1]', '[1] “Enyi Wana wa Israili!” Anayekusudiwa na Israili hapa ni Nabii Yaaqub, amani iwe juu yake.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 41, 'Na aminini niliyoyateremsha ambayo yanasadikisha mliyo nayo, wala msiwe wa kwanza kuyakataa. Wala msiuze ishara zangu kwa thamani ndogo. Na nicheni Mimi tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 42, 'Wala msichanganye haki na batili, na mkaificha haki nanyi mnajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 43, 'Na shikeni Sala, na toeni Zaka, na inameni pamoja na wanaoinama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 44, 'Je, mnawaamrisha watu mema na mnajisahau wenyewe, na hali nyinyi mnasoma Kitabu? Basi je, hamtumii akili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 45, 'Na tafuteni msaada kwa kusubiri na kwa kusali; na kwa hakika jambo hilo ni gumu isipokuwa kwa wanyenyekevu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 46, 'Ambao wana yakini kuwa hakika watakutana na Mola wao Mlezi na ya kuwa hakika ni wa kurejea kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 47, 'Enyi Wana wa Israili! Kumbukeni zile neema zangu nilizokuneemesheni, na nikakuboresheni kuliko wote wengineo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 48, 'Na icheni Siku ambayo mtu hatamfaa mtu kwa lolote, wala hayatakubaliwa kwake maombezi, wala hakitapokewa kikomboleo kwake; wala hawatanusuriwa.[1]', '[1] Aya hii imekanusha huko Akhera mambo ambayo wanadamu wamezoea kuyafanya katika dunia hii wanapopatwa na shida.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 49, 'Na (kumbukeni) tulipowaokoa kutoka kwa watu wa Firauni, waliokuwa wakikupeni adhabu mbaya, wakiwachinja wana wenu wa kiume, na wakiwawacha hai wanawake wenu. Na katika hayo kulikuwa na mtihani mkubwa kutoka kwa Mola wenu Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 50, 'Na tulipoipasua bahari kwa ajili yenu na tukakuokoeni, na tukawazamisha watu wa Firauni, na huku mnatazama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 51, 'Na tulipomuahidi Musa usiku arubaini, kisha mkamchukua ndama (mkamuabudu) baada yake, na mkawa wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 52, 'Kisha tukakusameheni baada ya hayo, ili mpate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 53, 'Na tulipompa Musa Kitabu na pambanuo ili mpate kuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 54, 'Na Musa alipowaambia watu wake: Enyi watu wangu! Hakika nyinyi mmezidhulumu nafsi zenu kwa kuchukua kwenu ndama (kumuabudu). Basi tubuni kwa Muumba wenu na ziueni nafsi zenu. Haya ni bora kwenu mbele ya Muumba wenu. Naye akapokea toba yenu. Hakika Yeye ndiye apokeaye toba mno, Mwenye kurehemu zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 55, 'Na mliposema: ''Ewe Musa! Hatutakuamini mpaka tumwone Mwenyezi Mungu waziwazi.'' Basi ukakunyakueni mpigo wa radi nanyi mnaangalia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 56, 'Kisha tukakufufueni baada ya kufa kwenu, ili mpate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 57, 'Na tukakutilieni kivuli kwa mawingu na tukakuteremshieni Manna na Salwa; tukakwambieni: ''Kuleni katika vitu vizuri hivi tulivyokuruzukuni.'' Nao hawakutudhulumu Sisi lakini walikuwa wakizidhulumu nafsi zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 58, 'Na tuliposema: Ingieni mji huu, na humo mle mpendapo maridhawa, na ingieni katika mlango wake kwa unyenyekevu, na semeni: ''Tusamehe!'' Tutakusameheni makosa yenu, na tutawazidishia wema wafanyao wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 59, 'Lakini waliodhulumu waliibadili kauli isiyokuwa waliyoambiwa. Kwa hivyo tukaiteremsha juu ya wale waliodhulumu adhabu kutoka mbinguni kwa sababu ya walivyokuwa wakivuka mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 60, 'Na Musa alipoomba maji kwa ajili ya watu wake, tukamwambia: ''Lipige jiwe kwa fimbo yako.'' Mara zikatimbuka chemichemi kumi na mbili; kila kabila likajua mahali pake pa kunywea. Tukawaambia: Kuleni na mnywe katika riziki ya Mwenyezi Mungu, wala msiasi katika nchi mkafanya uharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 61, 'Na mliposema: ''Ewe Musa! Hatuwezi kuvumilia chakula cha namna moja tu. Basi tuombee kwa Mola wako Mlezi atutolee vile vinavyomea katika Ardhi, kama mboga zake, na matango yake, na vitunguu saumu vyake, na adesi zake, na vitunguu maji vyake.'' Akasema: "Mnabadili kilicho duni kwa kilicho bora? Shukeni mjini, huko mtapata mlivyoviomba." Na wakapigwa na unyonge, na umasikini, na wakastahili ghadhabu ya Mwenyezi Mungu. Na haya ni kwa sababu walikuwa wakiyakufuru maneno ya Mwenyezi Mungu, na wakiwauwa Manabii pasipo haki. Hayo ni kwa walivyoasi na wakapindukia mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 62, 'Hakika Walioamini, na Mayahudi na Wakristo, na Wasabai; yeyote atakayemuamini Mwenyezi Mungu na Siku ya Mwisho na akatenda mema, basi watapata malipo yao kwa Mola wao Mlezi, wala haitakuwa hofu juu yao, wala hawatahuzunika.[1]', '[1] Hii ilikuwa hukumu yao kabla ya utume wa Muhammad - rehema na amani za Mwenyezi Mungu ziwe juu yake. Na aya hii ilitajwa hapa kwa sababu Mwenyezi Mungu alipowakashifu wana wa Israili kwa dhambi zao, na maovu yao, huenda iliingia katika nafsi za baadhi yao kwamba sio wote waliyafanya hayo. Kwa hivyo, aya hii ikawaondoa wale ambao hawakuhusika katika kashfa hiyo.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 63, 'Na tulipochukua agano lenu, na tukaunyanyua mlima juu yenu (tukakwambieni): Shikeni kwa nguvu haya tuliyokupeni, na yakumbukeni yaliyomo ndani yake ili mpate kuokoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 64, 'Kisha mligeuka baada ya haya. Na lau kuwa si fadhila za Mwenyezi Mungu juu yenu na rehema zake, mngelikuwa miongoni mwa wenye kupata hasara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 65, 'Na hakika mlikwishayajua ya wale miongoni mwenu waliopindukia mipaka kuhusu Sabato (siku ya Jumamosi) na tukawaambia: Kuweni manyani mliodhalilika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 66, 'Kwa hivyo tukayafanya hayo kuwa onyo kwa wale waliokuwa katika zama zao na waliokuja baada yao, na mawaidha kwa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 67, 'Na Musa alipowaambia watu wake: Hakika Mwenyezi Mungu anakuamrisheni mchinje ng''ombe. Wakasema: Je! Unatufanyia mzaha? Akasema: "A''udhu billah (Najikinga kwa Mwenyezi Mungu) nisiwe miongoni mwa wajinga."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 68, 'Wakasema: Tuombee kwa Mola wako Mlezi atupambanulie ni ng''ombe gani? Akasema: Hakika Yeye anasema kwamba ng''ombe huyo si mpevu, wala si kinda, bali ni wa katikati baina ya hao. Basi fanyeni mnavyoamrishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 69, 'Wakasema: Tuombee kwa Mola wako Mlezi atupambanulie ni ipi rangi yake? Akasema: Yeye anasema kuwa ng''ombe huyo ni wa manjano, na rangi yake imekoza, huwapendeza wanaomtazama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 70, 'Wakasema: Tuombee kwa Mola wako Mlezi atupambanulie ni yupi? Hakika tunaona ng''ombe wamefanana. Na kwa yakini, In sha Allah (Mwenyezi Mungu akipenda), tutaongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 71, 'Akasema: Yeye anasema kuwa huyo ni ng''ombe asiyetiwa kazini kulima Ardhi wala kumwagia maji kwenye mimea, mzima, hana baka. Wakasema: Sasa umeleta (jambo la) haki. Basi wakamchinja, na walikaribia kuwa wasifanye hayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 72, 'Na mlipomuua mtu, kisha mkahitilafiana kwayo, na Mwenyezi Mungu ni mwenye kuyatoa hayo mliyokuwa mkiyaficha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 73, 'Tukasema: Mpigeni (mtu huyo) kwa kipande chake (huyo ng''ombe). Ndivyo hivi Mwenyezi Mungu huwahuisha wafu; na anakuonyesheni ishara zake ili mpate kufahamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 74, 'Kisha nyoyo zenu zikawa ngumu baada ya hayo, hata zikawa kama mawe au ngumu zaidi; kwani kuna mawe yanayotimbuka mito, na kuna mengine yanayopasuka yakatoka maji ndani yake, na kuna mengine huanguka kwa sababu ya kumhofu Mwenyezi Mungu. Na Mwenyezi Mungu si mwenye kughafilika mbali na mnayoyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 75, 'Mnatumai watakuaminini na hali baadhi yao walikuwa wakisikia maneno ya Mwenyezi Mungu, kisha wanayabadili baada ya kuwa wameyafahamu, na hali wanajua?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 76, 'Na wanapokutana na wale walioamini, husema: ''Tumeamini.'' Na wanapokuwa peke yao, wao kwa wao, husema: Mnawaambia aliyokufunulieni Mwenyezi Mungu ili wapate kukuhojini kwayo mbele ya Mola wenu Mlezi? Kwani hamfahamu nyinyi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 77, 'Kwani hawajui ya kwamba Mwenyezi Mungu anayajua wanayoyaficha na wanayoyaweka wazi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 78, 'Na wamo miongoni mwao wasiojua kusoma; hawakijui Kitabu isipokuwa uongo wanaoutamani, nao hawana ila ni kudhania tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 79, 'Basi ole wao wanaoandika kitabu kwa mikono yao, kisha wakasema: ''Hiki kimetoka kwa Mwenyezi Mungu'', ili wanunue kwacho thamani ndogo. Basi ole wao kwa yale iliyoyaandika mikono yao, na ole wao kwa yale wanayoyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 80, 'Na walisema: Hautatugusa Moto ila kwa siku chache tu. Sema: Mmechukua agano kwa Mwenyezi Mungu? Kwa hivyo Mwenyezi Mungu hatakwenda kinyume na agano lake. Au mnamsingizia Mwenyezi Mungu mambo msiyoyajua?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 81, 'Ndiyo, anayechuma ubaya - na makosa yake yakamzingira, hao ndio watu wa Motoni; humo watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 82, 'Na wale walioamini na wakatenda mema, hao ndio watu wa Bustanini, humo watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 83, 'Na tulipofunga agano na Wana wa Israili: ''Hamtamuabudu yeyote ila Mwenyezi Mungu; na muwafanyie wema wazazi na jamaa na mayatima na masikini, na semeni na watu kwa wema, na shikeni Sala, na toeni Zaka.'' Kisha mkageuka isipokuwa wachache tu katika nyinyi; na nyinyi mnapuuza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 84, 'Na tulipochukua agano lenu kuwa hamtamwaga damu zenu, wala hamtatoana majumbani mwenu; nanyi mkakubali, nanyi mnashuhudia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 85, 'Kisha nyinyi kwa nyinyi mnauwana, na mnawatoa baadhi yenu majumbani mwao, mkisaidiana (na adui zao) dhidi yao kwa dhambi na uadui. Na wakikujieni wakiwa mateka, mnawakomboa, na hali mlikatazwa kuwatoa. Je, mnaamini baadhi ya Kitabu na mnamkufuru baadhi yake? Basi ni yapi malipo ya mwenye kutenda hayo miongoni mwenu ila aibu katika maisha ya duniani, na Siku ya Kiyama watapelekwa kwenye adhabu kali kabisa. Na Mwenyezi Mungu si mwenye kughafilika mbali na yale mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 86, 'Hao ndio walionunua uhai wa dunia kwa (uhai wa) Akhera. Kwa hivyo, hawatapunguziwa adhabu, wala hawatanusuriwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 87, 'Na hakika tulimpa Musa Kitabu na tukafuatisha baada yake Mitume wengine. Na tukampa Isa, mwana wa Mariamu hoja zilizo wazi, na tukamtia nguvu kwa Roho Mtakatifu. Basi kila walipokufikieni Mitume kwa yale ambayo hayapendwi na nafsi zenu, mlijivuna; wengine mkawakanusha, na wengine mkawauwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 88, 'Na walisema: ''Nyoyo zetu zimefunikwa.'' Bali Mwenyezi Mungu amewalaani kwa kufuru zao; kwa hivyo ni kidogo tu wanayoyaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 89, 'Na kilipowajia Kitabu kitokacho kwa Mwenyezi Mungu kinachothibitisha waliyo nayo - na wao walikuwa wakiomba ushindi kuwashinda makafiri - yalipowajia yale waliyokuwa wakiyajua, waliyakanusha. Basi laana ya Mwenyezi Mungu iko juu ya makafiri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 90, 'Kiovu kweli walichoziuzia nafsi zao, nacho ni kule kukataa kwao aliyoyateremsha Mwenyezi Mungu, kwa sababu ya kuona haya kwa kuwa Mwenyezi Mungu humteremshia fadhila yake amtakaye miongoni mwa waja wake. Basi wamejiletea wenyewe ghadhabu juu ya ghadhabu. Na makafiri watapata mateso ya kudhalilisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 91, 'Na wanapoambiwa: Yaaminini aliyoyateremsha Mwenyezi Mungu. Wao husema: ''Tunaamini tuliyoteremshiwa sisi.'' Na huyakataa yasiyokuwa hayo. Na hali ya kuwa hii ndiyo haki inayothibitisha yale waliyo nayo wao. Sema: Mbona mliwauwa Manabii wa Mwenyezi Mungu hapo zamani ikiwa kweli mlikuwa Waumini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 92, 'Na alikujieni Musa na hoja zilizo wazi, kisha mkamchukua ndama (kumuabudu) baada yake, na mkawa wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 93, 'Na tulipochukua agano lenu na tukauinua mlima juu yenu (tukakwambieni): Kamateni kwa nguvu haya tuliyokupeni na sikieni. Wakasema: ''Tumesikia na tumeasi!'' Na wakanyweshwa nyoyoni mwao (imani ya) ndama kwa kufuru yao. Sema: Ni uovu mno iliyokuamrisheni imani yenu ikiwa nyinyi ni waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 94, 'Sema: Ikiwa ile nyumba ya Akhera iliyoko kwa Mwenyezi Mungu ni yenu tu bila ya watu wengine, basi tamanini mauti kama nyinyi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 95, 'Wala hawatayatamani kamwe; kwa sababu ya yale mikono yao ilitanguliza. Na Mwenyezi Mungu ni mwenye kuwajua vyema wanaodhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 96, 'Na hakika utawapata ni wenye pupa ya kuishi kuwashinda watu wote, na kuliko washirikina. Mmoja wao anatamani lau angelipewa umri wa miaka elfu. Wala hilo (la kuzidishiwa umri) haliwezi kumweka mbali na adhabu, ili apewe umri mrefu. Na Mwenyezi Mungu anayaona vyema wanayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 97, 'Sema: Aliyekuwa ni adui wa Jibril, basi huyo ndiye aliyeiteremsha Qur''ani moyoni mwako kwa idhini ya Mwenyezi Mungu, inayothibitisha yaliyokuwa kabla yake, na ni uongofu na bishara njema kwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 98, 'Aliyekuwa adui wa Mwenyezi Mungu na Malaika wake na Mitume wake na Jibril na Mikail, basi hakika Mwenyezi Mungu ni adui wa makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 99, 'Hakika tumekuteremshia ishara zilizo wazi na hapana anayezikufuru isipokuwa wenye kupindukia mipaka (wapotovu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 100, 'Kwani kila wanapofunga agano, huwapo kikundi miongoni mwao kinalivunja? Bali wengi wao hawaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 101, 'Na alipowajia Mtume kutoka kwa Mwenyezi Mungu, mwenye kuthibitisha yale waliyo nayo, kundi moja miongoni mwa wale waliopewa Kitabu lilitupa Kitabu cha Mwenyezi Mungu hicho nyuma ya migongo yao kama kwamba hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 102, 'Na wakafuata yale waliyosoma mashetani katika ufalme wa Suleiman. Na wala Suleiman hakukufuru, bali mashetani ndio waliokufuru, wakiwafundisha watu uchawi, na yaliyoteremshwa kwa wale Malaika wawili, Haarut na Maarut huko Baabil. Wala hao hawakumfundisha yeyote mpaka wamwambie: ''Hakika sisi ni mtihani; basi usikufuru.'' Wakajifunza kwa hao wawili yale ya kumtenganisha mtu na mkewe. Wala hawawezi kumdhuru mtu ila kwa kutaka kwa Mwenyezi Mungu. Na wanajifunza yenye kuwadhuru wala hayawanufaishi. Na hakika, walikwishajua kwamba mwenye kuununua (uchawi), hatakuwa na fungu lolote katika Akhera. Na hakika ni kiovu mno walichouza kwacho nafsi zao, laiti wangelikuwa wanajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 103, 'Na lau kuwa wangeamini na wakamcha Mungu, bila ya shaka malipo yatokayo kwa Mwenyezi Mungu yangekuwa bora. Laiti wangelikuwa wanajua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 104, 'Enyi mlioamini! Msiseme: "Raa''ina", na semeni: "Ndhurna". Na sikieni! Na makafiri watapata adhabu chungu.[1]', '[1] Neno “ra’ina" linalomaanisha "tutunze hali zetu". Lakini kwa lugha ya mayahudi linamaanisha ugumu. Basi Mwenyezi Mungu akakataza neno hili ili kuufunga mlango huu, na akawaamrisha waja wake waseme badala yake: “Undhurna" yaani "Tutazame, tutunze.” kwa Waarabu na Mayahudi.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 105, 'Waliokufuru miongoni mwa watu wa Kitabu na washirikina hawapendi mteremshiwe heri yoyote kutoka kwa Mola wenu Mlezi. Na Mwenyezi Mungu humteuwa amtakaye kumpa rehema yake. Na Mwenyezi Mungu ni mwenye fadhila kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 106, 'Ishara yoyote tunayoifuta au tunayoisahaulisha, tunaileta iliyo bora kuliko hiyo, au iliyo mfano wake. Je, hujui kwamba Mwenyezi Mungu ni Muweza mno wa kila kitu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 107, 'Je, hujui kwamba Mwenyezi Mungu ana ufalme wa Mbingu na Ardhi? Nanyi hamna mlinzi wala msaidizi isipokuwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 108, 'Au mnataka kumuuliza Mtume wenu kama alivyoulizwa Musa zamani? Na anayebadilisha Imani kwa ukafiri, bila ya shaka, huyo ameipotea njia iliyo sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 109, 'Wengi miongoni mwa watu wa Kitabu wanapenda lau wangekurudisheni nyinyi muwe makafiri baada ya kuamini kwenu, kwa sababu ya uhasidi uliomo ndani ya nafsi zao, baada ya kwishawapambanukia haki. Basi sameheni na tupilieni mbali mpaka Mwenyezi Mungu atakapoleta amri yake. Hakika Mwenyezi Mungu ni Muweza mno wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 110, 'Na simamisheni Swala na toeni Zaka; na heri mtakazozitangulizia nafsi zenu, mtazikuta kwa Mwenyezi Mungu. Hakika Mwenyezi Mungu anayaona vyema mnayoyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 111, 'Na walisema: ''Hataingia Peponi ila Myahudi au Mkristo.'' Hayo ni matamanio yao. Sema: Leteni ushahidi wenu kama nyinyi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 112, 'Sivyo hivyo! Yeyote anayeelekeza uso wake kwa Mwenyezi Mungu, naye ni mtenda mema, basi ana malipo yake kwa Mola wake Mlezi; wala haitakuwa hofu juu yao wala hawatahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 113, 'Na Mayahudi husema: Wakristo hawana lao jambo (wanalolifuata). Na Wakristo husema: Mayahudi hawana lao jambo (wanalolifuata). Na ilhali wote wanasoma Kitabu kicho hicho (Biblia). Na kadhaalika walisema wale wasiojua kitu mfano wa kauli yao hii. Basi Mwenyezi Mungu atahukumu baina yao Siku ya Kiyama katika yale waliyokuwa wakihitilafiana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 114, 'Na ni nani dhalimu mkubwa kuliko yule anayezuia misikiti ya Mwenyezi Mungu kutajwa ndani yake jina lake, na akajitahidi kuiharibu? (Watu) hao haitawafalia kuingia humo isipokuwa kwa hofu. Duniani watapata hizaya (aibu kubwa maishani), na Akhera watapata adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 115, 'Na mashariki na magharibi ni za Mwenyezi Mungu. Kwa hivyo, kokote mnakoelekea, huko upo uso wa Mwenyezi Mungu. Hakika Mwenyezi Mungu ni Mwenye wasaa, Mwenye kujua mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 116, 'Na ati wanasema: ''Mwenyezi Mungu ana mwana.'' Subhanahu (ametakasika mbali na hayo!) Bali vyote vilivyomo mbinguni na duniani ni vyake. Vyote vinamdhalilikia Yeye kwa hofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 117, 'Yeye ndiye Muumba wa mbingu na ardhi pasina mfano wa awali; na anapotaka jambo, basi Yeye kwa hakika huliambia tu: ''Kuwa!'' Nalo huwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 118, 'Na walisema wale wasiojua kitu: ʻMbona Mwenyezi Mungu hasemi nasi au zikatufikia Ishara.ʼ Kama hivyo walisema wale waliokuwa kabla yao mfano wa kauli yao hii. Nyoyo zao zimefanana. Hakika Sisi tumeziweka wazi Ishara kwa watu wenye yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 119, 'Hakika Sisi tumekutuma kwa haki uwe mbashiri, na mwonyaji. Na wala hutaulizwa juu ya watu wa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 120, 'Na Mayahudi hawawi radhi nawe, wala Wakristo, mpaka ufuate mila yao. Sema: Hakika uongofu wa Mwenyezi Mungu ndio uongofu. Na kama ukifuata matamanio yao baada ya yaliyokujia katika elimu, hutapata mlinzi wala msaidizi kando na Mwenyezi Mungu.[1]', '[1] Mayahudi na Manaswara hawawaridhii Waislamu kwa chochote isipokuwa kwamba wawafuate katika dini yao. Lakini hayo waliyo nayo ni matamanio tu, siyo dini ya haki.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 121, 'Wale tuliowapa Kitabu, wanakisoma kama ipasavyo kukisoma. Hao ndio kweli wanakiamini. Na wanaokikataa, basi hao ndio wenye kuhasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 122, 'Enyi Wana wa Israili! Kumbukeni neema yangu niliyokuneemesheni, na hakika Mimi nilikuboresheni kuliko wengineo wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 123, 'Na icheni siku ambayo hatamfaa mtu mwenziwe kwa lolote, wala hakitakubaliwa kwake kikomboleo, wala maombezi hayatamfaa, wala hawatanusuriwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 124, 'Na Mola wake Mlezi alipomjaribu Ibrahim kwa kumpa amri fulani, naye akazitimiza. Akamwambia: Hakika Mimi nitakufanya uwe mwongozi wa watu. Akasema: Je, na katika kizazi changu pia? Akasema: Agano langu halitawafikia wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 125, 'Na kumbukeni tulipoifanya ile Nyumba (ya Alkaaba) iwe pahali pa kukusanyikia watu na pahali pa amani. Na alipokuwa akisimama Ibrahim pafanyeni pawe pa kusalia. Na tuliagana na Ibrahim na Ismail: Itakaseni Nyumba yangu kwa ajili ya wanaoizunguka kwa kutufu na wanaojitenga huko kwa ibada, na wanaoinama na kusujudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 126, 'Na aliposema Ibrahim: Ewe Mola wangu Mlezi! Ufanye huu uwe mji wa amani, na uwaruzuku watu wake matunda, wale wanaomuamini Mwenyezi Mungu na Siku ya Mwisho. Akasema: Na mwenye kukufuru pia nitamstarehesha kidogo, kisha nitamsukumiza kwenye adhabu ya Moto, napo ni pahali pabaya mno pa kurejea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 127, 'Na kumbukeni Ibrahim na Ismail walipokuwa wanainyanyua misingi ya ile Nyumba wakaomba: Ewe Mola Mlezi wetu! Tukubalie! Hakika Wewe ndiye Mwenye kusikia mno, Mwenye kujua zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 128, 'Ewe Mola Mlezi wetu! Tujaalie tuwe ni wenye kusilimu kwako, na pia miongoni mwa vizazi vyetu wawe umma uliosilimu kwako. Na utuonyeshe njia za ibada yetu na utusamehe. Bila shaka Wewe ndiye Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 129, 'Ewe Mola Mlezi wetu! Waletee Mtume anayetokana na wao, awasomee Aya zako, na awafundishe Kitabu na hekima na awatakase. Hakika Wewe ndiye Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 130, 'Na nani atajitenga na mila ya Ibrahim isipokuwa anayeitia nafsi yake katika upumbavu? Na kwa yakini, Sisi tulimteua yeye katika dunia. Na hakika yeye katika Akhera atakuwa miongoni mwa watu wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 131, 'Na Mola wake Mlezi alipomwambia: Silimu! Akasema: Nimesilimu kwa Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 132, 'Na Ibrahim akawausia wanawe hilo, na pia Yaaqub: Enyi wanangu! Hakika Mwenyezi Mungu amekuteulieni Dini hii. Basi kamwe msife ila nanyi ni Waislamu.[1]', '[1] Yani aliichagua na akawateulia kama rehema na wema. Basi inapasa kusimama nayo na kusifika kwa sheria zake, na kujipaka maadili yake na kudumu namna hiyo hadi kifo. Kwa sababu, mwenye kuishi juu ya kitu, atakufa juu yake. Na mwenye kufa juu ya kitu, atafufuliwa juu yake.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 133, 'Je, mlikuwapo yalipomfikia Yaaqub mauti, akawaambia wanawe: Mtamuabudu nani baada yangu? Wakasema: Tutamuabudu Mungu wako na Mungu wa baba zako, Ibrahim na Ismail na Is-hak, Mungu Mmoja tu. Na sisi tunasilimu kwake.[1]', '[1] Hii ni hoja dhidi ya Mayahudi (na mfano wao) wanaodai kuwa wanaifuata mila (dini) ya Ibrahim na (Manabii wa) baada yake (kama vile) Yaaqub. Mwenyezi Mungu Mtukufu akawauliza ikiwa waliushuhudia wasia wa mwisho wa Yaqub kwa wana wake. "Je, mtamuabudu nani baada yangu?" Wakasema kuwa watamuabudu Mungu wake, Mungu wa baba zake, ambaye ni Mungu Mmoja tu, na kwamba wao ni wenye kujisilimisha kwake (yaani ni Waislamu)."');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 134, 'Hao ni watu waliokwishapita. Watapata waliyoyachuma, nanyi mtapata mtakayoyachuma; wala hamtaulizwa nyinyi waliyokuwa wakiyafanya wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 135, 'Na wakasema: Kuweni Mayahudi au Wakristo ndio mtaongoka. Sema: Bali tunashika mila ya Ibrahim mwongofu, wala hakuwa katika washirikina.[1]', '[1] Mayahudi na Wakristo huwaita Waislamu kuingia katika Dini zao wakidai kuwa huo ndio uongofu. Lakini Mwenyezi Mungu akakanusha hilo, na kwamba mila (dini) ya Ibrahim ndiyo uongofu. Na katika kuipa mgongo mila yake ni ukafiri na kupotea.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 136, 'Semeni nyinyi: Tumemuamini Mwenyezi Mungu na yale tuliyoteremshiwa sisi, na yaliyoteremshwa kwa Ibrahim na Ismail na Is-hak na Yaakub na watoto wake, na waliyopewa Musa na Isa, na pia waliyopewa Manabii wengine kutoka kwa Mola wao Mlezi; hatutofautishi baina ya yeyote katika hao, na sisi kwake tumesilimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 137, 'Basi wakiamini kama mnavyoamini nyinyi, itakuwa kweli wameongoka. Na wakikengeuka, basi wao wamo katika upinzani tu. Na Mwenyezi Mungu atakutosheni kukukingeni kutokana na shari yao, na Yeye ndiye Mwenye kusikia mno, ajuaye zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 138, 'Huko ndiko kupaka rangi kwa Mwenyezi Mungu. Na nani aliye mbora wa kupaka rangi kuliko Mwenyezi Mungu? Na sisi ni wenye kumuabudu Yeye tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 139, 'Sema: Mnahojiana nasi juu ya Mwenyezi Mungu, naye ni Mola wetu Mlezi na Mola wenu Mlezi, na sisi tuna vitendo vyetu na nyinyi mna vitendo vyenu? Nasi tunamsafia Yeye tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 140, 'Au mnasema kuwa Ibrahim na Ismail na Is-hak na Yaakub na watoto wake walikuwa Mayahudi au Wakristo? Sema: Je, nyinyi mnajua zaidi au Mwenyezi Mungu? Na ni nani mwenye kudhulumu zaidi kuliko yule aliyeficha ushahidi alio nao utokao kwa Mwenyezi Mungu? Na Mwenyezi Mungu si mwenye kughafilika mbali na hayo myafanyayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 141, 'Hao ni watu waliokwishapita. Wao watapata waliyoyachuma, na nyinyi mtapata mliyoyachuma, wala hamtaulizwa nyinyi yale waliyokuwa wakiyafanya wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 142, 'Wapumbavu miongoni mwa watu watasema: ‘Ni nini kilichowageuza kutoka kibla chao walichokuwa wakikielekea?’ Sema: ‘Mashariki na Magharibi ni ya Mwenyezi Mungu; Yeye humwongoa amtakaye kwenye njia iliyonyooka.’', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 143, 'Na vivyo hivyo tumewafanya muwe Umma wa wastani, ili muwe mashahidi juu ya watu, na Mtume awe shahidi juu yenu. Na hatukukifanya kibla ulichokuwa juu yake isipokuwa ili tupate kumjua yule anayemfuata Mtume, na yule anayegeuka akarejea kwa visigino vyake. Na kwa yakini, hilo lilikuwa jambo kubwa isipokuwa kwa wale aliowaongoa Mwenyezi Mungu. Na Mwenyezi Mungu hakuwa mwenye kuipoteza Imani yenu. Kwa hakika, Mwenyezi Mungu kwa watu ni Mpole, Mwenye kuwarehemu mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 144, 'Kwa yakini, tuliona unavyougeuzageuza uso wako mbinguni. Basi, tutakuelekeza kwenye Kibla unachokiridhia. Basi, elekeza uso wako upande wa Msikiti Mtakatifu. Na popote mnapokuwa, zielekezeni nyuso zenu upande wake. Na hakika, wale waliopewa Kitabu wanajua sana kwamba hiyo ndiyo haki itokayo kwa Mola wao Mlezi. Na Mwenyezi Mungu si mwenye kughafilika mbali na yale wanayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 145, 'Na hata ukiwaletea hao waliopewa Kitabu hoja za kila namna, hawatafuata Kibla chako. Wala wewe hutafuata kibla chao. Wala baadhi yao hawatafuata kibla cha wengineo. Na kama ukiyafuata matamanio yao baada ya kile kilichokufikia katika elimu, wewe kwa hakika hapo utakuwa miongoni mwa wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 146, 'Wale tuliowapa Kitabu, wanayajua haya kama wanavyowajua watoto wao. Na kuna kikundi katika wao huificha haki na hali wanajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 147, 'Haki inatoka kwa Mola wako Mlezi. Basi usiwe kabisa miongoni mwa wenye shaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 148, 'Na kila mmoja anao mwelekeo anaoelekea. Basi shindanieni mema. Popote mlipo, Mwenyezi Mungu atawaleta nyote pamoja. Hakika, Mwenyezi Mungu ni Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 149, 'Na kokote uendako, uelekeze uso wako kwenye Msikiti Mtakatifu. Na hiyo kwa hakika ndiyo haki itokayo kwa Mola wako Mlezi. Na Mwenyezi Mungu si mwenye kughafilika mbali na mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 150, 'Na kokote uendako, uelekeze uso wako kwenye Msikiti Mtakatifu. Na popote mlipo, zielekezeni nyuso zenu upande wake, ili watu wasiwe na hoja juu yenu; isipokuwa wale waliodhulumu miongoni mwao. Basi, msiwaogope wao, lakini niogopeni Mimi. Na ili niwatimizie neema yangu, na ili mpate kuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 151, 'Kama tulivyomtuma Mtume kwenu anayetokana na nyinyi, anawasomea Aya zetu na kuwatakasa na kuwafundisha Kitabu na hekima, na anawafundisha ambayo hamkuwa mnayajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 152, 'Basi nitajeni, nitakutajeni. Na nishukuruni, wala msinikufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 153, 'Enyi mlioamini! Takeni msaada kwa subira na Swala. Hakika, Mwenyezi Mungu yu pamoja na wanaosubiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 154, 'Wala msiseme kuwa wale waliouwawa katika Njia ya Mwenyezi Mungu ni maiti. Bali hao ni hai. Lakini nyinyi hamtambui.[1]', '[1] Inajulikana kuwa kipenzi hakiachwi na wenye akili timamu, isipokuwa kwa ajili ya kipenzi kilicho juu zaidi na kikubwa kukiliko. Kwa hivyo, Mwenyezi Mungu Mtukufu akajulisha kwamba mwenye kuuawa katika njia yake akipigana katika njia ya Mwenyezi Mungu, ili neno la Mwenyezi Mungu liwe ndilo la juu zaidi; na dini yake iwe iliyo dhahiri zaidi. Basi yeye kwa hakika hajakosa uhai alioupenda, bali (alipouawa) alipata uhai mkubwa na kamili zaidi kuliko mnavyofikiria nyinyi.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 155, 'Hapana shaka, tutakujaribuni kwa chembe ya hofu, na njaa, na upungufu wa mali na watu na mazao. Na wabashirie wanaosubiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 156, 'Wale ambao ukiwapata msiba, husema: Hakika sisi ni wa Mwenyezi Mungu, na kwake Yeye hakika tutarejea.[1]', '[1] Wao husema hivyo kwa sababu wanajua kwamba wanamilikiwa na Mwenyezi Mungu, wako chini ya amri yake na uendeshaji wake. Kwa hivyo, hatuna chochote katika nafsi zetu wala mali zetu. Na akitujaribu kwa kitu katika hayo, basi Yeye Mwingi wa rehema atakuwa amewaendesha wamilikiwa wake na mali zake. Kwa hivyo haifai kuwa na pingamizi lolote dhidi yake.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 157, 'Hao juu yao zitakuwa baraka zitokazo kwa Mola wao Mlezi na rehema. Na hao ndio walioongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 158, 'Hakika, vilima vya Safaa na Marwa ni katika alama za Mwenyezi Mungu. Basi, anayehiji kwenye Nyumba hiyo au akafanya Umra, si kosa kwake kuzunguka kati yake. Na anayejitolea kutenda heri, basi bila ya shaka Mwenyezi Mungu ni Mwenye shukrani na Mwenye kujua hilo mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 159, 'Hakika, wale wanaoficha yale tuliyoyateremsha, nazo ni hoja zilizo wazi na uongofu baada ya Sisi kuzibainisha kwa watu Kitabuni, hao anawalaani Mwenyezi Mungu, na wanawalaani kila wenye kulaani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 160, 'Isipokuwa wale waliotubu, wakatengeneza na wakabainisha. Basi hao nitapokea toba yao, na Mimi ni Mwingi wa kupokea toba, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 161, 'Hakika, waliokufuru na wakafa hali ni makafiri, hao iko juu yao laana ya Mwenyezi Mungu na ya Malaika na ya watu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 162, 'Watadumu humo. Hawatapunguziwa adhabu wala hawatapewa muda wa kupumzika.[1]', '[1] Hawatapumzishwa, yaani kupewa muhula, kwa sababu wakati wa muhula ambao ulikuwa duniani ulikwishapita.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 163, 'Na Mungu wenu ni Mungu mmoja tu, hapana mungu ila Yeye. Mwingi wa rehema, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 164, 'Hakika, katika kuumbwa kwa mbingu na ardhi, na kukhitalifiana usiku na mchana. Na marikebu ambazo hupita baharini kwa viwafaavyo watu, na maji anayoyateremsha Mwenyezi Mungu kutoka mbinguni, na kwa hayo, akaihuisha ardhi baada ya kufa kwake, na akaeneza humo kila aina ya wanyama; na katika mabadiliko ya pepo na mawingu yanayoamrishwa kupita baina ya mbingu na ardhi, bila shaka zimo Ishara kwa watu watumiao akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 165, 'Na katika watu wapo wanaojifanyia waungu wasio kuwa Mwenyezi Mungu. Wanawapenda kama kumpenda Mwenyezi Mungu. Lakini walioamini wanampenda Mwenyezi Mungu zaidi sana. Na laiti waliodhulumu wakajua watakapoiona adhabu kuwa nguvu zote ni za Mwenyezi Mungu, na kuwa Mwenyezi Mungu ni mkali wa kuadhibu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 166, 'Waliofuatwa watakapowakataa wale waliowafuata, na hali ya kuwa wamekwishaiona adhabu; na yatakatika kabisa mafungamano yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 167, 'Na watasema wale waliofuata: ''Laiti tungeweza kurudi tukawakataa wao kama wanavyotukataa sisi!'' Hivi ndivyo Mwenyezi Mungu atakavyowaonyesha vitendo vyao kuwa majuto yao; wala hawatakuwa wenye kutoka Motoni.[1]', '[1] Basi matendo yao (ya kumwabudu asiyekuwa Mwenyezi Mungu Mmoja) yakapotelea mbali. Na hali zao zikaangamia, na ikawadhihirikia kuwa wao walikuwa ni waongo. Na kwamba matendo yao waliyoyatarajia yawanufaishe na wapate matokeo yake yaliwabadilikia yakawa masikitiko na majuto.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 168, 'Enyi watu! Kuleni vilivyo katika ardhi, halali na vizuri, wala msifuate nyayo za Shetani. Hakika yeye ni adui yenu aliye dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 169, 'Yeye anakuamrisheni maovu na machafu, na mumsingizie Mwenyezi Mungu mambo msiyoyajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 170, 'Na wanapoambiwa: ''Fuateni aliyoyateremsha Mwenyezi Mungu;'' wao husema: ''Bali tutafuata tuliyowakuta nayo baba zetu.'' Je, hata ikiwa baba zao walikuwa hawaelewi kitu, wala hawakuongoka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 171, 'Na mfano wa waliokufuru ni kama mfano wa anayempigia kelele asiyesikia isipokuwa wito na sauti tu. Ni viziwi, mabubu, vipofu, kwa hivyo hawaelewi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 172, 'Enyi mlioamini! Kuleni katika vizuri tulivyokuruzukuni, na mumshukuru Mwenyezi Mungu, ikiwa kweli mnamuabudu Yeye tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 173, 'Hakika Yeye amekuharamishieni mzoga tu na damu na nyama ya nguruwe na kilichotajiwa, katika kuchinjwa kwake, jina la asiyekuwa Mwenyezi Mungu. Lakini aliyefikiwa na dharura bila ya kutamani wala kupita kiasi, yeye hana dhambi. Hakika Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 174, 'Hakika, wale wanaoficha aliyoyateremsha Mwenyezi Mungu katika Kitabu, na wakanunua kwacho thamani ndogo, hao hawali katika tumbo zao isipokuwa moto. Wala Mwenyezi Mungu hatawaongelesha Siku ya Kiyama, wala hatawatakasa, nao wana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 175, 'Hao ndio walionunua upotovu kwa uongofu, na adhabu kwa msamaha. Basi ni wavumilivu wa namna gani hawa kwa Moto!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 176, 'Hayo ni kwa sababu Mwenyezi Mungu ameteremsha Kitabu kwa haki. Na hakika wale waliohitilafiana katika Kitabu wamo katika upinzani ulio mbali na haki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 177, 'Siyo wema kuwa mnaelekeza nyuso zenu upande wa mashariki na magharibi. Bali wema ni wa anayemuamini Mwenyezi Mungu na Siku ya Mwisho na Malaika na Kitabu na Manabii. Na anawapa mali - licha ya kuipenda - jamaa na mayatima na masikini na wasafiri, na waombao, na katika ukombozi. Na akawa anashika Swala, na akatoa Zaka, na wanaotimiza agano lao wanapoahidi, na wanaovumilia katika shida na dhara na wakati wa vita. Hao ndio walio sadikisha, na hao ndio wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 178, 'Enyi mlioamini! Mmepewa ruhusa kulipa kisasi katika waliouawa - muungwana kwa muungwana, na mtumwa kwa mtumwa, na mwanamke kwa mwanamke. Na anayesamehewa na ndugu yake chochote, basi ashikwe kulipa kwa wema, na yeye alipe kwa ihsani. Huko ni kupunguziwa kulikotokana na Mola wenu Mlezi, na ni rehema. Na atakayevuka mipaka baada ya haya, basi yeye atapata adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 179, 'Mtakuwa na uhai mzuri katika kulipiza kisasi enyi wenye akili, ili mpate kuwa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 180, 'Mmeandikiwa mmoja wenu anapofikwa na mauti, kama ataacha heri (yaani mali), afanye wasia kwa wazazi wake wawili, na jamaa zake kwa wema. Ni haki juu ya wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 181, 'Na atakayeibadilisha (wasia) baada ya kuisikia, basi dhambi yake ni juu ya wale watakaoibadilisha; hakika Mwenyezi Mungu ni Mwenye kusikia, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 182, 'Na mwenye kumhofia muusiaji kwenda kombo au kupata dhambi, na akasuluhisha baina yao, basi hakuna dhambi yoyote juu yake. Hakika, Mwenyezi Mungu ni Msamehevu, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 183, 'Enyi mlioamini! Mmeandikiwa Saumu, kama walivyoandikiwa (watu) waliokuwa kabla yenu ili mpate kumcha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 184, '(Mfunge) siku zenye kuhesabika. Na atakayekuwa miongoni mwenu mgonjwa au yumo safarini, basi atimize hesabu katika siku nyingine. Na wale wasioweza, watoe fidia kwa kumlisha masikini. Na atakayefanya wema kwa kujitolea, basi ni bora kwake. Na mkifunga saumu, ndiyo bora kwenu, ikiwa mnajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 185, 'Mwezi wa Ramadhani ndio ambao imeteremshwa Qur-ani ndani yake kuwa uongofu kwa watu, na hoja zilizo wazi za uongofu na upambanuzi. Kwa hivyo, atakayeushuhudia mwezi miongoni mwenu, basi na afunge. Na atakayekuwa mgonjwa au safarini, basi atimize hesabu katika siku nyinginezo. Mwenyezi Mungu anawatakia yaliyo mepesi, wala hawatakii yaliyo mazito, na ili mkamilishe hesabu hiyo, na ili mumtukuze Mwenyezi Mungu kwa yale aliyowaongoa ili mpate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 186, 'Na waja wangu watakapokuuliza kunihusu Mimi, basi Mimi kwa hakika nipo karibu. Ninaitikia maombi ya mwombaji anaponiomba. Basi na waniitikie Mimi, na waniamini Mimi, ili wapate kuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 187, 'Mmehalalishiwa usiku wa Saumu kuingiliana na wake zenu. Wao ni vazi kwenu, na nyinyi ni vazi kwao. Mwenyezi Mungu alikwishajua kwamba mlikuwa mkizihini nafsi zenu. Kwa hivyo amewakubalia toba yenu na amewasamehe. Basi sasa changanyikeni nao na tafuteni kile alichowaandikia Mwenyezi Mungu. Na kuleni na kunyweni mpaka uwabainikie weupe wa alfajiri kutokana na weusi wa usiku. Kisha timizeni Saumu mpaka usiku. Wala msichanganyike nao hali ya kuwa mmekaa Itikafu msikitini. Hiyo ni mipaka ya Mwenyezi Mungu, basi msiikaribie. Hivyo ndivyo Mwenyezi Mungu anavyowabainishia Aya (Ishara) zake watu ili wapate kumcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 188, 'Wala msiliane mali zenu kwa batili, na kuzipeleka kwa mahakimu ili mpate kula sehemu ya mali ya watu kwa dhambi, na hali mnajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 189, 'Wanakuuliza kuhusu miezi miandamo. Sema: Hiyo ni vipimo vya nyakati kwa ajili ya watu na Hija. Wala sio wema kwamba mziingie nyumba kwa nyuma yake. Bali mwema ni mwenye kumcha Mungu. Na ingieni majumbani kupitia milangoni mwake. Na mcheni Mwenyezi Mungu ili mpate kufaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 190, 'Na piganeni katika Njia ya Mwenyezi Mungu na wale wanaopigana nanyi, wala msianzishe uadui. Kwani Mwenyezi Mungu kwa hakika hawapendi waanzao uadui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 191, 'Na waueni popote muwakutapo, na watoeni popote walipowatoa; kwani fitina ni mbaya zaidi kuliko kuua. Wala msipigane nao kwenye Msikiti Mtakatifu mpaka wawapigie huko. Wakikupigeni huko, basi nanyi pia wapigeni. Na hivi ndivyo yalivyo malipo ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 192, 'Lakini wakiacha, basi Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 193, 'Na piganeni nao mpaka pasiwepo fitina, na Dini iwe ya Mwenyezi Mungu tu. Na kama wakiacha, basi usiwepo uadui isipokuwa kwa madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 194, 'Mwezi mtakatifu kwa mwezi mtakatifu. Na vitu vitakatifu vimeekewa kisasi. Basi, anayewashambulia, nanyi mshambulieni kwa sawa na alivyowashambulia. Na mcheni Mwenyezi Mungu. Na jueni kwamba Mwenyezi Mungu kwa hakika yu pamoja na wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 195, 'Na toeni katika njia ya Mwenyezi Mungu, wala msijitupe katika maangamivu kwa mikono yenu. Na fanyeni wema. Hakika, Mwenyezi Mungu huwapenda wanaofanya wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 196, 'Na timizeni Hija na Umra kwa ajili ya Mwenyezi Mungu. Na ikiwa mtazuiwa, basi (chinjeni) wanyama walio wepesi kupatikana. Wala msinyoe vichwa vyenu mpaka wanyama hao wafike mahali pao pa kuchinjiwa. Na atakayekuwa mgonjwa miongoni mwenu au ana vya kumuudhi kichwani kwake, basi atoe fidia kwa kufunga saumu au kwa kutoa sadaka au kuchinja wanyama. Na mtakapokuwa na amani, basi mwenye kujistarehesha kwa kufanya Umra kisha akahiji, basi achinje mnyama aliye mwepesi kumpata. Na asiyepata, afunge siku tatu katika Hija na siku saba mtakaporudi. Hizo ni kumi kamili. Hayo ni kwa yule ambaye jamaa zake hawako karibu na Msikiti Mtakatifu. Na mcheni Mwenyezi Mungu, na jueni kwamba Mwenyezi Mungu ni Mkali wa kuadhibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 197, 'Hija ni miezi maalumu. Basi anayehirimia Hija ndani yake (miezi hiyo), basi asijamiiane wala asipindukie mipaka wala asibishane katika Hija. Na chochote mnachokifanya katika heri, Mwenyezi Mungu anaijua. Na chukueni masurufu. Na hakika, masurufu (yaliyo) bora zaidi ni ucha Mungu. Na nicheni Mimi, enyi wenye akili ya hali ya juu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 198, 'Hakuna ubaya wowote juu yenu kutafuta fadhila kutoka kwa Mola wenu Mlezi. Basi mtakapomiminika kutoka ''Arafat, mtajeni Mwenyezi Mungu katika Mash''aril Haram (eneo takatifu). Na mtajeni kama alivyowaongoa, ijapokuwa kabla ya hilo mlikuwa miongoni mwa waliopotea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 199, 'Kisha miminikeni kutoka pale wanapomiminika watu, na muombeni Mwenyezi Mungu msamaha. Hakika, Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 200, 'Na mkishatimiza ibada zenu za Hija, mtajeni Mwenyezi Mungu kama mlivyokuwa mkiwataja baba zenu au utajo mkubwa zaidi. Na katika watu kuna wale wanaosema, “Mola wetu Mlezi, tupe duniani!” Naye katika Akhera hana fungu lolote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 201, 'Na miongoni mwao kuna wale wanaosema, “Mola wetu Mlezi, tupe duniani mema, na Akhera mema, na utulinde kutokana na adhabu ya Moto!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 202, 'Hao ndio walio na fungu kwa sababu ya yale waliyoyachuma. Na Mwenyezi Mungu ni Mwepesi wa kuhisabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 203, 'Na mtajeni Mwenyezi Mungu katika zile siku zinazohisabiwa. Lakini mwenye kufanya haraka (akarejea) katika siku mbili, basi hakuna dhambi juu yake. Na mwenye kukawia, pia hakuna dhambi juu yake, kwa mwenye kumcha Mungu. Na mcheni Mwenyezi Mungu, na jueni kwamba nyinyi mtakusanywa kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 204, 'Na katika watu yupo yule ambaye maneno yake kwa maisha ya kidunia hukupendeza; naye humshuhudisha Mwenyezi Mungu kwa yaliyo katika moyo wake, na hali yeye ndiye mgomvi mkubwa mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 205, 'Na akishageuka akaenda, anazunguka katika ardhi ili afanye humo uharibifu na kuangamiza mimea na viumbe. Na Mwenyezi Mungu hapendi uharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 206, 'Na akiambiwa, “Mche Mwenyezi Mungu,” hupandwa na mori wa kutenda madhambi. Basi huyo kinachomtosha ni Jahannam. Napo hakika ni pahali pabaya mno pa kupumzikia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 207, 'Na katika watu, kuna yule anayeiuza nafsi yake kwa kutaka radhi za Mwenyezi Mungu. Na Mwenyezi Mungu ni Mpole kwa waja wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 208, 'Enyi mlioamini! Ingieni katika Uislamu kwa ukamilifu, wala msifuate nyayo za Shetani. Hakika, yeye kwenu ni adui wa wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 209, 'Na mkiteleza baada ya kufikiwa na hoja zilizo wazi, basi jueni kuwa Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 210, 'Je, wanangoja mpaka Mwenyezi Mungu awajie katika vivuli vya mawingu pamoja na Malaika, na hukumu iwe imekwishatolewa? Na kwa Mwenyezi Mungu ndiyo hurejeshwa mambo yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 211, 'Waulize Wana wa Israili: ''Tumewapa ishara ngapi zilizo wazi?'' Na anayezibadili neema za Mwenyezi Mungu baada ya kumfikia, basi hakika Mwenyezi Mungu ni mkali wa kuadhibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 212, 'Waliokufuru wamepambiwa maisha ya duniani; na wanawafanyia masihara wale walioamini. Na wale wanaomcha Mwenyezi Mungu watakuwa juu yao Siku ya Kiyama. Na Mwenyezi Mungu humruzuku amtakaye bila ya hisabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 213, 'Watu wote walikuwa umma mmoja. Kisha Mwenyezi Mungu akawatuma Manabii wenye kupeana habari njema na waonyaji. Na akateremsha pamoja nao Kitabu kwa haki, ili kihukumu baina ya watu katika yale waliyohitilafiana. Na wala hawakuhitilafiana ndani yake isipokuwa wale waliopewa Kitabu hicho baada ya kufikiwa na hoja zilizo wazi, kwa sababu ya husuda ya baina yao. Ndipo Mwenyezi Mungu kwa idhini yake akawaongoa walioamini kuiendea haki katika yale waliyohitilafiana ndani yake. Na Mwenyezi Mungu humwongoa amtakaye kwenye Njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 214, 'Ama mnadhani kuwa mtaingia Bustanini, ilhali bado hamjajiwa na mfano wa (yaliyowajia) wale waliopita kabla yenu? Uliwapata ufukara (shida) na maradhi, na wakatikiswa mpaka Mtume na walioamini pamoja naye wakasema: “Ni lini nusura ya Mwenyezi Mungu (itakuja)?” Jueni kuwa hakika nusura ya Mwenyezi Mungu ipo karibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 215, 'Wanakuuliza watoe nini? Sema: Chochote mnachotoa katika heri ni kwa ajili ya wazazi na jamaa na mayatima na masikini na msafiri. Na chochote mnachofanya katika heri, basi Mwenyezi Mungu kwa hakika anaijua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 216, 'Mmeandikiwa kupigana vita, navyo vinawachukiza. Lakini huenda mkachukia kitu, nacho ni heri kwenu. Na huenda mkapenda kitu, nacho ni shari kwenu. Na Mwenyezi Mungu anajua, na nyinyi hamjui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 217, 'Wanakuuliza juu ya kupigana vita katika mwezi mtakatifu. Sema: Kupigana vita ndani yake ni dhambi kubwa. Lakini kuzuia watu wasiende katika Njia ya Mwenyezi Mungu na kumkufuru Yeye, na kuzuilia watu wasiende kwenye Msikiti Mtakatifu na kuwatoa watu wake humo, ni makubwa zaidi mbele ya Mwenyezi Mungu. Na fitina ni jambo kubwa zaidi kuliko kuua. Wala hawataacha kupigana nanyi mpaka wawatoe katika Dini yenu kama wakiweza. Na yeyote katika nyinyi atakayeacha Dini yake, na akafa hali ya kuwa ni kafiri, basi hao ndio ambao matendo yao yameharibika katika dunia na Akhera. Na hao ndio watu wa Motoni. Wao humo watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 218, 'Hakika, wale walioamini, na wale waliohama na wakafanya juhudi katika Njia ya Mwenyezi Mungu, hao ndio wanaotarajia rehema za Mwenyezi Mungu. Na Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 219, 'Wanakuuliza juu ya mvinyo na kamari. Sema: Katika hivyo zipo dhambi kubwa na manufaa kwa watu. Lakini dhambi zake ni kubwa zaidi kuliko manufaa yake. Na wanakuuliza watoe nini? Sema: Kilichozidi mahitaji. Hivi ndivyo Mwenyezi Mungu anawabainishia Aya zake ili mpate kutafakari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 220, 'Katika dunia na Akhera, na wanakuuliza juu ya mayatima. Sema: Kuwatengenezea ndio heri. Na mkichanganyika nao, basi ni ndugu zenu. Na Mwenyezi Mungu anamjua mharibifu na mtengenezaji. Na Mwenyezi Mungu angelipenda, angelikutieni katika ugumu. Hakika, Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 221, 'Wala msiwaoe wanawake washirikina mpaka waamini. Na mjakazi Muumini ni bora kuliko mwanamke mshirikina hata akiwapendeza. Wala msiwaoze (binti zenu) wanaume washirikina mpaka waamini. Na mtumwa mwanamume Muumini ni bora kuliko mwanamume mshirikina hata akiwapendeza. Hao wanaitia kwenye Moto, naye Mwenyezi Mungu anaitia kwenye Bustani na maghfira kwa idhini yake. Naye huwabainishia Aya zake watu ili wapate kukumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 222, 'Na wanakuuliza juu ya hedhi. Waambie: hayo ni madhara. Basi jitengeni mbali na wanawake wakati wa hedhi, wala msiwakaribie mpaka wawe safi. Na wakishajisafisha, basi waendeeni namna alivyokuamrisheni Mwenyezi Mungu. Hakika, Mwenyezi Mungu huwapenda wanaotubu, na huwapenda wanaojisafisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 223, 'Wake zenu ni konde zenu. Basi ziendeeni konde zenu mpendavyo. Lakini zitangulizieni heri nafsi zenu, na mcheni Mwenyezi Mungu, na jueni kuwa hakika nyinyi mtakutana naye. Na wape habari njema Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 224, 'Wala msifanye Mwenyezi Mungu katika viapo vyenu kuwa kisingizio cha kuacha kufanya wema, na kumcha Mungu, na kupatanisha baina ya watu. Na Mwenyezi Mungu ni Mwenye kusikia, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 225, 'Mwenyezi Mungu hawachukulii ubaya katika viapo vyenu ambavyo hamkuvikusudia. Lakini anawachukulia ubaya kwa yale ambayo nyoyo zenu zinachuma. Na Mwenyezi Mungu ni Mwenye kusamehe, Mpole.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 226, 'Kwa wale wanaoapa kujitenga na wake zao, wangojee miezi minne. Na wakirejea, basi Mwenyezi Mungu hakika ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 227, 'Na wakiazimia kuwapa talaka, basi Mwenyezi Mungu ni Mwenye kusikia, Mweye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 228, 'Na wanawake waliopewa talaka, wazizuie nafsi zao tahara (au hedhi) tatu. Wala sio halali kwao kuficha alichoumba Mwenyezi Mungu katika matumbo yao ya uzazi, ikiwa wanamuamini Mwenyezi Mungu na Siku ya Mwisho. Na waume wao wana haki zaidi ya kuwarejesha katika muda huo, ikiwa wanataka kufanya suluhu. Nao wanawake wanayo haki sawa na ile haki iliyo juu yao. Na wanaume wana daraja zaidi juu yao. Na Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 229, 'Talaka ni mara mbili. Kisha ni kukaa kwa wema au kuachana kwa uzuri. Wala si halali kwenu kuchukua chochote katika kile mlichowapa wake zenu, isipokuwa ikiwa wote wawili watahofia ya kwamba hawataweza kushikamana na mipaka ya Mwenyezi Mungu. Basi mkihofia kuwa hawataweza kushikamana na mipaka ya Mwenyezi Mungu, hapo hakuna ubaya juu yao katika kile ambacho mke atajikomboa kwacho. Hii ndiyo mipaka ya Mwenyezi Mungu. Basi msiikiuke. Na mwenye kukiuka mipaka ya Mwenyezi Mungu, basi hao ndio madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 230, 'Na akimtaliki (talaka ya tatu), basi yeye si halali kwake baada ya hayo mpaka aolewe na mume asiyekuwa yeye. Na (huyo mwingine) akimtaliki, basi hakuna ubaya kwao (mke na mume wa kwanza) kurejeana wakiona kuwa watashikamana na mipaka ya Mwenyezi Mungu. Na hii ni mipaka ya Mwenyezi Mungu anayoibainisha kwa watu wanaojua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 231, 'Na mtakapowataliki wanawake talaka, nao wakafikia kumaliza eda yao, basi warejeeni kwa wema au waachilieni kwa wema. Wala msiwarejee kwa kuwadhuru mkafanya uadui. Na atakayefanya hivyo, ameidhulumu nafsi yake. Wala msizichukulie Aya za Mwenyezi Mungu kwa masikhara. Na kumbukeni neema ya Mwenyezi Mungu juu yenu, na aliyowateremshia katika Kitabu na hekima anachowaonya kwacho. Na mcheni Mwenyezi Mungu, na jueni kwamba hakika Mwenyezi Mungu ni Mwenye kujua mno kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 232, 'Na mtakapowataliki wanawake, nao wakamaliza muda wao (wa eda), basi msiwazuie kuoleka kwa waume zao endapo baina yao wamekubaliana kwa wema. Hayo anawaidhiwa kwayo yule miongoni mwenu anayemwamini Mwenyezi Mungu na Siku ya Mwisho. Hayo ni bora zaidi kwenu na safi kabisa. Na Mwenyezi Mungu anajua, lakini nyinyi hamjui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 233, 'Na wazazi wanawake wawanyonyeshe watoto wao miaka miwili kamili kwa anayetaka kutimiza kunyonyesha. Na ni juu ya aliyezaliwa mwana huyo chakula chao na mavazi yao kwa wema. Wala halazimishwi mtu isipokuwa kwa kiwango cha uwezo wake. Mama asitaabishwe kwa sababu ya mwanawe, wala yule aliyezaliwa mwana kwa sababu ya mwanawe. Na juu ya mrithi ni mfano wa hivyo. Na kama wote wawili watataka kumwachisha kunyonya kwa kuridhiana na kushauriana, basi hakuna ubaya juu yao. Na mkitaka kuwapa watoto wenu mama wa kuwanyonyesha, basi hakuna ubaya juu yenu ikiwa mtapeana mlichoahidi kwa wema. Na mcheni Mwenyezi Mungu. Na jueni kwamba Mwenyezi Mungu anayaona vyema mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 234, 'Na wale miongoni mwenu wanaofishwa, na wanaacha wake, hawa wake wazizuie nafsi zao miezi minne na siku kumi. Na wanapotimiza muda wao (wa eda), basi hakuna ubaya wowote juu yao katika yale wanayojifanyia kwa wema. Na Mwenyezi Mungu anazo habari za yote mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 235, 'Wala hakuna ubaya juu yenu katika kupeleka posa kwa ishara tu kwa wanawake walio katika eda au mkalificha ndani ya nyoyo zenu. Mwenyezi Mungu alikwishajua kwamba nyinyi mtawakumbuka. Lakini msiwaahidi kwa siri, isipokuwa mseme maneno mema. Wala msiazimie kufunga mkataba wa ndoa mpaka andiko (la amri ya eda) lifike muda wake. Na jueni kwamba Mwenyezi Mungu kwa hakika anajua yaliyo katika nafsi zenu. Basi jitahadharini naye. Na jueni kwamba Mwenyezi Mungu ni Mwenye kusamehe, Mpole.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 236, 'Hakuna ubaya wowote juu yenu mkiwataliki wanawake ambao hamjawagusa au kuwabainishia mahari yao. Lakini wapeni cha kuwaliwaza, mwenye wasaa kwa kiwango awezacho na mwenye dhiki kwa kiwango awezacho, maliwazo kwa wema, ni haki juu ya watendao mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 237, 'Na mkiwataliki kabla ya kuwagusa, na tayari mmeshawakatia mahari mahususi, basi wapeni nusu ya mahari mliyowakatia. Isipokuwa ikiwa wanawake wenyewe watasamehe, au amesamehe yule ambaye fundo la ndoa liko mkononi mwake. Na mkisamehe ndiyo kuwa karibu zaidi na ucha Mungu. Wala msisahau fadhila zilizo baina yenu. Hakika, Mwenyezi Mungu anayaona vyema mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 238, 'Zilindeni Swala, na hasa Swala ya katikati. Na simameni kwa ajili ya Mwenyezi Mungu kwa unyenyekevu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 239, 'Na mkiwa na hofu, basi (swalini) hali ya kuwa mnakwenda kwa miguu au mmepanda. Na mtakapokuwa katika amani, basi mtajeni Mwenyezi Mungu kama alivyowafunza yale ambayo hamkuwa mnayajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 240, 'Na wale miongoni mwenu wanaofishwa, na wanawaacha wake, na wausie kwa ajili ya wake zao kupata matumizi kwa mwaka mmoja bila ya kuwatoa nyumbani. Na wanawake wenyewe wakiondoka, basi hakuna ubaya wowote juu yenu katika yale waliyojifanyia wenyewe kwa wema. Na Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 241, 'Na wanawake waliotalikiwa wapewe cha kuwaliwaza kwa wema. Hii ni haki juu ya wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 242, 'Namna hivi ndivyo anavyowabainishia Mwenyezi Mungu Aya zake ili mpate kufahamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 243, 'Je, hukuwaona wale waliotoka katika maboma yao kwa maelfu kwa kuogopa mauti? Na Mwenyezi Mungu akawaambia: "Kufeni!" Kisha akawahuisha. Hakika, Mwenyezi Mungu ni Mwenye fadhila juu ya watu, lakini wengi wa watu hawashukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 244, 'Na piganeni vita katika Njia ya Mwenyezi Mungu, na jueni kwamba Mwenyezi Mungu ni Mwenye kusikia, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 245, 'Ni nani atakayemkopesha Mwenyezi Mungu mkopo mwema; ili amzidishie mizidisho mingi. Na Mwenyezi Mungu hukunja na hukunjua. Na kwake Yeye mtarejeshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 246, 'Je, hukuwaona watukufu katika Wana wa Israili baada ya Musa, walipomwambia Nabii wao: Tuwekee mfalme ili tupigane katika Njia ya Mwenyezi Mungu? Akasema: Je, haielekei ikiwa mtaandikiwa vita kuwa msipigane? Wakasema: Itakuwaje tusipigane katika Njia ya Mwenyezi Mungu, ilhali tumeshatolewa katika maboma yetu na watoto wetu? Lakini walipoandikiwa kupigana vita, wakageuka, isipokuwa wachache miongoni mwao. Na Mwenyezi Mungu anawajua vyema madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 247, 'Na Nabii wao akawaambia: Hakika, Mwenyezi Mungu ameshawateulia Taluti (Sauli) kuwa ndiye mfalme. Wakasema: Vipi atakuwa na ufalme juu yetu, ilhali sisi tuna haki zaidi kupata ufalme kuliko yeye, naye hakupewa wasaa wa mali? Akasema: Hakika, Mwenyezi Mungu amemteua yeye juu yenu na amemzidishia ukunjufu wa elimu na kiwiliwili. Na Mwenyezi Mungu humpa ufalme wake amtakaye. Na Mwenyezi Mungu ni Mwenye wasaa, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 248, 'Na Nabii wao akawaambia: Hakika, alama ya ufalme wake ni kwamba awaletee lile sanduku ambalo ndani yake mna kituliza nyoyo zenu kutoka kwa Mola wenu Mlezi. Na mabaki ya waliyoyaacha watu wa Musa na watu wa Harun, linalobebwa na Malaika. Bila shaka, katika hayo zimo ishara kwenu ikiwa nyinyi ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 249, 'Basi Taluti alipoondoka na majeshi, alisema: Hakika, Mwenyezi Mungu atawajaribu kwa mto. Hivyo basi, atakayekunywa humo, si pamoja nami. Na yule asiyeyaonja, basi huyo atakuwa pamoja nami; ila atakayeteka humo kiasi cha kitanga cha mkono wake. Lakini walikunywa humo isipokuwa wachache tu miongoni mwao. Na alipovuka mto yeye na wale walioamini pamoja naye, walisema: Leo hatumwezi Jaluti (Goliati) na majeshi yake. Wakasema wale wenye yakini ya kukutana na Mwenyezi Mungu: Ni makundi mangapi madogo yalishinda makundi makubwa kwa idhini ya Mwenyezi Mungu? Na Mwenyezi Mungu yu pamoja na wenye kusubiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 250, 'Na walipotoka ili kupambana na Jaluti na majeshi yake, walisema: Mola wetu Mlezi! Tumiminie subira, na isimamishe imara miguu yetu, na utunusuru kutokana na watu hawa makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 251, 'Kwa hivyo, wakawashinda kwa idhini ya Mwenyezi Mungu, na Daudi akamuua Jaluti. Na Mwenyezi Mungu akampa Daudi ufalme na hekima, na akamfundisha katika aliyoyataka. Na lau kuwa Mwenyezi Mungu hawazuii watu kwa watu, basi dunia ingeliharibika. Lakini Mwenyezi Mungu ni Mwenye fadhila juu ya walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 252, 'Hizi ni Aya za Mwenyezi Mungu tunazokusomea kwa haki. Na hakika wewe ni miongoni mwa Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 253, 'Mitume hao tumewaboresha baadhi yao juu ya wengineo. Miongoni mwao kuna wale ambao Mwenyezi Mungu alisema nao, na akawapandisha vyeo baadhi yao. Na tukampa Isa mwana wa Maryam hoja zilizo wazi, na tukamtia nguvu kwa Roho Mtakatifu. Na lau kuwa Mwenyezi Mungu angelipenda, wasingelipigana wale waliokuwa baada yao, baada ya kujiwa na hoja zilizo wazi. Lakini walihitilafiana. Basi miongoni mwao kuna wale walioamini, na miongoni mwao kuna wale waliokufuru. Na lau kuwa Mwenyezi Mungu angelitaka, wasingelipigana. Lakini Mwenyezi Mungu hufanya kile akitakacho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 254, 'Enyi mlioamini! Toeni katika tulivyowaruzuku kabla haijakuja Siku ambayo hapatakuwapo biashara yoyote, wala urafiki, wala uombezi. Na makafiri ndio madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 255, 'Mwenyezi Mungu - hakuna mungu isipokuwa Yeye, Aliye hai, Msimamizi wa mambo yote milele. Hashikwi na kusinzia wala kulala. Ni vyake vilivyomo mbinguni na vilivyomo duniani. Ni nani huyo awezaye kufanya uombezi mbele yake isipokuwa kwa idhini yake? Anayajua yaliyo mbele yao, na yaliyo nyuma yao, wala wao hawajui vyema chochote katika elimu yake isipokuwa kwa kile akitakacho. Kursi (mahali inapokanyaga miguu) yake imeenea mbingu na dunia, na wala halemewi katika kuvilinda vyote viwili. Na Yeye ndiye aliye juu zaidi, Mkuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 256, 'Hakuna kulazimisha katika Dini. Kwani uongofu umekwishapambanuka kutokana na upotovu. Kwa hivyo, anayemkufuru Taaghuut na akamwamini Mwenyezi Mungu, basi bila ya shaka amekamata kishikio madhubuti, kisichovunjika. Na Mwenyezi Mungu ni Mwenye kusikia mno, Mwenye kujua vyema.[1]', '[1] Na wala hakuna upinzani baina ya maana hii na Aya nyingi zinazolazimu kuwepo kwa Jihadi. Kwani, Mwenyezi Mungu ameamrisha kupigana vita ili Dini yote iwe ya Mwenyezi Mungu tu. Na kuzuia uadui wa wenye kufanya uadui dhidi ya dini.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 257, 'Mwenyezi Mungu ndiye Mlinzi wa walioamini. Huwatoa katika giza mbalimbali kwenda katika nuru. Lakini wale waliokufuru, walinzi wao ni Taaghut. Huwatoa katika nuru kwenda hadi katika giza mbalimbali. Hao ndio watu wa Motoni, humo watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 258, 'Kwani hukumuona yule aliyehojiana na Ibrahim kuhusu Mola wake Mlezi kwa sababu Mwenyezi Mungu alimpa ufalme? Ibrahim aliposema: Mola wangu Mlezi ni yule ambaye huhuisha na kufisha. Yeye akasema: Mimi pia ninahuisha na ninafisha. Ibrahim akasema: Kwa hakika, Mwenyezi Mungu hulileta jua kutokea mashariki, basi wewe lilete kutokea magharibi. Kwa hivyo, akashindwa yule aliyekufuru. Na Mwenyezi Mungu hawaongoi kaumu dhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 259, 'Au kama yule aliyepita karibu na mji hali ya kuwa umekwishakuwa magofu tu. Akasema: Vipi Mwenyezi Mungu ataufufua mji huu baada ya kufa kwake? Basi Mwenyezi Mungu akamfisha yeye (muda wa) miaka mia moja, kisha akamfufua. Akasema: Je umekaa muda gani? Akasema: (Labda) nimekaa siku moja au sehemu ya siku. Akasema: Bali umekaa miaka mia moja. Hebu angalia chakula chako na vinywaji vyako, havikuharibika. Na mwangalie punda wako. Na ili tukufanye uwe ni ishara kwa watu. Na iangalie mifupa yake hii jinsi tunavyoinyanyua kisha tuivishe nyama. Basi yalipombainikia, alisema: Ninajua kwamba kwa hakika Mwenyezi Mungu ni Mwenye uwezo mno juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 260, 'Na Ibrahim aliposema: Mola wangu Mlezi! Nionyeshe vipi unavyofufua wafu. Mwenyezi Mungu akasema: Kwani huamini? Akasema: Hasha! Lakini ili moyo wangu utue. Akasema: Basi wachukue wanne katika ndege na uwazoeshe kwako. Kisha weka juu ya kila kilima sehemu katika hao, kisha waite, watakujia mbio. Na ujue kwamba hakika Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 261, 'Mfano wa wale wanaotoa mali zao katika Njia ya Mwenyezi Mungu ni kama mfano wa punje moja iliyochipuza mashuke saba. Katika kila shuke zimo punje mia moja. Na Mwenyezi Mungu humzidishia amtakaye. Na Mwenyezi Mungu ni Mwenye wasaa, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 262, 'Wale wanaotoa mali zao kwa Njia ya Mwenyezi Mungu, kisha hawafuatishi kile walichotoa masimbulizi wala udhia, wana ujira wao kwa Mola wao Mlezi. Wala haitakuwa hofu juu yao wala wao hawatahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 263, 'Kauli njema na msamaha ni bora kuliko sadaka inayofuatwa na maudhi. Na Mwenyezi Mungu ndiye Mwenye kujitosheleza, Mstahamilivu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 264, 'Enyi mlioamini! Msiharibu sadaka zenu kwa masimbulizi na maudhi. Kama yule anayetoa mali yake ili kujionyesha kwa watu, wala hamuamini Mwenyezi Mungu wala Siku ya Mwisho. Basi mfano wake ni kama mfano wa jabali ambalo juu yake kuna udongo, kisha likapigwa na mvua kubwa, ikaliacha tupu. Basi hawatakuwa na uwezo wowote juu ya kile walichochuma. Na Mwenyezi Mungu hawaongoi kaumu ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 265, 'Na mfano wa wale wanaotoa mali zao kwa kuzitafuta radhi za Mwenyezi Mungu, na kuzipa nguvu roho zao ni kama mfano wa bustani iliyo mahali pa juu. Ikaifikia mvua kubwa na ikaleta mazao yake maradufu. Na hata kama haifikiwi na mvua kubwa, basi manyunyu tu yanatosha. Na Mwenyezi Mungu anayaona vyema mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 266, 'Je, angependa mmoja wenu kwamba awe na bustani ya mitende na mizabibu ipitayo mito chini yake. Naye humo hupata katika mazao ya kila namna, na uzee ukamfikia ilhali ana watoto wanyonge. Kisha ikapigwa na kimbunga chenye moto, kwa hivyo ikaungua? Hivi ndivyo Mwenyezi Mungu anavyowabainishia ishara ili mtafakari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 267, 'Enyi mlioamini! Toeni katika vile vizuri mlivyovichuma, na katika vile tulivyowatolea katika ardhi. Wala msikusudie kutoa vilivyo vibaya, ilhali nyinyi wenyewe msingevipokea isipokuwa kwa kuvifumbia macho. Na jueni kwamba Mwenyezi Mungu ni Mwenye kujitosha, Msifiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 268, 'Shetani anawatia hofu ya ufakiri, na anawaamrisha machafu. Na Mwenyezi Mungu anawaahidi msamaha kutoka kwake na fadhila. Na Mwenyezi Mungu ni Mwenye wasaa, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 269, 'Yeye humpa hekima amtakaye. Na mwenye kupewa hekima, basi bila ya shaka amepewa heri nyingi. Na hawakumbuki isipokuwa wenye akili ya hali ya juu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 270, 'Na chochote mnachotoa au nadhiri mnazoweka, basi hakika Mwenyezi Mungu anajua hayo. Na madhalimu hawana wowote wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 271, 'Mkizidhihirisha sadaka, basi hilo ni vizuri. Na mkizificha na mkawapa mafakiri kwa siri, basi hilo ni heri kwenu, na yatawaondolea katika maovu yenu. Na Mwenyezi Mungu ana habari ya mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 272, 'Si juu yako wewe kuwaongoa, lakini Mwenyezi Mungu humwongoa amtakaye. Na chochote mnachotoa katika heri, basi ni cha nafsi zenu. Wala hamtoi isipokuwa kwa kutafuta uso wa Mwenyezi Mungu. Na chochote mnachotoa katika heri, mtalipwa kwa ukamilifu, nanyi hamtadhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 273, 'Na wapewe mafakiri waliozuiliwa katika njia za Mwenyezi Mungu, wasioweza kusafiri katika nchi kutafuta riziki. Asiyewajua hali zao huwadhania kuwa ni matajiri kwa sababu ya kujizuia kwao. Utawatambua kwa alama zao; hawawang''ang''anilii watu kwa kuwaomba. Na chochote mnachotoa katika heri, basi hakika Mwenyezi Mungu anaijua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 274, 'Wale wanaotoa mali zao usiku na mchana, kwa siri na dhahiri, wana ujira wao kwa Mola wao Mlezi; wala haitakuwa hofu juu yao, wala wao hawatahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 275, 'Wale wanaokula riba, hawasimami isipokuwa kama anavyosimama aliyezugwa na Shetani kwa kumgusa. Hayo ni kwa kuwa walisema: Hakika, biashara ni kama riba. Lakini Mwenyezi Mungu ameihalalisha biashara na ameiharamisha riba. Basi mwenye kujiwa na mawaidha kutoka kwa Mola wake Mlezi, kisha akakomeka, basi yake ni yaliyokwishapita. Na mambo yake yako kwa Mwenyezi Mungu. Na wenye kurudia, basi hao ndio watu wa Motoni, wao watadumu humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 276, 'Mwenyezi Mungu huondoa baraka katika riba, na huzibariki sadaka. Na Mwenyezi Mungu hampendi kila mwenye kukufuru mno na afanyae dhambi nyingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 277, 'Hakika, wale walioamini na wakatenda mema na wakashika Swala na wakatoa Zaka, wao watapata ujira wao kwa Mola wao Mlezi. Wala haitakuwa hofu juu yao, wala hawatahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 278, 'Enyi mlioamini! Mcheni Mwenyezi Mungu, na acheni riba zilizobaki, ikiwa nyinyi ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 279, 'Na msipofanya, basi jitangazieni vita kutoka kwa Mwenyezi Mungu na Mtume wake. Na mkitubu, basi haki yenu ni rasilimali zenu. Msidhulumu wala msidhulumiwe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 280, 'Na (mdaiwa) akiwa ana ugumu, basi (mdai) angoje mpaka awe katika wepesi. Na mkilifanya deni kuwa ni sadaka, basi ni bora kwenu, ikiwa mnajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 281, 'Na iogopeni Siku ambayo mtarudishwa kwa Mwenyezi Mungu, kisha kila nafsi italipwa ilichochuma. Nao hawatadhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 282, 'Enyi mlioamini! Mnapodaiana deni hadi muda maalumu, basi liandikeni. Na mwandishi aandike baina yenu kwa uadilifu, wala mwandishi asikatae kuandika kama alivyomfunza Mwenyezi Mungu. Basi na aandike, na mwenye deni juu yake aandikishe; na amche Mwenyezi Mungu, Mola wake Mlezi, wala asipunguze chochote ndani yake. Na ikiwa mwenye kudaiwa ni mtu aliye pumbaa au mnyonge au hawezi kuandikisha mwenyewe, basi aandikishe mlinzi wake kwa uadilifu. Na washuhudisheni mashahidi wawili katika wanaume wenu. Na ikiwa wanaume wawili hawapo, basi mwanamume mmoja na wanawake wawili katika wale mnaowaridhia miongoni mwa mashahidi. Ili ikiwa mmoja wao (wanawake hao) atapotea, basi mmoja wao amkumbushe huyo mwengine. Na mashahidi wasikatae pindi wanapoitwa. Wala msipuuze kuliandika deni likiwa dogo au kubwa mpaka muda wake. Hayo ndiyo ya uadilifu zaidi kwa Mwenyezi Mungu, na ndiyo sawa zaidi kwa ushahidi, na ya chini zaidi ili msiwe na shaka. Isipokuwa ikiwa ni biashara ya mkono kwa mkono mnayoifanya baina yenu, basi hapo hakuna ubaya juu yenu msipoiandika. Lakini wekeni mashahidi mnapouziana. Wala asitiwe matatani mwandishi wala shahidi. Na mkifanya hivyo, basi hakika huko ni kupita mipaka mliko nako. Na mcheni Mwenyezi Mungu. Na Mwenyezi Mungu anajua kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 283, 'Na mkiwa katika safari, na hamkupata mwandishi, basi yatosha kukabidhiwa rahani. Na mmoja wenu akimwekea amana mwenziwe, basi aliyeaminiwa airudishe amana ya mwenzake, na amche Mwenyezi Mungu, Mola wake Mlezi. Wala msifiche ushahidi. Na atakayeuficha, basi hakika moyo wake ni wenye kutenda dhambi. Na Mwenyezi Mungu anayajua mnayoyatenda', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 284, 'Ni vya Mwenyezi Mungu vilivyo katika mbingu na vilivyo katika ardhi. Na mkidhihirisha yaliyo katika nafsi zenu au mkayaficha, Mwenyezi Mungu atawahesabu kwayo. Kisha atamsamehe amtakaye na amwadhibu amtakaye. Na Mwenyezi Mungu ni Muweza mno wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 285, 'Mtume ameamini yaliyoteremshwa kwake kutoka kwa Mola wake Mlezi, na Waumini vile vile. Wote wamemwamini Mwenyezi Mungu, na Malaika wake, na Vitabu vyake na Mitume wake. Hatutofautishi baina ya yeyote katika Mitume wake, na (Waumini) husema: Tumesikia na tumetii. Tunakutaka maghfira Mola wetu Mlezi! Na marejeo ni kwako.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 286, 'Mwenyezi Mungu haikalifishi nafsi yoyote isipokuwa kwa kiwango cha iwezavyo. Faida ya iliyoyachuma ni yake, na hasara ya iliyoyachuma ni juu yake pia. (Semeni) Mola wetu Mlezi! Usituchukulie ubaya tukisahau au tukikosea. Mola wetu Mlezi! Usitubebeshe mzigo kama uliyowabebesha wale waliokuwa kabla yetu. Mola wetu Mlezi! Usitutwike tusiyoyaweza, na uyatupilie mbali mabaya yetu, na utusamehe na uturehemu. Wewe ndiye Mlinzi wetu. Basi tupe ushindi dhidi ya kaumu ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 1, 'Alif Laam Miim.[1]', '[1] Herufi hizi "Alif Laam Miim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 2, 'Mwenyezi Mungu, hakuna mungu isipokuwa Yeye. Aliye hai, Msimamizi wa yote milele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 3, 'Amekiteremsha Kitabu juu yako kwa haki, kinachosadikisha yaliyokuwa kabla yake. Na aliteremsha Taurati na Injili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 4, 'Kabla yake, viwe uongofu kwa watu. Na akateremsha Furqani (Upambanuo). Hakika, wale waliozikufuru Ishara za Mwenyezi Mungu wana adhabu kali. Na Mwenyezi Mungu ni Mwenye nguvu, Mwenye kulipiza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 5, 'Hakika, Mwenyezi Mungu hakifichikani chochote kwake, katika dunia wala katika mbingu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 6, 'Yeye ndiye anayewaunda ndani ya matumbo ya uzazi kwa namna apendavyo. Hakuna mungu isipokuwa Yeye, Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 7, 'Yeye ndiye aliyeteremsha juu yako Kitabu hiki. Ndani yake zimo Aya muhkam (zenye maana wazi). Hizo ndizo msingi wa Kitabu hiki. Na zimo nyingine Mutashabihat (zenye maana zisizo wazi). Ama wale ambao katika nyoyo zao umo upotovu, wao wanafuata zile zenye maana zisizo wazi kwa kutafuta fitina, na kutafuta kupotoa maana yake. Na wala hapana ajuaye maana yake isipokuwa Mwenyezi Mungu. Na wale waliokita katika elimu husema: Sisi tumeziamini, zote zimetoka kwa Mola wetu Mlezi. Lakini hawakumbuki (hayo) isipokuwa wenye akili ya hali ya juu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 8, '(Na wao husema) Mola wetu Mlezi! Usizipotoe nyoyo zetu baada ya kutuongoa, na tutunuku rehema itokayo kwako. Hakika, Wewe ndiye Mwenye kutunuku mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 9, 'Mola wetu Mlezi! Hakika, Wewe ndiye utakayewakusanya watu kwa Siku isiyo na shaka ndani yake. Hakika, Mwenyezi Mungu havunji miadi yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 10, 'Kwa hakika, wale waliokufuru, hazitawafaa kitu mali zao wala watoto wao kutokana na Mwenyezi Mungu. Na hao ndio kuni za Moto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 11, 'Kama ada ya watu wa Firauni na wale waliokuwa kabla yao. Walikadhibisha Ishara zetu, basi Mwenyezi Mungu akawachukua kwa dhambi zao; na Mwenyezi Mungu ni Mkali wa kuadhibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 12, 'Waambie wale waliokufuru: Karibuni mtashindwa na mtakusanywa mtiwe kwenye Jahannam; napo ndipo pahali paovu zaidi pa mapumziko.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 13, 'Hakika, mlikuwa na Ishara katika yale makundi mawili yalipokutana (katika vita). Kundi moja likipigana katika Njia ya Mwenyezi Mungu, nalo lingine kafiri likiwaona zaidi kuliko wao mara mbili, kwa kuona kwa macho. Na Mwenyezi Mungu humuunga mkono amtakaye kwa nusura yake. Hakika, katika hayo kuna mazingatio kwa wenye macho yaliyo sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 14, 'Watu wamepambiwa kupenda matamanio ya wanawake, na wana, na mirundo mingi ya dhahabu na fedha, na farasi wazuri zaidi, na mifugo, na mashamba. Hayo ni starehe ya maisha ya duniani, na Mwenyezi Mungu ana marejeo mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 15, 'Sema: Je, niwaambie yaliyo bora kuliko hayo? Kwa waliomcha Mungu kwa Mola wao Mlezi ziko Bustani zipitazo mito chini yake. Watadumu humo, na wake waliotakaswa, na radhi kutoka kwa Mwenyezi Mungu. Na Mwenyezi Mungu ni Mwenye kuwaona vyema waja wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 16, 'Wale wanaosema: Mola wetu Mlezi! Hakika, sisi tumeamini. Basi tusamehe dhambi zetu, na tuepushe kutokana na adhabu ya Moto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 17, 'Wanaovumilia, na wakweli, na wanyenyekevu, na watoao, na wanao omba msamaha katika masaa ya mwisho ya usiku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 18, 'Mwenyezi Mungu alishuhudia kuwa hakika hakuna mungu isipokuwa Yeye, na pia (walishuhudia) Malaika, na wenye elimu akisimamisha uadilifu. Hakuna mungu isipokuwa Yeye Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 19, 'Hakika, Dini kwa Mwenyezi Mungu ni Uislamu. Na hawakuhitilafiana wale waliopewa Kitabu isipokuwa baada ya kujiwa na elimu, kwa sababu ya uhasidi uliokuwa baina yao. Na mwenye kuzikufuru Ishara za Mwenyezi Mungu, basi hakika Mwenyezi Mungu ni Mwepesi wa kuhesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 20, 'Na wakikuhoji, basi sema: Mimi nimeusalimisha uso wangu kwa ajili ya Mwenyezi Mungu, na vile vile walionifuata. Na waambie wale waliopewa Kitabu na wale wasiojua kusoma: "Je, mmesilimu?" Wakisilimu, basi hakika wameongoka. Na wakikengeuka, basi juu yako ni kufikisha ujumbe tu. Na Mwenyezi Mungu ni Mwenye kuwaona vyema waja wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 21, 'Hakika, wale wanaozikufuru Ishara za Mwenyezi Mungu, na wakawaua Manabii bila ya haki, na wakawaua wale wanaoamrisha haki katika watu, basi wabashirie adhabu kali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 22, 'Hao ndio ambao vitendo vyao viliharibika duniani na Akhera. Nao hawana wowote wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 23, 'Je, huwaoni wale waliopewa fungu katika Kitabu? Wanaitwa kukiendea Kitabu cha Mwenyezi Mungu ili kihukumu baina yao; kisha kundi miongoni mwao wanageuka huku wamepeana mgongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 24, 'Hayo ni kwa sababu walisema: "Hautatugusa Moto isipokuwa kwa siku chache tu." Na yakawadanganya katika dini yao yale ambayo wenyewe walikuwa wakiyazua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 25, 'Basi itakuwaje tutakapowakusanya kwa ajili ya Siku ambayo hakuna shaka nayo? Na kila nafsi italipwa ilichochuma, nao hawatadhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 26, 'Sema: Ewe Mwenyezi Mungu uliye Mmiliki wa ufalme wote! Wewe humpa ufalme umtakaye, na humwondolea ufalme umtakaye. Na humtukuza umtakaye, na humdhalilisha umtakaye. Heri yote iko mkononi mwako. Hakika, Wewe ni Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 27, 'Wewe huuingiza usiku katika mchana, na huuingiza mchana katika usiku. Na humtoa hai kutokana na maiti, na humtoa maiti kutokana na aliye hai. Na unamruzuku umtakaye bila ya hesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 28, 'Waumini wasiwafanye makafiri kuwa marafiki wa kuwasaidia badala ya Waumini. Na mwenye kufanya hilo, basi hatakuwa na chochote mbele ya Mwenyezi Mungu. Isipokuwa ikiwa kwa ajili ya kujilinda na shari zao. Na Mwenyezi Mungu anawahadharisha naye mwenyewe. Na marejeo ni kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 29, 'Sema: Mkificha yaliyo vifuani mwenu au mkiyaweka wazi, Mwenyezi Mungu anayajua. Na anayajua yaliyo katika mbingu na yaliyo katika dunia. Na Mwenyezi Mungu ni Muweza mno wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 30, 'Siku ambayo kila nafsi itakuta yale iliyofanya katika mema yamehudhurishwa, na pia yale iliyofanya katika ubaya. Itapenda lau baina ya hayo (mabaya) na yeye ungekuwepo umbali mrefu. Na Mwenyezi Mungu anawatahadharisha na yeye mwenyewe. Na Mwenyezi Mungu ni Mpole kwa waja wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 31, 'Sema: Ikiwa nyinyi mnampenda Mwenyezi Mungu, basi nifuateni mimi, Mwenyezi Mungu atawapenda na atawafutia dhambi zenu. Na Mwenyezi Mungu ni Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 32, 'Sema: ''Mtiini Mwenyezi Mungu na Mtume.'' Na wakigeuka, basi hakika Mwenyezi Mungu hawapendi makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 33, 'Hakika, Mwenyezi Mungu alimteua Adam, na Nuhu, na ukoo wa Ibrahim, na ukoo wa Imran juu ya walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 34, 'Ni dhuria wao kwa wao. Na Mwenyezi Mungu ni Mwenye kusikia, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 35, 'Aliposema mke wa Imran: Mola wangu Mlezi! Hakika mimi, nimekuwekea nadhiri kilicho katika tumbo langu la uzazi awe mtumishi wako, basi nikubalie. Hakika, Wewe ndiye Mwenye kusikia, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 36, 'Basi alipomzaa, akasema: Mola wangu Mlezi! Hakika mimi, nimemzaa wa kike - na Mwenyezi Mungu anajua sana aliyemzaa. Na wa kiume si sawa na wa kike. Na mimi kwa hakika nimemwita Mariam. Nami kwa hakika ninamkinga kwako, yeye na dhuria yake kutokana na Shetani aliyelaaniwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 37, 'Basi Mola wake Mlezi akampokea kwa mapokeo mema na akamkuza makuzo mema, na akamfanya Zakariya awe mlezi wake. Kila mara Zakariya alipoingia chumbani kwake, alimkuta na vyakula. Basi alisema: Ewe Mariam! Unavipata wapi hivi? Naye akasema: Hivi vinatoka kwa Mwenyezi Mungu. Hakika, Mwenyezi Mungu humruzuku amtakaye bila ya hesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 38, 'Pale pale Zakariya akamwomba Mola wake Mlezi, akasema: Mola wangu Mlezi! Nitunuku kutoka kwako dhuria njema. Hakika, Wewe ndiye unayesikia maombi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 39, 'Kwa hivyo, Malaika wakamwita hali ya kuwa amesimama katika chumba akisali kwamba: Mwenyezi Mungu anakupa bishara njema ya Yahya, atakayesadikisha neno litokalo kwa Mwenyezi Mungu, na ni bwana, na mtawa, na ni Nabii miongoni mwa walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 40, 'Zakariya akasema: Mola wangu Mlezi! Vipi nitapata mwana, ilhali tayari uzee umeshanifikia, na mke wangu ni tasa? Akasema: Hivyo ndivyo Mwenyezi Mungu, yeye hufanya apendavyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 41, 'Akasema: Mola wangu Mlezi! Niwekee alama. Akasema: Alama yako ni kuwa hutasema na watu kwa siku tatu, isipokuwa kwa kuashiria tu. Na mtaje Mola wako Mlezi kwa wingi, na mtakase jioni na asubuhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 42, 'Na tazama, pale Malaika waliposema: Ewe Maryam! Kwa hakika, Mwenyezi Mungu amekuteua, na amekutakasa, na amekuteua juu ya wanawake wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 43, 'Ewe Maryam! Mnyenyekee Mola wako Mlezi, na usujudu, na urukuu pamoja na wanaorukuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 44, 'Hizi ni katika habari za ghaibu tunazokufunulia. Nawe hukuwa nao walipokuwa wakitupa kalamu zao ni nani wao atakayemlea Maryam? Na hukuwa nao walipokuwa wakizozana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 45, 'Pale Malaika waliposema: Ewe Maryam! Hakika, Mwenyezi Mungu anakupa bishara njema ya (mwana kwa) neno litokalo kwake. Jina lake ni Masihi Isa mwana wa Maryam, mwenye heshima katika dunia na Akhera, na ni miongoni mwa waliowekwa karibu (na Mwenyezi Mungu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 46, 'Naye atazungumza na watu katika utoto wake na katika utu uzima wake, na atakuwa katika walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 47, 'Maryam akasema: Mola wangu Mlezi! Vipi nitampata mwana ilhali hajanigusa mwanadamu? Akasema: Hivyo ndivyo Mwenyezi Mungu, yeye huumba atakavyo. Anapohukumu jambo, yeye kwa hakika huliambia: ''Kuwa!'' Na linakuwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 48, 'Na atamfundisha kuandika na hekima na Taurati na Injili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 49, 'Na ni Mtume kwa Wana wa Israili kuwaambia: Mimi kwa hakika nimewajia na Ishara kutoka kwa Mola wenu Mlezi, ya kwamba mimi kwa hakika ninawaundia kwa udongo kama sura ya ndege. Kisha ninapuliza ndani yake na anakuwa ndege kwa idhini ya Mwenyezi Mungu. Na ninawaponesha vipofu wa tangu kuzaliwa na wakoma, na ninawafufua maiti kwa idhini ya Mwenyezi Mungu. Na ninawaambia mnachokila na mnachoweka akiba katika nyumba zenu. Hakika, katika haya ipo Ishara kwenu ikiwa nyinyi ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 50, 'Na ninasadikisha yaliyokuwa kabla yangu katika Taurati, na ili niwahalalishie baadhi ya yale mliyoharamishiwa. Na nimewajia na Ishara kutoka kwa Mola Mlezi wenu. Kwa hivyo, mcheni Mwenyezi Mungu na nitiini mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 51, 'Hakika, Mwenyezi Mungu ni Mola wangu Mlezi na ni Mola wenu Mlezi. Basi muabuduni Yeye. Hii ndiyo Njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 52, 'Isa alipohisi ukafiri miongoni mwao, akasema: Ni nani watakaonisaidia katika kulingania kwa Mwenyezi Mungu? Wanafunzi wake wakasema: Sisi tutamnusuru Mwenyezi Mungu. Tumemuamini Mwenyezi Mungu, na shuhudia kwamba sisi hakika ni Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 53, 'Mola wetu Mlezi! Tuliyaamini uliyoyateremsha, na tulimfuata Mtume huyu, basi tuandike pamoja na wanaoshuhudia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 54, 'Na makafiri wakapanga vitimbi, na Mwenyezi Mungu akapanga vitimbi, na Mwenyezi Mungu ndiye mbora wa wenye kupanga vitimbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 55, 'Pale Mwenyezi Mungu aliposema: Ewe Isa, hakika Mimi nitakuchukua (bila kukufisha), na nitakunyanyua hadi kwangu, na nitakutakasa kutokana na wale waliokufuru, na nitawaweka wale waliokufuata juu ya wale waliokufuru, mpaka Siku ya Kiyama. Kisha kwangu ndiko marejeo yenu, na nihukumu kati yenu katika yale mliyokuwa mkihitilafiana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 56, 'Ama wale waliokufuru, basi nitawaadhibu adhabu kali katika dunia na Akhera, na wala hawatapata wowote wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 57, 'Na ama wale walioamini na wakatenda mema, basi Mwenyezi Mungu atawalipa ujira wao kamili. Na Mwenyezi Mungu hawapendi madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 58, 'Haya tunayokusomea ni katika Aya na ukumbusho wenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 59, 'Hakika, mfano wa Isa kwa Mwenyezi Mungu ni kama mfano wa Adam. Alimuumba kwa udongo kisha akamwambia: ''Kuwa!'' Basi akawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 60, 'Hii ni haki itokayo kwa Mola wako Mlezi. Basi usiwe miongoni mwa wanaofanya shaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 61, 'Basi mwenye kukuhoji katika haya baada ya yale yaliyokufikia katika elimu hii, waambie: Njooni tuwaite watoto wetu na watoto wenu, na wake zetu na wake zenu, na sisi wenyewe na nyinyi wenyewe, kisha tuombe kwa unyenyekevu tutake laana ya Mwenyezi Mungu iwashukie waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 62, 'Hakika, haya ndiyo maelezo ya kweli. Na hakuna mungu yeyote isipokuwa Mwenyezi Mungu tu. Na hakika Mwenyezi Mungu ndiye Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 63, 'Na wakigeuka, basi Mwenyezi Mungu anawajua mno waharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 64, 'Sema: ''Enyi Watu wa Kitabu! Njooni kwenye neno lililo sawa baina yetu na nyinyi: Ya kwamba tusimuabudu yeyote isipokuwa Mwenyezi Mungu, wala tusimshirikishe na chochote. Wala tusifanyane waungu sisi kwa sisi badala ya Mwenyezi Mungu.'' Na wakigeuka, basi semeni: Shuhudieni ya kwamba sisi kwa hakika ni Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 65, 'Enyi Watu wa Kitabu! Mbona mnabishana juu ya Ibrahim, na hali Taurati na Injili havikuteremshwa isipokuwa baada yake? Kwani hamtumii akili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 66, 'Angalieni! Nyinyi mlibishana katika yale mliyoyajua. Mbona sasa mnabishana katika yale msiyoyajua? Na Mwenyezi Mungu ndiye ajuaye, na nyinyi hamjui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 67, 'Ibrahim hakuwa Myahudi wala Mkristo. Lakini alikuwa mnyoofu, Muislamu, na wala hakuwa katika washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 68, 'Hakika, watu wanaomstahiki zaidi Ibrahim ni wale waliomfuata yeye, na Nabii huyu na wale walioamini. Na Mwenyezi Mungu ndiye Kipenzi Mlinzi wa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 69, 'Kilipenda kikundi katika Watu wa Kitabu lau kuwa wangekupotezeni. Lakini hawapotezi isipokuwa nafsi zao, nao wenyewe hawatambui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 70, 'Enyi Watu wa Kitabu! Kwa nini mnazikufuru Ishara za Mwenyezi Mungu ilhali nyinyi mnashuhudia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 71, 'Enyi Watu wa Kitabu! Kwa nini mnaivisha haki uongo, na mnaificha haki ilhali mnajua?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 72, 'Na kilisema kikundi kimoja katika Watu wa Kitabu: Yaaminini yale waliyoteremshiwa wale walioamini mwanzo wa mchana, na yakufuruni mwisho wake; huenda wakarejea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 73, 'Wala msimuamini isipokuwa yule anayeifuata dini yenu. Sema: Hakika uongofu ni uongofu wa Mwenyezi Mungu, kuwa apewe mtu mfano wa yale mliyopewa nyinyi au wawahoji mbele ya Mola wenu Mlezi. Sema: Hakika fadhila zimo mkononi mwa Mwenyezi Mungu. Humpa hizo amtakaye. Na Mwenyezi Mungu ni Mwenye wasaa, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 74, 'Yeye humchagua kumpa rehema zake amtakaye. Na Mwenyezi Mungu ndiye Mwenye fadhila kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 75, 'Na miongoni mwa Watu wa Kitabu yupo ambaye ukimpa amana ya mrundo wa mali, atakurudishia. Na miongoni mwao yupo ambaye ukimpa amana ya dinari moja, hakurudishii isipokuwa ukimsimamia kumdai. Haya ni kwa kuwa walisema: ''Hatuna lawama kwa sababu ya hawa wasiojua kusoma na kuandika.'' Na wanasema uongo juu ya Mwenyezi Mungu hali ya kuwa wanajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 76, 'Sivyo hivyo! Bali mwenye kulitimiza agano lake na akawa mcha Mungu, basi hakika Mwenyezi Mungu huwapenda wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 77, 'Hakika, wale wanaouza agano la Mwenyezi Mungu na viapo vyao kwa thamani ndogo, hao hawatakuwa na fungu lolote katika Akhera, wala Mwenyezi Mungu hatasema nao, wala hatawatazama Siku ya Kiyama, wala hatawatakasa, nao wana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 78, 'Na hakika wapo miongoni mwao kundi lipindualo ndimi zao katika kusoma Kitabu ili mdhani kuwa hayo yanatoka Kitabuni, na wala hayatoki Kitabuni. Nao husema: ''Haya yametoka kwa Mwenyezi Mungu.'' Na wala hayakutoka kwa Mwenyezi Mungu. Na wanasema uongo juu ya Mwenyezi Mungu hali ya kuwa wanajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 79, 'Haikumfailia mtu yeyote kwamba Mwenyezi Mungu ampe Kitabu na hekima na Unabii, kisha awaambie watu: ''Kuweni wa kuniabudu mimi badala ya Mwenyezi Mungu.'' Bali atawaambia: ''Kuweni wenye kumuabudu Mola Mlezi wa viumbe vyote, kwa kuwa nyinyi mnafundisha Kitabu na kwa kuwa mnakisoma.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 80, 'Wala hatawaamrisha kwamba muwafanye Malaika na Manabii kuwa ni miungu. Je, atawaamrisha ukafiri baada ya nyinyi kuwa Waislamu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 81, 'Na pale Mwenyezi Mungu alipochukua agano la Manabii: Nikishawapa Kitabu na hekima, kisha akawajia Mtume mwenye kusadikisha yale mliyo nayo, basi hakika mtamuamini na mtamsaidia. Akasema: Je, mmekiri na mmekubali kushika agano langu la mkazo juu ya hayo? Wakasema: Tumekubali. Akasema: Basi shuhudieni, na Mimi ni pamoja nanyi katika wanaoshuhudia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 82, 'Kwa hivyo, mwenye kugeuka baada ya haya, basi hao ndio wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 83, 'Je, wanataka dini isiyokuwa ya Mwenyezi Mungu, ilhali kila kilicho katika mbingu na katika ardhi kimejisalimisha kwake kwa kumtii Yeye kwa kupenda na kwa kutopenda, na kwake Yeye watarejeshwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 84, 'Sema: Tumemwamini Mwenyezi Mungu, na yale tuliyoteremshiwa sisi, na yale yaliyoteremshwa kwa Ibrahim, na Ismail, na Is-haak na Yaakub na wana wake, na yale aliyopewa Musa na Isa na Manabii wengine kutoka kwa Mola wao Mlezi. Hatutofautishi yeyote baina yao, na sisi ni wenye kujisalimisha kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 85, 'Na mwenye kutafuta dini isiyokuwa Uislamu, basi haitakubaliwa kutoka kwake. Naye katika Akhera atakuwa miongoni mwa waliohasirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 86, 'Vipi Mwenyezi Mungu atawaongoa kaumu waliokufuru baada ya kuamini kwao, na wakashuhudia ya kuwa Mtume huyu ni wa haki, na zikawajia hoja zilizo wazi? Na Mwenyezi Mungu hawaongoi kaumu ya madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 87, 'Hao malipo yao ni kuwa ipo juu yao laana ya Mwenyezi Mungu na ya Malaika na ya watu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 88, 'Humo watadumu. Hawatapunguziwa adhabu, wala hawatapewa nafasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 89, 'Isipokuwa wale waliotubu baada ya hayo na wakatengenea. Basi Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 90, 'Hakika, wale waliokufuru baada ya kuamini kwao, kisha wakazidi kukufuru, haitakubaliwa toba yao, na hao ndio waliopotea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 91, 'Hakika, wale waliokufuru, na wakafa hali ya kuwa ni makafiri, haitakubaliwa kutoka kwa yeyote wao fidia ya dhahabu ya kujaza dunia nzima lau wangeliitoa. Hao wana adhabu chungu, wala hawatakuwa na wowote wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 92, 'Kamwe hamtaufikia wema mpaka mtoe katika vile mnavyovipenda. Na kitu chochote mnachokitoa, basi hakika Mwenyezi Mungu anakijua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 93, 'Kila chakula kilikuwa halali kwa Wana wa Israili isipokuwa kile alichojiharamishia Israili mwenyewe kabla ya kuteremshwa Taurati. Sema: Ileteni Taurati, na muisome ikiwa nyinyi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 94, 'Na mwenye kumzulia uongo Mwenyezi Mungu baada ya hayo, basi hao ndio madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 95, 'Sema: Mwenyezi Mungu amesema kweli. Basi fuateni mila ya Ibrahim mwongofu, wala hakuwa miongoni mwa washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 96, 'Hakika, Nyumba ya kwanza waliyowekewa watu kwa ibada ni ile iliyo Bakka, iliyobarikiwa na yenye uongofu kwa walimwengu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 97, 'Ndani yake kuna Ishara zilizo wazi - masimamio ya Ibrahim. Na mwenye kuingia humo, anakuwa na amani. Na kwa ajili ya Mwenyezi Mungu imewawajibikia watu wahiji kwenye Nyumba hiyo, kwa yule awezaye njia ya kuiendea. Na atakayekufuru, basi hakika Mwenyezi Mungu si mhitaji kwa walimwengu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 98, 'Sema: Enyi Watu wa Kitabu! Kwa nini mnazikufuru ishara za Mwenyezi Mungu, na ilhali Mwenyezi Mungu ni Shahidi kwa yote mnayoyatenda?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 99, 'Sema: Enyi Watu wa Kitabu! Kwa nini mnamzuilia Njia ya Mwenyezi Mungu aliyeamini mkiitakia ipotoke, ilhali nyinyi mnashuhudia? Na Mwenyezi Mungu si mwenye kughafilika mbali na mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 100, 'Enyi mlioamini! Mkilitii kundi katika wale waliopewa Kitabu, watawarudisha baada ya kuamini kwenu muwe makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 101, 'Na vipi mkufuru hali ya kuwa nyinyi mnasomewa Aya za Mwenyezi Mungu, na Mtume wake yuko miongoni mwenu? Na mwenye kushikamana na Mwenyezi Mungu, basi huyo hakika ameongolewa kwenye Njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 102, 'Enyi mlioamini! Mcheni Mwenyezi Mungu haki ya kumcha, wala kamwe msife isipokuwa nyinyi ni Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 103, 'Na shikamaneni kwa Kamba ya Mwenyezi Mungu nyote pamoja, wala msitengane. Na ikumbukeni neema ya Mwenyezi Mungu juu yenu: Mlipokuwa maadui nyinyi kwa nyinyi, naye akaziunganisha nyoyo zenu; na kwa neema yake mkawa ndugu. Na mlikuwa kwenye ukingo wa shimo la Moto, naye akawaokoa kutokana nao. Hivi ndivyo Mwenyezi Mungu anavyowabainishia Ishara zake ili mpate kuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 104, 'Na uwepo umma miongoni mwenu wanaoilingania heri, na wanaamrisha mema na wanakataza maovu. Na hao ndio waliofaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 105, 'Wala msiwe kama wale waliotengana na wakahitilafiana baada ya kufikiwa na hoja zilizo wazi. Na hao ndio wana adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 106, 'Siku ambapo nyuso zitakuwa nyeupe, na nyuso nyingine zikawa nyeusi. Basi, ama wale ambao nyuso zao zitakuwa nyeusi (wataambiwa): Je, mlikufuru baada ya kuamini kwenu? Basi ionjeni adhabu kwa sababu ya yale mliyokuwa mkikufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 107, 'Na ama wale ambao nyuso zao zitakuwa nyeupe, basi watakuwa katika rehema ya Mwenyezi Mungu. Wao humo watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 108, 'Hizi ni Aya za Mwenyezi Mungu tunazokusomea kwa haki. Na Mwenyezi Mungu hataki kuwadhulumu walimwengu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 109, 'Na ni cha Mwenyezi Mungu kilicho katika mbingu na kilicho katika ardhi, na kwa Mwenyezi Mungu ndiko mambo yote yatarejeshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 110, 'Nyinyi mmekuwa bora ya umma waliotolewa watu, kwa kuwa mnaamrisha mema na mnakataza maovu, na mnamuamini Mwenyezi Mungu. Na lau kuwa Watu wa Kitabu waliamini, ingelikuwa bora kwao. Miongoni mwao wako Waumini, lakini wengi wao ni wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 111, 'Maadui hawatawadhuru isipokuwa kwa maudhi tu. Na wakipigana nanyi, watawapa migongo, kisha hawatanusuriwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 112, 'Umepigwa udhalilifu juu yao popote wanapokutwa, isipokuwa kwa kamba ya Mwenyezi Mungu na kamba ya watu. Na walirudi na ghadhabu kutoka kwa Mwenyezi Mungu, na unyonge umepigwa juu yao. Hayo ni kwa sababu walikuwa wakizikufuru Ishara za Mwenyezi Mungu, na wakiwaua Manabii bila ya haki. Hayo ni kwa sababu waliasi na walikuwa wakiruka mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 113, 'Wote hao si wamoja. Miongoni mwa Watu wa Kitabu kuna watu waliosimama barabara, wanasoma Aya za Mwenyezi Mungu nyakati za usiku, nao wanasujudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 114, 'Wanamwamini Mwenyezi Mungu na Siku ya Mwisho, na wanaamrisha mema na wanakataza maovu, na wanakimbilia katika mambo ya heri. Na hao wako miongoni mwa walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 115, 'Na heri yoyote wanayoifanya, basi hawatanyimwa malipo yake. Na Mwenyezi Mungu anawajua wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 116, 'Hakika, wale waliokufuru, hazitawafaa kitu mali zao wala watoto wao mbele ya Mwenyezi Mungu. Na hao ndio watu wa Motoni. Wao watadumu humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 117, 'Mfano wa vile wanavyovitoa katika uhai wao wa duniani ni kama upepo ambao ndani yake kuna baridi ya barafu, ukalipiga shamba la kaumu waliozidhulumu nafsi zao, basi ukaliharibu. Na Mwenyezi Mungu hakuwadhulumu, bali wao wenyewe wanazidhulumu nafsi zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 118, 'Enyi mlioamini! Msiwafanye wandani wenu kuwa watu wasiokuwa katika nyinyi. Hawataacha kuwafikishia lolote la kuwadhuru. Wanapenda mngepata taabu. Imekwishadhihirika chuki yao kutoka katika midomo yao. Na yanayofichwa na vifua vyao ni makubwa zaidi.Tumekwishawabainishia Ishara ikiwa nyinyi mnatumia akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 119, 'Nyinyi ndio hawa mnawapenda watu hao, wala wao hawawapendi. Nanyi mnaviamini Vitabu vyote. Na wanapokutana nanyi husema: ''Tumeamini.'' Na wanapokuwa peke yao, wanawaumia vidole kwa chuki. Sema: Kufeni na chuki yenu! Hakika, Mwenyezi Mungu anayajua vyema yale yaliyo katika vifua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 120, 'Ikikuguzeni heri, inawawia vibaya. Na ikikupateni shari, wanaifurahia. Na nyinyi mkisubiri na mkamcha Mwenyezi Mungu, havitawadhuru kitu vitimbi vyao. Hakika, Mwenyezi Mungu ameyazingira yote wayatendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 121, 'Na pale ulipotoka asubuhi kwa ahali zako ili uwapange Waumini kwenye vituo kwa ajili ya vita. Na Mwenyezi Mungu ni Mwenye kusikia, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 122, 'Makundi mawili miongoni mwenu yalipoingiwa na woga kuwa watashindwa - na hali Mwenyezi Mungu ndiye Kipenzi Mlinzi wao. Na kwa Mwenyezi Mungu tu, na wategemee Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 123, 'Na Mwenyezi Mungu alishawanusuru huko Badri hali ya kuwa nyinyi ni wanyonge. Basi mcheni Mwenyezi Mungu ili mpate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 124, 'Ulipowaambia Waumini: Je, haiwatoshi kwamba Mola wenu Mlezi awasaidie kwa Malaika elfu tatu walioteremshwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 125, 'Kwani! Ikiwa mtavumilia na mkamcha Mungu, na hata maadui wakiwajia mara hii, basi hapo Mola wenu Mlezi atakusaidieni kwa Malaika elfu tano wenye alama maalumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 126, 'Na Mwenyezi Mungu hakufanya haya isipokuwa iwe ni bishara kwenu, na ili nyoyo zenu zipate kutua kwa hilo. Na nusura haitoki isipokuwa kwa Mwenyezi Mungu, Mwenye Nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 127, 'Ili akate sehemu katika wale waliokufuru, au awahizi; wapate kurejea nyuma hali ya kuwa wameambulia patupu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 128, 'Wewe huna chochote katika jambo hili. Ama atawakubalia toba au atawaadhibu, kwani wao hakika ni madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 129, 'Na ni vya Mwenyezi Mungu vyote vilivyo katika mbingu na vilivyo katika ardhi. Yeye humfutia dhambi amtakaye na humwadhibu amtakaye. Na Mwenyezi Mungu ni Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 130, 'Enyi mlioamini! Msile riba mkizidisha juu kwa juu. Na mcheni Mwenyezi Mungu ili mpate kufaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 131, 'Na ucheni Moto ambao umeandaliwa kwa ajili ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 132, 'Na mtiini Mwenyezi Mungu na Mtume ili mpate kurehemewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 133, 'Na kimbilieni kufutiwa dhambi kutoka kwa Mola wenu Mlezi, na Bustani ambayo upana wake ni mbingu na ardhi. Iliandaliwa kwa ajili ya wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 134, 'Wale ambao hutoa wanapokuwa katika nyakati nzuri na wanapokuwa katika dhiki, na wanajizuia ghadhabu, na ni wasamehevu kwa watu. Na Mwenyezi Mungu huwapenda wafanyao wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 135, 'Na wale ambao wanapofanya uchafu au wakazidhulumu nafsi zao, humtaja Mwenyezi Mungu; na hapo wanamwomba kufutiwa dhambi zao. Na ni nani anayefuta dhambi isipokuwa Mwenyezi Mungu? Na wala hawaendelei na waliyoyafanya hali ya kuwa wanajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 136, 'Hao malipo yao ni kufutiwa dhambi kutoka kwa Mola wao Mlezi, na Bustani zipitazo mito chini yake. Humo watadumu, na bora zaidi ni ujira wa watendao (wema).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 137, 'Tayari zimepita kabla yenu nyendo nyingi. Basi tembeeni katika ulimwengu na muangalie vipi ulikuwa mwisho wa wanaokanusha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 138, 'Huu ni ubainisho kwa watu wote, na ni uongofu, na mawaidha kwa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 139, 'Wala msilegee, wala msihuzunike, kwani nyinyi ndio wa juu ikiwa nyinyi ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 140, 'Ikiwa mtaguswa na majeraha, basi kwa hakika hao watu wengine walikwishapatwa na majeraha mfano wake. Na siku za namna hii tunawaletea watu kwa zamu, ili Mwenyezi Mungu awajue wale walioamini na awateue miongoni mwenu wanaokufa kwa ajili ya Dini (Mashahidi). Na Mwenyezi Mungu hawapendi madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 141, 'Na pia ili Mwenyezi Mungu awasafishe walioamini na awafutilie mbali makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 142, 'Je, mnadhani kwamba mtaingia Bustanini ilhali Mwenyezi Mungu hajawajua wale miongoni mwenu waliopigana Jihadi, na akawajua waliosubiri?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 143, 'Na nyinyi mlikuwa mkiyatamani mauti kabla hamjakutana nayo. Basi sasa mmekwishayaona na huku mnayatazama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 144, 'Na Muhammad si isipokuwa Mtume tu. Wamekwishapita kabla yake Mitume. Je, akifa au akiuawa, mtageuka mrudi kwa visigino vyenu? Na atakayegeuka akarudi kwa visigino vyake, basi huyo hatamdhuru kitu Mwenyezi Mungu. Na Mwenyezi Mungu atawalipa wanaoshukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 145, 'Na haikuwa kwa nafsi kufa isipokuwa kwa idhini ya Mwenyezi Mungu kama ilivyoandikiwa muda wake. Na mwenye kutaka malipo ya duniani, tutampa kwayo. Na mwenye kutaka malipo ya Akhera, tutampa kwayo. Na tutawalipa wenye kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 146, 'Na ni Manabii wangapi ambao Waumini wengi wenye ikhlasi walipigana vita pamoja nao! Na hawakulegea kwa yaliyowapata katika Njia ya Mwenyezi Mungu, wala hawakudhoofika wala hawakusalimu amri. Na Mwenyezi Mungu huwapenda wanaosubiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 147, 'Na haikuwa kauli yao isipokuwa walisema: Mola wetu Mlezi! Tufutie dhambi zetu na kupita kwetu kiasi katika mambo yetu, na isimamishe imara miguu yetu na utunusuru dhidi ya kaumu ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 148, 'Basi Mwenyezi Mungu akawapa malipo ya duniani na malipo bora ya Akhera. Na Mwenyezi Mungu anawapenda wafanyao mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 149, 'Enyi mlioamini! Ikiwa mtawatii wale waliokufuru, watawarudisha kwa visigino vyenu, na hapo mtageuka huku mmehasirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 150, 'Bali Mwenyezi Mungu ndiye Kipenzi Mlinzi wenu. Naye ndiye mbora wa wanaonusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 151, 'Tutatia hofu katika nyoyo za wale waliokufuru kwa vile walivyomshirikisha Mwenyezi Mungu na yale ambayo hakuyateremshia hoja yoyote. Na makazi yao ni Motoni. Na maovu mno ni maskani ya madhalimu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 152, 'Na Mwenyezi Mungu aliwatimilizia ahadi yake, vile mlivyokuwa mnawaua kwa idhini yake, mpaka mlipolegea na mkazozana katika amri hii, na mkaasi baada ya Yeye kuwaonyesha yale mnayoyapenda. Wapo miongoni mwenu wanaotaka dunia, na wapo miongoni mwenu wanaotaka Akhera. Kisha akawatenga nao (maadui) ili akujaribuni. Naye sasa amekwishawasamehe. Na Mwenyezi Mungu ni Mwenye fadhila juu ya Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 153, 'Pale mlipokuwa mkikimbia mbio, wala hamumsikilizi yeyote, na Mtume anawaita, yuko nyuma yenu. Basi Mwenyezi Mungu akawapa dhiki juu ya dhiki, ili msisikitike kwa yale yaliyowakosa wala kwa yale yaliyowapata. Na Mwenyezi Mungu ana habari za yote mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 154, 'Kisha baada ya dhiki aliwateremshia utulivu - usingizi ambao ulifunika kundi moja kati yenu. Na kundi jingine nafsi zao ziliwashughulisha hata wakamdhania Mwenyezi Mungu dhana isiyokuwa ya haki, dhana ya kijinga. Wakisema: Je, sisi tuna lolote katika jambo hili? Sema: Jambo hili lote ni la Mwenyezi Mungu. Wanaficha katika nafsi zao wasiyokudhihirishia. Wanasema: Lau ingelikuwa tuna lolote katika jambo hili, tusingeuliwa papa hapa. Sema: Hata mngelikuwa majumbani mwenu, basi wangelitoka wale walioandikiwa kufa, wakaenda mahali pao pa kuangukia wafe. (Haya ni hivyo) ili Mwenyezi Mungu ayajaribu yaliyo katika vifua vyenu, na asafishe yaliyo katika nyoyo zenu. Na Mwenyezi Mungu anayajua vyema yaliyomo vifuani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 155, 'Hakika, wale waliogeuka wakakimbia miongoni mwenu siku yalipokutana makundi mawili, hakika Shetani tu ndiye aliyewatelezesha kwa sababu ya baadhi ya makosa waliyoyafanya. Na Mwenyezi Mungu amekwishawasamehe. Hakika, Mwenyezi Mungu ni Mwenye kufuta dhambi, Mpole.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 156, 'Enyi mlioamini! Msiwe kama wale waliokufuru na wakawaambia ndugu zao wanaposafiri katika nchi au wanapokuwa vitani: ''Lau wangelikuwa nasi, wasingelikufa na wasingeliuwawa.'' Ili Mwenyezi Mungu afanye hayo kuwa ni majuto makubwa katika nyoyo zao. Na Mwenyezi Mungu huhuisha na hufisha. Na Mwenyezi Mungu ni Mwenye kuyaona vyema mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 157, 'Na mkiuliwa katika Njia ya Mwenyezi Mungu, au mkifa, hakika kufutiwa dhambi kutoka kwa Mwenyezi Mungu na rehema ni bora kuliko yale wanayoyakusanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 158, 'Na mkifa au mkiuliwa, basi ni kwa Mwenyezi Mungu ndiko mtakakokusanywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 159, 'Basi ni kwa sababu ya rehema itokayo kwa Mwenyezi Mungu ndiyo umekuwa laini kwao. Na lau ungelikuwa mkali, mwenye moyo mgumu, bila ya shaka wangelikukimbia. Basi wasamehe, na waombee kufutiwa dhambi, na shauriana nao katika mambo. Na ukishakata shauri, basi mtegemee Mwenyezi Mungu. Hakika, Mwenyezi Mungu huwapenda wanaomtegemea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 160, 'Ikiwa Mwenyezi Mungu atakunusuruni, basi hakuna wa kukushindeni. Na akikutupeni, basi ni nani huyo baada yake atakayekunusuruni? Na kwa Mwenyezi Mungu tu, basi na wategemee Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 161, 'Na haikuwa kwa Nabii yeyote kufanya hiyana. Na atakayefanya hiyana, atakuja Siku ya Kiyama na kile alichofanyia hiyana, kisha kila nafsi italipwa kwa iliyoyachuma kwa ukamilifu; wala hawatadhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 162, 'Je, aliyeyafuata ya kumridhisha Mwenyezi Mungi ni kama yule aliyerudi na ghadhabu ya Mwenyezi Mungu, na makazi yake yakawa Jahannamu? Napo ndipo pahali pabaya mno pa kurejea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 163, 'Hao wana vyeo mbalimbali kwa Mwenyezi Mungu. Na Mwenyezi Mungu ni Mwenye kuyaona yote wayatendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 164, 'Hakika, Mwenyezi Mungu amewafanyia wema mkubwa Waumini alipowaletea Mtume kutoka miongoni mwao wenyewe, anayewasomea Aya zake, na anawatakasa, na anawafunza Kitabu na hekima, ijapokuwa kabla ya hapo walikuwa katika upotovu ulio wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 165, 'Nyinyi mlipopatwa na msiba ambao nyinyi mmekwishawatia mara mbili mfano wake, mkasema: Umetoka wapi huu? Sema: Huo umetoka kwenu wenyewe. Hakika, Mwenyezi Mungu ni Mwenye uwezo juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 166, 'Na yale yaliyowapata siku yalipokutana makundi mawili, yalikuwa kwa idhini ya Mwenyezi Mungu, na ili awajue Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 167, 'Na ili awajue wale waliofanya unafiki, walipoambiwa: Njooni mpigane katika Njia ya Mwenyezi Mungu au lindeni. Wakasema: ''Tungelijua kuna kupigana vita, bila ya shaka tungeliwafuata.'' Wao siku ile walikuwa karibu zaidi na ukafiri kuliko Imani. Wanasema kwa midomo yao yasiyokuwa katika nyoyo zao. Na Mwenyezi Mungu anajua vyema wanayoyaficha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 168, 'Wale waliowaambia ndugu zao, na wao wenyewe walikuwa wamekaa: Lau wangelitutii, wasingeliuliwa. Sema: Ziondoleeni nafsi zenu mauti kama nyinyi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 169, 'Wala kabisa usiwadhanie wale waliouliwa katika Njia ya Mwenyezi Mungu kuwa ni wafu. Bali hao wa hai kwa Mola wao Mlezi wanaruzukiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 170, 'Wanafurahia yale aliyowapa Mwenyezi Mungu katika fadhila zake, na wanawapa bishara wale ambao bado hawajajiunga nao, walio nyuma yao, ya kwamba haitakuwa hofu juu yao wala hawatahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 171, 'Wanapata bishara ya neema kutoka kwa Mwenyezi Mungu na fadhila, na ya kwamba Mwenyezi Mungu hapotezi ujira wa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 172, 'Wale waliomwitikia Mwenyezi Mungu na Mtume baada ya kwishapatwa na majeraha. Kwa waliofanya wema miongoni mwao na wakamcha Mungu, utakuwa ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 173, 'Wale walioambiwa na watu: ''Hakika, kuna watu wamewakusanyikia, hivyo waogopeni!'' Hayo yakawazidishia Imani, na wakasema: Mwenyezi Mungu anatutosha, naye ni mbora zaidi wa kutegemewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 174, 'Basi wakarudi na neema kutoka kwa Mwenyezi Mungu na fadhila. Hakuna baya lililowagusa, na wakafuata yanayomridhisha Mwenyezi Mungu. Na Mwenyezi Mungu ni Mwenye fadhila kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 175, 'Hakika, huyo ni Shetani tu anawatia hofu marafiki zake. Basi msiwaogope. Bali niogopeni Mimi ikiwa nyinyi ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 176, 'Wala wasikuhuzunishe wale wanaoukimbilia ukafiri. Hakika, hao hawamdhuru kitu Mwenyezi Mungu. Mwenyezi Mungu anataka asiwawekee fungu lolote katika Akhera. Na wana adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 177, 'Hakika, wale walioununua ukafiri kwa Imani, hawatamdhuru kitu Mwenyezi Mungu. Na wana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 178, 'Wala wasidhani kabisa wale wanaokufuru kwamba muhula huu tunaowapa ni heri kwao. Hakika, tunawapa muhula ili wazidishe dhambi. Na wana adhabu ya kudunisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 179, 'Na hakuwa Mwenyezi Mungu ni mwenye kuwaacha Waumini katika hali mliyo nayo mpaka apambanue mbaya kutokana na mwema. Na wala hakuwa Mwenyezi Mungu ni mwenye kuwajulisha mambo ya ghaibu. Lakini Mwenyezi Mungu humteua katika Mitume wake amtakaye. Basi muaminini Mwenyezi Mungu na Mitume wake. Na mkiamini, na mkamcha Mungu, basi mtakuwa na ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 180, 'Wala wasidhani kabisa wale ambao wanafanya ubahili katika aliyowapa Mwenyezi Mungu katika fadhila zake kuwa ni heri kwao. Bali hiyo ni shari kwao. Watafungwa shingoni yale waliyoyafanyia ubahili Siku ya Kiyama. Na urithi wa mbingu na ardhi ni wa Mwenyezi Mungu. Na Mwenyezi Mungu ana habari za yote myatendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 181, 'Hakika Mwenyezi Mungu amekwishasikia kauli ya wale waliosema: ''Hakika, Mwenyezi Mungu ni fakiri, na sisi ni matajiri.'' Tutayaandika yale waliyoyasema, na pia kuwaua kwao Manabii bila ya haki, na tutawaambia Siku ya Kiyama: Onjeni adhabu ya kuunguza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 182, 'Hayo ni kwa sababu ya iliyotanguliza mikono yenu, na kwamba Mwenyezi Mungu si mwenye kuwadhulumu waja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 183, 'Waliosema: Hakika, Mwenyezi Mungu alituusia kwamba tusimwamini Mtume yeyote mpaka atujie na kafara inayoliwa na moto. Waambie: Walikujieni Mitume kabla yangu kwa hoja zilizo wazi na kwa hayo mnayosema. Basi kwa nini mliwaua ikiwa nyinyi ni wakweli?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 184, 'Na wakikukadhibisha, basi walikadhibishwa Mitume wengine kabla yako, waliokuja na hoja zilizo wazi, na Vitabu vyenye hekima, na Kitabu chenye nuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 185, 'Kila nafsi itaonja mauti. Na bila ya shaka mtapewa ujira wenu kamili Siku ya Kiyama. Na atakayeepushwa na Moto, na akaingizwa Bustanini, basi huyo hakika amefuzu. Na maisha ya dunia si kitu isipokuwa starehe ya udanganyifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 186, 'Bila shaka mtajaribiwa katika mali zenu, na nafsi zenu. Na bila ya shaka yoyote mtasikia udhia mwingi kutoka kwa wale waliopewa Kitabu kabla yenu na wale walioshirikisha. Na ikiwa mtasubiri na mkamcha Mungu, basi hakika hayo ni katika mambo ya kuazimia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 187, 'Na pale Mwenyezi Mungu alipochukua agano la wale waliopewa Kitabu kuwa: ''Bila shaka mtawabainishia watu, na wala hamtakificha.'' Lakini wakakitupa nyuma ya migongo yao, na wakanunua kwacho thamani ndogo. Basi ni kiovu mno hicho wanachokinunua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 188, 'Kamwe usiwadhanie wale wanaofurahia yale waliyoyafanya, na wakapenda kwamba wasifiwe kwa yale ambayo hawakuyatenda. Basi kamwe usiwadhanie kuwa watasalimika kutokana na adhabu. Na wana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 189, 'Na ni wa Mwenyezi Mungu ufalme wa mbingu na ardhi. Na Mwenyezi Mungu ni Mwenye uwezo juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 190, 'Hakika, katika kuumbwa mbingu na ardhi na kuhitilafiana usiku na mchana ziko Ishara kwa wenye akili ya hali ya juu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 191, 'Ambao humkumbuka Mwenyezi Mungu hali ya kuwa wamesimama, na wameketi, na kwenye mbavu zao. Na hutafakari katika kuumbwa kwa mbingu na ardhi, wakisema: Mola wetu Mlezi! Hukuviumba hivi bure. Subhanaka (umetakasika)! Basi tukinge kutokana na adhabu ya Moto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 192, 'Mola wetu Mlezi! Hakika, yule unayemwingiza Motoni, basi umemhizi. Na waliodhulumu hawana wasaidizi wowote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 193, 'Mola wetu Mlezi! Hakika, sisi tumemsikia mwitaji akiita kwenye Imani kwamba: ''Muaminini Mola wenu Mlezi''; kwa hivyo, tukaamini. Basi tufutie dhambi zetu, na utufunikie makosa yetu, na utufishe pamoja na walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 194, 'Mola wetu Mlezi! Na tupe yale uliyotuahidi kwa Mitume wako, wala usituhizi Siku ya Kiyama. Hakika, Wewe huvunji miadi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 195, 'Basi, Mola wao Mlezi akayakubali maombi yao akayajibu: Hakika Mimi, sipotezi matendo ya mfanya matendo yeyote miongoni mwenu, akiwa mwanamume au mwanamke, kwani ni nyinyi kwa nyinyi. Basi waliohama, na waliotolewa katika makazi yao, na wakaudhiwa katika Njia yangu, na wakapigana vita, na wakauliwa, kwa yakini Mimi nitawafunikia makosa yao; na kwa yakini nitawaingiza katika Mabustani yanayopita mito chini yake. Hizo ndizo thawabu zinazotoka kwa Mwenyezi Mungu. Na Mwenyezi Mungu kwake kuna thawabu njema kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 196, 'Kamwe kusiwadanganye kutangatanga kwa wale waliokufuru katika nchi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 197, 'Hiyo ni starehe ndogo. Kisha makazi yao yatakuwa Jahannamu. Na ni pahali pabaya mno pa kupumzikia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 198, 'Lakini wale waliomcha Mola wao Mlezi wana Mabustani yanayopita mito chini yake. Watadumu humo. Hayo ni makaribisho yao yatokayo kwa Mwenyezi Mungu. Na vilivyo kwa Mwenyezi Mungu ni bora kwa walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 199, 'Na hakika, miongoni mwa Watu wa Kitabu kuna wale wanaomwamini Mwenyezi Mungu na yaliyoteremshwa kwenu na yaliyoteremshwa kwao, wakimnyenyekea Mwenyezi Mungu. Hawanunui kwa Aya za Mwenyezi Mungu thamani ndogo. Hao wana ujira wao kwa Mola wao Mlezi. Hakika, Mwenyezi Mungu ni Mwepesi wa kuhesabu.[1]', '[1] Imani yao ilipokuwa ya ujumla (bila ya kutofautisha baina ya Manabii na Vitabu), na ya uhakika, ikawa ni ya manufaa. Kwa hivyo, ikawafanya kumnyenyekea Mwenyezi Mungu. Na katika ukamilifu wa kumnyenyekea kwao Mwenyezi Mungu ni kwamba, "hawanunui kwa Aya za Mwenyezi Mungu thamani ndogo." Kwa hivyo, hawaitangulizi dunia mbele ya dini kama walivyofanya watu wa upotovu, ambao wanaficha yale aliyoyateremsha Mwenyezi Mungu na kununua kwayo thamani ndogo. Na wakajua kwamba katika hasara kubwa zaidi ni kutosheka na kilicho duni badala ya dini.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 200, 'Enyi mlioamini! Subirini, na vumilieni, na kuweni macho, na mcheni Mwenyezi Mungu, ili mpate kufaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 1, 'Enyi watu! Mcheni Mola wenu Mlezi ambaye aliwaumba kutokana na nafsi moja, na akamuumba mkewe kutoka kwayo. Na akaeneza kutokana na wawili hao wanaume wengi na wanawake. Na mcheni Mwenyezi Mungu ambaye kwaye mnaomba, na jamaa zenu. Hakika, Mwenyezi Mungu ni Mwenye kuwaangalia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 2, 'Na wapeni mayatima mali zao. Wala msibadilishe kibaya kwa kizuri. Wala msile mali zao pamoja na mali zenu. Hakika, yote hayo ni dhambi kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 3, 'Na ikiwa mnaogopa kuwa hamtowafanyia mayatima uadilifu, basi oeni mnaowapenda katika wanawake, wawili au watatu au wanne. Na mkiogopa kuwa hamwezi kufanya uadilifu, basi mmoja tu, au wale ambao mikono yenu ya kulia imewamiliki. Kufanya hivi ndiko kutapelekea msidhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 4, 'Na wapeni wanawake mahari yao hali ya kuwa ni kipawa. Lakini wakiwatunuku kitu kwayo kwa roho safi yao, basi kileni kiwashuke kwa raha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 5, 'Wala msiwape wasio na akili mali zenu ambazo Mwenyezi Mungu amezifanya kuwa za kuwakimu. Na walisheni kutoka kwazo, na wavisheni, na waambieni kauli njema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 6, 'Na wajaribuni mayatima mpaka wanapofikia umri wa kuoa. Mkiona uamuzi wa busara ndani yao, basi wapeni mali zao. Wala msizile kwa kupitiliza na mapema mapema kwa kuwa watakuja kuwa watu wazima. Na yule ambaye ni tajiri, basi na ajizuilie. Na yule ambaye ni fakiri, basi na ale kwa wema. Na mtakapowapa mali zao, basi washuhudisheni mashahidi juu yao. Na Mwenyezi Mungu anatosha kuwa Mhasibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 7, 'Wanaume wana fungu katika yale wanayoyaacha wazazi na jamaa wa karibu. Na wanawake wanalo fungu katika yale waliyoyaacha wazazi na jamaa wa karibu. Kwa kile kilicho kidogo chake au kingi. Ni mafungu yaliyofaradhiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 8, 'Na wakihudhuria ugawi (wa mali ya urithi) jamaa wa karibu, na mayatima, na masikini, basi wapeni kwayo, na waambieni kauli njema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 9, 'Na wachelee wale ambao lau kuwa na wao wangeliacha nyuma yao dhuria wanyonge, wangeliwahofia. Basi nao wamche Mwenyezi Mungu, na waseme kauli iliyo sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 10, 'Hakika, wale wanaokula mali za mayatima kwa dhuluma, hakuna shaka yoyote wanakula moto matumboni mwao. Na wataingia Moto wenye mwako mkali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 11, 'Mwenyezi Mungu anawausia juu ya watoto wenu: Fungu la mwanamume ni kama fungu la wanawake wawili. Na wakiwa ni wanawake zaidi ya wawili, basi wana theluthi mbili za alichokiacha maiti. Lakini akiwa mtoto mwanamke ni mmoja, basi fungu lake ni nusu. Na kwa wazazi wake wawili, kila mmoja wao apate sudusi moja katika kile alichokiacha, ikiwa ana mtoto. Na ikiwa hana mtoto, na wazazi wake wawili wakawa wanamrithi, basi mama yake atapata theluthi moja. Na ikiwa ana ndugu, basi mama yake atapata sudusi. Haya ni baada ya kutolewa alichousia au kulipa deni. Baba zenu na watoto wenu, nyinyi hamjui ni nani kati yao aliyekaribu zaidi kwenu kwa manufaa. Hiyo ni sheria iliyotoka kwa Mwenyezi Mungu. Bila ya shaka, Mwenyezi Mungu ni Mwenye kujua, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 12, 'Nanyi mna nusu ya walichoacha wake zenu ikiwa hawana mtoto. Lakini ikiwa wana mtoto, basi mna robo katika kile walichokiacha, baada ya wasia waliyousia au kulipa deni. Na wake zenu wana robo katika kile mlichokiacha, ikiwa hamna mtoto. Lakini ikiwa mna mtoto, basi wana thumuni katika kile mlichokiacha, baada ya wasia mliousia au kulipa deni. Na ikiwa mwanamume au mwanamke anayerithiwa hana mtoto wala wazazi, lakini anaye kaka au dada, basi kila mmoja wao ana sudusi. Na wakiwa zaidi kuliko hivyo, basi watashirikiana katika theluthi, baada ya wasia iliyousiwa au kulipa deni, pasi na kuleta madhara. Huu ndio wasia uliotoka kwa Mwenyezi Mungu. Na Mwenyezi Mungu ni Mwenye kujua, Mstahamilivu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 13, 'Hiyo ni mipaka ya Mwenyezi Mungu. Na anayemtii Mwenyezi Mungu na Mtume wake, Yeye atamtia katika Bustani zipitazo mito chini yake, wadumu humo. Na huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 14, 'Na mwenye kumuasi Mwenyezi Mungu na Mtume wake, na akaipindukia mipaka yake, (Mwenyezi Mungu) atamtia Motoni adumu humo, naye ana adhabu ya kudhalilisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 15, 'Na wale ambao wanafanya uchafu miongoni mwa wanawake wenu, washuhudisheni watu wanne katika nyinyi. Watakaposhuhudia, basi wazuieni majumbani mpaka wafishwe na mauti au Mwenyezi Mungu awafanyie njia nyengine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 16, 'Na wawili kati yenu wafanyao hayo miongoni mwenu, waudhini. Na wakitubia wakatengenea, basi waacheni. Hakika, Mwenyezi Mungu ni Mwingi wa kupokea toba, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 17, 'Hakika, toba inayokubaliwa na Mwenyezi Mungu ni ya wale wafanyao uovu kwa ujinga, kisha wakatubia kwa haraka. Hao ndio Mwenyezi Mungu huwakubalia toba yao, na Mwenyezi Mungu ni mwenye kujua, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 18, 'Wala hawana toba wale wafanyao maovu mpaka yakamfikia mmoja wao mauti, kisha hapo akasema: Hakika, mimi sasa nimetubu. Wala wale wanaokufa hali ya kuwa wao ni makafiri. Hao tumewaandalia adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 19, 'Enyi mlioamini! Si halali kwenu kuwarithi wanawake kwa nguvu. Wala msiwadhikishe ili muwapokonye baadhi ya mlivyowapa, isipokuwa wakifanya uchafu ulio wazi. Na kaeni nao kwa wema. Na ikiwa mmewachukia, basi huenda mkakichukia kitu, na Mwenyezi Mungu ametia heri nyingi ndani yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 20, 'Na mkitaka kubadilisha mke pahali pa mke hali ya kuwa mmempa mmoja wao chungu ya mali, basi msichukue katika hiyo kitu chochote. Je, mnaichukua kwa dhuluma na kosa lililo wazi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 21, 'Na vipi mnaichukua ilhali mlikwishaingiliana nyinyi kwa nyinyi, nao (wanawake) walikwishachukua kutoka kwenu agano lililo madhubuti?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 22, 'Wala msiwaoe wale waliowaoa baba zenu, isipokuwa yale yaliyokwishapita. Hakika, huo ni uchafu, na uchukizo, na ni njia mbaya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 23, 'Mmeharamishiwa mama zenu, na binti zenu, na dada zenu, na shangazi zenu, na khaalati zenu, na binti wa kaka, na binti wa dada, na mama zenu waliowanyonyesha, na dada zenu kwa kunyonya, na mama wa wake zenu, na watoto wenu wa kambo walio katika ulinzi wenu waliozaliwa na wake zenu mliowaingilia. Ikiwa hamkuwaingilia, basi hakuna ubaya juu yenu. (Pia mmeharamishiwa) wake wa watoto wenu waliotoka katika migongo yenu. Na kuwaoa kwa pamoja dada wawili isipokuwa yale yaliyokwishapita. Hakika, Mwenyezi Mungu ni Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 24, 'Na wanawake wenye waume, isipokuwa waliomilikiwa na mikono yenu ya kulia. Ndiyo sheria ya Mwenyezi Mungu juu yenu. Na mmehalalishiwa wasiokuwa hao, mtafute kwa mali zenu kwa kuoa pasi na kuzini. Kama mnavyostarehe nao, basi wapeni mahari yao kwa kuwa ni wajibu. Wala hakuna ubaya juu yenu kwa mtakachokubaliana baada ya kutimiza wajibu. Hakika, Mwenyezi Mungu ni Mwenye kujua, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 25, 'Na asiyeweza kati yenu kupata mali ya kuolea wanawake wa kiungwana Waumini, basi na aoe katika vijakazi Waumini iliowamiliki mikono yenu ya kulia. Na Mwenyezi Mungu anajua vyema imani yenu. Nyinyi mmetokana wenyewe kwa wenyewe. Basi waoeni kwa idhini ya watu wao, na wapeni mahari yao kulingana na ada, wawe wanawake wema, si makahaba wala si mahawara. Na wanapoolewa kisha wakafanya uchafu, basi adhabu yao itakuwa ni nusu ya adhabu waliyowekewa waungwana. Hayo ni kwa yule miongoni mwenu anayeogopa kuingia katika zinaa. Na mkisubiri, ndiyo bora kwenu. Na Mwenyezi Mungu ni Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 26, 'Mwenyezi Mungu anataka kwamba awabainishie, na awaongoze nyendo za wale waliokuwa kabla yenu, na akubali toba zenu. Na Mwenyezi Mungu ni Mwenye kujua, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 27, 'Na Mwenyezi Mungu anataka kuwakubalia toba zenu, na wale wanaofuata matamanio wanataka kwamba mjipinde kujipinda kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 28, 'Na Mwenyezi Mungu anataka kwamba awahafifishie, na mwanadamu ameumbwa dhaifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 29, 'Enyi mlioamini! Msizile mali zenu baina yenu kwa batili, isipokuwa ikiwa ni biashara kwa kuridhiana wenyewe. Wala msijiue. Hakika, Mwenyezi Mungu kwenu ni Mrehemevu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 30, 'Na mwenye kufanya hayo kwa kupita mipaka na udhalimu, basi tutamwingiza motoni. Na hilo ni jepesi kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 31, 'Mkiyaepuka makubwa ya yale mnayokatazwa, tutawafutia makosa yenu madogo, na tutawaingiza pahali pa kuingia patukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 32, 'Wala msitamani alichowafadhilisha kwacho Mwenyezi Mungu baadhi yenu kuliko wengine. Wanaume wana fungu katika walivyovichuma, na wanawake wana fungu katika walivyovichuma. Na mwombeni Mwenyezi Mungu katika fadhila zake. Hakika, Mwenyezi Mungu ni Mwenye kujua kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 33, 'Na kila mmoja tumemfanyia warithi katika yale waliyoyaacha wazazi wawili na jamaa. Na wale mliofungamana nao kwa viapo, wapeni fungu lao. Hakika, Mwenyezi Mungu ni Shahidi juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 34, 'Wanaume ni wasimamizi imara wa wanawake, kwa yale aliyowafadhilisha kwayo Mwenyezi Mungu baadhi yao juu ya baadhi, na kwa yale wanayoyatoa katika mali zao. Basi wanawake wema ni wale wenye kutii na wanaojilinda hata katika siri kwa kuwa Mwenyezi Mungu ameamrisha wajilinde. Na wale mnaochelea kutoka kwao katika utiifu, waaidhini, na wahameni katika malazi, na wapigeni. Basi wakiwatii, msitafute njia yoyote dhidi yao. Hakika, Mwenyezi Mungu ndiye aliye juu, Mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 35, 'Na mkihofia kuwepo mfarakano baina ya wawili hao, basi mtumeni mpatanishi kutoka kwa jamaa za mume, na mpatanishi kutoka kwa jamaa za mke. Ikiwa wanataka kutengeneza mambo, Mwenyezi Mungu ataleta maafikiano kati yao. Hakika, Mwenyezi Mungu ni Mwenye kujua, Mwenye habari zote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 36, 'Na mwabuduni Mwenyezi Mungu wala msimshirikishe na chochote. Na wafanyieni wema wazazi wawili, na jamaa, na mayatima, na masikini, na jirani wa karibu, na jirani wa ubavuni, na mwenza wa ubavuni, na mwana njia, na wale iliowamiliki mikono yenu ya kulia. Hakika, Mwenyezi Mungu hampendi mwenye kiburi anayejifahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 37, 'Ambao wanafanya ubahili na wanaamrisha watu ubahili, na wanaficha yale aliyowapa Mwenyezi Mungu katika fadhila zake. Na tuliwaandalia makafiri adhabu ya kudunisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 38, 'Na ambao hutoa mali zao ili kujionyesha kwa watu, wala hawamwamini Mwenyezi Mungu wala Siku ya Mwisho. Na yule ambaye Shetani amekuwa ndiye mwenza wake, basi ana mwenza mbaya mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 39, 'Na ingeliwadhuru nini wao lau wangelimwamini Mwenyezi Mungu na Siku ya Mwisho, na wakatoa katika yale aliyowaruzuku Mwenyezi Mungu? Na Mwenyezi Mungu ni Mwenye kuwajua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 40, 'Hakika Mwenyezi Mungu hadhulumu hata uzito wa chembe moja. Na ikiwa ni jambo zuri, atalizidisha na atapeana kutoka kwake malipo makubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 41, 'Basi itakuwa vipi tutakapoleta shahidi kutoka kwa kila umma, na tukakuleta wewe kuwa shahidi dhidi ya hawa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 42, 'Siku hiyo watapenda wale waliokufuru na wakamuasi Mtume lau kuwa ardhi isawazishwe kwa wao. Wala hawataweza kumficha Mwenyezi Mungu neno lolote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 43, 'Enyi mlioamini! Msiikaribie Swala hali ya kuwa mmelewa, mpaka myajue mnayoyasema. Wala mkiwa na janaba (msikaribie swala wala msikiti), isipokuwa wanaopita njia (msikitini), mpaka muoge. Na mkiwa wagonjwa, au katika safari, au mmoja wenu akitoka chooni, au mkiwagusa (yaani kuwajamii) wanawake, na msipate maji, basi ukusudieni mchanga safi. Basi upangusieni kwenye nyuso zenu na mikono yenu. Hakika, Mwenyezi Mungu ni Msamehevu, Mwenye kufuta dhambi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 44, 'Je, hukuwaona wale waliopewa fungu katika Kitabu wanaununua upotovu na wanataka kwamba mpotee Njia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 45, 'Na Mwenyezi Mungu anawajua vyema maadui zenu. Na Mwenyezi Mungu anatosha kuwa Mlinzi, na Mwenyezi Mungu anatosha kuwa Mwenye kunusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 46, 'Miongoni mwa Mayahudi wamo wanaopotosha maneno kuyatoa pahali pake, na husema: ''Tumesikia na tumeasi, na sikia bila ya kusikizishwa.'' Na husema: "Raai''naa", kwa kuzipotoa ndimi zao na kuitukana Dini. Na lau kama wangelisema: "Tumesikia na tumetii, na usikie na "Undhurna (utuangalie)," ingelikuwa heri kwao na ya unyoofu zaidi. Lakini Mwenyezi Mungu aliwalaani kwa kufuru yao; basi hawaamini isipokuwa wachache tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 47, 'Enyi mliopewa Kitabu! Aminini tuliyoyateremsha yenye kusadikisha yale mliyo nayo, kabla hatujazifutilia mbali nyuso na kuzipeleka nyuma yake, au tuwalaani kama tulivyowalaani watu wa Sabato (Jumamosi). Na amri ya Mwenyezi Mungu ni lazima ifanyike.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 48, 'Hakika, Mwenyezi Mungu hafuti dhambi ya kushirikishwa, na hufuta dhambi ya yale yaliyo duni ya hilo kwa amtakaye. Na mwenye kumshirikisha Mwenyezi Mungu, basi hakika amezua dhambi kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 49, 'Je, hukuwaona wale wanaojitakasa nafsi zao? Bali Mwenyezi Mungu humtakasa amtakaye. Na hawatadhulumiwa hata kiasi cha kijiuzi kilicho ndani ya uwazi wa kokwa ya tende.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 50, 'Tazama namna wanavyomzulia uongo Mwenyezi Mungu, na haya yanatosha kuwa dhambi iliyo wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 51, 'Je, hukuwaona wale waliopewa fungu katika Kitabu? Wanaamini masanamu na Taghut! Na wanasema kuhusu wale waliokufuru kwamba hawa ndio walioongoka zaidi katika njia kuliko wale walioamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 52, 'Hao ndio Mwenyezi Mungu amewalaani. Na ambaye Mwenyezi Mungu amemlaani, basi hutapata wa kumnusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 53, 'Au wanalo fungu katika mamlaka? Basi hapo wasingewapa watu hata jicho la kokwa ya tende.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 54, 'Au wanawahusudu watu kwa yale aliyowapa Mwenyezi Mungu katika fadhila zake? Basi hakika tuliwapa ukoo wa Ibrahim Kitabu na hekima, na tukawapa ufalme mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 55, 'Basi miongoni mwao kuna yule aliyemwamini, na miongoni mwao kuna yule aliyemkufuru. Na Jahannamu inatosha kuwa ndio moto wenye mwako mkali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 56, 'Hakika wale waliozikufuru Ishara zetu, tutawaingiza motoni. Kila zitakapoiva ngozi zao, tutawabadilishia ngozi nyingine ili waionje hiyo adhabu. Hakika, Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 57, 'Na wale walioamini na wakatenda mema, tutawaingiza katika Bustani zipitazo mito chini yake wadumu humo milele. Humo watakuwa na wake waliotakaswa, na tutawaingiza katika vivuli vizuri kwelikweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 58, 'Hakika Mwenyezi Mungu anawaamrisha kwamba mzirudishe amana kwa wenyewe. Na mnapohukumu baina ya watu mhukumu kwa uadilifu. Hakika haya anayowawaidhi kwayo Mwenyezi Mungu ndiyo mazuri sana. Hakika Mwenyezi Mungu ndiye Mwenye kusikia, Mwenye kuona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 59, 'Enyi mlioamini! Mtiini Mwenyezi Mungu, na mtiini Mtume na wenye mamlaka katika nyinyi. Na mkizozana katika kitu, basi kirudisheni kwa Mwenyezi Mungu na Mtume, ikiwa mnamwamini Mwenyezi Mungu na Siku ya Mwisho. Hayo ndiyo bora zaidi na ndiyo yenye mwisho mwema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 60, 'Je, hukuwaona wale wanaodai kwamba wameamini yale yaliyoteremshwa kwako na yale yaliyoteremshwa kabla yako? Wanataka kupeleka kesi yao kwa Twaghut, na ilhali kwa hakika waliamrishwa kwamba wazikufuru! Na anataka Shetani kwamba awapoteze kupotea kwa mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 61, 'Na wanapoambiwa: ''Njooni kwa yale aliyoyateremsha Mwenyezi Mungu na kwa Mtume'', utawaona wanafiki wanaepukana na wewe kuepuka kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 62, 'Basi inakuwa vipi unapowasibu msiba kwa sababu ya yale iliyotanguliza mikono yao? Hapo, wanakujia wakiapa kwa Mwenyezi Mungu wakisema: Hatukutaka isipokuwa wema na mapatano.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 63, 'Hao ndio wale ambao Mwenyezi Mungu anayajua yaliyo katika nyoyo zao. Basi wapuuze, na uwawaidhi, na uwaambie maneno ya kuathiri na kuingia katika nafsi zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 64, 'Na hatukumtuma Mtume yeyote isipokuwa atiiwe kwa idhini ya Mwenyezi Mungu. Na lau pale walipozidhulumu nafsi zao, wangelikujia, wakamwomba Mwenyezi Mungu kuwafutia dhambi, na Mtume akawaombea kufutiwa dhambi, basi bila ya shaka wangelimkuta Mwenyezi Mungu ni Mwenye kupokea toba, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 65, 'Hapana! Ninaapa kwa Mola wako Mlezi! Hawataamini mpaka wakufanye wewe ndiye mwenye kuhukumu katika yale wanayohitilafiana, kisha wasipate uzito wowote katika nyoyo zao juu ya hukumu utakayotoa, na wajisalimishe kujusalimisha kukamilifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 66, 'Na lau kuwa tuliwaandikia kuwa: ''Jiueni, au tokeni majumbani mwenu'', wasingeliyafanya hayo isipokuwa wachache tu miongoni mwao. Na lau kama wangeliyafanya yale wanayowaidhiwa kwayo, ingelikuwa bora kwao na uthibitisho wa nguvu zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 67, 'Na hapo tungewapa malipo makubwa kutoka kwetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 68, 'Na tungeliwaongoa njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 69, 'Na mwenye kumtii Mwenyezi Mungu na Mtume, basi hao wako pamoja na wale aliowaneemesha Mwenyezi Mungu miongoni mwa Manabii, na Masiddiqi (Wakweli), na Mashahidi (watu waliouawa kwa ajili ya dini), na Watu wema. Na hao ndio wenza wazuri mno!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 70, 'Hiyo ndiyo fadhila itokayo kwa Mwenyezi Mungu. Na Mwenyezi Mungu anatosha kwamba ndiye Mwenye kujua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 71, 'Enyi mlioamini! Chukueni tahadhari yenu! Na mtoke haraka kwa vikosi au tokeni nyote kwa pamoja!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 72, 'Na hakika yupo kati yenu anayejikokota sana. Na ukikupateni msiba, husema: ''Hakika Mwenyezi Mungu amenineemesha kwa vile sikuwa nimehudhuria pamoja nao.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 73, 'Na ikikupateni fadhila kutoka kwa Mwenyezi Mungu, anasema, kana kwamba hapakuwa mapenzi baina yenu na yeye: ''Aa! Laiti ningelikuwa pamoja nao nikafuzu kufuzu kukubwa.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 74, 'Basi na wapigane katika Njia ya Mwenyezi Mungu wale ambao wanauza uhai wa dunia kwa Akhera. Na mwenye kupigana katika Njia ya Mwenyezi Mungu, kisha akauwawa au akashinda, basi tutampa ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 75, 'Na mna nini hampigani katika Njia ya Mwenyezi Mungu, na ya wale wanaoonewa miongoni mwa wanaume na wanawake na watoto, ambao husema: ''Mola wetu Mlezi! Tutoe katika mji huu ambao watu wake ni madhalimu, na tufanyie mlinzi kutoka kwako, na tufanyie wa kutunusuru kutoka kwako.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 76, 'Wale walioamini wanapigana vita katika Njia ya Mwenyezi Mungu, na wale waliokufuru wanapigana vita katika njia ya Twaghut. Basi piganeni na marafiki wa Shetani. Hakika, hila ya Shetani ni dhaifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 77, 'Je, hukuwaona wale walioambiwa: ‘Izuieni mikono yenu, na mshike Swala na mtoe Zaka.’ Na pindi walipoamrishwa kupigana, mara kundi moja miongoni mwao likawaogopa watu kama kumwogopa Mwenyezi Mungu, au kwa hofu kubwa zaidi. Na wakasema: ‘Mola wetu Mlezi! Kwa nini umetuamrisha kupigana? Laiti ungetuahirishia kiasi ya muda kidogo hivi!’ Sema: ‘Starehe ya dunia ni ndogo, na Akhera ni bora zaidi kwa mwenye kucha Mungu. Wala hamtadhulumiwa hata kijiuzi kilicho ndani ya uwazi wa kokwa ya tende.’', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 78, 'Popote mtakapokuwa, mauti yatawafikia, hata kama mtakuwa katika ngome zilizoimarishwa. Na likiwapata zuri, wanasema: Hili limetoka kwa Mwenyezi Mungu. Na likiwapata ovu, wanasema: Hili limetoka kwako wewe. Sema: Yote hayo yanatokana na Mwenyezi Mungu. Basi wana nini watu hawa hata hawakaribii kufahamu maneno?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 79, 'Yaliyokupata katika mazuri, basi ni kutokana na Mwenyezi Mungu. Na yaliyokusibu katika maovu, basi ni kutokana na nafsi yako. Nasi tumekutuma kwa watu uwe ni Mtume. Na Mwenyezi Mungu anatosha kuwa Shahidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 80, 'Mwenye kumtii Mtume, basi hakika amemtii Mwenyezi Mungu. Na mwenye kugeuka, basi Sisi hatukukutuma uwe mlinzi juu yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 81, 'Na wanasema: ''Tunatii.'' Lakini wanapotoka kule uliko, kundi moja miongoni mwao hupanga njama usiku kinyume na unayoyasema. Na Mwenyezi Mungu anayaandika yote hayo wanayoyapangia njama za usiku. Basi wape mgongo, na umtegemee Mwenyezi Mungu. Na Mwenyezi Mungu anatosha kuwa Mtegemewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 82, 'Kwani hawaizingatii hii Qur-ani? Na lau kuwa ingetoka kwa asiyekuwa Mwenyezi Mungu, bila ya shaka wangelikuta ndani yake hitilafu nyingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 83, 'Na linapowajia jambo lolote linalohusiana na amani au hofu, wao wanalitangaza. Na lau kuwa wangelipeleka hilo kwa Mtume na kwa wenye mamlaka kati yao, wale wanaochunguza miongoni mwao wangelijua. Na lau kuwa si fadhila ya Mwenyezi Mungu juu yenu na rehema yake, mngelimfuata Shetani isipokuwa wachache tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 84, 'Basi pigana vita katika Njia ya Mwenyezi Mungu. Hutwikwi isipokuwa nafsi yako tu. Na wahimize Waumini. Huenda Mwenyezi Mungu akayazuia mashambulizi ya wale waliokufuru. Na Mwenyezi Mungu ndiye Mkali zaidi wa kushambulia, na Mkali zaidi wa kutesa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 85, 'Mwenye kufanya uombezi mzuri, ana fungu lake katika hayo. Na mwenye kufanya uombezi mbaya, naye ana sehemu yake katika hayo. Na hakika Mwenyezi Mungu ni Mwenye uwezo na ujuzi juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 86, 'Na mnapoamkiwa kwa maamkizi yoyote, basi itikieni kwa yaliyo mazuri zaidi kuliko hayo, au yarejesheni hayo hayo. Hakika, Mwenyezi Mungu ni Mwenye kuhesabu kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 87, 'Mwenyezi Mungu, hapana mungu isipokuwa Yeye. Kwa yakini, atawakusanya Siku ya Kiyama. Halina shaka hilo. Na ni nani mkweli zaidi katika mazungumzo kuliko Mwenyezi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 88, 'Basi mna nini mmekuwa makundi mawili kuhusiana na (habari ya) wanafiki, na ilhali Mwenyezi Mungu amewageuza kwa sababu ya yale waliyoyachuma? Je, mnataka kumwongoa yule ambaye Mwenyezi Mungu amempoteza? Na mwenye kupotezwa na Mwenyezi Mungu, basi wewe hutapata njia yoyote kwa ajili yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 89, 'Wanapenda lau kuwa mtakufuru kama walivyokufuru wao, ili muwe sawasawa. Basi, msifanye marafiki wandani miongoni mwao mpaka wahame kwenda katika njia ya Mwenyezi Mungu. Na wakigeuka, basi wakamateni, na waueni popote mnapowapata. Wala msifanye miongoni mwao rafiki mwandani wala msaidizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 90, 'Isipokuwa wale waliofungamana na kaumu ambao kuna ahadi baina yenu na wao, au wanawajia hali ya kuwa vifua vyao vina dhiki juu ya kupigana nanyi, au kupigana na kaumu yao. Na lau angelipenda Mwenyezi Mungu, angeliwapa mamlaka juu yenu na wangelipigana nanyi. Kwa hivyo, wakijitenga nanyi, na wasipigane nanyi, na wakawaletea amani, basi Mwenyezi Mungu hakuwapa nyinyi njia dhidi yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 91, 'Mtawakuta wengine wanataka wapate salama kwenu na salama kwa watu wao. Kila wakirudishwa kwenye fitina, hudidimizwa humo. Na ikiwa hawajitengi nanyi, na wakawaletea salama, na wakaizuia mikono yao, basi wakamateni na waueni popote mnapowakuta. Na hao, tumewapa nyinyi hoja zilizo wazi juu yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 92, 'Na haiwi Muumini kumuua Muumini isipokuwa kwa kukosea. Na mwenye kumuua Muumini kwa kukosea, basi amkomboe mtumwa aliye Muumini, na atoe diya kuwapa jamaa zake maiti, isipokuwa waiache wenyewe kuwa ni sadaka. Na akiwa ni wa kutoka kwa kaumu ambao ni maadui zenu, ilhali yeye ni Muumini, basi ni kwa kumkomboa mtumwa aliye Muumini. Na akiwa ni miongoni wa kaumu ambao kuna agano baina yenu na wao, basi wapewe diya watu wake na akombolewe mtumwa Muumini. Na asiyepata, basi afunge miezi miwili mfululizo, iwe ni toba kwa Mwenyezi Mungu. Na Mwenyezi Mungu ni Mwenye kujua vyema, Mwenye hekima kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 93, 'Na mwenye kumuua Muumini kwa kukusudia, basi malipo yake ni Jahannamu humo atadumu, na Mwenyezi Mungu amemkasirikia, na amemlaani, na amemwandalia adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 94, 'Enyi mlioamini! Mnaposafiri katika Njia ya Mwenyezi Mungu, basi chunguzeni sawasawa, wala msimwambie anayewatolea salamu: ''Wewe si Muumini''; kwa kutaka manufaa ya maisha ya dunia hii, hali ya kuwa kwa Mwenyezi Mungu ndiko zipo ghanima nyingi. Hivyo ndivyo mlivyokuwa nyinyi zamani, na Mwenyezi Mungu akawaneemesha. Basi chunguzeni sawasawa. Hakika, Mwenyezi Mungu kwa yale mnayoyatenda anazo habari zote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 95, 'Hawawi sawa wanaokaa tu miongoni mwa Waumini wasiokuwa na dharura, na wale wanaopigana katika Njia ya Mwenyezi Mungu kwa mali zao na nafsi zao. Mwenyezi Mungu amewaboresha kwa daraja wale wanaopigana kwa mali zao na nafsi zao juu ya wale wanaokaa tu. Na kila mmoja wao Mwenyezi Mungu amemuahidi mazuri mno. Lakini Mwenyezi Mungu amewaboresha kwa ujira mkubwa wale wanaopigana kuliko wale wanaokaa tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 96, 'Hivyo ni vyeo kutoka kwake, na kufutiwa dhambi, na rehema. Na Mwenyezi Mungu ni Mwingi wa kufuta dhambi, na Mwenye kurehemu sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 97, 'Hakika, wale ambao Malaika wanawafisha hali ya kuwa wamezidhulumu nafsi zao, watawaambia: ''Mlikuwa katika nini?'' Watasema: ''Tulikuwa tumefanywa kuwa wanyoge katika ardhi.'' Watawaambia: ''Kwani ardhi ya Mwenyezi Mungu haikuwa na wasaa, mkahamie humo?'' Basi hao makazi yao ni Jahannam, nayo ni marejeo mabaya kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 98, 'Isipokuwa wale waliodhoofishwa miongoni mwa wanaume na wanawake na watoto wasioweza hila wala hawawezi kufuata sawasawa njia ya kuhama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 99, 'Basi hao, huenda Mwenyezi Mungu akawasamehe. Na Mwenyezi Mungu ni Mwingi wa kusamehe, Mwingi wa kufuta dhambi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 100, 'Na mwenye kuhama katika Njia ya Mwenyezi Mungu, atapata pengi duniani pa kukimbilia, na atapata wasaa. Na mwenye kutoka katika nyumba yake akihamia kwa Mwenyezi Mungu na Mtume wake, kisha yakamfika mauti, basi hakika umekwishawajibika ujira wake kwa Mwenyezi Mungu. Na Mwenyezi Mungu ndiye Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 101, 'Na mnaposafiri katika nchi, basi hakuna ubaya juu yenu mkifupisha katika Swala, iwapo mnachelea kwamba wale waliokufuru watawajaribu. Hakika, makafiri ni maadui zenu walio wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 102, 'Na unapokuwa miongoni mwao, na ukawasimamishia Swala, basi kundi moja miongoni mwao lisimame pamoja nawe, na wachukue silaha zao. Na watakapomaliza kusujudu, basi na wawe nyuma yenu, na lije kundi lingine ambalo halijaswali, na waswali pamoja nawe, nao wachukue hadhari yao na silaha zao. Walipenda wale waliokufuru lau mghafilike mbali na silaha zenu na mizigo yenu ili wawavamie mvamio wa mara moja. Wala hakuna ubaya juu yenu ikiwa mnaona udhia kwa sababu ya mvua au mkawa wagonjwa, mkaziweka silaha zenu. Na chukueni hadhari yenu. Hakika, Mwenyezi Mungu amewaandalia makafiri adhabu ya kudunisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 103, 'Na mkishamaliza Swala, basi mtajeni Mwenyezi Mungu hali ya kuwa mmesimama, na mkikaa, na kwa mbavu zenu. Na mtakapotulia, basi simamisheni Swala. Kwani, hakika Swala juu ya Waumini ni andiko lililowekewa nyakati maalumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 104, 'Wala msilegee katika kuwafukuzia kaumu hawa (ya maadui). Ikiwa mnaumia, basi nao pia wanaumia kama mnavyoumia. Nanyi mnataraji kwa Mwenyezi Mungu yale wasiyoyataraji. Na hakika, Mwenyezi Mungu ni Mwenye kujua, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 105, 'Hakika Sisi tumekuteremshia Kitabu hiki kwa haki ili uhukumu baina ya watu kwa kile alichokuonyesha Mwenyezi Mungu. Wala usiwe mtetezi wa mahaini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 106, 'Na omba Mwenyezi Mungu kufutiwa dhambi. Hakika, Mwenyezi Mungu ni Mwingi wa kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 107, 'Wala usiwabishanie wale wanaozihini nafsi zao. Hakika, Mwenyezi Mungu hampendi yule ambaye ni haini mkubwa, mwenye dhambi nyingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 108, 'Wanawaficha watu, wala hawamfichi Mwenyezi Mungu, naye yu pamoja nao pale wanapopanga njama usiku kwa maneno asiyoyapenda. Na Mwenyezi Mungu ameyazingira vyema wanayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 109, 'Hivi ni nyinyi hawa mmewabishania katika uhai huu wa duniani. Basi ni nani atakayewabishania dhidi ya Mwenyezi Mungu Siku ya Kiyama? Au ni nani atakuwa wakili wao wa kumtegemea?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 110, 'Na anayetenda uovu au akaidhulumu nafsi yake, kisha akaomba kufutiwa dhambi kwa Mwenyezi Mungu, atamkuta Mwenyezi Mungu ni Mwingi wa kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 111, 'Na mwenye kuchuma dhambi, basi ameichumia nafsi yake mwenyewe. Na Mwenyezi Mungu ni Mwenye kujua, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 112, 'Na mwenye kuchuma kosa au dhambi kisha akamsingizia asiye na kosa, basi amejitwika kashfa na dhambi iliyo wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 113, 'Na lau kuwa si fadhila ya Mwenyezi Mungu juu yako na rehema yake, kundi moja kati yao lingedhamiria kukupoteza. Na hawapotezi isipokuwa nafsi zao, wala hawawezi kukudhuru kwa lolote. Na Mwenyezi Mungu amekuteremshia Kitabu na hekima, na akakufundisha yale uliyokuwa huyajui. Na fadhila za Mwenyezi Mungu zilizo juu yako ni kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 114, 'Hakuna heri katika mengi ya wanayoshauriana kwa siri, isipokuwa kwa yule anayeamrisha kutoa sadaka, au kutenda mema, au kupatanisha baina ya watu. Na mwenye kufanya hayo kwa kutaka radhi za Mwenyezi Mungu, basi tutampa ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 115, 'Na mwenye kumpinga Mtume baada ya kubainikiwa na uongofu, na akafuata njia isiyokuwa ya Waumini, tutamuelekeza alikoelekea, na tutamuingiza katika Jahannam. Na hayo ni marejeo maovu zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 116, 'Hakika Mwenyezi Mungu hasamehi kushirikishwa na kitu. Lakini Yeye husamehe yasiyokuwa hayo kwa amtakaye. Na mwenye kumshirikisha Mwenyezi Mungu, basi kwa hakika amepotea upotovu wa mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 117, 'Wao hawawaombi badala yake Yeye isipokuwa vya kike, na wala hawamuombi isipokuwa Shetani aliyeasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 118, 'Mwenyezi Mungu amemlaani. Naye Shetani akasema: Hakika, nitachukua sehemu maalumu katika waja wako.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 119, 'Na hakika nitawapoteza, na nitawatia matamanio, na nitawaamrisha, basi hakika watakata masikio ya wanyama, na nitawaamrisha, basi hakika watabadili aliyoumba Mwenyezi Mungu. Na mwenye kumfanya Shetani kuwa ni rafiki mwandani badala ya Mwenyezi Mungu, basi hakika amehasiri hasara ya dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 120, 'Anawaahidi, na anawatia tamaa. Na Shetani hawaahidi isipokuwa udanganyifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 121, 'Hao makao yao ni Jahannam, na wala hawatapata makimbilio kutoka humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 122, 'Na wale walioamini na wakatenda mema, tutawaingiza katika Bustani zipitazo mito kwa chini yake. Watadumu humo milele. Ndiyo ahadi ya Mwenyezi Mungu iliyo kweli. Na ni nani mkweli zaidi wa kauli kuliko Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 123, 'Si kwa matamanio yenu, wala matamanio ya Watu wa Kitabu! Mwenye kufanya ubaya, atalipwa kwa huo, wala hatajipatia kando na Mwenyezi Mungu mlinzi wala wa kumnusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 124, 'Na mwenye kufanya katika mema, akiwa wa kiume au wa kike, naye ni Muumini, basi hao wataingia Peponi wala hawatadhulumiwa kiasi cha jicho la kokwa ya tende.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 125, 'Na ni nani aliye bora zaidi kwa dini kuliko yule aliyeusilimisha uso wake kwa Mwenyezi Mungu hali ya kuwa ni mwema, na akafuata mila ya Ibrahim mnyoofu? Na Mwenyezi Mungu alimfanya Ibrahim kuwa ni rafiki mwandani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 126, 'Na ni vya Mwenyezi Mungu tu vyote vilivyo katika mbingu na vilivyo katika dunia. Na Mwenyezi Mungu amekizingira kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 127, 'Na wanakuuliza fatwa kuhusiana na wanawake. Sema: Mwenyezi Mungu anawatolea fatwa juu yao, na yale mnayosomewa katika Kitabu hiki kuhusu mayatima wanawake ambao hamuwapi kile walichoandikiwa, na mnapenda kwamba muwaoe, na kuhusu wanyonge katika watoto, na kwamba muwasimamie mayatima kwa uadilifu. Na chochote mnachofanya katika heri, basi hakika Mwenyezi Mungu anaijua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 128, 'Na mwanamke akihofia kutupwa au kutojaliwa na mumewe, basi si vibaya kwao wakisikizana kwa suluhu. Na suluhu ni bora. Na nafsi zimewekewa machoni mwake tamaa na uchoyo. Na mkifanya wema na mkamcha Mungu, basi hakika Mwenyezi Mungu anazo habari za yote mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 129, 'Wala hamtaweza kufanya uadilifu baina ya wanawake, hata mkikakamia. Kwa hivyo, msiegemee moja kwa moja mkamwacha (mmoja wao) kama aliyetundikwa. Na mkisikizana na mkamcha Mungu, basi Mwenyezi Mungu ni Mwingi wa kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 130, 'Na wakitengana, Mwenyezi Mungu atamtosheleza kila mmoja kutoka katika wasaa wake. Na Mwenyezi Mungu ni Mwenye wasaa, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 131, 'Na ni vya Mwenyezi Mungu tu vyote vilivyo katika mbingu na vilivyo katika ardhi. Na kwa hakika tuliwausia wale waliopewa Kitabu kabla yenu, na nyinyi pia, kwamba mumche Mwenyezi Mungu. Na mkikufuru, basi ni vya Mwenyezi Mungu vilivyo katika mbingu na vilivyo katika ardhi. Na Mwenyezi Mungu ni Mwenye kujitosheleza, Msifiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 132, 'Na ni vya Mwenyezi Mungu vilivyo katika mbingu na vilivyo katika ardhi. Na Mwenyezi Mungu anatosha kuwa Mtegemewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 133, 'Akitaka, atawaondoa, enyi watu! Na awalete wengineo. Na Mwenyezi Mungu ni Muweza mno wa hayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 134, 'Mwenye kutaka malipo ya dunia, basi kwa Mwenyezi Mungu yapo malipo ya dunia na Akhera. Na Mwenyezi Mungu ni Mwenye kusikia vyema, Mwenye kuona yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 135, 'Enyi mlioamini! Kuweni wenye kusimama imara katika kufanya uadilifu, wenye kushuhudia kwa ajili ya Mwenyezi Mungu, hata kama ni juu ya nafsi zenu, au wazazi wawili na jamaa zenu. Akiwa tajiri au fukara, Mwenyezi Mungu ndiye anayewastahiki zaidi. Basi msifuate matamanio, mkaacha kufanya uadilifu. Na mkiupotoa au mkaupa mgongo, basi Mwenyezi Mungu anajua vyema mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 136, 'Enyi mlioamini! Muaminini Mwenyezi Mungu, na Mtume wake, na Kitabu alichokiteremsha juu ya Mtume wake, na Kitabu alichokiteremsha kabla yake. Na anayemkufuru Mwenyezi Mungu, na Malaika wake, na Vitabu vyake, na Mitume wake, na Siku ya Akhera, basi hakika amekwishapotea kupotea kwa mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 137, 'Hakika, wale walioamini, kisha wakakufuru, kisha wakaamini, kisha wakazidi ukafiri, Mwenyezi Mungu hakuwa wa kuwafutia dhambi wala wa kuwaongoa njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 138, 'Wabashirie wanafiki kwamba hakika wana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 139, 'Wale ambao huwafanya makafiri kuwa ndio marafiki wandani badala ya Waumini. Je, wanataka wapate kwao utukufu? Basi hakika utukufu wote ni wa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 140, 'Naye amekwishawateremshia katika Kitabu hiki ya kwamba mnaposikia Aya za Mwenyezi Mungu zinakanushwa na zinafanyiwa kejeli, basi msikae pamoja nao, mpaka waingie katika mazungumzo mengine. Hivyo mtakuwa nanyi mfano wao hao. Hakika Mwenyezi Mungu atawakusanya wanafiki na makafiri wote pamoja katika Jahannam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 141, 'Wale ambao wanawangojelea. Basi mkipata ushindi unaotoka kwa Mwenyezi Mungu, wao husema: "Kwani hatukuwa pamoja nanyi?" Na ikiwa ni sehemu ya makafiri kushinda, wao huwaambia: "Hatukuwa ni waweza wa kukushindeni, nasi tukawakinga kutokana na hawa Waumini?" Basi Mwenyezi Mungu atahukumu baina yenu Siku ya Kiyama, wala Mwenyezi Mungu hatawapa makafiri njia ya kuwashinda Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 142, 'Hakika wanafiki wanamhadaa Mwenyezi Mungu, na hali ni Yeye ndiye mwenye kuwahadaa wao. Na wanapoinuka kusali huinuka kwa unyong''onyo, wanajionyesha kwa watu tu, wala hawamdhukuru Mwenyezi Mungu ila kidogo tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 143, 'Wanayumbayumba baina ya huku na huko. Huku hawako na huko hawako. Na ambaye Mwenyezi Mungu amemwacha kupotea, kabisa hutompatia njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 144, 'Enyi mlioamini! Msiwafanye makafiri kuwa ndio wasaidizi wandani badala ya Waumini. Je, mnataka kumfanyia Mwenyezi Mungu hoja iliyo wazi juu yenu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 145, 'Hakika, wanafiki watakuwa katika tabaka la chini kabisa katika Moto, wala hutampata yeyote wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 146, 'Isipokuwa wale waliotubu, na wakatengenea, na wakashikamana na Mwenyezi Mungu, na wakamfanyia Mwenyezi Mungu peke yake Dini yao, basi hao wako pamoja na Waumini. Na Mwenyezi Mungu atawapa Waumini ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 147, 'Mwenyezi Mungu atafanyia nini kuwaadhibu ikiwa mtashukuru na mkaamini? Na Mwenyezi Mungu ndiye Mwenye kushukuru, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 148, 'Mwenyezi Mungu hapendi kutajwa mabaya hadharani isipokuwa kwa aliyedhulumiwa. Na Mwenyezi Mungu ni Mwenye kusikia, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 149, 'Mkidhihirisha wema au mkiuficha, au mkiyasamehe mabaya, basi hakika Mwenyezi Mungu ni Mwingi wa kusamehe, Muweza mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 150, 'Hakika, wale wanaomkufuru Mwenyezi Mungu na Mitume wake, na wanataka kufarikisha baina ya Mwenyezi Mungu na Mitume wake, na wanasema: ''Wengine tunawaamini na wengine tunawakufuru.'' Na wanataka kushika njia iliyo kati ya hayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 151, 'Hao ndio makafiri wa hakika. Na tumewaandalia makafiri adhabu ya kudunisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 152, 'Na wale waliomwamini Mwenyezi Mungu na Mitume wake, wala hawakumfarikisha yeyote kati yao, hao atawapa ujira wao. Na Mwenyezi Mungu ni Mwingi wa kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 153, 'Watu wa Kitabu wanakuuliza uwateremshie kitabu kutoka mbinguni. Na kwa hakika, walikwishamuuliza Musa makubwa zaidi ya hayo. Walisema: ''Tuonyeshe Mwenyezi Mungu wazi wazi.'' Kwa hivyo, radi ikawapiga kwa dhuluma yao hiyo. Kisha wakamchukua ndama kumwabudu, baada ya kwishawajia hoja zilizo wazi. Nasi tukasamehe hayo, na tukampa Musa hoja zilizo dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 154, 'Na tukanyanyua mlima juu yao kwa kufanya agano nao. Na tukawaambia: Ingieni mlangoni kwa kusujudu. Na tukawaambia: Msikiuke mipaka kuhusiana na Siku ya Sabato (Jumamosi). Na tukachukua kwao agano lililo madhubuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 155, 'Basi kwa sababu ya kuvunja kwao maagano yao, na kuzikufuru kwao ishara za Mwenyezi Mungu, na kuwauwa kwao Manabii bila ya haki, na kusema kwao: ''Nyoyo zetu zimefumbwa''; bali Mwenyezi Mungu ameziziba kwa kufuru zao, basi hawaamini isipokuwa kidogo tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 156, 'Na kwa kufuru zao na kusema kwao juu ya Maryam uongo mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 157, 'Na kusema kwao: ''Hakika, sisi tulimuua Masihi Isa, mwana wa Maryam, Mtume wa Mwenyezi Mungu.'' Nao hawakumuua wala hawakumsulubisha, bali walifananishiwa tu. Na hakika wale waliohitilafiana katika haya wamo katika shaka nayo. Wao hawana elimu yoyote nayo isipokuwa ni kufuata dhana tu. Wala hawakumuua kwa yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 158, 'Bali Mwenyezi Mungu alimwinua kwenda kwake, na hakika Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 159, 'Na hawi katika Watu wa Kitabu isipokuwa hakika atamuamini yeye kabla ya kufa kwake. Naye Siku ya Kiyama atakuwa shahidi juu yao.[1]', '[1] Hakuna hata mmoja katika Watu wa Kitabu (Mayahudi na Wakristo) ambaye hatamwamini Isa, amani iwe juu yake, baada ya kuteremka kwake katika mwisho wa zama na kabla ya kufa kwake Isa katika zama hizo. Na Siku ya Kiyama, Isa, amani iwe juu yake, atakuwa shahidi juu ya matendo yao. Yale yanayokubaliana na sheria na yale yanayopingana nayo.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 160, 'Basi kwa sababu ya dhuluma ya Mayahudi, tuliwaharamishia vitu vizuri walivyohalalishiwa. Na kwa sababu ya kuwazuilia kwao watu wengi na Njia ya Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 161, 'Na kuchukua kwao riba, na ilhali walikwishakatazwa hilo, na kula kwao mali ya watu kwa batili. Basi tumewaandalia makafiri katika wao adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 162, 'Lakini waliobobea katika elimu miongoni mwao, na Waumini, wanayaamini yale yaliyoteremshwa juu yako, na yale yaliyoteremshwa kabla yako. Na wanaosimamisha Sala, na wakatoa Zaka, na wanaomuamini Mwenyezi Mungu na Siku ya Mwisho, hao tutawapa malipo makubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 163, 'Hakika Sisi tumekufunulia ufunuo (wahyi) wewe kama tulivyomfunulia ufunuo (wahyi) Nuhu na Manabii waliokuwa baada yake. Na tulimfunulia ufunuo (wahyi) Ibrahim na Ismail na Is-hak na Yaakub na wanawe, na Isa na Ayub na Yunus na Harun na Suleiman, naye Daud tukampa Zaburi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 164, 'Na Mitume tuliokwishakukuhadithia kabla yake, na Mitume wengine ambao hatukukuhadithia. Na Mwenyezi Mungu alizungumza na Musa kwa maneno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 165, 'Mitume hao ni wabashiri na waonyaji, ili watu wasiwe na hoja juu ya Mwenyezi Mungu baada ya kuletewa Mitume. Na Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 166, 'Lakini Mwenyezi Mungu anayashuhudia yale aliyokuteremshia wewe. Aliyateremsha kwa elimu yake, na Malaika pia wanashuhudia. Na Mwenyezi Mungu anatosha kuwa shahidi wa sawasawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 167, 'Hakika, wale waliokufuru na wakaizuilia Njia ya Mwenyezi Mungu, hakika wamekwishapotea kupotea kwa mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 168, 'Hakika, wale waliokufuru na wakadhulumu, hakuwa Mwenyezi Mungu ni wa kuwafutia dhambi wala kuwaongoa njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 169, 'Isipokuwa njia ya Jahannam. Humo watadumu milele. Na hayo kwa Mwenyezi Mungu ni mepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 170, 'Enyi Watu! Hakika, amekwishawajia Mtume huyu kwa haki kutoka kwa Mola wenu Mlezi. Basi aminini, ndiyo heri kwenu. Na mkikufuru, basi hakika ni vya Mwenyezi Mungu vilivyo katika mbingu na ardhi. Na hakika Mwenyezi Mungu ni Mwenye kujua, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 171, 'Enyi Watu wa Kitabu! Msipite kiasi katika dini yenu, wala msiseme juu ya Mwenyezi Mungu isipokuwa haki tu. Hakika, Masihi Isa mwana wa Maryam ni Mtume wa Mwenyezi Mungu, na neno lake tu alilomfikishia Maryam, na ni roho iliyotoka kwake. Basi Muaminini Mwenyezi Mungu na Mitume wake. Wala msiseme: ''Utatu.'' Komekeni! Itakuwa heri kwenu. Hakika, Mwenyezi Mungu ni Mungu mmoja tu. Ametakasika Yeye na kuwa na mwana. Ni vyake Yeye vyote vilivyo katika mbingu na vilivyo katika ardhi. Na Mwenyezi Mungu anatosha kuwa Mtegemewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 172, 'Masihi hatajiinua juu zaidi kuwa mja wa Mwenyezi Mungu, wala Malaika waliowekwa karibu. Na mwenye kujiinua juu zaidi ya kumuabudu Yeye Mwenyezi Mungu na akafanya kiburi, basi atawakusanya wote kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 173, 'Basi wale walioamini na wakatenda mema, atawalipa ujira wao kikamilifu, na atawazidishia katika fadhila zake. Na ama wale waliojiinua juu, na wakafanya kiburi, basi atawaadhibu adhabu chungu. Wala hawatajipatia kando na Mwenyezi Mungu rafiki mwandani wala wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 174, 'Enyi watu! Hakika umekwishawafikia ushahidi kutoka kwa Mola wenu Mlezi, na tumewateremshia nuru iliyo wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 175, 'Ama wale waliomwamini Mwenyezi Mungu, na wakashikamana naye, basi atawaingiza katika rehema itokayo kwake, na fadhila, na atawaongoa kwenye Njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 176, 'Wanakuuliza hukumu ya kisheria, sema: Mwenyezi Mungu anawapa hukumu ya kisheria juu ya kalala (mtu aliyekufa bila ya kuacha mzazi wala mwana). Ikiwa mtu amekufa, naye hana mwana, lakini anaye dada, basi huyo atapata nusu ya alichokiacha. Naye (mwanamume) atamrithi (dada yake) ikiwa hana mwana. Na ikiwa wao ni madada wawili, basi watapata theluthi mbili za alichokiacha. Na wakiwa ndugu wanaume na wanawake, basi wa kiume atapata sehemu iliyo sawa na ya wa kike wawili. Mwenyezi Mungu anawabainishia ili msipotee. Na Mwenyezi Mungu ni Mwenye kujua kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 1, 'Enyi mlioamini! Timizeni mapatano. Mmehalalishiwa wanyama wa kufugwa, isipokuwa wale mnaosomewa. Lakini msihalalishe kuwinda hali ya kuwa mko katika Ihram. Hakika, Mwenyezi Mungu anahukumu apendavyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 2, 'Enyi mlioamini! Msivunje alama za Dini, za Mwenyezi Mungu wala mwezi mtakatifu, wala wanyama wanaopelekwa Makka kuchinjwa kama zawadi, wala wale wanaotiwa vigwe, wala wale wanaoelekea kuiendea Nyumba Takatifu, wakitafuta fadhila kutoka kwa Mola wao Mlezi na radhi. Na mkishatoka katika Ihram, basi windeni. Wala kuwachukia watu kwa kuwa waliwazuia kuufikia Msikiti mtakatifu kusiwapelekeeni kuwafanyia uadui. Na saidianeni katika wema na ucha Mungu. Wala msisaidiane katika dhambi na kupita mipaka. Na mcheni Mwenyezi Mungu. Hakika, Mwenyezi Mungu ni Mkali wa kuadhibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 3, 'Mmeharimishiwa nyamafu, na damu, na nyama ya nguruwe, na kile kilichochinjwa kwa ajili ya asiyekuwa Mwenyezi Mungu, na yule aliyekufa kwa kunyongeka koo. Na yule aliyekufa kwa kupigwa, na yule aliyekufa kwa kuanguka, na yule aliyekufa kwa kupigwa pembe, na yule aliyeliwa na mnyama, isipokuwa mkimdiriki kumchinja, na yule aliyechinjiwa masanamu, na ni haramu kupiga ramli. Hayo yote ni kupita mipaka. Leo wale waliokufuru wamekata tamaa na Dini yenu; basi msiwaogope, bali niogopeni Mimi. Leo nimewakamilishia Dini yenu, na nimewatimizia neema yangu, na nimeridhia Uislamu uwe ndiyo Dini yenu. Na mwenye kulazimishwa na njaa, bila ya kupendelea dhambi, basi hakika Mwenyezi Mungu ni Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 4, 'Wanakuuliza ni nini wamehalalishiwa? Sema: Mmehalalishiwa kila vilivyo vizuri na mlichowafundisha wanyama kukiwinda. Mnawafundisha alivyokufunzeni Mwenyezi Mungu. Basi kuleni katika kile walichowakamatia, na mkisomee jina la Mwenyezi Mungu. Na mcheni Mwenyezi Mungu; hakika Mwenyezi Mungu ni Mwepesi wa kuhesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 5, 'Leo mmehalalishiwa kila vilivyo vizuri. Na chakula cha wale waliopewa Kitabu ni halali kwenu, na chakula chenu ni halali kwao. Na pia wanawake wema miongoni mwa Waumini, na wanawake wema miongoni mwa wale waliopewa Kitabu kabla yenu, mtakapowapa mahari yao, mkafunga nao ndoa, bila ya kufanya zinaa na kila mtu, wala na mpenzi asiyekuwa katika ndoa. Na mwenye kuikufuru Imani, bila shaka matendo yake yameharibika, naye katika Akhera atakuwa miongoni mwa wenye hasara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 6, 'Enyi mlioamini! Mnaposimama kwa ajili ya Sala, basi osheni nyuso zenu, na mikono yenu mpaka vifundoni, na mpake katika vichwa vyenu, na osheni miguu yenu mpaka vifundoni. Na mkiwa na janaba, basi jisafisheni. Na mkiwa wagonjwa au katika safari, au mmoja wenu ametoka chooni au mmewagusa wanawake, na hamkupata maji, basi likusudieni vumbi lililo nzuri, na pakeni nyuso zenu na mikono yenu katika hilo. Hapendi Mwenyezi Mungu kuwatia katika uzito, bali anataka kuwatakasa na kutimiza neema yake juu yenu ili mpate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 7, 'Na kumbukeni neema ya Mwenyezi Mungu iliyo juu yenu, na agano lake alilofungamana nanyi, mliposema: Tumesikia na tumetii. Na mcheni Mwenyezi Mungu. Hakika Mwenyezi Mungu ni Mwenye kujua sana yaliyo ndani ya vifua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 8, 'Enyi mlioamini! Kuweni wasimamao madhubuti kwa ajili ya Mwenyezi Mungu, wenye kushuhudia kwa haki. Na wala kamwe kusiwapelekee kuchukiana na watu kutofanya uadilifu. Fanyeni uadilifu. Hivyo ndivyo kuwa karibu mno na ucha Mungu. Na mcheni Mwenyezi Mungu. Hakika Mwenyezi Mungu anazo habari za mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 9, 'Mwenyezi Mungu amewaahidi wale walioamini na wakatenda mema kwamba wana kufutiwa dhambi na malipo makubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 10, 'Na wale waliokufuru na wakazikadhibisha Ishara zetu, hao ndio watu wa Jahiim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 11, 'Enyi mlioamini! Kumbukeni neema za Mwenyezi Mungu juu yenu, walipotaka watu kuwanyooshea mikono yao, naye akaizuia mikono yao kuwafikia. Na mcheni Mwenyezi Mungu. Na kwa Mwenyezi Mungu, basi na wategemee Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 12, 'Na hakika Mwenyezi Mungu alichukua agano la Wana wa Israili. Na tukawatumia kutokana nao wakuu kumi na wawili. Na Mwenyezi Mungu akasema: ''Kwa yakini Mimi niko pamoja nanyi. Mkisimamisha Swala, na mkatoa Zaka, na mkawaamini Mitume wangu, na mkawasaidia, na mkamkopesha Mwenyezi Mungu mkopo mzuri, hakuna shaka nitawafutia mabaya yenu na nitawaingiza katika mabustani yapitayo mito chini yake. Kwa hivyo mwenye kukufuru miongoni mwenu baada ya hayo, basi bila ya shaka atakuwa amepotea njia iliyo sawa.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 13, 'Basi kwa sababu ya kuvunja kwao agano lao, tuliwalaani, na tukazifanya nyoyo zao kuwa ngumu. Wanayabadilisha maneno kutoka pahali pake, na walisahau sehemu katika yale waliyokumbushwa kwayo. Na huachi kutambua hiyana kutoka kwao, isipokuwa wachache miongoni mwao. Basi wasamehe na uwaache. Hakika Mwenyezi Mungu huwapenda wafanyao wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 14, 'Na kutoka kwa wale waliosema: ''Sisi ni Manasara'', tulichukua agano lao, lakini wakasahau sehemu katika yale waliyokumbushwa kwayo. Kwa hivyo tukaweka kati yao uadui na chuki mpaka Siku ya Qiyama. Na hapo Mwenyezi Mungu atawaambia yale waliyokuwa wakiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 15, 'Enyi Watu wa Kitabu! Hakika amekwishawajia Mtume wetu anayewabainishia mengi katika yale mliyokuwa mkiyaficha katika Kitabu, na anayaacha mengi. Bila shaka imekwishawajia kutoka kwa Mwenyezi Mungu nuru na Kitabu kilicho wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 16, 'Mwenyezi Mungu huwaongoa kwacho wenye kufuata radhi yake katika njia za salama, na huwatoa katika giza mbalimbali na kuwapeleka kwenye nuru kwa idhini yake, na huwaongoa kwenye Njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 17, 'Hakika wamekufuru wale waliosema: ''Hakika Mwenyezi Mungu ni Masihi mwana wa Maryam.'' Sema: Basi ni nani mwenye kumiliki chochote mbele ya Mwenyezi Mungu ikiwa Yeye angetaka kumwangamiza Masihi mwana wa Maryamu, na mama yake, na wote walio katika ardhi? Na ni wa Mwenyezi Mungu tu ufalme wa mbingu na ardhi na vilivyo kati yake. Huumba apendavyo. Na Mwenyezi Mungu anao uweza juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 18, 'Na Mayahudi na Wakristo walisema: Sisi ni wana wa Mwenyezi Mungu na vipenzi vyake. Sema: Basi kwa nini anawaadhibu kwa sababu ya dhambi zenu? Bali nyinyi ni wanadamu tu kama wale wengine aliowaumba. Humfutia dhambi amtakaye na humuadhibu amtakaye. Na ni wa Mwenyezi Mungu tu ufalme wa mbingu na ardhi na vilivyo kati yake. Na marejeo ni kwake Yeye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 19, 'Enyi Watu wa Kitabu! Bila ya shaka amewajia Mtume wetu akiwabainishia katika wakati usiokuwa na Mitume, ili msije mkasema: ''Hakutujia mbashiri wala mwonyaji.'' Basi kwa hakika amekwisha wajia mbashiri na mwonyaji. Na Mwenyezi Mungu ana uweza juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 20, 'Na pale Musa alipowaambia watu wake: Enyi watu wangu! Kumbukeni neema za Mwenyezi Mungu juu yenu, alipowateua Manabii kati yenu, na akawafanya watawala, na akawapa yale ambayo hakuwapa wowote katika walimwengu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 21, 'Enyi watu wangu! Ingieni katika nchi takatifu ambayo Mwenyezi Mungu amewaandikia. Wala msirudi nyuma, mkawa wenye kuhasirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 22, 'Wakasema: Ewe Musa! Hakika, huko wako watu majabari. Nasi kamwe hatutaingia humo mpaka wao watoke humo. Wakitoka humo, hapo hakika tutaingia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 23, 'Wanaume wawili miongoni mwa wale wanaohofu ambao Mwenyezi Mungu amewaneemesha, wakasema: Waingilieni mlangoni. Na mtakapowaingilia, basi kwa yakini nyinyi mtashinda. Na mtegemeeni Mwenyezi Mungu ikiwa nyinyi ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 24, 'Wakasema: Ewe Musa! Hakika Sisi kamwe hatutaingia humo maadamu wao wamo humo. Basi nenda wewe na Mola wako Mlezi mkapigane. Sisi hakika tutakaa papa hapa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 25, 'Akasema: Mola wangu Mlezi! Hakika mimi similiki isipokuwa nafsi yangu na kaka yangu. Basi tutenge na hawa watu wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 26, '(Mwenyezi Mungu) akasema: Basi hakika nchi hiyo wameharamishiwa, kwa muda wa miaka arobaini watakuwa wakitangatanga katika ardhi. Basi wewe usiwasikitikie watu wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 27, 'Na wasomee habari za wana wawili wa Adam kwa haki. Walipotoa mhanga, basi ukakubaliwa wa mmoja wao, na wa mwingine haukukubaliwa. Akasema (yule ambaye haukukubaliwa mhanga wake): Lazima nitakuua. Akasema huyo mwingine: Hakika Mwenyezi Mungu hupokea tu kutoka kwa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 28, 'Ukininyooshea mkono wako ili uniue, mimi sitakunyooshea mkono wangu ili nikuue. Hakika mimi namhofu Mwenyezi Mungu, Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 29, 'Hakika mimi ninataka ubebe dhambi zangu na dhambi zako, ili wewe uwe miongoni mwa watu wa Motoni. Na hayo ndiyo malipo ya madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 30, 'Basi nafsi yake ikampelekea kumuua kaka yake, na akamuua. Kwa hivyo akawa miongoni mwa waliohasirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 31, 'Hapo Mwenyezi Mungu akamtuma kunguru anayefukua katika ardhi ili amwonyeshe jinsi ya kuuzika mwili wa kaka yake. Akasema: ''Ole wangu! Nimeshindwa kuwa kama kunguru huyu nikauzika mwili wa kaka yangu?'' Basi akawa miongoni mwa wenye kujuta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 32, 'Kwa sababu ya hayo, tuliwaandikia Wana wa Israili ya kwamba mwenye kuiua nafsi bila ya nafsi hiyo kuiua nyingine, au kufanya uharibifu katika nchi, basi ni kama amewauwa watu wote. Na mwenye kuiweka hai, basi ni kama amewaweka hai watu wote. Na hakika walikwishawajia Mitume wetu na hoja zilizo wazi. Kisha hakika wengi katika wao baada ya haya wakawa waharibifu katika nchi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 33, 'Basi malipo ya wale wanaompiga vita Mwenyezi Mungu na Mtume wake, na wakawania kufanya uharibifu katika nchi, ni kuuawa, au kusulibiwa, au kukatwa mikono yao na miguu yao kwa mabadilisho, au kutolewa nchini. Hii ndiyo hizaya yao katika dunia; na katika Akhera wana adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 34, 'Isipokuwa wale waliotubia kabla hamjawatia nguvuni. Basi jueni kwamba hakika Mwenyezi Mungu ni Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 35, 'Enyi mlioamini! Mcheni Mwenyezi Mungu, na tafuteni njia ya kumfikia. Na pambaneni kwa juhudi katika njia yake ili mfaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 36, 'Hakika wale waliokufuru lau yangelikuwa yao ni yote yaliyo katika dunia, na mfano wake pamoja na hayo, ili watoe kwayo fidia ya kuepukana na adhabu ya Siku ya Kiyama, yasingelikubaliwa kutoka kwao; na wana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 37, 'Wanataka kwamba watoke Motoni, lakini hawawezi kutoka humo, na wana adhabu inayodumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 38, 'Na mwizi mwanamume na mwizi mwanamke, ikateni mikono yao, yakiwa ni malipo ya waliyoyachuma, ndiyo adhabu ya mfano itokayo kwa Mwenyezi Mungu. Na Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 39, 'Lakini mwenye kutubia baada ya dhuluma yake, na akatengenea, basi Mwenyezi Mungu ataipokea toba yake. Hakika Mwenyezi Mungu ni Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 40, 'Je, hukujua ya kwamba Mwenyezi Mungu anao ufalme wa mbingu na ardhi? Humuadhibu amtakaye, na humsamehe amtakaye. Na Mwenyezi Mungu ni Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 41, 'Ewe Mtume! Wasikuhuzunishe wale wanaokimbilia kukufuru, miongoni mwa wale waliosema kwa vinywa vyao, "Tumeamini", na hali nyoyo zao hazikuamini, na miongoni mwa Mayahudi, wanaosikiliza sana uongo, wanaowasikiliza sana kaumu wengine ambao hawajakujia. Wao huyabadilisha maneno baada ya kuwekwa pahali pake. Wanasema, "Mkipewa haya, basi yachukueni, na msipopewa haya, tahadharini." Na yule ambaye Mwenyezi Mungu anataka kumfitini, basi huwezi kuwa na uwezo kwa ajili yake mbele ya Mwenyezi Mungu. Hao ndio ambao Mwenyezi Mungu hataki kuzisafisha nyoyo zao. Wana hizaya katika dunia, na Akhera wana adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 42, 'Hao ni wasikilizaji sana wa uongo, na ni walaji mno vya haramu! Basi wakikujia, wahukumu baina yao au wapuuze. Na ukiwapuuza, basi wao hawatakudhuru kitu. Na ukiwahukumu, basi hukumu baina yao kwa uadilifu. Hakika Mwenyezi Mungu anawapenda waadilifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 43, 'Na vipi wanakufanya kuwa hakimu wao ilhali wanayo Taurati yenye hukumu za Mwenyezi Mungu ndani yake? Kisha baada ya hayo wanageuka. Na hao si Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 44, 'Hakika Sisi tuliiteremsha Taurati yenye uongofu na nuru, ambayo kwayo Manabii walionyenyekea Kiislamu, na wacha Mungu, na wanachuoni, waliwahukumu Mayahudi; kwa maana walikabidhiwa kukihifadhi Kitabu cha Mwenyezi Mungu, nao wakawa ni mashahidi juu yake. Basi msiwaogope watu, bali niogopeni Mimi. Wala msibadilishe Aya zangu kwa thamani chache. Na wasiohukumu kwa aliyoyateremsha Mwenyezi Mungu, basi hao ndio makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 45, 'Na humo tuliwaandikia ya kwamba nafsi kwa nafsi, na jicho kwa jicho, na pua kwa pua, na sikio kwa sikio, na jino kwa jino, na kwa majeraha ni kisasi. Lakini mwenye kuitoa kama sadaka, basi hiyo ni kafara kwake. Na yule asiyehukumu kwa yale aliyoyateremsha Mwenyezi Mungu, basi hao ndio madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 46, 'Na tukawafuatishia nyuma yao, Isa mwana wa Maryam akiyasadikisha yale yaliyokuwa kabla yake katika Taurati, na tukampa Injili iliyo na uongofu ndani yake, na ni nuru, na inayosadikisha yale yaliyokuwa kabla yake katika Taurati, na ni uwongofu na mawaidha kwa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 47, 'Basi na wahukumu Watu wa Injili kwa yale aliyoyateremsha Mwenyezi Mungu ndani yake. Na mwenye kutohukumu kwa yale aliyoyateremsha Mwenyezi Mungu, basi hao ndio waliopita mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 48, 'Na tulikuteremshia wewe Kitabu hiki kwa haki, kinachosadikisha yale yaliyokuwa kabla yake katika Vitabu na kuyalinda. Basi hukumu baina yao kwa yale aliyoyateremsha Mwenyezi Mungu, wala usifuate matamanio yao ukaacha haki iliyokujia. Kila mmoja katika nyinyi tumemwekea sheria yake na njia yake. Na lau kuwa Mwenyezi Mungu angelitaka, angeliwafanya nyote umma mmoja, lakini ni ili awajaribu kwa yale aliyowapa. Basi yakimbilieni mambo ya heri. Kwa Mwenyezi Mungu ndiyo marejeo yenu nyote, kisha atawaambia yale mliyokuwa mkihitilafiana juu yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 49, 'Na hukumu baina yao kwa yale aliyoyateremsha Mwenyezi Mungu, wala usifuate matamanio yao. Na watahadhari wasije wakakutia majaribu ukaacha baadhi ya yale aliyokuteremshia Mwenyezi Mungu. Na wakigeuka, basi jua kwamba hakika Mwenyezi Mungu anataka kuwasibu kwa baadhi ya dhambi zao. Na hakika wengi miongoni mwa watu ni wenye kupita mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 50, 'Je, wanataka hukumu za Kijahiliya? Na ni nani aliye mzuri zaidi katika kuhukumu kuliko Mwenyezi Mungu kwa watu wenye yakini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 51, 'Enyi mlioamini! Msiwafanye Mayahudi na Wakristo kuwa ni marafiki wandani. Wao kwa wao ni marafiki wandani. Na mwenye kuwafanya marafiki wandani miongoni mwenu, basi huyo hakika ni miongoni mwao. Hakika Mwenyezi Mungu hawaongoi kaumu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 52, 'Utawaona wale wenye maradhi katika nyoyo zao wanakimbilia kwao wakisema: ''Tunahofu kusibiwa na mabadiliko.'' Basi huenda Mwenyezi Mungu akaleta ushindi au jambo lingine kutoka kwake, na wakawa kwa yale waliyoyaficha katika nafsi zao ni wenye kujuta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 53, 'Na wale walioamini wanasema: Je, hawa ndio wale walioapa kwa Mwenyezi Mungu viapo vyao vikali mno kuwa wao hakika wako pamoja nanyi? Vitendo vyao viliharibika, na wakawa wamehasirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 54, 'Enyi mlioamini! Atakayeiacha Dini yake miongoni mwenu, basi Mwenyezi Mungu atakujaleta watu anaowapenda nao wanampenda, wanyenyekevu kwa Waumini na wenye nguvu juu ya makafiri, wanapigania Jihadi katika Njia ya Mwenyezi Mungu, wala hawaogopi lawama ya mwenye kulaumu. Hiyo ndiyo fadhila ya Mwenyezi Mungu, humpa amtakaye. Na Mwenyezi Mungu ni Mwenye wasaa, Mwenye kujua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 55, 'Hakika rafiki yenu mwandani ni Mwenyezi Mungu na Mtume wake na wale walioamini, ambao husimamisha Swala na hutoa Zaka, nao wanarukuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 56, 'Na mwenye kumfanya rafiki wandani Mwenyezi Mungu na Mtume wake na wale walioamini, basi hakika kundi la Mwenyezi Mungu ndio wenye kushinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 57, 'Enyi mlioamini! Msiwafanye marafiki wandani wale walioifanyia kejeli na mchezo Dini yenu miongoni mwa wale waliopewa Kitabu kabla yenu, na makafiri wengine. Na mcheni Mwenyezi Mungu ikiwa nyinyi ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 58, 'Na mnapoiadhinia Swala, wao wanaifanyia masihara na mchezo. Hayo ni kwa sababu wao ni kaumu wasiotumia akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 59, 'Sema: Enyi Watu wa Kitabu! Je, mnatuchukia isipokuwa tu kwamba tulimuamini Mwenyezi Mungu na yale tuliyoteremshiwa na yale yaliyoteremshwa kabla, na kwa kuwa wengi wenu ni wavukao mipaka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 60, 'Sema: Je, niwaambie lililo baya zaidi kuliko hilo katika malipo mbele ya Mwenyezi Mungu? Ni yule ambaye Mwenyezi Mungu alimlaani na akamkasirikia, na akawafanya miongoni mwao manyani na nguruwe, na wakamuabudu Shetani. Hao ndio wenye mahali pabaya zaidi na waliopotea zaidi njia iliyo sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 61, 'Na wanapowajia, husema, "Tumeamini." na ilhali hakika waliingia na ukafiri wao, nao wameshatoka nao pia. Na Mwenyezi Mungu ni Mwenye kujua vyema yale wanayoyaficha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 62, 'Na utawaona wengi miongoni mwao wanakimbilia kwenye dhambi, na kupita mipaka, na ulaji wao vya haramu. Ni maovu mno hayo wayatendayo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 63, 'Mbona hao wanachuoni wa Kiyahudi na makuhani wao hawawakatazi kusema kwao dhambi, na kula kwao vya haramu? Ni maovu mno hayo wayafanyayo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 64, 'Na Mayahudi walisema: ''Mkono wa Mwenyezi Mungu umefumba.'' Mikono yao ndiyo iliyofumba, na wamelaaniwa kwa sababu ya waliyoyasema. Bali mikono yake iko wazi. Hutoa apendavyo. Kwa yakini yaliyoteremshwa kwako kutoka kwa Mola wako Mlezi yatawazidishia wengi katika wao uasi na kufuru. Na Sisi tumewatilia uadui na chuki baina yao mpaka Siku ya Kiyama. Kila mara wanapowasha moto wa vita, Mwenyezi Mungu anauzima. Na wanajitahidi kuleta uharibifu katika ardhi. Na Mwenyezi Mungu hawapendi waharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 65, 'Na lau kuwa Watu wa Kitabu wangeliamini na wakamcha Mungu, hapana shaka tungeliwafutia mabaya yao, na tungeliwaingiza katika Mabustani yenye neema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 66, 'Na lau kuwa wangeliisimamisha Taurati na Injili na yote waliyoteremshiwa kutoka kwa Mola wao Mlezi, basi hakuna shaka wangelikula kutokea juu yao na kutokea chini ya miguu yao. Wapo watu miongoni mwao walio sawa, lakini wengi wao wanayoyafanya ni mabaya mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 67, 'Ewe Mtume! Fikisha uliyoteremshiwa kutoka kwa Mola wako Mlezi. Na ikiwa hufanyi, basi hutakuwa umefikisha ujumbe wake. Na Mwenyezi Mungu atakulinda kutokana na watu. Hakika Mwenyezi Mungu hawaongoi kaumu ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 68, 'Sema: ''Enyi Watu wa Kitabu! Hamna lenu jambo mpaka muisimamishe Taurati na Injili na yote mliyoteremshiwa kutoka kwa Mola wenu Mlezi.'' Na hakika uliyoteremshiwa wewe kutoka kwa Mola wako Mlezi yatawazidishia wengi katika wao uasi na ukafiri. Basi usiwasikitikie kaumu ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 69, 'Hakika wale walioamini, na Mayahudi, na Masabii na Wakristo, mwenye kumuamini Mwenyezi Mungu, na Siku ya Mwisho, na akatenda mema, basi hawatakuwa na hofu juu yao wala hawatahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 70, 'Hakika, tulichukua agano la Wana wa Israili, na tukawatumia Mitume. Kila alipowajia Mtume kwa yale zisiyoyapenda nafsi zao, wengine wao waliwakanusha, na wengine wao wakawaua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 71, 'Na wakadhani kuwa hapatakuwa majaribio; basi wakawa vipofu na viziwi. Kisha Mwenyezi Mungu akawapokelea toba zao. Kisha tena wengi katika wao wakawa vipofu na viziwi. Na Mwenyezi Mungu ni Mwenye kuyaona vyema hayo wayatendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 72, 'Hakika, wamekufuru wale waliosema: ''Hakika, Mwenyezi Mungu ni Masihi mwana wa Maryam!'' Na hali Masihi mwenyewe alisema: ''Enyi Wana wa Israili! Muabuduni Mwenyezi Mungu, Mola wangu Mlezi na Mola wenu Mlezi. Kwani, mwenye kumshirikisha Mwenyezi Mungu, hakika Mwenyezi Mungu amemharamishia Bustani ya mbinguni, na pahali pake ni Motoni. Na madhalimu hawatakuwa na wowote wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 73, 'Hakika, wamekufuru wale waliosema: ''Mwenyezi Mungu ni wa tatu wa watatu.'' Hali hakuna mungu isipokuwa Mungu Mmoja tu. Na ikiwa hawayaachi hayo wanayoyasema, basi kwa yakini itawagusa wale waliokufuru miongoni mwao adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 74, 'Je, hawatubii kwa Mwenyezi Mungu na wakamwomba awafutie dhambi? Na Mwenyezi Mungu ni Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 75, 'Masihi mwana wa Maryam si chochote isipokuwa ni Mtume. Wamekwishapita Mitume kabla yake. Na mama yake ni mwanamke mkweli. Wote wawili walikuwa wakila chakula. Angalia jinsi tunavyowabainishia Aya, kisha angalia vipi wanavyogeuzwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 76, 'Sema: Je, mnawaabudu, badala ya Mwenyezi Mungu, wale ambao hawawamilikii kudhuru wala kunufaisha? Na Mwenyezi Mungu ndiye Mwenye kusikia vyema, Mwenye kujua yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 77, 'Sema: Enyi Watu wa Kitabu! Msipite kiasi katika dini yenu bila ya haki. Wala msifuate matamanio ya kaumu waliokwishapotea tangu zamani, na wakawapoteza wengi, na wenyewe wakapotea njia iliyo sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 78, 'Walilaaniwa wale waliokufuru miongoni mwa Wana wa Israili kwa ulimi wa Daud na Isa mwana wa Maryamu. Hayo ni kwa sababu waliasi na wakawa wanapita mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 79, 'Walikuwa hawakatazani maovu waliyokuwa wakiyafanya. Hakika ni maovu mno waliyokuwa wakiyafanya!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 80, 'Utawaona wengi miongoni mwao wanafanya urafiki wandani na wale waliokufuru. Hakika ni maovu mno ziliyozitanguliza nafsi zao hata Mwenyezi Mungu akawakasirikia, nao watadumu katika adhabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 81, 'Na lau wangelikuwa wanamwamini Mwenyezi Mungu, na Nabii huyu, na yale yaliyoteremshwa kwake, wasingeliwafanya hao kuwa marafiki wandani. Lakini wengi miongoni mwao ni wapitao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 82, 'Hakika utawakuta walio na uadui mkubwa mno kuliko watu wote juu ya wale walioamini ni Mayahudi na wale walioshirikisha. Na hakika utawakuta wale wao walio karibu mno kwa mapenzi kwa wale walioamini ni wale waliosema: ''Hakika Sisi ni Manasara.'' Hayo ni kwa sababu wapo miongoni mwao makasisi na wamonaki, na kwamba wao hawafanyi kiburi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 83, 'Na wanaposikia yale yaliyoteremshwa kwa Mtume, utayaona macho yao yanamiminika machozi kwa sababu ya haki waliyoitambua. Wanasema: Mola wetu Mlezi! Tumeamini. Basi tuandike pamoja na wanaoshuhudia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 84, 'Na kwa nini tusimwamini Mwenyezi Mungu na haki iliyotujia, na hali tunatumai Mola wetu Mlezi atuingize pamoja na kaumu ya walio wema?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 85, 'Basi Mwenyezi Mungu akawalipa kwa yale waliyoyasema, Mabustani yapitayo mito kwa chini yake, wadumu humo. Na hayo ndiyo malipo ya wafanyao wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 86, 'Na wale waliokufuru na wakazikadhibisha ishara zetu, hao ndio watu wa Jahiim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 87, 'Enyi mlioamini! Msiviharamishe vizuri alivyowahalalishia Mwenyezi Mungu, wala msivuke mipaka. Hakika Mwenyezi Mungu hawapendi wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 88, 'Na kuleni katika vile alivyowaruzuku Mwenyezi Mungu, vya halali na vizuri. Na mcheni Mwenyezi Mungu ambaye nyinyi mnamwamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 89, 'Mwenyezi Mungu hawachukulii dhambi kwa viapo vyenu vya upuuzi, lakini atawachukulia dhambi kwa mnavyoapa kweli kweli kwa makusudio. Basi kafara yake ni kuwalisha masikini kumi kwa chakula cha wastani mnachowalisha ahali zenu, au kuwavisha, au kumkomboa mtumwa. Na asiyepata, basi na afunge siku tatu. Hii ndiyo kafara ya viapo vyenu mnapoapa. Na hifadhini viapo vyenu. Namna hivyo ndivyo Mwenyezi Mungu anawabainishia Aya zake ili mpate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 90, 'Enyi mlioamini! Bila ya shaka mvinyo, na kamari, na masanamu, na kupiga ramli, ni uchafu katika kazi ya Shetani. Basi jiepusheni navyo, ili mfaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 91, 'Hakika Shetani anataka kutia kati yenu uadui na chuki katika mvinyo na kamari, na awazuie kumkumbuka Mwenyezi Mungu na kuswali. Basi je, mmeacha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 92, 'Na mtiini Mwenyezi Mungu, na mtiini Mtume, na tahadharini. Na ikiwa mtageuka, basi hakika jueni ya kuwa juu ya Mtume wetu ni kufikisha ujumbe kuliko wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 93, 'Hakuna ubaya juu ya wale walioamini na wakatenda mema kwa vile walivyovila (zamani) maadamu wakimcha Mungu na wakiamini na wakitenda mema, kisha wakamcha Mungu, na wakaamini, kisha wakamcha Mungu na wakafanya mazuri. Na Mwenyezi Mungu huwapenda wafanyao mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 94, 'Enyi mlioamini! Hakika Mwenyezi Mungu atawajaribu kwa kitu kidogo katika mawindo inayowafikia mikono yenu na mikuki yenu, ili Mwenyezi Mungu amjue mwenye kumhofu katika ghaibu. Kwa hivyo, mwenye kuvuka mipaka baada ya hayo, basi ana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 95, 'Enyi mlioamini! Msiwaue mawindo hali ya kuwa mko katika Ihram (ya Hija au ''Umra). Na miongoni mwenu atakayemuua makusudi, basi malipo yake yatakuwa ni kuchinja kilicho sawa na alichokiua, katika mifugo, kama wanavyohukumu hivyo waadilifu wawili miongoni mwenu. Mnyama huyo apelekwe kwenye Al-Kaaba, au kutoa kafara kwa kuwalisha masikini; au badala ya hayo ni kufunga, ili aonje ubaya wa jambo lake hili. Mwenyezi Mungu amekwishayafuta yaliyopita. Lakini atakayefanya tena, Mwenyezi Mungu atamwadhibu vikali. Na Mwenyezi Mungu ndiye Mwenye nguvu, Mwenye kuadhibu vikali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 96, 'Mmehalalishiwa mawindo ya baharini na kuyala, kwa faida yenu na kwa wasafiri. Na mmeharimishiwa mawindo ya barani maadamu mko katika Ihram. Na mcheni Mwenyezi Mungu ambaye mtakusanywa kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 97, 'Mwenyezi Mungu ameifanya Al-Kaaba, hii Nyumba Tukufu, kuwa ya kuwakimu watu, na Miezi Mitakatifu, na dhabihu walioletwa Makka kama zawadi, na dhabihu waliofungwa vigwe. Hayo ni ili mjue ya kwamba hakika Mwenyezi Mungu anayajua yaliyo katika mbingu na yaliyo katika ardhi, na ya kwamba Mwenyezi Mungu ni Mwenye kujua kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 98, 'Jueni kwamba Mwenyezi Mungu ni Mkali wa kuadhibu, na ya kwamba Mwenyezi Mungu ni Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 99, 'Hakuna kilicho juu ya Mtume isipokuwa kufikisha ujumbe tu. Na Mwenyezi Mungu anajua mnachokidhihirisha na mnachokificha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 100, 'Sema: Haviwi sawa viovu na vizuri hata kama utapendezwa na wingi wa viovu. Basi mcheni Mwenyezi Mungu, enyi wenye akili ya hali ya juu, ili mfaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 101, 'Enyi mlioamini! Msiulize kuhusu mambo ambayo mkidhihirishiwa, yatawachukiza. Na mkiuliza juu yake wakati inateremshwa Qur-ani, mtadhihirishiwa hayo. Mwenyezi Mungu amesamehe hayo. Na Mwenyezi Mungu ni Mwenye kufuta dhambi, Mpole.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 102, 'Hakika, walikwishayauliza kaumu ya kabla yenu, kisha wakawa wenye kuyakufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 103, 'Mwenyezi Mungu hakuweka uharamu wowote juu ya "Bahira" wala "Saiba" wala "Wasila" wala "Hami". Lakini wale waliokufuru ndio humzulia uongo Mwenyezi Mungu, na wengi wao hawatumii akili.[1]', '[1] Al-Bahira ni ngamia jike ambaye sikio lake hukatwa ikiwa atazaa idadi fulani ya ngamia, na As-Sa’iba ni ngamia jike ambaye anapofika umri fulani huachiwa masanamu yao, na Al-Wasiila ni ngamia jike anayezaa jike baada ya jike mwingine, na Al-Haami ni ngamia dume ambaye watazalishwa idadi fulani ya ngamia kutoka kwa mgongo wake.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 104, 'Na wanapoambiwa: Njooni kwenye yale aliyoyateremsha Mwenyezi Mungu, na kwa Mtume, wanasema: Yanatutosha tuliyowakuta nayo baba zetu. Je, hata ikiwa baba zao walikuwa hawajui kitu wala hawakuongoka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 105, 'Enyi mlioamini! Kilicho lazima juu yenu ni nafsi zenu. Hatawadhuru mwenye kupotoka ikiwa nyinyi mmeongoka. Ni kwa Mwenyezi Mungu ndiyo marejeo yenu nyote; kisha atawaambia yale mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 106, 'Enyi mlioamini! Yanapomfikia mauti mmoja wenu na akataka kutoa wasia, basi wawepo mashahidi wawili miongoni mwenu ambao ni waadilifu. Na mnapokuwa katika safari, na msiba wa mauti ukawasibu, basi washuhudie wengineo wawili wasiokuwa katika nyinyi. Mtawazuia wawili hao baada ya Swala na waape kwa Mwenyezi Mungu, mkitilia shaka, wakisema: Hatutopokea thamani yoyote kwa haya hata kwa ajili ya jamaa; na wala hatutaficha ushahidi wa Mwenyezi Mungu; hakika hapo tutakuwa miongoni mwa wenye dhambi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 107, 'Lakini ikigundulika kuwa wawili hao wamestahiki dhambi, basi wawili wengineo kutokana na warithi wenye kudai haki washike mahali pa wale wa mwanzo. Nao waape kwa Mwenyezi Mungu wakisema: Hakika ushahidi wetu ni wa haki zaidi kuliko ushahidi wa wale. Na sisi hatujafanya dhambi; hakika hapo tutakuwa miongoni mwa madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 108, 'Hivyo ni karibu zaidi na kwamba watatoa ushahidi ulio sawa au wataogopa visije vikaletwa viapo vingine baada ya viapo vyao. Na mcheni Mwenyezi Mungu na msikie. Na Mwenyezi Mungu hawaongoi kaumu ya wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 109, 'Siku ambayo Mwenyezi Mungu atawakusanya Mitume na awaambie: Mlijibiwa nini? Watasema: Hatujui; hakika Wewe ndiwe Mwenye kujua yote yaliyofichikana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 110, 'Na pale Mwenyezi Mungu aliposema: Ewe Isa mwana wa Maryamu! Kumbuka neema yangu juu yako, na juu ya mama yako, nilipokutia nguvu kwa Roho Mtakatifu, ukazungumza na watu katika utoto na utu uzimani. Na nilivyokufunza kuandika na hekima na Taurati na Injili. Na ulipokuwa unatengeneza kutoka katika udongo kama umbo la ndege, kwa idhini yangu, kisha unapuliza ndani yake na linakuwa ndege kwa idhini yangu. Na ulipowaponya vipofu na wakoma kwa idhini yangu. Na ulipowafufua wafu kwa idhini yangu. Na nilipokukinga kutokana na Wana wa Israili ulipowajia na hoja zilizo wazi, na wakasema wale waliokufuru miongoni mwao: Haya si lolote isipokuwa uchawi ulio wazi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 111, 'Na nilipowafunulia ufunuo (wahyi) Wanafunzi (wako) kwamba: "Niaminini Mimi na Mtume wangu." Wakasema: "Tumeamini, na shuhudia kuwa sisi hakika ni Waislamu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 112, 'Wanafunzi (wako) waliposema: Ewe Isa mwana wa Maryam! Je, Mola wako Mlezi anaweza kututeremshia meza yenye chakula kutoka mbinguni? Akasema: Mcheni Mwenyezi Mungu ikiwa nyinyi ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 113, 'Wakasema: Tunataka kula kwayo, na nyoyo zetu zitue, na tujue kwamba umetuambia ukweli, na tuwe miongoni mwa wanaoshuhudia juu ya hilo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 114, 'Akasema Isa mwana wa Maryam: Ewe Mwenyezi Mungu, Mola Mlezi wetu! Tuteremshie meza yenye chakula kutoka mbinguni ili kiwe kwetu Sikukuu kwa ajili ya wa mwanzo wetu na wa mwisho wetu, na kiwe ni ishara itokayo kwako. Basi turuzuku, kwani Wewe ndiye mbora zaidi wa wanaoruzuku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 115, 'Mwenyezi Mungu akasema: Hakika Mimi nitawateremshia hicho. Lakini yeyote katika nyinyi atakayekufuru baadaye, basi hakika Mimi nitamuadhibu adhabu nisiyomuadhibu yeyote katika walimwengu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 116, 'Na pale Mwenyezi Mungu aliposema: Ewe Isa mwana wa Maryamu! Je, wewe ndiye uliwaambia watu: Nifanyeni mimi na mama yangu kuwa ni miungu wawili badala ya Mwenyezi Mungu? (Isa) akasema: Subhanaka (Wewe umetakasika)! Hainifailii mimi kusema ambayo si haki yangu. Ikiwa nilisema, basi bila ya shaka umekwishayajua. Wewe unayajua yaliyo ndani ya nafsi yangu, lakini mimi siyajui yaliyo katika nafsi yako. Hakika Wewe ndiye Mwenye kujua vyema yale yaliyofichikana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 117, 'Sikuwaambia lolote isipokuwa yale uliyoniamrisha, kwamba: Muabuduni Allah (Mwenyezi Mungu), Mola wangu Mlezi na Mola wenu Mlezi. Na mimi nilikuwa shahidi juu yao nilipokuwa miongoni mwao. Na uliponifisha, ukawa Wewe ndiye Muangalizi juu yao. Na Wewe ni shahidi juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 118, 'Ukiwaadhibu, basi hao ni waja wako. Na ukiwafutia dhambi, basi Wewe ndiye Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 119, 'Mwenyezi Mungu akasema: Hii ndiyo Siku ambayo wasemao ukweli utawafaa ukweli wao. Wao wana Mabustani yapitayo mito chini yake. Humo watadumu milele. Mwenyezi Mungu amewawia radhi, nao walimridhia. Huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 120, 'Ni wa Mwenyezi Mungu ufalme wa mbingu na ardhi na vilivyo ndani yake. Naye ni Muweza mno wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 1, 'Sifa njema zote ni za Mwenyezi Mungu, ambaye aliumba mbingu na ardhi, na akafanya giza mbalimbali na nuru. Kisha wale waliokufuru wanawafanya wengine kuwa sawa na Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 2, 'Yeye ndiye aliyewaumba kutokana na udongo, kisha akawahukumia muda, na muda maalumu uko kwake tu. Kisha nyinyi mnatia shaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 3, 'Na Yeye ndiye Mwenyezi Mungu katika mbingu na katika ardhi. Anajua ya siri yenu na ya dhahiri yenu. Na anajua mnayoyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 4, 'Na haiwajii ishara miongoni mwa ishara za Mola wao Mlezi isipokuwa walikuwa wakiipa mgongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 5, 'Basi hakika walikwishaikadhibisha haki ilipowajia. Kwa hivyo, zitawajia habari za yale waliyokuwa wakiyafanyia mzaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 6, 'Je, hawakuona ni vizazi vingapi tulivyoviangamiza kabla yao? Tuliwaimarisha katika dunia namna ambavyo hatukuwaimarisha nyinyi; na tukawatumia mvua nyingi na tukaifanya mito inapita kwa chini yao. Mwishowe tukawaangamiza kwa madhambi yao; na tukaanzisha baada yao kizazi kingine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 7, 'Na lau tungelikuteremshia kitabu cha karatasi, wakakigusa kwa mikono yao, wangelisema wale waliokufuru: Haya si chochote isipokuwa ni uchawi ulio wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 8, 'Na walisema, "Mbona hakuteremshiwa Malaika?" Na kama tungelimteremsha Malaika, basi bila ya shaka ingeshahukumiwa amri, kisha wasingelipewa muhula.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 9, 'Na kama tungelimfanya Malaika, bila ya shaka tungelimfanya kuwa mwanamume, na tungeliwatilia matatizo yale wanayoyatatiza wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 10, 'Na hakika walifanyiwa mzaha Mitume waliokuwa kabla yako, lakini wale waliowafanyia mzaha yakawafika yale yale waliyokuwa wakiyafanyia mzaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 11, 'Sema: Tembeeni katika ardhi, kisha mtazame vipi ulikuwa mwisho wa wanaokadhibisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 12, 'Sema: Ni vya nani vilivyo katika mbingu na katika ardhi? Sema: Ni vya Mwenyezi Mungu. Yeye ameiandika rehema juu ya nafsi yake. Hakika atawakusanya hadi Siku ya Kiyama isiyokuwa na shaka. Wale waliojihasiri nafsi zao, wao hawaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 13, 'Na ni vyake vilivyotulia katika usiku na mchana. Naye ndiye Mwenye kusikia, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 14, 'Sema: Je, nimfanye rafiki mwandani asiyekuwa Mwenyezi Mungu, ambaye ndiye Muumba mwanzilishi wa mbingu na ardhi, naye ndiye anayelisha wala halishwi? Sema: Hakika Mimi nimeamrishwa kwamba niwe wa kwanza wa wenye kusilimu. Na wala kabisa usiwe miongoni wa washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 15, 'Sema: Hakika Mimi ninahofu nikimuasi Mola wangu Mlezi, adhabu ya Siku kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 16, 'Mwenye kuepushwa mbali nayo Siku hiyo, basi hakika atakuwa amemrehemu. Na huko ndiko kufuzu kuliko wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 17, 'Na ikiwa Mwenyezi Mungu atakugusa kwa madhara, basi hapana wa kuyaondoa isipokuwa Yeye. Na ikiwa atakugusa kwa heri, basi Yeye ndiye Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 18, 'Naye ndiye Mwenye nguvu za ushindi juu ya waja wake, naye ndiye Mwenye hekima, Mwenye habari zote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 19, 'Sema: Ni kitu gani ushahidi wake ndio mkubwa kabisa? Sema: Mwenyezi Mungu. Yeye ndiye shahidi baina yangu na nyinyi. Na imefunuliwa kwangu Qur-ani hii ili kwayo niwaonye nyinyi na kila inayemfikia. Ati kweli nyinyi mnashuhudia kuwa pamoja na Mwenyezi Mungu wapo miungu wengine? Sema: Mimi sishuhudii hayo. Sema: Hakika Yeye ni Mungu mmoja tu, nami hakika niko mbali na mnaowashirikisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 20, 'Wale tuliowapa Kitabu wanakijua kama wanavyowajua watoto wao. Wale waliozihasiri nafsi zao, basi wao hawaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 21, 'Na nani dhalimu zaidi kuliko anayemzulia uongo Mwenyezi Mungu, au akazikadhibisha Ishara zake? Hakika madhalimu hawafaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 22, 'Siku tutakapowakusanya wote pamoja, kisha tuwaambie wale walioshirikisha: Wako wapi washirikishwa wenu mliokuwa mkidai?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 23, 'Kisha hautakuwa udhuru wao isipokuwa ni kusema: Wallahi (Tunaapa kwa Mwenyezi Mungu), Mola wetu Mlezi! Hatukuwa washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 24, 'Tazama jinsi wanavyosema uongo juu ya nafsi zao wenyewe. Na yamewapotea waliyokuwa wakiyazua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 25, 'Na miongoni mwao kuna wale wanaokusikiliza; na tumezitia pazia kwenye nyoyo zao wasije kuyafahamu. Na upo uziwi katika masikio yao, na wakiona kila Ishara, hawaiamini. Mpaka wakikujia kwa kujadiliana nawe, wanasema wale waliokufuru: Hizi si chochote isipokuwa hadithi za watu wa kale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 26, 'Nao huwazuia watu hayo, na wao wenyewe wanajitenga nayo. Nao hawaangamizi isipokuwa nafsi zao tu, wala wao hawatambui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 27, 'Na lau ungeona waliposimamishwa kwenye Moto, wakawa wanasema: Laiti tungelirudishwa, wala tusizikadhibishe tena Ishara za Mola wetu Mlezi, na tuwe miongoni mwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 28, 'Bali yamewadhihirikia yale waliyokuwa wakiyaficha zamani. Na lau wangelirudishwa, bila ya shaka wangeliyarejea yale yale waliyokatazwa. Na hakika wao ni waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 29, 'Na walisema: Hakuna mengine isipokuwa maisha yetu haya ya duniani, wala sisi hatutafufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 30, 'Na lau utaona walivyosimamishwa mbele ya Mola wao Mlezi, akasema, "Je, huu si uhakika?" Na wao wakasema, "Ndiyo? Tunaapa kwa Mola wetu Mlezi (ni uhakika)." Yeye akasema: Basi onjeni adhabu kwa sababu ya vile mlivyokuwa mnakufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 31, 'Hakika wamehasirika wale waliokadhibisha kukutana na Mwenyezi Mungu, mpaka ilipowajia Saa kwa ghafla, wakasema: ''Ee majuto yetu kwa yale tuliyoyapuuza!'' Nao watabeba mizigo yao juu ya migongo yao. Tazama! Ni maovu mno hayo wanayoyabeba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 32, 'Na maisha ya dunia si chochote isipokuwa ni mchezo na pumbao tu. Na hakika Nyumba ya Akhera ni bora zaidi kwa wale wanaomcha Mwenyezi Mungu. Basi, je, hamtumii akili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 33, 'Hakika tunajua ya kwamba yanakuhuzunisha yale wanayoyasema. Basi hakika wao hawakukadhibishi wewe, lakini hao madhalimu wanazikataa Ishara za Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 34, 'Na hakika walikadhibiwa Mitume wa kabla yako. Nao wakavumilia kule kukanushwa, na kuudhiwa, mpaka ilipowafikia nusura yetu. Na hakuna wa kubadilisha maneno ya Mwenyezi Mungu. Na hakika imekwishakujia katika habari za Mitume hao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 35, 'Na ikiwa ni makubwa kwako huku kupeana kwao mgongo, basi kama unaweza kutafuta njia ya chini kwa chini ya ardhi, au ngazi ya kwendea mbinguni ili uwaletee Ishara. Na lau kuwa Mwenyezi Mungu angelipenda, angeliwakusanya kwenye uongofu. Basi kamwe usiwe miongoni mwa wajinga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 36, 'Hakika wanaoitikia ni wale wanaosikia. Na ama wafu, Mwenyezi Mungu atawafufua, kisha kwake Yeye ndiko watakakorejeshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 37, 'Na walisema: Kwa nini hakuteremshiwa muujiza kutoka kwa Mola wake Mlezi? Sema: Hakika Mwenyezi Mungu ni Muweza wa kuteremsha muujiza. Lakini wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 38, 'Na hakuna mnyama yeyote katika ardhi, wala ndege anayepaa kwa mbawa zake mbili, isipokuwa ni umma kama nyinyi. Hatukupuuza kitu chochote katika Kitabu. Kisha kwa Mola wao Mlezi watakusanywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 39, 'Na wale waliozikadhibisha Ishara zetu ni viziwi na mabubu wamo katika giza mbalimbali. Yule ambaye Mwenyezi Mungu anataka, anampoteza, na yule ambaye anataka, anamuweka katika Njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 40, 'Sema: Mwaonaje ikiwajia adhabu ya Mwenyezi Mungu, au ikawajia hiyo Saa, asiyekuwa Mwenyezi Mungu ndiye mtakayemuomba, ikiwa nyinyi ni wakweli?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 41, 'Bali Yeye ndiye mtakayemuomba, naye atawaondolea mnachomwomba akipenda. Na mtasahau hao mnaowafanya washirika wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 42, 'Na kwa yakini tuliwatuma Mitume kwa kaumu zilizokuwa kabla yako, kisha tukawatia katika dhiki na mashaka ili wanyenyekee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 43, 'Kwa nini hawakunyenyekea ilipowafika adhabu yetu? Lakini nyoyo zao zilikuwa ngumu, na Shetani akawapambia waliyokuwa wakiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 44, 'Basi waliposahau yale waliyokumbushwa, tuliwafungulia milango ya kila kitu. Mpaka walipofurahia yale waliyopewa, tukawashika kwa ghafla, na mara wakawa wenye kukata tamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 45, 'Ikakatwa mizizi ya kaumu waliodhulumu, na sifa njema ni za Mwenyezi Mungu, Mola Mlezi wa viumbe vyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 46, 'Sema: Mwaonaje Mwenyezi Mungu akinyakua kusikia kwenu, na kuona kwenu, na akaziziba nyoyo zenu, ni mungu gani asiyekuwa Mwenyezi Mungu atakayewaletea hayo tena? Angalia vipi tunavyozieleza Ishara, kisha wao wanapuuza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 47, 'Sema: Mwaonaje, ikiwafikia adhabu ya Mwenyezi Mungu kwa ghafla, au kwa dhahiri, je wataangamizwa isipokuwa kaumu waliodhulumu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 48, 'Na hatuwatumi Mitume isipokuwa huwa ni wabashiri na waonyaji. Basi mwenye kuamini na akatengenea, haitakuwa hofu yoyote juu yao, wala hawatahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 49, 'Na wale waliozikadhibisha Ishara zetu itawagusa adhabu kwa vile walivyokuwa wakivuka mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 50, 'Sema: Mimi siwaambii kuwa ninazo hazina za Mwenyezi Mungu. Wala sijui mambo yaliyofichikana. Wala siwaambii kuwa mimi ni Malaika. Mimi sifuati isipokuwa yanayofunuliwa kwangu. Sema: Je, wanakuwa sawa, kipofu na mwenye kuona. Basi hamfikirii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 51, 'Na waonye kwayo wale wanaohofu kuwa watakusanywa kwa Mola wao Mlezi, hali ya kuwa hawana kando naye mlinzi wala mwombezi, ili wamche Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 52, 'Wala usiwafukuze wale wanaomwomba Mola wao Mlezi asubuhi na jioni kwa kutaka radhi yake. Si juu yako hisabu yao hata kidogo, wala hisabu yako si juu yao hata kidogo, hata uwafukuze na uwe miongoni mwa wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 53, 'Na hivi ndivyo tunavyowajaribu wao kwa wao, ili waseme: Ni hao ndio Mwenyezi Mungu amewafadhilisha miongoni mwetu? Kwani Mwenyezi Mungu hawajui vyema wanaoshukuru?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 54, 'Na wanapokujia wanaoziamini Ishara zetu waambie: Assalamu alaikum! (Amani iwe juu yenu!) Mola wenu Mlezi amejilazimisha rehema, ya kwamba atakayefanya uovu miongoni mwenu kwa ujinga, kisha akatubu baada yake na akatengenea, basi hakika Yeye ni Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 55, 'Na ndivyo hivyo tunavyozieleza Ishara, na ili ibainike njia ya wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 56, 'Sema: Mimi nimekatazwa kuwaabudu hao mnaowaomba badala ya Mwenyezi Mungu. Sema: mimi sifuati matamanio yenu. Hivyo nitakuwa nimepotea, na sitakuwa miongoni mwa walioongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 57, 'Sema: Mimi nipo kwenye sheria iliyo wazi itokayo kwa Mola wangu Mlezi, nanyi mnaikanusha. Mimi sina hicho (adhabu) mnachotaka kije haraka. Hakuna hukumu ila ya Mwenyezi Mungu. Yeye anasimulia yaliyo kweli; naye ni Mbora wa kuhukumu kuliko wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 58, 'Sema: Lau kuwa ninacho hicho mnachotaka kije haraka, ingelikwishakatwa shauri baina yangu na nyinyi. Na Mwenyezi Mungu ndiye anayewajua zaidi madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 59, 'Na ziko kwake funguo za ghaibu; hakuna azijuaye ila Yeye tu. Na Yeye anajua kilicho katika nchi kavu na baharini. Na halidondoki jani ila analijua. Wala punje katika giza la ardhi, wala kinyevu, wala kikavu ila kimo katika Kitabu kinachobainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 60, 'Naye ndiye anayewafisha usiku, na anakijua mlichokifanya mchana. Kisha Yeye huwafufua humo mchana ili muda uliowekwa utimizwe. Kisha kwake Yeye ndiyo marejeo yenu, kisha atawaambia yale mliyokuwa mkiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 61, 'Naye ndiye Mwenye nguvu za kushinda, aliye juu ya waja wake. Na huwapelekea (nyinyi) waangalizi, mpaka mmoja wenu yakimjia mauti wajumbe wetu humfisha, nao hawapuuzi chochote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 62, 'Kisha watarudishwa kwa Mwenyezi Mungu, Mola wao wa Haki. Hakika, hukumu ni yake. Naye ni Mwepesi zaidi kuliko wote wanaohisabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 63, 'Sema: Ni nani anayewaokoa kutoka katika giza la nchi kavu na baharini? Mnamwomba kwa unyenyekevu na kwa siri, mkisema: Kama akituokoa na haya, bila ya shaka tutakuwa miongoni mwa wanaoshukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 64, 'Sema: Mwenyezi Mungu hukuokoeni kutoka katika hayo, na kutoka katika kila mashaka, na kisha nyinyi mnamshirikisha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 65, 'Sema: Yeye ndiye Muweza wa kuwatumia adhabu kutoka juu yenu au kutoka chini ya miguu yenu, au awavishe fujo la mfarakano, na awaonjeshe baadhi yenu jeuri ya wenzi wenu. Tazama vipi tunavyozieleza Aya ili wafahamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 66, 'Na kaumu yako waliikadhibisha, nayo ndiyo Haki. Sema: Mimi si wakili juu yenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 67, 'Kila habari ina kipindi chake. Nanyi mtakujajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 68, 'Na unapowaona wanaoziingilia Aya zetu, basi jitenge nao mpaka waingilie mazungumzo mengine. Na kama Shetani atakusahaulisha, basi baada ya kutanabahi usikae pamoja na watu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 69, 'Wala hakuna jukumu lolote kwa wale wamchao Mungu, lakini ni kukumbusha tu, asaa wapate kumcha Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 70, 'Waachilie mbali walioifanya dini yao ni mchezo na pumbao, na uhai wa dunia ukawadanganya. Nawe kumbusha kwayo, isije nafsi ikaangamizwa kwa sababu ya iliyoyachuma, nayo haina mlinzi wala mwombezi ila Mwenyezi Mungu. Na ingetoa kila fidia, haitokubaliwa. Hao ndio walioangamizwa kwa sababu ya yale waliyoyachuma. Wao watapata kinywaji cha maji ya moto kabisa, na adhabu chungu kwa sababu ya walivyokuwa wakikufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 71, 'Sema: Je, tumuombe asiyekuwa Mwenyezi Mungu ambaye hatufai wala hatudhuru, na turejee nyuma baada ya Mwenyezi Mungu kwisha tuongoa? Tuwe kama ambao mashetani wamempumbaza katika ardhi, amechanganyikiwa? Anao marafiki wanaomwita aende kwenye uwongofu, wakimwambia: ''Njoo kwetu!'' Sema: Hakika uongofu wa Mwenyezi Mungu ndio Uongofu. Nasi tumeamrishwa tusilimu kwa Mola Mlezi wa viumbe vyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 72, 'Na mshike Sala, na mcheni Yeye, na kwake Yeye ndiko mtakakokusanywa', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 73, 'Naye ndiye aliyeziumba mbingu na ardhi kwa Haki. Siku atakaposema: "Kuwa!" Na yawe. Kauli yake ni Haki. Na ufalme wote ni wake Siku litakapopulizwa barugumu, Mjuzi wa yaliyofichikana na yanayoonekana. Naye ndiye Mwenye hekima, Mwenye habari zote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 74, 'Na pale Ibrahim alipomwambia baba yake, Azar: Unayafanya masanamu kuwa ni miungu? Hakika mimi nakuona wewe na watu wako mko katika upotovu ulio wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 75, 'Na vivyo hivyo tulimwonyesha Ibrahim ufalme wa mbingu na ardhi, na ili awe miongoni mwa wenye yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 76, 'Na ulipomwingilia usiku, aliona nyota kubwa, akasema: Huyu ndiye Mola wangu Mlezi. Na ilipotua, akasema: Siwapendi wanaotua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 77, 'Alipouona mwezi unachomoza alisema: Huyu ndiye Mola wangu Mlezi. Na ulipotua, akasema: Kama Mola wangu Mlezi hataniongoa, basi hakika nitakuwa miongoni mwa kaumu waliopotea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 78, 'Na alipoliona jua linachomoza, akasema: ''Huyu ndiye Mola wangu Mlezi. Huyu ni mkubwa zaidi.'' Na lilipotua, akasema: Enyi kaumu yangu! Mimi niko mbali sana na hayo mnayoshirikisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 79, 'Hakika mimi nimeuelekeza uso wangu kwa yule aliyeziumba mbingu na ardhi, huku nikiwa mnyoofu, wala mimi si miongoni mwa washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 80, 'Na kaumu yake wakamhoji. Akasema: Je, mnanihoji kuhusiana na Mwenyezi Mungu, na ilhali Yeye hakika amekwishaniongoa? Wala siogopi hao mnaowashirikisha naye, isipokuwa ikiwa Mola wangu Mlezi akipenda kitu. Mola wangu Mlezi amekusanya elimu ya kila kitu. Basi je, hamkumbuki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 81, 'Na vipi nivihofu hivyo mlivyovishirikisha, ilhali nyinyi hamhofu kuwa nyinyi mmemshirikisha Mwenyezi Mungu na kitu ambacho hakuwateremshia uthibitisho juu yake. Basi ni kundi gani katika mawili haya lina haki zaidi kupata amani, ikiwa nyinyi mnajua?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 82, 'Wale ambao waliamini, na hawakuchanganya imani yao na dhuluma, hao ndio wana amani, na wao ndio walioongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 83, 'Na hizo ndizo hoja zetu tulizompa Ibrahim dhidi ya kaumu yake. Tunamnyanyua tumtakaye daraja mbalimbali. Hakika Mola wako Mlezi ni Mwenye hekima, Mwenye kujua yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 84, 'Na tukamtunuku (Ibrahim) Is-haq na Yaakub. Kila mmoja wao tulimwongoa. Na Nuhu tulimwongoa kabla. Na katika kizazi chake tulimwongoa Daud na Suleiman na Ayyub na Yusuf na Musa na Harun. Na hivi ndivyo tunavyowalipa wafanyao mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 85, 'Na Zakaria, na Yahya, na Isa, na Ilyas. Kila mmoja wao ni miongoni mwa walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 86, 'Na Ismail, na Al-Yasaa, na Yunus, na Lut''. Na kila mmoja wao tulimboresha juu ya walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 87, 'Na katika baba zao, na vizazi vyao, na ndugu zao. Na tukawateua na tukawaongoa kwenye njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 88, 'Huo ni uongofu wa Mwenyezi Mungu, anaongoa kwao amtakaye katika waja wake. Na lau wangelimshirikisha, basi yangeliwaharibikia yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 89, 'Hao ndio tuliowapa Kitabu, na hukumu, na Unabii. Kwa hivyo, ikiwa hawa (makafiri) watayakufuru, basi hakika tumekwishayawakilisha kwa kaumu wasioyakufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 90, 'Hao ndio ambao Mwenyezi Mungu amewaongoa. Basi fuata uongofu wao. Sema: Mimi siwaombi ujira wowote juu yake. Haya si isipokuwa ni ukumbusho kwa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 91, 'Na hawakumkadiria Mwenyezi Mungu kwa haki ya kadri yake, waliposema: Mwenyezi Mungu hakumteremshia mwanaadamu chochote. Sema: Nani aliyekiteremsha Kitabu alichokuja nacho Musa, chenye nuru na uwongofu kwa watu, mlichokifanya kurasa kurasa mkizionyesha, na mengi mkiyaficha? Na mkafunzwa mliyokuwa hamyajui nyinyi wala baba zenu? Sema: ''Mwenyezi Mungu.'' Kisha waache wacheze katika porojo lao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 92, 'Na hiki ni Kitabu tulichokiteremsha, kilichobarikiwa, chenye kusadikisha yale yaliyokitangulia, na ili uuonye Mama wa Miji na wale walio pembezoni mwake. Na wale wanaoiamini Akhera wanakiamini, nao wanazihifadhi Swala zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 93, 'Na ni nani dhalimu zaidi kuliko yule anayemzulia uongo Mwenyezi Mungu, au anayesema: ''Mimi nimeletewa wahyi''; na ilhali hakuletewa wahyi wowote. Na yule anayesema: Nitateremsha kama alivyoteremsha Mwenyezi Mungu. Na lau ungeliwaona madhalimu wanapokuwa katika mahangaiko ya mauti, na Malaika wamewanyooshea mikono wakiwambia: Zitoeni roho zenu! Leo mtalipwa adhabu ya kudunisha kwa sababu ya yale mliyokuwa mkiyasema juu ya Mwenyezi Mungu yasiyo ya haki, na mlivyokuwa mkizifanyia kiburi Ishara zake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 94, 'Nanyi mlitujia wapweke kama tulivyowaumba mara ya kwanza. Na mkayaacha nyuma yenu yote tuliyowapa, na wala hatuwaoni hao waombezi wenu, ambao mlidai kuwa ni washirika wa Mwenyezi Mungu kwenu. Yamekatika mahusiano baina yenu, na yamekupoteeni mliyokuwa mkiyadai.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 95, 'Hakika Mwenyezi Mungu ndiye mpasuaji nafaka na mbegu za tende, zikachipua. Humtoa aliye hai kutokana na maiti, na humtoa maiti kutokana na aliye hai. Huyo ndiye Mwenyezi Mungu. Basi vipi mnadanganywa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 96, 'Ndiye anayepambaza mwangaza wa asubuhi; na ameufanya usiku kuwa mapumziko, na jua na mwezi kwenda kwa hesabu. Hayo ndiyo makadirio ya Mwenye nguvu kubwa, Mwenye kujua yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 97, 'Na Yeye ndiye aliyewawekea nyota ili mwongoke kwazo katika giza mbalimbali za bara na bahari. Hakika tumezieleza kwa kina Ishara hizi kwa kaumu wanaojua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 98, 'Na Yeye ndiye aliyewaanzilisha kutokana na nafsi moja. Pako pahali pa kutulia na pa kupita njia. Hakika tumezichambua Ishara hizi kwa watu wanaofahamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 99, 'Na Yeye ndiye aliyeteremsha maji kutoka mbinguni; na kwayo tukatoa mimea ya kila kitu. Na kutokana na baadhi yake tukatoa mimea ya kijani, tukatoa ndani yake punje zilizopandana; na kutokana na mitende katika makole yake yakatoka mashada yaliyo karibu; na mabustani ya mizabibu na mizaituni, na makomamanga, yanayofanana na yasiyofanana. Angalieni matunda yake yanapozaa na yakaiva. Hakika katika hayo kuna Ishara kwa kaumu wanaoamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 100, 'Lakini walimfanyia Mwenyezi Mungu washirika, majini, ilhali Yeye ndiye aliyewaumba. Na wakamzulia kuwa ana wana wa kiume na wa kike, bila ya kuwa na elimu yoyote. Yeye Ametakasika, na ametukuka juu zaidi ya hayo wanayomuelezea kwayo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 101, 'Yeye ndiye Muumbaji mwanzilishi wa mbingu na ardhi. Vipi awe na mwana, ilhali hakuwa na mke? Naye ndiye aliyeumba kila kitu. Naye ni Mwenye kujua vyema kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 102, 'Huyo ndiye Mwenyezi Mungu, Mola wenu Mlezi, hakuna mungu isipokuwa Yeye, Muumba wa kila kitu. Basi muabuduni Yeye tu. Naye ni Mtegemewa wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 103, 'Macho hayawezi kumzunguka, naye anayazunguka macho. Naye ni Mjua siri, Mwenye habari zote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 104, 'Hakika zimekwishawajia hoja wazi wazi kutoka kwa Mola wenu Mlezi. Kwa hivyo, mwenye kuona, basi ni kwa faida yake mwenyewe. Na mwenye kupofuka, basi ni hasara yake. Wala mimi si mtunzaji wenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 105, 'Na namna hivyo tunazileta Aya mbalimbali, na wao wakwambie: ''Umesoma.'' Na ili tuyabainishie watu wanaojua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 106, 'Fuata yale yaliyofunuliwa kwako kutoka kwa Mola wako Mlezi. Hakuna mungu isipokuwa Yeye. Na jitenge na washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 107, 'Na lau Mwenyezi Mungu angelipenda, wasingelimshirikisha. Na Sisi hatukukufanya wewe uwe mtunzaji wao. Wala wewe si mlinzi juu yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 108, 'Wala msiwatukane hao ambao wao wanawaomba badala ya Mwenyezi Mungu, nao wakamtukana Mwenyezi Mungu kwa jeuri bila ya kujua. Namna hivyo tumewapambia kila umma vitendo vyao. Kisha marejeo yao ni kwa Mola wao Mlezi, naye atawaambia yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 109, 'Na waliapa kwa Mwenyezi Mungu viapo vyao vikali zaidi, kuwa ikiwajia Ishara, bila shaka wataiamini. Sema: Hakika Ishara hizo ziko kwa Mwenyezi Mungu. Na ni nini kitawajulisha kuwa zikija, hawataamini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 110, 'Na tutazigeuza nyoyo zao na macho yao kama vile hawakuiamini mara ya kwanza. Kisha tutawaacha katika upotovu wao wakitangatanga kwa upofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 111, 'Na lau kuwa tungeliwateremshia Malaika, na maiti wakazungumza nao, na tukawakusanyia kila kitu mbele yao, bado hawakuwa ni wa kuamini, isipokuwa Mwenyezi Mungu atake. Lakini wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 112, 'Na kadhalika tumemfanyia kila Nabii maadui mashetani wa kiwatu, na kijini, wanafundishana wao kwa wao maneno ya kupambapamba, kwa udanganyifu. Na angelipenda Mola wako Mlezi, wasingelifanya hayo. Basi waache na hayo wanayoyazua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 113, 'Na ili ziyaelekee hayo nyoyo za wale wasioiamini Akhera, nao wayaridhie, na wayachume yale wanayoyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 114, 'Je, nimtafute hakimu asiyekuwa Mwenyezi Mungu, naye ndiye aliyewateremshia Kitabu hiki kilichoelezwa kwa kina? Na wale tuliowapa Kitabu wanajua ya kwamba kimeteremshwa kutoka kwa Mola wako Mlezi kwa Haki. Basi kamwe usiwe katika wale wanaotia shaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 115, 'Na yametimia maneno ya Mola Mlezi wako kwa ukweli na uadilifu. Hakuna yeyote wa kuyabadilisha maneno yake. Na Yeye ndiye Mwenye kusikia vyema, Mwenye kujua yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 116, 'Na ukiwatii wengi wa hawa walio katika dunia, watakupoteza mbali na Njia ya Mwenyezi Mungu. Hawa hawafuati isipokuwa dhana tu, na hawakuwa isipokuwa ni wenye kusema uongo tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 117, 'Hakika Mola wako Mlezi ndiye anayejua vyema yule aliyepotea Njia yake, naye ndiye anayejua vyema wale walioongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 118, 'Basi kuleni katika vile vilivyotajiwa jina la Mwenyezi Mungu, ikiwa mnaziamini Aya zake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 119, 'Na mna nini msile katika vile vilivyotajiwa jina la Mwenyezi Mungu, naye amekwishawabainishia kwa kina vile alivyowaharamishia, isipokuwa vile mnavyolazimishwa? Na hakika wengi wanapotea kwa matamanio yao bila ya kuwa na elimu. Hakika Mola wako Mlezi ndiye Mwenye kujua vyema wale wanaopindukia mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 120, 'Na acheni dhambi iliyo dhahiri na iliyofichikana yake. Hakika wale wanaochuma dhambi watalipwa kwa yale waliyokuwa wakiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 121, 'Wala msile katika vile ambavyo halikutajwa jina la Mwenyezi Mungu juu yake. Kwani huko hakika ni kuvuka mipaka. Na kwa yakini mashetani wanawaletea wahyi marafiki zao ili wabishane nanyi. Na mkiwatii, basi nyinyi kwa hakika mtakuwa washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 122, 'Je, yule aliyekuwa maiti, kisha tukamhuisha, na tukamfanyia nuru akatembea kwayo katika watu, ni kama yule ambaye mfano wake yuko katika giza mbalimbali, sio wa kutoka humo? Kama hivyo ndivyo makafiri walivyopambiwa yale waliyokuwa wakiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 123, 'Na namna hivi tumeweka katika kila mji wakubwa wa wahalifu ili wafanye vitimbi ndani yake. Na wala hawafanyii vitimbi isipokuwa nafsi zao ilhali hawatambui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 124, 'Na inapowajia Ishara, wao husema: ''Hatutaamini mpaka tupewe mfano wa yale waliyopewa Mitume wa Mwenyezi Mungu.'' Mwenyezi Mungu ndiye anayejua zaidi ni wapi anaweka ujumbe wake. Itawafikia wale waliofanya uhalifu udhalili kwa Mwenyezi Mungu, na adhabu kali kwa sababu ya vitimbi walivyokuwa wakivifanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 125, 'Basi yule ambaye Mwenyezi Mungu anataka kumuongoa, humfungulia kifua chake kwa Uislamu. Na yule anayetaka kumpoteza, hukifanya kifua chake kuwa na dhiki, kimebana, kama kwamba anapanda katika mbingu kwa ugumu mkubwa. Namna hivi ndivyo Mwenyezi Mungu anaweka uchafu juu ya wale wasioamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 126, 'Na hii ndiyo Njia ya Mola wako Mlezi iliyonyooka. Tumeshazieleza Aya kwa kina kwa kaumu wanaokumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 127, 'Hao watapata nyumba ya salama kwa Mola wao Mlezi. Naye ndiye Rafiki Mlinzi wao kwa sababu ya yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 128, 'Na ile Siku atakapowakusanya wote, “Enyi kundi la majini! Hakika nyinyi mmechukua wafuasi wengi katika wanadamu.” Na marafiki zao katika wanadamu watasema: ''Mola wetu Mlezi! Tulinufaishana baadhi yetu kwa wenzi wetu, na tumefikia muda wetu uliotuwekea.'' Basi Mwenyezi Mungu atasema: Moto ndiyo makazi yenu, mtadumu humo, isipokuwa apendavyo Mwenyezi Mungu. Hakika Mola wako Mlezi ni Mwenye hekima, Mwenye kujua zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 129, 'Na namna hivi ndivyo tunavyowafanya baadhi ya madhalimu wapendane wao kwa wao kwa sababu ya yale waliyokuwa wakiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 130, 'Enyi kundi la majini na watu! Je, hawakuwajia Mitume kutokana na nyinyi wenyewe wakiwabainishia Aya zangu, na wakiwasimulia kukutana na Siku yenu hii? Nao watasema, “Tumeshuhudia juu ya nafsi zetu.” Na yaliwadanganya maisha ya dunia. Nao watashuhudia dhidi yao wenyewe ya kwamba walikuwa makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 131, 'Hayo ni kwa sababu ya kuwa Mola wako Mlezi hakuwa ni wa kuiangamiza miji kwa dhuluma, hali ya kuwa wenyewe wameghafilika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 132, 'Na kila mmoja ana daraja mbalimbali kutokana na yale waliyoyatenda. Na Mola wako Mlezi si mwenye kughafilika mbali na yale wanayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 133, 'Na Mola wako Mlezi ndiye asiyemhitaji yeyote, Mwenye rehema. Akitaka, atawaondoa na awaweke nyuma yenu wengine awatakao, kama vile alivyokutoeni kutokana na dhuria ya kaumu wengine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 134, 'Hakika, yale mnayoahidiwa yatafika, wala nyinyi hamtaweza kushinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 135, 'Sema: Enyi kaumu yangu! Fanyieni pahali penu mlipo, na hakika mimi ninafanya. Mtakuja jua ni ya nani yatakuwa makazi mema mwishoni. Hakika, madhalimu hawafaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 136, 'Na walimwekea Mwenyezi Mungu fungu katika mimea na wanyama alioumba, wakasema: ''Hii ni sehemu ya Mwenyezi Mungu - kwa madai yao - na hii ni ya washirikishwa wetu.'' Basi vile vilivyokuwa vya washirikishwa wao, havimfikii Mwenyezi Mungu, vile vilivyokuwa vya Mwenyezi Mungu, huwafikia washirikishwa wao. Ni uovu mno hayo wanayoyahukumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 137, 'Na kadhalika hao washirika wao wamewapambia wengi katika washirikina kuwaua watoto wao ili kuwaangamiza na kuwachanganyia dini yao. Na lau kuwa Mwenyezi Mungu angelipenda, wasingelifanya hayo. Basi waache na hayo wanayozua ya uongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 138, 'Nao walisema: "Mifugo hawa na mimea ni miiko. Hawavili isipokuwa tumtakaye" - kwa madai yao tu. Na mifugo wengine imeharamishwa migongo. Na mifugo wengine hawalitaji jina la Mwenyezi Mungu juu yao, kwa kumzulia uongo tu. Atawalipa kwa hayo ya uongo waliyokuwa wakiyazua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 139, 'Na walisema: Vile vilivyo katika matumbo ya mifugo hawa ni vya wanaume wetu tu, na vimeharamishwa kwa wake zetu. Lakini wakiwa nyamafu, basi wanashirikiana ndani yake. Atawalipa maelezo yao hayo. Hakika Yeye ni Mwenye hekima, Mwenye kujua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 140, 'Hakika walipata hasara wale waliowaua watoto wao kwa upumbavu bila ya elimu, na wakaharamisha vile alivyowaruzuku Mwenyezi Mungu kwa kumzulia Mwenyezi Mungu uongo. Hakika walipotea, wala hawakuwa wenye kuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 141, 'Na Yeye ndiye aliyeyaanzisha mabustani yenye kutambaa kwenye fito, na yasiyotambaa kwenye fito, na mitende, na mimea yenye vyakula mbali mbali, na mizaituni na mikomamanga inayofanana na isiyofanana. Kuleni katika matunda yake inapozaa, na toeni haki yake siku ya kuvunwa kwake. Wala msitumie kwa kupitiliza. Hakika Yeye hawapendi watumiao kwa kupitiliza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 142, 'Na katika mifugo kuna wale wabebao mizigo na wengine wadogo. Kuleni katika vile alivyowaruzuku Mwenyezi Mungu, wala msifuate nyayo za Shetani. Hakika yeye kwenu ni adui wa wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 143, '(Amewaumbia) majozi manane: katika kondoo ni wawili, na katika mbuzi ni wawili. Sema: Je, ameharamisha madume wawili hawa au majike wawili hawa, au wale walio matumboni mwa majike yote mawili haya? Niambieni kwa elimu ikiwa nyinyi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 144, 'Na katika ngamia ni wawili, na katika ng''ombe ni wawili. Sema: Je, ameharamisha haya madume yote mawili au majike wawili haya, au walio matumboni mwa majike haya? Au, nyinyi mlishuhudia Mwenyezi Mungu alipowausia haya? Basi ni nani dhalimu mkubwa kuliko yule aliyemzulia Mwenyezi Mungu uoongo, ili awapoteze watu bila ya elimu? Hakika Mwenyezi Mungu hawaongoi kaumu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 145, 'Sema: Sipati katika yale niliyofunuliwa mimi kitu kilichoharamishwa kwa mlaji kukila isipokuwa ikiwa ni nyamafu, au damu inayomwagika, au nyama ya nguruwe, kwani huo ni uchafu; au kilichovukiwa mipaka (wakati wa kuchinjwa) kwa kutajiwa jina la asiyekuwa Mwenyezi Mungu. Lakini mwenye kushikwa na dharura, bila ya kutamani wala kupita mipaka, basi hakika Mola wako Mlezi ni Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 146, 'Na Mayahudi tuliwaharamishia kila mwenye kwato au mguu usio na mgawanyiko. Na katika ng''ombe, na kondoo, na mbuzi tuliwaharamishia shahamu yao, isipokuwa ile iliyobeba migongo yao au matumbo yao, au iliyochanganyika na mifupa. Hayo tuliwalipa kwa sababu ya uasi wao. Nasi bila ya shaka ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 147, 'Na wakikukadhibisha, basi wewe sema: Mola wenu Mlezi ni Mwenye rehema kunjufu. Wala haizuiwi adhabu yake kwa kaumu wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 148, 'Watasema wale walioshirikisha, "Lau kuwa Mwenyezi Mungu angetaka, tusingelishirikisha, wala baba zetu, wala tusingeliharamisha kitu chochote." Hivyo ndivyo walivyokadhibisha wale waliokuwa kabla yao mpaka walipoionja adhabu yetu. Sema: Je, nyinyi mnayo elimu yoyote mtutolee hiyo? Nyinyi hamfuati isipokuwa dhana. Wala hamfanyi isipokuwa kukisia tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 149, 'Sema: Basi Mwenyezi Mungu ndiye Mwenye hoja ya kukata. Na kama angelitaka, angeliwaongoa nyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 150, 'Sema: Waleteni mashahidi wenu ambao wanashuhudia kuwa Mwenyezi Mungu amewaharamisha hawa. Kwa hivyo, wakishuhudia, basi wewe usishuhudie pamoja nao. Wala usifuate matamanio ya wale waliozikadhibisha Ishara zetu, na ambao hawaamini katika Akhera, nao wanamlinganisha Mola wao Mlezi na wengine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 151, 'Sema: Njooni niwasomee yale aliyowaharamishia Mola wenu Mlezi: Kwamba msimshirikishe Yeye na chochote, na wazazi wawili wafanyieni uzuri, wala msiwauwe watoto wenu kwa sababu ya umasikini. Sisi tunawaruzuku nyinyi na wao. Wala msikaribie machafu, yaliyo dhahiri yake, na yaliyofichikana yake. Wala msiiue nafsi ambayo Mwenyezi Mungu aliiharamisha isipokuwa kwa haki. Hayo aliwausia ili myatie akilini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 152, 'Wala msiikaribie mali ya yatima isipokuwa kwa kile kilicho kizuri kabisa mpaka afike utu uzima wake. Na timizeni kipimo na mizani kwa uadilifu. Hatuibebeshi nafsi isipokuwa kwa uwezo wake. Na mnaposema, basi fanyeni uadilifu hata kama ni jamaa. Na ahadi ya Mwenyezi Mungu, itimizeni. Hayo amewausia ili mkumbuke.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 153, 'Na kwamba hakika hii ndiyo Njia yangu iliyonyooka, basi ifuateni. Wala msifuate njia nyinginezo, zikakutengeni mbali na Njia yake. Haya amewausia ili mche (Mwenyezi Mungu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 154, 'Tena tulimpa Musa Kitabu kwa kumtimizia (neema) yule aliyefanya uzuri, na kuwa ni maelezo ya kina ya kila kitu, na uwongofu na rehema, ili waamini katika kukutana na Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 155, 'Na hiki ni Kitabu tulichokiteremsha, kilichobarikiwa. Basi kifuateni, na mcheni, ili mrehemewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 156, 'Mkaja kusema, “Hakika waliteremshiwa Kitabu makundi mawili tu kabla yetu, na sisi tulikuwa hatuna habari ya waliyokuwa wakiyasoma.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 157, 'Au mkasema: "Lau hakika sisi tungeteremshiwa Kitabu hicho, basi tungelikuwa waongofu zaidi kuwaliko wao." Basi hakika imekwishawajia hoja iliyo wazi kutoka kwa Mola wenu Mlezi, na uongofu, na rehema. Kwa hivyo, ni nani aliye dhalimu mkubwa zaidi kuliko yule anayekadhibisha Ishara za Mwenyezi Mungu, na akajitenga nazo? Tutawalipa wale wanaojitenga na Ishara zetu adhabu mbaya kabisa kwa sababu ya walivyokuwa wakijitenga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 158, 'Je, wanangoja isipokuwa kwamba wajiwe na Malaika, au awajie Mola wako Mlezi, au ziwajie baadhi ya Ishara za Mola wako Mlezi? Siku zitakapowajia baadhi ya Ishara za Mola wako Mlezi, kuamini kwa nafsi hapo hakutaifaa kitu, ikiwa haikuwa imeamini kabla yake, au imefanya heri katika Imani yake. Sema, "Ngojeni, nasi hakika pia ni wenye kungoja."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 159, 'Hakika wale waliofarakisha Dini yao na wakawa makundi makundi, wewe si miongoni mwao katika chochote. Bila ya shaka jambo lao liko kwa Mwenyezi Mungu; kisha atawajulisha yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 160, 'Mwenye kuja na jema, basi ana mara kumi mfano wake. Na mwenye kuja na baya, basi hatalipwa isipokuwa mfano wake. Na wao hawatadhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 161, 'Sema: "Hakika mimi, Mola wangu Mlezi ameniongoa kwenye njia iliyonyooka, dini iliyo sawa kabisa, mila ya Ibrahim aliyekuwa mnyofu, wala hakuwa miongoni mwa washirikina."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 162, 'Sema: "Hakika Swala yangu, na kuchinja kwangu , na uhai wangu, na kufa kwangu, ni kwa ajili ya Mwenyezi Mungu, Mola Mlezi wa walimwengu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 163, 'Hana mshirika yeyote. Na hayo ndiyo niliyoamrishwa, na mimi ni wa kwanza wa Waislamu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 164, 'Sema: Je nimtafute mola mlezi asiyekuwa Mwenyezi Mungu, ilhali Yeye ndiye Mola Mlezi wa kila kitu? Na wala haichumi kila nafsi isipokuwa ni juu yake. Na wala hatabeba mbeba mzigo, mzigo wa mwingine. Kisha kwa Mola wenu Mlezi ndiyo marejeo yenu, kisha atawajulisha yale mliyokuwa mkihitilafiana ndani yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 165, 'Naye ndiye aliyewafanya kuwa wafuatizi (makhalifa) katika ardhi, na amewanyanyua baadhi yenu juu ya wengine daraja mbalimbali ili akujaribuni katika hayo aliyowapa. Hakika Mola wako Mlezi ni Mwepesi wa kuadhibu, na hakika Yeye ni Mwenye kufuta dhambi zaidi, Mwenye kurehemu sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 1, 'Alif Laam Miim Swaad.[1]', '[1] Herufi hizi "Alif Laam Miim Swaad" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 2, 'Kitabu kilichoteremshwa kwako, basi isiwe dhiki yoyote katika kifua chako kwa sababu yake, ili uonye kwacho, na kiwe ni ukumbusho kwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 3, 'Yafuateni yale yaliyoteremshwa kwenu kutoka kwa Mola wenu Mlezi, wala msifuate marafiki wasaidizi wowote badala yake. Ni machache mnayoyakumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 4, 'Na ni miji mingapi tuliyoiangamiza, ikaifikia adhabu yetu usiku au walipokuwa wamelala adhuhuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 5, 'Basi haukuwa mwito wao wakati ilipowajia adhabu yetu, isipokuwa walisema, "Hakika sisi tulikuwa madhalimu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 6, 'Na hakika tutawauliza wale waliotumiwa Ujumbe, na pia hakika tutawauliza hao Wajumbe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 7, 'Tena hakika tutawasimulia kwa elimu. Wala Sisi si kwamba hatukuwepo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 8, 'Na kipimo Siku hiyo kitakuwa kwa haki. Kwa hivyo, yule ambaye vipimo vyake vitakuwa vizito, basi hao ndio waliofaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 9, 'Na yule ambaye vipimo vyake vitakuwa hafifu, basi hao ndio waliozihasirisha nafsi zao kwa sababu ya vile walivyokuwa wakizifanyia Ishara zetu udhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 10, 'Na hakika tumewaimarisha katika dunia, na tukawajalia humo njia za kupata maisha. Ni kidogo tu mnavyoshukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 11, 'Na hakika tuliwaumba, kisha tukawatia sura, kisha tukawaambia Malaika, "Msujudieni Adam." Basi wakasujudu isipokuwa Iblisi, hakuwa miongoni mwa waliosujudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 12, '(Mwenyezi Mungu) akasema, "Ni nini kilichokuzuia kusujudu nilipokuamrisha?" Akasema, "Mimi ni bora zaidi kumliko yeye. Uliniumba kwa moto, naye ulimuumba kwa udongo."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 13, 'Akasema, "Basi teremka kutoka humo! Haikufalii kufanya kiburi humo. Basi toka! Hakika wewe ni miongoni mwa walio duni."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 14, 'Akasema, "Nipe muhula mpaka siku watakapofufuliwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 15, 'Akasema, "Hakika wewe ni miongoni mwa waliopewa muhula."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 16, 'Akasema: Kwa kuwa umenipotosha, basi hakika nitawakalia katika Njia yako iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 17, 'Kisha nitawajia kwa mbele yao na kwa nyuma yao na kuliani kwao kwote na kushotoni kwao kwote. Wala hutawakuta wengi wao ni wenye shukrani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 18, 'Akasema: Toka humo ilhali umefedheheshwa, umefukuzwa. Hakuna shaka atakayekufuata miongoni mwao, basi nitaijaza Jahannam kwa nyinyi nyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 19, 'Na wewe, Adam! Kaa wewe na mkeo Bustanini humo, na kuleni kwayo mpendapo. Wala msiukaribie mti huu, basi mkawa katika madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 20, 'Basi Shetani akawatia wasiwasi ili awafichulie tupu zao walizofichwa, na akasema: Hakuwakataza Mola wenu Mlezi mti huu isipokuwa mkaja kuwa Malaika, au mkawa katika wanaoishi milele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 21, 'Naye akawaapia: Hakika mimi ni miongoni wa wanaowanasihi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 22, 'Basi akawatumbukiza kwa hadaa. Na walipouonja ule mti, tupu zao zikawafichukia na wakaanza kujibandikia katika majani ya Bustani hiyo. Na Mola wao Mlezi akawaita, "Je, sikuwakataza mti huo, na kuwaambia ya kwamba hakika Shetani kwenu ni adui wa dhahiri?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 23, 'Wakasema: Mola wetu Mlezi! Tumezidhulumu nafsi zetu, na kama hutatufutia dhambi na ukaturehemu, hakika tutakuwa katika waliohasirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 24, 'Akasema: Teremkeni! Nyinyi kwa nyinyi ni maadui. Nanyi katika ardhi mtakuwa na makao na starehe mpaka ufike muda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 25, 'Akasema: Humo mtakuwa hai, na humo mtakufa, na kutoka humo mtatolewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 26, 'Enyi wanadamu! Hakika tumewateremshia vazi la kuficha tupu zenu na vazi la pambo. Na vazi la ucha Mungu, hilo ndilo bora zaidi. Hilo ni katika Ishara za Mwenyezi Mungu ili mpate kukumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 27, 'Enyi wanadamu! Kamwe Shetani asiwafitini kama alivyowatoa wazazi wenu katika Bustani ile, akawavua vazi lao ili awaonyeshe tupu zao. Hakika yeye anawaona yeye na kabila yake kwa namna ambayo nyinyi hamuwaoni. Hakika Sisi tumewafanya Mashetani kuwa ni marafiki wasaidizi wa wale wasioamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 28, 'Na wanapofanya uchafu, husema: Tuliwakuta baba zetu juu yake, na Mwenyezi Mungu ndiye aliyetuamrisha hayo. Sema: Hakika Mwenyezi Mungu haamrishi uchafu. Je, mnasema juu ya Mwenyezi Mungu yale msiyoyajua?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 29, 'Sema: Mola wangu Mlezi ameamrisha uadilifu, na zielekezeni nyuso zenu kila mnaposujudu, na muombeni Yeye kwa kumfanyia yeye tu Dini. Kama alivyowaanzisha, ndivyo mtakavyorudi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 30, 'Kundi moja ameliongoa, na kundi jingine limethibitikiwa na upotovu. Kwa hakika hao waliwafanya mashetani kuwa ndio marafiki walinzi badala ya Mwenyezi Mungu, na wanadhani kuwa wao wameongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 31, 'Enyi wanadamu! Chukueni pambo lenu mnapokwenda kwenye kila mahali pa kusudjudu (kama vile msikiti), na kuleni, na kunyweni, wala msipitilize. Kwa hakika Yeye hapendi wanaopitiliza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 32, 'Sema: Ni nani aliyeharamisha pambo la Mwenyezi Mungu alilowatolea waja wake, na vile vilivyo vizuri katika riziki? Sema: Hivyo ni kwa wale walioamini katika uhai wa duniani, na Siku ya Kiyama vitakuwa vyao wao tu. Namna hivyo ndivyo tunavyowaelezea Ishara kaumu wanaojua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 33, 'Sema: Hakika Mola wangu Mlezi ameharamisha machafu, yaliyodhihiri yake na ya siri, na dhambi, na kuvuka mipaka bila ya haki, na kumshirikisha Mwenyezi Mungu na ambacho hakukiteremshia uthibitisho wowote, na kusema juu ya Mwenyezi Mungu yale msiyoyajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 34, 'Na kila umma una muda wake. Na unapokuja muda wao, basi hawakawii hata saa moja, wala hawatangulii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 35, 'Enyi wanadamu! Watakapowajia Mitume miongoni mwenu wakiwasimulia Ishara zangu, basi mwenye kumcha Mungu na akatengenea, haitakuwa hofu kwao, wala wao hawatahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 36, 'Na wale waliozikadhibisha Ishara zetu na wakazifanyia kiburi, hao ndio watu wa Motoni, wao humo watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 37, 'Basi ni nani dhalimu zaidi kuliko yule anayemzulia Mwenyezi Mungu uongo, au akazikadhibisha Ishara zake? Hao litawafikia fungu lao waliloandikiwa, mpaka watakapowajia wajumbe wetu kuwafisha, watawaambia: Wako wapi wale mliokuwa mkiwaomba badala ya Mwenyezi Mungu? Watasema: ''Wametupotea!'' Na watashuhudia dhidi yao wenyewe kwamba walikuwa makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 38, 'Mwenyezi Mungu atasema: Ingieni (Motoni) pamoja na umma zilizopita kabla yenu miongoni mwa majini na watu. Kila utakapoingia umma, utalaani dada yake. Mpaka watakapokusanyika wote humo, wa mwisho wao atasema juu ya wa mwanzo wao: Mola wetu Mlezi! Hawa ndio waliotupoteza. Basi wape adhabu ya Motoni maradufu. Atasema: Kila mmoja ana maradufu, lakini nyinyi hamjui tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 39, 'Na wa mwanzo wao atamwambia wa mwisho wao: Basi nyinyi pia hamkuwa na ubora wowote kuliko sisi. Basi onjeni adhabu kwa sababu ya yale mliyokuwa mkiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 40, 'Hakika wale waliozikadhibisha Ishara zetu na wakazifanyia kiburi, hawatafunguliwa milango ya mbingu, wala hawataingia Bustanini mle mpaka aingie ngamia katika tundu ya sindano. Na hivyo ndivyo tunavyowalipa wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 41, 'Wana kitanda chao katika Jahannamu, na juu yao nguo za moto za kujifunika. Na hivyo ndivyo tunavyowalipa madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 42, 'Na wale walioamini na wakatenda mema, hatuitwiki nafsi yoyote isipokuwa kwa kiasi cha uwezo wake. Hao ndio watu wa Bustanini. Wao watadumu humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 43, 'Na tutaondoa kilicho katika vifua vyao cha chuki, na chini yao itapita mito. Na watasema: Alhamdulillah (sifa njema ni za Mwenyezi Mungu), ambaye alituongoa kuyafikia haya. Wala hatukuwa wenye kuongoka wenyewe lau kuwa Mwenyezi Mungu hakutuongoa. Hakika Mitume wa Mola wetu Mlezi walikuja na haki. Na watanadiwa kwamba: Hiyo ndiyo Bustani mliyorithishwa kwa sababu ya yale mliyokuwa mkiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 44, 'Na watu wa Bustanini watawanadi watu wa Motoni, "Sisi tumeshakuta yale aliyotuahidi Mola wetu Mlezi kuwa ni kweli. Na je, nyinyi pia mmekuta yale aliyowaahidi Mola wenu Mlezi kuwa ni kweli?" Watasema: "Ndiyo!" Basi mtangazaji atatangaza kati yao kwamba, "Laana ya Mwenyezi Mungu iko juu ya madhalimu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 45, 'Wale wanaozuilia Njia ya Mwenyezi Mungu, na wanataka ipotoke, nao wanaikufuru Akhera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 46, 'Na baina yao (makundi mawili hayo) patakuwapo pazia. Na juu ya Minyanyuko patakuwa watu watakaomjua kila mmoja kwa alama zao, na wao watawaita watu wa Peponi: Salamu Alaykum (amani iwe juu yenu)! Wao bado hawajaingia humo, lakini wanatumai.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 47, 'Na yanapogeuzwa macho yao kuelekea watu wa Motoni, watasema: Mola wetu Mlezi! Usitujaalie kuwa pamoja na kaaumu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 48, 'Na watu hao wa Minyanyukoni watawaita watu wanaowajua kwa alama zao. Watasema: Kujumuika kwenu hakukuwafaa kitu, wala hicho mlichokuwa mnakifanyia kiburi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 49, 'Je, hawa ndio wale mliokuwa mkiwaapia kuwa Mwenyezi Mungu hatawafikishia rehema? Ingieni Peponi, hakuna hofu kwenu, wala hamtahuzunika!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 50, 'Na watu wa Motoni watawaita watu wa Bustanini: Tumiminieni maji, au chochote alichowaruzuku Mwenyezi Mungu. Nao watasema: Hakika Mwenyezi Mungu ameviharamisha hivyo kwa makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 51, 'Ambao waliifanya dini yao kuwa ni pumbao na mchezo, na maisha ya dunia yakawadanganya. Basi leo sisi tunawasahau kama walivyousahau mkutano wa Siku yao hii, na kwa sababu ya kule kuzikataa Ishara zetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 52, 'Na hakika tumewaletea Kitabu tulichokipambanua kwa elimu, uongofu na rehema kwa watu wenye kuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 53, 'Je, lipo wanalolingojea isipokuwa matokeo yake? Siku yatatapofika matokeo yake watasema wale waliokisahau: Kweli Mitume wa Mola Mlezi wetu walileta Haki! Je, tunao waombezi ili watuombee? Au turudishwe ili tufanye yasiyokuwa yale tuliyokuwa tukiyafanya? Bila ya shaka wamejihasiri nafsi zao, na yamewapotea waliyokuwa wakiyazua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 54, 'Hakika Mola wenu Mlezi ni Mwenyezi Mungu ambaye aliziumba mbingu na ardhi katika siku sita. Kisha akainuka akawa juu ya Kiti cha Enzi. Huufunika usiku kwa mchana, ufuatao upesi upesi. Na jua, na mwezi, na nyota zinazotumika kwa amri yake. Fahamuni! Ni kwake kuumba na amri. Mwenyezi Mungu ni Mwingi wa baraka, Mola Mlezi wa viumbe vyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 55, 'Muombeni Mola wenu Mlezi kwa unyenyekevu na kwa siri. Hakika Yeye hawapendi wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 56, 'Wala msifanye uharibifu katika dunia baada ya kutengenea kwake. Na mwombeni kwa hofu na kutumai. Hakika rehema ya Mwenyezi Mungu iko karibu na wafanyao uzuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 57, 'Na Yeye ndiye anayetuma pepo (za kuvuma) kuwa ni bishara kabla ya kufika rehema yake. Hata hizo pepo zinapobeba mawingu mazito, tunayapeleka kwenye nchi iliyokufa. Kisha tunateremsha kwayo maji, na tukatoa kwayo kila aina ya matunda. Basi namna hiyo ndivyo tunavyowafufua wafu, ili mkumbuke.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 58, 'Na ardhi nzuri mimea hutoka yake kwa idhini ya Mola Mlezi wake. Nayo ardhi ambayo ni mbaya haitoki isipokuwa mimea michache, isiyokuwa na faida, tena kwa shida. Na hivyo ndivyo tunavyozipambanua Ishara (Aya) kwa kaumu wanaoshukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 59, 'Hakika, tulimtuma Nuhu kwa kaumu yake, naye akasema: Enyi kaumu yangu! Muabuduni Mwenyezi Mungu. Nyinyi hamna Mungu ila Yeye. Hakika mimi ninawahofia adhabu ya Siku iliyo kuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 60, 'Wale watukufu katika kaumu yake wakasema: Hakika sisi tunakuona wewe umo katika upotovu ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 61, 'Akasema: Enyi watu wangu! Mimi siko katika upotovu, lakini mimi ni Mtume nitokaye kwa Mola Mlezi wa viumbe vyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 62, 'Nawafikishia Ujumbe wa Mola Mlezi wangu, na ninawanasihi; na ninayajua kwa Mwenyezi Mungu msiyoyajua nyinyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 63, 'Je, mnastaajabu kukujieni mawaidha yanayotoka kwa Mola Mlezi wenu kwa njia ya mtu ambaye ni mmoja wenu, ili akuonyeni na ili mumche Mungu, na ili mpate kurehemewa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 64, 'Basi walimkanusha. Nasi tukamwokoa yeye na waliokuwa pamoja naye katika jahazi. Na tukawazamisha wale waliozikanusha Ishara zetu. Hakika hao walikuwa watu vipofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 65, 'Na kwa ''Aadi tulimpeleka ndugu yao, Huud. Akasema: Enyi watu wangu! Muabuduni Mwenyezi Mungu. Nyinyi hamna mungu ila Yeye. Basi je, hamumchi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 66, 'Wakasema watukufu wa wale waliokufuru katika kaumu yake: Sisi tunakuona uko katika upumbavu, na hakika sisi tunakufikiria kuwa wewe ni katika waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 67, 'Akasema: Enyi watu wangu! Mimi sina upumbavu. Lakini mimi ni Mtume niliyetoka kwa Mola Mlezi wa viumbe vyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 68, 'Nawafikishia ujumbe wa Mola wangu Mlezi. Na mimi kwenu ni mwenye kuwanasihi, mwaminifu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 69, 'Mnaona ajabu kukufikieni mawaidha yanayotoka kwa Mola wenu Mlezi kwa mtu aliye mmoja wenu nyinyi ili awaonye? Na kumbukeni alivyokufanyeni mshike mahali pa kaumu ya Nuhu, na akawazidishia katika umbo. Basi zikumbukeni neema za Mwenyezi Mungu ili mpate kufanikiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 70, 'Wakasema: Je, umetujia ili tumuabudu Mwenyezi Mungu peke yake, na tuyaache waliyokuwa wakiyaabudu baba zetu? Basi tuletee hayo unayotuahidi, ikiwa wewe ni miongoni mwa wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 71, 'Akasema: Bila ya shaka adhabu na ghadhabu zimekwishakuwaangukia kutoka kwa Mola wenu Mlezi. Mnabishana nami kwa sababu ya majina tu mliyoyaita nyinyi na baba zenu ambayo kwayo Mwenyezi Mungu hakuteremsha uthibitisho? Basi ngojeni, mimi pia ni pamoja nanyi katika wanaongoja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 72, 'Basi tukamwokoa yeye na waliokuwa pamoja naye kwa rehema zetu, na tukaikata mizizi ya wale waliozikanusha Ishara zetu, na hawakuwa wenye kuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 73, 'Na kwa Thamud tulimpeleka ndugu yao, Swaleh. Akasema: Enyi watu wangu! Muabuduni Mwenyezi Mungu. Nyinyi hamna Mungu ila Yeye. Hakika imekwishawafikia Ishara iliyo wazi kutoka kwa Mola wenu Mlezi. Huyu ni ngamia jike wa Mwenyezi Mungu aliye Ishara kwenu. Basi mwacheni ale kwenye ardhi ya Mwenyezi Mungu, wala msimdhuru, isije kukushukieni adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 74, 'Na kumbukeni alivyowafanya wafuatizi (makhalifa) wa A’adi na akawaweka vizuri katika nchi, mnajenga majumba ya fakhari katika nyanda zake, na mnachonga majumba katika milima. Basi zikumbukeni neema za Mwenyezi Mungu wala msienee katika nchi kwa kufanya uharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 75, 'Waheshimiwa wa kaumu yake wanaojivuna waliwaambia wanaoonewa wenye kuamini miongoni mwao: Je, mnaitakidi ya kwamba Swaleh ametumwa na Mola wake Mlezi? Wakasema: Hakika sisi tunayaamini yale aliyotumwa nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 76, 'Wakasema wale wanaojivuna: Sisi tunayakataa hayo mnayoyaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 77, 'Basi wakamuua yule ngamia, na wakaiasi amri ya Mola Mlezi wao, na wakasema: Ewe Saleh! Tuletee unayotuahidi ikiwa wewe ni miongoni mwa Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 78, 'Basi tetemeko la ardhi likawanyakua, na kulipokucha wakawa majumbani mwao kifudifudi wamekwishakufa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 79, 'Basi Swaleh akawaacha na akasema: Enyi watu wangu! Niliwafikishia Ujumbe wa Mola wangu Mlezi, na nikawanasihi, lakini nyinyi hamuwapendi wanaonasihi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 80, 'Na Lut alipowaambia kaumu yake, "Je, mnafanya uchafu ambao hajawatangulia kwa huo yeyote katika walimwengu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 81, 'Hakika nyinyi mnawaingilia wanaume kwa shahawa na mnawaacha wanawake? Bali nyinyi ni watu wapitilizao!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 82, 'Na halikuwa jibu la kaumu yake isipokuwa walisema, "Watoeni kutoka katika mji wenu. Maana wao hakika ni watu wanaojitakasa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 83, 'Basi tukamwokoa yeye na ahali zake, isipokuwa mkewe, alikuwa miongoni mwa walioangamia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 84, 'Na tukawanyeshea mvua. Basi tazama jinsi ulivyokuwa mwisho wa wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 85, 'Na kwa (watu wa) Madyana tulimtuma ndugu yao Shu''aib. Akasema, "Enyi kaumu yangu! Muabuduni Mwenyezi Mungu. Hamna mungu yeyote isipokuwa Yeye. Hakika imekwishawajia hoja wazi kutoka kwa Mola wenu Mlezi. Basi timizeni sawasawa vipimo na mizani, wala msiwapunje watu vitu vyao, wala msifanye uharibifu katika ardhi baada ya kutengenea kwake. Hayo ndiyo bora kwenu ikiwa nyinyi ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 86, 'Wala msikae katika kila njia mkitishia, na mkiizuia njia ya Mwenyezi Mungu wale waliomuamini, na mkiitaka ipotoke. Na kumbukeni mlipokuwa wachache, naye akawafanya kuwa wengi. Na tazameni jinsi ulivyokuwa mwisho wa waharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 87, 'Na kama liko kundi miongoni mwenu lililoamini haya niliyotumwa nayo, na kundi lingine halikuamini, basi subirini mpaka Mwenyezi Mungu ahukumu baina yetu. Naye ndiye Mbora zaidi wa wenye kuhukumu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 88, 'Wakasema waheshimiwa waliotakabari katika kaumu yake, "Lazima tutakutoa ewe Shu''aib na wale walioamini pamoja nawe katika mji wetu, au lazima mtarejea katika mila yetu." Akasema, "Je, hata kama tunachukia?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 89, '"Bila ya shaka tutakuwa tumemzulia uongo Mwenyezi Mungu ikiwa tutarudi katika mila yenu baada ya Mwenyezi Mungu kwishatuokoa kutokana nayo. Wala haiwi kwetu sisi kuirejea mila hiyo, isipokuwa akitaka Mwenyezi Mungu, Mola wetu Mlezi. Mola wetu Mlezi umekienea kila kitu kwa elimu. Kwa Mwenyezi Mungu tumetegemea. Mola wetu Mlezi, hukumu baina yetu na kaumu yetu kwa haki, nawe ndiwe Mbora zaidi wa wanaohukumu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 90, 'Na wakasema waheshimiwa waliokufuru katika kaumu yake, "Mkimfuata Shu''aib, basi hakika nyinyi mtahasiri."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 91, 'Basi tetemeko la ardhi likawachukua, kwa hivyo wakawa katika makazi yao wameanguka kifudifudi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 92, 'Wale waliomkadhibisha Shu''aib ni kama kwamba hawakuishi humo. Wale waliomkadhibisha Shu''aib walikuwa ndio waliohasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 93, 'Basi akawaachilia mbali na akasema, "Enyi kaumu yangu! Hakika nimewafikishia jumbe za Mola wangu Mlezi, na nimewanasihi. Basi vipi niwahuzunikie kaumu makafiri?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 94, 'Na hatukumtuma katika mji wowote Nabii yeyote isipokuwa tuliwachukua wakazi wake kwa umaskini na maradhi ili wanyenyekee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 95, 'Kisha tukabadilisha pahali pa ubaya kwa wema, mpaka wakazidi, na wakasema, "Hakika ziliwafikia baba zetu taabu na raha." Basi tukawachukua kwa ghafla hali ya kuwa hawatambui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 96, 'Na lau kuwa watu wa miji wangeliamini na wakamcha Mungu, basi hakika tungeliwafungulia baraka za kutoka mbinguni na ardhini. Lakini walikadhibisha, basi tukawachukua kwa sababu ya yale waliyokuwa wakiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 97, 'Je, wakazi wa mijini wana amani ya kuwa iwajie adhabu yetu usiku hali ya kuwa wamelala?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 98, 'Au wakazi wa mijini wana amani ya kuwa iwajie adhabu yetu mchana hali ya kuwa wanacheza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 99, 'Je, wana amani dhidi ya mipango ya Mwenyezi Mungu? Kwani hawawi na amani dhidi ya mipango ya Mwenyezi Mungu isipokuwa kaumu waliohasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 100, 'Kwani haijawabainikia wale wanaoirithi ardhi baada ya waliokuwa wenyewe kwamba tukitaka tunawasibu kwa madhambi yao, na tukaziba nyoyo zao, kwa hivyo hawatasikia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 101, 'Miji hiyo, tunakusimulia katika habari zake. Na hakika waliwajia Mitume wao na hoja zilizo waziwazi. Lakini hawakuwa wenye kuamini yale waliyoyakadhibisha zamani. Namna hivi ndivyo Mwenyezi Mungu anavyoziba nyoyo za makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 102, 'Wala hatukuwapata wengi wao wakiwa ni wenye kushika agano lolote, bali kwa hakika tuliwapata wengi wao ni wavukao mno mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 103, 'Kisha tukamtuma baada yao Musa na Ishara zetu kwa Firauni na waheshimiwa wake. Nao wakazifanyia dhuluma. Basi tazama namna ulivyokuwa mwisho wa waharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 104, 'Na Musa akasema, "Ewe Firauni! Hakika mimi ni Mtume kutoka kwa Mola Mlezi wa walimwengu wote', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 105, 'Inastahiki zaidi juu yangu kwamba nisiseme juu ya Mwenyezi Mungu isipokuwa haki tu. Hakika nimewajia na Ishara za waziwazi kutoka kwa Mola wenu Mlezi. Basi waachilie pamoja nami Wana wa Israili."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 106, 'Akasema (Firauni), "Ikiwa umekuja na ishara yoyote, basi ilete ikiwa wewe ni katika wakweli."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 107, 'Basi akaitupa fimbo yake, na tazama, ikawa joka lililo dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 108, 'Na akautoa nje mkono wake, na tazama ulikuwa mweupe kwa watazamao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 109, 'Wakasema waheshimiwa kutoka katika kaumu ya Firauni, "Hakika huyu ni mchawi ajuaye vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 110, 'Anataka kuwatoa katika nchi yenu. Basi mnaamrisha nini?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 111, 'Wakasema: Mwache kidogo yeye na kaka yake, na watume mijini wakusanyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 112, 'Wakujie na kila mchawi ajuaye vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 113, 'Na wachawi wakamjia Firauni, wakasema: Hakika tutapata ujira ikiwa tutakuwa sisi ndio washindi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 114, 'Akasema: Ndiyo! Nanyi bila ya shaka ni katika waliotiwa karibu nami.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 115, 'Wakasema: Ewe Musa! Ima utupe wewe, au tuwe sisi ndio watupao?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 116, 'Akasema: Tupeni! Basi walipotupa, waliyafanyia uchawi macho ya watu na wakawatia hofu, na wakaleta uchawi mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 117, 'Nasi tukamfunulia Musa kumwambia: Itupe fimbo yako, na tazama, ikawa inavimeza vyote vile walivyovizulia uongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 118, 'Basi haki ikathibiti na yakabatilika yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 119, 'Kwa hivyo wakashindwa huko, na wakageuka kuwa wadogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 120, 'Na wachawi wakajitupa chini wakasujudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 121, 'Wakasema: Tumemuamini Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 122, 'Mola Mlezi wa Musa na Harun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 123, 'Akasema Firauni: Mmemuamini kabla mimi kuwapa idhini? Hakika, hii ni njama mliyoipangia huko mjini ili muwatoe humo wenyewe. Basi karibu mtajua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 124, 'Lazima nitaikata mikono yenu na miguu yenu kwa kutofautisha. Kisha lazima nitawasulubisha nyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 125, 'Wakasema: Hakika sisi ni wenye kurejea kwa Mola wetu Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 126, 'Nawe hutushutumu kwa chuki isipokuwa kwa kuwa tumeziamini Ishara za Mola wetu Mlezi pindi zilipotujia. Ewe Mola wetu Mlezi! Tumiminie subira na utufishe hali ya kuwa ni Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 127, 'Na wakasema waheshimiwa kutoka kwa kaumu ya Firauni: Je, unamuacha Musa na kaumu yake ili wafanye uharibifu katika ardhi na akuache wewe na miungu yako? Akasema: Tutawaua sana wavulana wao, na tuwaache hai wanawake wao. Na bila ya shaka sisi ni wenye nguvu juu yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 128, 'Musa akawaambia kaumu yake: Ombeni msaada kwa Mwenyezi Mungu, na subirini. Hakika ardhi ni ya Mwenyezi Mungu, anairithisha amtakaye katika waja wake. Na mwisho mwema ni wa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 129, 'Wakasema: Tumeudhiwa kabla wewe kutujia, na baada ya wewe kutujia! Musa akasema: Huenda Mola wenu Mlezi akamuangamiza adui wenu, na akawafanya nyinyi ndio wa kufuatia kushika ardhi, ili atazame mtakavyokujatenda nyinyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 130, 'Na hakika tuliwachukua watu wa Firauni kwa miaka (ya ukame), na kwa upungufu katika mazao, huenda wakakumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 131, 'Basi wakijiwa na zuri, wanasema, "Ni haki yetu hii." Na likiwasibu ovu, wanaona mkosi kwa Musa na wale walio pamoja naye. Tazama! Hakika mkosi wao huo unatoka kwa Mwenyezi Mungu. Lakini wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 132, 'Na walisema, "Hata ukitujia na Ishara zozote zile kutufanyia uchawi kwazo, basi sisi hatutakuamini."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 133, 'Basi tukawatumia tufani, na nzige, na chawa, na vyura, na damu, ziwe ni Ishara za kina. Lakini wakatakabari, na wakawa kaumu wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 134, 'Na ilipowaangukia adhabu, wakasema, "Ewe Musa! Tuombee kwa Mola wako Mlezi kwa yale aliyokuahidi. Ukituondolea adhabu hii, hakuna shaka tutakuamini, na tutawaachilia Wana wa Israili waende pamoja nawe."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 135, 'Basi tulipowaondolea adhabu mpaka muda fulani wao waufikie, tazama! Wakavunja ahadi yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 136, 'Basi tukawaadhibu, tukawazamisha katika bahari kwa sababu walizikadhibisha Ishara zetu, na wakawa wanaghafilika mbali nazo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 137, 'Na tukawarithisha kaumu wale waliokuwa wakidhoofishwa, mashariki ya ardhi na magharibi yake ambayo tulibariki ndani yake. Na likatimia neno jema la Mola wako Mlezi juu ya Wana wa Israili, kwa vile walivyosubiri. Na tukayaangamiza yale aliyokuwa akiyafanya Firauni na kaumu yake, na yale waliyokuwa wakiyajenga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 138, 'Na tukawavusha bahari Wana wa Israili, kisha wakajia kaumu waliokuwa wanayaabudu masanamu yao. Wakasema, "Ewe Musa! Tufanyie mungu kama hawa walivyo na miungu." Musa akasema: Hakika nyinyi ni kaumu msiojua kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 139, 'Hakika hawa, haya waliyomo yatakujaangamia, na ni batili hayo waliyokuwa wakiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 140, 'Akasema, "Je, niwatafutie mungu asiyekuwa Mwenyezi Mungu, ilhali Yeye ndiye aliyewaboresha kuliko walimwengu wote?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 141, 'Na pale tulipowaokoa kutoka kwa watu wa Firauni waliowatia adhabu mbaya zaidi. Wakiwaua wavulana wenu, na wakiwaacha hai wanawake wenu. Na katika hayo yalikuwa majaribio makubwa kutoka kwa Mola wenu Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 142, 'Na tulimuahidi Musa usiku thelathini na tukazitimiza kwa kumi; basi ikatimia miadi ya Mola wake Mlezi usiku arobaini. Na Musa akamwambia kaka yake, Harun: Shika pahali pangu katika kaumu yangu na utengeneze, wala usifuate njia ya waharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 143, 'Na alipokuja Musa kwenye miadi yetu, na Mola wake Mlezi akamuongelesha, alisema: Mola wangu Mlezi! Nionyeshe nikutazame. Mwenyezi Mungu akasema: Hutaniona. Lakini utazame huo mlima. Ikiwa utabaki mahali pake, basi utaniona. Basi alipojionyesha Mola wake Mlezi kwa mlima huo, akaufanya upasukepasuke, na Musa akaanguka chini akazimia. Basi alipozindukana, akasema: Subhanaka (Umetakasika)! Nimetubia kwako, na mimi ni wa kwanza wa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 144, '(Mwenyezi Mungu) akasema: Ewe Musa! Hakika Mimi nilikuteua uende kwa watu na jumbe zangu na maneno yangu. Basi chukua hayo niliyokupa na kuwa katika wanaoshukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 145, 'Na tukamuandikia kwenye mbao zile katika kila kitu, mawaidha na maelezo ya kina ya kila kitu. (Tukamwambia): Basi yachukue kwa nguvu na uwaamrishe kaumu yako wayachukue kwa ubora wake. Nami nitawaonyesha makazi ya wale waliovuka mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 146, 'Nitawaepusha na Ishara zangu wale wanaotakabari katika ardhi bila ya haki. Na wao wakiona kila Ishara, hawaiamini. Wakiiona njia ya uwongofu, hawaichukui kuwa ndiyo njia. Lakini wakiiona njia ya ukengeufu, wanaichukua kuwa ndiyo njia. Hayo ni kwa sababu walizikadhibisha Ishara zetu, na walikuwa wakighafilika mbali nazo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 147, 'Na wale waliozikadhibisha Ishara zetu na kukutana na Akhera, matendo yao yameharibika. Kwani watalipwa isipokuwa yale waliyokuwa wakiyatenda?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 148, 'Na kaumu ya Musa wakamfanya baada yake kutoka katika mapambo yao ndama mwenye kiwiliwili, mwenye kutoa mlio wa ng''ombe. Kwani hawakuona kuwa hawasemeshi wala hawaongoi njia yoyote? Walimchukua (kumuabudu), na wakawa madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 149, 'Na wakati mambo yalipoangushwa katika mikono yao, na wakaona ya kwamba wamekwishapotea, wakasema: Ikiwa Mola wetu Mlezi hataturehemu na akatufutia dhambi, basi bila ya shaka tutakuwa miongoni mwa waliohasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 150, 'Na wakati aliporudi Musa kwa kaumu yake hali ya kuwa ameghadhibika na kuhuzunika, akasema: Ni mabaya mno mliyonifanyia nyuma yangu! Je, mmeiharakisha amri ya Mola wenu Mlezi? Na akazitupa chini mbao zile, na akamkamata kaka yake kichwa akimvuta kwake. (Harun) akasema: Ewe mwana wa mama yangu! Hakika kaumu hawa waliniona kuwa mimi ni dhaifu, na walikaribia kuniua. Basi usiwafurahishe maadui zangu, wala usiniweke pamoja na kaumu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 151, '(Musa) akasema: Mola wangu Mlezi! Nifutie dhambi mimi na kaka yangu, na utuingize katika rehema yako. Nawe ni Mwenye kurehemu zaidi kuliko wote wenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 152, 'Hakika wale waliojifanyia (na kumuabudu) ndama, itawapata ghadhabu kutoka kwa Mola wao Mlezi, na udhalilifu katika maisha ya dunia. Na hivyo ndivyo tunavyowalipa wazuao uongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 153, 'Na wale waliotenda mabaya, kisha wakatubia baada yake na wakaamini, hakika Mola wako Mlezi baada ya hayo ni Mwenye kufuta dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 154, 'Na wakati ghadhabu ilipomtulia Musa, akazichukua mbao zile. Na katika maandiko yake kuna uongofu na rehema kwa wale ambao wanamhofu Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 155, 'Na Musa akawateua kaumu wake wanaume sabini kwa ajili ya miadi yetu. Na ulipowachukua mtetemeko mkubwa, akasema: Mola wangu Mlezi! Ungelitaka, ungeliwaangamiza wao hapo kabla na hata mimi. Unatuangamiza kwa yale waliyoyafanya wapumbavu katika sisi? Haya si chochote isipokuwa ni majaribio yako, unampoteza kwayo umtakaye, na unamuongoa umtakaye. Wewe ndiye rafiki mlinzi wetu. Basi tusitiri dhambi na uturehemu. Na Wewe ndiwe Mbora zaidi wa wasitirio dhambi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 156, 'Na tuandikie mazuri katika dunia hii na katika Akhera. Hakika sisi tumerejea kwako. (Mwenyezi Mungu) akasema: Adhabu yangu nitamsibu kwayo nimtakaye. Na rehema yangu imeenea kila kitu. Basi nitaiandika hii hasa kwa wale wanaomcha Mungu, na wanaotoa Zaka, na wale ambao wanaziamini Ishara zetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 157, 'Wale ambao wanamfuata huyo Mtume, Nabii, asiyesoma wala kuandika, ambaye wanamkuta ameandikwa kwao katika Taurati na Injili, anayewaamrisha mema na anawakataza maovu, na anawahalalishia vizuri, na anawaharamishia viovu, na anawaondolea mizigo yao na minyororo ambayo ilikuwa juu yao. Basi wale waliomwamini yeye, na wakampa taadhima, na wakamnusuru, na wakaifuata nuru ambayo iliteremshwa pamoja naye, hao ndio waliofaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 158, 'Sema: Enyi watu! Hakika mimi ni Mtume wa Mwenyezi Mungu kwenu nyinyi nyote, Yeye ambaye ni wake ufalme wa mbingu na ardhi. Hakuna mungu isipokuwa Yeye. anahuisha na anafisha. Basi mwaminini Mwenyezi Mungu na Mtume wake, Nabii asiyejua kusoma na kuandika, ambaye anamwamini Mwenyezi Mungu na maneno yake. Na mfuateni yeye ili muongoke.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 159, 'Na katika kaumu ya Musa upo umma unaowaongoa watu kwa haki, na kwayo wanafanya uadilifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 160, 'Na tukawakatakata makabila kumi na mawili, mataifa mbali mbali. Na tulimfunulia Musa wakati kaumu yake walipomwomba maji kwamba: ''Lipige hilo jiwe kwa fimbo yako.'' Mara zikabubujika kutoka humo chemchemi kumi na mbili, na kila watu wakajua pahali pao pa kunywea. Na tukawafunikia kivuli kwa mawingu, na tukawateremshia Manna na Salwa. ''Kuleni katika vizuri hivi tulivyowaruzuku.'' Na hawakutudhulumu Sisi, bali walikuwa wakijidhulumu wenyewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 161, 'Na pale walipoambiwa: Ukaeni mji huu, na mle humo popote mpendapo, na semeni: ''Tufutie dhambi zetu.'' Na uingieni mlango wake kwa kusujudu, tutawasitiria makosa yenu. Walio wema tutawazidishia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 162, 'Lakini wakabadilisha wale waliodhulumu miongoni mwao kauli isiyo ile waliyoambiwa. Basi tukawatumia adhabu kutoka mbinguni kwa vile walivyokuwa wakidhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 163, 'Na waulize kuhusu kijiji kilichokuwa kando ya bahari, walipokuwa wakiivunja Sabato (Jumaamosi ya mapumziko). Walipokuwa samaki wakiwajia juu juu siku ya Sabato, na siku isiyokuwa ya Sabato hawawajii. Kwa namna hiyo tuliwajaribu kwa sababu walikuwa wakivuka mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 164, 'Na kikundi miongoni mwao walisema: Kwa nini mnawawaidhi watu ambao tangu hapo Mwenyezi Mungu atawaangamiza au atawaadhibu adhabu kali? Wakasema: Ili uwe ni udhuru kwa Mola wenu Mlezi, na huenda nao wakamcha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 165, 'Basi walipoyasahau yale waliyokumbushwa kwayo, tukawaokoa wale waliokuwa wakikataza mabaya, na tukawachukua wale waliodhulumu kwa adhabu mbaya mno kwa vile walivyokuwa wakivuka mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 166, 'Walipotakabari na kuasi yale waliyokatazwa, tukawaambia, "Kuweni manyani, mliodharauliwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 167, 'Na pale alipotangaza Mola wako Mlezi kwamba hakuna shaka atawaletea watu ambao watawaadhibu kwa adhabu mbaya mpaka Siku ya Kiyama. Hakika Mola wako Mlezi ni Mwepesi wa kuadhibu, na bila ya shaka ni Mwenye maghfira, na Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 168, 'Na tukawagawanya katika ardhi umma mbalimbali. Miongoni mwao kuna wale walio wema, na miongoni mwao kuna walio kinyume cha hivyo. Na tukawajaribu kwa mazuri na mabaya huenda wakarejea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 169, 'Basi wakafuatia baada yao wafuatizi waliokirithi Kitabu. Wanachukua anasa za haya maisha duni, na wanasema, "Tutasitiriwa dhambi!" Na ikiwajia tena anasa mfano wake, wanaichukua pia. Je, halikuchukuliwa juu yao agano la Kitabu kuwa wasiseme juu ya Mwenyezi Mungu isipokuwa haki tu? Nao wamekwishasoma yale yaliyo humo. Na nyumba ya Akhera ni bora zaidi kwa wachao. Basi je, hamtii akilini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 170, 'Na wale wanaokikamata sawasawa Kitabu, na wakasimamisha Swala, hakika Sisi hatupotezi ujira wa watengenezao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 171, 'Na pale tulipounyanyua mlima juu yao ukawa kama kwamba ni kiwingu kilichowafunika, na wakadhani kuwa utawaangukia, (tukawaambia): Chukueni yale tuliyowapa kwa nguvu, na yakumbukeni yaliyo ndani yake ili mche.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 172, 'Na pale Mola wako Mlezi alipochukua kutoka kwa wanadamu kutoka katika migongo yao dhuria zao na akawashuhudisha juu ya nafsi zao (na kuwaambia), "Je, mimi si Mola wenu Mlezi?" Wakasema, "Ndiyo, tumeshuhudia." Mje mkasema Siku ya Kiyama, "Hakika sisi tulikuwa tumeghafilika mbali na haya."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 173, 'Au mkasema: Hakika baba zetu ndio walioshirikisha kabla yetu, na sisi ni dhuriya zao tu baada yao. Basi utatuangamiza kwa sababu ya waliyoyafanya wapotovu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 174, 'Na ndiyo kama hivyo tunavyozieleza Ishara kwa kina, ili huenda wakarejea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 175, 'Na wasomee habari za yule ambaye tulimpa Ishara zetu, naye akajivua kutoka kwazo, basi Shetani akamfuata. Kwa hivyo, akawa miongoni mwa waliopotea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 176, 'Na lau kuwa tungelitaka, tungelimwinua kwazo, lakini yeye alizama katika ulimwengu na akafuata matamanio yake. Basi mfano wake ni kama mfano wa mbwa. Ukimhujumu hupumua na kutoa ulimi nje, na ukimwacha, pia hupumua na kutoa ulimi nje. Huo ni mfano wa kaumu ambao walizikadhibisha Ishara zetu. Basi simulia hadithi, huenda wakatafakari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 177, 'Mfano mbaya zaidi ni wa kaumu waliozikadhibisha Ishara zetu na walikuwa wakizidhulumu nafsi zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 178, 'Yule ambaye Mwenyezi Mungu amemuongoa, basi huyo ndiye mwongofu. Na yule aliyempoteza, basi hao ndio waliohasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 179, 'Na hakika tumeiumbia Jahannamu wengi katika majini na watu. Wana nyoyo wasizofahamu kwazo. Na wana macho wasiyoona kwayo. Na wana masikio wasiyosikia kwayo. Hao ni kama wanyama wa mifugo, bali wao ni wapotovu zaidi. Hao ndio walioghafilika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 180, 'Na Mwenyezi Mungu ana majina mazuri kabisa, basi muombeni kwayo. Na waacheni wale wanaopindukia mipaka katika majina yake. Watakujalipwa yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 181, 'Na katika wale tuliowaumba wako umma wanaoongoza kwa haki, na kwayo wanafanya uadilifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 182, 'Na wale waliokadhibisha Ishara zetu, tutawapeleka katika maangamio pole pole kutokea pale wasipojua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 183, 'Nami nitawapa muda. Hakika mpango wangu ni madhubuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 184, 'Je, hawafikirii? Huyu mwenzao hana wazimu. Yeye siyo isipokuwa ni mwonyaji aliye dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 185, 'Je, hawatazami ufalme wa mbingu na ardhi, na vile vyote alivyoviumba Mwenyezi Mungu katika vitu, na kwamba huenda muda wao umekwishakaribia? Basi maneno gani baada ya haya watayaamini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 186, 'Yule Mwenyezi Mungu alimpoteza, basi hana wa kumwongoa. Na atawaacha hao katika upotovu wao wakitangatanga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 187, 'Wanakuuliza kuhusu hiyo Saa (ya Kiyama) kusimama kwake ni lini? Sema: Elimu yake iko kwa Mola wangu Mlezi. Haidhihirishi hiyo kwa wakati wake isipokuwa Yeye. Ni nzito katika mbingu na ardhi. Haitawajia isipokuwa kwa ghafla tu. Wanakuuliza kama kwamba wewe una pupa ya kuijua. Sema: Elimu yake iko tu kwa Mwenyezi Mungu. Lakini wengi wa watu hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 188, 'Sema: Siimilikii nafsi yangu manufaa wala madhara, isipokuwa apendavyo Mwenyezi Mungu. Na lau kuwa ninayajua ya ghaibu, ningalitenda mema sana, wala ubaya usingenigusa. Mimi si chochote ila ni mwonyaji na mbashiri kwa kaumu wanaoamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 189, 'Yeye ndiye aliyewaumba kutoka katika nafsi moja; na katika hiyo hiyo akamfanya mwenzi wake, ili ajitulize kwake. Na alipomuingilia, akabeba mimba nyepesi, akitembea nao. Anapokuwa mjamzito, wote wawili humwomba Mwenyezi Mungu, Mola wao Mlezi: Kama ukitupa mwana mwema hakika tutakuwa katika wanaoshukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 190, 'Basi alipowapa mwana mwema, wakamfanyia washirikina Mwenyezi Mungu katika kile kile alichowapa. Basi Mwenyezi Mungu ametukuka na huko kushirikisha kwao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 191, 'Ati wanashirikisha kisichoumba kitu, hali ya kuwa wao wanaumbwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 192, 'Wala hawawezi kuwanusuru wala wao wenyewe hawajinusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 193, 'Na mkiwaita kwenye uongofu, hawawafuati. Ni mamoja kwenu ikiwa mtawaita au mkae kimya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 194, 'Hakika wale mnaowaomba badala ya Mwenyezi Mungu ni waja mfano wenu nyinyi. Basi waombeni, nao wawaitikie ikiwa nyinyi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 195, 'Je, wao wanayo miguu wanayotembea kwayo? Au wanayo mikono wanayokamata kwa nguvu kwayo? Au wanayo macho wanayoona kwayo? Au wanayo masikio wanayosikia kwayo? Sema: Waiteni washirika wenu hao, kisha nifanyieni mimi njama, na wala msinipe muhula.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 196, 'Hakika Mlinzi wangu ni Mwenyezi Mungu ambaye aliteremsha Kitabu. Naye ndiye anayewalinda walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 197, 'Na wale mnaowaomba badala ya Mwenyezi hawawezi kuwanusuru, wala hawajinusuru wao wenyewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 198, 'Na mkiwaita kwenye uongofu, hawasikii. Na utawaona wanakutazama hali ya kuwa hawaoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 199, 'Chukua yaliyo mepesi (katika matendo yao), na amrisha mema, na jitenge na majahili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 200, 'Na kama uchochezi kutoka kwa Shetani utakuchochea, basi tafuta ulinzi wa Mwenyezi Mungu. Hakika Yeye ni Msikizi mzuri, Mwenye kujua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 201, 'Hakika wale wamchao Mungu, zinapowagusa pepesi kutoka kwa Shetani, mara huzindukana na hapo huwa wenye kuiona haki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 202, 'Na ndugu zao wanawavutia kwenye upotovu, kisha wao hawaachi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 203, 'Na usipowajia na Ishara, wanasema: Kwa nini hukuibuni? Sema: hakika mimi ninafuata tu yale yanayofunuliwa kwangu kutoka kwa Mola wangu Mlezi. Hii (Qur''ani) ni hoja zinazotoka kwa Mola wenu Mlezi, na uongofu, na rehema kwa kaumu wanaoamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 204, 'Na inaposomwa Qur-ani, basi isikilizeni na mnyamaze ili mrehemewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 205, 'Na mkumbuke Mola wako Mlezi katika nafsi yako kwa unyenyekevu na hofu, na bila ya kuinua sauti juu kwa kauli, asubuhi na jioni, wala usiwe miongoni wa walioghafilika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 206, 'Hakika wale walio kwa Mola wako Mlezi hawajivuni wakaacha kumuabudu, na wanamtakasa, na wanamsujudia Yeye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 1, 'Wanakuuliza juu ya ngawira. Sema: Ngawira ni ya Mwenyezi Mungu na Mtume. Basi mcheni Mwenyezi Mungu na suluhisheni mambo baina yenu, na mtiini Mwenyezi Mungu na Mtume wake ikiwa nyinyi ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 2, 'Hakika Waumini ni wale ambao anapotajwa Mwenyezi Mungu, nyoyo zao zinaingia hofu. Na wanaposomewa Aya zake, zinawazidishia Imani, na wakamtegemea Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 3, 'Wale wanaosimamisha Swala, na wanatoa katika vile tunavyowaruzuku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 4, 'Hao ndio Waumini wa uhakika. Wana vyeo kwa Mola wao Mlezi, na kusitiriwa dhambi, na riziki tukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 5, 'Kama alivyokutoa Mola wako Mlezi katika nyumba yako kwa haki, na hakika kundi moja katika Waumini linachukia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 6, 'Wanakujadili kuhusu haki baada ya kwisha bainika, kama kwamba wanasukumwa kwenye mauti hali ya kuwa wanatazama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 7, 'Na Mwenyezi Mungu alipowaahidi moja ya vikundi vile viwili kuwa ni chenu. Nanyi mkapenda kwamba kile kisichokuwa kikali ndicho kiwe chenu. Naye Mwenyezi Mungu anataka ahakikishe haki kwa maneno yake, na aikate mizizi ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 8, 'Ili aihakikishe haki na aibatilishe batili hata kama watachukia wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 9, 'Mlipokuwa mnamuomba msaada Mola wenu Mlezi, naye akawaitikia kuwa Mimi hakika nitawasaidia kwa elfu moja miongoni mwa Malaika wakifuatana mfululizo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 10, 'Na Mwenyezi Mungu hakufanya hayo isipokuwa yawe ni bishara na ili nyoyo zenu zitue kwayo. Na nusura haiwi isipokuwa kutoka kwa Mwenyezi Mungu. Hakika Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 11, 'Alipowafunika kwa usingizi uwe ni amani kutoka kwake, na akawateremshia maji kutoka mbinguni ili awasafishe kwayo na awaondolee uchafu wa Shetani, na ili azifunge nyoyo zenu, na aimarishe kwayo miguu yenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 12, 'Mola wako Mlezi alipowafunulia Malaika: Hakika Mimi niko pamoja nanyi, basi watieni nguvu wale walioamini. Nitatupa woga katika nyoyo za wale waliokufuru. Basi wapigeni juu ya shingo na wapigeni kwenye kila ncha za vidole.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 13, 'Hayo ni kwa sababu walimuasi Mwenyezi Mungu na Mtume wake. Na mwenye kumuasi Mwenyezi Mungu na Mtume wake, basi hakika Mwenyezi Mungu ni Mkali wa kuadhibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 14, 'Ndivyo hivyo! Basi ionjeni! Na bila ya shaka makafiri wana adhabu ya Moto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 15, 'Enyi Mlioamini! Mnapokutana na wale waliokufuru vitani, msiwageuzie migongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 16, 'Na atakayewageuzia mgongo wake siku hiyo, isipokuwa kwa mbinu za vita au kuungana na kikosi, basi hakika atakuwa amestahiki ghadhabu ya Mwenyezi Mungu. Na pahali pake ni Jahannam, na hayo ndiyo marejeo mabaya kabisa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 17, 'Kwa hivyo, hamkuwaua nyinyi, lakini Mwenyezi Mungu ndiye aliyewaua. Nawe hukutupa ulipotupa, lakini Mwenyezi Mungu ndiye aliyetupa, na ili awajaribu Waumini majaribio mazuri kutoka kwake. Hakika Mwenyezi Mungu ni Mwenye kusikia vyema, Mwenye kujua yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 18, 'Hayo! Na kwamba hakika Mwenyezi Mungu ni Mwenye kudhoofisha njama za makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 19, 'Mkiomba msaada wa ushindi, basi msaada wa ushindi ulikwishawajia. Na mkikomeka, basi hilo ndilo heri kwenu. Na mkirejea, Sisi pia tutarejea. Na kundi lenu halitawanufaisha kitu hata kama yatakuwa (makundi) mengi. Kwani hakika Mwenyezi yu pamoja na Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 20, 'Enyi mlioamini! Mtiini Mwenyezi Mungu na Mtume wake, wala msigeuke mkamuacha hali ya kuwa mnasikia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 21, 'Wala msiwe kama wale wanaosema, "Tumesikia" na hali hawasikii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 22, 'Hakika waovu mno wa wanyama wote mbele ya Mwenyezi Mungu ni wale viziwi, na mabubu wasiotumia akili zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 23, 'Na Mwenyezi Mungu angelijua heri yoyote ndani yao, angewasikilizisha, na lau angewasikilizisha, wangeligeuka hali ya kuwa wamepuuza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 24, 'Enyi mlioamini! Muitikieni Mwenyezi Mungu na Mtume anapowaitia yale yenye kuwahuisha. Na jueni kuwa Mwenyezi Mungu huzuia kati ya mtu na moyo wake, na kwamba hakika kwake Yeye mtakusanywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 25, 'Na jikingeni kutokana na mtihani ambao hautawasibu wale waliodhulumu pekee miongoni mwenu. Na jueni kuwa Mwenyezi Mungu ni Mkali wa kuadhibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 26, 'Na kumbukeni mlipokuwa wachache, mkidhoofishwa katika ardhi, mkiogopa kwamba watu watawanyakua, naye akawapa pahali pazuri pa kukaa, na akawaunga mkono kwa nusura yake, na akawaruzuku katika vilivyo vizuri ili mshukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 27, 'Enyi mlioamini! Msimhini Mwenyezi Mungu na Mtume, na mkahini amana zenu, hali ya kuwa mnajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 28, 'Na jueni ya kwamba mali zenu na wana wenu ni mtihani, na kwamba Mwenyezi Mungu ana ujira mkubwa kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 29, 'Enyi mlioamini! Mkimcha Mwenyezi Mungu, atawapa kipambanuo, na atawasitiria mabaya yenu, na awafutie dhambi, na Mwenyezi Mungu ndiye Mwenye fadhila kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 30, 'Na walipokupangia vitimbi wale waliokufuru ili wakufunge, au wakuue, au wakutoe. Na wakapanga vitimbi vyao, naye Mwenyezi Mungu akapanga vitimbi vyake. Na Mwenyezi Mungu ndiye mbora wa wapangao vitimbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 31, 'Na wanaposomewa Aya zetu, wao husema: Hakika tumesikia. Lau tungetaka, tungesema mfano wa haya. Haya si chochote isipokuwa ngano za wa mwanzo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 32, 'Na waliposema: Ewe Mwenyezi Mungu! Ikiwa haya ndiyo haki kutoka kwako, basi tunyeshee mawe kutoka mbinguni, au tujie na adhabu yoyote iliyo chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 33, 'Na Mwenyezi Mungu hakuwa wa kuwaadhibu hali ya kuwa uko miongoni mwao, na Mwenyezi Mungu hakuwa mwenye kuwaadhibu hali ya kuwa wanaomba msamaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 34, 'Lakini wana nini hata Mwenyezi Mungu asiwaadhibu, na hali ya kuwa wanawazuilia watu Msikiti Mtakatifu, wala wao hawakuwa ndio walinzi wake? Bali walinzi wake si isipokuwa wacha Mungu tu, lakini wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 35, 'Na hakukuwa kuswalia kwao kwenye hiyo Nyumba (Al-Kaaba) isipokuwa ni kupiga miunzi na makofi. Basi onjeni adhabu kwa vile mlivyokuwa mkikufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 36, 'Hakika wale waliokufuru hutoa mali zao ili waizuilie Njia ya Mwenyezi Mungu. Basi watazitoa, kisha zitakuwa majuto juu yao, kisha watashindwa. Na wale waliokufuru watakusanywa kwenye Jahannam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 37, 'Ili Mwenyezi Mungu awapambanue waovu kutokana na wazuri, na awaweke waovu juu ya waovu wengine, na awarundike wote pamoja, na awatie katika Jahannam. Hao ndio waliohasirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 38, 'Waambie wale waliokufuru ikiwa watakoma, watasitiriwa yale yaliyokwisha pita. Na wakiyarudia, basi hakika imekwisha pita mifano ya wa mwanzo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 39, 'Na piganeni nao mpaka kusiwepo majaribio na Dini yote iwe kwa ajili ya Mwenyezi Mungu. Lakini wakiacha, basi hakika Mwenyezi Mungu anayaona vyema wanayayatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 40, 'Na kama wakigeuka basi jueni kwamba Mwenyezi Mungu ndiye Mola wenu, ni Mola Mwema na Msaidizi Mwema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 41, 'Na jueni ya kwamba ngawira yoyote mnayoipata, basi humusi yake ni ya Mwenyezi Mungu na ni ya Mtume, na ni ya jamaa, na mayatima, na masikini, na wasafiri, ikiwa nyinyi mlimwamini Mwenyezi Mungu na yale tuliyoyateremsha kwa mja wetu siku ya kipambanuo, siku yalipokutana makundi yale mawili. Na Mwenyezi Mungu ni Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 42, 'Kumbukeni pale mlipokuwa nyinyi kwenye ng''ambo ya karibu ya bonde, na wao wakawa kwenye ng''ambo ya mbali, na msafara ulipokuwa chini yenu. Na ingelikuwa mliagana, basi mngelihitilafiana katika miadi. Lakini (mkakutana) ili Mwenyezi Mungu atimize jambo liliokuwa lazima litendwe. Ili aangamie wa kuangamia kwa ushahidi ulio wazi, na asalimike wa kusalimika kwa ushahidi ulio wazi. Na hakika Mwenyezi Mungu ni Mwenye kusikia vyema, Mwenye kujua yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 43, 'Kumbuka Mwenyezi Mungu alipokuonyesha wao katika usingizi wako kwamba wao ni wachache, na lau angelikuonyesha kuwa ni wengi, basi mngeliingiwa na woga, na mngelizozana katika jambo hilo. Lakini Mwenyezi Mungu akawapa salama. Hakika Yeye ni Mwenye kuyajua vyema yaliyo vifuani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 44, 'Na alipowaonyesha mlipokutana, katika macho yenu kuwa wao ni wachache, na akawafanya nyinyi ni wachache katika macho yao, ili Mwenyezi Mungu atimize jambo lililokuwa lifanywe. Na kwa Mwenyezi Mungu yatarejeshwa mambo yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 45, 'Enyi mlioamini! Mkikutana na kikundi, basi kueni imara, na mkumbukeni Mwenyezi Mungu sana ili mfaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 46, 'Na mtiini Mwenyezi Mungu na Mtume wake, wala msizozane mkaingiwa woga, na zikapotea nguvu zenu. Na subirini. Hakika Mwenyezi Mungu yu pamoja na wanaosubiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 47, 'Wala msiwe kama wale waliotoka katika majumba yao kwa fahari na kujionyesha kwa watu, na wakiwazuilia watu Njia ya Mwenyezi Mungu. Na Mwenyezi Mungu ameyazingira yote wanayoyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 48, 'Na wakati Shetani alipowapambia vitendo vyao, na akasema, "Hakuna yeyote wa kuwashinda leo hii katika watu, nami hakika ni rafiki mlinzi wenu." Basi yalipoonana makundi mawili hayo, akarudi nyuma juu ya visigino vyake, na akasema, "Hakika mimi niko mbali sana nanyi. Hakika mimi naona msiyoyaona. Hakika mimi ninamhofu Mwenyezi Mungu, na Mwenyezi Mungu ni mkali wa kuadhibu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 49, 'Waliposema wanafiki, na wale wenye ugonjwa katika nyoyo zao, "Watu hawa dini yao imewadanganya." Na mwenye kumtegemea Mwenyezi Mungu, basi hakika Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 50, 'Na laiti ungeliona Malaika wanapowafisha wale waliokufuru wakiwapiga nyuso zao na migongo yao, (na kuwaambia), "Ionjeni adhabu iunguzayo!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 51, 'Hayo ni kwa sababu ya yale yaliyotangulizwa na mikono yenu, na kwamba hakika Mwenyezi Mungu si mwenye kuwadhulumu waja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 52, 'Kama ada ya watu wa Firauni na wale waliokuwa kabla yao, walizikufuru Ishara za Mwenyezi Mungu. Basi Mwenyezi Mungu akawachukua kwa madhambi yao. Hakika Mwenyezi Mungu ni Mwenye nguvu, Mkali wa kuadhibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 53, 'Hiyo ni kwa sababu Mwenyezi Mungu hakuwa ni wa kuibadilisha neema aliyowaneemesha kwayo kaumu, mpaka wao wabadilishe yale yaliyo katika nafsi zao, na kwamba hakika Mwenyezi Mungu ni Mwenye kusikia vyema, Mwenye kujua yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 54, 'Ni kama ada ya watu wa Firauni na wale waliokuwa kabla yao, walizikadhibisha Ishara za Mola wao Mlezi, basi tukawaangamiza kwa madhambi yao, na tukawazamisha watu wa Firauni. Na kila mmoja wao walikuwa madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 55, 'Hakika waovu zaidi ya wanyama wote mbele ya Mwenyezi Mungu ni wale waliokufuru, basi hao hawaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 56, 'Wale ambao miongoni mwao ulifanya agano nao, kisha wanavunja agano lao katika kila mara, wala wao hawamchi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 57, 'Kwa hivyo, ukiwakuta katika vita, basi wakimbize kwa hawa wale walio nyuma yao ili wapate kukumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 58, 'Na ukichelea hiana kwa kaumu fulani, basi watupilie ahadi yao kwa usawa. Hakika Mwenyezi Mungu hawapendi wahaini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 59, 'Wala kamwe wasidhanie wale waliokufuru kwamba wao wametangulia mbele. Hakika, wao hawatashinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 60, 'Na waandalieni muwezavyo katika nguvu, na kwa farasi waliofungwa tayari tayari, ili muwatie hofu kwavyo maadui wa Mwenyezi Mungu na maadui zenu, na wengineo kando na hao ambao hamwajui, lakini Mwenyezi Mungu anawajua. Na chochote mnachotoa kwenda katika Njia ya Mwenyezi Mungu, mtarudishiwa kikamilifu, nanyi hamtadhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 61, 'Na wakiielekea amani, basi nawe pia ielekee, na mtegemee Mwenyezi Mungu. Hakika Yeye ndiye Mwenye kusikia vyema, Mwenye kujua yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 62, 'Na wakitaka kukufanyia hiana, basi hakika Mwenyezi Mungu atakutosheleza. Yeye ndiye aliyekuunga mkono kwa nusura yake, na kwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 63, 'Na akaziunga pamoja nyoyo zao. Lau wewe ungelitoa vyote vilivyo katika ardhi, usingeliweza kuziunga pamoja nyoyo zao, lakini Mwenyezi Mungu ndiye aliyewaunganisha. Hakika Yeye ndiye Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 64, 'Ewe Nabii! Mwenyezi Mungu anakutosha wewe na mwenye kukufuata miongoni mwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 65, 'Ewe Nabii! Wahimize Waumini juu ya kupigana vita. Wakiwapo miongoni mwenu ishirini wanaosubiri, watawashinda mia mbili. Na wakiwapo miongoni mwenu mia, watawashinda elfu moja katika wale waliokufuru, kwa sababu wao ni kaumu wasiofahamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 66, 'Sasa Mwenyezi Mungu amewapunguzia, na alijua kuwa ndani yenu upo udhaifu. Kwa hivyo, wakiwapo watu mia moja miongoni mwenu wenye kusubiri, watawashinda mia mbili. Na wakiwapo elfu moja, watawashinda elfu mbili, kwa idhini ya Mwenyezi Mungu. Na Mwenyezi Mungu yu pamoja na wenye kusubiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 67, 'Haikuwa kwa Nabii yeyote kwamba awe na mateka, mpaka awe ameshinda sawasawa katika ardhi. Mnataka vitu vya dunia, na Mwenyezi Mungu anataka Akhera. Na Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 68, 'Lau lisingelikuwa andiko lililokwisha tangulia kutoka kwa Mwenyezi Mungu, ingewagusa adhabu kubwa kwa vile mlivyochukua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 69, 'Basi kuleni katika mlivyoteka, ni halali na vizuri, na mcheni Mwenyezi Mungu. Hakika Mwenyezi Mungu ni Mwenye kusitiri na kusamehe dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 70, 'Ewe Nabii! Waambie wale walio katika mikono yenu miongoni mwa mateka: Kama Mwenyezi Mungu akijua heri yoyote katika nyoyo zenu, atawapa bora kuliko vilivyochukuliwa kutoka kwenu, na atawasitiria dhambi. Na Mwenyezi Mungu ni Mwenye kusitiri na kusamehe dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 71, 'Na ikiwa wanataka kukufanyia hiana, basi hakika walikwishamfanyia hiana Mwenyezi Mungu kabla, naye akawawezesha nyinyi kuwashinda. Na Mwenyezi Mungu ni Mwenye kujua vyema, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 72, 'Hakika wale walioamini na wakahama na wakaipigania Njia ya Mwenyezi Mungu kwa mali zao na nafsi zao, na wale waliotoa pahali pa kukaa, na wakanusuru, hao ni marafiki na walinzi wao kwa wao. Na wale walioamini lakini hawakuhama, nyinyi hamna wajibu wa ulinzi kwao hata kidogo mpaka wahame. Lakini wakiomba msaada kwenu katika Dini, basi ni juu yenu kuwasaidia, isipokuwa juu ya kaumu ambao lipo agano baina yenu na wao. Na Mwenyezi Mungu anayaona vyema yale mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 73, 'Na wale waliokufuru ni marafiki walinzi wenyewe kwa wenyewe. Msipofanya hivi, itakuwepo fitina katika ardhi na uharibifu mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 74, 'Na wale walioamini, na wakahama, na wakapigana Jihadi katika Njia ya Mwenyezi Mungu, na wale waliotoa pahali pa kukaa na wakanusuru, hao ndio Waumini wa kweli. Watapata msamaha (wa Mwenyezi Mungu) na riziki njema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 75, 'Na wale walioamini baadaye, na wakahama, na wakapigana Jihadi pamoja nanyi, basi hao ni miongoni mwenu. Na jamaa wa nasaba wanastahikiana zaidi wenyewe kwa wenyewe katika Kitabu cha Mwenyezi Mungu. Hakika, Mwenyezi Mungu ni Mwenye kujua kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 1, '[Huku ni] kujiweka mbali kutokako kwa Mwenyezi Mungu na Mtume wake kuwaendea wale mlioagana nao miongoni mwa washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 2, 'Basi tembeeni katika ardhi miezi minne, na jueni kwamba nyinyi hamwezi kumshinda Mwenyezi Mungu, na kwamba hakika Mwenyezi Mungu atawahizi makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 3, 'Na ni tangazo kutoka kwa Mwenyezi Mungu na Mtume wake kuwaendea watu wote siku ya Hija Kubwa kwamba Mwenyezi Mungu yuko mbali na washirikina, na Mtume wake pia yuko mbali. Kwa hivyo, mkitubu, basi hilo ndilo heri kwenu. Na mkigeuka, basi jueni kuwa nyinyi hamuwezi kumshinda Mwenyezi Mungu. Na wabashirie wale waliokufuru adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 4, 'Isipokuwa wale mlioagana nao katika washirikina, kisha hawakuwapunguza chochote, wala hawakumsaidia yeyote dhidi yenu. Basi hao watimizieni ahadi yao mpaka muda wao. Hakika, Mwenyezi Mungu huwapenda wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 5, 'Na ikiisha miezi mitukufu, basi waueni washirikina popote muwakutapo, na wachukueni na wazingireni, na wavizieni katika kila njia. Lakini wakitubu, na wakashika Sala, na wakatoa Zaka, basi waachilieni njia yao. Hakika Mwenyezi Mungu ni Mwenye kusamehe dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 6, 'Na ikiwa yeyote miongoni mwa washirikina atakuomba ulinzi, basi mpe ulinzi ili apate kusikia maneno ya Mwenyezi Mungu. Kisha mfikishe mahali pake pa amani. Haya ni kwa kuwa hao ni kaumu wasiojua kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 7, 'Vipi washirikina watakuwa na agano kwa Mwenyezi Mungu na kwa Mtume wake, isipokuwa wale mliofanya agano nao kwenye Msikiti Mtakatifu? Basi maadamu watawawia wanyoofu, basi nanyi pia wawieni wanyoofu. Hakika Mwenyezi Mungu huwapenda wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 8, 'Vipi, na wakiwa na ushindi dhidi yenu, hawachungi kwenu udugu wala ahadi. Wanawafurahisha kwa midomo yao tu, lakini nyoyo zao zinakataa hayo. Na wengi wao ni wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 9, 'Walinunua Ishara za Mwenyezi Mungu kwa thamani chache, kwa hivyo wakaizuilia njia yake. Hakika hao ni maovu waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 10, 'Hawachungi kwa Muumini udugu wala ahadi. Basi hao ndio wapindukiao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 11, 'Kwa hivyo wakitubu, na wakasimamisha Sala, na wakatoa Zaka, basi ni ndugu zenu katika Dini. Na tunazipambanua Aya kwa kaumu wanaojua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 12, 'Na wakivunja viapo vyao baada ya agano lao, na wakaitia dosari Dini yenu, basi piganeni na viongozi wa ukafiri. Hakika hao hawana viapo vya kweli. Huenda (kwa hayo) wakaacha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 13, 'Je, hampigani na kaumu waliovunja viapo vyao na wakawa na hamu ya kumtoa Mtume, nao ndio waliowaanza mara ya kwanza? Je, mnawaogopa? Basi Mwenyezi Mungu anastahiki zaidi mumwogope, ikiwa nyinyi ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 14, 'Piganeni nao, Mwenyezi Mungu awaadhibu kwa mikono yenu, na awahizi na awanusuru dhidi yao, na aviponye vifua vya kaumu ya Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 15, 'Na aondoe hasira ya nyoyo zao. Na Mwenyezi Mungu humkubalia toba amtakaye. Na Mwenyezi Mungu ni Mwenye kujua vyema, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 16, 'Je, mlidhani kuwa mtaachwa tu, na Mwenyezi Mungu hajawajua wale waliopigana Jihadi miongoni mwenu, na wala hawakumfanya yeyote mwendani wao isipokuwa Mwenyezi Mungu na Mtume wake na Waumini wenziwe? Na Mwenyezi Mungu anazo habari za yote mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 17, 'Haikuwa kwa washirikina kwamba waiimarishe misikiti ya Mwenyezi Mungu, hali ya kuwa wanazishuhudia nafsi zao wenyewe ukafiri. Hao matendo yao yaliharibika, na katika Moto wao watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 18, 'Hakika anayeimarisha tu misikiti ya Mwenyezi Mungu ni yule anayemwamini Mwenyezi Mungu, na Siku ya Mwisho, na akasimamisha Sala, na akatoa Zaka, na wala hakumnyenyekea isipokuwa Mwenyezi Mungu. Basi huenda hao wakawa katika waongofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 19, 'Je, mnafanya kuwanywesha maji Mahujaji na kuimarisha Msikiti Mtakatifu ni sawa na mwenye kumuamini Mwenyezi Mungu, na Siku ya Mwisho, na akafanya Jihadi katika Njia ya Mwenyezi Mungu? Hawawi sawa kwa Mwenyezi Mungu. Na Mwenyezi Mungu hawaongoi kaumu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 20, 'Wale walioamini, na wakahama, na wakafanya Jihadi katika Njia ya Mwenyezi Mungu kwa mali zao na nafsi zao, hao wana daraja kubwa zaidi kwa Mwenyezi Mungu. Na hao ndio waliofuzu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 21, 'Mola wao Mlezi anawabashiria rehema zitokazo kwake, na radhi, na Bustani ambazo humo wana neema za kudumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 22, 'Watadumu humo milele. Hakika kwa Mwenyezi Mungu yapo malipo makubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 23, 'Enyi mlioamini! Msiwafanye baba zenu na ndugu zenu kuwa marafiki walinzi wenu ikiwa wanaupendelea ukafiri kuliko Imani. Na mwenye kuwafanya marafiki walinzi miongoni mwenu, basi hao ndio madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 24, 'Sema: Ikiwa baba zenu, na wana wenu, na ndugu zenu, na wake zenu, na jamaa zenu, na mali mlizozichuma, na biashara mnazohofia kuharibika kwake, na makazi mnayoyaridhia, ni vipenzi zaidi kwenu kuliko Mwenyezi Mungu na Mtume wake na kufanya Jihadi katika Njia yake, basi ngojeni mpaka Mwenyezi Mungu aje na amri yake. Na Mwenyezi Mungu hawaongoi kaumu wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 25, 'Hakika Mwenyezi Mungu aliwanusuru katika maeneo mengi, na siku ya Hunayni wakati wingi wenu uliwapa majivuno, lakini haukuwafaa kitu, na ardhi ikawa finyu kwenu pamoja na upana wake. Kisha mkageuka mkapeana migongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 26, 'Kisha Mwenyezi Mungu akateremsha utulivu wake juu ya Mtume wake na juu ya Waumini. Na akateremsha majeshi ambayo hamkuyaona, na akawaadhibu wale waliokufuru. Na hayo ndiyo malipo ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 27, 'Kisha baada ya hayo Mwenyezi Mungu atamkubalia toba amtakaye. Na Mwenyezi Mungu ni Mwenye kusamehe dhambi, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 28, 'Enyi mlioamini! Hakika washirikina ni najisi, kwa hivyo wasiukaribie Msikiti Mtakatifu baada ya mwaka wao huu. Na ikiwa mnahofia umasikini, basi Mwenyezi Mungu atakutajirisheni kutoka katika fadhila zake akitaka. Hakika Mwenyezi Mungu ni Mwenye kujua vyema, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 29, 'Piganeni na wale wasiomwamini Mwenyezi Mungu wala Siku ya Mwisho, wala hawaharamishi yale aliyoharamisha Mwenyezi Mungu na Mtume wake, wala hawashiki Dini ya haki, miongoni mwa wale waliopewa Kitabu, mpaka watoe kodi kwa hiari yao, hali wametii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 30, 'Na Mayahudi walisema: Uzeir ni mwana wa Mwenyezi Mungu. Na Wakristo walisema: Masihi ni mwana wa Mwenyezi Mungu. Hiyo ni kauli yao tu kwa vinywa vyao. Wanayaiga maneno ya wale waliokufuru kabla yao. Mwenyezi Mungu awaangamize! Wanageuzwa namna gani hawa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 31, 'Waliwafanya makuhani wao na wamonaki wao kuwa ni mabwana badala ya Mwenyezi Mungu, na pia Masihi mwana wa Maryamu. Na wala hawakuamrishwa isipokuwa wamwabudu Mungu Mmoja, hakuna mungu isipokuwa Yeye. Subhanahu (ametakasika) mbali na hayo wanayoyashirikisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 32, 'Wanataka kuizima Nuru ya Mwenyezi Mungu kwa vinywa vyao, na Mwenyezi Mungu anakataa isipokuwa aitimize Nuru yake hata makafiri wakichukia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 33, 'Yeye ndiye aliyemtuma Mtume wake kwa uongofu na Dini ya haki ili aipe ushindi juu ya dini zote, hata washirikina wakichukia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 34, 'Enyi mlioamini! Hakika wengi katika makuhani na wamonaki wanakula mali za watu kwa batili na wanazuilia Njia ya Mwenyezi Mungu. Na wale wanaolimbika dhahabu na fedha, wala hawazitumii katika Njia ya Mwenyezi Mungu, basi wabashirie adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 35, 'Siku zitakapotiwa moto katika Moto wa Jahannamu, na kwazo vikachomwa vipaji vya nyuso zao na mbavu zao na migongo yao, wakaambiwa: Haya ndiyo mliyozilimbikia nafsi zenu. Basi onjeni yale mliyokuwa mkilimbika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 36, 'Hakika idadi ya miezi kwa Mwenyezi Mungu ni miezi kumi na miwili katika andiko la Mwenyezi Mungu tangu alipoumba mbingu na ardhi. Katika hiyo iko minne mitakatifu. Hiyo ndiyo Dini iliyonyooka sawa. Basi msidhulumu nafsi zenu humo. Na piganeni na washirikina wote kama wao wanavyopigana nanyi nyote. Na jueni kuwa Mwenyezi Mungu yu pamoja na wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 37, 'Hakika kuahirisha (miezi) ni kuzidi tu katika kukufuru; wanapotezwa kwa hilo wale waliokufuru. Wanauhalalisha mwaka mmoja na kuharimisha mwaka mwingine, ili wafanye kuwa sawa idadi ya ile (miezi) aliyoitukuza Mwenyezi Mungu, ndiyo wahalalishe yale aliyoyaharamisha Mwenyezi Mungu. Wamepambiwa ubaya wa vitendo vyao hivi. Na Mwenyezi Mungu hawaongoi kaumu makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 38, 'Enyi mlioamini! Mna nini mnapoambiwa: Nendeni katika Njia ya Mwenyezi Mungu, mnajitia uzito katika ardhi? Je, mmeridhia maisha ya dunia kuliko ya Akhera? Lakini starehe za maisha ya dunia kwa kulinganisha na Akhera siyo isipokuwa chache.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 39, 'Kama hamuendi, atawaadhibu adhabu chungu, na atawabadilisha na kaumu wasiokuwa nyinyi, wala nyinyi hamtamdhuru chochote. Na Mwenyezi Mungu ni Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 40, 'Ikiwa nyinyi hamtamnusuru Mtume, basi Mwenyezi Mungu alikwishamnusuru walipomtoa wale waliokufuru, akiwa ni wa pili wa wawili walipokuwa katika pango, alipomwambia sahibu yake: ''Usihuzunike. Hakika Mwenyezi Mungu yu pamoja nasi.'' Basi Mwenyezi Mungu akauteremsha utulivu wake juu yake, na akamuunga mkono kwa majeshi ambayo hamkuyaona, na akalifanya neno la wale waliokufuru kuwa chini zaidi, na Neno la Mwenyezi Mungu ndilo la juu zaidi. Na Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 41, 'Tokeni muende mkiwa wepesi na wazito, na piganeni Jihadi kwa mali zenu na nafsi zenu katika Njia ya Mwenyezi Mungu. Hayo ni heri kwenu ikiwa mnajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 42, 'Lau ingelikuwa ipo faida ya papo kwa hapo, na safari fupi, basi hakika wangelikufuata. Lakini waliona kwamba ni mbali na kuna ugumu. Nao wataapa kwa Mwenyezi Mungu: ''Tungeliweza, basi bila ya shaka tungelitoka pamoja nanyi.'' Wanaziangamiza nafsi zao. Na Mwenyezi Mungu anajua kuwa hakika hao ni waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 43, 'Mwenyezi Mungu amekusamehe! Kwa nini ukawapa ruhusa kabla ya kukubainikia wale wanaosema ukweli, na ukawajua waongo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 44, 'Hawakuombi ruhusa wale wanaomwamini Mwenyezi Mungu na Siku ya Mwisho ili wafanye Jihadi kwa mali zao na nafsi zao. Na Mwenyezi Mungu ni Mwenye kuwajua vyema wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 45, 'Hakika wanakuomba ruhusa tu wale wasiomwamini Mwenyezi Mungu, na Siku ya Mwisho, na nyoyo zao zikatia shaka. Basi hao wanasitasita katika shaka yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 46, 'Na wangelitaka kweli kutoka, basi bila ya shaka wangeliliandalia hilo maandalizi ya sawasawa. Lakini Mwenyezi Mungu alichukia kutoka kwao, kwa hivyo akawazuia na ikasemwa: Kaeni pamoja na wanaokaa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 47, 'Lau wangelitoka kati yenu, wasingeliwazidisha isipokuwa mchafuko, na wangetangatanga kati yenu wakiwatakia fitina. Na miongoni mwenu wako wanaowasikiliza sana. Na Mwenyezi Mungu anawajua madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 48, 'Hakika, walikwishataka kuleta mafarakano tangu zamani, na wakakugeuzia mambo, mpaka ikaja haki na ikadhihirika amri ya Mwenyezi Mungu hali kuwa wao wamechukia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 49, 'Na miongoni mwao wapo wanaosema: ''Niruhusu wala usinitie majaribuni.'' Kwa yakini wao hivyo wamekwishatumbukia katika majaribu. Na hakika Jahannam imewazingira makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 50, 'Likikupata zuri, linawawia baya. Na ukikusibu msiba, wanasema: ''Sisi hakika tuliangalia mambo yetu vizuri tangu zamani.'' Na wanageuka kwenda zao hali ya kuwa wamefurahi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 51, 'Sema: Halitusibu isipokuwa yale aliyotuandikia Mwenyezi Mungu. Yeye ndiye Mola wetu Mlinzi. Na kwa Mwenyezi Mungu, basi na wategemee Waumini!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 52, 'Sema: Hivyo mnatutazamia litupate lolote isipokuwa moja katika mazuri mawili? Na sisi tunawatazamia kuwa Mwenyezi Mungu atawasibu kwa adhabu kutoka kwake, au kwa mikono yetu. Basi tazamieni, nasi hakika tunatazamia pamoja nanyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 53, 'Sema: Toeni kwa kupenda au kwa kuchukia. Kamwe hakitakubaliwa kutoka kwenu. Kwani hakika nyinyi mmekuwa kaumu wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 54, 'Na hawakuzuiliwa kukubaliwa kutoa kwao isipokuwa kwa kuwa walimkufuru Mwenyezi Mungu na Mtume wake, wala hawaji kwenye Sala isipokuwa huku ni wavivu, wala hawatoi isipokuwa nao wamechukia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 55, 'Basi zisikufurahishe mali zao wala wana wao. Hakika Mwenyezi Mungu anataka kuwaadhibu kwazo katika maisha ya dunia hii, na zitoke roho zao na hali wao ni makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 56, 'Na wanaapa kwa Mwenyezi Mungu kwamba wao ni katika nyinyi, wala wao si katika nyinyi. Lakini wao ni kaumu wanaoogopa mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 57, 'Lau kama watapata pa kukimbilia au mapango au mahali pa kuingia, basi hakika wangeligeuka kwenda huko huku wanakimbia mbio zisizozuilika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 58, 'Na miongoni mwao kuna yule anayekusengenya kuhusiana na sadaka. Kwa hivyo wakipewa kwayo, wanaridhika. Na wasipopewa kwayo, tazama, wanakasirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 59, 'Na lau kuwa waliridhia kile alichowapa Mwenyezi Mungu na Mtume wake, na wakasema: Mwenyezi Mungu anatutosheleza, Mwenyezi Mungu atatupa katika fadhila yake, na pia Mtume wake; hakika sisi ni wenye kumtaka Mwenyezi Mungu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 60, 'Hakika sadaka ni za mafakiri tu, na masikini, na wanaozitumikia, na wa kutiwa nguvu nyoyo zao, na katika kukomboa watumwa, na waliogharamika, na katika Njia ya Mwenyezi Mungu, na wasafiri. Huu ni waajibu uliofaridhiwa na Mwenyezi Mungu. Na Mwenyezi Mungu ni Mwenye kujua vyema, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 61, 'Na miongoni mwao kuna wale wanaomuudhi Nabii na wanasema: Yeye ni sikio tu. Sema: Basi ni sikio la heri kwenu. Anamwamini Mwenyezi Mungu, na ana imani na Waumini, naye ni rehema kwa wanaoamini miongoni mwenu. Na wale wanaomuudhi Mtume wa Mwenyezi Mungu wana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 62, 'Wanawaapia kwa Mwenyezi Mungu ili wakuridhishenyi, ilhali Mwenyezi Mungu na Mtume wake ndio wanaostahiki zaidi kwamba wao wawaridhishe ikiwa wao ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 63, 'Je, hawajui ya kwamba anayempinga Mwenyezi Mungu na Mtume wake, basi huyo hakika ana Moto wa Jahannam adumu humo? Hiyo ndiyo hizaya kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 64, 'Wanafiki wanaogopa kwamba iteremshwe Sura juu yao itakayowaambia yale yaliyo katika nyoyo zao. Sema: Fanyeni stihizai! Hakika Mwenyezi Mungu atayatoa nje hayo mnayoyaogopa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 65, 'Na ukiwauliza, bila shaka watasema: Hakika tulikuwa tukipiga porojo na kucheza tu. Sema: Kwani mlikuwa mkimfanyia masikhara Mwenyezi Mungu, na ishara zake, na Mtume wake?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 66, 'Msitoe udhuru. Hakika mmekwishakufuru baada ya kuamini kwenu! Tukilisamehe kundi moja miongoni mwenu, tunaliadhibu kundi jingine kwa kuwa wao wamekuwa wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 67, 'Wanaume wanafiki na wanawake wanafiki, wote ni hali moja. Huamrisha maovu na hukataza mema, na huifumba mikono yao. Walimsahau Mwenyezi Mungu, basi na Yeye pia akawasahau. Hakika wanafiki ndio wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 68, 'Mwenyezi Mungu amewaahidi wanafiki wanaume na wanafiki wanawake na makafiri Moto wa Jahannamu watadumu humo. Hiyo ndiyo inawatosha, na Mwenyezi Mungu amewalaani; nao wana adhabu ya kudumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 69, 'Ni kama wale waliokuwa kabla yenu. Walikuwa wana nguvu na mali na watoto zaidi kuwaliko nyinyi. Basi walistareheka kwa fungu lao, na nyinyi mnastareheka kwa fungu lenu, kama walivyostareheka kwa fungu lao wale waliokuwa kabla yenu. Na nyinyi mkazama katika maovu kama wao walivyozama. Hao, matendo yao yaliharibika katika dunia na Akhera; na hao ndio waliohasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 70, 'Je, hazikuwajia habari za wale waliokuwa kabla yao, kaumu ya Nuhu, na A''ad, na Thamud, na kaumu ya Ibrahim, na watu wa Madyana, na miji iliyopinduliwa chini juu? Mitume wao waliwajia na hoja zilizo wazi. Basi Mwenyezi Mungu hakuwa mwenye kuwadhulumu, lakini wao walikuwa wakijidhulumu wenyewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 71, 'Na Waumini wanaume na Waumini wanawake wao kwa wao ni marafiki walinzi. Huamrisha mema na hukataza maovu, na husimamisha Sala, na hutoa Zaka, na humtii Mwenyezi Mungu na Mtume wake. Hao Mwenyezi Mungu atawarehemu. Hakika Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 72, 'Mwenyezi Mungu amewaahidi Waumini wanaume na Waumini wanawake Bustani zipitiazo mito chini yake, watadumu humo. Na makazi mema katika Bustani za kudumu, na Radhi kutoka kwa Mwenyezi Mungu ndizo kubwa zaidi kuliko yote. Huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 73, 'Ewe Nabii! Pambana na makafiri na wanafiki, na wawiye mgumu. Na makazi yao ni Jahannamu, na hayo ndiyo marejeo mabaya kabisa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 74, 'Wanaapa kwa Mwenyezi Mungu kuwa hawakusema; nao hakika wamekwishasema neno la ukafiri, na wakakufuru baada ya kusilimu kwao. Na wakawa na utashi mkubwa juu ya yale ambayo hawakuweza kuyafikia. Na hawakuchukia ila kwa kuwa Mwenyezi Mungu aliwatajirisha, na Mtume wake pia kutokana na fadhila zake. Basi wakitubu, itakuwa heri kwao. Na wakigeuka, Mwenyezi Mungu atawaadhibu adhabu chungu katika dunia na Akhera. Na wala hawana katika ardhi mlinzi yeyote wala wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 75, 'Na miongoni mwao kuwa wale waliomuahidi Mwenyezi Mungu kwamba: Akitupa katika fadhila yake, hapana shaka tutatoa sadaka, na tutakuwa katika waliotengenea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 76, 'Basi alipowapa katika fadhila yake, wakaifanyia ubahili na wakageuka hali ya kuwa wamepeana mgongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 77, 'Basi akawafuatisha unafiki katika nyoyo zao mpaka Siku watakapokutana naye, kwa sababu ya kuwa walimvunjia Mwenyezi Mungu yale waliyomuahidi, na kwa sababu ya kusema kwao uongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 78, 'Je, hawajui kwamba Mwenyezi Mungu anajua siri zao na minong''ono yao, na kwamba Mwenyezi Mungu ni Mwenye kuyajua sana ya ghaibu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 79, 'Wale wanaowabeua Waumini wanaotoa sadaka nyingi na wasio na cha kutoa ila kiasi cha juhudi yao, hivyo wanawafanyia masikhara. Mwenyezi Mungu atawakejeli wao! Nao wana adhabu chungu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 80, 'Waombee msamaha au usiwaombee msamaha. Hata ukiwaombea msamaha mara sabini, Mwenyezi Mungu hatawasamehe. Hayo ni kwa sababu ya kuwa wao walimkufuru Mwenyezi Mungu na Mtume wake. Na Mwenyezi Mungu hawaongoi kaumu wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 81, 'Walifurahi walioachwa nyuma kwa kule kukaa kwao nyuma ya Mtume wa Mwenyezi Mungu. Na wakachukia kupigana Jihadi kwa mali zao na nafsi zao katika njia ya Mwenyezi Mungu, na wakasema: Msitoke kwenda katika joto! Sema: Moto wa Jahannamu una joto kubwa zaidi, laiti wangelikuwa wanafahamu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 82, 'Basi na wacheke kidogo, na walie sana. Hayo ni malipo ya yale waliyokuwa wakiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 83, 'Basi Mwenyezi Mungu akikurudisha kwenye kikundi kimoja miongoni mwao - na wakakutaka idhini ya kutoka - basi sema: Nyinyi hamtatoka pamoja nami kabisa, wala hamtapigana na adui pamoja nami. Hakika nyinyi mliridhia kusalia nyuma mara ya kwanza, basi kaeni pamoja na hao waliosalia nyuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 84, 'Wala usimsalie kabisa yeyote katika wao akifa, wala usisimame kaburini kwake. Hakika hao walimkufuru Mwenyezi Mungu na Mtume wake, na wakafa hali ya kuwa wamevuka mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 85, 'Wala zisikupendeze mali zao na watoto wao. Hakika Mwenyezi Mungu anataka tu kuwaadhibu kwa hayo katika dunia; na zitoke roho zao hali ya kuwa ni makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 86, 'Na inapoteremshwa sura kwamba muaminini Mwenyezi Mungu na piganeni Jihadi pamoja na Mtume wake, wale wenye nguvu miongoni mwao hukutaka ruhusa na wanasema: Tuache tuwe pamoja na wanaokaa nyuma!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 87, 'Waliridhia kwamba wawe pamoja na wasaliao nyuma, na nyoyo zao zikafunikwa, kwa hivyo hawafahamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 88, 'Lakini Mtume na wale walioamini pamoja naye, walifanya Jihadi kwa mali zao na nafsi zao. Na hao ndio wana heri nyingi. Na hao ndio waliofaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 89, 'Mwenyezi Mungu amewaandalia Bustani zipitazo mito kwa chini yake, watadumu humo. Huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 90, 'Na walikuja wenye kutoa udhuru miongoni mwa Mabedui ili wapewe ruhusa, na wakakaa wale waliomdanganya Mwenyezi Mungu na Mtume wake. Itawafika wale waliokufuru miongoni mwao adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 91, 'Hakuna lawama juu ya wanyonge, wala juu ya wagonjwa, wala juu ya wale wasiopata cha kutoa, maadamu wanamsafia nia Mwenyezi Mungu na Mtume wake. Hakuna njia ya kuwalaumu wanaofanya mazuri. Na Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 92, 'Wala wale wanaokujia ili uwape kipando, ukasema: Sina kipando cha kukubebeeni juu yake, kwa hivyo wanageuka kwenda huku macho yao yanamiminika machozi kwa huzuni ya kwamba hawatapata cha kutoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 93, 'Hakika njia ya lawama iko tu juu ya wale wanaokuomba ruhusa wasiende vitani ilhali wao ni matajiri. Waliridhia kwamba wawe pamoja na wanaosalia nyuma. Na Mwenyezi Mungu akaiziba mioyo yao. Kwa hivyo hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 94, 'Watawatolea udhuru mtakapowarudia. Sema: Msitoe udhuru; hatutawaamini. Mwenyezi Mungu amekwishatujulisha habari zenu. Na Mwenyezi Mungu na Mtume wake wataviona vitendo vyenu. Kisha mtarudishwa kwa Mjuzi wa ya siri na ya dhahiri; naye atawaambia mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 95, 'Watawaapia kwa Mwenyezi Mungu mtakaporudi kwao ili muwaachilie mbali. Basi waachilieni mbali. Hakika hao ni najisi, na makazi yao ni Jahannam, kuwa ni malipo kwa yale waliyokuwa wakiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 96, 'Wanawaapia ili muwe radhi nao. Lakini hata mkiwa radhi nao nyiye, basi hakika Mwenyezi Mungu hawi radhi na kaumu wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 97, 'Mabedui ndio wenye ukafiri mkubwa zaidi na unafiki, na wameelekea zaidi kutojua mipaka ya yale aliyoyateremsha Mwenyezi Mungu juu ya Mtume wake. Na Mwenyezi Mungu ni mwenye kujua zaidi, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 98, 'Na katika Mabedui hao kuna yule anayefikiri kuwa kile anachotoa ni gharama ya bure, na anakutazamieni mambo yawageukie. Mageuko maovu yatakuwa juu yao! Na Mwenyezi Mungu ni Mwenye kusikia vyema, Mwenye kujua yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 99, 'Na katika Mabedui kuna yule anayemwamini Mwenyezi Mungu na Siku ya Mwisho, na anakichukulia kile anachotoa kuwa ni cha kumsongeza karibu na Mwenyezi Mungu na cha kupata kwacho dua za Mtume. Ndiyo! Hayo hakika ni mambo ya kuwasongeza karibu. Mwenyezi Mungu atawaingiza katika rehema yake. Hakika Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 100, 'Na wale waliotangulia, wa kwanza, katika Wahajiri na Ansari, na wale waliowafuata kwa uzuri, Mwenyezi Mungu aliwaridhia, na wao walimridhia, na amewaandalia Bustani zipitazo mito chini yake, watadumu humo milele. Huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 101, 'Na katika mabedui walio jirani zenu kuna wanafiki; na katika wakazi wa Madina pia wapo wale waliobobea katika unafiki. Wewe huwajui. Sisi tunawajua. Tutawaadhibu mara mbili, kisha watarudishwa kwenye adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 102, 'Na wengine walikiri dhambi zao, walichanganya matendo mema na mengine mabaya. Huenda Mwenyezi Mungu akakubali toba zao. Hakika Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 103, 'Chukua sadaka katika mali zao, uwasafishe na uwatakase kwayo, na waombee dua. Hakika kuomba dua kwako ni utulivu kwao. Na Mwenyezi Mungu ni Mwenye kusikia vyema, Mwenye kujua yote', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 104, 'Je, hawajui ya kwamba Mwenyezi Mungu anakubali toba ya waja wake, na anazichukua sadaka, na kwamba Mwenyezi Mungu ni Mwingi wa kukubali toba, Mwenye kurehemu sana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 105, 'Na sema: Tendeni matendo. Na Mwenyezi Mungu atayaona matendo yenu, na Mtume wake, na Waumini. Na mtarudishwa kwa Mwenye kujua siri na dhahiri; basi naye atawaambia yale mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 106, 'Na wapo wengine wanaongojea amri ya Mwenyezi Mungu. Ima atawaadhibu au atawakubalia toba. Na Mwenyezi Mungu ni Mwenye kujua zaidi, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 107, 'Na wapo waliojenga msikiti kwa ajili ya madhara, na ukafiri, na kuwafarikisha Waumini, na pa kuvizia kwa ajili ya wale waliompiga vita Mwenyezi Mungu na Mtume wake hapo kabla. Na bila ya shaka wataapa kwamba: ''Hatukukusudia isipokuwa uzuri tu.'' Na Mwenyezi Mungu anashuhudia kuwa wao hakika ni waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 108, 'Usisimame ndani yake kabisa. Msikiti uliojengwa juu ya msingi wa ucha Mungu tangu siku ya mwanzo unastahiki zaidi wewe usimame ndani yake. Humo wamo wanaume wanaopenda kujitakasa. Na Mwenyezi Mungu anawapenda wanaojitakasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 109, 'Je, mwenye kuweka msingi wa mjengo wake juu ya uchaji utokao kwa Mwenyezi Mungu na radhi zake ni bora zaidi au mwenye kuweka msingi wa mjengo wake juu ya ukingo wa shimo unaoporomoka? Kwa hivyo ukaporomoka naye ndani ya Moto wa Jahannamu? Na Mwenyezi Mungu hawaongoi kaumu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 110, 'Na mjengo wao huo walioujenga hautaacha kuwa shaka katika nyoyo zao mpaka nyoyo zao hizo zikatike vipande vipande. Na Mwenyezi Mungu ni Mwenye kujua vyema, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 111, 'Hakika Mwenyezi Mungu alinunua kutoka kwa Waumini nafsi zao na mali zao kwa kuwa wao wana Bustani ya mbinguni. Wanapigana katika Njia ya Mwenyezi Mungu, kwa hivyo wanaua na wanauawa. Hii ni ahadi aliyojilazimisha (Mwenyezi Mungu) kwa haki katika Taurati, na Injili, na Qur-ani. Na nani atimizaye zaidi ahadi yake zaidi kuliko Mwenyezi Mungu? Basi furahini kwa biashara yenu mliyofanya naye. Na huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 112, 'Wale wanaotubia, wanaoabudu, wanaohimidi, wanaokimbilia heri, wanaorukuu, wanaosujudu, wanaoamrisha mema na wanaokataza maovu, na wanaolinda mipaka ya Mwenyezi Mungu. Na wabashirie Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 113, 'Haimpasii Nabii na wale walioamini kuwaombea msamaha washirikina, hata wakiwa ni jamaa zao, baada ya kwishawabainikia kuwa hao ni watu wa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 114, 'Wala haikuwa Ibrahim kumtakia msamaha baba yake isipokuwa kwa sababu ya ahadi aliyomuahidi. Lakini ilipombainikia kwamba yeye ni adui ya Mwenyezi Mungu, alijiweka mbali mno naye. Hakika Ibrahim alikuwa mwingi wa kuomba, mnyenyekevu, mvumilivu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 115, 'Na haiwi kwa Mwenyezi Mungu kuwapotosha kaumu baada ya kwishawaongoa mpaka awabainishie ya kujiepusha nayo. Hakika Mwenyezi Mungu ni Mwenye kujua vyema kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 116, 'Hakika Mwenyezi Mungu anao ufalme wa mbingu zote na ardhi; huhuisha na hufisha. Nanyi hamna mlinzi yeyote wala msaidizi kando na Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 117, 'Mwenyezi Mungu alikwishakubali toba ya Nabii na Wahajiri na Ansari waliomfuata katika saa ya ugumu, baada ya kwamba nyoyo za kundi miongoni mwao zilikuwa zimekaribia kukengeuka. Basi akakubali toba yao. Hakika Yeye kwao ni Mpole, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 118, 'Na pia wale watatu walioachwa nyuma hata ardhi wakaiona kuwa ni finyu juu yao, pamoja na ukunjufu wake, na nafsi zao zikawabana, na wakayakinika kuwa hakuna kimbilio kutoka kwa Mwenyezi Mungu isipokuwa kwake Yeye. Kisha akawakubalia toba ili nao watubu. Hakika Mwenyezi Mungu ndiye Mwenye kukubali toba sana, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 119, 'Enyi mlioamini! Mcheni Mwenyezi Mungu, na kuweni pamoja na wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 120, 'Haiwafailii watu wa Madina na Mabedui walio kando kando yao kusalia nyuma wasitoke pamoja na Mtume, wala kujipendelea nafsi zao kuliko nafsi yake. Hayo ni kwa sababu wao hakiwapati kiu, wala machovu, wala njaa, katika Njia ya Mwenyezi Mungu, wala hawaendi mahali panapowaghadhibisha makafiri, wala hakiwapati chochote kutokana na maadui, isipokuwa huandikiwa kwa hicho kitendo chema. Hakika Mwenyezi Mungu haupotezi ujira wa wanaofanya uzuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 121, 'Wala hawatoi masurufu madogo wala makubwa, wala hawalivuki bonde, isipokuwa huandikiwa, ili Mwenyezi Mungu awalipe bora zaidi ya yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 122, 'Na haiwapasi Waumini kutoka wote pamoja. Lakini kwa nini hawatoki baadhi katika kila kundi miongoni mwao, wakajifunze vyema Dini, na kisha waje kuwaonya wenzao watakapowarudia, ili wajihadharishe?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 123, 'Enyi mlioamini! Piganeni na wale walio karibu yenu miongoni mwa makafiri, na wakute ugumu kwenu. Na jueni ya kwamba Mwenyezi Mungu yu pamoja na wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 124, 'Na inapokwishateremshwa sura, basi wapo miongoni mwao wasemao: "Ni nani miongoni mwenu sura hii imemzidishia Imani?" Ama wale walioamini, iliwazidishia Imani, nao wanafurahi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 125, 'Na ama wale wenye maradhi katika nyoyo zao, basi iliwazidishia uovu juu ya uovu wao; na wanakufa hali ya kuwa wao ni makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 126, 'Je, hawaoni ya kwamba wanajaribiwa kila mwaka mara moja au mara mbili? Kisha hawatubu, wala hawakumbuki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 127, 'Na ikishateremka sura, hutazamana wao kwa wao, (kama kwamba wanasema:) "Je, yuko yeyote anayewaona nyinyi" Kisha huondoka wakaenda. Mwenyezi akaziondoa nyoyo zao kwa kuwa hao ni kaumu wasiofahamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 128, 'Hakika amekwishawajia Mtume kutokana na nyinyi wenyewe; yanamhuzunisha yale yanayowataabisha, anawajali sana, kwa Waumini ni mpole na mwenye kuwarehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 129, 'Kwa hivyo, wakigeuka, basi wewe sema, ”Mwenyezi Mungu ananitosha. Hakuna mungu isipokuwa Yeye tu. Mimi ninamtegemea Yeye, na Yeye ndiye Mola Mlezi wa Kiti Kikuu cha Enzi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 1, 'Alif Laam Raa.[1] Hizo ni Aya za Kitabu chenye hekima.', '[1] Herufi hizi "Alif Laam Raa" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 2, 'Je, imekuwa ajabu kwa watu kwamba tumemfunulia mwanamume kutokana nao kuwa, “Waonye watu, na wabashirie wale walioamini ya kuwa wana cheo cha juu kwa Mola wao Mlezi?” Wakasema makafiri, “Hakika huyu ni mchawi aliye dhahiri!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 3, 'Hakika Mola wenu Mlezi ni Mwenyezi Mungu, ambaye ameziumba mbingu na ardhi kwa siku sita, kisha akainuka akawa juu ya Kiti cha Enzi, anaendesha mambo yote. Hakuna mwombezi yeyote isipokuwa baada ya idhini yake. Huyo ndiye Mwenyezi Mungu, Mola wenu Mlezi. Basi muabuduni Yeye. Je, hamkumbuki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 4, 'Kwake Yeye tu ndiyo marejeo yenu nyote. Hii ni ahadi ya Mwenyezi Mungu iliyo ya kweli. Hakika Yeye ndiye anayeanzisha uumbaji, kisha ataurejesha ili awalipe kwa uadilifu wale walioamini na wakatenda mema. Na wale waliokufuru, wana vinywaji vya maji ya moto, na adhabu chungu kwa sababu ya yale waliyokuwa wakiyakufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 5, 'Yeye ndiye aliyelifanya jua kuwa na mwangaza, na mwezi ukawa na nuru, na akaupimia vituo ili mjue idadi ya miaka na hesabu. Mwenyezi Mungu hakuviumba hivyo isipokuwa kwa haki. Anazipambanua Ishara kwa kaumu wanaojua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 6, 'Hakika katika kuhitilafiana usiku na mchana, na katika vile alivyoviumba Mwenyezi Mungu katika mbingu na ardhi, zipo Ishara kwa kaumu wamchao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 7, 'Hakika wale wasiotaraji kukutana nasi, na wakaridhia uhai wa dunia hii na wakatua nao, na wale walioghafilika mbali na Ishara zetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 8, 'Hao, makazi yao ni Motoni kwa sababu ya yale waliyokuwa wakiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 9, 'Hakika wale walioamini na wakatenda mema, Mola wao Mlezi atawaongoa kwa sababu ya Imani yao. Itapita mito kwa chini yao katika Mabustani yenye neema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 10, 'Wito wao humo utakuwa, “Subhanaka Allahumma (Umetakasika ewe Mwenyezi Mungu!)." Na maamkizi yao humo ni "Salama." Na mwisho wa wito wao ni, “Alhamdulillahi Rabbil ''aalamiin (Sifa zote njema ni za Mwenyezi Mungu, Mola Mlezi wa walimwengu wote)."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 11, 'Na lau kama Mwenyezi Mungu angeliwafanyia watu haraka kuwaletea maovu kama wanavyojiharakishia kuletewa heri, basi bila ya shaka wangelikwishatimiziwa muda wao. Lakini tunawaacha wale wasiotaraji kukutana nasi wakihangaika katika upotovu wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 12, 'Na mtu akiguswa na shida, hutuomba naye ameegesha ubavu, au amekaa au amesimama. Lakini tunapomwondoshea shida yake hiyo, huendelea kama kwamba hakuwahi kutuomba tumwondoshee shida iliyomgusa. Hivyo ndivyo walivyopambiwa wapitilizao viwango yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 13, 'Na hakika tuliviangamiza vizazi vya kabla yenu walipodhulumu, na waliwajia Mitume wao kwa Ishara zilizo wazi, lakini hawakuwa wenye kuamini. Hivyo ndivyo tunavyowalipa kaumu wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 14, 'Kisha tukawafanya nyinyi ndio wenye kushika pahala pao katika ardhi baada yao ili tuone jinsi mtakavyotenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 15, 'Na wanaposomewa Aya zetu zilizo wazi, wale wasiotaraji kukutana na Sisi husema, “Leta Qur-ani isiyokuwa hii, au ibadilishe.” Sema, “Haiwi kwangu niibadilishe nitakavyo mimi mwenyewe. Mimi sifuati isipokuwa yale ninayofunuliwa kwa Wahyi. Hakika mimi ninahofu, nikimuasi Mola wangu Mlezi, adhabu ya Siku iliyo kuu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 16, 'Sema, “Mwenyezi Mungu angelitaka, nisingeliwasomea, wala nisingelikuwa mwenye kukijua zaidi yenu. Kwani nilikwishakaa miongoni mwenu umri mzima kabla yake! Kwani, hamtii akilini?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 17, 'Basi ni nani aliye dhalimu zaidi kuliko yule anayemzulia uongo Mwenyezi Mungu na akazikadhibisha Ishara zake? Hakika hawafaulu wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 18, 'Nao wanaabudu badala ya Mwenyezi Mungu wale wasiowadhuru wala kuwanufaisha, na wanasema, “Hawa ndio waombezi wetu kwa Mwenyezi Mungu!” Sema, “Je, mnamwambia Mwenyezi Mungu yale asiyoyajua ya katika mbingu wala katika ardhi? Ametakasika na ametukuka mbali na hao wanaomshirikisha nao.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 19, 'Na watu hawakuwa isipokuwa Umma mmoja tu, kisha wakahitilafiana. Na lau kuwa si neno lililokwishatangulia kutoka kwa Mola wako Mlezi, hakuna shaka hukumu ingelikwishakatwa baina yao katika yale wanayohitilafiana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 20, 'Na wanasema, “Kwa nini hakuteremshiwa Ishara kutoka kwa Mola wake Mlezi?” Sema, “Hakika mambo ya ghaibu ni ya Mwenyezi Mungu tu. Basi nyinyi ngojeni, na mimi niko pamoja nanyi katika wanaongojea.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 21, 'Na tunapowaonjesha watu rehema baada ya shida iliyowagusa, tazama, wanafanya njama katika Ishara zetu. Sema, “Mwenyezi Mungu ni Mwepesi zaidi wa kupanga njama. Hakika wajumbe wetu wanayaandika hayo mnayoyapangia njama.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 22, 'Yeye ndiye anayewaendesha katika nchi kavu na baharini. Mpaka mnapokuwa katika majahazi na yakawa yanakwenda nao kwa upepo mzuri na wakaufurahia, upepo mkali ukayajia, na yakawajia mawimbi kutokea kila mahali, na wakaona kwamba wameshazingirwa, basi hapo wanamwomba Mwenyezi Mungu kwa kumpwekeshea yeye tu dini, “Ukituokoa kutokana na haya, bila ya shaka tutakuwa miongoni mwa wanaoshukuru.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 23, 'Lakini anapowaokoa, tazama, wanafanya jeuri tena katika ardhi bila ya haki. Enyi watu! Hakika jeuri zenu zitawadhuru nyinyi wenyewe. Hii ni starehe ya maisha ya dunia tu. Kisha marejeo yenu ni kwetu, na hapo tutawaambia yale mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 24, 'Hakika mfano wa uhai wa dunia hii ni kama maji tuliyoyateremsha kutoka mbinguni, kisha mimea ya ardhi ikachanganyika nayo miongoni mwa vile wanavyovila watu na wanyama. Mpaka ardhi ilipokamilika uzuri wake, na ikapambika, na wenyewe wakadhani kwamba wameshaiweza, iliifikia amri yetu usiku au mchana, kwa hivyo tukaifanya kama iliyofyekwa, kama kwamba haikuwapo jana. Hivyo ndivyo tunavyozipambanua Ishara zetu kwa kaumu wanaotafakari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 25, 'Na Mwenyezi Mungu anaita kwenye Nyumba ya amani, na anamwongoa amtakaye kwenye Njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 26, 'Kwa wafanyao uzuri, ni uzuri na zaidi. Wala vumbi halitawafunika nyuso zao, wala madhila. Hao ndio watu wa Bustanini. Wao, humo watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 27, 'Na wale waliochuma mabaya, malipo ya baya ni kwa mfano wake, na watafunikwa na madhila. Hawatakuwa na wa kuwalinda kutokana na Mwenyezi Mungu. Nyuso zao ni kama kwamba zimefunikwa na vipande vya usiku wa giza. Hao ndio watu wa Motoni. Wao, humo watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 28, 'Na siku tutakapowakusanya wote, kisha tutawaambia wale walioshirikisha, "Simameni mahali penu nyinyi na washirika wenu." Kisha tutatenganisha baina yao. Na hao washirika wao watasema, "Nyinyi hamkuwa mkituabudu sisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 29, 'Basi Mwenyezi Mungu anatosha kuwa ni shahidi baina yetu na nyinyi. Hakika sisi tulikuwa hatuna habari na ibada yenu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 30, 'Huko kila nafsi itayajua iliyoyatanguliza. Na watarudishwa kwa Mwenyezi Mungu, Mola wao wa haki, na yote ya uongo waliyokuwa wakiyazua yatawapotea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 31, 'Sema, "Ni nani anayekuruzukuni kutoka mbinguni na ardhini? Au ni nani anayemiliki kusikia na kuona? Na ni nani atoaye kilicho hai kutoka kwa maiti, na atoaye maiti kutoka kwa kilicho hai? Na ni nani anayeyaendesha mambo yote?" Basi watasema, "Mwenyezi Mungu." Basi sema, "Je, hamchi?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 32, 'Basi huyo ndiye Mwenyezi Mungu, Mola wenu Mlezi wa haki. Na kipo kitu gani baada ya haki, isipokuwa upotovu tu? Basi ni vipi mnageuzwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 33, 'Ndivyo hivyo kauli ya Mola wako Mlezi ilivyowathibitikia wale waliovuka mipaka ya kwamba hawataamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 34, 'Sema: Je, yupo katika washirika wenu mwenye kuanzisha kuumba viumbe, kisha akavirejesha? Sema: Mwenyezi Mungu anaanzisha kuumba viumbe, kisha anavirejesha. Basi ni vipi mnadanganywa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 35, 'Sema, "Je, yupo yeyote katika washirika wenu mwenye kuongoa kwenye haki?" Sema, "Mwenyezi Mungu anaongoa kwenye haki." Basi, je, yule anayeongoa kwenye haki anastahiki zaidi kufuatwa au yule asiyeongoka isipokuwa akiongozwa? Basi nyinyi mna nini, mnahukumu namna gani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 36, 'Na wengi wao hawafuati isipokuwa dhana tu. Na hakika, dhana haifai kitu mbele ya haki. Hakika Mwenyezi Mungu anajua zaidi yote wanayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 37, 'Na haikuwa Qur-ani hii ni ya kuzuliwa kutoka kwa asiyekuwa Mwenyezi Mungu. Lakini ni usadikisho wa yale yaliyoitangulia, na ni maelezo ya kina ya Kitabu kisicho na shaka yoyote ndani yake, kutoka kwa Mola Mlezi wa viumbe vyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 38, 'Ama ndiyo wanasema ameizua? Sema, "Hebu leteni sura moja mfano wake na muwaite muwawezao, kando na Mwenyezi Mungu, ikiwa nyinyi ni wakweli."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 39, 'Bali waliyakadhibisha yale wasiyoyaelewa elimu yake vyema kabla hayajawajia maelezo yake. Hivyo ndivyo walivyokadhibisha wale waliokuwa kabla yao. Basi angalia jinsi ulivyokuwa mwisho wa madhalimu hao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 40, 'Na miongoni mwao kuna anayeiamini, na miongoni mwao kuna asiyeiamini. Na Mola wako Mlezi ndiye anayewajua vyema waharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 41, 'Na wakikukadhibisha, basi sema, "Mimi nina matendo yangu, na nyinyi mna matendo yenu. Nyinyi mko mbali sana na yale ninayoyatenda, nami niko mbali sana na mnayoyatenda."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 42, 'Na miongoni mwao kuna wale wanaokusikiliza. Je, wewe unaweza wasikizisha viziwi hata kama hawatumii akili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 43, 'Na miongoni mwao kuna yule anayekutazama. Je, wewe unaweza kuwaongoa vipofu hata kama hawaoni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 44, 'Hakika Mwenyezi Mungu hawadhulumu watu kitu chochote, lakini watu wenyewe wanazidhulumu nafsi zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 45, 'Na Siku atakapowakusanya, itakuwa kama kwamba hawakukaa isipokuwa saa moja tu katika mchana! Watatambuana. Hakika wamehasirika wale waliokadhibisha kukutana na Mwenyezi Mungu, wala hawakuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 46, 'Na ima tutakuonyesha baadhi ya yale tunayowaahidi, au tukufishe kabla yake, basi marejeo yao ni kwetu. Kisha Mwenyezi Mungu ni Shahidi wa wanayoyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 47, 'Na kila umma una Mtume. Kwa hivyo, anapowajia Mtume wao, inahukumiwa baina yao kwa uadilifu, nao hawadhulumiwi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 48, 'Na wanasema, “Ni lini ahadi hii, ikiwa nyinyi ni wakweli?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 49, 'Sema: Sijimilikii nafsi yangu shari wala kheri ila apendavyo Mwenyezi Mungu. Kila umma una muda wao waliowekewa. Ukifika muda wao, hawakawii hata saa moja wala hawatangulii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 50, 'Sema, “Mnaonaje ikiwajia adhabu yake hiyo usiku au mchana. Basi wahalifu wanaharakisha nini?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 51, 'Tena je, ikishatokea ndiyo mtaiamini? Je, sasa? Na ilhali mlikuwa mkiifanyia haraka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 52, 'Kisha wale waliodhulumu wataambiwa, "Ionjeni adhabu ya kudumu. Kwani mtalipwa isipokuwa yale mliyokuwa mkiyachuma?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 53, 'Na wanakuuliza, "Je, ni kweli hayo?" Sema, "Ehe! Ninaapa kwa Mola wangu Mlezi! Hakika hayo ni kweli, na wala nyinyi hamtashinda."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 54, 'Na lau kuwa kila nafsi iliyodhulumu inamiliki kila kilichomo katika ardhi, basi bila ya shaka ingejikomboa kwavyo. Na watakapoiona adhabu, wataficha majuto. Na itahukumiwa baina yao kwa uadilifu, nao hawatadhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 55, 'Jueni kuwa hakika ni vya Mwenyezi Mungu vyote vilivyo katika mbingu na katika ardhi. Jueni kuwa hakika ahadi ya Mwenyezi Mungu ni ya haki. Lakini wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 56, 'Yeye ndiye anayehuisha na anayefisha. Na kwake mtarejeshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 57, 'Enyi watu! Yamekwishawajia mawaidha kutoka kwa Mola wenu Mlezi, na ponya ya yale yaliyo katika vifua, na uongofu, na rehema kwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 58, 'Sema, "Kwa fadhila ya Mwenyezi Mungu na rehema yake! Basi na wafurahi kwa hayo. Hayo ndiyo bora kuliko hayo wanayoyakusanya."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 59, 'Sema: Je, mnaonaje yale aliyowateremshia Mwenyezi Mungu katika riziki, basi mkafanya katika hizo nyingine haramu na nyingine halali. Sema, "Je, Mwenyezi Mungu aliwaruhusu, au mnamzulia Mwenyezi Mungu tu?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 60, 'Na ni nini dhana ya wale wanaomzulia Mwenyezi Mungu uongo Siku ya Kiyama? Hakika Mwenyezi Mungu ni mwenye fadhila juu ya watu, lakini wengi wao hawashukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 61, 'Na huwi katika jambo lolote, wala husomi sehemu yoyote katika Qur-ani, wala hamtendi kitendo chochote isipokuwa Sisi huwa ni mashahidi juu yenu mnaposhughulika nayo. Na hakifichikani kwa Mola wako Mlezi chenye uzito hata wa chembe katika ardhi na katika mbingu, wala kidogo kuliko hicho wala kikubwa isipokuwa kimo katika Kitabu kibainifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 62, 'Jueni kuwa vipenzi wa Mwenyezi Mungu hawana hofu yoyote juu yao wala hawatahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 63, 'Wale walioamini na wakawa wachaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 64, 'Wao wana bishara njema katika uhai wa dunia na katika Akhera. Hakuna mabadiliko katika maneno ya Mwenyezi Mungu. Huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 65, 'Wala yasikuhuzunishe maneno yao. Hakika utukufu wote ni wa Mwenyezi Mungu. Yeye ndiye Mwenye kusikia vyema, Mwenye kujua yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 66, 'Jueni kuwa ni vya Mwenyezi Mungu vyote vilivyo katika mbingu na katika ardhi. Na wala hawafuati hao wanaoomba badala ya Mwenyezi Mungu washirika wowote. Wao hawafuati isipokuwa dhana tu, na hawasemi isipokuwa uongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 67, 'Yeye ndiye aliyewawekea usiku ili mtulie humo, na mchana wa kuonea. Hakika katika haya zipo Ishara kwa kaumu wanaosikia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 68, 'Walisema, "Mwenyezi Mungu alijifanyia mwana." Ametakasika! Yeye ndiye asiyehitajia kitu. Ni vyake vilivyo katika mbingu na katika ardhi. Nyinyi hamna uthibitisho wowote wa haya! Je, mnamzulia Mwenyezi Mungu msiyoyajua?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 69, 'Sema, "Hakika wale wanaomzulia uongo Mwenyezi Mungu hawatafanikiwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 70, 'Hiyo ni starehe ya duniani tu, kisha marejeo yao ni kwetu. Kisha tutawaonjesha adhabu kali kwa sababu ya yale waliyokuwa wakikufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 71, 'Na wasomee habari za Nuhu alipowaambia kaumu yake: Enyi kaumu yangu! Ikiwa ni kukubwa kwenu kukaa kwangu nanyi na kuwakumbusha kwangu kwa Ishara za Mwenyezi Mungu, basi mimi namtegemea Mwenyezi Mungu. Kwa hivyo, nyinyi likusanyeni jambo lenu pamoja na washirika wenu, kisha jambo lenu hilo lisiwe la kufichikana kwenu, kisha nihukumuni, wala msinipe muhula.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 72, 'Na mkigeuka, basi mimi sikuwaomba ujira wowote. Ujira wangu hauko isipokuwa kwa Mwenyezi Mungu. Na nimeamrishwa kwamba niwe miongoni mwa Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 73, 'Lakini wakamkadhibisha. Kwa hivyo tukamwokoa, pamoja na wale waliokuwa naye, katika jahazi. Na tukawafanya wao ndio waliobakia, na tukawazamisha wale waliozikadhibisha Ishara zetu. Basi angalia vipi ulikuwa mwisho wa walioonywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 74, 'Kisha baada yake tukawatuma Mitume kwa kaumu zao. Nao wakawajia kwa Ishara zilizo wazi. Lakini hawakuwa wenye kuyaamini wale waliyoyakanusha kabla yake. Hivyo ndivyo tunavyoziziba nyoyo za wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 75, 'Kisha baada yao tukamtuma Musa na Haruni kwa Firauni na waheshimiwa wake, kwa Ishara zetu. Wakatakabari, na wakawa kaumu wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 76, 'Basi ilipowajia haki kutoka kwetu, walisema: Hakika huu ni uchawi ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 77, 'Akasema Musa, "Je, mnasema hivi juu ya haki ilipowajia? Je, huu ni uchawi? Na wachawi hawafanikiwi!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 78, 'Wakasema: Je, umetujia ili utuachishe tuliyowakuta nayo baba zetu, na mpate nyinyi wawili ukubwa katika ardhi? Wala sisi hatuwaamini nyinyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 79, 'Na Firauni akasema: Nileteeni kila mchawi ajuaye zaidi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 80, 'Basi walipokuja wachawi hao, Musa akawaambia: Vitupeni mnavyovitupa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 81, 'Basi walipotupa, Musa akasema: Mliyoleta ndiyo uchawi. Hakika Mwenyezi Mungu ataubatilisha. Hakika Mwenyezi Mungu hayatengenezi matendo ya waharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 82, 'Na Mwenyezi Mungu huihakikisha haki kwa maneno yake, hata wakichukia wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 83, 'Basi hawakumwamini Musa isipokuwa baadhi ya vijana kutoka kwa kaumu yake, kwa kumwogopa Firauni na wakuu wao wasiwatese. Kwani hakika Firauni alikuwa jeuri katika ardhi. Na kwa yakini alikuwa miongoni mwa waliopita kiasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 84, 'Na Musa alisema: Enyi kaumu yangu! Ikiwa nyinyi mmemwamini Mwenyezi Mungu, basi mtegemeeni Yeye, ikiwa nyinyi ni Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 85, 'Wakasema: Tunamtegemea Mwenyezi Mungu. Ewe Mola wetu Mlezi! Usitufanye wenye kutiwa majaribio na hawa kaumu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 86, 'Na utuokoe kwa rehema yako kutokana na kaumu hawa makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 87, 'Na tukamteremshia ufunuo (wahyi) Musa na ndugu yake kuwa: Watengenezeeni majumba kaumu yenu katika Misri na zifanyeni nyumba zenu ndimo mahali pa ibada, na mdumishe Swala, na wape habari njema Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 88, 'Na Musa akasema: Mola wetu Mlezi! Hakika wewe umempa Firauni na wakuu wake mapambo na mali katika uhai wa dunia. Hivyo wanapoteza watu kutoka kwa njia yako. Mola wetu Mlezi! Zifutilie mbali mali hizo na zifunge nyoyo zao, wasiamini mpaka waione adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 89, 'Mwenyezi Mungu akasema: Hakika maombi yenu wawili yameshakubaliwa. Basi nyookeni, wala msifuate njia ya wale wasiojua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 90, 'Tukawavusha bahari Wana wa Israili, naye Firauni na askari wake wakawafuata kwa dhuluma na uadui. Mpaka kuzama kulipomfikia, akasema: Nimeamini kuwa hakuna mungu isipokuwa yule ambaye walimwamini Wana wa Israili, na mimi ni miongoni mwa Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 91, 'Je, sasa? Na ilhali uliasi kabla yake na ukawa miongoni mwa waharibifu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 92, 'Leo basi, tutakuokoa kwa mwili wako, ili uwe Ishara kwa wale walio nyuma yako. Na hakika watu wengi wameghafilika mbali na Ishara zetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 93, 'Na hakika tuliwaandalia Wana wa Israili makao mema, na tukawaruzuku katika vitu vizuri. Nao hawakuhitilafiana mpaka ilipowafikia elimu. Hakika Mola wako Mlezi atahukumu baina yao Siku ya Kiyama katika yale waliyokuwa wakihitilafiana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 94, 'Na ikiwa uko katika shaka juu ya yale tuliyokuteremshia, basi waulize wale wasomao Kitabu kabla yako. Kwa yakini imekwishakujia haki kutoka kwa Mola wako Mlezi. Basi kamwe usiwe miongoni mwa wenye shaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 95, 'Na kamwe usiwe miongoni mwa wale waliozikadhibisha Ishara za Mwenyezi Mungu, ukawa katika waliohasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 96, 'Hakika wale ambao neno la Mola wako Mlezi limekwishathibitika juu yao, hawataamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 97, 'Hata kama itawajia kila Ishara, mpaka waione adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 98, 'Basi kwa nini haukuwepo mji ulioamini, kwa hivyo Imani yake ikaufaa, isipokuwa kaumu ya Yunus? Walipoamini, tukawaondolea adhabu ya hizaya katika uhai wa dunia, na tukawastarehesha kwa muda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 99, 'Na angelitaka Mola wako Mlezi, wangeliamini walio katika ardhi wote kwa pamoja. Je, wewe utawalazimisha watu kwa nguvu mpaka wawe Waumini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 100, 'Na haiwi kwa nafsi kuamini isipokuwa kwa idhini ya Mwenyezi Mungu. Naye hujaalia adhabu juu ya wale wasiotumia akili zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 101, 'Sema: Angalieni yaliyo katika mbingu na ardhi! Na Ishara zote na maonyo haviwafai kitu kaumu wasioamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 102, 'Basi, je, wanangojea kingine isipokuwa kama yale yaliyotokea siku za watu waliopita kabla yao? Sema: Ngojeni! Nami hakika ni pamoja nanyi katika wanaongoja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 103, 'Kisha Sisi huwaokoa Mitume wetu na wale walioamini. Ndiyo kama hivyo, inatustahiki kuwaokoa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 104, 'Sema: Enyi watu! Ikiwa nyinyi mko katika shaka juu ya Dini yangu, basi mimi siwaabudu mnaowaabudu nyinyi badala ya Mwenyezi Mungu. Lakini mimi namwabudu Mwenyezi Mungu anayewafisha. Na nimeamrishwa kwamba niwe miongoni mwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 105, 'Na kwamba uuelekeze uso wako kwenye Dini ya kweli, kwa unyofu wala kamwe usiwe katika washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 106, 'Na wala usiombe badala ya Mwenyezi Mungu wale ambao hawakufai kitu wala hawakudhuru. Na ukifanya hivyo, basi wewe hakika ni miongoni mwa madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 107, 'Na Mwenyezi Mungu akikugusa kwa madhara, basi hakuna wa kukuondolea isipokuwa Yeye. Na akikutakia heri, basi hakuna wa kurudisha fadhila yake. Humsibu kwayo amtakaye katika waja wake, na Yeye ndiye Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 108, 'Sema: Enyi watu! Haki imekwishawajia kutoka kwa Mola wenu Mlezi. Kwa hivyo, anayeongoka, basi anaongoka kwa faida ya nafsi yake, na anayepotea, basi anapotea kwa hasara ya nafsi yake. Na mimi si mwakilishi juu yenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 109, 'Na wewe fuata yale yanayofunuliwa kwako kwa ufunuo (wahyi). Na vumilia mpaka Mwenyezi Mungu ahukumu, na Yeye ndiye mbora wa wanaohukumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 1, 'Alif Laam Raa.[1] Hiki ni Kitabu ambacho Aya zake zimefanywa kuwa sawasawa, kisha zikapambanuliwa kwa kina, kilichotoka kwa Mwenye Hekima, Mwenye habari zote.', '[1] Herufi hizi "Alif Laam Raa" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 2, 'Ili msimuabudu isipokuwa Mwenyezi Mungu. Hakika mimi kwenu ni mwonyaji na mbashiri nitokaye kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 3, 'Na ili mumwombe msamaha Mola wenu Mlezi, kisha mtubie kwake. Atawastarehesha starehe nzuri mpaka muda maalumu. Na atampa kila mwenye fadhila, fadhila yake. Na wakikengeuka, basi mimi hakika ninawahofia adhabu ya hiyo Siku Kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 4, 'Marejeo yenu ni kwa Mwenyezi Mungu tu. Naye ni Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 5, 'Hebu angalia! Ati wanafunika vilivyomo vifuani mwao ili wamfiche Mwenyezi Mungu! Jueni kuwa wanapojigubika nguo zao, Yeye anajua yale wanayoyaficha na yale wanayoyaweka hadharani. Hakika Yeye ni Mwenye kujua zaidi yaliyomo vifuani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 6, 'Na hakuna mnyama yoyote katika ardhi isipokuwa riziki yake iko kwa Mwenyezi Mungu. Naye anajua makao yake na mapitio yake. Yote hayo yako katika Kitabu chenye kubainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 7, 'Na Yeye ndiye aliyeziumba mbingu na ardhi katika siku sita. Na Kiti chake cha Enzi kilikuwa juu ya maji, ili awajaribu ni nani kati yenu ndiye mzuri zaidi wa matendo. Na wewe ukisema, "Hakika nyinyi mtafufuliwa baada ya kufa" hakika wale waliokufuru watasema, "Haya si isipokuwa uchawi ulio wazi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 8, 'Na hata tukiwacheleweshea adhabu mpaka muda uliokwishahisabiwa, wao hakika watasema, "Ni nini kinachoizuia?" Jueni! Siku itakapowajia, basi haitaondolewa kwao. Na yatawazingira yale waliyokuwa wakiyafanyia mzaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 9, 'Na tukimwonjesha mtu rehema kutoka kwetu, kisha tukaiondoa kwake, yeye hakika ni mwenye kukata tamaa, mwingi wa kukufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 10, 'Na tukimwonjesha neema baada ya madhara yaliyomgusa, hakika yeye husema, "Mabaya yamekwishaniondokea." Hakika yeye ni mwenye kufurahi, mwenye kujifahiri mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 11, 'Isipokuwa wale waliosubiri na wakatenda mema. Hao wana maghufira na malipo makubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 12, 'Basi labda utaacha baadhi ya yale yaliyofunuliwa kwako, na kifua chako kikaona dhiki kwa hayo, kwa sababu wanasema, "Mbona hakuteremshiwa hazina, au Malaika akaja pamoja naye?" Hakika, wewe ni mwonyaji tu, na Mwenyezi Mungu ndiye Mtegemewa kwa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 13, 'Au wanasema, "Ameizua?" Sema, "Basi leteni sura kumi zilizozuliwa mfano wake, na waiteni muwawezao isipokuwa Mwenyezi Mungu, ikiwa nyinyi ni wakweli."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 14, 'Na wasipokuitikieni, basi jueni ya kwamba (hii Qur-ani) imeteremshwa kwa elimu ya Mwenyezi Mungu, na kwamba hakuna mungu isipokuwa Yeye. Basi je, nyinyi ni Waislamu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 15, 'Yule ambaye anataka uhai wa dunia na mapambo yake, tutawalipa humo matendo yao kamili. Na wao humo hawatapunjwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 16, 'Hao ndio ambao hawana kitu katika Akhera isipokuwa Moto, na yataharibika yale waliyoyafanya humo, na yatabatilika yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 17, 'Basi je, yule ambaye ana ushahidi ulio wazi kutoka kwa Mola wake Mlezi, na unaofuatwa na shahidi anayetoka kwake, na kabla yake kilikuwapo Kitabu cha Musa kilichokuwa mwongozi na rehema. Hao wanaiamini. Naye anayeikufuru katika makundi, basi Moto ndipo pahali pa miadi yake. Kwa hivyo, usiwe katika shaka juu yake. Hakika, hii ni haki itokayo kwa Mola wako Mlezi, lakini wengi wa watu hawaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 18, 'Na ni nani aliye dhalimu zaidi kuliko yule anayemzulia Mwenyezi Mungu uongo? Hao wataletwa mbele ya Mola wao Mlezi, na mashahidi watasema, "Hawa ndio waliomdanganyishia Mola wao Mlezi. Sikilizeni! Laana ya Mwenyezi Mungu iwapate madhalimu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 19, 'Ambao wanazuilia njia ya Mwenyezi Mungu, na wanaitakia ijipinde, nao wanakufuru Akhera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 20, 'Hao hawakuwa ni wa kushinda katika ardhi, wala hawana walinzi wowote kando na Mwenyezi Mungu. Watazidishiwa adhabu; kwa kuwa, hawakuwa wakiweza kusikia wala hawakuwa wakiona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 21, 'Hao ndio waliozihasiri nafsi zao, na yakawapotea yale waliyokuwa wakiyazua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 22, 'Hakuna shaka kwamba wao katika Akhera ndio waliohasiri zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 23, 'Hakika, wale walioamini, na wakatenda mema, na wakanyenyekea kwa Mola wao Mlezi, hao ndio watu wa Bustanini, humo watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 24, 'Mfano wa makundi mawili haya ni kama kipofu na kiziwi, na mwenye kuona na anayesikia. Je, wawili hawa wanakuwa sawa kwa kufananishwa? Basi, je, hamkumbuki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 25, 'Na hakika, tulimtuma Nuhu kwa kaumu yake, akawaambia, "Hakika mimi ni mwonyaji aliye wazi kwenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 26, 'Ya kwamba msimuabudu isipokuwa Mwenyezi Mungu tu. Hakika mimi ninawahofia adhabu ya siku chungu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 27, 'Basi wakasema wakuu waliokufuru katika kaumu yake, "Hatukuoni wewe isipokuwa ni mtu tu mfano wetu, wala hatukuoni wamekufuata isipokuwa wale wetu walio duni, watu wasiokuwa na maoni. Wala hatuwaoni nyinyi kuwa mna ubora wowote kutushinda sisi. Bali tunawadhania nyinyi kuwa ni waongo."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 28, 'Akasema, "Enyi kaumu yangu! Hebu fikirini! Ikiwa mimi ninayo hoja wazi iliyotoka kwa Mola wangu Mlezi, na amenipa rehema kutoka kwake, nayo ikafichwa kwenu. Je, tuwalazimishe kuikubali ilhali nyinyi mnaichukia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 29, 'Na enyi kaumu yangu! Mimi siwaombi mali kwa ajili ya haya. Mimi sina ujira isipokuwa kwa Mwenyezi Mungu; na mimi sitawafukuza walioamini. Hakika wao watakutana na Mola wao Mlezi, lakini mimi nawaona mnafanya ujinga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 30, 'Na enyi kaumu yangu! Ni nani atakayeninusuru kwa Mwenyezi Mungu nikiwafukuza hawa? Basi je, hamkumbuki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 31, 'Wala siwaambii kuwa nina hazina za Mwenyezi Mungu, wala kuwa mimi ninajua mambo ya ghaibu, wala sisemi: Mimi ni Malaika. Wala sisemi kuhusu wale ambao yanawadharau macho yenu kuwa Mwenyezi Mungu hatawapa heri. Mwenyezi Mungu ndiye anayajua zaidi yaliyo katika nafsi zao. Hapo bila ya shaka nitakuwa miongoni mwa madhalimu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 32, 'Wakasema, "Ewe Nuhu! Umejadiliana nasi, na umekithirisha kutujadili. Basi tuletee hayo unayotuahidi, ikiwa wewe ni miongoni mwa wakweli."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 33, 'Akasema, "Hakika Mwenyezi Mungu tu ndiye atakayewaletea akitaka. Wala nyinyi si wenye kumshinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 34, 'Wala nasaha yangu haitawafaa kitu nikitaka kuwanasihi, ikiwa Mwenyezi Mungu anataka kuwapoteza. Yeye ndiye Mola wenu Mlezi, na kwake mtarejeshwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 35, 'Au ndio wanasema, "Ameizua?" Sema, "Ikiwa nimeizua, basi kosa hilo ni juu yangu, na mimi niko mbali sana na makosa myatendayo."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 36, 'Na akafunuliwa Nuhu akaambiwa, "Hataamini yeyote katika kaumu yako isipokuwa wale waliokwishaamini. Basi usisikitike kwa yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 37, 'Na unda jahazi mbele ya macho yetu na kwa mujibu wa ufunuo wetu. Wala usiniongeleshe kuwatetea wale waliodhulumu. Kwani hao bila ya shaka watazamishwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 38, 'Na akawa anaunda jahazi, na kila walipopita karibu nayo wakuu kutoka kwa kaumu yake, wanamkejeli. Yeye akasema, "Ikiwa nyinyi mnatukejeli, basi sisi pia tunawakejeli kama mnavyotukejeli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 39, 'Nanyi mtakuja jua ni nani itakayemfikia adhabu ya kumhizi, na itakayemteremkia adhabu ya kudumu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 40, 'Mpaka ilipokuja amri yetu, na tanuri ikafoka maji, tulisema, "Pakia humo katika kila kitu, jozi mbili ya dume na jike, na ahali zako, isipokuwa wale ambao imekwishawapitia hukumu, na watu walioamini." Na hawakuamini pamoja naye isipokuwa wachache tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 41, 'Na akasema, "Pandeni humo kwa jina la Mwenyezi Mungu, kwenda kwake na kusimama kwake. Hakika Mola wangu Mlezi ni Mwenye kusamehe, Mwenye kurehemu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 42, 'Ikawa inakwenda nao katika mawimbi kama milima. Na Nuhu akamwita mwanawe, naye alikuwa mbali: Ewe mwanangu! Panda pamoja nasi, wala usiwe pamoja na makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 43, 'Akasema: Nitakimbilia mlimani unilinde kutokana na maji. (Nuhu) akasema: "Leo hakuna wa kulindwa kutokana na amri ya Mwenyezi Mungu isipokuwa yule aliyemrehemu mwenyewe." Na wimbi likawatenganisha, basi akawa katika waliozama majini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 44, 'Na ikasemwa: "Ewe ardhi! Meza maji yako. Na ewe mbingu! Jizuie." Basi maji yakadidimia chini, na amri hiyo ikapitishwa, na (jahazi) likasimama juu ya (mlima) wa Al-Juudiy. Na ikasemwa: Wapotelee mbali kaumu madhalimu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 45, 'Na Nuhu alimwomba Mola wake Mlezi: Ee Mola wangu Mlezi! Hakika mwanangu ni katika ahali zangu, na hakika ahadi yako ndiyo ya haki. Na Wewe ndiye hakimu bora zaidi ya wote wanaohukumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 46, 'Akasema: Ewe Nuhu! Huyu si katika ahali zako. Hakika yeye ni (wa) matendo yasiyo mema. Basi usiniombe jambo usilo na elimu nalo. Mimi nakuwaidhi usije ukawa miongoni mwa wajinga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 47, 'Nuhu akasema: Ewe Mola wangu Mlezi! Mimi najikinga kwako kutokana na kukuomba nisilo na elimu nalo. Na kama hunisamehi na ukanirehemu, nitakuwa katika waliohasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 48, 'Ikasemwa: Ewe Nuhu! Shuka kwa salama itokayo kwetu, na baraka nyingi juu yako na juu ya umma miongoni mwa wale walio pamoja nawe. Na zitakuwapo umma tutakazozistarehesha, na kisha zitaguswa na adhabu chungu itokayo kwetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 49, 'Hizi ni katika habari za ghaibu tunazokufunulia. Hukuwa ukizijua wewe, wala kaumu yako, kabla ya haya. Basi subiri! Hakika Mwisho mwema ni wa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 50, 'Na kwa kina ''Aadi tulimtuma ndugu yao Hud. Akasema, "Enyi kaumu yangu! Muabuduni Mwenyezi Mungu! Hamna mungu isipokuwa Yeye tu. Nyinyi si chochote isipokuwa ni wazushi tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 51, 'Enyi watu wangu! Siwaombi ujira kwa ajili ya haya. Ujira wangu hauko isipokuwa kwa Yule aliyeniumba. Basi hamtumii akili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 52, 'Na enyi kaumu yangu! Mwombeni msamaha Mola wenu Mlezi, kisha mtubie kwake. Atawatumia mbingu zenye kunyesha mvua ya kumiminika kwa wingi, na atawazidishia nguvu juu ya nguvu zenu. Wala msigeuke mkawa wahalifu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 53, 'Wakasema, "Ewe Hud! Hujatuletea ushahidi ulio wazi. Wala sisi hatuiachi miungu yetu kwa kufuata kauli yako. Na wala sisi hatukuamini wewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 54, 'Sisi tunasema: ʻBaadhi ya miungu yetu imekusibu kwa baa.ʼˮ Akasema, “Hakika, mimi ninamshuhudisha Mwenyezi Mungu, na nyinyi shuhudieni, ya kwamba mimi niko mbali na hao mnaowafanya washirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 55, 'Badala ya Yeye. Basi nyinyi nyote nipangieni njama, na kisha msinipe muhula!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 56, 'Hakika mimi nimemtegemea Mwenyezi Mungu, Mola wangu Mlezi na Mola wenu Mlezi. Hakuna kiumbe yeyote isipokuwa Yeye anamwendesha atakavyo. Hakika Mola wangu Mlezi yuko kwenye njia iliyonyooka."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 57, 'Na wakikengeuka, "Basi hakika mimi nimekwishawafikishia yale niliyotumwa nayo kwenu. Na Mola wangu Mlezi atawaleta watu wengine badala yenu, wala nyinyi hamumdhuru kitu Yeye. Hakika Mola wangu Mlezi ni Mwenye kuhifadhi vyema kila kitu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 58, 'Na ilipofika amri yetu, tulimwokoa Hud na wale walioamini pamoja naye, kwa rehema itokayo kwetu. Na tukawaokoa kutokana na adhabu nzito.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 59, 'Na hao ndio kina ''Aadi. Walizikufuru Ishara za Mola wao Mlezi, na wakawaasi Mitume wake, na wakafuata amri ya kila jabari mkaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 60, 'Na wakafuatishiwa laana katika dunia hii na Siku ya Kiyama. Basi tambueni mtanabahi kuwa hakika kina ''Aadi walimkufuru Mola wao Mlezi. Na tambueni mtanabahi kuwa hakika waliangamizwa kina ''Aadi, kaumu ya Hud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 61, 'Na kina Thamud tuliwatumia ndugu yao Saleh. Akasema: Enyi kaumu yangu! Muabuduni Mwenyezi Mungu. Nyinyi hamna mungu yeyote isipokuwa Yeye. Yeye ndiye aliyewaumba kutoka katika ardhi, na akawaweka humo imara. Basi mwombeni msamaha, kisha mtubu kwake. Hakika Mola wangu Mlezi yupo karibu, anaitikia maombi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 62, 'Wakasema: Ewe Saleh! Hakika kabla ya haya ulikuwa unatarajiwa heri kwetu. Je, unatukataza kuwaabudu wale ambao baba zetu walikuwa wakiwaabudu? Na hakika sisi tuna shaka na wasiwasi kwa hayo unayotuitia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 63, 'Akasema: Enyi kaumu yangu! Mnaonaje ikiwa ninao ushahidi ulio wazi kutoka kwa Mola wangu Mlezi, naye akawa amenipa rehema kutoka kwake, je, ni nani atakayeninusuru kutokana na Mwenyezi Mungu nikimuasi? Basi nyinyi hamnizidishii isipokuwa kuhasirika tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 64, 'Na enyi kaumu yangu! Huyu ni ngamia wa Mwenyezi Mungu awe Ishara kwenu. Basi mwacheni ale katika ardhi ya Mwenyezi Mungu, wala msimguse kwa ubaya, ikaja kuwaangamiza adhabu iliyo karibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 65, 'Lakini wakamchinja. Basi (Saleh) akasema: Stareheni katika makazi yenu (muda wa) siku tatu. Hiyo ni ahadi isiyokuwa ya uongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 66, 'Basi ilipokuja amri yetu, tulimwokoa sawasawa Saleh na wale walioamini pamoja naye kwa rehema yetu kutokana na hizaya ya siku ile. Hakika Mola wako Mlezi ndiye Mwenye nguvu, Mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 67, 'Na ukelele uliwaangamiza wale waliodhulumu, basi wakawa majumbani mwao wamekufa kifudifudi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 68, 'Kama kwamba hawakuishi huko kwa ustawi. Hebu zingatieni! Hakika kina Thamud walimkufuru Mola wao Mlezi. Hebu zingatieni! Thamud walipotelea mbali!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 69, 'Na hakika wajumbe wetu walimjia Ibrahim kwa bishara njema, wakasema, "Salama!" Naye akasema, "Salama!" Kisha hakukaa isipokuwa mara hiyo akaja na ndama wa kuchoma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 70, 'Basi alipoiona mikono yao haimfikii, akawatilia shaka, na akawahofu. Wakasema, "Usihofu! Hakika sisi tumetumwa kwa kaumu ya Lut."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 71, 'Na mkewe alikuwa amesimama wima, akacheka. Basi tukambashiria kuhusu (kuzaliwa kwa) Is-haq, na baada ya Is-haq, Yaaqub.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 72, 'Akasema, "Ole wangu! Mimi nizae ilhali mimi ni ajuza? Na tena huyu mume wangu ni mzee? Hakika haya ni mambo ya ajabu!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 73, 'Wakasema: Je, unastaajabia amri ya Mwenyezi Mungu? Rehema ya Mwenyezi Mungu na baraka zake ziwe juu yenu, enyi watu wa nyumba hii! Hakika Yeye ndiye Msifiwa, Mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 74, 'Basi hofu ilipomwondoka Ibrahim, na ikawa ile bishara imemfikia, alianza kujadiliana nasi juu ya kaumu ya Lut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 75, 'Hakika Ibrahim alikuwa mvumilivu sana, mwenye huzuni kubwa, na mwepesi wa kurejea kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 76, '(Akaambiwa): Ewe Ibrahim! Achilia mbali haya! Hakika amri ya Mola wako Mlezi imekwishakuja, na hakika hao itawafikia adhabu isiyorudishwa nyuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 77, 'Na wajumbe wetu walipomjia Lut, yakamuwia mabaya kwa sababu yao na akaona dhiki kubwa kwa sababu yao. Akasema: Hii ni siku ngumu sana!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 78, 'Wakamjia kaumu yake mbio mbio. Na kabla ya haya walikuwa wakitenda mabaya. Yeye akasema: Enyi kaumu yangu! Hawa binti zangu, ndio wametakasika zaidi kwenu. Basi mcheni Mwenyezi Mungu, wala msinihizi mbele ya wageni wangu. Hivyo je, hakuna hata mwanamume mmoja miongoni mwenu aliyeongoka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 79, 'Wakasema: Bila shaka umekwishajua hatuna haki yoyote juu ya binti zako, na hakika wewe unayajua yale tunayoyataka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 80, 'Akasema: Laiti ningelikuwa na nguvu dhidi yenu, au nijilinde kwenye nguzo yenye nguvu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 81, '(Wajumbe) wakasema: Ewe Lut! Sisi ni wajumbe wa Mola wako Mlezi. Hawa hawatakufikia. Basi wewe ondoka pamoja na ahali zako usiku ungalipo. Wala yeyote miongoni mwenu asitazame nyuma, isipokuwa mkeo, kwani yeye utamfika msiba utakaowafika hao. Hakika miadi yao ni asubuhi. Je, kwani asubuhi haiko karibu sana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 82, 'Basi ilipokuja amri yetu, tuliigeuza nchi juu chini, na tukaiteremshia mvua ya changarawe za udongo mgumu uliokamatana wa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 83, 'Zilizotiwa alama kwa Mola wako Mlezi. Na haya hayako mbali na madhalimu wengineo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 84, 'Na kwa watu wa Madyana tuliwatumia ndugu yao Shu''aib. Akasema: Enyi kaumu yangu! Mwabuduni Mwenyezi Mungu. Nyinyi hamna mungu yoyote isipokuwa Yeye, wala msipunguze vipimo na mizani. Mimi ninawaona mko katika hali njema, nami ninawahofia adhabu ya siku kubwa hiyo itakayowazingira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 85, 'Na enyi kaumu yangu! Timizeni vipimo na mizani kwa uadilifu wala msiwapunje watu vitu vyao, wala msienee katika ardhi mkifanya uharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 86, 'Alivyowabakishia Mwenyezi Mungu ndivyo bora kwenu, ikiwa nyinyi ni Waumini. Wala mimi si mlinzi wenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 87, 'Wakasema: Ewe Shu''aibu! Je, ni sala zako ndizo zinazokuamrisha tuyaache yale waliyokuwa wakiyaabudu baba zetu, au tuache kufanya tupendavyo katika mali zetu? Ama hakika wewe ni mstahamilivu kweli na mwongofu mno!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 88, 'Akasema: Enyi kaumu yangu! Mnaonaje ikiwa ninao ushahidi ulio wazi kutoka kwa Mola wangu Mlezi, na ikawa Yeye ameniruzuku riziki njema kutoka kwake? Wala mimi sitaki kuwahalifu nikafanya yale ninayowakataza. Sitaki isipokuwa kutengeneza kiasi ninavyoweza. Na sipati kuwezeshwa haya isipokuwa na Mwenyezi Mungu. Kwake Yeye ninategemea, na kwake Yeye ninarudi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 89, 'Na enyi kaumu yangu! Kuhalifiana nami kusiwapelekee hata mkasibiwa na mfano wa yale waliyosibiwa kaumu ya Nuhu, au kaumu ya Hud, au kaumu ya Saleh. Na kaumu ya Lut si mbali nanyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 90, 'Na ombeni msamaha kwa Mola wenu Mlezi, tena tubuni kwake. Hakika Mola wangu Mlezi ni Mwenye kurehemu sana, Mwenye upendo mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 91, 'Wakasema: Ewe Shu''aibu! Mengi katika hayo unayoyasema hatuyafahamu. Na sisi tunakuona dhaifu miongoni mwetu. Na lau kuwa si jamaa zako, tungekupiga mawe, wala wewe si mtukufu kwetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 92, 'Akasema: Enyi kaumu yangu! Kwani jamaa zangu ni watukufu zaidi kwenu kuliko Mwenyezi Mungu? Na Yeye mmemueka nyuma ya migongo yenu! Hakika Mola wangu Mlezi ni Mwenye kuyazingira yote mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 93, 'Na enyi kaumu yangu! Fanyieni katika mahali penu, na mimi pia ninafanya. Karibuni mtajua ni nani itakayemfikia adhabu ya kumhizi, na ni nani mwongo. Na ngojeni, hakika mimi pia ninangoja pamoja nanyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 94, 'Na amri yetu ilipokuja, tulimwokoa sawasawa Shu''aibu na wale walioamini pamoja naye kwa rehema kutoka kwetu. Na ukelele uliwanyakua wale waliodhulumu, na wakaishia wamekufa kifudifudi katika majumba yao!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 95, 'Kama kwamba hawakuishi humo kwa ustawi. Zingatia ilivyoangamia Madyana, kama ilivyoangamia Thamud!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 96, 'Na hakika tulimtuma Musa pamoja na Ishara zetu na uthibitisho ulio wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 97, 'Kwa Firauni na waheshimiwa wake. Lakini wao wakafuata amri ya Firauni, na amri ya Firauni haikuwa yenye uongofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 98, 'Siku ya Kiyama atawatangulia kaumu yake na atawaingiza Motoni. Na muingio mbaya zaidi ulioje huo unaoingiwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 99, 'Nao walifuatishwa laana hapa (duniani) na Siku ya Kiyama. Ni kipawa kibaya zaidi kilichoje walichopewa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 100, 'Hizi ni katika habari za miji, tunakusimulia. Mingine ipo bado na mingine ilifyekwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 101, 'Na Sisi hatukuwadhulumu, lakini wao wenyewe walizidhulumu nafsi zao. Na miungu yao waliyokuwa wakiiomba badala ya Mwenyezi Mungu haikuwafaa kitu ilipokuja amri ya Mola wako Mlezi. Na hiyo miungu haikuwazidishia isipokuwa maangamio tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 102, 'Na hivyo ndivyo ulivyo mshiko wa Mola wako Mlezi anapoishika miji inapokuwa imedhulumu. Hakika mshiko wake ni mchungu na mkali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 103, 'Hakika katika hayo ipo ishara kwa yule anayehofu adhabu ya Akhera. Hiyo ndiyo Siku itakayokusanyiwa watu, na hiyo ndiyo Siku itakayoshuhudiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 104, 'Na wala hatuiahirishi isipokuwa kwa muda unaohisabiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 105, 'Siku hiyo itakapokuja, nafsi yoyote haitazungumza isipokuwa kwa idhini yake. Basi miongoni mwao kutakuwa na walio mashakani na wenye furaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 106, 'Ama wale waliojitia mashakani, hao watakuwa Motoni, humo watavuta pumzi na kuitoa kwa ugumu mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 107, 'Watadumu humo muda wa kudumu mbingu na ardhi, isipokuwa atakavyo Mola wako Mlezi. Hakika Mola wako Mlezi hutenda atakavyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 108, 'Na ama wale waliofurahishwa, wao watakuwa katika Bustani wadumu humo muda wa kudumu mbingu na ardhi, isipokuwa atakavyo Mola wako Mlezi. Hicho ni kipawa kisicho na kikomo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 109, 'Basi usiwe katika shaka juu ya yale wanayoyaabudu hawa. Hawaabudu isipokuwa kama walivyoabudu baba zao zamani. Na hakika Sisi tutawatimizia fungu lao bila ya kulipunguza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 110, 'Na hakika tulimpa Musa Kitabu, lakini kukazuka kuhitilafiana ndani yake. Na lau kuwa si neno lililokwishatangulia kutoka kwa Mola wako Mlezi, bila ya shaka ingelihukumiwa baina yao. Na hakika wao wamo katika shaka juu yake inayowahangaisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 111, 'Na hakika Mola wako Mlezi atawatimizia malipo ya matendo yao wote. Hakika Yeye anayo habari ya yale wanayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 112, 'Basi, nyooka kama ulivyoamrishwa, wewe na wale wanaotubia kwa Mwenyezi Mungu pamoja nawe, wala msivuke mipaka. Hakika Yeye anayaona yote myatendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 113, 'Wala msiwategemee wale waliodhulumu, mkaja kuguswa na Moto. Wala nyinyi hamna walinzi wowote kando na Mwenyezi Mungu, wala tena hamtanusuriwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 114, 'Na dumisha Swala katika ncha mbili za mchana na nyakati za usiku zilizo karibu na mchana. Hakika mazuri huondoa mabaya. Huu ni ukumbusho kwa wanaokumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 115, 'Na subiri, kwani hakika Mwenyezi Mungu hapotezi ujira wa wafanyao mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 116, 'Basi mbona hawakuwepo katika vizazi vya kabla yenu wenye vyeo na wasaa wanaokataza uharibifu katika nchi, isipokuwa wachache tu, miongoni mwa wale tuliowaokoa miongoni mwao? Na wale waliodhulumu walifuata yale waliyostareheshwa kwayo, na walikuwa wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 117, 'Wala hakuwa Mola wako Mlezi wa kuiangamiza miji kwa dhuluma tu ilhali watu wake ni watenda mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 118, 'Na Mola wako Mlezi angelitaka, angewafanya watu wote wakawa umma mmoja. Lakini hawaachi kuhitilafiana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 119, 'Isipokuwa wale ambao Mola wako Mlezi amewarehemu. Na kwa hiyo ndiyo Mwenyezi Mungu amewaumba. Na lilitimia neno la Mola wako Mlezi kwamba hakika nitaijaza Jahannam kwa majini na watu kwa pamoja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 120, 'Na yote tunayokusimulia katika habari za Mitume yale tunayoimarisha kwayo (ufahamu wa) moyo wako. Na katika haya imekujia haki na mawaidha na ukumbusho kwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 121, 'Na waambie wale wasioamini, "Fanyieni mahali penu, nasi hakika pia tunafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 122, 'Na ngojeni, na sisi hakika tunangoja."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 123, 'Na ni ya Mwenyezi Mungu tu ghaibu ya mbinguni na ardhi, na mambo yote yatarejeshwa kwake. Basi muabudu Yeye na umtegemee. Na Mola wako Mlezi haghafiliki mbali na yale mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 1, 'Alif Laam Raa.[1] Hizi ni Aya za Kitabu kinachobainisha.', '[1] Herufi hizi "Alif Laam Raa" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 2, 'Hakika Sisi tumeiteremsha Qur-ani kwa Kiarabu ili mpate kuzingatia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 3, 'Sisi tunakusimulia simulizi nzuri zaidi kwa kukufunulia Qur-ani hii. Na ijapokuwa kabla ya haya ulikuwa miongoni mwa walioghafilika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 4, 'Yusuf alipomwambia baba yake: Ewe baba yangu! Hakika mimi nimeota nyota kumi na moja, na jua, na mwezi. Nimeviota vikinisujudia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 5, '(Baba) akasema: Ewe mwanangu! Usiwasimulie nduguzo ndoto yako, wakaja kukufanyia njama. Hakika Shetani ni adui aliye dhahiri kwa mwanadamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 6, 'Na hivyo ndivyo Mola wako Mlezi atakuteua na atakufundisha katika tafsiri ya mambo. Na atatimiza neema zake juu yako na juu ya ukoo wa Yaa''qub, kama alivyowatimizia hapo zamani baba zako Ibrahim na Is-haq. Hakika Mola wako Mlezi ni Mwenye kujua vyema, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 7, 'Kwa yakini katika Yusuf na nduguze ziko ishara kwa wanaouliza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 8, 'Pale waliposema: Hakika Yusuf na kakaye wanapendwa zaidi na baba yetu kuliko sisi, ilhali sisi ni kikundi chenye nguvu. Hakika baba yetu yuko katika upotovu wa dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 9, 'Muueni Yusuf, au mtupeni nchi ya mbali ili uso wa baba yenu uwaelekee nyinyi tu. Na baada ya haya mtakuwa kaumu njema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 10, 'Akasema msemaji miongoni mwao: Msimuue Yusuf. Lakini mtumbukizeni ndani ya kisima. Baadhi ya wasafiri watakuja mwokota; ikiwa kweli mnataka kufanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 11, 'Wakasema: Ewe baba yetu! Una nini hata hutuamini kwa Yusuf? Na hakika sisi ni wenye kumtakia heri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 12, 'Muachilie kesho pamoja nasi, ale kwa furaha na acheze, na bila ya shaka sisi tutamhifadhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 13, 'Akasema: Kwa hakika inanihuzunisha kwamba nyinyi mwende naye, na ninahofia aje mbwa mwitu akamla ilhali nyinyi mmeghafilika mbali naye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 14, 'Wakasema: Ikiwa mbwa mwitu atamla na ilhali sisi ni kundi lenye nguvu kabisa, basi bila ya shaka sisi tutakuwa tumehasirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 15, 'Basi walipokwenda naye, na wakakubaliana kwamba wamtumbukize ndani ya kisima, tulimfunulia Yusuf: Hakika utakujawaambia jambo lao hili, na wala wao hawatambui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 16, 'Wakamjia baba yao usiku wakilia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 17, 'Wakasema: Ewe baba yetu! Hakika tulikwenda kushindana na tukamwacha Yusuf penye vitu vyetu. Basi mbwa mwitu akamla. Lakini wewe hutuamini ijapokuwa sisi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 18, 'Na walikuja na shati lake likiwa lina damu ya uongo. Akasema: Bali nafsi zenu zimewashawishi kutenda kitendo. Lakini subira ni njema; na Mwenyezi Mungu ndiye wa kuombwa msaada kwa haya mnayoyaeleza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 19, 'Na ukaja msafara, kisha wakamtuma mchota maji wao, naye akatumbukiza ndoo yake. Alisema: Hii ni bishara njema! Huyu hapa mvulana! Wakamficha ili kumfanya ni bidhaa. Na Mwenyezi Mungu ni Mwenye kujua vyema hayo wanayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 20, 'Na wakamuuza kwa thamani duni, dirhamu za kuhesabika tu. Wala hawakuwa na haja naye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 21, 'Na yule aliyemnunua huko Misri alimwambia mkewe: "Mtengenezee huyu makazi ya heshima; huenda akatufaa au tukamfanya mwanetu." Basi hivyo ndivyo tulivyomuweka Yusuf imara katika ardhi ili tumfundishe kufasiri mambo. Na Mwenyezi Mungu ndiye Mwenye kushinda katika jambo lake, lakini wengi wa watu hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 22, 'Na alipofikia utu uzima wake, tukampa hukumu na elimu. Na hivyo ndivyo tunavyowalipa watendao mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 23, 'Na yule bibi wa nyumba aliyokuwamo Yusuf akamtamani kinyume cha nafsi yake, na akafungafunga milango. Akamwambia: "Njoo!" Yusuf akasema: Audhubillahi (ninajikinga kwa Mwenyezi Mungu)! Hakika Yeye ni bwana wangu, aliniweka maskani nzuri. Hakika madhalimu hawafaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 24, 'Na hakika yule mwanamke alimuazimia, na Yusuf akamuazimia lau kuwa hakuona ishara ya Mola wake Mlezi. Ilikuwa hivyo, ili tumuepushie mabaya na uchafu. Hakika yeye alikuwa katika waja wetu walioteuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 25, 'Na wote wawili wakakimbilia mlangoni, na mwanamke huyo akalirarua shati lake Yusuf kwa nyuma. Na wakamkuta bwana wake mlangoni. Mwanamke huyo akasema: Hakuna malipo ya mwenye kutaka kumfanyia mabaya mkeo isipokuwa afungwe au kupewa adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 26, 'Yusuf akasema: Yeye ndiye aliyenitaka bila ya mimi kumtaka. Na shahidi aliyekuwa katika jamaa za mwanamke akasema: Ikiwa shati lake limechanwa kwa mbele, basi mwanamke amesema kweli, naye Yusuf ni katika waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 27, 'Na ikiwa shati lake limechanwa kwa nyuma, basi mwanamke amesema uongo, naye Yusuf ni katika wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 28, 'Basi yule bwana alipoona shati lake limechanwa kwa nyuma, akasema: Hakika haya ni katika vitimbi vyenu wanawake. Hakika vitimbi vyenu ni vikuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 29, 'Yusuf! Achilia mbali haya. Na wewe mwanamke, omba msamaha kwa dhambi zako. Hakika wewe ni katika waliofanya makosa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 30, 'Na wanawake wa mjini wakawa wanasema: Mke wa Mheshimiwa anamtamani mtumishi wake bila ya yeye kumtaka! Hakika mapenzi yamemuingia sana moyoni. Sisi hakika tunamwona yuko katika upotovu ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 31, 'Basi aliposikia yule bibi masengenyo yao, aliwaita, na akawawekea matakia ya kuegemea, na akampa kila mmoja wao kisu. Akamwambia Yusuf: "Jitokeze mbele yao." Basi walipomwona, waliona ni kitu kikubwa kabisa, na wakajikatakata mikono yao. Wakasema: Hasha Lillahi (Ametakasika Mwenyezi Mungu)! Huyu si mwanadamu. Huyu si isipokuwa Malaika mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 32, 'Yule bibi akasema: Huyu basi ndiye huyo mliyenilaumia! Na kweli mimi nilimtaka naye akakataa. Na asipofanya ninayomwamrisha, basi hakuna shaka atafungwa gerezani, na atakuwa miongoni mwa walio duni kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 33, 'Yusuf akasema: Ee Mola wangu Mlezi! Ninapendelea kifungo kuliko haya anayoniitia. Na usiponiondoshea vitimbi vya wanawake hawa, mimi nitaelekea kwao, na nitakuwa katika wajinga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 34, 'Basi Mola wake Mlezi akamwitikia, na akamwondoshea vitimbi vyao. Hakika Yeye ni Mwenye kusikia, Mwenye kujua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 35, 'Kisha ikawadhihirikia baada ya kuona Ishara mbalimbali kuwa lazima wamfunge kwa muda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 36, 'Na wakaingia gerezani pamoja naye vijana wawili. Mmoja wao akasema: Hakika mimi nimeota kuwa ninakamua mvinyo. Na mwingine akasema: Hakika mimi nimeota kuwa nimebeba mikate juu ya kichwa changu, na ndege wanakula kwayo. Hebu tuambie tafsiri yake, kwani sisi tunakuona wewe ni katika watu wazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 37, 'Akasema: Hakitawajia chakula mtakachoruzukiwa isipokuwa nitawaambia hakika yake kabla ya kuwajia. Hayo ni katika yale aliyonifundisha Mola wangu Mlezi. Hakika mimi nimeacha mila ya kaumu wasiomuamini Mwenyezi Mungu, na wakawa wameikufuru Akhera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 38, 'Na nimefuata mila ya baba zangu, Ibrahim, na Is-haq, na Yaa''qub. Haikutufailia sisi kumshirikisha Mwenyezi Mungu na chochote. Hiyo ni katika fadhila za Mwenyezi Mungu juu yetu na juu ya watu, lakini wengi wa watu hawashukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 39, 'Enyi wafungwa wenzangu wawili! Je, mabwana wengi tofautitofauti ni bora au Mwenyezi Mungu Mmoja Mwenye nguvu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 40, 'Hamuabudu badala yake isipokuwa majina tu mliyowaita nyinyi na baba zenu. Mwenyezi Mungu hakuyateremshia hayo uthibitisho wowote. Hakuna hukumu isipokuwa ya Mwenyezi Mungu tu. Yeye ameamrisha msimuabudu yeyote isipokuwa Yeye tu. Hiyo ndiyo Dini iliyonyooka. Lakini wengi wa watu hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 41, 'Enyi wafungwa wenzangu wawili! Ama mmoja wenu, yeye atamnywesha bwana wake mvinyo. Na ama mwengine, yeye atasulubiwa, na ndege watakula katika kichwa chake. Imekwishakatwa hukumu ya hilo jambo mlilokuwa mkiuliza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 42, 'Na akamwambia yule aliyejua kuwa ataokoka katika wawili hao: "Nikumbuke kwa bwana wako." Lakini Shetani alimsahaulisha kumtaja kwa bwana wake. Basi Yusuf akakaa gerezani miaka kadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 43, 'Na siku moja mfalme alisema: Hakika mimi nimeota ng''ombe saba wanene wanaliwa na ng''ombe saba waliokonda. Na mashuke saba mabichi na mengine makavu. Enyi waheshimiwa! Niambieni maana ya ndoto zangu, ikiwa nyinyi mnaweza kuagua ndoto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 44, 'Wakasema: Hizi ni ndoto zilizoparaganyika, wala sisi sio wenye kujua tafsiri ya ndoto hizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 45, 'Hapo akasema yule aliyeokoka katika wale wawili na akakumbuka baada ya muda. Mimi nitawaambia tafsiri yake. Basi nitumeni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 46, 'Yusuf! Ewe mkweli! Tueleze ni nini maana ya ng''ombe saba wanene kuliwa na ng''ombe saba waliokonda. Na mashuke saba mabichi na mengine makavu, ili nirejee kwa watu ili wapate kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 47, 'Akasema: Mtalima miaka saba kwa juhudi. Kwa hivyo mtakachovuna, kiwacheni katika mashuke yake, isipokuwa kidogo mtachokula kwacho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 48, 'Kisha itakuja baadaye miaka saba ya shida itakayokula kile mlichoiwekea isipokuwa kidogo katika kile mtakachokihifadhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 49, 'Kisha baada ya haya utakuja mwaka ambao ndani yake watu watasaidiwa na watakamua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 50, 'Na mfalme akasema: "Nijieni naye!" Basi mjumbe huyo alipomjia, Yusuf akasema: Rudi kwa bwana wako na umuulize wana nini wale wanawake waliojikatakata mikono yao. Hakika Mola wangu Mlezi anazijua vyema njama zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 51, 'Mfalme alisema: Mlikuwa mna nini mlipomtaka Yusuf kinyume na nafsi yake? Wakasema: Hasha Lillahi (Mwenyezi Mungu apishe mbali)! Sisi hatukujua ubaya wowote kwake. Mke wa Mheshimiwa yule akasema: Sasa haki imedhihiri. Mimi ndiye niliyemtaka kinyume na nafsi yake, na hakika yeye ni katika wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 52, 'Hayo ni ili ajue ya kwamba sikumfanyia hiyana alipokuwa hayupo, na ya kwamba Mwenyezi Mungu haziongoi njama za wahaini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 53, 'Nami sijitoi lawamani. Kwa hakika nafsi ni yenye kuamrisha mno mabaya, isipokuwa kile alichorehemu Mola wangu Mlezi. Hakika Mola wangu Mlezi ni Msamehevu mno, Mwenye kurehemu sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 54, 'Basi mfalme akasema, "Nijieni naye, awe wangu mwenyewe hasa." Basi alipomsemesha, akasema, "Hakika wewe leo umekwishakuwa imara kwetu na umeaminika."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 55, 'Yusuf akasema: Nifanye msimamizi wa hazina za nchi. Kwani hakika mimi ni mlinzi mzuri, mwenye elimu sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 56, 'Basi hivyo ndivyo tulivyomuimarisha Yusuf katika ardhi, akawa anakaa humo popote anapotaka. Tunamfikishia rehema zetu tumtakaye, wala hatupotezi malipo ya wafanyao mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 57, 'Na hakika malipo ya Akhera ni bora zaidi, kwa wale walioamini na wakawa wanamcha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 58, 'Wakaja ndugu zake Yusuf, na wakaingia alimokuwa. Yeye akawajua, na wao hawakumjua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 59, 'Na alipowatengenezea tayari haja yao, alisema: Nileteeni ndugu yenu wa kwa baba yenu. Je, hamuoni ya kwamba mimi hakika ninatimiza kipimo, nami ni mbora wa wanaokaribisha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 60, 'Na msiponijia naye, basi hamtapata kipimo chochote kwangu, wala msinikaribie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 61, 'Wakasema: Sisi tutamrai baba yake amwachilie, na bila ya shaka tutafanya hilo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 62, 'Na Yusuf akawaambia watumishi wake: Tieni bidhaa zao katika mizigo yao, ili wazione watakaporudi kwa watu wao ili wapate kurejea tena.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 63, 'Basi waliporejea kwa baba yao, walisema: Ewe baba yetu! Tumenyimwa chakula zaidi. Basi muachilie ndugu yetu pamoja nasi ili tupate kupimiwa. Nasi hakika tutamlinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 64, 'Akasema: Je, niwaamini juu yake isipokuwa kama nilivyowaamini kwa kakaye zamani? Lakini Mwenyezi Mungu ndiye Mbora zaidi wa kulinda, naye ndiye Mbora zaidi wa wanaorehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 65, 'Na walipofungua mizigo yao, wakakuta bidhaa zao wamerudishiwa. Wakasema: Ewe baba yetu! Tutake nini zaidi? Hizi hapa bidhaa zetu tumerudishiwa. Wacha tuwaletee watu wetu chakula, na tutamlinda kaka yetu, na tutaongeza shehena ya ngamia. Na hicho ni kipimo kidogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 66, 'Akasema: Sitamuachilia pamoja nanyi mpaka mnipe agano kwa Mwenyezi Mungu kwamba lazima mtanijia naye isipokuwa ikiwa mtazungukwa. Basi walipompa agano lao, alisema: Mwenyezi Mungu ndiye Mtegemewa kwa tuyasemayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 67, 'Na akasema: Enyi wanangu! Msiingie kupitia mlango mmoja, bali ingieni kwa kupitia milango tofautitofauti. Wala mimi siwafai kitu mbele ya Mwenyezi Mungu. Hukumu haiko isipokuwa kwa Mwenyezi Mungu tu. Juu yake mimi nimetegemea, na juu yake na wategemee wanaotegemea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 68, 'Na walipoingilia pale alipowaamrisha baba yao, hakuwa wa kuwafaa kitu kwa Mwenyezi Mungu, isipokuwa ni haja tu iliyokuwa katika nafsi ya Yaa''qub aliyoitimiza. Na hakika yeye alikuwa na elimu kwa sababu tulimfundisha, lakini wengi wa watu hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 69, 'Na walipoingia alimokuwa Yusuf, alimkumbatia kakaye na akasema: Mimi hakika ndiye yule kaka yako. Basi usihuzunike kwa yale waliyokuwa wakiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 70, 'Na alipokwishawatayarishia mahitaji yao, akakitia kikopo cha kunywea maji katika mzigo wa kakaye huyo, kisha mwenye kunadi akanadi: Enyi msafara! Hakika nyinyi ni wezi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 71, 'Wakasema huku wamegeuka kuwaelekea, “Kwani mmepoteza nini?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 72, 'Wakasema: Tumepoteza kopo la mfalme. Na atakayenijia nalo, atapewa shehena nzima abebayo ngamia. Nami ni mdhamini juu ya hilo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 73, 'Wakasema: Tallahi! Hakika mlikwishajua vyema kwamba sisi hatukuja kufanya uharibifu katika nchi hii, wala sisi si wezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 74, 'Wakasema: Basi malipo yake ni nini ikiwa nyinyi ni waongo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 75, 'Wakasema: Malipo yake ni kwamba yule ambaye litapatikana katika shehena lake, basi huyo ndiye malipo yake. Hivyo ndivyo tunavyowalipa madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 76, 'Basi akaanza na mizigo yao kabla ya mzigo wa kakaye. Kisha akalitoa katika mzigo wa kakaye. Hivyo ndivyo tulivyompangia njama Yusuf. Hakuwa ni wa kumzuia kakaye kwa sheria ya mfalme huyo isipokuwa Mwenyezi Mungu akitaka. Tunamuinua daraja tumtakaye. Na juu ya kila ajuaye yupo ajuaye zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 77, 'Wakasema: Akiwa ameiba huyu, basi hakika kakaye vile vile aliiba hapo zamani. Lakini Yusuf akaliweka hilo kisiri katika moyo wake wala hakulionyesha kwao. Akasema: Nyinyi ndio mko katika pahali paovu zaidi, na Mwenyezi Mungu anajua zaidi hayo mnayosingizia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 78, 'Wakasema: Ewe Mheshimiwa! Hakika huyu anaye baba mzee sana. Kwa hivyo mchukue mmoja wetu badala yake. Hakika sisi tunakuona wewe ni katika watu wazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 79, 'Akasema: Mwenyezi Mungu apishe mbali kumshika yeyote yule isipokuwa yule tuliyemkuta naye kitu chetu. Hakika, hapo tutakuwa ni wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 80, 'Basi walipokata tamaa naye, wakaenda kando kunong''ona. Mkubwa wao akasema: Je! Hamjui ya kwamba baba yenu amechukua agano kutoka kwenu kwa Mwenyezi Mungu, na kabla ya hapo namna mlivyokosa katika agano lenu juu ya Yusuf? Basi mimi sitatoka nchi hii mpaka baba yangu anipe ruhusa au Mwenyezi Mungu anihukumie. Na Yeye ndiye Mbora wa wanaohukumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 81, 'Rudini kwa baba yenu, na mwambieni: Ee baba yetu! Hakika mwanao ameiba. Na sisi hatutoi ushahidi isipokuwa kwa tunayoyajua. Wala sisi hatukuwa wenye kuhifadhi mambo ya ghaibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 82, 'Na uliza mji tuliokuwamo, na msafara tuliokuja nao. Na hakika sisi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 83, 'Akasema: Bali nafsi zenu zimewashawishi kwenye jambo fulani. Basi subira ni nzuri! Huenda Mwenyezi Mungu akaniletea wote pamoja. Hakika Yeye ndiye Mwenye kujua vyema, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 84, 'Naye akajitenga nao, na akasema: Ah! Huzuni wangu mkubwa juu ya Yusuf! Na macho yake yakawa meupe kutokana na huzuni, na akaizuia bila ya kuidhirisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 85, 'Wakasema: Tallahi! Huachi kumkumbuka Yusuf mpaka uwe mgonjwa sana au uwe katika walioangamia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 86, 'Akasema: Hakika mimi namshitakia Mwenyezi Mungu tu sikitiko langu na huzuni wangu. Na ninajua kutoka kwa Mwenyezi Mungu yale msiyoyajua nyinyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 87, 'Enyi wanangu! Nendeni mumtafute Yusuf na nduguye, wala msikate tamaa na faraja ya Mwenyezi Mungu. Hakika hawakati tamaa na faraja ya Mwenyezi Mungu isipokuwa kaumu makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 88, 'Basi walipoingia alimokuwa Yusuf, wakasema: Ewe Mheshimiwa! Imetupata shida kubwa, sisi na ahali zetu. Na tumekujia na mali kidogo. Basi tutimizie tu kipimo na tupe sadaka. Hakika Mwenyezi Mungu huwalipa watoao sadaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 89, 'Akasema: Je, mnajua yale mliyomfanyia Yusuf na kakaye mlipokuwa wajinga?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 90, 'Wakasema: Kumbe hakika wewe ndiye Yusuf? Akasema: Mimi ndiye Yusuf, na huyu ni kaka yangu. Mwenyezi Mungu ametufanyia hisani. Hakika anayemcha Mungu na akasubiri, basi Mwenyezi Mungu hapotezi ujira wa wafanyao mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 91, 'Wakasema: Tallahi! Mwenyezi Mungu amekufadhilisha wewe kuliko sisi, na hakika sisi tulikuwa wenye kukosa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 92, 'Akasema: Leo hakuna lawama yoyote juu yenu. Mwenyezi Mungu atawasamehe, naye ni Mwenye kurehemu zaidi kuliko wote wanaorehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 93, 'Nendeni na shati langu hili na mlitupe usoni mwa baba yangu, atakuwa mwenye kuona. Na mnijie na ahali zenu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 94, 'Na ulipoondoka tu msafara, baba yao akasema: Hakika mimi ninaipata harufu ya Yusuf, lau kuwa hamtanituhumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 95, 'Wakasema: Tallahi! Hakika wewe bado ungali katika upotovu wako wa zamani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 96, 'Basi alipofika tu mbashiri huyo, akalitupa shati hilo usoni pake, basi akarejea kuona. Akasema: Je, sikuwaambia kuwa mimi ninajua kutoka kwa Mwenyezi Mungu yale msiyoyajua nyinyi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 97, 'Wakasema: Ewe baba yetu! Tuombee msamaha kwa dhambi zetu. Hakika sisi tulikuwa katika waliokosa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 98, 'Akasema: Nitakujawaombea msamaha kwa Mola wangu Mlezi. Hakika Yeye ndiye Mwenye kusamehe mno, Mwenye kurehemu sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 99, 'Na wakati walipoingia alimokuwa Yusuf, aliwakumbatia wazazi wake na akasema: Ingieni Misri, In shaa Allah (Mwenyezi Mungu akipenda) kwa amani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 100, 'Na akawapandisha wazazi wake kwenye kiti cha enzi, na wote wakaporomoka kumsujudia. Akasema: Ewe baba yangu! Hii ndiyo tafsiri ya ile ndoto yangu ya zamani. Mola wangu Mlezi ameifanya kuwa kweli. Na Mwenyezi Mungu amenifanyia uzuri kunitoa gerezani, na akawaleta kutoka jangwani baada ya Shetani kuchochea baina yangu na ndugu zangu. Hakika Mola wangu Mlezi ni Mpole kwa alitakalo. Hakika Yeye ndiye Mwenye kujua vyema, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 101, 'Ewe Mola wangu Mlezi! Hakika umenipa katika ufalme, na umenifunza katika tafsiri ya mambo. Ewe Muumba wa mbingu na ardhi! Wewe ndiye Mlinzi wangu katika dunia na Akhera. Nifishe hali ya kuwa ni Muislamu na niunganishe na walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 102, 'Hizo ni katika habari za ghaibu tulizokufunulia. Na hukuwa pamoja nao walipoazimia jambo lao hilo walipokuwa wanafanya njama zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 103, 'Na wengi wa watu si wenye kuamini hata ukijitahidi vipi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 104, 'Wala wewe huwaombi ujira kwa haya. Hayakuwa haya isipokuwa ni ukumbusho kwa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 105, 'Na ni ishara ngapi katika mbingu na ardhi wanazozipitia, lakini wao wanazipuuza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 106, 'Na wengi wao hawamuamini Mwenyezi Mungu pasina kuwa washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 107, 'Je, wana amani kuwa iwajie adhabu ya Mwenyezi Mungu ya kuwagubika, au iwajie Saa ya Kiyama kwa ghafla, na hali hawatambui?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 108, 'Sema: Hii ndiyo njia yangu - ninalingania kwa Mwenyezi Mungu kwa ufahamu mzuri - mimi na wale wanaonifuata. Na ametakasika Mwenyezi Mungu, na wala mimi si katika washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 109, 'Na hatukuwatuma Mitume kabla yako isipokuwa wanaume tuliowafunulia ufunuo (wahyi) miongoni mwa watu wa mijini. Je, hawakutembea katika ardhi wakaona jinsi ulivyokuwa mwisho wa wale waliokuwa kabla yao? Na hakika nyumba ya Akhera ndiyo bora kwa wamchao Mungu. Basi hamtumii akili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 110, 'Mpaka Mitume walipokata tamaa (ya watu wao kuamini) na wakaona kuwa wamekadhibishwa, hapo ikawajia nusura yetu, kwa hivyo wakaokolewa sawasawa tuwatakao. Na adhabu yetu haiwezi kurudishwa dhidi ya kaumu wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 111, 'Kwa hakika katika hadithi zao limo zingatio kwa wenye akili. Hazikuwa hadithi tu zilizozuliwa, bali ni za kusadikisha yale yaliyo kabla yake, na ufafanuzi wa kina wa kila kitu, na ni uongofu na rehema kwa kaumu inayoamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 1, 'Alif Laam Miim Raa.[1] Hizi ni Ishara za Kitabu. Na yale uliyoteremshiwa kutoka kwa Mola wako Mlezi ni Haki. Lakini wengi wa watu hawaamini.', '[1] Herufi hizi "Alif Laam Miim Raa" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 2, 'Mwenyezi Mungu ndiye aliyeziinua juu mbingu bila ya nguzo mnazoziona, kisha akainuka akawa juu ya Kiti cha Enzi, na akatiisha jua na mwezi, kila kimoja kinakwenda kwa muda maalumu. Anaendesha mambo, na anazipambanua Ishara kwa kina ili mpate kuwa na yakini ya kukutana na Mola wenu Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 3, 'Naye ndiye aliyeikunjua ardhi na akaweka humo milima mathubuti na mito. Na katika kila matunda akafanya jozi, cha kiume na cha kike. Huufunika usiku juu ya mchana. Hakika katika hayo zimo Ishara kwa kaumu wanaotafakari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 4, 'Na katika ardhi vimo vipande vilivyokaribiana, na zipo bustani za mizabibu, na mimea mingine, na mitende yenye kuchipua kwenye shina moja na isiyochipua kwenye shina moja, nayo inanyweshwa katika maji yale yale. Na tunaifanya baadhi yake kuwa bora kuliko mingine katika kula. Hakika katika hayo zimo ishara kwa kaumu wanaotia mambo akilini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 5, 'Na kama ukistaajabu, basi cha ajabu zaidi ni huo usemi wao: Je, tukishakuwa mchanga, kweli tutakuwa katika umbo jipya? Hao ndio waliomkufuru Mola wao Mlezi. Na hao ndio watakaokuwa na makongwa shingoni mwao, na hao ndio watu wa Motoni. Humo watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 6, 'Na wanakuharakisha ulete mabaya kabla ya mazuri, hali ya kuwa zimekwishapita kabla yao adhabu za kupigiwa mfano. Na hakika Mola wako Mlezi ni Mwenye msamaha kwa watu juu ya udhalimu wao. Na hakika Mola wako Mlezi ni Mkali wa kuadhibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 7, 'Na wale waliokufuru wanasema: Mbona hakuteremshiwa ishara kutoka kwa Mola wake Mlezi? Hakika wewe ni Mwonyaji tu, na kila kaumu ina wa kuwaongoza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 8, 'Mwenyezi Mungu anajua mimba ibebwayo na kila cha kike, na kinachopunguka na kuzidi matumboni mwa uzazi. Na kila kitu kwake ni kwa kipimo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 9, 'Yeye ndiye Mwenye kujua ya ghaibu na yanayoonekana, Mkubwa, Mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 10, 'Ni sawa anayeficha kauli yake miongoni mwenu na anayeidhihirisha, na anayejibanza usiku na anayetembea jahara mchana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 11, 'Kila mtu analo kundi la malaika mbele yake na nyuma yake linamlinda kwa amri ya Mwenyezi Mungu. Hakika Mwenyezi Mungu habadilishi yaliyoko kwa kaumu mpaka wabadilishe wao yaliyo katika nafsi zao. Na Mwenyezi Mungu anapowatakia kaumu ubaya, basi hakuna cha kuuzuia wala hawana mlinzi yeyote asiyekuwa Yeye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 12, 'Yeye ndiye anayewaonyesha umeme kwa hofu na matumaini, na huyaanzisha mawingu mazito.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 13, 'Na radi inamtakasa Mwenyezi Mungu kwa kumsifu, na Malaika pia, kwa kumhofu. Naye hutuma mapigo ya radi na kumsibu kwayo amtakaye. Nao wanabishana kuhusiana na Mwenyezi Mungu, na Yeye ndiye Mwenye adhabu kali!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 14, 'Wa kuombwa kweli ni Yeye tu. Na hao wanaowaomba badala yake hawawajibu chochote; bali ni kama mwenye kunyoosha viganja vyake kwenye maji ili yafike kinywani mwake, lakini hayakifikii. Na maombi ya makafiri hayako isipokuwa katika upotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 15, 'Na vinamsujudia Mwenyezi Mungu vilivyomo mbinguni na katika ardhi kwa kutii na kwa lazima. Na pia vivuli vyao, asubuhi na jioni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 16, 'Sema: Ni nani Mola Mlezi wa mbingu na ardhi? Sema: Mwenyezi Mungu. Sema: Basi je, mnawafanya wenginewe badala yake kuwa ni walinzi, nao hawajimilikii manufaa yoyote wala madhara? Sema: Je, kipofu na mwenye kuona huwa sawa? Au je, huwa sawa giza na mwangaza? Au wamemfanyia Mwenyezi Mungu washirika walioumba kama alivyoumba Yeye, na viumbe hivyo vikawachanganyikia? Sema: Mwenyezi Mungu ndiye Muumba wa kila kitu. Na Yeye ni Mmoja, Mwenye kushinda!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 17, 'Ameteremsha maji kutoka mbinguni. Na mabonde yakamiminika maji kwa kiasi chake. Na mafuriko yakabeba mapovu yaliyokusanyika juu yake. Na kutokana na wanavyoyeyusha katika moto kwa kutaka mapambo au vyombo hutokea povu vile vile. Namna hivyo ndivyo Mwenyezi Mungu anavyopiga mifano ya haki na batili. Basi lile povu linapita kama takataka tu. Na ama kinachowafaa watu hubakia kwenye ardhi. Hivyo ndivyo anavyopiga Mwenyezi Mungu mifano.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 18, 'Wale waliomuitikia Mola wao Mlezi watapata mazuri. Na wale ambao hawakumuitikia, hata wangelikuwa na vyote vilivyo katika ardhi na mfano wa hivyo, bila ya shaka wangelivitoa kujikombolea! Hao wana hesabu mbaya kabisa, na makao yao ni Jahannamu. Na hapo ni mahali pabaya mno pa kupumzikia!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 19, 'Je, anayejua ya kwamba yale yaliyoteremshwa kwako kutoka kwa Mola wako Mlezi ni Haki ni sawa na aliye kipofu? Hakika wenye akili ya hali ya juu tu ndio wanaokumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 20, 'Wale ambao wanatimiza mapatano yao na Mwenyezi Mungu, wala hawavunji agano.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 21, 'Na wale ambao huyaunga yale aliyoamrisha Mwenyezi Mungu yaungwe, na wanamhofu Mola wao Mlezi, na wanaiogopa hesabu mbaya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 22, 'Na ambao husubiri kwa kuutaka uso wa Mola wao Mlezi, na wakasimamisha Swala, na wakatoa katika vile tulivyowapa, kwa siri na kwa uwazi, na wanayaondoa mabaya kwa mazuri. Hao ndio wana malipo ya nyumba nzuri ya Akhera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 23, 'Nazo ni Bustani za milele, wataziingia wao na wale waliotengenea miongoni mwa baba zao, na wake zao, na vizazi vyao. Na Malaika watawaingilia katika kila mlango.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 24, '(Wakiwaambia) Assalamu Alaikum (Amani iwe juu yenu), kwa sababu ya vile mlivyosubiri! Basi ni mema mno malipo ya Nyumba ya Akhera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 25, 'Na wale wanaovunja agano la Mwenyezi Mungu baada ya kulifunga, na wanakata yale aliyoamrisha Mwenyezi Mungu yaungwe, na wanafanya uharibifu katika ardhi, hao wana laana, na wana Nyumba mbaya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 26, 'Mwenyezi Mungu humkunjulia riziki amtakaye, na humkunjia kwa kipimo. Na waliufurahia uhai wa dunia. Na uhai wa dunia kwa kulinganisha na Akhera si kitu isipokuwa ni starehe ndogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 27, 'Na wanasema wale waliokufuru: Kwa nini hakuteremshiwa ishara kutoka kwa Mola wake Mlezi? Sema: Hakika Mwenyezi Mungu humpoteza amtakaye, na humwongoa anayerudi kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 28, 'Wale walioamini na zikatua nyoyo zao kwa kumtaja Mwenyezi Mungu. Sikilizeni! Kwa kumtaja Mwenyezi Mungu ndiyo nyoyo hutua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 29, 'Wale walioamini na wakatenda mema watakuwa na raha na marejeo mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 30, 'Ndivyo hivyo tulivyokutuma kwa umma ambao zimekwishapita kabla yao umma nyingine, ili uwasomee yale tuliyokufunulia, na wao wanamkufuru Rahmani (Mwingi wa Rehema)! Sema: Yeye ndiye Mola wangu Mlezi. Hakuna mungu isipokuwa Yeye. Juu yake nimetegemea, na kwake ndiyo marejeo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 31, 'Na kama ingelikuwako Qur-ani inayoendeshewa milima, na kupasuliwa kwayo ardhi, na kusemeshwa kwayo wafu, (basi ingelikuwa Qur-ani hii). Bali mambo yote ni ya Mwenyezi Mungu. Je, hawajajua wale walioamini kwamba lau kuwa Mwenyezi Mungu angetaka, bila ya shaka angeliwaongoa watu wote? Na wale waliokufuru hawaachi kusibiwa na balaa kwa yale waliyoyatenda, au ikawateremkia karibu na nyumbani kwao, mpaka ije ahadi ya Mwenyezi Mungu. Hakika Mwenyezi Mungu havunji miadi yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 32, 'Na hakika walifanyiwa kejeli Mitume waliokuwa kabla yako. Na nikawapururia wale waliokufuru, kisha nikawashika! Basi ilikuwaje adhabu yangu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 33, 'Je, anayeisimamia kila nafsi kwa yale iliyoyachuma...? Na wamemfanyia Mwenyezi Mungu washirika! Sema: Watajeni. Au ndiyo mnampa habari ya yale asiyoyajua katika ardhi, au ni maneno matupu tu? Bali wale waliokufuru wamepambiwa njama zao na wamezuiliwa njia ya sawasawa. Na yule ambaye Mwenyezi Mungu amempoteza, basi hana yeyote wa kumwongoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 34, 'Wana adhabu katika uhai wa dunia, na adhabu ya Akhera hakuna shaka ndiyo ngumu zaidi. Na wala hawatakuwa na wa kuwalinda kutokana na Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 35, 'Mfano wa Bustani waliyoahidiwa wacha Mungu, kwa chini yake inapita mito, chakula chake ni cha daima, na pia kivuli chake. Huu ndio mwisho wa wale waliomcha Mungu. Na mwisho wa makafiri ni Moto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 36, 'Na wale tuliowapa Kitabu wanayafurahia yale yaliyoteremshwa kwako. Na katika makundi mengine wapo wanaoyakataa baadhi yake. Sema: Hakika nimeamrishwa nimuabudu Mwenyezi Mungu tu, na wala nisimshirikishe. Kwake Yeye ndiko ninaitia na kwake Yeye ndiko marejeo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 37, 'Na ndivyo hivyo tumeiteremsha (Qur-ani hii kuwa ni) hukumu kwa lugha ya Kiarabu. Na ukifuata matamanio yao baada ya elimu hii iliyokujia, hutakuwa na rafiki yeyote wala mlinzi kando na Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 38, 'Na hakika Sisi tulikwishawatuma Mitume kabla yako, na tukawafanya wawe na wake na dhuria. Na haikuwa kwa Mtume yeyote kuleta ishara isipokuwa kwa idhini ya Mwenyezi Mungu. Kila kipindi kina hukumu yake iliyoandikwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 39, 'Mwenyezi Mungu hufuta na huthibitisha ayatakayo. Na kiko kwake Kitabu asili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 40, 'Na ikiwa tutakuonyesha baadhi ya yale tuliyowaahidi au tukakufisha kabla yake, juu yako wewe ni kufikisha ujumbe tu na juu yetu ni hesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 41, 'Je, hawakuona kwamba tunaijia ardhi tukiipunguza kutokea nchani mwake? Na Mwenyezi Mungu huhukumu, na hakuna wa kurekebisha hukumu yake, naye ni Mwepesi wa kuhesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 42, 'Na walipanga njama wale waliokuwa kabla yao, lakini Mwenyezi Mungu ndiye Mwenye njama zote. Yeye anajua kile inachochuma kila nafsi. Na makafiri watakuja jua ni ya nani nyumba (njema) ya mwisho (huko Akhera)!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 43, 'Na wale waliokufuru wanasema: Wewe hukutumwa. Sema: Mwenyezi Mungu anatosha kuwa shahidi baina yangu na nyinyi, na pia yule mwenye elimu ya Kitabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 1, 'Alif Laam Raa.[1] Hiki ni Kitabu tulichokuteremshia ili uwatoe watu kwenye giza mbalimbali uwapeleke kwenye mwangaza, kwa idhini ya Mola wao Mlezi, uwafikishe kwenye Njia ya Mwenye nguvu, Msifika.', '[1] Herufi hizi "Alif Laam Raa" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 2, 'Naye ni Mwenyezi Mungu ambaye ni vyake Yeye vyote vilivyo katika mbingu zote na katika ardhi. Na ole wao makafiri kwa adhabu kali!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 3, 'Wale wanaoupendelea uhai wa dunia kuliko Akhera, na wanawazuilia watu Njia ya Mwenyezi Mungu, na wanataka kuipotosha. Hao wako katika upotovu wa mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 4, 'Na hatukumtuma Mtume yeyote isipokuwa kwa ulimi wa kaumu yake ili apate kuwabainishia. Basi Mwenyezi Mungu anampoteza amtakaye, na anamwongoa amtakaye. Naye ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 5, 'Na hakika tulimtuma Musa na miujiza yetu, tukamwambia: Watoe kaumu yako kwenye giza mbalimbali uwapeleke kwenye nuru. Na uwakumbushe siku za Mwenyezi Mungu. Hakika katika hayo zipo ishara kwa kila mwenye kusubiri sawasawa, mwenye kushukuru sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 6, 'Na Musa alipowaambia kaumu yake, "Kumbukeni neema ya Mwenyezi Mungu juu yenu pale alipowaokoa kutokana na watu wa Firauni waliokuwa wakiwatia adhabu mbaya kabisa, wakiwachinja wana wenu wanaume, na wakiwaacha hai wanawake wenu. Na katika hayo ulikuwa mtihani mkubwa unaotoka kwa Mola wenu Mlezi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 7, 'Na alipotangaza Mola wenu Mlezi: Mkishukuru, hakika nitawazidishia. Na mkikufuru, basi adhabu yangu ni kali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 8, 'Na Musa alisema: Mkikufuru nyinyi na wote walio katika dunia, basi hakika Mwenyezi Mungu ni Mwenye kujitosha, Msifika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 9, 'Je, hazikuwafikia habari za wale waliokuwa kabla yenu? Kaumu ya Nuhu, na ''Aadi, na Thamud, na wale waliokuwa baada yao, ambao hakuna awajuaye isipokuwa Mwenyezi Mungu? Mitume wao waliwajia na hoja zilizo wazi, na wao wakarudisha mikono yao kwenye vinywa vyao, wakasema: Hakika sisi tumeyakufuru hayo mliyotumwa nayo, na hakika sisi tuko katika shaka kubwa na hayo mnayotuitia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 10, 'Mitume wao wakasema: Ati kuna shaka kuhusiana na Mwenyezi Mungu, Muumba mbingu na ardhi? Yeye anawaita ili awafutie madhambi yenu, na awape muhula mpaka muda uliowekwa. Wakasema: Nyinyi si chochote isipokuwa ni wanadamu tu kama sisi. Mnataka kutuzuilia mbali na yale waliyokuwa wakiabudu baba zetu. Basi tujieni na hoja iliyo wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 11, 'Mitume wao wakawaambia: Sisi kweli si chochote isipokuwa ni wanadamu kama nyinyi. Lakini Mwenyezi Mungu humneemesha amtakaye katika waja wake. Wala sisi hatuwezi kuwaletea uthibitisho isipokuwa kwa idhini ya Mwenyezi Mungu. Na juu ya Mwenyezi Mungu basi na wategemee Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 12, 'Na tuna nini hata tusimtegemee Mwenyezi Mungu, na hali Yeye ametuongoa kwenye njia zetu. Na hakuna hakika tutayavumilia hayo maudhi mnayotuudhi nayo. Na juu ya Mwenyezi Mungu na wategemee wanaotegemea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 13, 'Na wale waliokufuru wakawaambia Mitume wao: Hakika, tutawatoa katika nchi yetu, au lazima mtarudi katika mila yetu. Basi Mola wao Mlezi akawafunulia ufunuo (wahyi): Hakika tutawaangamiza madhalimu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 14, 'Na hakika tutawaweka kukaa katika ardhi baada yao. Haya ni kwa anayehofu kusimamishwa mbele yangu, na akahofu ahadi yangu ya adhabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 15, 'Na wakaomba ushindi, na akashindwa kila jabari mkaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 16, 'Nyuma yake iko Jahannamu, na atanyweshwa katika maji ya usaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 17, 'Awe anayagugumiza, wala hataweza kuyameza. Na mauti yatamjia kutokea kila upande, wala hatakufa. Na zaidi ya hayo itakuwepo adhabu nyengine kali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 18, 'Mfano wa wale waliomkufuru Mola wao Mlezi, vitendo vyao ni kama jivu linalopeperushwa kwa nguvu za upepo katika siku ya upepo mkali. Hawawezi kupata chochote katika yale waliyoyachuma. Huko ndiko kupotea kwa mbali!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 19, 'Je, huoni kuwa Mwenyezi Mungu ameziumba mbingu na ardhi kwa Haki? Akitaka, anawaondoa na alete viumbe wapya!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 20, 'Na hilo kwa Mwenyezi Mungu si jambo gumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 21, 'Na wote watajitokeza mbele ya Mwenyezi Mungu. Wanyonge watawaambia wale waliotakabari: Hakika sisi tulikuwa wafwasi wenu; basi hebu mtuondolee kidogo hivi katika adhabu ya Mwenyezi Mungu? Watasema: Lau Mwenyezi Mungu angelituongoa, basi hakuna shaka nasi tungeliwaongoa. Ni mamoja kwetu tukipapatika au tukisubiri; hatuna popote pa kukimbilia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 22, 'Na shetani atasema itakapokatwa hukumu: Hakika Mwenyezi Mungu aliwaahidi ahadi ya kweli. Nami niliwaahidi; lakini sikuwatimizia ahadi yangu. Na sikuwa na mamlaka yoyote juu yenu, isipokuwa niliwaita, nanyi mkaniitikia. Basi msinilaumu mimi, bali jilaumuni wenyewe. Mimi siwezi kuwa mtetezi wenu, wala nyinyi hamuwezi kuwa watetezi wangu. Hakika mimi nilikufuru tangu zamani huko kunishirikisha kwenu na Mwenyezi Mungu. Hakika madhalimu wana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 23, 'Na wale walioamini na wakatenda mema wataingizwa katika Mabustani yapitayo mito kwa chini yake, wadumu humo kwa idhini ya Mola wao Mlezi. Maamkizi yao humo yatakuwa: Salaam (Amani)!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 24, 'Je, hukuona vipi Mwenyezi Mungu alivyopiga mfano wa neno zuri? Ni kama mti mzuri, mizizi yake ni imara, na matawi yake yako mbinguni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 25, 'Hutoa matunda yake kila wakati kwa idhini ya Mola wake Mlezi. Na Mwenyezi Mungu huwapigia watu mifano ili wapate kukumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 26, 'Na mfano wa neno ovu ni kama mti muovu, uliong''olewa juu ya ardhi. Hauna uimara wowote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 27, 'Mwenyezi Mungu huwaimarisha wale walioamini kwa kauli ya imara katika uhai wa dunia na katika Akhera. Na Mwenyezi Mungu huwapoteza madhalimu. Na Mwenyezi Mungu hufanya apendavyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 28, 'Je, hukuwaona wale waliobadilisha neema ya Mwenyezi Mungu kwa kufuru, na wakawafikisha kaumu yao kwenye nyumba ya maangamizo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 29, 'Nayo ni Jahannamu wataiingia! Na ni mahali pa kukaa pabaya mno!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 30, 'Na walimfanyia Mwenyezi Mungu wenza ili wapoteze watu kutoka kwenye njia yake. Sema: Stareheni! Kwani maishio yenu ni Motoni!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 31, 'Waambie waja wangu walioamini, wadumishe Swala, na watoe katika tulivyowaruzuku, kwa siri na dhahiri, kabla ya kufika kwa Siku isiyokuwa na biashara yoyote wala urafiki wa dhati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 32, 'Mwenyezi Mungu ndiye aliyeziumba mbingu na ardhi, na akateremsha maji kutoka mbinguni, na kwa hayo akatoa matunda kuwa ni riziki yenu. Na akawatiishia majahazi yanayokwenda baharini kwa amri yake, na akawatiishia mito.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 33, 'Na akawatiishia jua na mwezi vinavyokwenda daima dawamu, na akawatiishia usiku na mchana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 34, 'Na akawapa katika kila mlichomuomba. Na mkihesabu neema za Mwenyezi Mungu, hamuwezi kuzidhibiti. Hakika mwanadamu ni dhalimu mkubwa, mwenye kukufuru sana neema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 35, 'Na Ibrahim aliposema: Ewe Mola wangu Mlezi! Ujaalie mji huu uwe wa amani, na uniepushe mimi na wanangu na kuabudu masanamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 36, 'Ewe Mola wangu Mlezi! Hakika hayo yamewapoteza wengi wa watu. Basi aliyenifuata mimi, huyo hakika ni miongoni mwangu. Na aliyeniasi, hakika Wewe ni Mwingi wa kusamehe, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 37, 'Mola wetu Mlezi! Hakika mimi nimewaweka baadhi ya dhuria yangu katika bonde lisilokuwa na mimea, kwenye Nyumba yako Takatifu, ewe Mola wetu Mlezi, ili wadumishe Swala. Basi zifanye nyoyo za watu zielekee kwao, na waruzuku matunda, ili wapate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 38, 'Ewe Mola wetu Mlezi! Hakika Wewe unajua tunayoyaweka hadharani na tunayoyaficha. Na hakuna kitu kinachofichikana kwa Mwenyezi Mungu katika ardhi wala katika mbingu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 39, 'Alhamdulillahi (sifa njema ni za Mwenyezi Mungu) aliyenitunuku pamoja na uzee wangu Ismail na Is-haq. Hakika Mola wangu Mlezi ni Mwenye kusikia sana maombi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 40, 'Mola wangu Mlezi! Nifanye niwe mwenye kudumisha Swala, na katika dhuria yangu pia. Ewe Mola wetu Mlezi, na ikubali dua yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 41, 'Mola wetu Mlezi! Nisamehe mimi na wazazi wangu wote wawili, na Waumini, siku itakaposimama hesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 42, 'Wala kamwe usidhani Mwenyezi Mungu ameghafilika mbali na wanayoyafanya madhalimu. Hakika Yeye anawaahirisha tu mpaka siku yatakapokodoka macho yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 43, 'Watakuwa mbioni, vichwa juu, huku macho yao hayapepesi, na nyoyo zao zitakuwa tupu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 44, 'Na waonye watu siku itakapowajia adhabu, na wale waliodhulumu waseme, "Ewe Mola wetu Mlezi! Tuahirishe muda kidogo tuitikie wito wako na tuwafuate Mitume." Kwani nyinyi hamkuapa zamani kwamba kamwe hamuwezi kuondoka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 45, 'Na mkakaa katika maskani zile zile za wale waliozidhulumu nafsi zao. Na ikawabainikia jinsi tulivyowatendea. Nasi tukawapigia mifano mingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 46, 'Na hakika walifanya vitimbi vyao, na vitimbi vyao hivyo anavijua Mwenyezi Mungu. Na kwa yakini vitimbi vyao hivyo vilikuwa ni vya kuweza kuondosha milima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 47, 'Basi kamwe usimdhanie Mwenyezi Mungu kuwa ni mwenye kuwavunjia ahadi yake Mitume wake. Hakika Mwenyezi Mungu ni Mwenye Nguvu, Mwenye kulipiza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 48, 'Siku itakapogeuzwa ardhi iwe ardhi nyingine, na mbingu zote pia. Nao watajitokeza mbele ya Mwenyezi Mungu Mmoja, Mshindi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 49, 'Na utaona wahalifu siku hiyo wamefungwa pamoja katika minyororo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 50, 'Nguo zao zitakuwa za lami, na Moto utazigubika nyuso zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 51, 'Ili Mwenyezi Mungu ailipe kila nafsi yale iliyoyachuma. Hakika Mwenyezi Mungu ni Mwepesi wa kuhesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 52, 'Huu ni ufikishaji kwa watu, ili waonywe kwao, na wapate kujua kuwa hakika Yeye ni Mungu Mmoja, na wapate kukumbuka wenye akili zilizo sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 1, 'Alif Lam Ra.[1] Hizi ni Aya za Kitabu na Qur-ani inayobainisha.', '[1] Herufi hizi "Alif Laam Raa" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 2, 'Huenda ikawa wale waliokufuru wakatamani kwamba wangekuwa Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 3, 'Waache wale, na wastarehe, na yawazuge matumaini. Basi watakujajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 4, 'Na hatukuuangamiza mji wowote ule isipokuwa ulikuwa na muda wake maalumu ulioandikiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 5, 'Hawawezi umma wowote kuutangulia muda wao, wala kuchelewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 6, 'Na walisema, "Ewe uliyeteremshiwa Ukumbusho! Hakika wewe ni mwendawazimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 7, 'Mbona hutuletei Malaika ikiwa wewe ni miongoni mwa wakweli?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 8, 'Sisi hatuwateremshi Malaika isipokuwa kwa sababu ya haki, na hapo hawatapewa muhula.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 9, 'Hakika Sisi ndio tuliouteremsha Ukumbusho huu, na hakika Sisi ndio tutakaoulinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 10, 'Na hakika tulikwishatuma Mitume kabla yako kwa mataifa ya mwanzo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 11, 'Na hakuwajia Mtume yeyote isipokuwa walikuwa wakimfanyia stihizai.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 12, 'Na kama hivi ndivyo tunavyoyaingiza katika nyoyo za wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 13, 'Hawayaamini haya, na ilhali imekwishawapitia desturi ya wa mwanzo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 14, 'Na lau tungeliwafungulia mlango huko mbinguni, wakawa wanapanda kupitia humo,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 15, 'Basi wangelisema: Hakika macho yetu yameleweshwa tu. Bali sisi wenyewe ni kaumu tuliofanyiwa uchawi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 16, 'Na hakika tumeweka katika mbingu vituo vya sayari, na tumezipamba kwa wenye kuangalia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 17, 'Na tumezilinda kutokana na kila shetani aliyelaaniwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 18, 'Isipokuwa mwenye kusikiliza kwa kuibia, naye hufuatwa na kijinga cha moto kilicho dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 19, 'Na ardhi tumeitandaza, na humo tumeweka milima madhubuti, na tumeotesha ndani yake katika kila kitu kwa kiasi chake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 20, 'Na tumewafanyia humo vitu vya maisha yenu, na ya hao ambao nyinyi sio wenye kuwaruzuku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 21, 'Na hakuna chochote ila asili yake inatokana na Sisi; wala hatukiteremshi isipokuwa kwa kipimo maalumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 22, 'Na tunazipeleka pepo za kupandishia, na tunateremsha kutoka mbinguni maji, kisha tukakunywesheni maji hayo. Wala si nyinyi mnayoyaweka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 23, 'Na hakika Sisi ndio tunaohuisha na tunaofisha. Na Sisi ndio Warithi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 24, 'Na hakika tunawajua waliotangulia katika nyinyi, na tunawajua waliobaki nyuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 25, 'Na hakika Mola wako Mlezi ndiye atakayewakusanya. Hakika Yeye ni Mwenye hekima, Mwenye kujua mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 26, 'Na hakika tulimuumba Mtu kwa udongo unaotoa sauti, unaotokana na matope yaliyotiwa sura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 27, 'Naye Jini tulimuumba hapo kabla kutokana na moto wa upepo umoto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 28, 'Na Mola wako Mlezi alipowaambia Malaika: Hakika Mimi nitamuumba mtu kwa udongo unaotoa sauti, unaotokana na matope yaliyotiwa sura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 29, 'Basi nitakapomtengeneza sawasawa, na nikampulizia katika roho yangu, basi angukeni kumsujudia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 30, 'Basi Malaika wote pamoja walimsujudia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 31, 'Isipokuwa Iblisi. Yeye alikataa kuwa pamoja na waliosujudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 32, '(Mwenyezi Mungu) akasema: Ewe Iblisi! Una nini hata hukuwa pamoja na waliosujudu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 33, 'Akasema: Haiwi mimi nimsujudie mtu uliyemuumba kutokana na udongo unaotoa sauti, unaotokana na matope yaliyotiwa sura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 34, '(Mwenyezi Mungu) akasema: Basi toka humo, kwani hakika wewe umefukuziliwa mbali!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 35, 'Na hakika juu yako ipo laana mpaka Siku ya Malipo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 36, 'Akasema (Iblisi): Mola wangu Mlezi! Nipe muhula mpaka siku watakapofufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 37, '(Mwenyezi Mungu) akasema: Hakika wewe ni katika waliopewa muhula.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 38, 'Mpaka siku ya wakati maalumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 39, 'Akasema: Mola wangu Mlezi! Ilivyokuwa umenipoteza, basi hakika nitawapambia katika dunia na hakika nitawapoteza wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 40, 'Isipokuwa waja wako walioteuliwa miongoni mwao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 41, 'Akasema: Hii ni njia ya kujia kwangu iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 42, 'Hakika waja wangu, wewe hutakuwa na mamlaka juu yao, isipokuwa wale watakaokufuata miongoni mwa wapotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 43, 'Na hakika Jahannamu ndipo mahali pao walipoahidiwa wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 44, 'Ina milango saba; kila mlango ulitengewa sehemu miongoni mwao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 45, 'Hakika wacha Mungu watakuwa katika Mabustani na chemchemi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 46, '(Wataambiwa:) Ingieni humo kwa salama na amani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 47, 'Na tutaondoa chuki iliyokuwa vifuani mwao, wawe ndugu, juu ya viti vya kifahari huku wameelekeana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 48, 'Humo hayatawagusa machovu, wala hawatatolewa humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 49, 'Wape habari waja wangu ya kwamba Mimi ndiye Mwenye kusamehe zaidi, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 50, 'Na kwamba adhabu yangu ndiyo adhabu iliyo chungu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 51, 'Na wape habari za wageni wa Ibrahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 52, 'Walipoingia kwake na wakasema: Salama! Yeye akasema: Hakika sisi tunawaogopa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 53, 'Wakasema: Usiogope. Hakika, Sisi tunakubashiria kijana mwenye elimu mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 54, 'Akasema: Mnanibashiria nami uzee umenishika! Basi ni kwa njia gani mnanibashiria?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 55, 'Wakasema: Tunakubashiria kwa haki, basi usiwe miongoni mwa wanaokata tamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 56, 'Akasema: Na ni nani anayekata tamaa na rehema ya Mola wake Mlezi isipokuwa wapotovu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 57, 'Akasema: Hebu mna jambo gani, enyi wajumbe?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 58, 'Wakasema: Hakika sisi tumetumwa kwa kaumu ya wahalifu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 59, 'Isipokuwa watu wa familia ya Lut''. Bila ya shaka sisi tutawaokoa hao wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 60, 'Isipokuwa mkewe. Tumekwishapitisha kwamba huyo hakika atakuwa miongoni mwa watakaosalia nyuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 61, 'Basi wajumbe hao walipowajia watu wa familia ya Lut''.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 62, '(Lut'') Alisema: Hakika nyinyi ni kaumu msiojulikana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 63, 'Wakasema: Bali sisi tumekuletea yale waliyokuwa wakiyafanyia shaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 64, 'Na tumekujia kwa Haki, na hakika sisi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 65, 'Basi ondoka na ahali zako usiku ungalipo, nawe ufuate nyuma yao, wala yeyote kati yenu asigeuke nyuma. Na mwende huko mnakoamrishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 66, 'Na tukamfunulia hukumu hiyo, ya kwamba hata wa mwisho wao hao ikifika asubuhi atakuwa amekwishakatiliwa mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 67, 'Na wakaja watu wa mji huo huku wamefurahi mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 68, 'Akasema: Hakika hawa ni wageni wangu. Basi msinifedheheshe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 69, 'Na mcheni Mwenyezi Mungu, wala msinihizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 70, 'Wakasema: Kwani hatukukukataza (kuwakaribisha) walimwengu hawa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 71, 'Akasema, "Hawa binti zangu (waoeni)[1], ikiwa nyinyi ni watendaji."', '[1] Lut''i, amani iwe juu yake, alimaanisha kwamba hawa ni binti zangu miongoni mwa wanawake wenu, basi waoeni hao.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 72, 'Ninaapa kwa uhai wako! Hakika hao walikuwa katika ulevi wao, wakihangaika ovyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 73, 'Basi ukelele ukawatwaa wakipambaukiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 74, 'Kwa hivyo, tukaugeuza mji huo juu chini, na tukawanyeshea mvua ya mawe ya udongo wa kutoka Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 75, 'Hakika katika hayo zipo ishara kwa wanaotafakari na kuzingatia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 76, 'Na hakika miji hii ipo kwenye njia wazi inayopitiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 77, 'Hakika katika hayo ipo ishara kwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 78, 'Na hakika watu wa Kichakani walikuwa madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 79, 'Kwa hivyo tukawaadhibu. Na hakika miji miwili hii iko kwenye njia iliyo wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 80, 'Na bila ya shaka wakazi wa Hijr waliwakadhibisha Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 81, 'Na tuliwaletea ishara zetu, nao wakawa wanazipa migongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 82, 'Nao walikuwa wakichonga majumba katika milima kwa amani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 83, 'Basi ukelele ukawatwaa asubuhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 84, 'Na hayakuwafaa yale waliyokuwa wakiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 85, 'Na hatukuziumba mbingu na ardhi na vilivyo kati yake isipokuwa kwa haki. Na hakika Saa ya Kiyama itafika. Basi samehe msamaha mzuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 86, 'Hakika Mola wako Mlezi ndiye Muumbaji, Mwenye kujua zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 87, 'Na hakika tumekupa (aya) saba zinazosomwa mara kwa mara, na Qur-ani Tukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 88, 'Kamwe usivinyoshee macho yako vitu tulivyowastarehesha kwavyo makundi fulani kati yao, wala usiwahuzunikie. Na wainamishie bawa lako (la huruma) Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 89, 'Na sema: Hakika mimi ndiye mwonyaji mwenye kubainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 90, 'Kama hivyo tuliwateremshia waliogawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 91, 'Ambao waliifanya Qur-ani vipande vipande.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 92, 'Basi ninaapa kwa Mola wako Mlezi! Lazima tutawauliza wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 93, 'Kuhusu yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 94, 'Basi wewe yadhihirishe yale uliyoamrishwa, na jitenge mbali na washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 95, 'Hakika Sisi tunatosha kukukinga kutokana na wanaofanya stihizai.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 96, 'Ambao wanafanya mungu mwingine kuwa pamoja na Mwenyezi Mungu. Basi watakujajua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 97, 'Na Sisi tunajua kwa hakika kuwa wewe kifua chako kinaona dhiki kwa hayo wayasemayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 98, 'Basi mtakase Mola wako Mlezi kwa kumsifu, na uwe miongoni mwa wanaomsujudia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 99, 'Na muabudu Mola wako Mlezi mpaka ikufikie Yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 1, 'Amri ya Mwenyezi Mungu itafika tu. Basi msiiharakishe. Ametakasika na ametukuka mbali na hayo wanayomshirikisha nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 2, 'Huwateremsha Malaika na ufunuo kwa amri yake juu ya amtakaye katika waja wake kwamba onyeni kuwa hakuna mungu yeyote isipokuwa Mimi, basi nicheni Mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 3, 'Ameziumba mbingu na ardhi kwa Haki. Ametukuka na hayo wanayomshirikisha nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 4, 'Amemuumba mtu kwa tone la manii. Na tazama, akawa mshindani aliye dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 5, 'Na aliwaumba wanyama. Katika hao mna vifaa vya kutia joto, na manufaa mengineyo, na baadhi yao mnawala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 6, 'Na katika hao mnapata furaha pale mnapowarudisha jioni na mnapowapeleka malishoni asubuhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 7, 'Nao hubeba mizigo yenu kupeleka kwenye miji msiyoweza kuifikia isipokuwa kwa mashaka ya nafsi. Hakika Mola wenu Mlezi ni Mpole mno, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 8, 'Na farasi, nyumbu, na punda ili muwapande, na wawe ni pambo. Na anaumba msivyovijua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 9, 'Na ni juu ya Mwenyezi Mungu kuelekeza Njia. Na zipo njia za upotovu. Na angelipenda, angeliwaongoa nyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 10, 'Yeye ndiye anayewateremshia maji kutoka mbinguni. Katika hayo nyinyi mnapata ya kunywa, na miti ya kulishia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 11, 'Kwa hayo Yeye anawaoteshea mimea, na mizaituni, na mitende, na mizabibu, na kila aina ya matunda. Hakika katika hayo ipo ishara kwa kaumu wanaotafakari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 12, 'Na amewatiishia usiku na mchana, na jua na mwezi, na nyota zimetiishwa kwa amri yake. Hakika katika hayo zipo ishara kwa kaumu watumiao akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 13, 'Na vile alivyowaenezea katika ardhi vya rangi mbalimbali. Hakika katika hayo ipo ishara kwa kaumu wanaokumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 14, 'Yeye ndiye aliyeitiisha bahari, ili kutokana na humo mpate kula nyama laini, na mtoe humo mapambo mnayoyavaa. Na utaona merikebu zikikata maji humo, ili mtafute fadhila yake, na mpate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 15, 'Na akaweka katika ardhi milima madhubuti ili ardhi isiyumbeyumbe nanyi. Na mito, na njia mbalimbali ili mpate kuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 16, 'Na alama nyinginezo. Na kwa nyota wao wanajiongoza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 17, 'Ati yule anayeumba ni kama asiyeumba? Basi hebu hamkumbuki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 18, 'Na mkizihesabu neema za Mwenyezi Mungu, hamwezi kuzidhibiti. Hakika Mwenyezi Mungu ni Mwenye maghfira mno, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 19, 'Na Mwenyezi Mungu anayajua mnayoyaficha na mnayoyaweka hadharani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 20, 'Na wale wanaowaomba wasiokuwa Mwenyezi Mungu hawaumbi kitu, bali wao wameumbwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 21, 'Ni wafu, si wahai, na wala hawajui watafufuliwa lini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 22, 'Mungu wenu ni Mungu Mmoja. Lakini wale wasioiamini Akhera nyoyo zao zinakataa, nao wanatakabari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 23, 'Hakuna shaka kuwa hakika Mwenyezi Mungu anayajua yale wanayoyaficha na wanayoyaweka hadharani. Hakika, Yeye hawapendi wanaotakabari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 24, 'Na wanapoambiwa, "Ni nini alichoteremsha Mola wenu Mlezi?" Husema: Hadithi za kubuni za wa mwanzo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 25, 'Ili wabebe mizigo yao kwa ukamilifu Siku ya Kiyama, na sehemu ya mizigo ya wale wanaowapoteza bila ya kujua. Angalia, ni mabaya mno hayo wanayoyabeba!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 26, 'Walipanga njama wale waliokuwa kabla yao, naye Mwenyezi Mungu akayajia majengo yao kutokea kwenye misingi, kwa hivyo dari zake zikaporomoka juu yao, na adhabu ikawajia kutokea wasipohisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 27, 'Kisha Siku ya Kiyama atawahizi na atasema: Wako wapi hao washirika wangu ambao kwao mlikuwa mkipinga (Manabii)? Watasema wale waliopewa elimu: Hakika leo ndiyo hizaya na ubaya vitawashukia makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 28, 'Wale ambao Malaika huwafisha huku wamejidhulumu nafsi zao! Basi wanasalimu amri, waseme: Hatukuwa tukifanya ubaya wowote. (Wataambiwa). Hasha! Hakika Mwenyezi Mungu anajua sana mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 29, 'Basi ingieni milango ya Jahannamu, humo mdumu. Ni mabaya mno makazi ya wafanyao kiburi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 30, 'Na wataambiwa wale waliomcha Mungu: Mola wenu Mlezi aliteremsha nini? Watasema: "Heri." Kwa wale waliofanya mazuri katika dunia hii watapata mazuri. Na nyumba ya Akhera ni bora zaidi, na ni njema mno nyumba hiyo ya wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 31, 'Bustani za milele wataziingia; iwe inapita kwa chini yake mito. Humo watapata watakacho. Hivi ndivyo Mwenyezi Mungu awalipavyo wenye kumcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 32, 'Wale ambao Malaika huwafisha katika hali nzuri, wanawaambia: Salama iwe juu yenu! Ingieni Bustanini kwa sababu ya yale mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 33, 'Wanangojea jingine hawa isipokuwa Malaika wawafikie, au iwafikie amri ya Mola wako Mlezi? Kama hivyo, walitenda wale waliokuwa kabla yao. Na Mwenyezi Mungu hakuwadhulumu, lakini walijidhulumu wenyewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 34, 'Basi yakawafikia mabaya ya yale waliyoyatenda, na yale waliyokuwa wakiyafanyia stihizai yakawazingira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 35, 'Na washirikina walisema: Mwenyezi Mungu angelitaka, tusingeliabudu chochote badala yake, sisi wala baba zetu, wala tusingeliharamisha chochote bila ya Yeye. Kama hivyo, walifanya wale waliokuwa kabla yao. Basi lipo lolote juu ya Mitume isipokuwa kufikisha tu kwa wazi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 36, 'Na hakika kwa kila umma tuliutumia Mtume kwamba: Muabuduni Mwenyezi Mungu, na muepukeni Twaghut. Basi kati yao wapo aliowaongoa Mwenyezi Mungu. Na kati yao wapo ambao uliwathibitikia upotovu. Basi tembeeni katika ardhi, muangalie ulikuwaje mwisho wa wale wanaokadhibisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 37, 'Hata ukiwa na pupa juu ya kuongoka kwao, basi hakika Mwenyezi Mungu hamwongoi yule anayeshikilia kupotea. Wala hawatapata yeyote wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 38, 'Na waliapa kwa Mwenyezi Mungu ukomo wa viapo vyao kwamba Mwenyezi Mungu hatamfufua aliyekufa. Kwani! Ni ahadi iliyo juu yake kikweli; lakini wengi wa watu hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 39, 'Ili awabainishie yale waliyohitilafiana ndani yake, na ili wajue wale waliokufuru kwamba wao walikuwa waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 40, 'Hakika, kauli yetu kwa kitu tunapokitaka kiwe, ni kukiambia tu: "Kuwa!" Basi kinakuwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 41, 'Na wale waliohama kwa ajili ya Mwenyezi Mungu baada ya kudhulumiwa, bila ya shaka tutawaweka katika maskani mazuri katika dunia; na hakika ujira wa Akhera ni mkubwa zaidi; lau wangekuwa wanajua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 42, 'Wale waliosubiri na wakamtegemea Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 43, 'Nasi hatukuwatuma kabla yako isipokuwa watu wanaume tuliowapa ufunuo (wahyi). Basi waulizeni wenye ukumbusho kama nyinyi hamjui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 44, 'Kwa Ishara wazi na Vitabu. Na tumekuteremshia ukumbusho huu ili uwabainishie watu yale yaliyoteremshwa kwao, ili wapate kutafakari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 45, 'Je wana amani wale wanaopanga njama mbaya kwamba Mwenyezi Mungu hatawadidimiza katika ardhi, na haitawafikia adhabu kutoka wasipohisi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 46, 'Au hatawashika katika harakati zao, na wala hawatamshinda?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 47, 'Au hatawashika huku wana hofu? Hakika Mola wenu Mlezi ni Mwenye huruma kubwa, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 48, 'Je, hawavioni vitu alivyoviumba Mwenyezi Mungu, vivuli vyao vinaelekea kushotoni na kuliani, vikimsujudia Mwenyezi Mungu na vikinyenyekea?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 49, 'Na vinamsujudia Mwenyezi Mungu vyote vilivyo katika mbingu na katika ardhi, miongoni mwa wanyama mpaka Malaika na wala havitakabari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 50, 'Vinamhofu Mola wao Mlezi aliye juu yao, na vinafanya vinavyoamrishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 51, 'Na Mwenyezi Mungu amesema: Msijifanyie miungu wawili! Hakika Yeye ndiye Mungu Mmoja tu. Basi niogopeni sana Mimi tu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 52, 'Na ni vyake Yeye vilivyo katika mbingu na ardhi. Na Dini ni yake Yeye daima. Je, mnamcha mwingine asiyekuwa Mwenyezi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 53, 'Na neema yoyote mliyo nayo inatoka kwa Mwenyezi Mungu. Kisha yakiwagusa madhara, mnamyayatikia Yeye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 54, 'Na anapowaondoshea madhara hayo, mara kundi moja miongoni mwenu linamshirikisha Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 55, 'Wakizikataa neema tulizowapa. Basi stareheni. Mtakujajua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 56, 'Na hao ambao hata hawawajui wanawawekea sehemu katika vile tunavyowaruzuku. Tallahi! Bila ya shaka mtaulizwa kwa hayo mliyokuwa mnayazua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 57, 'Na wanamfanyia Mwenyezi Mungu mabinti, Subhanahu (ametakasika)! Na wao wenyewe, ati ndiyo wana hayo wanayoyatamani!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 58, 'Na mmoja wao akibashiriwa msichana, uso wake unasalia umesawijika na anakuwa na huzuni mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 59, 'Anajificha asionekane na watu kwa sababu ya ubaya wa yule aliyebashiriwa! Je, akae naye pamoja na fedheha hiyo au amfukie udongoni? Tazama, ni ubaya mno wanavyohukumu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 60, 'Wale wasioiamini Akhera wana mfano mbaya mno, naye Mwenyezi Mungu ndiye Mwenye mfano bora zaidi. Naye ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 61, 'Na lau kuwa Mwenyezi Mungu angeliwaadhibu watu kwa mujibu wa dhuluma zao, basi asingelimwacha juu yake hata mnyama mmoja. Lakini anawaahirisha mpaka muda uliowekwa. Na unapofika muda wao, hawatakawia hata saa moja wala hawatatangulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 62, 'Na wanampa Mwenyezi Mungu wanavyovichukia wao, na ndimi zao zinasema uongo kwamba wao watapata mazuri zaidi. Hakuna shaka kwamba hakika wana Moto, na kwamba kwa yakini wataachwa humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 63, 'Tallahi! Hakika tuliwatuma Mitume kwa umma zilizokuwa kabla yako, lakini Shetani akawapambia matendo yao. Kwa hivyo leo, yeye ndiye kipenzi chao msaidizi, nao wana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 64, 'Na hatukukuteremshia Kitabu hiki isipokuwa ili uwabainishie yale ambayo wanahitilafiana ndani yake, na kiwe uwongofu na rehema kwa kaumu wanaoamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 65, 'Na Mwenyezi Mungu ameteremsha maji kutoka mbinguni na kwa hayo akaihuisha ardhi baada ya kufa kwake. Kwa hakika, katika hayo imo Ishara kwa kaumu wanaosikia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 66, 'Na hakika katika wanyama wa kufugwa[1], mna mazingatio. Tunawanywesha katika vile vilivyomo matumboni mwao - baina ya mavi na damu - maziwa safi, mazuri kwa wanywao.', '[1] Nao ni ngamia, ng''ombe, mbuzi na kondoo.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 67, 'Na kutokana na matunda ya mitende na mizabibu mnatengeneza vileo na riziki nzuri. Hakika katika hayo ipo Ishara kwa kaumu watumiao akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 68, 'Na Mola wako Mlezi alimfunulia nyuki kwamba: Jitengenezee majumba yako katika milima, na katika miti, na katika vile wanavyojenga watu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 69, 'Kisha kula katika kila matunda, na upite katika njia za Mola wako Mlezi zilizofanywa nyepesi kuzipita. Na kwenye matumbo yao kinatoka kinywaji chenye rangi mbalimbali; ndani yake kuna ponya kwa watu. Hakika katika haya ipo Ishara kwa kaumu wanaotafakari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 70, 'Na Mwenyezi Mungu aliwaumba; kisha atawafisha. Na miongoni mwenu wapo wanaorudishwa kwenye umri mbaya kabisa, hata akawa hajui kitu baada ya kuwa alikuwa anajua. Hakika Mwenyezi Mungu ndiye Mwenye kujua zaidi, Muweza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 71, 'Na Mwenyezi Mungu amewaboresha baadhi yenu kuliko wengine katika riziki. Na wale walioboreshwa hawarudishi riziki zao kwa wale iliowamiliki mikono yao ya kulia ili wawe sawa katika riziki hiyo. Basi je, wanazikataa neema za Mwenyezi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 72, 'Na Mwenyezi Mungu amewaumbia wake kutokana na nyinyi wenyewe, na akawafanyia kutoka kwa wake zenu wana na wajukuu, na akawaruzuku vitu vizuri. Basi je, wanaamini upotovu na wanazikufuru neema za Mwenyezi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 73, 'Na badala ya Mwenyezi Mungu wanawaabudu wasiowamilikia riziki kutoka mbinguni wala kwenye ardhi, wala hawawezi kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 74, 'Basi msimpigie Mwenyezi Mungu mifano. Hakika Mwenyezi Mungu anajua, na nyinyi hamjui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 75, 'Mwenyezi Mungu amepiga mfano wa mtumwa aliyemilikiwa, asiyeweza kitu, na mwingine tuliyemruzuku riziki njema inayotoka kwetu, naye akawa anatoa katika riziki hiyo kwa siri na dhahiri. Je, hao watakuwa sawa? Alhamdu Lillahi (sifa zote njema ni za Mwenyezi Mungu)! Lakini wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 76, 'Na Mwenyezi Mungu amepiga mfano wa wanaume wawili. Mmoja wao ni bubu, hawezi chochote, naye ni mzigo kwa mlezi wake. Popote anapomuelekeza, haleti heri yoyote. Je, huyo anaweza kuwa sawa na yule anayeamrisha uadilifu, naye yuko kwenye njia iliyonyooka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 77, 'Na siri zote za mbinguni na ardhini ni za Mwenyezi Mungu. Wala halikuwa jambo la Saa (ya Kiyama) isipokuwa kama kupepesa kwa jicho, au chini zaidi ya hivyo. Hakika Mwenyezi Mungu ni Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 78, 'Na Mwenyezi Mungu aliwatoa matumboni mwa mama zenu hali ya kuwa hamjui kitu, na akawajaalia kusikia na kuona na ufahamu wa nyoyo ili mpate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 79, 'Je, hawawaoni ndege walivyotiishwa katika anga la mbingu? Hakuna mwenye kuwashikilia isipokuwa Mwenyezi Mungu. Hakika katika haya zipo ishara kwa kaumu wanaoamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 80, 'Na Mwenyezi Mungu amewajaalia majumba yenu yawe ni maskani yenu, na amewajaalia kutokana na ngozi za wanyama, nyumba mnazoziona nyepesi wakati wa safari zenu na wakati wa kutua kwenu. Na kutokana na sufu zao, na manyoya yao, na nywele zao, mnafanya vyombo na mapambo ya kutumia kwa muda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 81, 'Na Mwenyezi Mungu amewafanyia vivuli katika vitu alivyoviumba, na amewafanyia maskani milimani, na amewafanyia nguo za kuwakinga kutokana na joto, na nguo za kuwakinga katika vita vyenu. Ndivyo hivyo anavyowatimizia neema zake ili mpate kujisalimisha kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 82, 'Kwa hivyo, wakikengeuka, basi lililo juu yako wewe ni kufikisha ujumbe wazi wazi tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 83, 'Wanazijua neema za Mwenyezi Mungu, kisha wanazikanusha, na wengi wao ni makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 84, 'Na siku tutakapomtoa shahidi kutoka katika kila umma, kisha hawataruhusiwa wale waliokufuru wala hawataachiliwa kutaka radhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 85, 'Na wale waliodhulumu watakapoiona adhabu, hawatapunguziwa adhabu hiyo, wala hawatapewa muhula.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 86, 'Na wale walioshirikisha watakapowaona hao waliowashirikisha na Mwenyezi Mungu, watasema: "Mola wetu Mlezi! Hawa ndio washirikishwa wetu ambao tulikuwa tukiwaomba badala yako." Lakini hao watawatupia kauli: Hakika nyinyi ni waongo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 87, 'Na siku hiyo watasalimu amri mbele ya Mwenyezi Mungu, na yatapotea yale waliyokuwa wakiyazua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 88, 'Wale waliokufuru na kuzuilia njia ya Mwenyezi Mungu, tutawazidishia adhabu juu ya adhabu, kwa walivyokuwa wakifanya uharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 89, 'Na (waonye) siku tutakapomtoa shahidi katika kila umma kutokana na wao wenyewe, na tutakuleta wewe uwe shahidi juu ya hawa. Na tumekuteremshia Kitabu hiki kinachobainisha kila kitu, na ni uongofu, na rehema, na bishara kwa Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 90, 'Hakika Mwenyezi Mungu anaamrisha kufanya uadilifu, na hisani, na kuwapa jamaa, na anakataza uchafu, na uovu, na dhuluma. Anawaaidhi ili mpate kukumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 91, 'Na timizeni agano la Mwenyezi Mungu mnapoagana, wala msivunje viapo baada ya kuvifunga imara, ilhali mmekwishamfanya Mwenyezi Mungu ndiye mdhamini wenu. Hakika Mwenyezi Mungu anayajua myafanyayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 92, 'Wala msiwe kama mwanamke yule aliyeufumua uzi wake baada ya kwishausokota ukawa mgumu. Mnavifanya viapo vyenu kuwa ni njia ya kudanganyana baina yenu kwa kuwa ati umma mmoja una nguvu zaidi kuliko mwingine? Hakika Mwenyezi Mungu anawajaribu kwa njia hiyo. Na bila ya shaka atawabainishia Siku ya Kiyama yale mliyokuwa mkihitilafiana ndani yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 93, 'Na Mwenyezi Mungu angelitaka, kwa yakini angeliwafanya kuwa umma mmoja. Lakini anampoteza amtakaye, na anamwongoa amtakaye. Na hakika mtaulizwa juu ya yale mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 94, 'Wala msifanye viapo vyenu kuwa njia ya kudanganyana baina yenu, mguu ukajateleza baada ya kuwa thabiti, na mkaonja mabaya kwa sababu ya kule kuzuilia kwenu njia ya Mwenyezi Mungu, na mkapata adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 95, 'Wala msinunue kwa agano la Mwenyezi Mungu thamani ndogo. Hakika kilicho kwa Mwenyezi Mungu ndicho bora kwenu, ikiwa mnajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 96, 'Mlivyo navyo vitakwisha, na vilivyo kwa Mwenyezi Mungu ndivyo vitakavyobakia. Na kwa yakini Sisi tutawapa wale waliosubiri ujira wao kwa bora zaidi ya yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 97, 'Mwenye kutenda mema, mwanamume au mwanamke, naye akawa ni Muumini, hakika tutamhuisha uhai mwema, na hakika tutawapa ujira wao kwa bora zaidi ya yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 98, 'Na unaposoma Qur-ani, mwombe Mwenyezi Mungu akulinde kutokana na Shetani aliyelaaniwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 99, 'Hakika yeye hana mamlaka juu ya wale walioamini na wakamtegemea Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 100, 'Hakika mamlaka yake yako juu ya wale wanaomfanya kuwa rafiki yao msaidizi, na wale wanaofanya ushirika naye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 101, 'Na tunapobadilisha Ishara pahala pa Ishara, na Mwenyezi Mungu anayajua anayoyateremsha, wanasema: "Wewe si chochote ila ni mzushi tu", lakini wengi wao hawajui tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 102, 'Sema: Ameiteremsha Roho Mtakatifu kutoka kwa Mola wako Mlezi kwa haki, ili iwaimarishe wale walioamini, na kuwa ni uongofu, na bishara kwa Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 103, 'Na Sisi hakika tunajua kwamba wanasema: "Hakika yuko mtu anayemfundisha." Lugha ya huyo wanayemuelekezea ni ya kigeni, na hii ni lugha ya Kiarabu iliyo bainifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 104, 'Hakika wale wasioziamini Ishara za Mwenyezi Mungu, Mwenyezi Mungu hawaongoi, nao wana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 105, 'Hakika wanazua uongo tu wale wasioziamini Ishara za Mwenyezi Mungu. Na hao ndio waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 106, 'Anayemkufuru Mwenyezi Mungu baada ya kuamini kwake - isipokuwa yule aliyelazimishwa na hali ya kuwa moyo wake umetua juu ya Imani, lakini yule aliyekifungulia kifua chake ukafiri - basi hao ghadhabu ya Mwenyezi Mungu ipo juu yao, na wao wana adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 107, 'Hayo ni kwa sababu wameupendelea uhai wa dunia hii kuliko Akhera, na kwa sababu Mwenyezi Mungu hawaongoi kaumu makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 108, 'Hao ndio ambao Mwenyezi Mungu ameziziba nyoyo zao na kusikia kwao na kuona kwao. Na hao ndio walioghafilika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 109, 'Hakuna shaka ya kwamba hao ndio waliohasirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 110, 'Kisha hakika Mola wako Mlezi, kwa wale waliohama makwao baada ya kuteswa, kisha wakapigania Dini na wakasubiri, bila ya shaka Mola wako Mlezi baada ya hayo ni Mwingi wa kusamehe, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 111, 'Siku ambayo kila nafsi itakuja ikijitetea, na kila nafsi italipwa kikamilifu yale iliyotenda, nao hawatadhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 112, 'Na Mwenyezi Mungu amepiga mfano wa mji uliokuwa na amani na utulivu, riziki yake ikiufikia kwa wingi kutokea kila mahali. Lakini ukazikufuru neema za Mwenyezi Mungu; kwa hivyo Mwenyezi Mungu akauvisha vazi la njaa na hofu kwa sababu ya yale waliyokuwa wakiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 113, 'Na alikwishawajia Mjumbe kutoka miongoni mwao. Lakini wakamkadhibisha; basi ikawachukua adhabu hali ya kuwa ni madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 114, 'Basi kuleni katika vile alivyowaruzuku Mwenyezi Mungu, vilivyo halali na vizuri. Na shukuruni neema za Mwenyezi Mungu, ikiwa kweli mnamuabudu Yeye tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 115, 'Hakika amewaharimishia tu nyamafu, na damu, na nyama ya nguruwe, na mnyama aliyechinjwa kwa ajili ya asiyekuwa Mwenyezi Mungu. Lakini anayelazimishwa bila ya kuasi, wala kuvuka mipaka, basi hakika Mwenyezi Mungu ni Mwingi wa kusamehe, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 116, 'Wala msiseme uongo, kwa kuropokwa na ndimi zenu: Hiki ni halali, na hiki ni haramu - mkimzulia uongo Mwenyezi Mungu. Hakika wale wanaomzulia uongo Mwenyezi Mungu hawatafaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 117, 'Ni starehe ndogo tu, nao wana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 118, 'Na Mayahudi tuliwaharimishia yale tuliyokuhadithia zamani. Na Sisi hatukuwadhulumu, bali walikuwa wakijudhulumu wenyewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 119, 'Kisha hakika Mola wako Mlezi kwa wale waliotenda mabaya kwa ujinga, kisha wakatubia baada ya hayo na wakatenda mazuri; bila ya shaka Mola wako Mlezi baada ya hayo ni Mwingi wa kusamehe, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 120, 'Hakika Ibrahim alikuwa mfano mwema, mnyenyekevu kwa Mwenyezi Mungu, mnyoofu kwa Mwenyezi Mungu, wala hakuwa miongoni mwa washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 121, 'Mwenye kuzishukuru neema zake. Yeye alimteua, na akamwongoa kwenye njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 122, 'Na tukampa mazuri katika dunia, naye hakika Akhera atakuwa miongoni mwa walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 123, 'Kisha tukakufunulia ya kwamba ufuate mila ya Ibrahim, mnyoofu kwa Mwenyezi Mungu, wala hakuwa miongoni mwa washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 124, 'Hakika siku ya Sabato (Jumamosi) waliwekewa wale waliohitilafiana kuhusiana nayo. Na hakika Mola wako Mlezi bila ya shaka atahukumu baina yao Siku ya Kiyama katika yale waliyokuwa wakihitilafiana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 125, 'Lingania kwenye njia ya Mola wako Mlezi kwa hekima na mawaidha mazuri, na ujadiliane nao kwa namna iliyo nzuri zaidi. Hakika Mola wako Mlezi ndiye anayemjua zaidi yule aliyeipotea njia yake, na Yeye ndiye anayewajua zaidi wale walioongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 126, 'Na mkilipiza, basi lipizeni sawa na vile mlivyoadhibiwa. Na ikiwa mtasubiri, basi hakika hivyo ni bora zaidi kwa wanaosubiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 127, 'Na subiri. Na kusubiri kwako kusiwe isipokuwa kwa ajili ya Mwenyezi Mungu tu. Wala usiwahuzunikie, wala usiwe katika dhiki kwa sababu ya njama wanazozifanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 128, 'Hakika Mwenyezi Mungu yu pamoja na wenye kumcha, na wale watendao mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 1, 'Ametakasika yule aliyemsafirisha mja wake usiku mmoja kutoka katika Msikiti Mtakatifu mpaka Msikiti wa Al-Aqswa, ambao tumebariki kandoni mwake, ili tumuonyeshe katika Ishara zetu. Hakika Yeye ndiye Mwenye kusikia zaidi, Mwenye kuona mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 2, 'Na tulimpa Musa Kitabu na tukakifanya kuwa ni uongofu kwa Wana wa Israili. (Tukawaambia) kwamba msimfanye yeyote asiyekuwa mimi kuwa mtegemewa wenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 3, 'Kizazi cha wale tuliowabeba pamoja na Nuhu. Hakika yeye alikuwa mja wa kushukuru sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 4, 'Na tukawahukumia Wana wa Israili katika Kitabu kwamba hakika mtafanya uharibifu katika ardhi mara mbili, na hakika mtapanda kiburi, kupanda kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 5, 'Na itakapokuja ahadi ya kwanza yake, tutawatumia waja wetu wenye nguvu kubwa. Watawaingilia ndani ya majumba. Na hii ilikuwa ahadi iliyotimizwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 6, 'Kisha tukawarudishia nguvu zenu dhidi yao, na tukawasaidia kwa mali na wana, na tukawafanya kuwa wengi zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 7, 'Mkifanya wema, mnafanyia wema nafsi zenu. Na mkifanya ubaya, basi mnajifanyia wenyewe. Na ikifika ahadi ya mwisho ili waziharibu nyuso zenu na waingie Msikitini kama walivyoingia mara ya kwanza na waharibu kila walichokiteka kwa uharibifu mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 8, 'Huenda Mola wenu Mlezi akakurehemuni, na mkirudia, na sisi tutarudia. Na tumeifanya Jahannam kuwa ni gereza kwa ajili ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 9, 'Hakika hii Qur-ani inaongoa kwenye yale yaliyonyooka kabisa, na inawabashiria Waumini ambao wanatenda mema ya kwamba wana malipo makubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 10, 'Na ya kwamba wale wasioiamini Akhera, tumewaandalia adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 11, 'Na mtu huomba maovu kama vile aombavyo heri, kwani mtu ni mwenye pupa mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 12, 'Na tumefanya usiku na mchana kuwa ishara mbili. Tena tukaifuta ishara ya usiku, na tukaifanya ishara ya mchana ni yenye mwangaza ili mtafute fadhila itokayo kwa Mola wenu Mlezi, na ili mpate kujua idadi ya miaka na hesabu. Na kila kitu tumekifafanua kwa kina waziwazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 13, 'Na kila mtu tumemfungia matendo yake shingoni mwake. Na Siku ya Kiyama tutamtolea kitabu atakachokikuta ki wazi kimekunjuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 14, 'Ataambiwa: Soma kitabu chako! Nafsi yako inakutosha leo kukuhesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 15, 'Anayeongoka, basi anaongoka kwa ajili ya nafsi yake. Na anayepotea, basi anapotea kwa hasara yake mwenyewe. Wala habebi mbebaji mzigo wa mwengine. Wala Sisi hatuadhibu mpaka tumtume mtume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 16, 'Na pindi tukitaka kuuteketeza mji, tunawaamrisha wale wana starehe na taanusi wake, lakini wao wakaendelea kutenda maovu humo. Basi hapo kauli ikathibiti juu ya mji huo, nasi tukauangamiza kwa maangamizo makubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 17, 'Na kaumu ngapi tumeziangamiza baada ya Nuhu! Na Mola wako Mlezi anatosha kabisa kuwa ni Mwenye kuzijua na kuziona dhambi za waja wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 18, 'Anayetaka yapitayo upesi upesi, tutafanya haraka kumletea humo (duniani) tunayoyataka kwa tumtakaye. Kisha tumemwekea Jahannamu, ataingia humo hali ya kuwa ni mwenye kulaumiwa na kufurushwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 19, 'Na anayeitaka Akhera, na akaifanyia juhudi ipasavyo ilhali ni Muumini, basi hao juhudi zao zitakuwa ni za kushukuriwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 20, 'Wote hao tunawakunjulia, hawa na hao, katika vipawa vya Mola wako Mlezi. Wala vipawa vya Mola wako Mlezi havizuiliki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 21, 'Angalia vipi tulivyowafadhilisha baadhi yao kuliko wengine wao. Na hakika Akhera ni yenye daraja kubwa zaidi na fadhila kubwa zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 22, 'Usimfanye mungu mwengine pamoja na Mwenyezi Mungu, ukaja ukawa wa kulaumiwa uliyetupika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 23, 'Na Mola wako Mlezi ameamrisha kuwa msimuabudu yeyote ila Yeye tu, na wazazi wawili muwatendee wema. Mmoja wao akifikia uzee, naye yuko pamoja nawe, au wote wawili, basi usiwaambie hata, "Ah!" Wala usiwakemee. Na uwaambie maneno ya heshima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 24, 'Na uwainamishie bawa la unyenyekevu kwa kuwaonea rehema. Na useme: Mola wangu Mlezi! Warehemu kama walivyonilea utotoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 25, 'Mola wenu Mlezi anajua kabisa yaliyo nyoyoni mwenu. Ikiwa nyinyi mtakuwa wema, basi hakika Yeye ni Mwenye kuwaghufiria wanaorudi sana kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 26, 'Na mpe aliye jamaa yako haki yake, na masikini, na msafiri; wala usitumie ovyo kwa fujo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 27, 'Hakika watumiao ovyo kwa fujo ni ndugu wa Mashetani. Na Shetani ni mwenye kumkufuru mno Mola wake Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 28, 'Na ikiwa utawapa mgongo sawasawa, nawe unatafuta rehema kutoka kwa Mola wako Mlezi unayoitaraji, basi sema nao maneno laini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 29, 'Wala usiufanye mkono wako kama uliofungwa shingoni mwako, wala usiukunjue wote kabisa, ukabaki ukilaumiwa uliyefilisika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 30, 'Hakika Mola wako Mlezi humkunjulia riziki amtakaye, na humpimia amtakaye. Hakika Yeye kwa waja wake ni Mwenye kuwajua na kuwaona vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 31, 'Wala msiwaue wana wenu kwa kuogopa umasikini. Sisi tunawaruzuku wao na nyinyi. Hakika kuwaua hao kulikuwa ni kosa kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 32, 'Wala msikaribie uzinzi. Hakika huo ni uchafu na njia mbaya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 33, 'Wala msiuwe nafsi ambayo Mwenyezi Mungu amekataza isipokuwa kwa haki. Na aliyeuliwa kwa kudhulumiwa, basi hakika tumempa msimamizi wake mamlaka. Lakini asipitilize kiasi katika kuua. Kwani yeye anasaidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 34, 'Wala msiyakaribie mali ya yatima, isipokuwa kwa njia iliyo nzuri zaidi, mpaka afike utu uzimani. Na timizeni ahadi. Kwa hakika ahadi itaulizwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 35, 'Na timizeni kipimo mnapopima. Na pimeni kwa mizani zilizo sawa. Hayo ni heri na yenye mwisho bora.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 36, 'Wala usiyafuate usiyo na elimu nayo. Hakika kusikia, na kuona, na (ufahamu wa) moyo hivyo vyote itaulizwa juu yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 37, 'Wala usitembee katika ardhi kwa kiburi. Hakika wewe huwezi kuipasua ardhi na kamwe huwezi kufikia urefu wa milima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 38, 'Hayo yote ubaya wake ni wenye kuchukiza kwa Mola wako Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 39, 'Hayo ni katika hekima alizokufunulia Mola wako Mlezi. Wala usimweke pamoja na Mwenyezi Mungu mungu mwengine, ukaja ukatupwa katika Jahannamu ukilaumiwa na kufurushwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 40, 'Je, Mola wenu Mlezi amewateulia nyinyi wavulana, na Yeye akawafanya Malaika ni banati zake? Kwa hakika nyinyi mnasema kauli kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 41, 'Na tumekwishabainisha katika Qur''ani hii ili wapate kukumbuka. Lakini haikuwazidisha ila kuwa mbali nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 42, 'Sema: Lau kuwa wangelikuwa pamoja naye miungu mingine kama wasemavyo, basi wangelitafuta njia ya kumfikia Mwenye Kiti cha Enzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 43, 'Subhanahu Wa Taa''la, (Ametakasika na Ametukuka mbali) kabisa na hayo wanayoyasema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 44, 'Zinamtakasa mbingu zote saba na ardhi na vyote vilivyo ndani yake. Na hakuna kitu ila kinamtakasa kwa sifa zake. Lakini nyinyi hamfahamu kutakasa kwake. Hakika Yeye ni Mpole na Mwenye maghfira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 45, 'Na unaposoma Qur-ani, tunaweka baina yako na wale wasioiamini Akhera pazia linalowafunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 46, 'Na tunaweka vifuniko juu ya nyoyo zao wasije wakaifahamu, na tunaweka kwenye masikio yao uziwi. Na unapomtaja katika Qur-ani Mola wako Mlezi peke yake, basi wao hugeuka nyuma wakaenda zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 47, 'Sisi tunajua vyema kabisa sababu wanayosikilizia wanapokusikiliza, na wanaponong''ona. Wanaposema hao madhalimu: Nyinyi hamumfuati isipokuwa mwanamume aliyerogwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 48, 'Tazama jinsi walivyokupigia mifano. Basi wakapotea. Kwa hivyo hawawezi kuipata njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 49, 'Na walisema: Je! Tutakapokuwa mifupa na mapande yaliyovurugika, tutafufuliwa kwa umbo jipya?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 50, 'Sema: Kuweni hata mawe au chuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 51, 'Au umbo lolote mnaloliona kubwa katika vifua vyenu. Watasema: Ni nani atakayeturudisha tena? Sema: Yule yule aliyewaumba mara ya kwanza! Watakutikisia vichwa vyao, na watasema: Ni lini hayo? Sema: Labda huenda itakuwa hivi karibuni!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 52, 'Siku atakapowaita, nanyi mtamuitikia kwa kumsifu, na mtadhani kuwa hamkukaa isipokuwa muda mdogo tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 53, 'Waambie waja wangu waseme maneno mazuri, kwa maana hakika Shetani huchochea ugomvi baina yao. Hakika Shetani ni adui aliye dhahiri kwa mwanadamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 54, 'Mola wenu Mlezi anawajua vilivyo. Akitaka, atawarehemu, na akitaka, atawaadhibu. Na hatukukutuma ili uwe msimamizi wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 55, 'Na Mola wako Mlezi anawajua vilivyo waliomo mbinguni na katika ardhi. Na hakika tumewafadhilisha baadhi ya Manabii kuliko wengine, na Daudi tulimpa Zaburi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 56, 'Sema: Waombeni hao mnaowadai badala yake Yeye. Hawawezi kuwaondolea madhara, wala kuyaweka pengine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 57, 'Hao ambao wao wanawaomba, wao wenyewe wanatafuta njia ya kwendea kwa Mola wao Mlezi hata miongoni mwao walio karibu mno, na wanataraji rehema zake, na wanaihofu adhabu yake. Hakika adhabu ya Mola wako Mlezi yafaa kutahadhariwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 58, 'Na hakuna mji wowote ila Sisi tutauteketeza kabla ya Siku ya Kiyama, au tutaupa adhabu kali. Haya yamekwishaandikwa katika Kitabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 59, 'Na hakuna kinachotuzuia kutuma miujiza ila ni kuwa watu wa zamani waliikanusha. Na tuliwapa Wathamudi ngamia jike kuwa ni Ishara iliyo dhaahiri, lakini walidhulumu kwaye. Nasi hatutumii Ishara isipokuwa kwa ajili ya kuhofisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 60, 'Na tulipokwambia: Hakika Mola wako Mlezi amekwishawazingira hao watu. Na hatukuifanya ndoto tuliyokuonyesha isipokuwa ni kuwajaribu watu, na mti uliolaaniwa katika Qur-ani. Na tunawahofisha, lakini haiwazidishii isipokuwa uasi mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 61, 'Na pale tulipowaambia Malaika, "Msujudieni Adam." Wakamsujudia isipokuwa Iblisi. Akasema, "Je, nimsujudie uliyemuumba kwa udongo?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 62, 'Akasema, "Hebu unamuona huyu uliyemtukuza zaidi yangu, ukiniahirisha mpaka Siku ya Kiyama, hapana shaka nitakiangamiza kizazi chake isipokuwa wachache tu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 63, 'Akasema Mwenyezi Mungu: Nenda! Na atakayekufuata katika wao, basi hakika Jahannamu itakuwa ndiyo malipo yenu, malipo yaliyo mengi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 64, 'Na wachochee uwawezao katika wao kwa sauti yako, na wakusanyie jeshi lako la wapandao farasi na waendao kwa miguu. Na shirikiana nao katika mali na wana, na waahidi. Na Shetani hawapi ahadi isipokuwa ya udanganyifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 65, 'Hakika wewe huna mamlaka yoyote juu ya waja wangu. Na Mola wako Mlezi anatosha kuwa ni Mtegemewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 66, 'Mola wenu Mlezi ndiye anayewaendeshea merikebu katika bahari ili mtafute katika fadhila zake. Hakika Yeye ni Mwingi wa kukurehemuni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 67, 'Na inapowakuta taabu katika bahari, hao mnaowaomba wanapotea, isipokuwa Yeye tu. Na anapowaokoa mkafika nchi kavu, mnageuka. Ama mwanadamu ni mwingi wa kukufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 68, 'Je, mna amani ya kuwa hatawadidimiza katika upande wowote katika nchi kavu, au kwamba hatawatumia tufani la kokoto? Kisha msipate yeyote wa kumtegemea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 69, 'Au mna amani ya kuwa hatawarudisha humo mara nyingine na akawatumia kimbunga cha upepo akawazamisha kwa mlivyokufuru, na kisha msipate wa kuwanusuru kutokana nasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 70, 'Na hakika tumewatukuza wanadamu, na tukawabeba katika nchi kavu na baharini, na tukawaruzuku katika vitu vizuri vizuri, na tukawafadhilisha kwa fadhila kubwa kuliko wengi miongoni mwa wale tuliowaumba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 71, 'Siku tutakapoita kila kikundi cha watu kwa mujibu wa wakifuatacho, basi atakayepewa kitabu chake kwa mkono wake wa kulia, basi hao watasoma kitabu chao wala hawatadhulumiwa hata chembe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 72, 'Na yule ambaye ni kipofu hapa, basi atakuwa kipofu Akhera, na atakuwa ndiye mpotovu zaidi wa Njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 73, 'Na hakika walikaribia kukushawishi uache hayo tuliyokufunulia ili utuzulie mengineyo. Na hapo, ndipo wangelikufanya mwandani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 74, 'Na lau kuwa hatukukuweka imara, ungelikaribia kuwaegemea kidogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 75, 'Hapo basi bila ya shaka, tungelikuonjesha adhabu maradufu ya uhai, na adhabu maradufu ya kifo. Kisha usingepata yeyote wa kukunusuru kutokana nasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 76, 'Na walitaka kukukera ili wakutoe nchini. Na hapo, wao wasingelibakia humo isipokuwa kwa muda mchache tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 77, 'Hiyo ndiyo desturi ya Mitume wetu tuliowatuma kabla yako. Wala hutapata mabadiliko katika desturi yetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 78, 'Simamisha Swala jua linapopinduka mpaka giza la usiku, na Qur-ani ya alfajiri. Hakika Qur-ani ya alfajiri inashuhudiwa daima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 79, 'Na amka usiku kwa ajili ya kufanya ibada kwayo, ni ziada ya sunna hasa kwako wewe. Huenda Mola wako Mlezi akakunyanyua cheo kinachosifika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 80, 'Na sema, "Mola wangu Mlezi! Niingize muingizo mwema, na unitoe kutoka kwema. Na unipe nguvu zinazotoka kwako zinisaidie."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 81, 'Na sema, "Haki imefika, na batili imetoweka. Hakika batili lazima itoweke!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 82, 'Na tunateremsha katika Qur-ani yale ambayo ni uponyaji na rehema kwa Waumini. Wala hayawazidishii madhalimu isipokuwa hasara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 83, 'Na tunapomneemesha mtu, hugeuka na kujitenga kando. Na yanapomgusa maovu, hukata tamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 84, 'Sema, "Kila mmoja anafanya kwa namna yake. Na Mola wenu Mlezi ndiye anayejua zaidi yule aliyeongoka katika njia."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 85, 'Na wanakuuliza habari za Roho. Sema, "Roho ni katika mambo ya Mola wangu Mlezi. Nanyi hamkupewa katika elimu isipokuwa kidogo tu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 86, 'Na tungelipenda, tungeliyaondoa yale tuliyokufunulia. Kisha usingelipata mwakilishi wa kukupigania kwetu kwa haya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 87, 'Isipokuwa iwe rehema itokayo kwa Mola wako Mlezi. Hakika fadhila yake kwako ni kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 88, 'Sema: Wangelikusanyika watu na majini ili walete mfano wa Qur-ani hii, basi hawawezi kuleta mfano wake, hata kama watasaidiana wao kwa wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 89, 'Na hakika tumewaeleza watu katika Qur-ani hii kwa kila mfano. Lakini wengi wa watu wakakataa isipokuwa kukufuru tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 90, 'Na walisema, "Hatutakuamini mpaka ututimbulie chemichemi katika ardhi hii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 91, 'Au uwe na bustani ya mitende na mizabibu, na utupitishie mito kati yake ikimiminika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 92, 'Au utuangushie mbingu vipande vipande kama ulivyodai, au utuletee Mwenyezi Mungu na Malaika uso kwa uso.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 93, 'Au uwe na nyumba iliyopambwa, au upae mbinguni. Wala hatutaamini kupaa kwako huko mpaka ututeremshie kitabu tukisome.ˮ Sema, “Subhana Rabbi (Ametakasika Mola wangu Mlezi)! Kwani mimi ni nani isipokuwa ni mtu tu Mtume?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 94, 'Na hakikuwazuilia watu kuamini ulipowajia uongofu isipokuwa ni kwamba walisema, "Je, Mwenyezi Mungu alimtuma mtu kuwa ni Mtume?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 95, 'Sema, "Ingelikuwa katika ardhi wapo Malaika wanatembea kwa utulivu wao, basi bila ya shaka tungeliwateremshia Malaika kuwa ni Mtume wao."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 96, 'Sema, "Mwenyezi Mungu anatosha kuwa Shahidi baina yangu na nyinyi. Hakika Yeye ana habari zote za waja wake na anawaona vyema."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 97, 'Na yule ambaye Mwenyezi Mungu anamuongoa, basi huyo ndiye aliyeongoka. Na yule ambaye anampotoa, basi hutawapatia walinzi wowote badala yake. Na tutawakusanya Siku ya Kiyama hali ya kuwa wanakokotwa juu ya nyuso zao, huku ni vipofu, mabubu, na viziwi. Na makazi yao ni Jahannamu. Kila ukifanya kuzimika, tutazidi kuuchochea uwake kwa nguvu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 98, 'Hayo ni malipo yao kwa sababu walizikataa ishara zetu, na wakasema: Hivyo tukishakuwa mifupa na mapande yaliyovurugika tutafufuliwa kwa umbo jipya?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 99, 'Kwani hawakuona ya kwamba Mwenyezi Mungu aliyeumba mbingu na ardhi ni Mwenye kuweza kuumba mfano wao? Na Yeye amewawekea muda usio na shaka yoyote. Lakini madhalimu walikataa isipokuwa kukufuru tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 100, 'Sema, "Lau kuwa nyinyi mnazimiliki hazina za rehema za Mola wangu Mlezi, basi hapana shaka mngelizuia kwa sababu ya kuhofu kuzitumia. Na mtu tangu hapo tabia yake ni mchoyo mno!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 101, 'Na kwa yakini tulimpa Musa ishara tisa zilizo wazi. Basi waulize Wana wa Israili alipowafikia, na Firauni akamwaambia, "Hakika mimi ninakuona wewe Musa umerogwa!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 102, 'Musa akasema, "Wewe unajua bila ya shaka kuwa haya hakuyateremsha isipokuwa Mola Mlezi wa mbingu na ardhi ili kuwa ni ushahidi wa kuonekana. Na hakika mimi bila ya shaka nakuona wewe, Firauni, kuwa utaangamizwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 103, 'Basi Firauni akataka kuwafukuza katika nchi. Kwa hivyo tukamzamisha majini yeye na wale waliokuwa pamoja naye wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 104, 'Na tukawaambia baada yake Wana wa Israili, "Kaeni katika nchi. Na itakapokuja ahadi ya Akhera, tutawaleta nyote pamoja."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 105, 'Na kwa Haki tuliiteremsha, na kwa Haki iliteremka. Na hatukukutuma isipokuwa uwe mbashiri na mwonyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 106, 'Na Qur-ani tumeigawanya sehemu mbalimbali ili uwasomee watu kwa kituo, na tumeiteremsha kidogo kidogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 107, 'Sema, "Iaminini au msiiamini. Hakika wale waliopewa elimu kabla yake, wanaposomewa hii, huanguka kifudifudi wanasujudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 108, 'Na wanasema, ''Subhana Rabbina (Ametakasika Mola wetu Mlezi)! Hakika ahadi ya Mola wetu Mlezi lazima itimizwe!''"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 109, 'Na huanguka kifudifudi na huku wanalia, na inawazidisha unyenyekevu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 110, 'Sema, "Mwombeni Allah (Mwenyezi Mungu), au mwombeni Ar-Rahman (Mwingi wa rehema), kwa jina lolote mnalomwita. Hakika, Yeye ana majina mazuri zaidi." Wala usiswali Swala yako kwa sauti kubwa sana, wala usiifiche kwa sauti ndogo sana, bali shika njia ya kati na kati ya hizo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 111, 'Na sema: Alhamdulillah (sifa njema zote ni za Mwenyezi Mungu) ambaye hakujifanyia mwana yeyote, wala hana mshirika yeyote katika ufalme, wala hana mlinzi yeyote wa kumsaidia kwa sababu ya udhaifu. Na mtukuze kwa utukufu mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 1, 'Sifa njema zote ni za Mwenyezi Mungu, ambaye alimteremshia mja wake Kitabu, wala hakukifanya kuwa na upogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 2, 'Kimenyooka sawa sawa, ili kionye adhabu kali kutoka kwake, na kiwabashirie Waumini watendao mema kwamba hakika wana ujira mzuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 3, 'Wakae humo milele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 4, 'Na kiwaonye wasemao, "Mwenyezi Mungu alijifanyia mwana."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 5, 'Wao hawana elimu yoyote ya jambo hili, wala baba zao. Ni neno kubwa hilo litokalo vinywani mwao. Hawasemi isipokuwa uongo tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 6, 'Huenda ukajihiliki nafsi yako kwa ajili yao, kuwasikitikia kwa kuwa hawayaamini mazungumzo haya!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 7, 'Kwa hakika tumevifanya vilivyoko juu ya ardhi kuwa ni pambo lake ili tuwafanyie mtihani, ni nani kati yao ndio wenye vitendo vizuri zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 8, 'Na hakika Sisi tutavifanya vyote vilivyo juu ya ardhi kuwa kama nchi iliyopigwa na ukame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 9, 'Kwani unadhani ya kwamba wale watu wa Pangoni na Maandishi ndio walikuwa tu ajabu miongoni mwa ishara zetu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 10, 'Vijana hao walipokimbilia kwenye pango, na wakasema, "Mola wetu Mlezi! Tupe rehema itokayo kwako, na tutengezee uongofu katika jambo letu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 11, 'Basi tukayaziba masikio yao kuwalaza humo pangoni kwa muda wa miaka kadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 12, 'Kisha tukawazindua ili tujue ni lipi katika makundi mawili yale ndilo lilihesabu sawa zaidi urefu wa muda waliokaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 13, 'Sisi tunakusimulia habari zao kwa haki. Hakika wao walikuwa ni vijana waliomuamini Mola wao Mlezi. Na Sisi tukawazidisha uongofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 14, 'Na tukazitia nguvu nyoyo zao waliposimama na wakasema, "Mola wetu Mlezi ni Mola Mlezi wa mbingu na ardhi. Kamwe hatutamuomba mwingine badala yake kuwa ni Mungu. Hivyo, itakuwa tumesema jambo la kuvuka mpaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 15, 'Hawa kaumu yetu walijifanyia miungu mingine badala yake Yeye. Kwa nini basi hawawatolei uthibitisho ulio dhahiri? Na ni nani aliye dhalimu zaidi kuliko anayemzulia uongo Mwenyezi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 16, 'Na mkijitenga nao na vile wanavyoviabudu badala ya Mwenyezi Mungu, basi kimbilieni pangoni, awafungulie Mola wenu Mlezi katika rehema zake, na awatengenezee ya kuwafaa katika mambo yenu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 17, 'Na unaliona jua linapochomoza, linainamia kuliani mwao kutoka hapo pangoni, na linapokuchwa, linawakwepa kushotoni, na wao wamo katika uwazi wa pango. Hizo ni katika ishara za Mwenyezi Mungu. Yule ambaye Mwenyezi Mungu anamwongoa, basi huyo ameongoka. Na yule ambaye anampoteza, basi hutampatia msimamizi wa kumwongoza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 18, 'Nawe utawadhania wa macho, na hali wamelala. Nasi tunawageuza kulia na kushoto. Na mbwa wao amenyoosha miguu yake ya mbele kizingitini. Kama ungeliwatokea, hakuna shaka ungeligeuka kuwakimbia, huku umejaa hofu kubwa juu yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 19, 'Na kwa namna hiyo tuliwainua usingizini ili wapate kuulizana wao kwa wao. Alisema msemaji katika wao: Mmekaa muda gani? Wakasema: Tumekaa siku moja au sehemu ya siku. Wakasema: Mola wenu Mlezi ndiye anayejua zaidi muda mliokaa. Hebu mtumeni mmoja wenu na hizi fedha zenu aende mjini, akatazame chakula chake kipi kilicho bora kabisa awaletee cha kula. Naye afanye mambo hayo kwa busara, wala kamwe asiwataje kwa yeyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 20, 'Kwani wao wakiwatambua, watawapiga mawe, au watawarudisha katika dini yao, na hapo kamwe hamtafanikiwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 21, 'Na namna hivo ndivyo tulivyowajulisha kwa watu ili wapate kujua ya kwamba ahadi ya Mwenyezi Mungu ni ya kweli, na kwamba Saa haina shaka. Walipokuwa wakigombania jambo lao wao kwa wao, wakasema: Jengeni jengo juu yao. Mola wao Mlezi anawajua vyema. Wakasema wale walioshinda katika shauri yao: Bila ya shaka tutajenga msikiti juu yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 22, 'Watasema: Walikuwa watatu, wa nne wao ni mbwa wao. Na wanasema: “Walikuwa watano, wa sita wao ni mbwa wao.ˮ Wanabahatisha ghaibu. Na wanasema: Walikuwa saba, na wa nane wao ni mbwa wao. Sema: “Mola wangu Mlezi ndiye anayejua sawa sawa hesabu yao. Hawawajui isipokuwa wachache tu.ˮ Basi usibishane juu yao isipokuwa kwa mabishano ya juu juu tu hivi. Wala usiulize habari zao kwa yeyote yule miongoni mwao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 23, 'Wala kamwe usiseme kwa jambo lolote lile: Hakika nitalifanya hilo kesho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 24, 'Isipokuwa Mwenyezi Mungu akipenda. Na mkumbuke Mola wako Mlezi pale unaposahau, na sema: huenda Mola wangu Mlezi ataniongoa kwenye uongozi ulio karibu zaidi kuliko huu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 25, 'Na walikaa katika pango lao hilo miaka mia tatu, na wakazidisha tisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 26, 'Sema: Mwenyezi Mungu ndiye anayejua zaidi muda waliokaa. Ni zake tu siri za mbingu na ardhi. Kuona vyema kulikoje kwake na kusikia kuzuri kulikoje! Hawana mlinzi yeyote isipokuwa Yeye, wala hamshirikishi yeyote katika hukumu yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 27, 'Na soma yale uliyofunuliwa katika Kitabu cha Mola wako Mlezi. Hakuna yeyote awezaye kubadilisha maneno yake. Wala nawe hutapata makimbilio yoyote isipokuwa kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 28, 'Na isubirishe nafsi yako pamoja na wale wanaomuomba Mola wao Mlezi asubuhi na jioni, hali ya kuwa wanataka uso wake. Wala macho yako yasiwaruke kwa kutaka pambo la uhai wa dunia. Wala usimtii tuliyemghafilisha moyo wake asitukumbuke, na akafuata matamanio yake, na mambo yake yakawa ni kupita tu mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 29, 'Na sema: Hii ni haki itokayo kwa Mola wako Mlezi. Basi atakaye, aamini. Na atakaye, akufuru. Hakika Sisi tumewaandalia madhalimu Moto ambao kuta zake zitawazingira. Na wakiomba msaada, watasaidiwa kwa kupewa maji yaliyo kama mafuta yaliyotibuka, yatakayowababua nyuso zao. Ni kinywaji kiovu mno kilichoje hicho, na ni mahali pabaya mno pa kupumzikia palipoje hapo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 30, 'Hakika wale walioamini na wakatenda mema, hakika Sisi hatupotezi ujira wa anayetenda mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 31, 'Hao watapata Bustani za milele, zinazopita mito kwa chini yao. Humo watapambwa kwa mavazi ya mikononi ya dhahabu, na watavaa nguo za kijani za hariri na atilasi, huku wakiegemea humo juu ya makochi. Hayo ndiyo malipo bora zaidi! Na ndiyo matandiko mazuri mno ya kupumzikia!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 32, 'Na wapigie mfano wa wanaume wawili: mmoja wao tulimpa vitalu viwili vya mizabibu, na tukavizungushia mitende, na kati yake tukatia mimea ya nafaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 33, 'Na hivyo vitalu viwili vikatoa mazao yake, wala hapana kitu katika hayo kilichotindikia. Na ndani yake tukapasua mito.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 34, 'Naye alikuwa na mazao mengi. Basi akamwambia mwenzake naye akibishana naye: Mimi nimekushinda wewe kwa mali na nguvu za watu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 35, 'Na akaingia kitaluni kwake, huku anajidhulumu nafsi yake. Akasema: Sidhani kabisa kuwa haya yatawahi kuharibika milele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 36, 'Wala sidhani kuwa hiyo Saa (ya Kiyama) itatokea. Na ikiwa nitarudishwa kwa Mola wangu Mlezi, bila ya shaka nitapata marejeo bora zaidi kuliko haya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 37, 'Mwenzake akamwambia kwa kubishana naye: Je, unamkufuru aliyekuumba kutokana na udongo, tena kutokana na tone la manii, kisha akakufanya mwanamume aliye sawasawa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 38, 'Lakini Yeye Mwenyezi Mungu ndiye Mola wangu Mlezi. Wala simshirikishi Mola wangu Mlezi na yeyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 39, 'Na lau kuwa ulipoingia kitaluni kwako, ungelisema: Mashaallah (alitakalo Mwenyezi Mungu huwa)! Hakuna nguvu yoyote isipokuwa kwa Mwenyezi Mungu. Ikiwa unaniona mimi nina mali kidogo zaidi na watoto kuliko wewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 40, 'Basi huenda Mola wangu Mlezi akanipa kilicho bora kuliko kitalu chako, na akakitumia balaa kutoka mbinguni kwa hivyo kikageuka kuwa ardhi tupu inayoteleza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 41, 'Au maji yake yakazama (katika ardhi), basi usiweze kuyatafuta ukayapata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 42, 'Basi, yakateketezwa matunda yake, akabaki akipinduapindua viganja vyake, kwa vile alivyoyagharamia, huku miti yake imebwagika juu ya chanja zake. Akawa anasema: Laiti nisingelimshirikisha Mola wangu Mlezi na yeyote!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 43, 'Wala hakuwa na kikundi cha kumnusuru badala ya Mwenyezi Mungu, wala mwenyewe hakuweza kujinusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 44, 'Huko ulinzi ni wa Mwenyezi Mungu wa Haki tu. Yeye ndiye mbora zaidi wa malipo, na wa mwisho ulio bora zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 45, 'Na wapigie mfano wa uhai wa dunia ambao ni kama maji tunayoyateremsha kutoka mbinguni, yakachanganyika na mimea ya ardhi, kisha mimea hiyo ikawa vibuwa vinavyopeperushwa na upepo. Na Mwenyezi Mungu ni Mwenye uweza juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 46, 'Mali na wana ni pambo la uhai wa dunia. Na mema yanayobakia ni bora mbele ya Mola wako Mlezi kwa malipo, na bora kwa matumaini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 47, 'Na siku tutakapoiondoa milima na ukaiona ardhi iwazi, na tukawafufua, wala hatutamwacha hata mmoja miongoni mwao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 48, 'Na wakahudhurishwa mbele ya Mola wako Mlezi kwa safu (wakaambiwa): Mmetujia kama tulivyowaumba mara ya kwanza! Bali mlidai kwamba hatutawawekea miadi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 49, 'Na kitawekwa mbele Kitabu. Basi utawaona wahalifu wanavyoogopa mno kwa sababu ya yale yaliyomo. Na watasema: "Ole wetu! Kitabu hiki kina nini! Hakikuacha dogo wala kubwa isipokuwa kililidhibiti vyema?" Na watayakuta yote waliyoyatenda yapo hadharani. Na Mola wako Mlezi hamdhulumu yeyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 50, 'Na tulipowaambia Malaika: Msujudieni Adam! Wakamsjudia isipokuwa Iblisi. Yeye alikuwa miongoni mwa majini, na akavunja amri ya Mola wake Mlezi. Je, mnamchukua yeye na dhuria yake kuwa vipenzi badala yangu, hali wao ni adui zenu? Ni ovu mno badala hii ya madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 51, 'Sikuwashuhudisha kuumbwa kwa mbingu na ardhi, wala kuumbwa kwa wao wenyewe. Wala sikuwafanya wapotezao kuwa ni wasaidizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 52, 'Na siku atakaposema (Mwenyezi Mungu): Waiteni hao mliodai kuwa ni washirika wangu. Basi watawaita, na wao hawatawaitikia. Nasi tutaweka baina yao maangamio.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 53, 'Na wahalifu watauona Moto na watajua ya kwamba wao lazima wataingia humo; wala hawatapata pa kuuepukia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 54, 'Na bila ya shaka tumewaelezea watu katika Qur-ani hii kila namna ya mfano. Lakini mwanadamu amezidi kuliko kila kitu kwa ubishi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 55, 'Na hakikuwazuia watu kuamini ulipowajia uongofu, na kuomba maghfira kwa Mola wao Mlezi, isipokuwa iwafikie desturi ya wale wa mwanzo, au iwafikie adhabu jahara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 56, 'Na hatuwatumi Mitume isipokuwa wawe wabashiri na waonyaji. Na wale waliokufuru wanabishana kwa batili, ili kwayo waivunje haki. Na walizifanya Ishara zangu na yale waliyoonywa kuwa ni mzaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 57, 'Na ni nani dhalimu zaidi kuliko yule anayekumbushwa Ishara za Mola wake Mlezi, naye akazipuuza na akasahau yaliyotangulizwa na mikono yake? Hakika Sisi tumeziba nyoyo zao ili wasifahamu, na uziwi uko kwenye masikio yao. Na ukiwaita kwenye uongofu, kamwe hawataweza kuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 58, 'Na Mola wako Mlezi ni Msamehevu, Mwenye rehema. Lau angeliwachukulia kwa mujibu wa yale waliyoyachuma, bila ya shaka angeliwafanyia haraka kuwaadhibu. Lakini wanayo miadi ambayo hawatapata makimbilio yoyote ya kuepukana nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 59, 'Na miji hiyo tuliwaangamiza watu wake walipodhulumu. Na tukawawekea miadi ya maangamizo yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 60, 'Na pale Musa alipomwambia kijana wake, "Sitaacha kuendelea mpaka nifike zinapokutana bahari mbili, au nitaendelea kwa muda mrefu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 61, 'Basi wawili hao walipofika zinapokutana hizo bahari mbili, walimsahau samaki wao, naye akashika njia yake akaponyokea baharini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 62, 'Walipokwishapita, alimwambia kijana wake: Tupe chakula chetu cha mchana. Kwa hakika tumepata machovu kweli kwa hii safari yetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 63, 'Akasema (kijana): Unaona! Pale tulipopumzika penye jabali, basi mimi nilimsahau yule samaki. Na hakuna aliyenisahaulisha kumkumbuka isipokuwa Shetani tu. Naye akashika njia yake baharini kwa ajabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 64, '(Musa) akasema: "Hayo ndiyo tuliyokuwa tunayataka." Basi wakarudi nyuma kwa kufuata njia waliyojia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 65, 'Basi wakamkuta mja katika waja wetu tuliyempa rehema kutoka kwetu, na tukamfunza mafunzo yaliyotoka kwetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 66, 'Musa akamwambia: Nikufuate ili unifunze katika ule uongofu uliofunzwa wewe?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 67, 'Akasema: Hakika wewe hutaweza kuvumilia kuwa pamoja nami.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 68, 'Na utawezaje kuvumilia yale usiyoyajua vilivyo undani wake?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 69, 'Akasema: In shaa Allah (Mwenyezi Mungu akitaka), utanikuta mvumilivu, wala sitaasi amri yako yoyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 70, 'Akasema: Basi ukinifuata, usiniulize kitu mpaka mimi nianze kukutajia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 71, 'Basi wawili hao wakatoka, hata walipoabiri jahazi (yule mtu), akalitoboa. (Musa) akasema: Unalitoboa ili uwazamishe watu wake? Hakika umefanya jambo baya mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 72, 'Akasema: Je, sikusema kwamba wewe hakika hutaweza kuvumilia kuwa pamoja nami?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 73, '(Musa) akasema: Usinichukulie makosa kwa niliyosahau, wala usinipe uzito kwa jambo langu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 74, 'Basi wakatoka wawili hao mpaka wakamkuta kijana, akamuua. (Musa) akasema: Ala! Umemuua mtu asiye na kosa, na wala hakuua nafsi yoyote! Ama hakika umefanya jambo baya kabisa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 75, '(Yule mtu) Akasema, "Je, sikukwambia kwamba hakika wewe hutaweza kusubiri kuwa pamoja nami?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 76, '(Musa) Akasema, "Nikikuuliza kuhusu kitu chochote baada ya haya, basi usifuatane nami. Kwani hakika umekwishapata udhuru kutoka kwangu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 77, 'Basi wakaondoka mpaka wakawafikia watu wa mji mmoja. Wakawaomba watu wake wawape chakula, nao wakakataa kuwakaribisha. Hapo wakakuta ukuta unataka kuanguka, (yule mja mwema) akausimamisha. (Musa) akasema, "Ungelitaka, ungelichukua ujira kwa haya."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 78, '(Yule mtu) akasema: Huku ndiko kutengana baina yangu na wewe. Sasa nitakueleza maana ya yale ambayo hukuweza kuyastahamili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 79, 'Ama lile jahazi, hilo lilikuwa la masikini fulani wafanyao kazi baharini. Kwa hivyo, nilitaka kulitia dosari, kwani nyuma yao alikuwapo mfalme aliyekuwa akichukua kwa nguvu majahazi yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 80, 'Na ama yule kijana, wazazi wake walikuwa ni Waumini. Tukahofu aje kuwatia mashakani kwa kupindukia mipaka na ukafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 81, 'Basi tulitaka Mola wao Mlezi awabadilishie aliye bora zaidi kuliko huyo kwa kutakasika, na aliye karibu zaidi kwa huruma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 82, 'Na ama ukuta ule, huo ulikuwa ni wa vijana wawili mayatima kule mjini. Na chini yake ilikuwapo hazina yao; na baba yao alikuwa ni mtu mwema. Basi Mola wako Mlezi alitaka wafikie utu uzima wao na wajitolee hazina yao wenyewe, hii ikiwa ni rehema itokayo kwa Mola wako Mlezi. Wala mimi sikutenda hayo kwa amri yangu. Hiyo ndiyo tafsiri ya hayo ambayo wewe hukuweza kuyasubiria.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 83, 'Na wanakuuliza kuhusu Dhul-Qarnain. Waambie: nitawasomea baadhi ya hadithi yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 84, 'Hakika Sisi tulimuimarisha katika ardhi na tukampa katika njia za kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 85, 'Basi akaifuata njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 86, 'Mpaka alipofika machweo ya jua, akaliona linatua katika chemichemi yenye matope meusi. Na pale akawakuta kaumu fulani. Tukasema: Ewe Dhul-Qarnain, ima uwaadhibu au uwafanyie uzuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 87, 'Akasema: Ama aliyedhulumu, basi tutamuadhibu kisha atarudishwa kwa Mola wake Mlezi, naye atamuadhibu adhabu mbaya zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 88, 'Na ama yule mwenye kuamini na akatenda mema, basi huyo ana malipo mazuri, nasi tutamwambia lililo jepesi katika amri yetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 89, 'Kisha akaifuata njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 90, 'Hata alipofika machomozeo ya jua, akaliona linawachomozea kaumu ambao hatukuwawekea pazia ya kuwakinga kutokana nalo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 91, 'Vivyo hivyo. Na Sisi tulizijua vilivyo habari zake zote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 92, 'Kisha akaifuata njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 93, 'Hata alipofika katikati ya milima miwili, alikuta nyuma yake kaumu ambao walikaribia kutofahamu neno lolote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 94, 'Wakasema: Ewe Dhul-Qarnain! Hakika Yaajuju na Maajuju wanafanya uharibifu katika ardhi. Basi je, tukupe ujira ili utie baina yetu na baina yao kizuizi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 95, 'Akasema: Yale ambayo Mola wangu Mlezi ameniimarisha ndani yake ndiyo bora zaidi. Lakini nisaidieni kwa nguvu. Nitaweka baina yenu na baina yao kizuizi imara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 96, 'Nileteeni vipande vya chuma. Hata alipoijaza sawasawa nafasi iliyo katikati ya milima miwili hiyo, akasema, "Pulizeni moto" mpaka alipokifanya kuwa moto, akasema, "Nileteeni shaba iliyoyeyuka niimimine juu ya chuma hicho."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 97, 'Basi hawakuweza kukikwea, wala hawakuweza kukitoboa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 98, 'Akasema, "Hii ni rehema kutoka kwa Mola wangu Mlezi. Na itakapokuja ahadi ya Mola wangu Mlezi, atakivunjavunja. Na ahadi ya Mola wangu Mlezi ni ya kweli."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 99, 'Na tutawaacha baadhi yao siku hiyo wachanganyike wao kwa wao, na litapulizwa baragumu, hapo tutawakusanya wote pamoja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 100, 'Na siku hiyo tutawadhihirishia wazi Jahannamu makafiri waione.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 101, 'Wale ambao macho yao yalikuwa paziani hawanikumbuki, na wakawa hawawezi kusikia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 102, 'Je, wanadhani wale waliokufuru kwamba watawafanya waja wangu kuwa vipenzi wao badala yangu Mimi? Hakika Sisi tumeiandaa Jahannamu iwe ndipo pahali pa kuteremkia pa makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 103, 'Sema: Je, tuwatajieni wenye hasara mno katika vitendo vyao?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 104, 'Ni wale ambao juhudi yao katika uhai wa dunia ilipotea bure, nao wanadhani kwamba wanafanya matendo mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 105, 'Hao ni wale waliozikufuru Ishara za Mola wao Mlezi na kukutana naye. Kwa hivyo matendo yao yakapotea bure, na wala Siku ya Kiyama hatutawasimamishia mizani yoyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 106, 'Hayo ndiyo malipo yao, Jahannam, kwa walivyokufuru na wakafanyia stihizai Ishara zangu na Mitume wangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 107, 'Hakika wale walioamini na wakatenda mema, mashukio yao yatakuwa kwenye Bustani za Firdausi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 108, 'Watadumu humo; kamwe hawatataka kuondoka humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 109, 'Sema: Lau kuwa bahari ingekuwa ndiyo wino kwa maneno ya Mola wangu Mlezi, basi bahari ingelimalizika kabla ya kumalizika maneno ya Mola wangu Mlezi, hata tungeliileta mfano wa hiyo kuongezea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 110, 'Sema, "Hakika mimi ni mwanadamu tu kama nyinyi. Ninaletewa ufunuo (wahyi) kwamba Mungu wenu ni Mungu Mmoja tu. Kwa hivyo, mwenye kutaraji kukutana na Mola wake Mlezi, basi na atende matendo mema, wala asimshirikishe yeyote katika ibada ya Mola wake Mlezi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 1, 'Kaf Ha Ya ''Ayn Swad.[1]', '[1] Herufi hizi "Kaf Ha Ya ''Ayn Swad" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 2, 'Huu ni ukumbusho wa rehema ya Mola wako Mlezi kwa mja wake, Zakariya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 3, 'Alipomwita Mola wake Mlezi kwa siri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 4, 'Akasema: Mola wangu Mlezi! Hakika mimi, mifupa yangu imedhoofika, na kichwa kinametameta kwa mvi; wala, Mola wangu Mlezi, sikuwa mwenye bahati mbaya kwa kukuomba Wewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 5, 'Na hakika mimi ninawahofia wasimamizi wa baada yangu. Na mke wangu ni tasa. Basi nitunuku mrithi kutoka kwako.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 6, 'Anirithi na awarithi ukoo wa Yaaqub. Na umjaalie ewe Mola wangu Mlezi awe mwenye kuridhisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 7, '(Akaambiwa): Ewe Zakariya! Hakika Sisi tunakubashiria mwana; jina lake ni Yahya. Hatujapata kumpa jina hilo yeyote kabla yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 8, 'Akasema: Ewe Mola wangu Mlezi! Vipi nitakuwa na mwana na ilhali mke wangu ni tasa, na mimi nimeshafikia ukongwe katika uzee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 9, 'Akasema: Hivyo ndivyo alivyosema Mola wako Mlezi: Haya ni mepesi kwangu. Na hakika Mimi nilikwishakuumba wewe zamani na wala hukuwa kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 10, 'Akasema: Mola wangu Mlezi nijaalie Ishara. Akasema: Ishara yako ni kuwa hutasema na watu kwa usiku tatu, na ilhali u mzima sawasawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 11, 'Basi akawatokea kaumu yake kutoka mihirabuni. Akawaashiria kwamba: Msabihini Mwenyezi Mungu asubuhi na jioni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 12, 'Ewe Yahya! Kishike Kitabu kwa nguvu! Nasi tulimpa hekima angali mtoto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 13, 'Na tukampa huruma itokayo kwetu, na utakaso, na akawa mcha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 14, 'Na akawa mwema kwa wazazi wake, wala hakuwa jabari muasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 15, 'Na salama iwe juu yake siku ya kuzaliwa, na siku ya kufa, na siku ya kufufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 16, 'Na mtaje Maryamu katika Kitabu, pale alipojitenga mbali na jamaa zake mahali upande wa mashariki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 17, 'Na akaweka pazia kujikinga nao. Basi tukamtumia Roho wetu, naye akajifananisha kwake sawa sawa na mtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 18, '(Maryamu) akasema: Hakika mimi ninajikinga kwa Mwingi wa rehema aniepushe nawe, ikiwa wewe ni mcha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 19, '(Malaika huyo) akasema: Hakika mimi ni mtume tu kutoka kwa Mola wako Mlezi ili nikutunuku mwana aliyetakasika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 20, 'Akasema: Nitampataje mwana ilhali mtu yeyote hajawahi kunigusa, wala sikuwahi kuwa kahaba?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 21, '(Malaika) akasema: Hivyo ndiyo alivyosema Mola wako Mlezi: Haya ni mepesi kwangu! Na ili tumfanye kuwa ni Ishara kwa watu, na rehema kutoka kwetu, na hilo ni jambo lililokwishahukumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 22, 'Basi akachukua mimba yake, na akaondoka nayo mpaka mahali pa mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 23, 'Kisha uchungu wa kuzaa ukamlazimu kwenda kwenye shina la mtende; akasema: Laiti ningelikufa kabla ya haya, na nikawa niliyesahaulika kabisa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 24, 'Kwa hivyo, akamnadi kutokea chini yake: Usihuzunike! Hakika Mola wako Mlezi ameshafanya chini yako kijito kidogo cha maji!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 25, 'Na litikise kwako hilo shina la mtende, utakuangushia tende nzuri zilizo mbivu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 26, 'Basi kula, na kunywa, na litulize jicho lako. Na pindi ukimwona mtu yeyote, basi sema: Hakika mimi nimeweka nadhiri kwa Mwingi wa rehema, ya kufunga; kwa hivyo leo sitasema na mtu yeyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 27, 'Basi akaenda naye (mwanawe) kwa jamaa zake amembeba. Wakasema: Ewe Maryamu! Hakika umeleta kitu cha ajabu sana!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 28, 'Ewe dada yake Harun! Baba yako hakuwa mtu mbaya, wala mama yako hakuwa kahaba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 29, 'Kwa hivyo, akamuashiria (mtoto). Wakasema: Vipi tumsemeshe aliye bado mtoto mdogo yumo katika mlezi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 30, '(Mtoto huyo) akasema: Hakika mimi ni mja wa Mwenyezi Mungu. Amenipa Kitabu, na amenifanya Nabii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 31, 'Na amenifanya ni mwenye kubarikiwa popote pale niwapo. Na ameniusia Swala na Zaka maadamu ni hai.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 32, 'Na nimtendee wema mama yangu. Wala hakunifanya niwe jeuri, mwovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 33, 'Na amani iko juu yangu siku niliyozaliwa, na siku nitakayokufa, na siku nitakayofufuliwa kuwa hai.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 34, 'Huyo ndiye Isa mwana wa Maryamu. Ndiyo kauli ya haki ambayo wanaifanyia shaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 35, 'Haiwi kwa Mwenyezi Mungu kujifanyia mwana, Subhanahu (Yeye ametakasika)! Anapolihukumia jambo, basi hakika huliambia tu: "Kuwa!" Na linakuwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 36, 'Na hakika Mwenyezi Mungu ndiye Mola wangu Mlezi, na Mola wenu Mlezi. Basi muabuduni Yeye. Hii ndiyo njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 37, 'Lakini makundi yakahitilafiana wao kwa wao. Basi ole wao hao waliokufuru kwa kuhudhuria Siku iliyo kuu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 38, 'Watasikia na wataona vizuri vilivyoje Siku watakayotujia! Lakini madhalimu sasa wamo katika upotovu ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 39, 'Na waonye siku ya majuto makubwa itapokatwa amri. Nao wako katika ghafla, wala hawaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 40, 'Hakika Sisi ndio tutairithi ardhi na wale walio juu yake. Na kwetu watarejeshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 41, 'Na mtaje katika Kitabu hiki Ibrahim. Hakika yeye alikuwa mkweli mno, na Nabii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 42, 'Alipomwambia baba yake: Ewe baba yangu! Kwa nini unaabudu visivyosikia, na visivyoona, na visivyokufaa chochote?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 43, 'Ewe baba yangu! Kwa yakini imenifikia elimu ambayo haikukujia wewe. Basi nifuate mimi, nami nitakuongoza njia iliyo sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 44, 'Ewe baba yangu! Usimuabudu Shetani. Hakika Shetani ni mwenye kumuasi sana Mwingi wa rehema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 45, 'Ewe baba yangu! Hakika mimi ninahofu ije kukupata adhabu inayotoka kwa Mwingi wa rehema, ukaja kuwa mwenziwe Shetani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 46, '(Baba) akasema: Je huitaki miungu yangu, ewe Ibrahim? Kama huachi, basi lazima nitakupiga mawe. Na niondokee mbali kwa muda mrefu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 47, '(Ibrahim) akasema: Salamun ''alaika (Amani iwe juu yako)! Mimi nitakuombea msamaha kwa Mola wangu Mlezi. Hakika Yeye ananihurumia sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 48, 'Nami ninajitenga mbali nanyi na hayo mnayoyaabudu badala ya Mwenyezi Mungu. Na ninamwomba Mola wangu Mlezi; asaa nisiwe mwenye kukosa bahati kwa kumwomba Mola wangu Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 49, 'Basi alipojitenga mbali nao na yale waliyokuwa wakiyaabudu badala ya Mwenyezi Mungu, tukamtunuku Is-haq na Yaaqub, na kila mmoja wao tukamfanya Nabii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 50, 'Na tukawatunuku katika rehema zetu na tukawafanya kupewa sifa za kweli tukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 51, 'Na mtaje Musa katika Kitabu. Hakika yeye alikuwa ni mwenye kuchaguliwa, na alikuwa Mtume, Nabii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 52, 'Na tulimwitia upande wa kulia wa mlima na tukamsogeza kunong''ona naye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 53, 'Nasi kwa rehema zetu tukamtunuku kakaye, Harun, awe Nabii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 54, 'Na mtaje katika Kitabu Ismail. Bila ya shaka yeye alikuwa ni mkweli wa ahadi, na alikuwa Mtume, Nabii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 55, 'Na alikuwa akiwaamrisha ahali zake Swala na Zaka, na alikuwa mbele ya Mola wake Mlezi mwenye kuridhiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 56, 'Na mtaje katika Kitabu Idris. Hakika yeye alikuwa ni mkweli mno, Nabii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 57, 'Na tulimuinua mahali pa juu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 58, 'Hao ndio aliowaneemesha Mwenyezi Mungu miongoni mwa Manabii katika uzao wa Adam, na katika uzao wa wale tuliowabeba pamoja na Nuhu, na katika uzao wa Ibrahim na Israili, na katika wale tuliowaongoa na tukawateua. Wanaposomewa Aya za Mwingi wa rehema, huanguka kusujudu na kulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 59, 'Lakini wakaja baada yao wafuatizi walioipoteza Swala, na wakafuata matamanio. Basi watakujakuta malipo ya ubaya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 60, 'Isipokuwa mwenye kutubu, akaamini, na akatenda mema. Hao basi, wataingia Bustanini wala hawatadhulumiwa chochote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 61, 'Bustani za milele ambazo aliwaahidi Rahmani (Mwingi wa rehema) waja wake katika ghaibu. Hakika Yeye ahadi yake hakuna shaka itafika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 62, 'Humo hawatasikia upuuzi wowote, isipokuwa salama tu. Na watapata humo riziki zao asubuhi na jioni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 63, 'Hiyo ndiyo Bustani tutakayowarithisha katika waja wetu wale waliokuwa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 64, 'Wala hatuteremki isipokuwa kwa amri ya Mola wako Mlezi. Ni yake Yeye yaliyoko mbele yetu na yaliyoko nyuma yetu, na yaliyomo katikati ya hayo. Na Mola wako Mlezi si mwenye kusahau.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 65, 'Mola Mlezi wa mbingu na ardhi na vilivyo kati yake. Basi muabudu Yeye tu, na usubiri katika kumuabudu. Je, unajua chochote kilicho sawa naye?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 66, 'Na mwanadamu husema: Hivyo, nitakapokufa, ni kweli nitafufuliwa niwe hai tena?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 67, 'Je, hakumbuki mwanadamu ya kwamba hakika tulimuumba kabla, na wala hakuwa chochote?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 68, 'Basi ninaapa kwa Mola wako Mlezi! Kwa yakini tutawakusanya wao pamoja na mashetani. Kisha tutawahudhurisha kuizunguka Jahannamu huku wamepiga magoti!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 69, 'Kisha kwa yakini tutaondoa katika kila kundi wale miongoni mwao waliozidi kumuasi Arrahmani (Mwingi wa rehema).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 70, 'Tena hakika Sisi tunawajua vyema zaidi wanaostahiki kuunguzwa humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 71, 'Wala hakuna yeyote katika nyinyi isipokuwa ataifikia. Hiyo ni hukumu ya Mola wako Mlezi ambayo lazima itimizwe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 72, 'Kisha tutawaokoa sawasawa wale waliomcha Mungu; na tutawaacha madhalimu humo huku wamepiga magoti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 73, 'Na wanaposomewa Aya zetu zilizo wazi, wale waliokufuru huwaambia wale walioamini: Ni lipi katika makundi mawili haya lenye cheo kizuri na lililo zuri zaidi barazani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 74, 'Na kaumu ngapi tuliziangamiza zilizokuwa na mapambo mazuri zaidi na wazuri zaidi katika muonekano!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 75, 'Sema: Yule aliye katika upotovu, basi Arrahmani (Mwingi wa rehema) na amuongezee (muda, mali na mengineyo) mpaka atakapoona yale waliyoahidiwa - ima ni adhabu au ni Saa, hapo ndipo watakapojua ni nani mwenye makao maovu zaidi na mwenye jeshi dhaifu zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 76, 'Na Mwenyezi Mungu huwazidishia wale walioongoka uongofu. Na mema yenye kubakia ni bora katika malipo mbele ya Mola wako Mlezi na yana marejeo mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 77, 'Je, umemwona aliyezikufuru Ishara zetu na akasema: Kwa hakika mimi nitapewa mali na wana!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 78, 'Kwani yeye amepata habari za ghaibu, au amechukua agano kwa Arrahmani (Mwingi wa rehema)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 79, 'Hasha! Tutaandika anayoyasema, na tutamuongezea sawasawa katika adhabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 80, 'Na tutamrithi hayo anayoyasema, na atatujia mtupu peke yake!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 81, 'Na walichukua miungu mingine badala ya Mwenyezi Mungu ili ati iwape nguvu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 82, 'Sivyo hivyo! Wataikataa hiyo ibada yao, na watakuwa ndio dhidi yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 83, 'Kwani huoni ya kwamba tuliwatuma mashetani kwa makafiri wawachochee sawasawa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 84, 'Basi usiwafanyie haraka. Sisi tunawahesabia idadi ya siku zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 85, 'Siku tutakayowakusanya wacha Mungu kuwapeleka kwa Arrahmani (Mwingi wa rehema) kuwa ni wageni wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 86, 'Na tukawaswaga wahalifu kwenda katika Jahannamu hali ya kuwa wana kiu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 87, 'Hawatakuwa na mamlaka ya uombezi isipokuwa yule aliyechukua ahadi kwa Arrahmani (Mwingi wa rehema).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 88, 'Na wao ati walisema kuwa Arrahmani (Mwingi wa rehema) alijifanyia mwana!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 89, 'Hakika mmeleta jambo la kuchusha mno!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 90, 'Zinakaribia mbingu kulipuka kwa hilo, na ardhi kupasuka, na milima kuanguka vipande vipande.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 91, 'Kwa kudai kwao kuwa Arrahmani (Mwingi wa rehema) ana mwana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 92, 'Wala Arrahmani (Mwingi wa rehema) hafailii kujichukulia mwana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 93, 'Hakuna yeyote aliyemo mbinguni na ardhini isipokuwa atamjia Arrahmani (Mwingi wa rehema) kuwa ni mja wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 94, 'Yeye hakika amewadhibiti na amewahesabu sawasawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 95, 'Na kila mmoja wao atamjia Siku ya Kiyama peke yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 96, 'Hakika wale walioamini na wakatenda mema, Arrahmani (Mwingi wa rehema) atawafanyia mapenzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 97, 'Na hakika tumeifanya nyepesi (Qur''ani) kwa ulimi wako, ili uwabashirie kwayo wacha Mungu, na uwaonye kwayo kaumu wagumu mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 98, 'Na kaumu ngapi tuliziangamiza kabla yao. Je, unamuona hata mmoja katika wao au unasikia hata mnong''ono wao?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 1, 'Twa Ha![1]', '[1] Herufi hizi "Twa Ha" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 2, 'Hatukukuteremshia Qur-ani ili upate mashaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 3, 'Bali ni ukumbusho kwa mwenye kunyenyekea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 4, 'Ni uteremsho kutoka kwa aliyeumba ardhi na mbingu zilizo juu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 5, 'Arrahmani (Mwingi wa rehema), aliyeinuka juu ya Kiti cha Enzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 6, 'Ni vyake vyote vilivyo katika mbingu na vilivyo katika ardhi, na vilivyo baina yake, na vilivyo chini ya ardhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 7, 'Na ukinyanyua sauti kwa kusema, basi hakika Yeye anajua siri na chini zaidi kuliko siri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 8, 'Mwenyezi Mungu! Hakuna mungu yeyote isipokuwa Yeye. Yeye ana majina mazuri zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 9, 'Na je, imekufikia hadithi ya Musa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 10, 'Alipouona moto, kwa hivyo akawaambia ahali zake: Ngojeni! Hakika mimi nimeuona moto, huenda nikawaletea kijinga kutoka humo, au nikapata uongofu kwenye moto huo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 11, 'Basi alipoufikia, akaitwa: Ewe Musa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 12, 'Hakika Mimi ndiye Mola wako Mlezi! Basi vua viatu vyako. Kwani uko katika bonde takatifu la ''Tuwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 13, 'Nami nimekuteua wewe; basi sikiliza yanayofunuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 14, 'Hakika Mimi ndiye Mwenyezi Mungu. Hakuna mungu isipokuwa Mimi tu. Basi niabudu Mimi, na udumishe Swala kwa ajili ya kunikumbuka Mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 15, 'Hakika Saa itakuja bila ya shaka. Nimekaribia mno kuificha, ili kila nafsi ilipwe kwa iliyoyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 16, 'Kwa hivyo, kamwe asikuzuilie nayo yule ambaye haiamini na akafuata matamanio yake ukaja kuangamia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 17, 'Na nini hicho kilichomo mkononi mwako wa kulia, ewe Musa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 18, 'Akasema: Hii ni fimbo yangu; ninaiegemea na ninawaangushia majani kwayo kondoo na mbuzi wangu. Tena inanifaa kwa matumizi mengine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 19, 'Akasema: Itupe, ewe Musa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 20, 'Akaitupa. Mara ikawa nyoka anayekwenda mbio.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 21, 'Akasema: Ikamate, wala usiogope! Tutairudisha hali yake ya kwanza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 22, 'Na uambatishe mkono wako kwenye ubavu, utatoka mweupe pasipo na madhara yoyote. Hiyo ni ishara nyingine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 23, 'Ili tukuonyeshe katika ishara zetu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 24, 'Nenda kwa Firauni. Hakika yeye amepindukia mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 25, '(Musa) akasema: Ewe Mola wangu Mlezi! Nikunjulie kifua changu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 26, 'Na nirahisishie kazi yangu hii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 27, 'Na lifungue fundo lililo katika ulimi wangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 28, 'Wapate kufahamu maneno yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 29, 'Na nipe msaidizi katika ahali zangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 30, 'Harun, kaka yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 31, 'Kwake yeye niongeze nguvu zangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 32, 'Na mshirikishe katika jambo langu hili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 33, 'Ili tukutakase kwa wingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 34, 'Na tukutaje kwa wingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 35, 'Hakika Wewe unatuona vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 36, 'Akasema: Hakika Umeshapewa maombi yako, ewe Musa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 37, 'Na hakika tulikwishakufanyia hisani mara nyingine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 38, 'Pale tulipomfunulia mama yako yaliyofunuliwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 39, 'Ya kuwa mtie katika kisanduku, na kisha kitie mtoni, na mto utamfikisha ufukweni. Atamchukua adui yangu naye ni adui yake. Na nimekutilia mapenzi yanayotoka kwangu, na ili ulelewe machoni mwangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 40, 'Dada yako alipokwenda na akasema: Je! Niwajulishe mtu wa kuweza kumlea? Basi tukakurejesha kwa mama yako ili macho yake yaburudike, wala asihuzunike. Na ulimuua mtu, nasi tukakuokoa katika dhiki, na tukakujaribu kwa majaribio mengi. Ukakaa miaka kwa watu wa Madyana. Kisha ukaja kama ilivyokadiriwa, ewe Musa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 41, 'Na nimekuteua kwa ajili ya nafsi yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 42, 'Nenda, wewe na ndugu yako, pamoja na ishara zangu, wala msichoke kunikumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 43, 'Nendeni kwa Firauni. Hakika yeye amepindukia mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 44, 'Mwambieni maneno laini, huenda akazingatia au akaogopa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 45, 'Wakasema: Ewe Mola wetu Mlezi! Hakika sisi tunaogopa asije akapindukia mipaka juu yetu au kufanya jeuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 46, 'Akasema: Msiogope! Hakika Mimi ni pamoja nanyi. Nasikia na ninaona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 47, 'Basi mwendeeni, na mwambieni: Hakika sisi ni Mitume wa Mola wako Mlezi! Basi waache Wana wa Israili watoke nasi, wala usiwaadhibu. Sisi tumekuletea ishara itokayo kwa Mola wako Mlezi. Na amani iwe juu ya atakayefuata uongofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 48, 'Hakika tumefunuliwa sisi kwamba hakuna shaka adhabu itampata anayekadhibisha na akapuuza', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 49, '(Firauni) akasema: Basi Mola wenu Mlezi ni nani, ewe Musa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 50, 'Akasema: Mola wetu Mlezi ni yule aliyekipa kila kitu umbo lake, kisha akakiongoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 51, 'Akasema: Nini hali ya karne za kwanza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 52, 'Akasema: Elimu yake iko kwa Mola wangu Mlezi katika Kitabu. Mola wangu Mlezi hapotei wala hasahau.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 53, 'Ambaye amewafanyia ardhi kuwa tandiko, na akawapitishia humo njia, na akawateremshia kutoka mbinguni maji. Na kwa hayo tukatoa namna mbalimbali za mimea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 54, 'Kuleni, na mchunge wanyama wenu. Hakika katika hayo zipo ishara kwa wenye akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 55, 'Tumewaumba kutokana nayo (ardhi), na humo tutawarudisha, na tutawatoa kutoka humo mara nyengine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 56, 'Na hakika tulimwonyesha ishara zetu zote. Lakini alikadhibisha na akakataa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 57, 'Akasema: Ewe Musa! Hivyo umetujia kututoa katika nchi yetu kwa uchawi wako?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 58, 'Basi sisi hakika tutakuletea uchawi kama huo. Basi weka miadi baina yetu na wewe, ambayo tusiivunje sisi wala wewe, mahali patakapokuwa sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 59, 'Akasema: Miadi yenu ni siku ya Sikukuu ya mapambo; na watu wakusanywe kabla ya adhuhuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 60, 'Basi Firauni akageuka akarudi, na akatengeneza hila yake, kisha akaja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 61, 'Musa akawaambia: Ole wenu! Msimzulie Mwenyezi Mungu uongo, akaja kuwafutilia mbali kwa adhabu. Na hakika mwenye kuzua lazima ashindwe!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 62, 'Basi wakazozana wenyewe kwa wenyewe kuhusiana na jambo lao hilo, na wakanong''ona kwa siri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 63, 'Wakasema: Hakika hawa wawili ni wachawi, wanataka kuwatoa katika nchi yenu kwa uchawi wao, na waondoe mila zenu zilizo bora kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 64, 'Kwa hivyo kusanyeni hila zenu zote, kisha mfike kwa kujipanga safu, na kwa yakini atafuzu kweli kweli leo atakayeshinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 65, 'Wakasema: Ewe Musa! Ima utupe wewe, au tuwe sisi ndio wa kwanza wa kutupa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 66, 'Akasema: Bali tupeni nyinyi! Tahamaki! Kamba zao na fimbo zao zikaonekana mbele yake, kwa uchawi wao, kuwa zinakwenda mbio.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 67, 'Basi Musa akaingia hofu katika nafsi yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 68, 'Tukasema: Usihofu! Hakika wewe ndiye utakayeshinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 69, 'Na kitupe kilicho katika mkono wako wa kulia; kitavimeza walivyoviunda. Hakika walivyounda ni hila za mchawi tu, na mchawi hafanikiwi popote afikapo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 70, 'Basi wachawi hao wakaangushwa chini wakasujudu. Wakasema: Tumemuamini Mola Mlezi wa Harun na Musa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 71, '(Firauni) akasema: Oh! Mmemuamini kabla ya mimi kuwapa ruhusa? Hakika yeye ndiye mkubwa wenu aliyewafundisha uchawi huu. Basi kwa yakini nitawakatakata mikono yenu na miguu yenu kwa kutofautisha. Na lazima nitawatundika misalabani katika vigogo vya mitende, na hapo kwa yakini mtajua ni nani katika sisi ndiye mkali zaidi wa kuadhibu na kuiendeleza zaidi adhabu yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 72, 'Wakasema: Hatutakupendelea wewe kuliko ishara waziwazi zilizotujia, na kuliko yule aliyetuumba. Basi hukumu utavyohukumu; kwani wewe hakika unahukumu tu haya ya maisha ya duniani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 73, 'Hakika sisi tumemuamini Mola wetu Mlezi ili atusamehe makosa yetu na uchawi uliotulazimisha kuufanya. Na Mwenyezi Mungu ndiye Mbora na Mwenye kudumu zaidi (katika kuadhibu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 74, 'Hakika atakayemjia Mola wake Mlezi naye ni mhalifu, basi kwa yakini, yake huyo ni Jahannamu. Hafi humo wala haishi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 75, 'Na anayemjia Yeye naye ni Muumini na akatenda mema, basi hao watakuwa na daraja za juu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 76, 'Bustani za milele zipitazo mito kati yake, wadumu humo. Na hayo ndiyo malipo ya mwenye kujitakasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 77, 'Na tulimfunulia Musa: Toka usiku na waja wangu, na uwapigie njia kavu baharini. Usihofu kukamatwa, wala usiogope.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 78, 'Firauni akawafuata pamoja na majeshi yake. Basi kikawafudikiza humo baharini kilichowafudikiza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 79, 'Na Firauni aliwapoteza watu wake wala hakuwaongoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 80, 'Enyi Wana wa Israili! Hakika tuliwaokoa kutokana na adui yenu, na tukawaahidi upande wa kulia wa mlima na tukawateremshia Manna na Salwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 81, 'Kuleni katika vitu vizuri hivyo tulivyowaruzuku, wala msiruke mipaka katika hayo, isije ikawashukia ghadhabu yangu. Na yule inayemshukia ghadhabu yangu basi huyo ameangamia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 82, 'Na hakika Mimi ni Mwingi wa kusamehe kwa anayetubia, na akaamini, na akatenda mema, kisha akaongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 83, 'Na nini kilichokutia haraka ukawaacha watu wako, ewe Musa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 84, 'Akasema: Hao wapo nyuma yangu wananifuata. Na nimefanya haraka kukujia, Mola wangu Mlezi, ili uridhike.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 85, '(Mwenyezi Mungu) akasema: Sisi tumewatia mtihani watu wako baada yako, na Msamaria amewapoteza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 86, 'Basi Musa akarudi kwa watu wake kwa ghadhabu na kusikitika. Akasema: Enyi watu wangu! Kwani Mola wenu Mlezi hakuwaahidi ahadi nzuri? Je, umekuwa muda mrefu kwenu au mmetaka ghadhabu ya Mola wenu Mlezi iwashukie, ndiyo maana mkavunja miadi yangu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 87, 'Wakasema: Sisi hatukuvunja miadi yako kwa hiari yetu, lakini tulibebeshwa mizigo ya mapambo ya watu, basi tukaitupa. Na hivyo ndivyo alivyotupa yule Msamaria.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 88, 'Na akawaundia ndama, kiwiliwili chenye sauti. Na wakasema: Huyu ndiye mungu wenu, na mungu wa Musa, lakini alisahau.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 89, 'Je, hawakuona kuwa hakuwarudishia neno, wala kuwamilikia kudhuru wala kufaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 90, 'Na hakika Harun alikwishawaambia kabla yake: Enyi watu wangu! Hakika nyinyi mmetiwa mtihanini tu kwa kitu hiki. Na kwa yakini Mola wenu Mlezi ni Arrahmani (Mwingi wa rehema). Basi nifuateni mimi, na tiini amri yangu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 91, 'Wakasema: Hatutaacha kumwabudu mpaka Musa atakaporejea kwetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 92, '(Musa) akasema: Ewe Harun! Ni nini kilichokuzuia, ulipowaona wamepotea?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 93, 'Usinifuate. Je, umeasi amri yangu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 94, 'Akasema: Ewe mwana wa mama yangu! Usinishike ndevu zangu, wala kichwa changu. Kwa hakika naliogopa usijesema: Umewatenganisha Wana wa Israili, na hukungojea kauli yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 95, '(Musa) akasema: Ewe Msamaria! Unataka nini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 96, 'Akasema: Niliona wasiyoyaona wao, nikachukua mkamato wa mkono katika athari za unyayo wa Mtume. Kisha nikaitupa. Na hivi ndivyo ilivyonielekeza nafsi yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 97, '(Musa) akasema: Basi ondoka! Na kwa yakini utakuwa katika maisha ukisema: Usiniguse. Na hakika una ahadi kwako isiyovunjwa. Na mtazame huyo mungu wako uliyeendelea kumuabudu. Sisi kwa hakika tutamchoma moto, kisha tutamtawanya sawasawa baharini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 98, 'Hakika mungu wenu ni Allah (Mwenyezi Mungu) tu. Hakuna mungu isipokuwa Yeye. Amekienea kila kitu kwa elimu yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 99, 'Namna hivi tunakuhadithia katika khabari za yaliyotangulia. Na hakika tumekuletea kutoka kwetu mawaidha ya kukumbukwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 100, 'Atakayeyapa mgongo, basi kwa yakini Siku ya Kiyama atabeba mzigo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 101, 'Wadumu humo. Na ni mzigo muovu kwao kuubeba Siku ya Kiyama!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 102, 'Siku litakapopulizwa barugumu, na tukawakusanya wahalifu Siku hiyo, hali macho yao ni ya buluu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 103, 'Watanong''onezana wao kwa wao: Hamkukaa ila siku kumi tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 104, 'Sisi tunajua zaidi watakayoyasema, atakaposema mbora wao katika mwendo: Nyinyi hamkukaa ila siku moja tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 105, 'Na wanakuuliza habari za milima. Waambie: Mola wangu Mlezi ataivurugavuruga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 106, 'Na ataiacha tambarare, uwanda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 107, 'Hutaona humo mdidimio wowote wala muinuko.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 108, 'Siku hiyo watamfuata muitaji huyo bila ya yeyote kumkengeuka. Na sauti zote zitamnyenyekea Arrahmani (Mwingi wa rehema). Basi hutasikia ila mnong''ono tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 109, 'Siku hiyo uombezi hautafaa kitu, ila kwa atakayeruhusiwa na Arrahmani (Mwingi wa rehema) na akaridhia na maneno yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 110, 'Yeye anajua yaliyo mbele yao, na yaliyo nyuma yao. Wala wao hawawezi kumjua Yeye vilivyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 111, 'Na zitadhalilika nyuso mbele ya Aliye Hai milele, Msimamia yote milele. Na atakuwa ameharibikiwa mwenye kubeba dhuluma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 112, 'Na anayetenda katika mema, naye ni Muumini, basi hatahofu kudhulumiwa wala kupunjwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 113, 'Na namna hivi tumeiteremsha Qur-ani kwa Kiarabu, na tumekariri humo vitisho ili wapate kuogopa na kujilinda na iwaletee makumbusho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 114, 'Basi ametukuka Mwenyezi Mungu, Mfalme wa Haki. Wala usiifanyie haraka hii Qur-ani, kabla haujamalizika ufunuo wake. Na sema: Mola wangu Mlezi! Nizidishie elimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 115, 'Na hapo zamani tuliagana na Adam, lakini alisahau, wala hatukupata kwake azimio kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 116, 'Na tulipowaambia Malaika: Msujudieni Adam! Wakasujudu, isipokuwa Iblisi, alikataa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 117, 'Tukasema: Ewe Adam! Hakika huyu ni adui yako na wa mkeo. Basi asiwatoe katika Bustani hii, mkaingia mashakani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 118, 'Hakika humo hutakuwa na njaa wala hutakuwa uchi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 119, 'Na hakika hutapata kiu humo wala hutapata joto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 120, 'Lakini Shetani alimtia wasiwasi, akamwambia: Ewe Adam! Nikujulishe mti wa kuishi maisha ya milele na ufalme usiokoma?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 121, 'Basi wakaula wote wawili, na uchi wao ukawadhihirikia na wakaanza kujibandika majani ya Bustanini. Na Adam akamuasi Mola wake Mlezi, na akapotea njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 122, 'Kisha Mola wake Mlezi akamteua, na akamkubalia toba yake, na akamwongoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 123, 'Akasema: Ondokeni humo nyote, hali ya kuwa ni maadui nyinyi kwa nyinyi. Na ukiwafikia uongofu kutoka kwangu basi atakayeufuata uongofu wangu, hatapotea wala hatataabika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 124, 'Na atakayeupa ukumbusho wangu mgongo, basi kwa yakini atapata maisha yenye dhiki, na Siku ya Kiyama tutamfufua hali ya kuwa ni kipofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 125, 'Aseme: Ewe Mola wangu Mlezi! Mbona umenifufua kipofu, nami nilikuwa nikiona vyema?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 126, '(Mwenyezi Mungu) atasema: Ndivyo hivyo. Zilikufikia ishara zetu, nawe ukazisahau; na vivyo hivyo leo utasahauliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 127, 'Na hivyo ndivyo tutakavyomlipa kila apitaye kiasi, na asiziamini ishara za Mola wake Mlezi. Na hakika adhabu ya Akhera ni kali zaidi, na inadumu zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 128, 'Je, haikuwabainikia ni ngapi katika vizazi tuliviangamiza kabla yao, nao wanatembea katika maskani zao? Hakika katika hayo zimo ishara kwa wenye akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 129, 'Na lau kuwa si neno lililokwishatangulia kutoka kwa Mola wako Mlezi na muda uliowekwa, bila ya shaka ingefika adhabu (duniani).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 130, 'Basi yavumilie haya wayasemayo. Na umtakase Mola wako Mlezi kwa kumsifu kabla ya kuchomoza jua, na kabla ya kuzama kwake, na nyakati za usiku pia umtakase, na nyakati za mwisho za mchana ili upate ya kukuridhisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 131, 'Wala kamwe usivikodolee macho tulivyowastarehesha kwavyo baadhi ya watu miongoni mwao, kwa ajili ya mapambo ya duniani, ili tuwajaribu katika hivyo. Na riziki ya Mola wako Mlezi ni bora na yenye kudumu zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 132, 'Na waamrishe ahali zako kuswali, na usubiri juu yake. Sisi hatukuombi wewe riziki, bali Sisi ndio tunakuruzuku. Na mwisho mwema ni kwa ucha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 133, 'Na walisema: "Kwa nini hakutuletea muujiza kutoka kwa Mola wake Mlezi?" Je, haukuwajia ushahidi wazi wa yaliyo katika Vitabu vya mwanzo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 134, 'Na lau kuwa tuliwaangamiza kwa adhabu kabla yake, wangelisema: Ewe Mola wetu Mlezi! Kama ungetuletea Mtume (ingekuwa bora), tukazifuata ishara zako kabla ya kudhalilika na kuhizika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 135, 'Sema: Kila mmoja anangoja. Basi ngojeni! Hivi karibuni mtajua ni akina nani ndio wenye njia sawa na ni nani aliyeongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 1, 'Imewakaribia watu hesabu yao, nao wako katika kughafilika wanapuuza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 2, 'Hauwajii ukumbusho mpya kutoka kwa Mola wao Mlezi isipokuwa huusikiliza na huku wanafanya mchezo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 3, 'Zimeghafilika nyoyo zao. Na wale waliodhulumu hunong''onezana kwa siri: Ni nani huyu isipokuwa ni mtu tu kama nyinyi! Je, mnauendea uchawi ilhali nyinyi mnaona?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 4, 'Alisema: Mola wangu Mlezi anayajua yasemwayo mbinguni na katika ardhi. Na Yeye ni Mwenye kusikia yote, Mwenye kujua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 5, 'Lakini wao walisema: "Hizo ni ndoto za ovyo ovyo, bali amezizua tu, bali huyo ni mtunga mashairi. Basi atuletee miujiza kama walivyotumwa wale wa mwanzo."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 6, 'Hawakuamini kabla yao watu wa mji wowote tuliouangamiza. Basi, je, hawa ndio wataamini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 7, 'Na hatukuwatuma kabla yako isipokuwa wanaume tuliowafunulia ufunuo (wahyi). Basi waulizeni wenye elimu ikiwa nyinyi hamjui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 8, 'Wala hatukuwafanya miili isiyokula chakula, wala hawakuwa wenye kuishi milele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 9, 'Kisha tukawatimizia miadi, na tukawaokoa wao na wale tuliowataka, na tukawaangamiza wale waliopitiliza mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 10, 'Na hakika tumewateremshia Kitabu ambacho ndani yake kuna ukumbusho wenu. Je, hamtumii akili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 11, 'Na ni mingapi katika miji iliyokuwa ikidhulumu tumeiteketeza, na tukawaanzisha baada yao kaumu wengine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 12, 'Basi walipoihisi adhabu yetu, tazama, wakaanza kuikimbia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 13, 'Msikimbie! Na rejeeni kwenye yale yale mliyostareheshwa kwayo, na maskani zenu, ili mpate kuulizwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 14, 'Wakasema: "Ole wetu! Hakika sisi tulikuwa madhalimu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 15, 'Basi hakikuacha hicho kuwa ndicho kilio chao mpaka tukawafanya kama waliofyekwa, wamezimika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 16, 'Na hatukuziumba mbingu na ardhi na vilivyo baina ya hivyo kwa mchezo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 17, 'Kama tungelitaka kufanya pumbao, tungejifanyia Sisi wenyewe, lau kwamba tungelikuwa ni wafanyao hivyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 18, 'Bali tunaitupa haki juu ya batili, ikaivunja na mara ikatoweka. Na ole wenu kwa mnayoyazua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 19, 'Na ni vyake Yeye tu vilivyomo mbinguni na katika ardhi. Na wale walioko kwake hawafanyi kiburi wakaacha kumuabudu, wala hawachoki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 20, 'Wanamtakasa usiku na mchana, wala hawanyong''onyei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 21, 'Au wamejifanyia miungu katika ardhi inayofufua?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 22, 'Lau wangelikuwamo humo miungu wengine isipokuwa Mwenyezi Mungu, basi bila ya shaka hizo mbingu na ardhi zingeliharibika. Subhanallah (Ametakasika Mwenyezi Mungu), Bwana wa Kiti cha Enzi mbali na hayo wanayoyazua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 23, 'Yeye haulizwi kwa ayatendayo, na wao ndio wanaoulizwa kwa wayatendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 24, 'Au wamejifanyia miungu mingine badala yake? Sema: Leteni ushahidi wenu! Haya ni ukumbusho wa hawa walio pamoja nami, na ukumbusho wa walio kabla yangu. Lakini wengi wao hawaijui haki, na kwa hivyo wanapeana mgongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 25, 'Na hatukumtuma kabla yako Mtume yeyote isipokuwa tulimfunulia ya kwamba hakuna mungu isipokuwa Mimi. Basi niabuduni Mimi tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 26, 'Na walisema: Arrahman (Mwingi wa rehema) alijifanyia mwana! Subhanahu (Ametakasika mbali na hayo!) Bali hao (wanaowaita wana) ni waja waliotukuzwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 27, 'Hawamtangulii kwa neno, nao wanafanya amri zake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 28, 'Anayajua yaliyo mbele yao na yaliyo nyuma yao. Wala hawamfanyii yeyote uombezi isipokuwa yule anayemridhia Yeye, nao kwa sababu ya kumhofu wanaogopa mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 29, 'Na yeyote kati yao atakayesema: "Hakika mimi ni mungu, badala yake", basi huyo tutamlipa Jahannamu. Hivyo ndivyo tuwalipavyo madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 30, 'Je, hao waliokufuru hawakuona kwamba mbingu na ardhi zilikuwa zimeambatana, kisha Sisi tukazibandua? Na tukafanya kwa maji kila kilicho hai? Basi je, hawaamini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 31, 'Na tukaweka katika ardhi milima iliyo thabiti ili isiwayumbishe, na tukaweka humo njia pana ili wapate kuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 32, 'Na tukaifanya mbingu kuwa dari iliyohifadhiwa, lakini wanazipuuza Ishara zake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 33, 'Na Yeye ndiye aliyeumba usiku na mchana na jua na mwezi, vyote katika anga vinaogelea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 34, 'Nasi hatukumfanya mwanadamu yeyote kabla yako kuwa na uhai wa milele. Basi je, ukifa wewe, wao wataishi milele?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 35, 'Kila nafsi itaonja mauti; na tunawajaribu kwa mtihani wa maovu na heri. Na kwetu Sisi mtarejeshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 36, 'Na wanapokuona wale waliokufuru, hawakufanyi wewe isipokuwa ni kitu cha masihara tu, (wakisema): Je, huyu ndiye anayeitaja miungu yenu? Na hali wao wanakufuru kumkumbuka Arrahman (Mwingi wa rehema)!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 37, 'Mwanadamu ameumbwa na haraka. Nitawaonyesha Ishara zangu. Basi msiniharakishe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 38, 'Na wanasema: Ahadi hii itatokea lini, ikiwa nyinyi ni wakweli?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 39, 'Lau wangelijua wale waliokufuru wakati ambao hawatauzuia Moto kwenye nyuso zao wala migongo yao, na wala hawatanusuriwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 40, 'Bali itawafikia kwa ghafla, na itawashitua na wala hawataweza kuirudisha, wala hawatapewa muhula!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 41, 'Na Mitume walio kabla yako walikwishadhihakiwa. Kwa hivyo wale waliowafanyia masihara yaliwafika yale waliyokuwa wakiyafanyia dhihaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 42, 'Sema: Ni nani anayewalinda usiku na mchana mbali na Arrahmani (Mwingi wa rehema)? Bali wao wanapuuza kumkumbuka Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 43, 'Au wao wanao miungu watakaoweza kuwakinga kutokana nasi? Hao hawawezi kujinusuru wao wenyewe, wala hawatalindwa kutokana nasi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 44, 'Bali tuliwastarehesha hawa na baba zao mpaka umri ukawa mrefu kwao. Je, hawaoni ya kwamba Sisi tunaijia ardhi tukiipunguza kutokea kwenye ncha zake? Basi je, hao ndio watashinda?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 45, 'Sema: Mimi ninawaonya kwa ufunuo (wahyi). Na viziwi hawasikii wito wanapoonywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 46, 'Na wanapoguswa na mpulizo mmoja tu wa adhabu itokayo kwa Mola wako Mlezi, bila ya shaka wao husema: Ole wetu! Hakika tulikuwa wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 47, 'Nasi tutaweka mizani za uadilifu kwa Siku ya Kiyama. Basi nafsi haitadhulumiwa kitu chochote. Hata ikiwa ni uzito wa chembe ya khardali, tutaileta. Nasi tunatosha kuwa wenye kufanya hisabu sawasawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 48, 'Na kwa yakini tuliwapa Musa na Harun kipambanuzi, na mwangaza, na makumbusho kwa wacha Mungu,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 49, 'Ambao wanamhofu Mola wao Mlezi faraghani, na wanaiogopa Saa ya Kiyama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 50, 'Na haya ni makumbusho yaliyobarikiwa, tuliyoyateremsha. Basi je! Mnayakataa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 51, 'Na hakika tulikwishampa Ibrahim uongofu wake zamani, na tulikuwa tunamjua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 52, 'Alipomwambia baba yake na watu wake: Ni nini haya masanamu mnayoshughulika kuyaabudu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 53, 'Wakasema: Tuliwakuta baba zetu wakiyaabudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 54, 'Akasema: Bila ya shaka nyinyi na baba zenu mmekuwa katika upotovu ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 55, 'Wakasema: Je, umetujia kwa maneno ya kweli au wewe ni katika wachezao tu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 56, 'Akasema: Bali Mola wenu Mlezi ni Mola Mlezi wa mbingu na ardhi ambaye ndiye aliyeziumba. Na mimi ni katika wenye kuyashuhudia hayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 57, 'Na ninaapa kwa Mwenyezi Mungu! Nitayafanyia vitimbi masanamu yenu haya baada ya mkishageuka kwenda zenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 58, 'Basi akayavunja vipande vipande, ila kubwa lao, ili wao walirudie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 59, 'Wakasema: Ni nani aliyeifanyia haya miungu yetu? Hakika yeye ni katika waliodhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 60, 'Wakasema: Tumemsikia kijana mmoja akiwataja. Anaitwa Ibrahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 61, 'Wakasema: Mleteni mbele ya macho ya watu, ili wapate kumshuhudia!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 62, 'Wakasema: Je! Wewe umeifanyia haya miungu yetu, ewe Ibrahim?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 63, 'Akasema: Bali amefanya hayo huyu mkubwa wao. Basi waulizeni ikiwa wanaweza kutamka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 64, 'Basi wakajirudia, wakasema: Hakika nyinyi mlikuwa madhalimu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 65, 'Kisha wakarejea kwenye ule ule upotovu wao wakasema: Hakika wewe unajua kwamba hawa hawasemi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 66, 'Akasema: Basi nyinyi mnawaabudu wasiokuwa Mwenyezi Mungu wasiowafaa kitu wala kuwadhuru?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 67, 'Aibu yenu nyinyi na hivyo mnavyoviabudu badala ya Mwenyezi Mungu! Basi nyinyi hamtii akilini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 68, 'Wakasema: Mchomeni moto, na muinusuru miungu yenu, ikiwa nyinyi ni watendao jambo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 69, 'Sisi tukasema: Ewe moto! Kuwa baridi na salama kwa Ibrahim!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 70, 'Wao walimkusudia maovu, lakini Sisi tukawafanya wao ndio waliohasiri zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 71, 'Na tukamwokoa yeye na Luuti, tukawapeleka kwenye nchi tuliyoibariki kwa ajili ya walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 72, 'Naye tukampa Is-haq, na Yaaqub kuwa ni ziada. Na wote tukawafanya kuwa watu wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 73, 'Na tukawafanya maimamu wakiongoa watu kwa amri yetu. Na tukawafunulia watende heri, na washike Sala, na watoe Zaka; na walikuwa wanatuabudu Sisi tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 74, 'Na Lut tukampa hukumu na elimu na tukamwokoa kutokana na ule mji uliokuwa ukifanya machafu. Hakika hao walikuwa watu wabaya, wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 75, 'Na tukamuingiza katika rehema yetu. Hakika yeye ni miongoni mwa walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 76, 'Na Nuhu alipoita zamani, nasi tukamuitikia, na tukamwokoa yeye na watu wake kutokana na shida kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 77, 'Na tukamnusuru kutokana na watu waliozikanusha Ishara zetu. Hakika hao walikuwa watu wabaya. Basi tukawazamisha wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 78, 'Na Daud na Suleiman walipokata hukumu katika suala la konde walipolisha humo mbuzi wa watu usiku. Na Sisi tulikuwa wenye kushuhudia hukumu yao hiyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 79, 'Basi tukamfahamisha Suleiman. Na kila mmoja wao tulimpa hukumu na elimu. Na tuliifanya milima na ndege kuwa pamoja na Daud imnyenyekee na imtakase Mwenyezi Mungu. Na Sisi ndio tulioyafanya hayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 80, 'Na tukamfundisha kuunda mavazi ya vita kwa ajili yenu ili yawahifadhi katika kupigana kwenu. Je, mtakuwa wenye kushukuru?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 81, 'Na tukamsahilishia Suleiman upepo wa kimbunga uendao kwa amri yake kwenye ardhi tuliyoibariki. Na Sisi ndio tunaojua kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 82, 'Na pia mashetani wanaompigia mbizi na kufanya kazi nyenginezo. Na Sisi tulikuwa walinzi wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 83, 'Na Ayyubu, alipomwita Mola wake Mlezi, akasema: Mimi yamenipata madhara. Na Wewe ndiye unayerehemu kuliko wote wanaorehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 84, 'Basi tukamwitikia, na tukamwondolea madhara aliyokuwa nayo, na tukampa watu wake na mfano wao pamoja nao kuwa ni rehema inayotoka kwetu, na ukumbusho kwa wafanyao ibada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 85, 'Na Ismail, na Idris, na Dhulkifli, wote walikuwa miongoni mwa wanaosubiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 86, 'Na tukawaingiza katika rehema yetu. Hakika wao walikuwa katika watu wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 87, 'Na Dhun-Nun alipoondoka hali ameghadhabika, na akadhani ya kwamba hatutamtia dhikini. Basi aliita katika giza: Hakuna mungu isipokuwa Wewe Subhanaka (Uliyetakasika). Hakika mimi nilikuwa miongoni mwa wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 88, 'Basi tukamwitikia na tukamwokoa kutokana na dhiki. Na hivyo ndivyo tunavyowaokoa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 89, 'Na Zakariya alipomwita Mola wake Mlezi: Mola wangu Mlezi! Usiniache peke yangu, na Wewe ndiye Mbora wa wanaorithi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 90, 'Basi tukamwitikia, na tukampa Yahya na tukamponyeshea mkewe. Hakika wao walikuwa wepesi wa kutenda mema, na wakituomba kwa shauku na hofu. Nao walikuwa wakitunyenyekea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 91, 'Na yule mwanamke aliyeulinda uke wake, na tukampulizia katika roho yetu, na tukamfanya yeye na mwanawe kuwa ni Ishara kwa walimwengu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 92, 'Kwa hakika huu umma wenu ni umma mmoja, na Mimi ni Mola wenu Mlezi. Kwa hivyo niabuduni Mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 93, 'Nao wakalikata jambo lao hili mapande mapande baina yao. Wote watarudi kwetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 94, 'Na atendaye mema naye ni Muumini, basi haitakataliwa juhudi yake. Na hakika Sisi tunamwandikia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 95, 'Na haiwi kwa wana mji tuliouangamiza, ya kwamba hawatarejea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 96, 'Mpaka watakapofunguliwa Yaajuju na Maajuju wakawa wanateremka haraka kutoka kwenye kila kilima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 97, 'Na Miadi ya haki ikakaribia. Hapo ndipo yatakapokodoka macho ya waliokufuru (na watasema): Ole wetu! Bila ya shaka tulikuwa tumeghafilika mbali na haya, bali tulikuwa wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 98, 'Hakika nyinyi na hao mnaowaabudu badala ya Mwenyezi Mungu ni kuni za Jahannamu; huko mtaingia tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 99, 'Lau kuwa hawa ni miungu, wasingelingia humo. Na wote watadumu humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 100, 'Lao wao humo ni kupiga mayowe, na wala hawatasikia (jinginelo).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 101, 'Ama wale ambao wema wetu umewatangulia, hao watatenganishwa na hayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 102, 'Hawatausikia mvumo wake, na wao watadumu katika yale ambayo nafsi zao zinayatamani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 103, 'Hicho Kitisho Kikubwa hakitawahuzunisha. Na Malaika watawapokea (kwa kuwaambia): Hii ndiyo Siku yenu mliyokuwa mkiahidiwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 104, 'Siku tutakapozikunja mbingu kama mkunjo wa karatasi za vitabu. Kama tulivyoanza uumbaji wa mwanzo, tutaurudisha tena. Ni ahadi iliyo juu yetu. Hakika Sisi ni watendao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 105, 'Na hakika tulikwishaandika katika Zaburi baada ya Kumbukumbu, ya kwamba ardhi watairithi waja wangu walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 106, 'Hakika katika haya yapo mawaidha kwa watu wafanyao ibada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 107, 'Nasi hatukukutuma ila uwe ni rehema kwa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 108, 'Sema: Hakika imefunuliwa kwangu ya kwamba hakika Mungu wenu ni Mungu Mmoja tu. Je, Mmesilimu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 109, 'Na kama wakigeuka, basi sema: Nimewatangazieni sawa sawa, wala sijui yako karibu au mbali hayo mliyoahidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 110, 'Hakika Yeye anajua kauli ya dhahiri na anajua myafichayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 111, 'Wala sijui pengine huu ni mtihani tu kwenu na starehe mpaka muda kidogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 112, 'Sema: Mola wangu Mlezi! Hukumu kwa haki. Na Mola wetu Mlezi ndiye Mwingi wa rehema, aombwaye msaada juu ya mnayoyazua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 1, 'Enyi watu! Mcheni Mola wenu Mlezi. Hakika mtetemeko wa Saa (ya Kiyama) ni jambo kuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 2, 'Siku mtakapoiona, kila mwenye kunyonyesha atamsahau amnyonyeshaye, na kila mwenye mimba, ataharibu mimba yake. Na utaona watu wamelewa, na kumbe hawakulewa. Lakini adhabu ya Mwenyezi Mungu ni kali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 3, 'Na miongoni mwa watu wapo wanaobishana juu ya Mwenyezi Mungu bila ya elimu, na wanamfuata kila shetani aliyeasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 4, 'Ameandikiwa kwamba anayemfanya kuwa rafiki, basi huyo hakika atampoteza na atamwongoza kwenye adhabu ya Moto mkali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 5, 'Enyi watu! Ikiwa nyinyi mna shaka juu ya kufufuliwa, basi kwa hakika Sisi tulikuumbeni kutokana na udongo, kisha kutokana na manii, kisha kutokana na kipande cha damu iliyogandana, kisha kutokana na kipande cha nyama chenye umbo na kisichokuwa na umbo, ili tuwabainishie. Nasi tunakiweka katika matumbo ya uzazi tunachokitaka mpaka muda uliowekwa. Kisha tunawatoa kwa hali ya mtoto mchanga, kisha mfikie kutimia akili. Na wapo katika nyinyi wanaokufa, na wapo katika nyinyi wanaorudishwa kwenye umri wa unyonge kabisa, hata mtu awe hajui kitu baada ya kuwa anakijua. Na unaiona ardhi imetulia kimya, lakini tunapoyateremsha maji juu yake, husisimka na kututumka, na kumea kila namna ya mimea mizuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 6, 'Hayo ni kwa sababu hakika Mwenyezi Mungu ndiye Haki, na kwamba hakika Yeye ndiye mwenye kuhuisha wafu, na kwamba hakika Yeye ni Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 7, 'Na kwamba hakika Saa (ya Kiyama) itakuja hakuna shaka kwa hilo, na kwamba hakika Mwenyezi Mungu atawafufua walio makaburini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 8, 'Na katika watu wapo wanaobishana juu ya Mwenyezi Mungu bila ya elimu, wala uongofu, wala Kitabu chenye nuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 9, 'Anayegeuza shingo yake ili kupoteza watu waiache njia ya Mwenyezi Mungu. Duniani atapata hizaya, na Siku ya Kiyama tutamwonjesha adhabu ya kuunguza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 10, '(Ataambiwa): Hayo ni kwa sababu ya yale iliyoyatanguliza mikono yako. Na hakika Mwenyezi Mungu si dhalimu kwa waja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 11, 'Na katika watu wapo wanaomuabudu Mwenyezi Mungu kwa ukingoni. Ikimfikia heri, hutulia kwayo. Na ukimfikia msukosuko, hugeuza uso wake. Amehasiri dunia na Akhera. Hiyo ndiyo hasara iliyo wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 12, 'Badala ya Mwenyezi Mungu, yeye huomba kisichomdhuru wala kumnufaisha. Huko ndiko kupotea kwa mbali!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 13, 'Humuomba yule ambaye bila ya shaka madhara yake yapo karibu zaidi kuliko manufaa yake. Kwa hakika huyo ni mlinzi muovu, na rafiki muovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 14, 'Hakika Mwenyezi Mungu atawaingiza wale walioamini na wakatenda mema katika Bustani zipitazo mito kwa chini yake. Hakika Mwenyezi Mungu hutenda atakayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 15, 'Anayedhani kwamba Mwenyezi Mungu hatamnusuru (Mtume) katika dunia na Akhera, basi na afunge kamba kwenye dari kisha na aikate, na atazame je hila yake itayaondoa hayo yaliyomkasirisha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 16, 'Na namna hivyo tumeiteremsha (Qur-ani) kuwa ni Aya zilizo wazi, na hakika Mwenyezi Mungu humwongoa amtakaye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 17, 'Hakika walioamini, na Mayahudi na Wasabai na Wakristo na Majusi na wale walioshirikisha, hakika Mwenyezi Mungu atawapambanua baina yao Siku ya Kiyama. Hakika Mwenyezi Mungu ni Shahidi wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 18, 'Je! Huoni kwamba vinamsujudia Mwenyezi Mungu vilivyomo mbinguni na vilivyomo ardhini, na jua, na mwezi, na nyota, na milima, na miti, na wanyama, na wengi miongoni mwa watu. Na wengi imewastahiki adhabu. Na anayefedheheshwa na Mwenyezi Mungu, huyo hana wa kumheshimu. Hakika Mwenyezi Mungu hutenda atakavyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 19, 'Hawa ni wagomvi wawili waliogombana kwa ajili ya Mola wao Mlezi. Basi waliokufuru watakatiwa nguo za moto, na yatamiminwa juu ya vichwa vyao maji yanayochemka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 20, 'Kwa maji hayo, vitayeyushwa vilivyomo matumboni mwao, na ngozi zao pia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 21, 'Na kwa ajili yao yatakuwapo marungu ya chuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 22, 'Kila wakitaka kutoka humo kwa sababu ya uchungu, watarudishwa humo humo, na wataambiwa: Onjeni adhabu ya kuunguza!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 23, 'Hakika Mwenyezi Mungu atawaingiza walioamini na wakatenda mema katika Bustani ambazo mito inapita kati yake. Watapambwa humo kwa mapambo ya mikononi ya dhahabu na lulu. Na mavazi yao humo ni hariri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 24, 'Na wataongozwa kwenye maneno mazuri, na wataongozwa kwenye njia ya Msifiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 25, 'Hakika wale waliokufuru na wakazuilia njia ya Mwenyezi Mungu na Msikiti Mtakatifu, ambao tumeufanya kwa ajili ya watu wote sawasawa, kwa wakaao humo na wageni. Na kila atakayetaka kufanya upotovu humo kwa dhuluma, basi tutamwonjesha adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 26, 'Na pale tulipomweka Ibrahim pahala penye ile Nyumba tukamwambia: Usinishirikishe na chochote; na isafishe Nyumba yangu kwa ajili ya wanaoizunguka kwa kutufu, na wanaokaa hapo kwa ibada, na wanaorukuu, na wanaosujudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 27, 'Na watangazie watu Hija; watakujia kwa miguu na juu ya kila ngamia aliyekonda, wakija kutoka katika kila njia ya mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 28, 'Ili washuhudie manufaa yao na walitaje jina la Mwenyezi Mungu katika siku maalumu juu ya wanyama wa mifugo aliowaruzuku. Basi kuleni katika hao na mlisheni mwenye shida aliye fakiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 29, 'Kisha wajisafishe taka zao, na watimize nadhiri zao, na waizunguke Nyumba ya Kale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 30, 'Ni hivyo! Na anayevitukuza vitakatifu vya Mwenyezi Mungu, basi hayo ndiyo heri yake mbele ya Mola wake Mlezi. Na mmehalalishiwa wanyama wa mifugo ila wale mliosomewa. Basi jiepusheni na uchafu wa masanamu, na jiepusheni na usemi wa uongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 31, 'Kwa kumtakasikia Imani Mwenyezi Mungu, bila ya kumshirikisha. Na anayemshirikisha Mwenyezi Mungu, basi ni kama kwamba ameporomoka kutoka mbinguni, kisha ndege wakamnyakua au upepo ukamtupa mahali mbali mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 32, 'Ndiyo hivyo! Na anayetukuza alama za dini za Mwenyezi Mungu, basi hayo ni katika unyenyekevu wa nyoyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 33, 'Katika hao nyinyi mna manufaa mpaka muda maalumu. Kisha mahali pa kuchinjiwa kwake ni kwenye Nyumba ya Kale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 34, 'Na kila umma tumewafanyia mahali pa kuchinjia mihanga ya ibada ili walitaje jina la Mwenyezi Mungu juu ya vile walivyoruzukiwa katika wanyama wa mifugo. Basi Mungu wenu ni Mungu Mmoja tu. Kwa hivyo, jisalimisheni kwake tu, na wabashirie wanyenyekevu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 35, 'Wale ambao, anapotajwa Mwenyezi Mungu, nyoyo zao hutetemeka, na wanavumilia kwa yanayowasibu, na wanashika Sala, na wanatoa katika tulivyowaruzuku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 36, 'Na ngamia (na ng''ombe) wa zawadi ya Nyumba Tukufu, tumewafanyia kuwa ni kudhihirisha alama za dini ya Mwenyezi Mungu. Kwa hao mna heri nyingi. Basi litajeni jina la Mwenyezi Mungu juu yao wanaposimama kwa safu. Na waangukapo kwenye ubavu, kuleni katika hao na walisheni waliokinai na wanaolazimika kuomba. Ndiyo kama hivi tumewafanya hawa wanyama dhalili kwenu ili mpate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 37, 'Nyama zao hazimfikii Mwenyezi Mungu wala damu zao, lakini unamfikia ucha Mungu wenu. Namna hivi tumewadhalilisha kwenu ili mumtukuze Mwenyezi Mungu kwa alivyowaongoa. Na wabashirie wafanyao mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 38, 'Hakika Mwenyezi Mungu huwakinga walioamini. Hakika Mwenyezi Mungu hampendi kila haini, mwingi wa kukufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 39, 'Wameruhusiwa kupigana wale wanaopigwa vita kwa sababu wamedhulumiwa - na kwa yakini Mwenyezi Mungu ni Muweza wa kuwasaidia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 40, 'Wale ambao walitolewa majumbani mwao pasina haki, ila kwa kuwa wanasema: "Mola wetu Mlezi ni Mwenyezi Mungu!" Na lau kuwa Mwenyezi Mungu hawakingi watu kwa watu, basi hapana shaka zingelivunjwa nyumba za watawa, na makanisa, na masinagogi, na misikiti, ambamo ndani yake jina la Mwenyezi Mungu linatajwa kwa wingi. Na bila ya shaka Mwenyezi Mungu humsaidia yule anayemsaidia Yeye. Hakika Mwenyezi Mungu ni Mwenye nguvu, Mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 41, 'Wale ambao tukiwapa madaraka katika nchi, hudumisha Sala, na wakatoa Zaka, na wakaamrisha mema, na wakakataza mabaya. Na kwa Mwenyezi Mungu ndiko marejeo ya mambo yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 42, 'Na wakikukanusha, basi walikwishakanusha kabla yao watu wa Nuhu, na kina ''Aad na kina Thamud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 43, 'Na watu wa Ibrahim na watu wa Luti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 44, 'Na watu wa Madiana. Na Musa pia alikanushwa. Nikawapa muda makafiri, kisha nikawatia mkononi. Basi ilikuwaje adhabu yangu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 45, 'Basi ni miji mingapi iliyokuwa ikidhulumu tuliiangamiza, ikawa imebaki magofu, na visima vilivyoachwa, na majumba yaliyokuwa madhubuti?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 46, 'Je, hawatembei katika ardhi ili wapate kuwa na nyoyo za kuzingatia, au masikio ya kusikilia? Kwani hakika si macho yanayopofuka. Lakini zinazopofuka ni nyoyo zilizomo vifuani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 47, 'Na wanakuharakisha ulete adhabu, lakini kamwe Mwenyezi Mungu hatakwenda kinyume na ahadi yake. Na hakika siku moja kwa Mola wako Mlezi ni kama miaka elfu mnavyohesabu nyinyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 48, 'Na ni miji mingapi niliipa muda na hali ilikuwa imedhulumu, na kisha nikaitia mkononi? Na kwangu Mimi ndiko marejeo yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 49, 'Sema: Enyi watu! Hakika mimi ni mwonyaji kwenu niliye dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 50, 'Basi walioamini na wakatenda mema watapata kufutiwa dhambi na riziki za ukarimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 51, 'Na wanaojitahidi kuzipinga Aya zetu, hao ndio watu wa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 52, 'Na hatukumtuma kabla yako Mtume wala Nabii ila anaposoma, Shetani hutumbukiza katika usomi wake. Lakini Mwenyezi Mungu huyaondoa anayoyatia Shetani; kisha Mwenyezi Mungu huzithibitisha Aya zake. Na Mwenyezi Mungu ndiye ajuaye zaidi, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 53, 'Hayo ni ili alifanye lile analolitia Shetani liwe ni majaribu kwa wale wenye maradhi ndani ya nyoyo zao, na wale ambao nyoyo zao ni ngumu. Na hakika madhalimu wako katika upinzani wa mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 54, 'Na ili waliopewa elimu wajue kuwa hayo ni Haki itokayo kwa Mola wako Mlezi na waamini, na zipate kutua nyoyo zao. Na hakika Mwenyezi Mungu ndiye anayewaongoa wenye kuamini kwenye njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 55, 'Na waliokufuru hawataacha kuwa katika wasiwasi kwa hilo mpaka Saa ya Kiyama iwafikie ghafla, au iwafikie adhabu ya Siku Tasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 56, 'Ufalme wote siku hiyo utakuwa wa Mwenyezi Mungu. Atahukumu baina yao. Basi walioamini na wakatenda mema, watakuwa katika Bustani zenye neema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 57, 'Na waliokufuru na kuzikanusha Ishara zetu, basi hao watapata adhabu ya kufedhehesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 58, 'Na waliohama kwa ajili ya Mwenyezi Mungu, kisha wakauawa au wakafa, bila ya shaka Mwenyezi Mungu atawaruzuku riziki njema. Na hakika Mwenyezi Mungu ni Mbora wa wanaoruzuku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 59, 'Bila ya shaka atawaingiza mahali watakapoparidhia. Na hakika Mwenyezi Mungu ndiye ajuaye zaidi, Mstahamilivu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 60, 'Ndiyo namna hivi. Na anayelipiza mfano wa alivyoadhibiwa, kisha akadhulumiwa, basi hakuna shaka Mwenyezi Mungu atamsaidia. Hakika Mwenyezi Mungu ni Msamehevu, Mwenye maghfira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 61, 'Hayo ni kwa kuwa Mwenyezi Mungu huingiza usiku katika mchana, na huuingiza mchana katika usiku, na ya kwamba Mwenyezi Mungu ni Mwenye kusikia, Mwenye kuona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 62, 'Hayo ni kwa kuwa Mwenyezi Mungu ndiye wa kweli, na kwamba wale wanaowaomba badala yake, ni batili, na hakika Mwenyezi Mungu ndiye aliye juu, Mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 63, 'Je, huoni kwamba Mwenyezi Mungu huteremsha maji kutoka mbinguni, na mara ardhi inakuwa kijani kibichi? Hakika Mwenyezi Mungu ni Mpole, Mwenye habari zote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 64, 'Ni vyake vilivyomo mbinguni na vilivyo katika ardhi. Na hakika Mwenyezi Mungu ni Mwenye kujitosha, Mwenye kusifiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 65, 'Je, huoni kwamba Mwenyezi Mungu amevidhalilisha kwenu vilivyo katika ardhi, na merikebu zipitazo baharini kwa amri yake, na amezishika mbingu zisianguke juu ya ardhi, ila kwa idhini yake. Hakika Mwenyezi Mungu ni Mpole kwa watu, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 66, 'Na Yeye ndiye aliyewahuisha kisha atawafisha, na kisha atawafufua. Hakika mwanadamu ni mwingi wa kukufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 67, 'Kila umma tumewawekea ibada zao wanazozishika. Basi wasizozane nawe katika jambo hili. Na waite watu kwenda kwa Mola wako Mlezi. Hakika wewe uko kwenye uongofu ulionyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 68, 'Na wakikujadili, basi sema: Mwenyezi Mungu anajua zaidi mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 69, 'Mwenyezi Mungu atahukumu baina yenu Siku ya Kiyama katika hayo mnayohitilafiana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 70, 'Je, hujui kwamba Mwenyezi Mungu anayajua yaliyomo mbinguni na katika ardhi? Hakika hayo yamo Kitabuni. Hakika hayo kwa Mwenyezi Mungu ni mepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 71, 'Na wanaabudu badala ya Mwenyezi Mungu ambavyo hakuviteremshia ushahidi, na ambavyo hawana elimu navyo. Na madhalimu hawatakuwa na wa kuwasaidia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 72, 'Na wanaposomewa Aya zetu zilizo wazi, utaona chuki katika nyuso za waliokufuru. Hukaribia kuwavamia wale wanaowasomea hizo Aya zetu. Sema: Je, nikuambieni yaliyo mabaya zaidi kuliko haya? Ni Moto. Mwenyezi Mungu amewaahidi waliokufuru, na ni marudio mabaya hayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 73, 'Enyi watu! Unapigwa mfano, basi usikilizeni. Hakika wale mnaowaomba badala ya Mwenyezi Mungu, hawawezi kuumba hata nzi ijapokuwa watajumuika kwa hilo. Na nzi akiwapokonya kitu, hawawezi kukiokoa kutoka kwake. Amedhoofika kweli huyo mwenye kutaka na mwenye kutakiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 74, 'Hawakumpa taadhima Mwenyezi Mungu anavyostahiki kupewa taadhima. Hakika Mwenyezi Mungu bila ya shaka ni Mwenye nguvu, Mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 75, 'Mwenyezi Mungu huteua Wajumbe miongoni mwa Malaika na miongoni mwa watu. Hakika Mwenyezi Mungu ni Mwenye kusikia, Mwenye kuona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 76, 'Anayajua yaliyo mbele yao na yaliyo nyuma yao. Na kwa Mwenyezi Mungu yatarejeshwa mambo yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 77, 'Enyi mlioamini! Rukuuni na sujuduni, na muabuduni Mola wenu Mlezi, na tendeni mema, ili mfanikiwe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 78, 'Na fanyeni juhudi kwa ajili ya Mwenyezi Mungu kama inavyostahiki kumfanyia juhudi. Yeye amewateua. Wala hakuweka juu yenu mambo mazito katika Dini. Nayo ni mila ya baba yenu Ibrahim. Yeye (Mwenyezi Mungu) aliwaita Waislamu tangu zamani, na katika hii (Qur''ani) pia, ili awe Mtume shahidi juu yenu, na nyinyi muwe mashahidi kwa watu. Basi shikeni Swala na toeni Zaka na shikamaneni na Mwenyezi Mungu. Yeye ndiye mlinzi wenu. Ni mlinzi mzuri kabisa, na msaidizi bora kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 1, 'Hakika wamefaulu Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 2, 'Ambao ni wanyenyekevu katika Swala zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 3, 'Na ambao hujiepusha na mambo ya upuuzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 4, 'Na ambao wanatoa Zaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 5, 'Na ambao wanazilinda tupu zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 6, 'Isipokuwa kwa wake zao au kwa wale iliyowamiliki mikono yao ya kulia. Kwani hao si wenye kulaumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 7, 'Lakini anayetaka kinyume cha haya, basi hao ndio wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 8, 'Na ambao wanazitunza amana zao na maagano yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 9, 'Na ambao Swala zao wanazihifadhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 10, 'Hao ndio warithi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 11, 'Ambao watairithi Bustani ya Firdausi, nao watadumu humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 12, 'Na kwa yakini tumemuumba mtu kutokana na asili ya udongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 13, 'Kisha tukamfanya kuwa tone la mbegu ya uzazi katika mahali patulivu palipo madhubuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 14, 'Kisha tukaliumba tone hilo kuwa damu iliyoganda, na tukaiumba damu hiyo kuwa pande la nyama, kisha tukaliumba pande hilo la nyama kuwa mifupa, na mifupa hiyo tukaivisha nyama. Kisha tukamfanya kuwa kiumbe mwingine. Basi Mwenyezi Mungu ni Mwingi wa baraka, Mbora zaidi wa waumbaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 15, 'Kisha hakika nyinyi baada ya hayo mtakufa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 16, 'Kisha hakika nyinyi Siku ya Kiyama mtafufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 17, 'Na kwa yakini tumeziumba juu yenu njia saba. Nasi hatukuwa wenye kughafilika na viumbe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 18, 'Na tumeteremsha kutoka mbinguni maji kwa kiasi na tukayatuliza katika ardhi. Na hakika Sisi tunaweza kuyaondoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 19, 'Kwa maji hayo tukawafanyia bustani za mitende na mizabibu, mnapata humo matunda mengi, na katika hayo mnakula.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 20, 'Na mti utokao katika mlima wa Sinai, unaotoa mafuta na kuwa kitoweo kwa walao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 21, 'Na hakika mnayo mazingatio makubwa katika wanyama wa kufugwa waliwao. Tunawanywesha nyinyi katika vile vilivyo matumboni mwao, na nyinyi mnapata katika hao manufaa mengi, na pia mnawala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 22, 'Na juu yao na juu ya marikebu mnabebwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 23, 'Na hakika tulimtuma Nuhu kwa kaumu yake, akasema, "Enyi kaumu yangu! Muabuduni Mwenyezi Mungu. Nyinyi hamna mungu yeyote asiyekuwa Yeye. Basi je, hamwogopi?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 24, 'Wakasema wale wakuu waliokufuru katika kaumu yake, "Huyu si chochote isipokuwa ni mtu tu kama nyinyi. Anataka kujipa ubora juu yenu. Na lau kuwa Mwenyezi Mungu angetaka, basi kwa yakini angeliteremsha Malaika. Hatukusikia haya kwa baba zetu wa mwanzoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 25, 'Huyu si lolote isipokuwa ni mwanamume mwenye wazimu. Basi mngojeeni tu kwa muda."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 26, 'Akasema (Nuhu), "Mola wangu Mlezi! Ninusuru kwa kuwa wamenikanusha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 27, 'Tukamfunulia wahyi kwamba, "Unda jahazi mbele ya macho yetu na ufunuo wetu! Na itakapofika amri yetu na ikafurika tanuri, hapo waingize ndani yake kutoka kwa kila jozi, dume na jike, na ahali zako, isipokuwa yule ambaye katika wao juu yake imekwisha tangulia kauli. Wala usiniongeleshe kuhusu hao waliodhulumu. Kwani hao bila ya shaka watazamishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 28, 'Basi utakapotulia sawasawa wewe na wale walio pamoja nawe humo merikebuni, sema: Alhamdulillahi (Sifa zote njema ni za Mwenyezi Mungu), aliyetuokoa kutoka kwa kaumu madhalimu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 29, 'Na sema: Mola wangu Mlezi! Niteremshe mteremsho wenye baraka, na Wewe ndiye Mbora wa wateremshaji."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 30, 'Hakika katika hayo zipo ishara. Na kwa yakini Sisi ni wenye kuwajaribu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 31, 'Kisha baada yao tukaanzisha kizazi kingine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 32, 'Kisha tukawatumia Mtume miongoni mwao, kuwaambia: Muabuduni Mwenyezi Mungu! Hamna mungu yeyote asiyekuwa Yeye. Je, hamumchi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 33, 'Na wakubwa katika kaumu yake, wale waliokufuru na wakakadhibisha mkutano wa Akhera, na tukawastarehesha katika uhai wa dunia hii, walisema: Huyu si chochote isipokuwa ni mtu kama nyinyi. Anakula katika mnavyokula, na anakunywa katika mnavyokunywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 34, 'Kwa hivyo, nyinyi mkimtii mtu kama nyinyi, basi hakika mtakuwa hasarani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 35, 'Hivi anawaahidi ati mtakapokufa na mkawa udongo na mifupa, kuwa hakika mtatolewa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 36, 'Hayawi! Hayawi hayo mnayoahidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 37, 'Hapana isipokuwa uhai wetu wa duniani tu, tunakufa na kuishi tu. Wala sisi hatutafufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 38, 'Huyu si lolote isipokuwa ni mwanamume anayemzulia Mwenyezi Mungu uongo, wala sisi sio wa kumuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 39, 'Akasema: Mola wangu Mlezi! Ninusuru kwa sababu wananikanusha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 40, '(Mwenyezi Mungu) akasema: Baada ya muda mchache watakuwa wenye kujuta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 41, 'Basi ukawanyakua ukelele kwa haki, na tukawafanya kama takataka zinazoelea juu ya maji. Ikapotelea mbali kaumu ya madhalimu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 42, 'Kisha tukaleta baada yao vizazi vingine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 43, 'Hapana umma uwezao kutanguliza muda wake wala kuuchelewesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 44, 'Kisha tukawatuma Mitume wetu, mmoja baada ya mmoja. Kila umma alipowafikia Mtume wao, walimkadhibisha. Tukawafuatanisha hawa baada ya hawa, na tukawafanya kuwa hadithi za kusimuliwa. Basi wakapotelea mbali kaumu wasioamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 45, 'Kisha tukamtuma Musa na kakaye, Harun, pamoja na ishara zetu na hoja zilizo wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 46, 'Kumwendea Firauni na wakuu wake. Lakini wakatakabari, nao walikuwa kaumu majeuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 47, 'Wakasema, "Je, tuwaamini watu wawili hawa kama sisi, na ambao kaumu yao ni watumwa wetu?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 48, 'Basi wakawakadhibisha, na wakawa miongoni mwa walioangamizwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 49, 'Na hakika tulimpa Musa Kitabu ili wapate kuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 50, 'Na tukamfanya mwana wa Mariamu na mama yake kuwa ni Ishara, na tukawapa makimbilio kwenda mahali palipoinuka penye utulivu na chemchemi za maji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 51, 'Enyi Mitume! Kuleni vyakula vizuri na tendeni mema. Hakika Mimi ninajua vyema mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 52, 'Na kwa yakini huu Umma wenu ni Umma mmoja, na Mimi ni Mola wenu Mlezi, basi nicheni Mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 53, 'Lakini walikatiana jambo lao mapande mbalimbali. Kila kundi likifurahia kwa waliyo nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 54, 'Basi waache katika ghafla yao kwa muda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 55, 'Je, wanadhani ya kuwa kwa vile tunavyowapa mali na watoto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 56, 'Ndiyo tunawaharakishia heri? Lakini wenyewe hawatambui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 57, 'Kwa hakika hao ambao kwa kumwogopa Mola wao Mlezi wananyenyekea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 58, 'Na wale ambao Ishara za Mola wao Mlezi wanaziamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 59, 'Na wale ambao Mola wao Mlezi hawamshirikishi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 60, 'Na wale ambao wanatoa kile walichopewa, na hali nyoyo zao zinaogopa kwa kuwa watarejea kwa Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 61, 'Basi wote hao ndio wanaokimbilia mambo ya heri, na ndio watakaotangulia kuyafikia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 62, 'Na hatuitwiki nafsi isipokuwa kwa kiasi cha uwezo wake. Na tunacho kitabu kisemacho kweli. Nao hawatadhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 63, 'Lakini nyoyo zao zimefunikwa hazitambui hayo, na wanavyo vitendo vinginevyo wanavyovifanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 64, 'Hata tutakapowatia katika adhabu wale waliodekezwa kwa starehe kati yao, hapo ndipo watakapoyayatika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 65, 'Msiyayatike leo! Hakika nyinyi hamtanusurika kutokana nasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 66, 'Hakika zilikuwa Aya zangu mkisomewa, nanyi mkirudi nyuma juu ya visigino vyenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 67, 'Na huku mkiitakabari na usiku mkiizungumzia (Qur-ani) kwa dharau.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 68, 'Je, hawakuifikiri kauli, au yamewajia ambayo hayakuwafikia baba zao wa zamani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 69, 'Au hawakumjua Mtume wao, ndiyo maana wanamkataa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 70, 'Au wanasema: Ana wazimu? Bali amewajia kwa Haki, na wengi wao wanaichukia Haki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 71, 'Na lau kuwa Haki ingelifuata matamanio yao, basi zingeliharibika mbingu na ardhi na waliomo ndani yake. Bali tumewaletea ukumbusho wao, nao wanajitenga mbali na ukumbusho wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 72, 'Au unawaomba ujira? Lakini ujira wa Mola wako Mlezi ni bora, na Yeye ndiye Mbora wa wanaoruzuku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 73, 'Na kwa yakini, wewe unawaita kwenye njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 74, 'Na hakika wale wasioiamini Akhera wanajitenga mbali na njia hiyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 75, 'Na lau tungeliwarehemu na tukawaondolea shida waliyo nayo, bila ya shaka wangeliendelea katika upotovu wao, vile vile wakitangatanga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 76, 'Na hakika tuliwatia adhabu kali; lakini hawakuelekea kwa Mola wao Mlezi wala hawakunyenyekea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 77, 'Mpaka tulipowafungulia mlango wa adhabu, hapo ndipo wakawa wenye kukata tamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 78, 'Na Yeye ndiye aliyewaumbia kusikia na kuona na nyoyo za kufahamu. Ni kuchache mno kushukuru kwenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 79, 'Na Yeye ndiye aliyewaeneza katika ardhi, na kwake Yeye mtakusanywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 80, 'Na Yeye ndiye anayehuisha na kufisha, na ni yake Yeye mabadiliko ya usiku na mchana. Basi je, hamfahamu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 81, 'Bali wanasema kama walivyosema watu wa kwanza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 82, 'Walisema: Je, tukishakufa tukawa udongo na mifupa, ndio tutafufuliwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 83, 'Tuliahidiwa haya sisi na baba zetu wa zamani. Hayakuwa haya ila ni visa vya uongo vya watu wa zamani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 84, 'Sema: Ni ya nani ardhi na vilivyo ndani yake, kama nyinyi mnajua?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 85, 'Watasema: Ni vya Mwenyezi Mungu! Sema: Basi, je, hamkumbuki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 86, 'Sema: Ni nani Mola Mlezi wa mbingu saba na Mola Mlezi wa Kiti Kikuu cha Enzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 87, 'Watasema: Ni vya Mwenyezi Mungu. Sema, Basi, je, hamwogopi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 88, 'Sema: Ni nani mkononi mwake umo Ufalme wa kila kitu, naye ndiye anayelinda, wala hakilindwi asichotaka, kama mnajua?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 89, 'Watasema, "Ufalme huo ni wa Mwenyezi Mungu." Sema: Basi vipi mnadanganyika?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 90, 'Bali tumewaletea Haki, na kwa yakini hao ni waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 91, 'Mwenyezi Mungu hana mwana yeyote, wala hanaye mungu mwingine. Ingekuwa hivyo basi kila mungu angelichukua alivyoumba, na baadhi yao wangeliwashinda wengine. Mwenyezi Mungu ameepukana na sifa wanazomsifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 92, 'Yeye ndiye ajuaye siri na dhahiri, na ametukuka juu ya hayo wanayomshirikisha nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 93, 'Sema: Mola wangu Mlezi! Ukinionyesha adhabu waliyoahidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 94, 'Mola wangu Mlezi! Usinifanye katika hao watu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 95, 'Na hakika Sisi ni waweza wa kukuonyesha tuliyowaahidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 96, 'Kinga maovu kwa kutenda yaliyo mema zaidi. Sisi tunayajua vyema wayasemayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 97, 'Na sema: Mola wangu Mlezi! Ninajikinga kwako kutokana na wasiwasi wa mashetani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 98, 'Na ninajikinga kwako, Mola wangu Mlezi, wasinikaribie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 99, 'Mpaka yanapomfikia mmoja wao mauti, husema: "Mola wangu Mlezi! Nirudishe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 100, 'Ili nitende mema sasa badala ya yale niliyoyaacha." Wapi! Hii ni kauli aisemayo yeye tu. Na nyuma yao kipo kizuizi mpaka siku watakapofufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 101, 'Basi litakapopulizwa baragumu, hapo hautakuwapo ujamaa baina yao siku hiyo, wala hawataulizana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 102, 'Ama wale ambao mizani zao zitakuwa nzito, hao ndio wenye kufanikiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 103, 'Na wale ambao mizani zao zitakuwa nyepesi, hao ndio waliozitia hasarani nafsi zao, na katika Jahannamu watadumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 104, 'Moto utababua nyuso zao, nao watakuwa na nyuso zilizo kunjana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 105, 'Je, hazikuwa Aya zangu mkisomewa, na nyinyi mkizikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 106, 'Watasema: Mola wetu Mlezi! Tulizidiwa na uovu wetu na tukawa watu tuliopotea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 107, 'Mola wetu Mlezi! Tutoe humu Motoni. Na tukirudia tena (ya zamani), basi kweli sisi ni wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 108, 'Atasema Mwenyezi Mungu: Tokomeeni humo, wala msinisemeshe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 109, 'Bila ya shaka lilikuwapo kundi katika waja wangu likisema: Mola wetu Mlezi! Tumeamini; basi tusamehe na uturehemu, nawe ndiwe Mbora wa wanaorehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 110, 'Lakini nyinyi mliwakejeli hata wakakusahaulisheni kunikumbuka, na mlikuwa mkiwacheka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 111, 'Hakika Mimi leo nimewalipa kwa vile walivyosubiri. Bila ya shaka hao ndio wenye kufuzu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 112, 'Atasema: Mlikaa muda gani katika ardhi kwa hisabu ya miaka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 113, 'Watasema: Tulikaa siku moja au sehemu ya siku. Basi waulize wanaoweka hisabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 114, 'Atasema: Nyinyi hamkukaa huko duniani ila kidogo, laiti ingelikuwa mnajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 115, 'Je, mlidhani ya kwamba tuliwaumba bure, na ya kwamba nyinyi kwetu hamtarudishwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 116, 'Ametukuka Mwenyezi Mungu, Mfalme wa Haki. Hakuna mungu yeyote isipokuwa Yeye, Mola Mlezi wa Kiti cha Enzi Kitukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 117, 'Na anayemuomba - pamoja na Mwenyezi Mungu - mungu mwenginewe, hana ushahidi wa hili; basi bila ya shaka hisabu yake iko kwa Mola wake Mlezi. Kwa hakika makafiri hawafanikiwi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 118, 'Nawe sema, "Mola wangu Mlezi, samehe na urehemu nawe ni Mbora wa wanaorehemu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 1, 'Hii ni Sura tuliyoiteremsha na tukailazimisha; na tukateremsha ndani yake Aya zilizo wazi ili mkumbuke.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 2, 'Mzinifu mwanamke na mzinifu mwanamume, mtandikeni kila mmoja katika wao bakora mia. Wala isiwashike huruma kwa ajili yao katika hukumu ya Mwenyezi Mungu, ikiwa nyinyi mnamuamini Mwenyezi Mungu na Siku ya Mwisho. Na lishuhudie adhabu yao kundi la Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 3, 'Mwanamume mzinifu hamwoi ila mwanamke mzinifu au mwanamke mshirikina. Na mwanamke mzinifu haolewi ila na mwanamume mzinifu au mshirikina. Na hayo yameharamishwa kwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 4, 'Na wanaowasingizia wanawake mahashumu, kisha wasilete mashahidi wanne, basi watandikeni bakora themanini, na msiwakubalie ushahidi wao tena. Na hao ndio wapotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 5, 'Isipokuwa wale waliotubu baada ya hayo na wakatengenea; kwani bila ya shaka Mwenyezi Mungu ni Msamehevu, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 6, 'Na wale wanaowasingizia wake zao uzinzi na hawana mashahidi ila nafsi zao, basi ushahidi wa mmoja wao utakuwa kushuhudilia mara nne kwa kiapo cha Mwenyezi Mungu, ya kwamba hakika yeye ni katika wasemao ukweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 7, 'Na mara ya tano kwamba laana ya Mwenyezi Mungu iwe juu yake ikiwa ni miongoni mwa waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 8, 'Na mke itamwondokea adhabu kwa kutoa shahada mara nne kwa kiapo cha Mwenyezi Mungu, ya kwamba huyu mume ni miongoni mwa waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 9, 'Na mara ya tano ya kwamba ghadhabu ya Mwenyezi Mungu iwe juu yake, kama mumewe yu miongoni mwa wanaosema ukweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 10, 'Na lau kuwa si fadhila ya Mwenyezi Mungu juu yenu na rehema yake, na ya kuwa Mwenyezi Mungu ni Mpokeaji toba na Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 11, 'Hakika wale walioleta uongo ni kundi miongoni mwenu. Msifikiri ni shari kwenu, bali hiyo ni kheri kwenu. Kila mtu katika wao atapata aliyoyachuma katika madhambi. Na yule aliyejitwika sehemu yake kubwa miongoni mwao, atapata adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 12, 'Kwa nini mlipoisikia habari hii, wanaume Waumini na wanawake Waumini hawakuwadhania wenzao mema, na kusema: Huu ni uzushi dhahiri?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 13, 'Kwa nini hawakuleta mashahidi wanne? Na ilivyokuwa hawakuleta mashahidi wanne, basi hao mbele ya Mwenyezi Mungu ni waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 14, 'Na lau kuwa si fadhila ya Mwenyezi Mungu juu yenu na rehema yake katika dunia na Akhera, bila ya shaka ingeliwapata adhabu kubwa kwa sababu ya yale mliyojiingiza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 15, 'Mlipoyapokea kwa ndimi zenu na mkasema kwa vinywa vyenu msiyoyajua, na mlifikiri ni jambo dogo, kumbe mbele ya Mwenyezi Mungu ni kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 16, 'Na kwa nini mlipoyasikia msiseme: Haitufalii kuzungumza haya. Subhanak! (Umetakasika!) Huu ni uzushi mkubwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 17, 'Mwenyezi Mungu anawaonya msirejee tena kufanya kama haya kabisa, ikiwa nyinyi ni Waumini!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 18, 'Na Mwenyezi Mungu anawabainishia Aya mbalimbali. Na Mwenyezi Mungu ndiye ajuaye zaidi, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 19, 'Kwa hakika wale wanaopenda uenee uchafu kwa walioamini, watapata adhabu chungu katika dunia na Akhera. Na Mwenyezi Mungu anajua na nyinyi hamjui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 20, 'Na lau kuwa si fadhila ya Mwenyezi Mungu juu yenu na rehema yake, na kuwa hakika Mwenyezi Mungu ni Mpole, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 21, 'Enyi mlioamini, msizifuate nyayo za Shetani. Na atakayefuata nyayo za Shetani basi yeye huamrisha machafu na maovu. Na lau kuwa si fadhila ya Mwenyezi Mungu na rehema yake juu yenu, asingelitakasika miongoni mwenu kabisa hata mmoja. Lakini Mwenyezi Mungu humtakasa amtakaye, na Mwenyezi Mungu ni Mwenye kusikia, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 22, 'Na wale katika nyinyi wenye fadhila na wasaa wasiape kutowapa jamaa zao, na masikini na waliohama kwa Njia ya Mwenyezi Mungu. Na wasamehe, na waachilie mbali. Je, nyinyi hampendi Mwenyezi Mungu awasamehe? Na Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 23, 'Hakika wanaowasingizia wanawake, wanaojiheshimu, walioghafilika, Waumini; wamelaaniwa duniani na Akhera, nao watapata adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 24, 'Siku ambayo zitawashuhudia ndimi zao na mikono yao na miguu yao kwa waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 25, 'Siku hiyo Mwenyezi Mungu atawapa sawa sawa malipo yao ya haki, na watajua kwamba hakika Mwenyezi Mungu ndiye Haki iliyo wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 26, 'Wanawake waovu ni wa wanaume waovu, na wanaume waovu ni wa wanawake waovu. Na wanawake wema ni wa wanaume wema, na wanaume wema ni wa wanawake wema. Hao wameepushwa na hayo wanayoyasema; wao watapata msamaha na riziki ya ukarimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 27, 'Enyi mlioamini! Msiingie nyumba zisizo nyumba zenu mpaka mwombe ruhusa, na mwatolee salamu wenyewe. Hayo ni bora kwenu ili mpate kukumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 28, 'Na msipomkuta mtu humo basi msiingie mpaka mruhusiwe. Na mkiambiwa: Rudini! Basi rudini. Hivi ni usafi zaidi kwenu. Na Mwenyezi Mungu anayajua mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 29, 'Si vibaya kwenu kuingia nyumba zisiokaliwa ambazo ndani yake yamo manufaa yenu. Na Mwenyezi Mungu anajua mnayoyadhihirisha na mnayoyaficha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 30, 'Waambie Waumini wanaume wainamishe macho yao, na wazilinde tupu zao. Hili ni takaso bora kwao. Hakika Mwenyezi Mungu anazo habari za wanayoyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 31, 'Na waambie Waumini wanawake wainamishe macho yao, na wazilinde tupu zao, wala wasionyeshe uzuri wao isipokuwa unaodhihirika. Na waangushe shungi zao juu ya vifua vyao, wala wasionyeshe uzuri wao ila kwa waume zao, au baba zao, au baba za waume zao, au watoto wao wa kiume, au watoto wa kiume wa waume zao, au kaka zao, au wana wa kiume wa kaka zao, au wana wa kiume wa dada zao, au wanawake wenzao, au iliyowamiliki mikono yao ya kiume, au wafwasi wanaume wasio na matamanio, au watoto ambao hawajajua mambo yanayohusu uchi wa wanawake. Wala wasipige chini miguu yao ili yajulikane mapambo waliyoyaficha. Na tubuni nyote kwa Mwenyezi Mungu, enyi Waumini, ili mpate kufanikiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 32, 'Na waozeni wajane miongoni mwenu na wema katika watumwa wenu na wajakazi wenu. Wakiwa mafakiri Mwenyezi Mungu atawatajirisha kwa fadhila yake. Na Mwenyezi Mungu ni Mwenye wasaa, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 33, 'Na wajizuilie mbali na machafu wale wasiopata cha kuolea, mpaka Mwenyezi Mungu awatajirishe kwa fadhila yake. Na wanaotaka kuandikiwa uhuru katika wale ambao mikono yenu ya kulia imewamiliki, basi waandikieni kama mkiona wema kwao. Na wapeni katika mali ya Mwenyezi Mungu aliyowapa. Wala msiwashurutishe vijakazi vyenu kufanya zina kwa ajili ya kutafuta pato la maisha ya dunia, ilhali wao wanataka kujiheshimu. Na atakayewalazimisha basi Mwenyezi Mungu baada ya kulazimishwa kwao huko, atawasamehe, kwani Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 34, 'Na kwa yakini tumewateremshia Ishara zilizo wazi, na mifano kutokana na waliotangulia kabla yenu na mawaidha kwa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 35, 'Mwenyezi Mungu ni Nuru ya Mbingu na Ardhi. Mfano wa Nuru yake ni kama shubaka lenye kuwekwa ndani yake taa. Taa ile imo katika tungi. Tungi lile ni kama nyota inayomeremeta, inayowashwa kwa mafuta yanayotoka katika mti uliobarikiwa, mzaituni. Si wa mashariki wala magharibi. Yanakaribia mafuta yake kung''aa wenyewe ingawa moto haujayagusa, - Nuru juu ya Nuru. Mwenyezi Mungu humwongoa kwenye Nuru yake amtakaye. Na Mwenyezi Mungu huwapigia watu mifano. Na Mwenyezi Mungu ni Mwenye kujua kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 36, 'Katika Nyumba ambazo Mwenyezi Mungu ameamrisha zitukuzwe, na humo litajwe jina lake, wanamtakasa humo asubuhi na jioni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 37, 'Watu ambao biashara wala kuuza hakuwashughulishi na kumdhukuru Mwenyezi Mungu, na kushika Sala, na kutoa Zaka. Wanaihofu Siku ambayo nyoyo na macho yatageuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 38, 'Ili Mwenyezi Mungu awalipe bora ya waliyoyatenda, na awazidishie katika fadhila zake. Na Mwenyezi Mungu humruzuku amtakaye bila ya hisabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 39, 'Na waliokufuru vitendo vyao ni kama sarabi (mazigazi) uwandani. Mwenye kiu huyadhania ni maji. Hata akiyaendea hapati chochote. Na atamkuta Mwenyezi Mungu hapo naye amlipe hisabu yake sawa sawa. Na Mwenyezi Mungu ni Mwepesi wa kuhisabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 40, 'Au ni kama giza katika bahari kuu, iliyofunikwa na mawimbi juu ya mawimbi, na juu yake yapo mawingu. Giza juu ya giza. Akiutoa mtu mkono wake anakaribia asiuone. Na ambaye Mwenyezi Mungu hakumjalia kuwa na nuru hawi na nuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 41, 'Je, huoni kwamba Mwenyezi Mungu vinamtakasa vilivyo katika mbingu na ardhi, na ndege wakikunjua mbawa zao? Kila mmoja amekwisha jua Swala yake na namna ya kumtakasa kwake. Na Mwenyezi Mungu ni Mwenye kuyajua wayatendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 42, 'Na ni wa Mwenyezi Mungu ufalme wa mbingu na ardhi, na kwa Mwenyezi Mungu ndiyo marejeo ya wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 43, 'Je, huoni ya kwamba Mwenyezi Mungu huyasukuma mawingu, kisha huyaambatisha, kisha huyafanya mirundi? Basi utaona mvua ikitoka kati yake. Na huteremsha kutoka juu kwenye milima ya mawingu mvua ya mawe, akamsibu nayo amtakaye na akamuepusha nayo amtakaye. Hukurubia mmetuko wa umeme wake kupofua macho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 44, 'Mwenyezi Mungu hubadilisha usiku na mchana. Hakika katika hayo yapo mazingatio kwa wenye kuona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 45, 'Na Mwenyezi Mungu ameumba kila kinyama kutokana na maji. Wengine katika wao huenda kwa matumbo yao, na wengine huenda kwa miguu miwili, na wengine huenda kwa miguu minne. Mwenyezi Mungu huumba ayatakayo. Hakika Mwenyezi Mungu ni Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 46, 'Kwa yakini tumeteremsha Ishara zinazobainisha. Na Mwenyezi Mungu humwongoa amtakaye kwenye Njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 47, 'Na wanasema: Tumemuamini Mwenyezi Mungu na Mtume, na tumetii. Kisha kikundi katika hao hugeuka baada ya hayo. Wala hao si wenye kuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 48, 'Na wanapoitwa kumuendea Mwenyezi Mungu na Mtume wake ili ahukumu baina yao, kipo kikundi katika wao kinakataa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 49, 'Na ikiwa haki ni yao, wanamjia kwa kutii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 50, 'Je, wana maradhi katika nyoyo zao, au wanaona shaka, au wanaogopa ya kuwa Mwenyezi Mungu na Mtume wake watawadhulumu? Bali hao ndio madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 51, 'Haiwi kauli ya Waumini wanapoitwa kwa Mwenyezi Mungu na Mtume wake ili ahukumu baina yao, ila ni kusema: "Tumesikia, na tumetii!" Na hao ndio wenye kufanikiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 52, 'Na wenye kumtii Mwenyezi Mungu na Mtume wake, na wakamwogopa Mwenyezi Mungu na wakamcha, basi hao ndio wenye kufuzu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 53, 'Na wanaapa kwa Mwenyezi Mungu ukomo wa kiapo chao ya kwamba ukiwaamrisha kwa yakini watatoka. Sema: Msiape! Utiifu unajulikana. Hakika Mwenyezi Mungu anazo habari za mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 54, 'Sema: Mtiini Mwenyezi Mungu, na mtiini Mtume. Na mkigeuka, basi yaliyo juu yake ni yale aliyobebeshwa, na yaliyo juu yenu ni yale mliyobebeshwa nyinyi. Na mkimtii yeye, mtaongoka. Na hapana juu ya Mtume ila kufikisha Ujumbe wazi wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 55, 'Wawe wananiabudu Mimi, wala wasinishirikishe na chochote. Na watakaokufuru baada ya hayo, basi hao ndio wapotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 56, 'Na shikeni Swala, na toeni Zaka, na mtiini Mtume, ili mpate kurehemewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 57, 'Msiwadhanie waliokufuru kwamba watashinda katika nchi. Na makaazi yao ni Motoni, na hakika ni maovu kweli marejeo yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 58, 'Enyi mlioamini, na wakukitakeni idhini wale iliyowamiliki mikono yenu ya kulia na walio bado kubaleghe miongoni mwenu mara tatu - kabla ya Swala ya Alfajiri, na wakati mnapovua nguo zenu adhuhuri, na baada ya Sala ya Isha. Hizi ni nyakati tatu za faragha kwenu. Si vibaya kwenu wala kwao baada ya nyakati hizi, kuzungukiana nyinyi kwa nyinyi. Hivyo ndivyo Mwenyezi Mungu anavyowaelezeni Aya zake, na Mwenyezi Mungu ni Mjuzi, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 59, 'Na watoto wanapofikilia umri wa kubaleghe basi na watake ruhusa, kama walivyotaka ruhusa wa kabla yao. Hivyo ndivyo anavyowabainishia Mwenyezi Mungu Aya zake, na Mwenyezi Mungu ni Mjuzi, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 60, 'Na wanawake wazee wasiotaraji kuolewa, si vibaya kwao kupunguza nguo zao, bila ya kujishaua kwa mapambo. Na wakijiheshimu ni bora kwao. Na Mwenyezi Mungu ni Mwenye kusikia, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 61, 'Si vibaya kwa kipofu, wala si vibaya kwa kiguru, wala si vibaya kwa mgonjwa, wala kwenu nyinyi, mkila katika nyumba zenu, au nyumba za baba zenu, au nyumba za mama zenu, au nyumba za kaka zenu, au nyumba za dada zenu, au nyumba za ami zenu, au nyumba za shangazi zenu, au nyumba za wajomba zenu, au nyumba za dada za mama zenu, au za mliowashikia funguo zao, au rafiki yenu. Si vibaya kwenu mkila pamoja au mbali mbali. Na mkiingia katika nyumba, toleaneni salamu, kuwa ni maamkio yanayotoka kwa Mwenyezi Mungu, yenye baraka na mema. Hivyo ndivyo Mwenyezi Mungu anavyo kubainishieni Aya zake ili mpate kuelewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 62, 'Hakika Waumini wa kweli ni wale waliomuamini Mwenyezi Mungu na Mtume wake; na wanapokuwa pamoja naye kwa jambo la kuwakhusu wote hawaondoki mpaka wamtake ruhusa. Kwa hakika wale wanaokuomba ruhusa, hao ndio wanaomuamini Mwenyezi Mungu na Mtume wake. Na wakikuomba ruhusa kwa baadhi ya kazi zao, mruhusu umtakaye miongoni mwao, uwaombee msamaha kwa Mwenyezi Mungu. Hakika Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 63, 'Msifanye wito wa Mtume baina yenu kama wito wa nyinyi kwa nyinyi. Hakika Mwenyezi Mungu anawajua miongoni mwenu wanaoondoka kwa kujificha. Basi na watahadhari wanaohalifu amri yake, usije ukawapata msiba au ikawapata adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 64, 'Jueni kuwa hakika ni vya Mwenyezi Mungu vilivyomo mbinguni na ardhini. Hakika Yeye anajua mliyo nayo. Na siku watakaporudishwa kwake atawaeleza waliyoyafanya. Na Mwenyezi Mungu ni Mwenye kujua vyema kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 1, 'Ametukuka aliyeteremsha Furqani kwa mja wake, ili awe mwonyaji kwa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 2, 'Ambaye ni wake ufalme wa mbingu na ardhi, wala hakuwa na mwana, wala hakuwa na mshirika katika ufalme, na akaumba kila kitu na akakikadiria kwa kipimo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 3, 'Na wamechukua badala yake miungu ambayo haiumbi chochote, bali hiyo inaumbwa, haijimilikii nafsi zao madhara wala manufaa, wala haimiliki mauti, wala uhai, wala kufufuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 4, 'Na wamesema waliokufuru: "Haya si chochote ila ni uzushi aliouzua, na wamemsaidia kwa haya watu wengine!" Hakika hawa wamekuja na dhuluma na uongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 5, 'Na wakasema: Hivi ni visa vya watu wa kale alivyoviandikisha, anavyosomewa asubuhi na jioni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 6, 'Sema: Ameyateremsha haya ajuaye siri za katika mbingu na ardhi. Hakika Yeye ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 7, 'Na wakasema: Ana nini Mtume huyu? Anakula chakula, na anatembea masokoni! Mbona hakuteremshiwa Malaika akawa mwonyaji pamoja naye?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 8, 'Au akaangushiwa hazina juu yake, au akawa na bustani ale katika hiyo? Wakasema madhalimu: Nyinyi hamumfuati ila mtu aliyerogwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 9, 'Tazama jinsi wanavyokupigia mifano. Basi wamepotea, wala hawataiweza Njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 10, 'Ametukuka ambaye akitaka atakujalia yaliyo bora kuliko hayo, nayo ni mabustani yapitayo mito kati yake, na atakujaalia majumba ya fahari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 11, 'Bali wanaikanusha Saa (ya Kiyama). Na Sisi tumemuandalia Moto mkali kabisa huyo mwenye kuikanusha Saa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 12, 'Ule Moto ukiwaona tangu mahali mbali, wao watasikia hasira yake na mngurumo wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 13, 'Na watakapotupwa humo mahali penye dhiki, hali wamefungwa, wataomba wafe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 14, 'Msiombe kufa mara moja tu, bali mfe mara nyingi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 15, 'Sema: Je, haya ni bora au Bustani ya milele, ambayo wameahidiwa wacha Mungu, iwe kwao malipo na marejeo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 16, 'Watayapata humo wayatakayo daima dawamu. Hii ni ahadi juu ya Mola wako Mlezi, inayoombwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 17, 'Na siku atakapowakusanya wao na hao wanaowaabudu, na akasema: Je, ni nyinyi mliowapoteza waja wangu hawa, au wao wenyewe walipotea njia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 18, 'Watasema: Subhanaka! (Umetakasika na upungufu!) Haikutupasia sisi kuchukulia walinzi badala yako, lakini Wewe uliwastarehesha wao na baba zao hata wakasahau kukumbuka, na wakawa watu walioangamia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 19, 'Basi waliwakanusheni kwa mliyoyasema. Kwa hivyo hamwezi kujiondolea wala kujisaidia. Na atakayedhulumu miongoni mwenu tutamwonjesha adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 20, 'Na hatukuwatuma kabla yako Mitume wowote ila kwa hakika na yakini walikuwa wakila chakula, na wakienda masokoni. Na tumewajaalia baadhi yenu wawe ni majaribio kwa wengine. Je, mtasubiri? Na Mola wako Mlezi ni Mwenye kuona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 21, 'Na walisema wale wasiotarajia kukutana nasi, "Mbona sisi hatukuteremshiwa Malaika au tumwone nasi Mola wetu Mlezi?" Hakika, hawa wamejiona bora nafsi zao; na wamepanda kichwa, vikubwa mno!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 22, 'Siku watakapowaona Malaika, hakutakuwa na furaha yoyote siku hiyo kwa wahalifu. Na watasema, "Mwenyezi Mungu apishe mbali!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 23, 'Na tutayaendea yale waliyoyatenda katika matendo na tuyafanye kama mavumbi yaliyotawanywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 24, 'Watu wa Bustanini siku hiyo watakuwa katika makazi bora na mahali penye starehe nzuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 25, 'Na siku zitakapopasuka mbingu zifunguke kwa mawingu, na wateremshwe Malaika kwa wingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 26, 'Ufalme wa haki siku hiyo utakuwa wa Arrahman (Mwingi wa rehema), na itakuwa siku ngumu kwa makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 27, 'Na siku ambayo mwenye kudhulumu atajiuma mikono yake, na huku anasema: Laiti ningelishika njia pamoja na Mtume!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 28, 'Ewe ole wangu! Laiti nisingelimfanya fulani kuwa rafiki mwandani!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 29, 'Hakika alinipoteza, nikaacha Ukumbusho, baada ya kwisha nijia, na kweli Shetani ni haini mkubwa kwa mwanadamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 30, 'Na Mtume alikuwa akisema: Ewe Mola wangu Mlezi! Hakika kaumu yangu wameifanya hii Qur-ani kuwa ni kihame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 31, 'Na vivyo hivyo tumemfanyia kila Nabii adui miongoni mwa wahalifu, na Mola wako Mlezi anatosha kuwa Mwenye kuongoa na Mwenye kunusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 32, 'Na wakasema wale waliokufuru: Kwa nini hakuteremshiwa Qur-ani yote mara moja tu? Hayo ni hivyo ili tuuimarishe kwayo (ufahamu wa) moyo wako, na ndiyo tumeisoma kwa mafungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 33, 'Wala hawatakuletea mfano wowote, isipokuwa na Sisi tutakuletea (jawabu) kwa haki, na tafsiri iliyo bora zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 34, 'Wale ambao watakusanywa kwa nyuso zao hadi katika Jahannamu, hao watakuwa na mahali pabaya mno, nao ndio wenye kuipotea zaidi njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 35, 'Na hakika tulimpa Musa Kitabu na tukamuweka pamoja naye kakaye, Harun, kuwa msaidizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 36, 'Tukawaambia: "Nendeni kwa kaumu waliokanusha Ishara zetu." Basi tukawateketeza kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 37, 'Na kaumu ya Nuhu, walipowakanusha Mitume, tuliwazamisha, na tukawafanya ni Ishara kwa watu. Na tumewaandalia madhalimu adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 38, 'Na (tuliwaangamiza) kina ''Adi na Thamudi na watu wa Rass na vizazi vingi vilivyokuwa kati yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 39, 'Na wote tuliwapigia mifano, na wote tuliwaangamiza kabisa kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 40, 'Na kwa yakini wao walikwisha ujia mji ulioteremshiwa mvua mbaya. Basi, je, hawakuwa wakiuona? Bali walikuwa hawataraji kufufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 41, 'Na wanapokuona, hawakuchukulii isipokuwa ni mzaha tu, na (wanasema): Ati huyu ndiye Mwenyezi Mungu alimtuma kuwa Mtume?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 42, 'Kwa hakika alikuwa karibu zaidi kutupoteza tuiache miungu yetu, lau kuwa hatukushikamana nayo kwa kuvumilia. Bado watakuja jua, watakapoiona adhabu, ni nani aliyepotea zaidi njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 43, 'Je, umemwona aliyeyafanya matamanio yake kuwa ndiyo mungu wake? Basi je, wewe utakuwa ni wakili wake?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 44, 'Au wewe unadhani kwamba wengi wao wanasikia au wanaelewa? Hao sio isipokuwa ni kama wanyama tu, bali wao wamepotea zaidi njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 45, 'Je, huoni jinsi Mola wako Mlezi anavyokitandaza kivuli. Na angelitaka, angelikifanya kikatulia tu. Kisha tumelifanya jua kuwa ni kiongozi wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 46, 'Kisha tunakivutia kwetu kidogo kidogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 47, 'Naye ndiye aliyewafanyia usiku kuwa ni vazi, na usingizi kuwa mapumziko, na akawafanyia mchana ni kufufuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 48, 'Naye ndiye anayezituma pepo kuwa bishara njema kabla ya rehema yake, na tunayateremsha kutoka mbinguni maji safi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 49, 'Ili kwa hayo tuihuishe nchi iliyokufa, na tuwanyweshe wanyama na watu wengi tuliowaumba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 50, 'Na kwa yakini tumeibadilibadili kati yao wapate kukumbuka. Lakini wengi wa watu wanakataa isipokuwa kukufuru tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 51, 'Na tungelitaka, tungelituma katika kila mji Mwonyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 52, 'Basi usiwatii makafiri. Na pambana nao kwayo kwa Jihadi kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 53, 'Naye ndiye aliyezipeleka bahari mbili, hii ni tamu mno, na hii ni ya chumvi chungu. Na akaweka baina yake kinga na kizuizi kizuiacho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 54, 'Naye ndiye aliyemuumba mwanadamu kutokana na maji, akamjaalia kuwa na nasaba na ushemeji. Na Mola wako Mlezi ni Muweza mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 55, 'Na wanayaabudu badala ya Mwenyezi Mungu yasiyowafaa wala yasiyowadhuru. Na kafiri daima ni msaidizi wa kumpinga Mola wake Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 56, 'Nasi hatukukutuma isipokuwa uwe Mbashiri na Mwonyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 57, 'Sema: Sikuwaomba ujira wowote juu yake; isipokuwa atakaye na ashike njia iendayo kwa Mola wake Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 58, 'Na mtegemee aliye Hai, ambaye hafi. Na umtakase kwa sifa zake. Naye anatosha kuwa ndiye Mwenye habari zote za dhambi za waja wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 59, 'Ambaye aliziumba mbingu na ardhi, na vilivyo kati yake kwa siku sita. Kisha akainuka akawa juu ya Kiti cha Enzi. Mwingi wa rehema (Arrahman)! Uliza habari zake kwa amjuaye.[1]', '[1] Yaani, muulize Mwenyezi Mungu mwenyewe ambaye anajua kila kitu, na hakuna kinachofichika kwake.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 60, 'Na wanapoambiwa: Msujudieni Arrahman (Mwingi wa rehema!) Wao husema: Ni nani Arrahman (Mwingi wa rehema)? Je, tumsujudie unayetuamrisha wewe tu? Na huwazidishia kujitenga mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 61, 'Ni Mwenye baraka nyingi yule aliyezijalia nyota mbinguni, na akajalia humo taa na mwezi unaong''ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 62, 'Naye ndiye aliyefanya usiku na mchana kufuatana kwa nafuu ya yule anayetaka kukumbuka, au anayetaka kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 63, 'Na waja wa Arrahman (Mwingi wa rehema) ni wale wanaotembea ulimwenguni kwa staha, na wajinga wakiwasemeza, hujibu: Salama!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 64, 'Na wale wanaokesha kwa ajili ya Mola wao Mlezi kwa kusujudu na kusimama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 65, 'Na wale wanaosema: "Mola wetu Mlezi! Tuondolee adhabu ya Jahannamu. Hakika adhabu yake ikimpata mtu haimwachi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 66, 'Hakika hiyo ni kituo na makao mabaya."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 67, 'Na wale ambao wanapotoa matumizi, hawatumii kwa fujo wala hawafanyi ubahili, bali wanakuwa katikati baina ya hayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 68, 'Na wale wasiomuomba mungu mwingine pamoja na Mwenyezi Mungu, wala hawaui nafsi aliyoiharimisha Mwenyezi Mungu isipokuwa kwa haki, wala hawazini. Na atakayefanya hayo, atapata madhara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 69, 'Atazidishiwa adhabu Siku ya Kiyama, na atadumu humo kwa kufedheheshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 70, 'Isipokuwa atakayetubu, na akaamini, na akatenda matendo mema. Basi hao Mwenyezi Mungu atayabadilisha maovu yao yawe mema. Na Mwenyezi Mungu ni Mwingi wa kusamehe, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 71, 'Na aliyetubu na akafanya mema, basi hakika huyo ametubu kweli kweli kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 72, 'Na wale ambao hawatoi ushahidi wa uongo, na pindi wapitapo penye upuuzi, hupita kwa heshima yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 73, 'Na wale ambao wanapokumbushwa Ishara za Mola wao Mlezi hawajifanyi viziwi nazo, na vipofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 74, 'Na wale wanaosema: "Mola wetu Mlezi! Tupe katika wake zetu na wana wetu yaburudishayo macho, na utujalie tuwe waongozi kwa wacha Mungu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 75, 'Hao ndio watakaolipwa makao ya juu kwa kuwa walisubiri, na watakuta humo maamkizi na salama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 76, 'Wadumu humo, kituo na makao mazuri kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 77, 'Sema: Mola wangu Mlezi asingewajali lau kuwa si kuomba kwenu. Lakini nyinyi mmemkadhibisha. Basi adhabu lazima iwe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 1, 'Tw''a Siin Miim.[1]', '[1] Herufi hizi "Tw''aa, Sin, Miim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 2, 'Hizi ni Aya za Kitabu kinachobainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 3, 'Huenda ukaihiliki nafsi yako kwa kuwa hawawi Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 4, 'Tungependa, tungeliwateremshia kutoka mbinguni Ishara zikashinda zimezinyenyekea shingo zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 5, 'Wala hauwafikii ukumbusho mpya kutoka kwa Arrahman (Mwingi wa rehema), isipokuwa wao huupa mgongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 6, 'Kwa yakini wamekwishakanusha; kwa hivyo zitakuja wafikia habari za yale waliyokuwa wakiyafanyia stihizai.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 7, 'Je, hawakuiona ardhi, ni mimea mingapi tumeiotesha humo, ya kila namna nzuri?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 8, 'Hakika katika haya zipo Ishara. Lakini wengi wao hawakuwa wenye kuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 9, 'Na hakika Mola wako Mlezi ndiye Yeye Mwenye nguvu, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 10, 'Na Mola wako Mlezi, alipomwita Musa, akamwambia: Nenda kwa kaumu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 11, 'Kaumu wa Firauni. Kwani hawamchi Mwenyezi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 12, 'Akasema: Mola wangu Mlezi, hakika mimi ninachelea kwamba watanikadhibisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 13, 'Na kifua changu kina dhiki, na ulimi wangu haukunjuki vyema. Basi mtumie ujumbe Harun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 14, 'Na wao wana dhambi niliyowafanyia, kwa hivyo ninahofu wanaweza kuniua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 15, 'Akasema: Sivyo hivyo kabisa! Nendeni na miujiza yetu. Hakika Sisi tu pamoja nanyi, tunasikiliza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 16, 'Basi nendeni kwa Firauni na mwambieni: Hakika sisi ni Mitume wa Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 17, 'Kwamba: Waachilie Wana wa Israili waende pamoja nasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 18, '(Firauni) akasema: Je, sisi hatukukulea wewe utotoni, na ukakaa miongoni mwetu katika umri wako miaka mingi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 19, 'Na ukatenda kitendo chako ulichotenda, nawe ukawa miongoni mwa wenye kukufuru?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 20, '(Musa) akasema: Nilitenda hayo hapo nilipokuwa miongoni mwa wale waliopotea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 21, 'Basi nikawakimbia nilipowahofu, tena Mola wangu Mlezi akanitunukia hukumu, na akanijaalia niwe miongoni mwa Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 22, 'Na hiyo ndiyo neema ya kunisimbulia, na wewe umewatia utumwani Wana wa Israili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 23, 'Firauni akasema: Na ni nani huyo Mola Mlezi wa walimwengu wote?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 24, 'Akasema: Ndiye Mola Mlezi wa mbingu na ardhi, na vilivyo baina yake, ikiwa nyinyi ni wenye yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 25, '(Firauni) akawaambia waliomzunguka: Kwani hamsikilizi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 26, '(Musa) akasema: Ndiye Mola wenu Mlezi, na Mola Mlezi wa baba zenu wa kwanza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 27, '(Firauni) akasema: Hakika huyu Mtume wenu aliyetumwa kwenu ni mwendawazimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 28, '(Musa) akasema: Ndiye Mola Mlezi wa Mashariki na Magharibi na vilivyo baina yake, ikiwa nyinyi mnatia akilini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 29, '(Firauni) akasema: Ukijifanyia mungu mwingine asiyekuwa mimi, basi bila ya shaka nitakufunga gerezani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 30, 'Akasema: Je, hata kama nitakuletea kitu cha kubainisha wazi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 31, 'Akasema: Kilete basi, kama wewe ni katika wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 32, 'Basi akaitupa fimbo yake, mara ikawa nyoka wa kuonekana dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 33, 'Na akautoa nje mkono wake, mara ukawa mweupe kwa watazamao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 34, '(Firauni) akawaambia waheshimiwa waliomzunguka: Hakika huyu ni mchawi mtaalamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 35, 'Anataka kuwatoa katika nchi yenu kwa uchawi wake. Basi mna shauri gani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 36, 'Wakasema: Mpe muda yeye na kakaye na uwatume mijini wakusanyao watu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 37, 'Wakuletee kila mchawi bingwa mtaalamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 38, 'Basi wakakusanywa wachawi kwa ajili ya miadi ya siku maalumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 39, 'Na watu wakaambiwa: Je, mtakusanyika?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 40, 'Huenda tutawafuata wachawi ikiwa wao ndio watakaoshinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 41, 'Basi walipokuja wachawi, wakamwambia Firauni: Je, tutapata ujira ikiwa sisi ndio tutakaoshinda?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 42, 'Akasema: Ndiyo! Na hakika mtakuwa katika watu wa mbele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 43, 'Musa akawaambia: Tupeni mnavyotaka kutupa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 44, 'Basi wakatupa kamba zao na fimbo zao, na wakasema: Kwa nguvu za Firauni hakika sisi hapana shaka ni wenye kushinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 45, 'Basi Musa akatupa fimbo yake, nayo mara ikavimeza vile walivyovizua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 46, 'Hapo wachawi hao walipinduka wakasujudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 47, 'Wakasema: Tumemuamini Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 48, 'Mola Mlezi wa Musa na Harun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 49, '(Firauni) akasema: Je, mmemuamini kabla ya kuwaruhusu? Bila ya shaka yeye basi ndiye mkubwa wenu aliyewafunza uchawi. Basi mtakuja jua! Nitakatakata mikono yenu na miguu yenu kwa kutofautisha. Na nitawasulubisha misalabani nyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 50, 'Wakasema: Haidhuru, kwani sisi ni wenye kurejea kwa Mola wetu Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 51, 'Hakika sisi tunatumai kwamba Mola wetu Mlezi atatusamehe makosa yetu, kwa kuwa tumekuwa wa kwanza wa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 52, 'Na tulimuamrisha Musa kwa ufunuo: Nenda na waja wangu wakati wa usiku. Kwa hakika mtafuatwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 53, 'Basi Firauni akawatuma mijini wakusanyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 54, '(Wakieneza): Hakika hawa ni kikundi kidogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 55, 'Nao kwa hakika wanatuudhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 56, 'Na sisi ni wengi, wenye kuchukua hadhari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 57, 'Basi tukawatoa katika mabustani na chemchemi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 58, 'Na mahazina, na vyeo vya heshima,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 59, 'Vivyo hivyo, na tukawarithisha hayo Wana wa Israili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 60, 'Basi wakawafuata lilipochomoza jua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 61, 'Na yalipoonana majeshi mawili haya, watu wa Musa wakasema: Hakika sisi bila ya shaka tumekutwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 62, '(Musa) akasema: Hasha! Hakika yu pamoja nami Mola wangu Mlezi. Yeye ataniongoa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 63, 'Na tulimletea Musa ufunuo tukamwambia: Piga bahari kwa fimbo yako. Basi ikatengana, na kila sehemu ikawa kama mlima mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 64, 'Na tukawasongesha hapo karibu wale wengine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 65, 'Tukawaokoa Musa na wale waliokuwa pamoja naye wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 66, 'Kisha tukawazamisha hao wengine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 67, 'Hakika bila ya shaka katika hayo ipo Ishara; lakini wengi wao si wenye kuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 68, 'Na kwa hakika Mola wako Mlezi ndiye Mwenye nguvu, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 69, 'Na wasomee habari za Ibrahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 70, 'Alipomwambia baba yake na kaumu yake: Mnaabudu nini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 71, 'Wakasema: Tunaabudu masanamu, daima tunayanyenyekea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 72, 'Akasema: Je, yanawasikia mnapoyaita?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 73, 'Au yanawafaa, au yanawadhuru?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 74, 'Wakasema: Bali tuliwakuta baba zetu wakifanya hivyo hivyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 75, 'Akasema: "Je, mmewaona hawa mnaowaabudu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 76, 'Nyinyi na baba zenu wa zamani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 77, 'Kwani hakika hao ni adui zangu, isipokuwa Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 78, 'Ambaye ndiye aliyeniumba, na Yeye ndiye ananiongoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 79, 'Na ambaye ndiye ananilisha na kuninywesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 80, 'Na ninapougua, ni Yeye ndiye anayeniponesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 81, 'Na ambaye atanifisha, na kisha atanihuisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 82, 'Na ambaye ndiye ninayemtumai kunisamehe makosa yangu Siku ya Malipo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 83, 'Mola wangu Mlezi! Nitunukie hukumu na uniunganishe na walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 84, 'Na unijalie nitajwe kwa wema na watu watakaokuja baadaye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 85, 'Na unijalie katika warithi wa Bustani za neema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 86, 'Na umsamehe baba yangu, kwani hakika alikuwa miongoni mwa wapotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 87, 'Wala usinihizi Siku watakapofufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 88, 'Siku ambayo kwamba mali haitafaa kitu wala wana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 89, 'Isipokuwa mwenye kumjia Mwenyezi Mungu na moyo safi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 90, 'Na Bustani ya mbiguni itasogezwa kwa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 91, 'Na Jahannamu itadhihirishwa kwa wapotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 92, 'Na wataambiwa: Wako wapi mliokuwa mkiwaabudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 93, 'Badala ya Mwenyezi Mungu? Je, wanawasaidia, au wanajisaidia wenyewe?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 94, 'Basi watavurumizwa humo wao na hao wakosefu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 95, 'Na majeshi ya Ibilisi yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 96, 'Watasema, na hali ya kuwa wanazozana humo:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 97, '"Tallahi! Kwa yakini tulikuwa katika upotovu ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 98, 'Tulipowafanya nyinyi ni sawa na Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 99, 'Na hawakutupoteza isipokuwa wale wakosefu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 100, 'Basi hatuna waombezi wowote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 101, 'Wala rafiki wa dhati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 102, 'Laiti tungelipata kurejea tena, tungelikuwa katika Waumini."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 103, 'Hakika katika haya ipo Ishara, lakini wengi wao hawakuwa wenye kuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 104, 'Na hakika Mola wako Mlezi ndiye Mwenye nguvu Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 105, 'Kaumu ya Nuhu waliwakadhibisha Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 106, 'Alipowaambia ndugu yao, Nuhu: Je, hamumchi Mwenyezi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 107, 'Hakika mimi kwenu ni Mtume muaminifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 108, 'Basi mcheni Mwenyezi Mungu, na nitiini mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 109, 'Na siwaulizi juu yake ujira, kwani ujira wangu hauko isipokuwa kwa Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 110, 'Basi mcheni Mwenyezi Mungu, na nitiini mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 111, 'Wakasema: Je, tukuamini wewe, ilhali wanaokufuata ni watu duni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 112, 'Akasema: Ninayajuaje waliyokuwa wakiyafanya?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 113, 'Hesabu yao haiko isipokuwa kwa Mola wao Mlezi, laiti mngelitambua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 114, 'Wala mimi si wa kuwafukuza Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 115, 'Mimi si chochote isipokuwa ni Mwonyaji wa dhahiri shahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 116, 'Wakasema: Ikiwa huachi, ewe Nuhu, bila ya shaka utapigwa mawe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 117, 'Akasema: Mola wangu Mlezi! Hakika watu wangu wamenikadhibisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 118, 'Basi hukumu baina yangu na wao kwa hukumu yako, na uniokoe mimi na walio pamoja nami miongoni mwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 119, 'Kwa hivyo tukamwokoa yeye na waliokuwa pamoja naye katika marikebu iliyosheheni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 120, 'Kisha tukawazamisha baadaye waliobakia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 121, 'Hakika katika haya ipo Ishara, lakini si wengi wao waliokuwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 122, 'Na hakika Mola wako Mlezi ndiye Yeye Mwenye nguvu, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 123, 'Kina ''Aad waliwakanusha Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 124, 'Alipowaambia ndugu yao, Hud: Je, hamumchi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 125, 'Hakika mimi kwenu ni Mtume muaminifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 126, 'Basi mcheni Mwenyezi Mungu, na nitiini mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 127, 'Wala siwaulizi juu yake ujira wowote, kwani ujira wangu hauko isipokuwa kwa Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 128, 'Je, mnajenga juu ya kila mnyanyuko kumbusho la kufanyia upuuzi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 129, 'Na mnajenga majengo ya kifahari kama kwamba mtaishi milele!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 130, 'Na mnapotumia nguvu, mnatumia nguvu kwa ujabari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 131, 'Basi mcheni Mwenyezi Mungu, na nitiini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 132, 'Na mcheni aliyewapa haya mnayoyajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 133, 'Aliwapa wanyama wa kufuga na wana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 134, 'Na mabustani na chemchemi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 135, 'Hakika mimi ninawahofia adhabu ya Siku Kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 136, 'Wakasema: Ni mamoja kwetu, ukitupa mawaidha au hukuwa miongoni mwa watoao mawaidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 137, 'Haya si chochote isipokuwa ni mtindo wa watu wa tokea zamani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 138, 'Wala sisi hatutaadhibiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 139, 'Wakamkadhibisha; nasi tukawaangamiza. Hakika bila ya shaka katika haya ipo Ishara. Lakini hawakuwa wengi wao wenye kuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 140, 'Na hakika Mola wako Mlezi ndiye Mwenye nguvu, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 141, 'Kina Thamud waliwakadhibisha Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 142, 'Alipowaambia ndugu yao Saleh: Je, hamumchi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 143, 'Hakika mimi kwenu ni Mtume muaminifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 144, 'Basi mcheni Mwenyezi Mungu, na nitiini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 145, 'Wala siwaulizi ujira wowote juu yake. Ujira wangu hauko isipokuwa kwa Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 146, 'Je, mtaachwa salama salimini katika haya yaliyopo hapa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 147, 'Katika mabustani, na chemchemi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 148, 'Na konde na mitende yenye makole yaliyowiva.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 149, 'Na mnachonga milimani majumba kwa ustadi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 150, 'Basi mcheni Mwenyezi Mungu, na nitiini mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 151, 'Wala msitii amri za waliopitiliza mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 152, 'Ambao wanafanya uharibifu katika nchi, wala hawatengenezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 153, 'Wakasema: Hakika wewe ni miongoni mwa waliorogwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 154, 'Wewe si chochote isipokuwa ni mtu kama sisi. Basi leta Ishara ikiwa wewe ni miongoni mwa wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 155, 'Akasema: Huyu ngamia jike; awe na zamu yake ya kunywa, na nyinyi muwe na zamu yenu ya kunywa katika siku maalumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 156, 'Wala msimguse kwa wovu, ikawashika adhabu ya Siku Kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 157, 'Lakini wakamuua, na wakawa wenye kujuta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 158, 'Basi ikawapata adhabu. Hakika katika hayo ipo Ishara. Lakini hawakuwa wengi wao wenye kuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 159, 'Na hakika Mola wako Mlezi ndiye Mwenye nguvu, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 160, 'Watu wa Luti waliwakadhibisha Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 161, 'Alipowaambia ndugu yao, Luti: Je, hamumchi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 162, 'Hakika mimi kwenu ni Mtume muaminifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 163, 'Basi mcheni Mwenyezi Mungu na nitiini mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 164, 'Wala mimi sikuwauliza ujira wowote juu yake; ujira wangu hauko isipokuwa kwa Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 165, 'Je, katika viumbe vyote mnawaingilia wanaume?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 166, 'Na mnaacha alichowaumbia Mola wenu Mlezi katika wake zenu? Ama kweli nyinyi ni watu mnaoruka mipaka!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 167, 'Wakasema: Ewe Luti! Usipoacha, hapana shaka utakuwa miongoni mwa wanaotolewa mji!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 168, 'Akasema: Hakika mimi ni katika wanaokichukia hiki kitendo chenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 169, 'Mola wangu Mlezi! Niokoe mimi na ahali zangu na haya wayatendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 170, 'Basi tukamwokoa yeye na ahali zake wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 171, 'Isipokuwa kikongwe katika waliokaa nyuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 172, 'Kisha tukawaangamiza wale wengine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 173, 'Na tukawanyeshea mvua, basi ni ovu mno mvua ya waliyoonywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 174, 'Hakika katika hayo ipo Ishara. Na hawakuwa wengi wao wenye kuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 175, 'Na hakika Mola wako Mlezi bila ya shaka ndiye Mwenye nguvu, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 176, 'Watu wa Machakani waliwakanusha Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 177, 'Shuaibu alipowaambia: Je, hamumchi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 178, 'Hakika mimi kwenu ni Mtume muaminifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 179, 'Basi mcheni Mwenyezi Mungu, na nitiini mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 180, 'Wala siwaulizi ujira wowote juu yake. Ujira wangu hauko isipokuwa kwa Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 181, 'Timizeni kipimo sawasawa, wala msiwe katika wanaopunja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 182, 'Na pimeni kwa haki iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 183, 'Wala msiwapunje watu vitu vyao, wala msifanye jeuri katika ardhi kwa kufanya uharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 184, 'Na mcheni aliyewaumba nyinyi na vizazi vilivyotangulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 185, 'Wakasema: Hakika wewe ni katika waliorogwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 186, 'Na wewe si chochote isipokuwa ni mtu tu kama sisi, na kwa yakini tunakuona wewe ni katika waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 187, 'Hebu tuangushie vipande kutoka mbinguni ikiwa wewe ni miongoni mwa wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 188, 'Akasema: Mola wangu Mlezi anajua zaidi mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 189, 'Basi walimkanusha, na ikawashika adhabu ya Siku ya kivuli. Hakika hiyo ilikuwa adhabu ya Siku kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 190, 'Hakika katika hayo ipo Ishara, lakini hawakuwa wengi wao wenye kuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 191, 'Na hakika Mola wako Mlezi bila ya shaka ndiye Yeye Mwenye nguvu, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 192, 'Na bila ya shaka hii ni Uteremsho wa Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 193, 'Ameuteremsha Roho muaminifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 194, 'Juu ya moyo wako, ili uwe katika Waonyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 195, 'Kwa ulimi wa Kiarabu ulio wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 196, 'Na hakika bila ya shaka haya yamo katika Vitabu vya kale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 197, 'Je, haikuwa kwao ni Ishara kwamba wanayajua haya wanachuoni wa Wana wa Israili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 198, 'Na lau kuwa tungeliiteremsha juu ya mmoja wa wasiokuwa Waarabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 199, 'Na akawasomea, wasingelikuwa wenye kuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 200, 'Namna hivi tunaingiza katika nyoyo za wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 201, 'Hawataiamini mpaka waione adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 202, 'Basi itawafikia kwa ghafla, na hali hawana habari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 203, 'Na watasema: "Je, tutapewa muhula?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 204, 'Basi je, wanaihimiza adhabu yetu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 205, 'Waonaje kama tukiwastarehesha kwa miaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 206, 'Kisha yakawafikia waliyokuwa wakiahidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 207, 'Yatawafaa nini yale waliyostareheshewa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 208, 'Wala hatukuangamiza mji wowote isipokuwa ulikuwa na waonyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 209, 'Kuwa ni ukumbusho. Wala Sisi hatukuwa wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 210, 'Wala Mashetani hawakuteremka nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 211, 'Wala haitakiwi kwao, na wala hawawezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 212, 'Hakika hao wametengwa na kusikia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 213, 'Basi usimwombe mungu mwingine pamoja na Mwenyezi Mungu ukawa miongoni mwa watakaoadhibiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 214, 'Na uwaonye jamaa zako walio karibu nawe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 215, 'Na watwae kwa upole wanaokufuata miongoni mwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 216, 'Na ikiwa watakuasi, basi sema: Mimi ninajitenga mbali na hayo mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 217, 'Na umtegemee Mtukufu Mwenye nguvu, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 218, 'Ambaye anakuona unaposimama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 219, 'Na mageuko yako katika wanaosujudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 220, 'Hakika Yeye ndiye Mwenye kusikia, Mwenye kujua zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 221, 'Je, niwaambieni nani wanawashukia Mashetani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 222, 'Wanamshukia kila mzushi mkubwa mwingi wa dhambi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 223, 'Wanawapelekea yale wanayoyasikia; na wengi wao ni waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 224, 'Na watungaji mashairi ni wapotovu ndio wanawafuata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 225, 'Je, huwaoni kwamba wao wanatangatanga katika kila bonde?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 226, 'Na kwamba wao husema wasiyoyatenda?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 227, 'Isipokuwa wale walioamini, na wakatenda mema, na wakamkumbuka Mwenyezi Mungu kwa wingi, na wakajitetea wanapodhulumiwa. Na wanaodhulumu watakuja jua mgeuko gani watakaogeuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 1, 'Tw''aa Siin. Hizi ni Aya za Qur-ani na Kitabu kinachobainisha.[1]', '[1] Herufi hizi "Twa, Sin" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali wa ushindi ya Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 2, 'Uongofu na bishara kwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 3, 'Ambao wanashika Swala, na wanatoa Zaka, na Akhera wana yakini nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 4, 'Kwa hakika wale wasioiamini Akhera tumewapambia vitendo vyao, kwa hivyo wanatangatanga ovyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 5, 'Hao ndio watapata adhabu mbaya kabisa, na hao katika Akhera ndiyo watapata hasara zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 6, 'Na hakika wewe unafundishwa Qur-ani inayotokana kwake Mwenye hekima, Mwenye kujua zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 7, '(Kumbuka) Musa alipowaambia ahali zake: Hakika nimeona moto, nitakwenda niwaletee habari kutoka huko, au nitawaletea kijinga kinacho waka ili mpate kuota moto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 8, 'Basi alipoufikia, ilinadiwa: Amebarikiwa aliyemo katika moto huu na walioko pembezoni mwake. Na ametakasika Mwenyezi Mungu, Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 9, 'Ewe Musa! Hakika Mimi ndiye Mwenyezi Mungu, Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 10, 'Na itupe fimbo yako! Alipoiona ikitikisika kama nyoka, aligeuka nyuma wala hakungoja. Ewe Musa! Usihofu! Hakika hawahofu mbele yangu Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 11, 'Lakini aliyedhulumu, kisha akabadilisha wema baada ya ubaya, basi Mimi hakika ni Mwingi wa kusamehe, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 12, 'Na ingiza mkono wako katika mfuko wako, utatoka mweupe bila ya maradhi. Ni katika Ishara tisa za kumpelekea Firauni na kaumu yake. Hakika hao walikuwa kaumu waovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 13, 'Basi zilipowafikia Ishara zetu hizo zenye kuonyesha, wakasema: Huu ni uchawi dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 14, 'Na wakazikataa kwa dhuluma na kujivuna, na hali ya kuwa nafsi zao zina yakini nazo. Basi angalia ulikuwaje mwisho wa waharibifu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 15, 'Na hakika tuliwapa Daudi na Suleiman elimu, na wakasema: Alhamdu Lillahi (Kuhimidiwa kote ni kwa Mwenyezi Mungu) aliyetufadhilisha kuliko wengi katika waja wake Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 16, 'Na Suleiman alimrithi Daudi, na akasema: Enyi watu! Tumefunzwa usemi wa ndege, na tumepewa katika kila kitu. Hakika hii ni fadhila iliyo dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 17, 'Na alikusanyiwa Suleiman majeshi yake ya majini, na watu, na ndege; nayo yakapangwa kwa nidhamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 18, 'Mpaka walipofika kwenye bonde la wadudu chungu, alisema mdudu chungu mmoja: Enyi wadudu chungu! Ingieni majumbani mwenu, asiwapondeni Suleiman na majeshi yake bila ya wao kutambua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 19, 'Basi (Suleiman) akatabasamu akacheka kwa neno hili, na akasema: Ewe Mola wangu Mlezi! Nizindue niishukuru neema yako uliyonineemesha mimi na wazazi wangu, na nipate kutenda mema uyapendayo, na uniingize kwa rehema yako katika waja wako wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 20, 'Na akawakagua ndege, na akasema: Imekuwaje, mbona simwoni Hud-hud, au amekuwa miongoni mwa wasiokuwepo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 21, 'Kwa yakini nitamuadhibu kwa adhabu kali, au nitamchinja, au aniletee hoja ya kutosha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 22, 'Basi (Hud-hud) akakaa si mbali na akasema: Nimegundua usilogundua wewe, na ninakujia hivi kutoka nchi ya Sabai, na nakuletea habari za yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 23, 'Hakika mimi nimemkuta mwanamke anawatawala, naye amepewa kila kitu, na anacho kiti cha enzi kikubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 24, 'Nimemkuta yeye na watu wake wanalisujudia jua badala ya Mwenyezi Mungu; na Shetani amewapambia vitendo vyao na akawazuilia Njia. Kwa hivyo hawakuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 25, 'Na hawamsujudii Mwenyezi Mungu ambaye huyatoa yaliyofichikana katika mbingu na ardhi, na anayajua mnayoyaficha na mnayoyadhihirisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 26, 'Mwenyezi Mungu - hapana mungu isipokuwa Yeye, Mola Mlezi wa Kiti cha Enzi kitukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 27, 'Akasema (Suleiman): Tutatazama iwapo umesema ukweli au wewe ni miongoni mwa waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 28, 'Nenda na barua yangu hii na uwafikishie, kisha waache na utazame watarejesha nini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 29, '(Malkia) akasema: Enyi waheshimiwa! Hakika nimeletewa barua tukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 30, 'Kwa hakika, imetoka kwa Suleiman nayo hakika ni: "Kwa jina la Mwenyezi Mungu, Mwingi wa rehema, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 31, 'Msinifanyie jeuri, na fikeni kwangu nanyi mmekwisha kuwa wenye kusalimu amri."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 32, 'Akasema: Enyi waheshimiwa! Nipeni shauri katika jambo langu hili, kwani mimi sikati shauri yoyote mpaka mhudhurie', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 33, 'Wakasema: Sisi ni wenye nguvu na wakali kwa vita; na amri iko kwako, basi tazama ni nini unaamrisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 34, 'Akasema: Hakika wafalme wanapouingia mji, wanauharibu, na wanawafanya wale watukufu wake kuwa wanyonge. Na hivyo ndivyo watendavyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 35, 'Lakini mimi nitawatumia zawadi, nami nitangoja watakayorudi nayo wajumbe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 36, 'Basi alipofika (mjumbe) kwa Suleiman, alisema (Suleiman): Hivyo ndivyo nyinyi mnanisaidia kwa mali? Aliyonipa Mwenyezi Mungu ni bora zaidi kuliko aliyowapa nyinyi. Lakini nyinyi mnafurahia hii zawadi yenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 37, 'Rejea kwao! Kwa yakini sisi tutawajia kwa majeshi wasioyaweza kuyakabili. Na hakika tutawatoa humo na hali wao wamekuwa madhalili na wanyonge.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 38, 'Akasema: Enyi waheshimiwa! Ni nani kati yenu atakayeniletea kiti chake cha enzi kabla hawajanijia, nao wamekwisha salimu amri?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 39, 'Akasema Afriti mmoja katika majini: Mimi nitakuletea kabla hujainuka pahala pako hapo. Na mimi kwa hakika katika hilo nina nguvu na muaminifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 40, 'Akasema mwenye elimu ya Kitabu: Mimi nitakuletea kabla ya kupepesa jicho lako. Basi alipokiona kimewekwa kimetulia mbele yake, akasema: Haya ni katika fadhila zake Mola wangu Mlezi, ili anijaribu nitashukuru au nitakufuru. Na mwenye kushukuru, kwa hakika, anashukuru kwa manufaa ya nafsi yake. Na anayekufuru, kwa hakika Mola wangu Mlezi ni Mkwasi na Mkarimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 41, 'Akasema: Mgeuzieni kiti chake cha enzi hiki, tuone ataongoka, au atakuwa miongoni mwa wasioongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 42, 'Basi (Malkia) alipofika akaambiwa: Je, kiti chako cha enzi ni kama hiki? Akasema: Kama kwamba ndicho hiki. (Suleiman na watu wake wakasema): Na sisi tumepewa elimu kabla yake (Malkia), na tukawa Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 43, 'Na yale aliyokuwa akiyaabudu badala ya Mwenyezi Mungu yalimzuilia. Hakika yeye (Malkia) alikuwa katika kaumu ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 44, 'Akaambiwa: Liingie behewa la hili jumba. Alipoliona, alidhani ni maji, na akapandisha nguo mpaka kwenye miundi yake. (Suleiman) akasema: Hakika hilo ni behewa lililofanyiwa sakafu ya vioo! Akasema (Malkia): Mola wangu Mlezi! Hakika mimi nimejidhulumu, na sasa ninanyenyekea pamoja na Suleiman kwa Mwenyezi Mungu, Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 45, 'Na kwa kina Thamud tulimtuma ndugu yao Saleh kuwaambia: Muabuduni Mwenyezi Mungu. Basi wakawa makundi mawili yanayogombana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 46, 'Akasema: Enyi kaumu yangu! Kwa nini mnauhimiza wovu kabla ya wema? Kwa nini hamuombi msamaha kwa Mwenyezi Mungu ili mrehemewe?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 47, 'Wakasema: Tuna kisirani nawe na wale walio pamoja nawe. Yeye akasema: Uaguzi wa ukorofi wenu uko kwa Mwenyezi Mungu; lakini nyinyi ni watu mnaojaribiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 48, 'Na walikuwamo mjini watu tisa wakifanya uharibifu katika nchi wala hawafanyi mambo kutengenea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 49, 'Wakasema: Apishaneni kwa Mwenyezi Mungu tutamshambulia usiku yeye na ahali zake; kisha tutamwambia mrithi wake: Sisi hatukuona maangamizo ya watu wake, na sisi bila ya shaka tunasema ukweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 50, 'Basi wakapanga mipango yao, na Sisi tukapanga mipango yetu, na wao hawatambui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 51, 'Basi angalia ulivyokuwa mwisho wa mipango yao, ya kwamba tuliwaangamiza wao pamoja na watu wao wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 52, 'Basi hizo nyumba zao ni tupu kwa sababu ya walivyodhulumu. Hakika bila ya shaka katika hayo ipo Ishara kwa watu wanaojua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 53, 'Na tukawaokoa wale walioamini na waliokuwa wanamcha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 54, 'Na Luti alipowaambia watu wake, "Je, mnafanya uchafu nanyi mnaona?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 55, 'Hakika nyinyi mnawaingilia wanaume kwa matamanio badala ya wanawake? Hakika nyinyi ni kaumu mnaofanya ujinga kabisa!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 56, 'Basi haikuwa jawabu ya kaumu yake isipokuwa ni walisema, "Wafukuzeni wafwasi wa Luti kutoka katika mji wenu. Hakika wao ni watu wanaojitia usafi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 57, 'Basi tukamwokoa yeye na ahali zake, isipokuwa mkewe; tukamkadiria katika waliobaki nyuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 58, 'Na tukawanyeshea mvua. Basi ni ovu mno mvua hiyo ya wale waliokwisha onywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 59, 'Sema: Alhamdu Lillahi (Kuhimidiwa ni kwa Mwenyezi Mungu!) Na amani ishuke juu ya waja wake aliowateua. Je, Mwenyezi Mungu ndiye bora, au wale wanaowashirikisha naye?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 60, 'Au ni nani yule aliyeziumba mbingu na ardhi, na akawateremshia maji kutoka mbinguni, na kwa hayo tukaziotesha bustani zenye kupendeza? Nyinyi hamkuwa na uwezo wa kuiotesha miti yake. Je, yupo mungu pamoja na Mwenyezi Mungu? Bali hao ni kaumu waliopotoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 61, 'Au nani yule aliyeifanya ardhi mahali pa kutua, na akajaalia ndani yake mito, na akaweka milima? Na akaweka baina ya bahari mbili kizuizi? Je, yupo mungu pamoja na Mwenyezi Mungu? Bali wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 62, 'Au ni nani yule anayemjibu mwenye shida kubwa pale anapomwomba, na akaiondoa dhiki, na akawafanya warithi wa ardhi? Je, yupo mungu pamoja na Mwenyezi Mungu? Ni machache mnayoyazingatia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 63, 'Au ni nani yule anayewaongoa katika giza la bara na bahari, na akazipeleka pepo kuleta bishara kabla ya rehema zake? Je, yupo mungu pamoja na Mwenyezi Mungu? Ametukuka Mwenyezi Mungu juu ya hao wanaomshirikisha nao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 64, 'Au ni nani anayeuanzisha uumbaji, kisha akaurejesha? Na ni nani anayewaruzuku kutoka mbinguni na kwenye ardhi? Je, yupo mungu pamoja na Mwenyezi Mungu? Sema: Leteni hoja zenu kama nyinyi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 65, 'Sema: Hapana katika mbingu na ardhi ajuaye ya ghaibu isipokuwa Mwenyezi Mungu. Wala wao hawajui lini watafufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 66, 'Kwani huo ujuzi wao umefikilia kuijua Akhera? Bali wao wamo katika shaka nayo tu, bali wao ni vipofu nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 67, 'Na wakasema wale waliokufuru: Je, tutakapokuwa mchanga, sisi na baba zetu, hivyo kweli tutakuja tolewa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 68, 'Hakika ni haya haya tu tuliahidiwa sisi na baba zetu zamani. Hayakuwa haya isipokuwa ni hadithi za uongo za watu wa kale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 69, 'Sema: Nendeni katika ardhi, na tazameni ulikuwaje mwisho wa wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 70, 'Wala usiwahuzunikie wala usiwe katika dhiki kwa sababu ya hila zao wanazozifanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 71, 'Na wanasema: Ahadi hii itatokea lini, ikiwa nyinyi ni wakweli?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 72, 'Sema: Huenda yako karibu kuwafikia sehemu ya yale mnayoyahimiza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 73, 'Na hakika Mola wako Mlezi ni Mwenye fadhila kwa watu, lakini wengi wao hawashukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 74, 'Na hakika Mola wako Mlezi anayajua yanayoficha vifua vyao na wanayoyaweka hadharani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 75, 'Na hakuna siri katika mbingu na ardhi isipokuwa imo katika Kitabu kinachobainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 76, 'Hakika Qur-ani hii inawasimulia Wana wa Israili mengi ya yale wanayohitalifiana ndani yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 77, 'Nayo hakika ni uongofu na rehema kwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 78, 'Hakika Mola wako Mlezi atawahukumu kwa hukumu yake, naye ni Mwenye nguvu, ajuaye zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 79, 'Basi mtegemee Mweneyezi Mungu; hakika wewe uko juu ya Haki iliyo wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 80, 'Kwa hakika wewe huwezi kuwafanya maiti wasikie, wala kuwafanya viziwi wasikie wito, wanapokwisha geuka kwenda zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 81, 'Wala huwezi kuwaongoa vipofu waache upotovu wao. Huwezi kuwafanya wasikie isipokuwa wenye kuziamini Ishara zetu; basi hao ndio Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 82, 'Na itakapowaangukia kauli juu yao, tutawatolea mnyama katika ardhi atakayewasemesha, ya kuwa watu walikuwa hawana yakini na Ishara zetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 83, 'Na Siku tutakapokusanya kutoka katika kila umma kundi miongoni mwa wale wanaokadhibisha Ishara zetu, nao watagawanywa mafungu mafungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 84, 'Hata watakapofika, (Mwenyezi Mungu) atasema: Je, nyinyi si mlizikanusha Ishara zangu pasipo kuzijua vyema? Au mlikuwa mkifanya nini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 85, 'Na kauli itawaangukia juu yao kwa vile walivyodhulumu. Basi hao hawatatamka lolote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 86, 'Je, hawaoni kwamba sisi tumeufanya usiku ili watulie, na mchana wa kuonea. Hakika katika hayo, zipo Ishara kwa watu wanaoamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 87, 'Na Siku litakapopulizwa baragumu, watahangaika waliomo mbinguni na katika ardhi, isipokuwa amtakaye Mwenyezi Mungu. Na wote watamfikia huku ni wanyonge.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 88, 'Na utaiona milima utaidhania imetulia; ilhali inakwenda kama mwendo wa mawingu. Huo ndio ufundi wa Mwenyezi Mungu aliyetengeneza sawasawa vilivyo kila kitu. Hakika Yeye anazo habari za yote myatendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 89, 'Mwenye kuja na uzuri, atapata bora kuliko huo. Nao watasalimika kutokana na mahangaiko ya Siku hiyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 90, 'Na atakayekuja na ubaya, basi zitasunukishwa nyuso zao Motoni. Je, kwani mnalipwa isipokuwa mliyokuwa mkiyatenda?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 91, 'Ama mimi, nimeamrishwa nimuabudu Mola Mlezi wa mji huu aliyeufanya ni mtakatifu; na ni vyake Yeye tu vitu vyote. Na nimeamrishwa niwe miongoni mwa Waislamu (wenye kunyenyekea).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 92, 'Na niisome Qur-ani. Na mwenye kuongoka, basi ameongoka kwa faida ya nafsi yake. Na mwenye kupotea, basi sema, "Hakika mimi ni miongoni mwa waonyaji."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 93, 'Na sema: Alhamdu lillaahi (Sifa njema zote ni za Mwenyezi Mungu). Yeye atawaonyesha Ishara zake, na mtazijua. Na Mola wako Mlezi si mwenye kughafilika mbali na hayo myatendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 1, 'Twa Sin Mim.[1]', '[1] Herufi hizi "Twa, Sin, Miim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 2, 'Hizi ni Aya za Kitabu kinachobainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 3, 'Tunakusomea katika habari za Musa na Firauni kwa Haki kwa ajili ya watu wanaoamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 4, 'Hakika Firauni alitakabari katika ardhi, na akawagawa wananchi makundi mbali mbali. Akalidhoofisha taifa moja miongoni mwao, akiwachinja watoto wao wanaume na akiwaacha hai watoto wao wanawake. Hakika yeye alikuwa katika waharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 5, 'Na tukataka kuwafadhili waliodhoofishwa katika ardhi na kuwafanya wawe waongozi na kuwafanya ni warithi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 6, 'Na kuwaimarisha katika ardhi, na kutokana na wao kuwaonyesha kina Firauni na Hamana na majeshi yao mambo yale waliyokuwa wakiyaogopa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 7, 'Tulimfunulia mama yake Musa kwa kumwambia: Mnyonyeshe. Na utakapomhofia, basi mtie mtoni, na usihofu wala usihuzunike. Hakika Sisi tutamrudisha kwako na tutamfanya miongoni mwa Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 8, 'Basi wakamwokota watu wa Firauni, aje kuwa adui kwao na huzuni. Hakika Firauni na Hamana na majeshi yao walikuwa wenye makosa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 9, 'Na mkewe Firauni alisema, "Atakuwa kiburudisho cha macho yangu na yako. Msimuuwe! Huenda akatufaa, au tumpange kuwa mwenetu." Wala wao hawakutambua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 10, 'Na (ufahamu wa) moyo wa mama yake Musa ukawa mtupu. Alikuwa karibu kumdhihirisha, ingelikuwa hatukumtia nguvu moyo wake ili awe miongoni mwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 11, 'Naye akamwambia dada yake Musa, "Mfuatie." Basi naye akawa anamuangalia kwa mbali bila ya wao kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 12, 'Na tukamjaalia awakatae wanyonyeshaji wote tangu mwanzo. Kwa hivyo, dada yake akasema, "Je, niwaonyesheni watu wa nyumba watakaomlelea huyu, nao pia watakuwa wema kwake?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 13, 'Basi tukamrudisha kwa mama yake ili macho yake yaburudike, wala asihuzunike. Na ajue ya kwamba ahadi ya Mwenyezi Mungu ni ya kweli, lakini wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 14, 'Na Musa alipofika utu uzima barabara, tulimpa akili na elimu. Na hivi ndivyo tunavyowalipa wazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 15, 'Na akaingia mjini wakati wa kughafilika wenyeji wake, na akakuta humo wanaume wawili wanapigana - mmoja ni katika watu wake, na mwingine katika maadui zake. Kwa hivyo, yule wa kutoka kwa watu wake akamtaka msaada kumpiga adui yake. Kwa hivyo, Musa akampiga ngumi, na akamuua. Akasema, "Hiki ni katika kitendo cha Shetani. Hakika yeye ni adui, mpotezaji dhahiri."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 16, 'Akasema, "Mola wangu Mlezi, hakika mimi nimejidhulumu mwenyewe. Basi nisamehe." Kwa hivyo, akamsamehe; hakika Yeye ni Mwingi wa kusamehe, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 17, 'Akasema, "Mola wangu Mlezi, kwa yale uliyonineemesha, basi mimi sitakuwa kabisa msaidizi wa wahalifu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 18, 'Akapambazukiwa mjini asubuhi naye ana hofu, akiangalia huku na huku. Mara yule yule aliyemtaka msaada jana akawa anamuita kwa sauti kubwa amsaidie. Musa akamwambia, "Hakika wewe ni mgomvi kweli kweli."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 19, 'Basi alipotaka kumshika kwa nguvu yule aliye adui wao wote wawili, akasema, "Ewe Musa, unataka kuniua kama ulivyomuuwa mwanamume jana? Wewe hutaki isipokuwa kuwa jabari katika ardhi, wala hutaki kuwa miongoni mwa wale watengenezao mambo."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 20, 'Na akaja mbio mwanamume mmoja kutoka sehemu ya mbali mno ya mji, akasema, "Ewe Musa! Hakika, wakubwa wanashauriana juu yako kukuua. Basi toka! Hakika mimi ni katika wanaokupa nasaha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 21, 'Basi akatoka humo, naye ana hofu, akiangalia huku na huku. Akasema, "Mola wangu Mlezi, niokoe kutokana na watu hawa madhalimu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 22, 'Na alipoelekea upande wa Madyana, alisema, "Huenda Mola wangu Mlezi akaniongoa njia iliyo sawa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 23, 'Na alipoyafikia maji ya Madyana, akakuta umati wa watu wananywesha (wanyama wao), na akakuta karibu yao wanawake wawili wanawazuia wanyama wao. Akasema, "Mna nini?" Wakasema, "Hatunyweshi sisi mpaka wamalize hao wachungaji. Na baba yetu ni mzee sana."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 24, 'Basi Musa akawanyweshea; kisha akarudi kivulini, na akasema, "Mola wangu Mlezi, hakika mimi ni mhitaji wa heri utakayoniteremshia."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 25, 'Basi mmoja katika wale wanawake wawili akamjia, naye anaona haya. Akasema, "Hakika baba yangu anakuita akulipe ujira wa kutunyweshea." Basi alipomjia na akamsimulia visa vyake, alisema, "Usihofu; umekwishaokoka kutokana na watu hao madhalimu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 26, 'Akasema mmoja katika wale wanawake, "Ewe baba yetu, muajiri huyu. Hakika mbora zaidi unayeweza kuajiri ni mwenye nguvu na muaminifu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 27, 'Akasema, "Hakika mimi ninataka kukuoza mmojawapo katika binti zangu hawa wawili kwa sharti kwamba unitumikie miaka minane. Lakini ukitimiza kumi, basi hiari ni yako. Nami sitaki kukutaabisha. Mwenyezi Mungu akipenda (Inshallah), utanikuta miongoni mwa watu wema."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 28, 'Musa akasema, "Hayo yamekwisha kuwa baina yangu na wewe. Muda mmojapo nikiumaliza, sitiwi ubayani. Na Mwenyezi Mungu ni Mtegemewa juu ya haya tunayoyasema."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 29, 'Basi Musa alipotimiza muda wake na akasafiri na ahali zake, aliona moto upande wa Mlima ''Turi. Akawaambia ahali zake, "Ngojeni! Hakika mimi nimeona moto. Labda nitawaletea kutoka huko habari au kijinga cha moto ili mpate kuota moto."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 30, 'Basi alipoufikia, aliitwa kutokea ng''ambo ya bonde la kuliani katika eneo lililobarikiwa kutoka kwenye mti, "Ewe Musa! Hakika Mimi ni Mwenyezi Mungu, Mola Mlezi wa walimwengu wote."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 31, 'Na tupa chini fimbo yako. Basi alipoiona ikitikisika kama nyoka, akarudi nyuma wala hakutazama. (Akaambiwa), "Ewe Musa, njoo mbele wala usihofu. Hakika wewe ni miongoni mwa walio katika amani."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 32, 'Ingiza mkono wako kwenye mfuko wako, utatoka mweupe pasipo na ubaya wowote. Na jiambatishe mkono wako ukihisi hofu. Basi hizi ni hoja mbili zitokazo kwa Mola wako Mlezi umpelekee Firauni na wakuu wa umma wake. Hakika hao walikuwa watu wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 33, 'Akasema, "Mola wangu Mlezi, hakika mimi nilimuua mtu katika wao, kwa hivyo ninahofu wataniua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 34, 'Na kaka yangu Harun ni fasaha zaidi ulimi wake kuliko mimi. Basi mtume pamoja nami kunisaidia, ili anisadikishe. Hakika mimi ninahofu watanikadhibisha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 35, '(Mwenyezi Mungu) akasema, "Tutautia nguvu mkono wako kwa kaka yako, na tutawapa mamlaka, kwa hivyo hawatawafikilia. Kwa sababu ya Ishara zetu, nyinyi na watakaowafuata ndio mtashinda."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 36, 'Basi Musa alipowafikia na Ishara zetu, walisema, "Haya si chochote isipokuwa ni uchawi uliozuliwa. Na hatukuyasikia haya kwa baba zetu wa zamani."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 37, 'Na Musa akasema, "Mola wangu Mlezi ni Mwenye kujua kabisa ni nani anayekuja na uongofu unaotoka kwake, na ni nani atakayekuwa na mwisho mwema wa makazi. Hakika wenye kudhulumu hawatafanikiwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 38, 'Na Firauni akasema, "Enyi waheshimiwa, sijawahi kujua kama mnaye mungu asiyekuwa mimi. Ewe Haman, niwashie moto unichomee udongo, unijengee mnara nipate kumchungulia mungu wa Musa. Na hakika mimi ninamwona yeye ni katika waongo."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 39, 'Na alipanda kiburi yeye na majeshi yake katika ardhi bila ya haki, na wakadhania kuwa hawatarudishwa kwetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 40, 'Basi tukamshika yeye na majeshi yake, na tukawatupa baharini. Basi hebu angalia ulikuwaje mwisho wa wenye kudhulumu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 41, 'Na tuliwafanya ni waongozi waitao kwenye Moto. Na Siku ya Kiyama hawatanusuriwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 42, 'Na tukawafuatishia laana katika dunia hii, na Siku ya Kiyama watakuwa miongoni mwa wanaochusha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 43, 'Na hakika bila ya shaka tulimpa Musa Kitabu baada ya kwisha kuziangamiza kaumu za mwanzo, ili kiwafumbue macho watu, na kiwe uongofu, na rehema, ili wapate kukumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 44, 'Wala wewe hukuwa upande wa magharibi tulipompa Musa amri, wala hukuwa katika waliohudhuria.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 45, 'Lakini Sisi tuliziumba kaumu, na ukawa mrefu umri juu yao. Wala hukuwa mkazi na watu wa Madyana ukiwasomea Aya zetu. Lakini ni Sisi tuliokuwa tukiwatuma Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 46, 'Wala hukuwa kando ya mlima ule tuliponadi. Lakini ni rehema itokayo kwa Mola wako Mlezi ili uwaonye watu wasiopata kufikiwa na mwonyaji kabla yako, huenda wakakumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 47, 'Na usije kuwasibu msiba kwa iliyoyatanguliza mikono yao, wakasema, "Ewe Mola wetu Mlezi, mbona hukututumia Mtume nasi, tukafuata Ishara zako, na tukawa miongoni mwa Waumini?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 48, 'Ilipowajia Haki kutoka kwetu, walisema, "Mbona hakupewa kama aliyopewa Musa?" Je, kwani wao hawakuyakataa aliyopewa Musa zamani? Walisema, "Ni wachawi wawili wanasaidiana." Na wakasema, "Hakika sisi tunawakataa wote."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 49, 'Sema, "Basi leteni Kitabu kinachotoka kwa Mwenyezi Mungu kilicho kiongofu zaidi kuliko hivi viwili nikifuate, kama nyinyi ni wakweli."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 50, 'Na ikiwa hawakuitikii, basi jua kuwa wanafuata matamanio yao tu. Na ni nani aliyepotea zaidi kumshinda anayefuata matamanio yake bila ya uongofu utokao kwa Mwenyezi Mungu? Hakika Mwenyezi Mungu hawaongoi watu wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 51, 'Na sasa kwa yakini tumewafikishia Neno moja baada ya lingine ili wapate kukumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 52, 'Wale tuliowapa Kitabu kabla yake wanakiamini hiki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 53, 'Na wanaposomewa, wanasema, "Tunaiamini. Hakika hii ndiyo Haki inayotoka kwa Mola wetu Mlezi. Hakika sisi kabla yake tulikuwa ni Waislamu, tulionyenyekea."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 54, 'Hao watapewa ujira wao mara mbili kwa walivyovumilia, na wakaondoa ubaya kwa wema, na wakatoa katika tulivyowaruzuku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 55, 'Na wanaposikia upuuzi, hujitenga nao na husema, "Sisi tuna vitendo vyetu, na nyinyi mna vitendo vyenu. Salamun Alaikum (Amani iwe juu yenu)! Sisi hatutaki kujibizana na wajinga."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 56, 'Kwa hakika, wewe humwongoi umpendaye. Lakini Mwenyezi Mungu humwongoa amtakaye. Na Yeye ndiye anawajua zaidi waongokao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 57, 'Na wakasema, "Tukiufuata uwongofu huu pamoja nawe, tutanyakuliwa kutoka nchi yetu." Je, kwani Sisi hatukuwaweka imara katika pahala patakatifu, penye amani, ambapo huletewa matunda ya kila aina kuwa ni riziki itokayo kwetu? Lakini wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 58, 'Na miji mingapi iliyojifahirisha katika maisha yao tumeiangamiza! Na hayo maskani yao hayakukaliwa tena baada yao, isipokuwa kwa uchache tu. Na Sisi ndio tumekuwa warithi wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 59, 'Na Mola wako Mlezi haangamizi miji mpaka ampeleke Mtume katika miji yake mikuu awasomee Ishara zetu. Wala hatuiangamizi miji mpaka watu wake wawe madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 60, 'Na chochote mlichopewa, ni matumizi ya maisha ya dunia na pambo lake. Na yaliyoko kwa Mwenyezi Mungu ndiyo bora na yatakayobaki zaidi. Basi je, hamfahamu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 61, 'Je, yule tuliyemuahidi ahadi nzuri, tena naye akayapata, ni kama tuliyemstarehesha kwa starehe za maisha ya duniani, na kisha Siku ya Kiyama akawa miongoni mwa wanaohudhurishwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 62, 'Na siku atakapowaita na akasema, "Wako wapi mliokuwa mkidai kuwa ni washirika wangu?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 63, 'Watasema wale iliyothibiti juu yao kauli, "Mola wetu Mlezi! Hawa ndio tuliowapoteza. Tuliwapoteza kama tulivyopotea sisi. Tunajitenga nao mbele yako. Hawakuwa wakituabudu sisi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 64, 'Na itasemwa, "Waiteni hao miungu wa kishirikina wenu!" Basi watawaita, lakini hawatawaitikia, na wataiona adhabu; laiti wangelikuwa wameongoka!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 65, 'Na siku atakapowaita na akasema, "Mliwajibu nini Mitume?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 66, 'Basi zitawapotea habari siku hiyo, nao hawataulizana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 67, 'Ama mwenye kutubu na akaamini na akatenda mema, huyo atakuwa miongoni mwa wenye kufaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 68, 'Na Mola wako Mlezi huumba na huteua atakavyo. Viumbe hawana hiari. Mwenyezi Mungu ametukuka na ametakasika na hao wanaowashirikisha naye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 69, 'Na Mola wako Mlezi anayajua viliyoyaficha vifua vyao, na wanayoyaweka hadharani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 70, 'Naye ni Mwenyezi Mungu ambaye hapana mungu isipokuwa Yeye. Sifa zote njema ni zake Yeye, mwanzo na mwisho. Na hukumu ni yake Yeye. Na kwake Yeye mtarejeshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 71, 'Sema: Mwaonaje, Mwenyezi Mungu angeliufanya usiku umekukalieni moja kwa moja mpaka Siku ya Kiyama, mungu gani asiyekuwa Mwenyezi Mungu atakayewaletea mwangaza? Basi je, hamsikii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 72, 'Sema: Mwaonaje, Mwenyezi Mungu angeliufanya mchana umewakalia moja kwa moja mpaka Siku ya Kiyama, mungu gani asiyekuwa Mwenyezi Mungu atayewaletea usiku mkapumzika humo? Basi je, hamwoni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 73, 'Na ni katika rehema zake amewafanyia usiku na mchana ili mpate kupumzika humo na mtafute fadhila zake, na ili mpate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 74, 'Na siku atakapowaita na akasema, "Wako wapi hao mliokuwa mkidai kuwa ni washirika wangu?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 75, 'Na tutatoa shahidi katika kila umma, na tutasema, "Leteni hoja zenu!" Hapo watajua kwamba hakika haki ni ya Mwenyezi Mungu, na yatawapotea yale waliyokuwa wakiyazua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 76, 'Hakika Qaruni alikuwa katika watu wa Musa, lakini aliwafanyia dhuluma. Na tulimpa hazina ambazo funguo zake zinawatopeza watu wenye nguvu kuzibeba. Watu wake walipomwambia, "Usijigambe! Hakika Mwenyezi Mungu hawapendi wanaojigamba."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 77, 'Na utafute, kwa aliyokupa Mwenyezi Mungu, makazi ya Akhera. Wala usisahau fungu lako la duniani. Nawe fanya wema kama Mwenyezi Mungu alivyokufanyia wema wewe. Wala usitafute kufanya uharibifu katika ardhi. Hakika Mwenyezi Mungu hawapendi wafanyao uharibifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 78, 'Akasema, "Kwa hakika nimepewa haya kwa sababu ya elimu niliyo nayo." Je, hakujua kwamba Mwenyezi Mungu alikwisha waangamiza, katika vizazi vya walio kabla yake, watu waliokuwa wenye nguvu zaidi kuliko yeye, na wenye makundi makubwa zaidi kuliko yake. Na wahalifu hawataulizwa habari ya dhambi zao."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 79, 'Basi akawatokea watu wake katika pambo lake. Wakasema wale waliokuwa wanataka maisha ya duniani, "Laiti tungelikuwa tunayo kama aliyopewa Qaruni! Hakika yeye ni mwenye bahati kubwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 80, 'Na wakasema wale waliopewa elimu, "Ole wenu! Malipo ya Mwenyezi Mungu ni bora kwa mwenye kuamini na akatenda mema. Wala hawatapewa hayo isipokuwa wenye subira."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 81, 'Basi tukamdidimiza yeye na nyumba yake katika ardhi; wala halikuwepo kundi lolote la kumnusuru kando na Mwenyezi Mungu, wala hakuwa miongoni mwa wanaojinusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 82, 'Na wale waliotamani kuwa pahala pake jana, wakawa wanasema, "Kumbe Mwenyezi Mungu humkunjulia riziki amtakaye katika waja wake, na humkunjia amtakaye. Ingelikuwa Mwenyezi Mungu hakutufanyia hisani, angelitudidimiza. Kumbe makafiri hawafanikiwi!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 83, 'Hayo ndiyo makazi ya Akhera, tumewafanyia wale wasiotaka kujiinua juu katika dunia wala uharibifu. Na mwisho mwema ni wa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 84, 'Atakayetenda mazuri, atapata malipo bora kuliko hayo mazuri aliyoyatenda. Na atakayetenda mabaya, hawalipwi watendao mabaya isipokuwa yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 85, 'Hakika yule aliyekulazimisha kuifuata Qur-ani, hapana shaka atakurudisha pahala pa marejeo. Sema, "Mola wangu Mlezi ndiye anayemjua zaidi mwenye kuja na uongofu, na ni nani aliyemo katika upotovu ulio dhahiri."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 86, 'Nawe hukuwa unataraji kuletewa Kitabu; lakini ni rehema tu ya Mola wako Mlezi. Basi kamwe usiwe msaidizi wa makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 87, 'Wala kamwe wasikuzuie kuzifuata Aya za Mwenyezi Mungu baada ya kuteremshiwa wewe. Na lingania kwa Mola wako Mlezi, wala kamwe usiwe miongoni mwa washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 88, 'Wala usimwombe pamoja na Mwenyezi Mungu mungu mwinginewe. Hapana mungu isipokuwa Yeye. Kila kitu kitaangamia isipokuwa uso wake. Hukumu ni yake, na kwake mtarejeshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 1, 'Alif Lam Mim.[1]', '[1] Herufi hizi "Alif, Laam, Miim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 2, 'Je, watu wanadhani kwamba wataachwa kwa kuwa wanasema, "Tumeamini." Nao wasijaribiwe?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 3, 'Hakika tuliwajaribu waliokuwa kabla yao, na kwa yakini Mwenyezi Mungu atawatambulisha wale walio wakweli na atawatambulisha waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 4, 'Au wale wanaotenda maovu wanadhani kwamba watatushinda? Ni hukumu mbaya mno hiyo wanayohukumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 5, 'Mwenye kutaraji kukutana na Mwenyezi Mungu, basi hakika miadi ya Mwenyezi Mungu itafika bila ya shaka. Naye ni Mwenye kusikia, Mwenye kujua zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 6, 'Na anayefanya juhudi, basi bila ya shaka anafanya juhudi kwa ajili ya nafsi yake. Hakika Mwenyezi Mungu si mhitaji wa walimwengu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 7, 'Na wale walioamini na wakatenda mema, kwa yakini tutawafutia makosa yao, na bila shaka tutawalipa bora ya waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 8, 'Na tumemuusia mwanadamu kuwafanyia wema wazazi wake. Na ikiwa watapambana nawe ili unishirikishe Mimi na yale usiyokuwa na elimu nayo, basi usiwatii. Kwangu Mimi ndiyo marejeo yenu, na nitawaambia yale mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 9, 'Na wale walioamini na wakatenda mema, bila ya shaka tutawatia miongoni mwa watu wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 10, 'Na katika watu yupo yule anayesema, "Tumemuamini Mwenyezi Mungu." Lakini anapopewa maudhi kwa sababu ya Mwenyezi Mungu, anayafanya mateso ya watu kama ni adhabu ya Mwenyezi Mungu. Na inapokuja nusura kutoka kwa Mola wako Mlezi, kwa yakini husema, "Hakika sisi tulikuwa pamoja nanyi." Kwani Mwenyezi Mungu hayajui zaidi yaliyomo vifuani mwa walimwengu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 11, 'Na hapana shaka Mwenyezi Mungu atawajua wale walioamini, na atawajua wanafiki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 12, 'Na wale waliokufuru waliwaambia wale walioamini, "Fuateni njia yetu, nasi tutayabeba makosa yenu." Wala wao hawatabeba katika makosa yao chochote kile. Hakika hao ni waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 13, 'Na hapana shaka wataibeba mizigo yao na mizigo mingine pamoja na mizigo yao. Na kwa yakini wataulizwa Siku ya Kiyama juu ya yale waliyokuwa wakiyazua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 14, 'Na hakika tulimtuma Nuhu kwa watu wake, na akakaa nao miaka elfu kasoro miaka hamsini. Basi tufani ikawachukua, nao ni madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 15, 'Nasi tukamwokoa yeye na wenziwe wa katika safina, na tukaifanya kuwa ni Ishara kwa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 16, 'Na Ibrahim pale alipowaambia watu wake, "Muabuduni Mwenyezi Mungu, na mcheni Yeye. Hiyo ndiyo heri yenu, ikiwa nyinyi mnajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 17, 'Hakika nyinyi mnaabudu tu masanamu badala ya Mwenyezi Mungu, na mnazua uzushi. Hakika hao mnaowaabudu badala ya Mwenyezi Mungu hawawamilikii riziki yoyote. Basi tafuteni riziki kutoka kwa Mwenyezi Mungu, na mumuabudu Yeye, na mumshukuru Yeye. Kwake Yeye ndiko mtarudishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 18, 'Na mkikadhibisha, basi kaumu kadhaa wa kadhaa za kabla yenu zilikwisha kadhibisha. Na si juu ya Mtume isipokuwa kufikisha Ujumbe waziwazi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 19, 'Je, wao hawaoni jinsi Mwenyezi Mungu anavyoanzisha uumbaji, na kisha akaurudisha tena. Hakika hayo kwa Mwenyezi Mungu ni mepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 20, 'Sema: Tembeeni katika ardhi na tazameni jinsi alivyoanzisha uumbaji; kisha Mwenyezi Mungu ndiye anayeumba umbo la baadaye. Hakika Mwenyezi Mungu ni Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 21, 'Humuadhibu amtakaye, na humrehemu amtakaye. Na kwake Yeye mtapelekwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 22, 'Na nyinyi si wenye kushinda katika ardhi wala katika mbingu. Wala nyinyi hamna mlinzi wala msaidizi isipokuwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 23, 'Na wale waliozikanusha Ishara za Mwenyezi Mungu na kukutana naye, hao ndio waliokata tamaa na rehema yangu, na hao ndio wana adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 24, 'Basi haikuwa jawabu ya watu wake isipokuwa walisema, "Muueni au mchomeni moto!" Kwa hivyo, Mwenyezi Mungu akamwokoa kutokana na moto huo. Hakika katika hayo zipo Ishara kwa watu wanaoamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 25, 'Na alisema, "Hakika nyinyi mmeyashika masanamu (kuyaabudu) badala ya Mwenyezi Mungu kwa mapenzi yaliyo baina yenu katika uhai wa duniani. Kisha Siku ya Kiyama mtakataana nyinyi kwa nyinyi, na mtalaaniana nyinyi kwa nyinyi. Na makazi yenu ni Motoni. Wala hamtapata wa kukunusuru wowote."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 26, 'Luti akamuamini, na akasema, "Hakika mimi nahamia kwa Mola wangu Mlezi. Hakika Yeye ndiye Mwenye nguvu, Mwenye hekima."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 27, 'Na tulimtunukia (Ibrahim) Is-haq na Yaa''qub. Na tukajaalia katika dhuria zake Unabii na Kitabu, na tukampa ujira wake katika dunia; naye hakika katika Akhera bila ya shaka ni katika watu wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 28, 'Na pale Luti alipowaambia watu wake, "Hakika nyinyi mnafanya uchafu, ambao hapana mmoja katika walimwengu aliyewatangulia kwa hayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 29, 'Je, nyinyi mnawaingilia wanaume, na mnaikata njia? Na katika mikutano yenu mnafanya maovu?" Basi haikuwa jawabu ya watu wake isipokuwa walisema, "Tuletee hiyo adhabu ya Mwenyezi Mungu ikiwa wewe ni katika wakweli."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 30, 'Akasema, "Ewe Mola wangu Mlezi, ninusuru kutokana na watu waharibifu hawa!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 31, 'Na wajumbe wetu walipomjia Ibrahim na bishara, walisema, "Hakika sisi hapana shaka tutawaangamiza watu wa mji huu, kwani watu wake hakika wamekuwa madhalimu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 32, 'Akasema, "Hakika humo yumo Luti." Wao wakasema, "Sisi tunajua zaidi ni nani yumo humo. Hapana shaka tutamwokoa yeye na ahali zake, isipokuwa mkewe aliye miongoni mwa watakaokaa nyuma."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 33, 'Na wajumbe wetu walipomfikia Luti, alihuzunika kwa sababu yao, na moyo ukaona dhiki kubwa kwa sababu yao. Wakasema, "Usihofu, wala usihuzunike. Hakika sisi tutakuokoa wewe na ahali zako, isipokuwa mkeo aliye miongoni mwa watakaokaa nyuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 34, 'Kwa yakini sisi tutawateremshia watu wa mji huu adhabu kutoka mbinguni kwa sababu ya kuvuka kwao mipaka."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 35, 'Na hakika tumeacha katika mji huo Ishara iliyo wazi kwa watu wanaotumia akili zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 36, 'Na kwa Madyana tulimtuma ndugu yao Shuaibu, naye akasema, "Enyi watu wangu, muabuduni Mwenyezi Mungu na iogopeni Siku ya Akhera, wala msiende katika ardhi mkifanya uharibifu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 37, 'Lakini walimkadhibisha, basi ukawatwaa mtikiso wa ardhi, wakapambazukiwa ndani ya nyumba zao nao wameanguka kifudifudi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 38, 'Na pia kina A''di na Thamud. Nanyi yamekwisha wabainikia kutokana na maskani zao. Na Shetani aliwapambia vitendo vyao, na akawazuilia Njia, na hali walikuwa wenye kuona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 39, 'Na pia Qaruni na Firauni na Hamana! Na Musa aliwajia kwa Ishara waziwazi, lakini walijivuna katika nchi, wala hawakuweza kushinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 40, 'Basi kila mmoja tulimtesa kwa mujibu wa makosa yake. Kati yao wapo tuliowapelekea kimbunga cha changarawe; na kati yao wapo walionyakuliwa na ukelele; na kati yao wapo ambao tuliwadidimiza katika ardhi; na kati yao wapo tuliowazamisha. Wala Mwenyezi Mungu hakuwa mwenye kuwadhulumu, lakini walikuwa wenyewe wakijidhulumu nafsi zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 41, 'Mfano wa wale waliowafanya walinzi badala ya Mwenyezi Mungu, ni mfano wa buibui alivyojitandia nyumba. Na hakika nyumba dhaifu mno kuliko zote ni jumba la buibui, laiti kuwa wanajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 42, 'Kwa hakika Mwenyezi Mungu anajua kila kitu wanachokiomba badala yake Yeye. Na Yeye ndiye Mtukufu Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 43, 'Na hiyo ni mifano tunawapigia watu, na hawaifahamu isipokuwa wenye elimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 44, 'Mwenyezi Mungu ameumba mbingu na ardhi kwa Haki. Kwa hakika katika hayo ipo Ishara kwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 45, 'Soma yale uliyofunuliwa katika Kitabu, na ushike Swala. Hakika Swala inazuilia mambo machafu na maovu. Na kwa yakini kumdhukuru Mwenyezi Mungu ndilo jambo kubwa kabisa. Na Mwenyezi Mungu anayajua mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 46, 'Wala msijadiliane na Watu wa Kitabu isipokuwa kwa njia iliyo nzuri kabisa, isipokuwa wale waliodhulumu miongoni mwao. Na semeni, "Tumeyaamini yaliyoteremshwa kwetu na yaliyoteremshwa kwenu. Na mungu wetu na mungu wenu ni Mmoja. Na sisi ni wenye kusilimu kwake."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 47, 'Na namna hivyo tumekuteremshia Kitabu hiki (Qur-ani). Basi wale tuliowapa Kitabu (cha Biblia) wataiamini (Qur-ani), na miongoni mwa hawa (washirikina) wapo watakaoiamini. Na hawazikatai Ishara zetu isipokuwa makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 48, 'Na wewe hukuwa kabla yake unasoma kitabu chochote, wala hukukiandika kwa mkono wako wa kulia. Ingelikuwa hivyo, wana batili wangelifanya shaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 49, 'Bali hii (Qur-ani) ni Ishara zilizo wazi katika vifua vya wale waliopewa elimu. Na hawazikatai Ishara zetu isipokuwa madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 50, 'Na walisema, "Mbona hakuteremshiwa Ishara kutoka kwa Mola wake Mlezi?" Sema, "Hakika Ishara ziko tu kwake Mwenyezi Mungu; ama mimi kwa hakika ni mwonyaji mwenye kubainisha tu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 51, 'Je, kwani hayakuwatosha ya kwamba tumekuteremshia Kitabu hiki wanachosomewa? Hakika katika hayo, zipo rehema na mawaidha kwa watu wanaoamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 52, 'Sema, "Mwenyezi Mungu anatosha kuwa ni Shahidi kati yangu na nyinyi. Anayajua yaliyo katika mbingu na ardhi. Na wale wanaoiamini batili na wakamkufuru Mwenyezi Mungu, hao ndio waliohasiri."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 53, 'Na wanakuhimiza waletewe adhabu kwa haraka. Na lau kuwa hapana wakati maalumu uliowekwa, basi adhabu ingeliwajia, na ingeliwatokea kwa ghafla ilhali wao hawana habari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 54, 'Wanakuhimiza waletewe adhabu kwa haraka, na hali Jahannamu kwa hakika imewazunguka makafiri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 55, 'Siku itakapowafunika adhabu hiyo kutoka juu yao na chini ya miguu yao, na atasema, "Onjeni hayo mliyokuwa mkiyatenda!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 56, 'Enyi waja wangu mlioamini! Kwa hakika ardhi yangu ina wasaa. Basi niabuduni Mimi peke yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 57, 'Kila nafsi itaonja mauti. Kisha mtarudishwa kwetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 58, 'Na ambao wameamini na wakatenda mema, bila ya shaka tutawaweka katika maghorofa ya Bustani ya mbinguni yenye kupitiwa chini yake mito, wakidumu humo. Ni mzuri ulioje huo ujira wa watendao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 59, 'Ambao walisubiri, na wakamtegemea Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 60, 'Na ni wanyama wangapi hawawezi kujimilikia riziki zao! Mwenyezi Mungu anawaruzuku hao na nyinyi pia. Na Yeye ndiye Mwenye kusikia Mwenye kujua zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 61, 'Na ukiwauliza; ni nani aliyeumba mbingu na ardhi na akafanya jua na mwezi kutiii amri yake? Bila ya shaka, watasema: Mwenyezi Mungu. Wapi basi wanakogeuzwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 62, 'Mwenyezi Mungu humkunjulia, na humkunjia riziki amtakaye katika waja wake. Kwa hakika Mwenyezi Mungu anajua zaidi kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 63, 'Na ukiwauliza: Ni nani anayeteremsha maji kutoka mbinguni, na akaihuisha ardhi baada ya kufa kwake? Bila ya shaka watasema: Ni Mwenyezi Mungu. Sema: Alhamdu Lillahi (Sifa njema zote ni za Mwenyezi Mungu). Bali wengi katika wao hawatumii akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 64, 'Na haya maisha ya dunia si chochote isipokuwa ni pumbao na mchezo. Na hakika nyumba ya Akhera ndiyo maisha hasa; laiti wangelikuwa wanajua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 65, 'Na wanapopanda katika marikebu, humwomba Mwenyezi Mungu kwa kumkusudia yeye tu dini yake. Lakini anapowavua wakafika nchi kavu, mara wanamshirikisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 66, 'Wapate kuyakufuru yale tuliyowapa, na wajistareheshe. Lakini watakuja jua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 67, 'Je, hawaoni ya kwamba tumeifanya nchi takatifu ina amani, na hali watu wengine wananyakuliwa kote kwa majirani zao? Je, wanaamini batili, na neema za Mwenyezi Mungu wanazikufuru?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 68, 'Na ni nani dhalimu mkubwa kuliko yule anayemzulia uongo Mwenyezi Mungu au anayekadhibisha Haki inapomjia? Je, si katika Jahannamu ndiyo yatakuwa makazi ya makafiri?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 69, 'Na wale wanaofanya juhudi kwa ajili yetu, Sisi hakika tutawaongoa kwenye njia zetu. Na hakika Mwenyezi Mungu yu pamoja na watu wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 1, 'Alif Lam Mim.[1]', '[1] Herufi hizi "Alif Laam Miim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 2, 'Warumi wameshindwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 3, 'Katika nchi iliyo karibu. Nao baada ya kushindwa kwao watashinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 4, 'Katika miaka michache. Amri ni ya Mwenyezi Mungu kabla yake na baada yake. Na siku hiyo Waumini watafurahi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 5, 'Kwa nusura ya Mwenyezi Mungu, humnusuru amtakaye. Naye ndiye Mwenye nguvu, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 6, 'Ni ahadi ya Mwenyezi Mungu. Mwenyezi Mungu havunji ahadi yake. Lakini wengi wa watu hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 7, 'Wanajua hali ya dhahiri ya maisha ya dunia, na wameghafilika na Akhera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 8, 'Je, hawajifikirii nafsi zao? Mwenyezi Mungu hakuumba mbingu na ardhi na vilivyo kati yake isipokuwa kwa Haki na kwa muda maalumu. Na hakika watu wengi bila ya shaka ni wenye kukufuru kuwa watakutana na Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 9, 'Je, hawatembei katika ardhi wakaona ulivyokuwa mwisho wa wale waliokuwa kabla yao? Nao walikuwa na nguvu zaidi kuliko wao, na wakaitimbua ardhi na wakaistawisha zaidi kuliko walivyoistawisha wao. Na Mitume wao wakawajia na ushahidi wa wazi. Basi hakuwa Mwenyezi Mungu ni mwenye kuwadhulumu, lakini wenyewe walikuwa wakijidhulumu nafsi zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 10, 'Kisha ulikuwa mwisho wa wale waliofanya ubaya ni mbaya zaidi kwa sababu walizikadhibisha Ishara za Mwenyezi Mungu, na wakawa wanazifanyia stihizai.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 11, 'Mwenyezi Mungu huanzisha uumbaji, tena akaurudisha mara ya pili, na kisha mtarejeshwa kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 12, 'Na siku itakaposimama Saa ya Kiyama, wahalifu watakata tamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 13, 'Wala hawatakuwa na waombezi wowote miongoni mwa wale waliokuwa wakiwashirikisha na Mwenyezi Mungu; na wao wenyewe watawakataa hao washirikishwa wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 14, 'Na siku itakaposimama Saa ya Kiyama, siku hiyo watatengana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 15, 'Ama wale walioamini na wakatenda mema, watafurahishwa katika Bustani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 16, 'Na ama wale waliokufuru na wakazikanusha Ishara zetu na mkutano wa Akhera, hao basi watahudhurishwa katika adhabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 17, 'Basi Subhanallah (Mtakaseni Mwenyezi Mungu) jioni na asubuhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 18, 'Na sifa zote njema ni zake katika mbingu na ardhi, na alasiri na adhuhuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 19, 'Hukitoa kilicho hai kutokana na kilichokufa, na hukitoa kilichokufa kutokana na kilicho hai. Na huihuisha ardhi baada ya kufa kwake. Na kama hivyo ndivyo mtavyofufuliwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 20, 'Na katika Ishara zake ni kuwa aliwaumba kwa udongo. Kisha mmekuwa watu mliotawanyika kote kote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 21, 'Na katika Ishara zake ni kuwa aliwaumbia wake zenu kutokana na nafsi zenu ili mpate utulivu kwao. Naye ameweka mapenzi na rehema baina yenu. Hakika katika haya bila ya shaka zipo Ishara kwa watu wanaotafakari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 22, 'Na katika Ishara zake ni kuumba mbingu na ardhi, na kutofautiana ndimi zenu na rangi zenu. Hakika katika hayo zipo Ishara kwa wajuao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 23, 'Na katika Ishara zake ni kulala kwenu usiku na mchana, na kutafuta kwenu fadhila zake. Hakika katika haya bila ya shaka zipo Ishara kwa watu wanaosikia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 24, 'Na katika Ishara zake huwaonyesha umeme kwa kuwatia hofu na tamaa. Na huwateremshia maji kutoka mbinguni, na kwa hayo huifufua ardhi baada ya kufa kwake. Hakika katika hayo zipo Ishara kwa watu watumiao akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 25, 'Na katika Ishara zake ni kuwa mbingu na ardhi zimesimama kwa amri yake. Kisha atakapowaita mwito mmoja tu, hapo mtatoka kwenye ardhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 26, 'Na ni vyake Yeye vilivyo mbinguni na katika ardhi. Vyote vinamtii Yeye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 27, 'Na Yeye ndiye anayeanzisha uumbaji, kisha ataurudisha mara nyingine. Na jambo hili ni jepesi zaidi kwake. Naye ndiye mwenye mfano bora zaidi katika mbingu na ardhi. Na Yeye ndiye Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 28, 'Amewapigia mfano kutokana na nafsi zenu. Je, katika hao iliyowamiliki mikono yenu ya kulia mnao washirika katika hivyo tulivyowaruzuku, mkawa nyinyi katika hivyo ni sawasawa, mnawaogopa kama mnavyoogopana wenyewe kwa wenyewe? Namna hivyo tunazipambanua Aya zetu kwa watu watumiao akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 29, 'Bali waliodhulumu wamefuata mapendo ya nafsi zao pasina kujua. Basi ni nani atamwongoa ambaye Mwenyezi Mungu amempoteza? Wala hao hawatakuwa na wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 30, 'Basi uelekeze uso wako sawasawa kwenye Dini kwa unyoofu, ndilo umbile la Mwenyezi Mungu alilowaumbia watu. Hapana mabadiliko katika uumbaji wa Mwenyezi Mungu. Hiyo ndiyo Dini iliyonyooka sawa. Lakini watu wengi hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 31, 'Muwe wenye kutubia kwake, na mcheni Yeye, na simamisheni Swala, na wala msiwe katika washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 32, 'Katika wale ambao kwamba wameigawanya dini yao, na wakawa makundi makundi, kila kikundi kinafurahia kilicho nacho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 33, 'Na watu wanapoguswa na madhara, humwomba Mola wao Mlezi huku wanatubu kwake. Kisha akiwaonjesha rehema itokayo kwake, mara kikundi miongoni mwao humshirikisha Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 34, 'Kwa kuyakufuru yale tuliyowapa. Basi stareheni. Mtakuja jua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 35, 'Au tumewateremshia hoja ambayo inazungumza juu ya kile walichokuwa wakishirikisha nacho?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 36, 'Na tunapowaonjesha watu rehema, huifurahia. Na ukiwasibu ubaya kwa iliyoyatanguliza mikono yao wenyewe, mara wanakata tamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 37, 'Kwani hawaoni kwamba Mwenyezi Mungu humkunjulia riziki amtakaye na humkunjia amtakaye? Hakika katika hayo, zipo Ishara kwa watu wanaoamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 38, 'Basi mpe jamaa haki yake, na masikini, na msafiri. Hayo ni heri kwa wanaotaka uso wa Mwenyezi Mungu. Na hao ndio waliofaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 39, 'Na mnachokitoa kwa riba ili kiongezeke katika mali ya watu, basi hakiongezeki mbele ya Mwenyezi Mungu. Lakini mnachokitoa kwa Zaka kwa kutaka uso wa Mwenyezi Mungu, basi hao ndio watakaozidishiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 40, 'Mwenyezi Mungu ndiye aliyewaumba, kisha akawaruzuku, kisha atawafisha, na kisha atawafufua. Je, yupo yeyote katika hao mnaowashirikisha na Mwenyezi Mungu afanyae lolote katika hayo? Yeye ametakasika, na ametukuka mbali na hayo mnayomshirikisha naye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 41, 'Uharibifu umedhihiri barani na baharini kwa yale iliyoyafanya mikono ya watu, ili Mwenyezi Mungu awaonjeshe baadhi ya yale waliyoyatenda. Huenda wakarejea kwa kutubu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 42, 'Sema: Safirini duniani na muangalie ulikuwaje mwisho wa wale waliotangulia. Wengi wao walikuwa washirikina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 43, 'Basi uelekeze uso wako sawasawa kwenye Dini iliyonyooka kabla ya kufika Siku hiyo isiyozuilika, inayotoka kwa Mwenyezi Mungu. Siku hiyo watu watatengana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 44, 'Anayekufuru, basi ukafiri wake utakuwa juu yake mwenyewe. Na anayetenda mema, basi wanazitengenezea nafsi zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 45, 'Ili awalipe wale walioamini na wakatenda mema kutokana na fadhila yake. Hakika Yeye hawapendi makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 46, 'Na katika Ishara zake ni kuzituma pepo ziletazo bishara njema, na ili kuwaonjesha baadhi ya rehema zake, na ili majahazi yaende kwa amri yake; na mtafute kutokana na fadhila yake, na ili mumshukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 47, 'Na hakika tulikwishawatuma Mitume kabla yako kwa kaumu zao, na wakawajia kwa hoja zilizo wazi. Tukawaadhibu wale waliofanya uhalifu. Na ilikuwa ni haki juu yetu kuwanusuru Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 48, 'Mwenyezi Mungu ndiye anayezituma pepo zikayatimua mawingu, kisha akayatandaza mbinguni kama apendavyo. Na akayafanya mapande mapande, basi ukaiona mvua inatoka ndani yake. Anapowafikishia awatakao katika waja wake, mara hao huwa na furaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 49, 'Na ingawa kabla ya kuteremshiwa walikuwa wenye kukata tamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 50, 'Basi ziangalie athari za rehema ya Mwenyezi Mungu, jinsi anavyoihuisha ardhi baada ya kufa kwake. Basi hakika huyo ndiye bila ya shaka mwenye kuhuisha wafu. Na Yeye ni Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 51, 'Na tungeutuma upepo na wakauona umekuwa rangi ya manjano, juu ya hayo wangeendelea kukufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 52, 'Kwani wewe hakika huwafanyi maiti wakasikia, wala viziwi wakasikia wito wakishageuka kukupa mgongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 53, 'Wala wewe huwaongoi vipofu kutoka katika upotovu wao. Huwasikilizishi isipokuwa wale wanaoziamini Aya zetu. Hao ndio Waislamu, walionyenyekea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 54, 'Mwenyezi Mungu ndiye aliyewaumba kutokana na udhaifu, kisha akajaalia nguvu baada ya unyonge, kisha akajaalia baada ya nguvu unyonge tena na ukongwe. Anaumba atakavyo. Naye ndiye ajuaye zaidi, Mwenye uweza wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 55, 'Na siku itakaposimama Saa ya Kiyama, wahalifu wataapa kwamba hawakukaa duniani isipokuwa saa moja tu. Hivyo ndivyo walivyokuwa wakipotoshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 56, 'Na wale waliopewa elimu na Imani watasema: Hakika nyinyi mlikwishakaa katika hukumu ya Mwenyezi Mungu mpaka Siku ya kufufuliwa. Basi hii ndiyo Siku ya kufufuliwa! Lakini nyinyi mlikuwa hamuijui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 57, 'Basi Siku hiyo hautawafaa wale waliodhulumu udhuru wao, wala haitatakiwa toba yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 58, 'Na hakika tulikwisha wapigia watu kila mfano katika hii Qur-ani. Na ukiwaletea Ishara yoyote, hapana shaka wale waliokufuru watasema, "Nyinyi si chochote isipokuwa ni wana batili."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 59, 'Hivi ndivyo Mwenyezi Mungu anavyoziba kwenye nyoyo za wale wasiojua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 60, 'Basi subiri. Hakika ahadi ya Mwenyezi Mungu ni ya haki. Wala kamwe wasikupaparishe hao wasiokuwa na yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 1, 'Alif Laam Miim.[1]', '[1] Herufi hizi "Alif Laam Miim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 2, 'Hizi ni Aya za Kitabu chenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 3, 'Kuwa ni uongofu na rehema kwa wafanyao wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 4, 'Wale wanaoshika Swala, na wanatoa Zaka, nao wana yakini na Akhera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 5, 'Hao ndio walio kwenye uongofu utokao kwa Mola wao Mlezi, na hao ndio waliofaulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 6, 'Na miongoni mwa watu wapo wanaonunua maneno ya upuuzi, ili wawapoteze watu mbali na njia ya Mwenyezi Mungu pasipo kujua, na wanaichukulia ni masihara. Hao watapata adhabu ya kuwafedhehesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 7, 'Na mtu kama huyo anaposomewa Aya zetu, huzipa mgongo kwa kujivuna, kana kwamba hakuzisikia, au masikioni mwake mna uziwi. Basi mbashirie kuwa atapata adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 8, 'Hakika walioamini na wakatenda mema watakuwa na Bustani za neema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 9, 'Watadumu humo, ni ahadi ya Mwenyezi Mungu ya kweli. Na Yeye ndiye Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 10, 'Ameziumba mbingu bila ya nguzo mnazoziona, na ameweka katika ardhi milima ili ardhi isiwayumbishe, na ametawanya humo kila namna ya wanyama, na tumeteremsha maji kutoka mbinguni, na tukaotesha katika ardhi mimea mizuri ya kila namna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 11, 'Huu ni uumbaji wa Mwenyezi Mungu. Basi nionyesheni wameumba nini hao wasiokuwa Yeye! Lakini madhalimu wamo katika upotovu ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 12, 'Na tulimpa Luqman hekima, tukamwambia; "Mshukuru Mwenyezi Mungu." Na mwenye kushukuru, basi hakika anashukuru kwa manufaa ya nafsi yake. Na aliyekufuru, basi Mwenyezi Mungu ni Mkwasi, Msifiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 13, 'Na Luqman alipomwambia mwanawe kwa kumpa mawaidha, "Ewe mwanangu, usimshirikishe Mwenyezi Mungu. Kwani, hakika ushirikina bila ya shaka ni dhuluma iliyo kubwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 14, 'Na tumemuusia mtu kwa wazazi wake wawili. Mama yake ameichukua mimba yake kwa udhaifu juu ya udhaifu, na kumwachisha ziwa baada ya miaka miwili. Tumemuusia, "Nishukuru Mimi na wazazi wako. Ni kwangu Mimi ndiyo marejeo yenu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 15, 'Na pindi wakikushikilia kunishirikisha na ambayo huna elimu nayo, basi usiwatii. Lakini kaa nao kwa wema duniani, nawe ishike njia ya anayeelekea kwangu. Kisha marejeo yenu ni kwangu Mimi, na Mimi nitawaambia yale mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 16, '"Ewe mwanangu, kikiwapo kitu cha uzito wa chembe ya khardali kikawa ndani ya jabali au ndani ya mbingu au ndani ya ardhi, basi Mwenyezi Mungu atakileta. Hakika Mwenyezi Mungu ni Mjuzi wa yaliyofichika, Mwenye habari za yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 17, 'Ewe mwanangu, shika Swala, na amrisha mema, na kataza maovu, na subiri kwa yanayokupata. Hayo ni katika mambo ya kuazimiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 18, 'Wala usiwabeuwe watu, wala usitembee katika nchi kwa maringo. Hakika Mwenyezi Mungu hampendi kila anayejivuna na kujifakhirisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 19, 'Na kuwa wa hali ya katikati katika kutembea kwako, na teremsha chini sauti yako. Hakika katika sauti mbaya kuliko zote ni sauti ya punda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 20, 'Kwani hamwoni ya kwamba Mwenyezi Mungu amevifanya vikutumikieni vilivyomo mbinguni na kwenye ardhi, na akakujalizieni neema zake, za dhahiri na za siri? Na miongoni mwa watu wapo wanaobishana juu ya Mwenyezi Mungu pasipo elimu, wala uongofu, wala Kitabu chenye nuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 21, 'Na wanapoambiwa, "Fuateni aliyoyateremsha Mwenyezi Mungu," husema: "Bali tunafuata tuliyowakuta nayo baba zetu". Je, hata kama Shetani anawaita kwenye adhabu ya Moto wenye mwako mkali?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 22, 'Na mwenye kuuelekeza uso wake kwa Mwenyezi Mungu, naye akawa anafanya wema, basi huyo hakika amekwisha kamata fundo lililo madhubuti. Na mwisho wa mambo yote ni kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 23, 'Na anayekufuru, isikuhuzunishe kufuru yake. Kwetu ndiyo marudio yao, na hapo tutawaambia waliyoyatenda. Hakika Mwenyezi Mungu ni Mjuzi wa yaliyomo vifuani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 24, 'Tunawastarehesha kwa uchache, kisha tutawasukuma kwenye adhabu ngumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 25, 'Na ukiwauliza nani aliyeziumba mbingu na ardhi? Bila shaka watasema, Mwenyezi Mungu. Wewe sema Alhamdulillahi! Sifa njema zote ni za Mwenyezi Mungu. Lakini wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 26, 'Ni vya Mwenyezi Mungu vyote vilivyomo mbinguni na katika ardhi. Hakika Mwenyezi Mungu ndiye Mkwasi, Mwenye kusifiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 27, 'Na lau kuwa miti yote iliyomo duniani ikawa ni kalamu, na bahari ikawa wino, na ikaongezewa juu yake bahari nyengine saba, maneno ya Mwenyezi Mungu yasingelikwisha. Hakika Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 28, 'Hakukuwa kuumbwa kwenu, wala kufufuliwa kwenu ila ni kama nafsi moja tu. Hakika Mwenyezi Mungu ni Mwenye kusikia, Mwenye kuona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 29, 'Kwani huoni kwamba Mwenyezi Mungu huuingiza usiku katika mchana, na huuingiza mchana katika usiku, na amedhalilisha jua na mwezi? Vyote hivyo vinakwenda mpaka wakati uliowekwa. Na Mwenyezi Mungu anazo habari za mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 30, 'Hivi ni kwa sababu, Mwenyezi Mungu ndiye wa kweli, na hakika wanachokiomba ni cha uongo. Na kwamba hakika Mwenyezi Mungu ndiye Mtukufu na ndiye Mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 31, 'Kwani huoni kwamba merikebu hupita baharini kwa neema za Mwenyezi Mungu, ili kuwaonyesha baadhi ya Ishara zake? Hakika katika haya zipo Ishara kwa kila mwenye kusubiri na mwenye kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 32, 'Na wimbi linapowafunika kama wingu, wao humwomba Mwenyezi Mungu kwa kumsafia dini. Lakini anapowaokoa wakafika nchi kavu, wapo baadhi yao huwa wa kati na kati. Wala hazikanushi Ishara zetu ila aliyekhaini kafiri mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 33, 'Enyi watu, mcheni Mola wenu Mlezi, na iogopeni siku ambayo mzazi hatamfaa mwana, wala mwana hatamfaa mzazi kwa lolote. Hakika ahadi ya Mwenyezi Mungu ni ya kweli. Basi yasiwadanganyeni maisha ya dunia, wala asiwadanganyeni na Mwenyezi Mungu yule mdanganyifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 34, 'Hakika kuijua Saa ya Kiyama kuko kwa Mwenyezi Mungu. Na Yeye ndiye anayeiteremsha mvua. Na anavijua vilivyo ndani ya matumbo ya uzazi. Na haijui nafsi yoyote itachuma nini kesho. Wala nafsi yoyote haijui itafia nchi gani. Hakika Mwenyezi Mungu ndiye Mwenye kujua, Mwenye habari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 1, 'Alif Laam Miim.[1]', '[1] Herufi hizi "Alif Laam Miim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 2, 'Huu ni uteremsho wa Kitabu kisichokuwa na shaka yoyote kinachotoka kwa Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 3, 'Au wanasema: Amekizua? Bali hiki ni kweli iliyotoka kwa Mola wako Mlezi ili uwaonye watu wasiofikiwa na mwonyaji kabla yako; huenda wakaongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 4, 'Mwenyezi Mungu ndiye aliyeumba mbingu na ardhi na vilivyo baina yake kwa siku sita, na akainuka akawa juu ya Kiti cha Enzi. Nyinyi hamna mlinzi wala mwombezi isipokuwa Yeye tu. Basi, je, hamkumbuki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 5, 'Anapitisha mambo yote yaliyo baina ya mbingu na ardhi, kisha yanapanda kwake kwa siku ambayo kipimo chake ni miaka elfu kwa mnavyohesabu nyinyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 6, 'Huyu ndiye Mwenye kuyajua yasiyoonekana na yanayoonekana. Mwenye nguvu, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 7, 'Ambaye ametengeneza vizuri umbo la kila kitu na akaanzisha kumuumba mtu kwa udongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 8, 'Na kisha akajaalia uzao wake utokane na kizazi cha maji dhaifu yanayodharauliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 9, 'Kisha akamtengeneza sawasawa, na akampulizia katika roho yake, na akawajalieni kusikia na kuona, na nyoyo za kufahamu. Ni uchache mnavyoshukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 10, 'Nao walisema: "Kwani tutakapokwishapotelea chini ya ardhi, ni kweli kwamba tutarudishwa katika umbo jipya?" Bali wao wanakufuru kukutana na Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 11, 'Sema, "Atakufisheni Malaika wa mauti aliyewakilishwa juu yenu; kisha mtarejeshwa kwa Mola wenu Mlezi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 12, 'Na ungeliwaona wakosefu wanavyoinamisha vichwa vyao mbele ya Mola wao Mlezi, wakisema: Mola wetu Mlezi! Tumeshaona, na tumeshasikia. Turejeshe tukatende mema, kwani hakika sisi tumekwisha kuwa na yakini sasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 13, 'Na lau tungelitaka, tungempa kila mtu uongofu wake. Lakini imekwisha kuwa kauli iliyotoka kwangu: Kwa yakini nitaijaza Jahannamu kwa wote hawa, majini na watu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 14, 'Basi onjeni kwa vile mlivyousahau mkutano wa Siku yenu hii. Na Sisi hakika tunakusahauni. Basi onjeni adhabu ya milele kwa yale mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 15, 'Hakika wanaoziamini Aya zetu ni hao tu ambao wakikumbushwa hizo, basi wao huanguka kusujudu, na humsabihi Mola wao Mlezi kwa kumhimidi, nao hawajivuni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 16, 'Mbavu zao zinaachana na vitanda kwa kumwomba Mola wao Mlezi kwa khofu na kutumaini, na hutoa kutokana na tulivyowaruzuku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 17, 'Nafsi yoyote haijui waliyofichiwa katika hayo yanayofurahisha macho - ni malipo ya yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 18, 'Ati aliye Muumini atakuwa sawa na aliye mpotovu? Hawawi sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 19, 'Ama walioamini na wakatenda mema, watakuwa nazo Bustani za makazi mazuri. Ndio pa kufikia kwa waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 20, 'Na ama wale waliotenda uovu, basi makazi yao ni Motoni. Kila wakitaka kutoka humo, watarudishwa humo humo. Na wataambiwa: Onjeni adhabu ya Moto ambayo mlikuwa mkiikanusha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 21, 'Na hakika tutawaonjesha katika adhabu hafifu kabla ya adhabu kubwa, huenda labda watarejea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 22, 'Na ni nani dhalimu mkubwa kuliko yule anayekumbushwa kwa Ishara za Mola wake Mlezi, kisha akazikataa? Hakika Sisi tutajilipiza kwa wakosefu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 23, 'Hakika Sisi tulikwisha mpa Musa Kitabu. Basi usiwe na shaka kuwa kakipokea. Na tukakifanya kuwa ni uongofu kwa Wana wa Israili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 24, 'Na tukawafanya miongoni mwa waongozi wanaoongoa watu kwa amri yetu, waliposubiri na wakawa na yakini na Ishara zetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 25, 'Hakika Mola wako Mlezi ndiye atakayefafanua baina yao Siku ya Kiyama katika yale waliyokuwa wakihitalifiana ndani yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 26, 'Ee! Haijawabainikia kwamba kaumu ngapi tuliziangamiza kabla yao, nao wanapita katika maskani zao hizo? Hakika katika hayo zipo Ishara. Basi, je, hawasikii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 27, 'Je, hawaoni ya kwamba tunayapeleka maji kwenye ardhi kavu, kisha kwayo tunaitoa mimea wanayokula wanyama wao na wao wenyewe? Je, hawaoni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 28, 'Wanasema: Ushindi huu ni lini, kama nyinyi ni wakweli?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 29, 'Sema: Siku ya Ushindi, wale waliokufuru imani yao haitawafaa kitu, wala wao hawatapewa muhula.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 30, 'Basi wapuuze, nawe ngoja; hakika wao wanangoja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 1, 'Ewe Nabii, mche Mwenyezi Mungu wala usiwatii makafiri na wanafiki. Hakika Mwenyezi Mungu ni Mwenye kujua, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 2, 'Na fuata uliyofunuliwa kwa wahyi kutokana na Mola wako Mlezi. Hakika Mwenyezi Mungu anazo habari ya mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 3, 'Na mtegemee Mwenyezi Mungu. Na Mwenyezi Mungu anatosha kuwa ni wa kutegemewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 4, 'Mwenyezi Mungu hakumwekea mwanamume yeyote kuwa ana nyoyo mbili ndani ya mwili wake. Wala hakuwafanya wake zenu - ambao mnawalinganisha migongo yao na migongo ya mama zenu - kuwa ni mama zenu. Wala hakuwafanya watoto wenu wa kupanga kuwa ni wana wenu khasa. Hayo ni maneno ya vinywa vyenu tu. Na Mwenyezi Mungu ndiye anayesema kweli, naye ndiye anayeongoa Njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 5, 'Waiteni kwa baba zao, maana huo ndio uadilifu zaidi mbele ya Mwenyezi Mungu. Na ikiwa hamuwajui baba zao, basi ni ndugu zenu katika Dini, na rafiki zenu. Wala si lawama juu yenu kwa mlivyokosea. Lakini ipo lawama katika yale ziliyofanya nyoyo zenu kwa makusudi. Na Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 6, 'Nabii ni bora zaidi kwa Waumini kuliko nafsi zao. Na wake zake ni mama zao. Na jamaa ni karibu wao kwa wao katika Kitabu cha Mwenyezi Mungu kuliko Waumini wengine na Wahamiaji. Ila muwe mnawafanyia wema marafiki zenu. Haya yamekwisha andikwa Kitabuni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 7, 'Na tulipochukua ahadi kwa Manabii na kwako wewe, na Nuhu na Ibrahim na Isa mwana wa Mariamu, na tulichukua kwao ahadi ngumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 8, 'Ili Mwenyezi Mungu awaulize wakweli juu ya ukweli wao. Na amewaandalia makafiri adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 9, 'Enyi mlioamini, zikumbukeni neema za Mwenyezi Mungu zilizo juu yenu. Pale yalipokufikieni majeshi, nasi tukayapelekea upepo, na majeshi msiyoyaona. Na Mwenyezi Mungu anayaona mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 10, 'Walipowakujieni kutoka juu yenu, na kutoka chini yenu; na macho yalipokodoka, na nyoyo zikapanda kooni, nanyi mkamdhania Mwenyezi Mungu dhana mbalimbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 11, 'Hapo ndipo Waumini walipojaribiwa, na wakatikiswa mtikiso mkali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 12, 'Na waliposema wanafiki na wale wenye maradhi katika nyoyo zao: "Mwenyezi Mungu na Mtume wake hawakutuahidi ila udanganyifu tu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 13, 'Na kundi moja katika miongoni mwao liliposema: "Enyi watu wa Yathrib, hapana kukaa nyinyi! Rudini." Na kundi jingine miongoni mwao likaomba ruhusa kwa Nabii kwa kusema: "Hakika nyumba zetu ni tupu." Wala hazikuwa tupu; hawakutaka isipokuwa kukimbia tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 14, 'Na lau kuwa wangeliingiliwa kwa pande zote, kisha wakatakiwa kufanya hiana, wangelifanya, na wasingelisita isipokuwa kidogo tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 15, 'Na hakika walikwisha muahidi Mwenyezi Mungu kabla yake kwamba hawatageuza migongo yao. Na ahadi ya Mwenyezi Mungu ni yenye kuulizwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 16, 'Sema: Kukimbia hakuwafai kitu ikiwa mnakimbia mauti au kuuawa, na hata hivyo hamtastareheshwa isipokuwa kidogo tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 17, 'Sema: Ni nani wa kuwalinda kutokana na Mwenyezi Mungu pindi akiwatakia uovu, au akiwatakia rehema? Wala hawatapata mlinzi wala msaidizi isipokuwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 18, 'Kwa hakika Mwenyezi Mungu anawajua hao wanaozuilia, na wanaowaambia ndugu zao: "Njooni kwetu!" Wala hawaingii vitani isipokuwa kidogo tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 19, 'Wana choyo juu yenu. Ikifika hofu, utawaona wanakutazama na macho yao yanazunguka, kama yule ambaye alizimia kwa kukaribia mauti. Na hofu ikiondoka, wanawaudhi kwa ndimi kali, nao ni mabahili kwa kila la heri. Hao hawakuamini, basi Mwenyezi Mungu amevibatilisha vitendo vyao. Na hayo kwa Mwenyezi Mungu ni mepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 20, 'Wanafikiri yale makundi ya maadui hayajaondoka. Na yakija hayo makundi, watatamani laiti wao wako majangwani pamoja na mabedui, wakiuliza habari zenu. Na lau wangekuwa pamoja nanyi, basi hawangepigana isipokuwa kidogo tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 21, 'Hakika nyinyi mnayo ruwaza njema kwa Mtume wa Mwenyezi Mungu kwa anayemtaraji Mwenyezi Mungu na Siku ya Mwisho, na akamkumbuka Mwenyezi Mungu sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 22, 'Na Waumini walipoyaona makundi, walisema, "Haya ndiyo aliyotuahidi Mwenyezi Mungu na Mtume wake. Na Mwenyezi Mungu na Mtume wake wamesema kweli." Na hayo hayakuwazidisha ila Imani na utiifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 23, 'Miongoni mwa Waumini wapo watu waliotimiza waliyoagana na Mwenyezi Mungu. Baadhi yao wamekwisha kufa, na baadhi wanangojea, wala hawakubadilisha ahadi hata kidogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 24, 'Ili Mwenyezi Mungu awalipe wakweli kwa sababu ya ukweli wao, na awaadhibu wanafiki pindi akitaka, au apokee toba yao. Hakika Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 25, 'Na Mwenyezi Mungu aliwarudisha nyuma makafiri juu ya ghadhabu yao; hawakupata heri yoyote. Na Mwenyezi Mungu amewatosheleza Waumini katika vita. Na Mwenyezi Mungu ni Mwenye nguvu na uweza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 26, 'Na akawateremsha wale waliowasaidia maadui katika Watu wa Kitabu kutoka katika ngome zao, na akatia hofu katika nyoyo zao. Baadhi yao mkawa mnawaua, na wengine mnawateka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 27, 'Na akawarithisha ardhi zao na nyumba zao na mali zao, na ardhi msiyopata kuikanyaga. Na Mwenyezi Mungu ni Mwenye uweza juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 28, 'Ewe Nabii! Waambie wake zako: Ikiwa mnataka maisha ya dunia na pambo lake, basi njooni, nitawapa kutoka nyumba, na kuwaacha mwachano mzuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 29, 'Na ikiwa mnamtaka Mwenyezi Mungu na Mtume wake na nyumba ya Akhera, basi Mwenyezi Mungu amewaandalia wafanyao mema, miongoni mwenu, malipo makubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 30, 'Enyi wake wa Nabii, atakayefanya uchafu dhahiri miongoni mwenu, atazidishiwa adhabu mara mbili. Na hayo kwa Mwenyezi Mungu ni mepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 31, 'Na miongoni mwenu atakayemtii Mwenyezi Mungu na Mtume wake, na akatenda mema, tutampa malipo yake mara mbili, na tutamwandalia riziki ya ukarimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 32, 'Enyi wake wa Nabii, nyinyi si kama yeyote katika wanawake wengine. Kama mnamcha Mungu, basi msilegeze sauti zenu, akaingia tamaa mwenye maradhi katika moyo wake. Na semeni maneno mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 33, 'Na kaeni majumbani kwenu, wala msijishauwe kwa majishauwo ya kijahilia ya kizamani. Na shikeni Swala, na toeni Zaka, na mtiini Mwenyezi Mungu na Mtume wake. Hakika Mwenyezi Mungu anataka kuwaondoleeni uchafu, enyi Watu wa Nyumba ya Mtume, na kukusafisheni sawasawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 34, 'Na kumbukeni yasomwayo majumbani mwenu katika Aya za Mwenyezi Mungu na hekima. Kwa hakika Mwenyezi Mungu ni Mjuzi wa mambo ya siri, na Mwenye habari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 35, 'Hakika Waislamu wanaume na Waislamu wanawake, na Waumini wanaume na Waumini wanawake, na wanaume watiifu na wanawake watiifu, na wanaume wakweli na wanawake wakweli, na wanaume wanaosubiri, na wanawake wanaosubiri, na wanaume wanyenyekevu na wanawake wanyenyekevu, na wanaume watoao sadaka na wanawake watoao sadaka, na wanaume wanaofunga saumu na wanawake wanaofunga saumu, na wanaume wanaojihifadhi tupu zao, na wanawake wanaojihifadhi tupu zao, na wanaume wanaomdhukuru Mwenyezi Mungu kwa wingi na wanawake wanaomdhukuru Mwenyezi Mungu kwa wingi, Mwenyezi Mungu amewaandalia msamaha na ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 36, 'Haiwi kwa Muumini mwanamume wala Muumini mwanamke kuwa na hiari katika jambo lao, Mwenyezi Mungu na Mtume wake wanapokata shauri katika jambo. Na mwenye kumuasi Mwenyezi Mungu na Mtume wake, basi hakika amepotea upotovu ulio wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 37, 'Na ulipomwambia yule ambaye Mwenyezi Mungu alimneemesha, nawe ukamneemesha: Shikamana na mkeo, na mche Mwenyezi Mungu. Na ukaficha nafsini mwako aliyotaka Mwenyezi Mungu kuyafichua, nawe ukawachelea watu, hali Mwenyezi Mungu ndiye mwenye haki zaidi kumchelea. Basi Zaid alipokwisha haja naye, tulikuoza wewe, ili isiwe taabu kwa Waumini kuwaoa wake wa watoto wao wa kupanga watapokuwa wamekwisha timiza nao shuruti za talaka. Na amri ya Mwenyezi Mungu ni yenye kutekelezwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 38, 'Hapana ubaya kwa Nabii kufanya aliyomhalalishia Mwenyezi Mungu. Huo ndio mwendo wa Mwenyezi Mungu kwa wale waliopita zamani. Na amri ya Mwenyezi Mungu ni mipango iliyokwisha pangwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 39, 'Hao wa zamani, waliokuwa wakifikisha jumbe za Mwenyezi Mungu na wanamwogopa Yeye, na wala hawamwogopi yeyote isipokuwa Mwenyezi Mungu. Na Mwenyezi Mungu anatosha kuwa Mhasibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 40, 'Muhammad si baba wa yeyote katika wanaume wenu, bali ni Mtume wa Mwenyezi Mungu na Mwisho wa Manabii, na Mwenyezi Mungu ni Mwenye kujua vyema kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 41, 'Enyi mlioamini! Mdhukuruni Mwenyezi Mungu kwa wingi wa kumdhukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 42, 'Na mtakaseni asubuhi na jioni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 43, 'Yeye ndiye anayekurehemuni na Malaika wake ili akutoeni gizani hadi kwenye nuru. Naye ni Mwenye kuwarehemu sana Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 44, 'Maamkizi yao siku ya kukutana naye yatakuwa Salama! Na amewaandalia malipo ya ukarimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 45, 'Ewe Nabii! Hakika Sisi tumekutuma uwe shahidi na mbashiri na mwonyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 46, 'Na mwitaji kumwendea Mwenyezi Mungu kwa idhini yake, na taa yenye kutoa nuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 47, 'Na wabashirie Waumini ya kwamba wana fadhila kubwa inayotoka kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 48, 'Wala usiwatii makafiri na wanafiki, na usijali udhia wao. Nawe mtegemee Mwenyezi Mungu. Na Mwenyezi Mungu anatosha kuwa Mtegemewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 49, 'Enyi mlioamini, mkiwaoa wanawake, Waumini, kisha mkawapa talaka kabla ya kuwagusa, basi hamna eda juu yao mtakayohesabu. Basi wapeni cha kuwaliwaza, na muwaache kwa wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 50, 'Ewe Nabii, tumekuhalalishia wake zako uliowapa mahari yao, na uliowamiliki kwa mkono wako wa kulia katika wale aliokupa Mwenyezi Mungu, na mabinti wa ami zako, na mabinti wa shangazi zako, na mabinti wa wajomba zako, na mabinti wa dada za mama yako waliohama pamoja nawe; na mwanamke Muumini akijitoa mwenyewe kwa Nabii, kama mwenyewe Nabii akitaka kumuoa. Ni halali kwako wewe tu, si kwa Waumini wengine. Sisi tunajua tuliyowafaradhishia wao katika wake zao na wanawake iliyowamiliki mikono yao ya kulia, ili isiwe dhiki kwao. Na Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 51, 'Unaweza kuakhirisha zamu kwa umtakaye katika wao, na umsongeze karibu umtakaye. Na kama ukimtaka yule uliyemtenga, basi si vibaya kwako. Kufanya hivi kutapelekea yaburudike macho yao, wala wasihuzunike, na wawe radhi juu ya kile unachowapa wao wote. Na Mwenyezi Mungu anajua yaliyomo nyoyoni mwenu, na Mwenyezi Mungu ni Mwenye kujua, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 52, 'Baada ya hawa hawakuhalalikii wewe wanawake wengine, wala kuwabadilisha kwa wake wengine, ingawa uzuri wao ukikupendeza, isipokuwa yule uliyemmiliki kwa mkono wako wa kulia. Na Mwenyezi Mungu anachunga kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 53, 'Enyi mlioamini, msiingie katika nyumba za Nabii isipokuwa mpewe ruhusa kwenda kula chakula, siyo kungojea kiive. Lakini mtakapoitwa, basi ingieni, na mkishakula, tawanyikeni, wala msiweke hapo mazungumzo. Hakika hayo yanamuudhi Nabii, naye anawastahi, lakini Mwenyezi Mungu hastahi kwa jambo la haki. Na mnapowauliza wakeze haja, waulizeni kwa nyuma ya mapazia. Hivyo ndivyo usafi zaidi kwa nyoyo zenu na nyoyo zao. Wala haikufailiini kumuudhi Mtume wa Mwenyezi Mungu, wala kuwaoa wake zake baada yake kabisa. Hakika jambo hilo ni kubwa mbele ya Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 54, 'Mkidhihirisha chochote kile, au mkikificha, basi hakika Mwenyezi Mungu ni Mwenye kujua kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 55, 'Hapana ubaya kwao (wake za Mtume), kuonana na baba zao, wala watoto wao, wala kaka zao, wala watoto wa kiume wa kaka zao, wala watoto wa kiume wa dada zao, wala wanawake wenzao, wala wale waliomilikiwa na mikono yao ya kulia. Na enyi wanawake, mcheni Mwenyezi Mungu. Hakika Mwenyezi Mungu ni Mwenye kushuhudia kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 56, 'Hakika Mwenyezi Mungu na Malaika wake wanamswalia Nabii. Enyi mlioamini, mswalieni na mumsalimu kwa salamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 57, 'Hakika wanaomuudhi Mwenyezi Mungu na Mtume wake, Mwenyezi Mungu amewalaani duniani na Akhera, na amewaandalia adhabu ya kufedhehesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 58, 'Na wale wanaowaudhi Waumini wanaume na wanawake pasi na wao kufanya kosa lolote, bila ya shaka wamebeba dhuluma kubwa na dhambi iliyo dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 59, 'Ewe Nabii, waambie wake zako, na binti zako, na wake za Waumini wajiteremshie nguo zao. Hivyo ni karibu zaidi kuweza kutambulikana kwa hivyo wasiudhiwe. Na Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 60, 'Kama wanafiki na wale wenye maradhi nyoyoni mwao, na waenezao fitina katika Madina hawataacha, basi kwa yakini tutakupa mamlaka juu yao, kisha hawatakaa humo karibu yako isipokuwa muda mchache tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 61, 'Wamelaaniwa! Popote watakapoonekana, watakamatwa na watauliwa kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 62, 'Hii ni ada ya Mwenyezi Mungu iliyokuwa kwa wale waliopita zamani. Wala hutapata mabadiliko katika ada ya Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 63, 'Watu wanakuuliza habari ya Saa ya Kiyama. Sema: "Hakika elimu yake iko kwa Mwenyezi Mungu." Na nini kitakujulisha, pengine hiyo Saa iko karibu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 64, 'Hakika Mwenyezi Mungu amewalaani makafiri na amewaandalia Moto unaowaka kwa nguvu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 65, 'Watadumu humo milele. Hawatampata mlinzi wala wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 66, 'Siku ambayo nyuso zao zitapinduliwa pinduliwa katika Moto, watasema: "Laiti tungelimtii Mwenyezi Mungu, na tungelimtii Mtume!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 67, 'Na watasema: "Mola wetu Mlezi, hakika sisi tuliwatii bwana zetu na wakubwa wetu; nao ndio waliotupoteza njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 68, 'Mola wetu Mlezi, wape wao adhabu mara mbili, na uwalaani laana kubwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 69, 'Enyi mlioamini, msiwe kama wale waliomtaabisha Musa, lakini Mwenyezi Mungu akamtakasa na hayo waliyoyasema, naye alikuwa mwenye heshima mbele ya Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 70, 'Enyi mlioamini, mcheni Mwenyezi Mungu na semeni maneno ya sawasawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 71, 'Atawatengenezea vitendo vyenu na awasamehe madhambi yenu. Na anayemtii Mwenyezi Mungu na Mtume wake, bila ya shaka amefuzu kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 72, 'Kwa hakika Sisi tuliwasilisha amana kwa mbingu na ardhi na milima, na vyote hivyo vikakataa kuichukua na vikaogopa. Lakini mwanadamu akaichukua. Hakika yeye amekuwa dhalimu, mjinga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 73, 'Ili Mwenyezi Mungu awaadhibu wanafiki wanaume na wanafiki wanawake, na washirikina wanaume na washirikina wanawake. Na awapokelee toba Waumini wanaume, na Waumini wanawake. Na Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 1, 'Sifa njema zote ni za Mwenyezi Mungu, ambaye ni vyake vyote vilivyo mbinguni na katika ardhi. Na sifa ni zake Yeye katika Akhera. Naye ni Mwenye hekima, Mwenye habari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 2, 'Anajua yanayoingia katika ardhi na yanayotoka humo, na yanayoteremka kutoka mbinguni, na yanayopanda huko. Na Yeye ni Mwenye kurehemu, Mwenye kusamehe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 3, 'Na walisema wale waliokufuru: "Haitatufikia Saa ya Kiyama." Sema: Kwani, hapana shaka itakufikieni, ninaapa kwa haki ya Mola wangu Mlezi, Mwenye kujua ya ghaibu! Hapana kinachofichikana kwake hata chenye uzito wa chembe tu, si katika mbingu wala katika ardhi, wala kilicho kidogo kuliko hivyo, wala kikubwa zaidi, isipokuwa vyote hivyo vimo katika Kitabu chake chenye kubainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 4, 'Ili awalipe wale walioamini na wakatenda mema. Hao watapata msamaha na riziki ya ukarimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 5, 'Na wale waliojitahidi kuzipinga Ishara zetu wakaona watashinda, hao watapata adhabu mbaya yenye uchungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 6, 'Na wale waliopewa elimu wanaona ya kuwa yale uliyoteremshiwa kutoka kwa Mola wako Mlezi ndiyo haki, nayo huongoa kwendea njia ya Mwenye nguvu, Mwenye kusifiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 7, 'Na wale waliokufuru walisema: Je, tuwajulisheni mtu anayewaambieni kwamba mtakapochambuliwa mapande mapande mtakuwa katika umbo jipya?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 8, 'Ama amemzulia Mwenyezi Mungu uongo, au ana wazimu. Bali wale wasioamini Akhera wamo adhabuni na upotovu wa mbali kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 9, 'Kwani hawaoni yaliyo mbele yao na yaliyo nyuma yao, ya mbingu na ardhi? Tungelipenda, tungeliwadidimiza ndani ya ardhi, au tungeliwateremshia juu yao vipande vya mbingu. Hakika katika haya zipo Ishara kwa kila mja aliyetubia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 10, 'Na tulimpa Daudi fadhila kutoka kwetu, tukasema: "Enyi milima, karirini kumtakasa Mwenyezi Mungu pamoja naye! Na ndege pia." Na tukamlainishia chuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 11, 'Tukamwambia: "Tengeneza nguo za chuma pana, na kadiria sawa katika kuunganisha. Na tendeni mema. Hakika Mimi nayaona vyema mnayoyatenda."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 12, 'Naye Suleiman tuliufanya upepo umtumikie. Safari yake ya asubuhi ni mwendo wa mwezi mmoja, na safari yake ya jioni ni mwendo wa mwezi mmoja. Na tukamyeyushia chemichemi ya shaba. Na katika majini, walikuwako waliokuwa wakifanya kazi mbele yake kwa idhini ya Mola wake Mlezi. Na kila anayejitenga na amri yetu katika wao, tunamuonjesha adhabu ya Moto unaowaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 13, 'Walikuwa wakimfanyia alipendalo, kama mihrabu, na vitu vifananavyo vingine, na madeste makubwa kama mahodhi, na masufuria makubwa yaliyo madhubuti. Enyi watu wa Daudi, fanyeni kazi kwa kushukuru. Na ni wachache katika waja wangu wanaoshukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 14, 'Na tulipomhukumia kufa, hapana aliyewajulisha kufa kwake ila mnyama wa ardhi aliyekula fimbo yake. Na alipoanguka, majini wakatambua lau kuwa wangelijua ya ghaibu wasingelikaa katika adhabu hiyo ya kufedhehesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 15, 'Hakika ilikuwepo Ishara kwa (watu wa nchi ya) Sabaa katika maskani yao - bustani mbili, kulia na kushoto. Kuleni katika riziki ya Mwenyezi Mungu, na mumshukuru. Mji mzuri na Mola Mlezi aliye Msamehevu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 16, 'Lakini wakayapa mgongo. Kwa hivyo, tukawatumia mafuriko makubwa, na tukawabadilishia badala ya bustani zao hizo kwa bustani nyingine zenye matunda makali, machungu, na mivinje, na kidogo katika miti ya kunazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 17, 'Hayo tuliwalipa kwa sababu ya walivyokufuru. Nasi kwani tunamuadhibu isipokuwa anayekufuru?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 18, 'Na baina yao na miji mingine tuliyoibariki tuliweka miji iliyo dhahiri, na tukaweka humo vituo vya safari. Tukawaambia, "Nendeni humo usiku na mchana kwa amani."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 19, 'Lakini wakasema, "Mola wetu Mlezi! Weka mwendo mrefu baina ya safari zetu." Na wakazidhulumu nafsi zao. Basi tukawafanya ni masimulizi tu, na tukawatawanya tawanya. Hakika katika hayo bila ya shaka zimo Ishara kwa kila mwenye kusubiri sana na akashukuru mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 20, 'Na bila ya shaka Iblisi aliihakikisha ile dhana yake juu yao. Nao walimfuata, isipokuwa kundi katika Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 21, 'Na yeye hakuwa na mamlaka yoyote juu yao, isipokuwa kwa sababu ya kuwajaribu ili tumjue ni nani mwenye kuamini Akhera, na ni nani anayeitilia shaka. Na Mola wako Mlezi ni Mwenye kuhifadhi kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 22, 'Sema, "Waiteni wale mnaowadaia kuwa ni badala ya Mwenyezi Mungu. Hawamiliki hata uzito wa chembe katika mbingu wala ardhi. Wala hawana ushirika wowote humo. Wala Yeye hana msaidizi miongoni mwao."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 23, 'Wala uombezi mbele yake hautafaa kitu, isipokuwa kwa aliyempa idhini. Hata itakapoondolewa hofu kwenye nyoyo zao, watasema: "Mola wenu Mlezi amesema nini?" Watasema: "Yaliyo kweli! Na Yeye ndiye Aliye juu, Mkubwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 24, 'Sema: Ni nani anayewaruzuku kutoka mbinguni na kwenye ardhi? Sema: Mwenyezi Mungu! Na hakika sisi au nyinyi bila ya shaka tuko kwenye uongofu au upotovu ulio wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 25, 'Sema: Nyinyi hamtaulizwa makosa tuliyoyafanya, wala sisi hatutaulizwa mnayoyatenda nyinyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 26, 'Sema: Mola wetu Mlezi atatukusanya, kisha atatuhukumu kwa haki; na Yeye ndiye Hakimu, Mwenye kujua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 27, 'Sema: Nionyesheni mliowaunganisha naye kuwa washirika. Hasha! Bali Yeye ndiye Mwenyezi Mungu, Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 28, 'Na hatukukutuma ila kwa watu wote, uwe mbashiri na mwonyaji. Lakini watu wengi hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 29, 'Na wanasema: "Ahadi hii itakuwa lini, ikiwa nyinyi mnasema kweli?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 30, 'Sema: "Nyinyi mnayo miadi ya Siku ambayo hamtakawiya mbali nayo kwa saa moja, wala hamtaitangulia."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 31, 'Na walisema wale waliokufuru, "Hatutaiamini Qur-ani hii, wala yale yaliyokuwa kabla yake." Na ungeliwaona madhalimu watakaposimamishwa mbele ya Mola wao Mlezi, wakirudishiana maneno wao kwa wao! Wanyonge wakiwaambia wale waliotakabari, "Lau kuwa si nyinyi, bila ya shaka tungelikuwa Waumini sisi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 32, 'Na wale waliotakabari watawaambia wanyonge, "Kwani sisi ndio tuliwazuia na uongofu baada ya huo kukujieni? Bali nyinyi wenyewe ni wahalifu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 33, 'Na wanyonge wakawaambia wale waliotakabari, "Bali ni vitimbi vyenu vya usiku na mchana, mlipokuwa mkituamrisha tumkufuru Mwenyezi Mungu, na tumfanyie washirika." Nao wataficha majuto watakapoiona adhabu. Na tutaweka makongwa shingoni mwa wale waliokufuru. Kwani wanalipwa isipokuwa kwa yale waliyokuwa wakiyatenda?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 34, 'Na hatukumtuma mwonyaji yeyote kwenye mji, isipokuwa walisema wale waliojidekeza kwa starehe zao, wa mji huo, "Hakika sisi tunayakataa hayo mliyotumwa nayo."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 35, 'Na wakasema, "Sisi tuna mali nyingi zaidi na watoto, wala sisi hatutaadhibiwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 36, 'Sema, "Hakika Mola wangu Mlezi humkunjulia riziki amtakaye na humdhikisha amtakaye. Lakini watu wengi hawajui."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 37, 'Na si mali zenu wala watoto wenu watakaowasongesha karibu na sisi, muwe karibu sana, isipokuwa yule aliyeamini na akatenda mema. Hao basi watapata malipo maradufu kwa yale waliyoyafanya. Nao watakuwa salama katika maghorofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 38, 'Na wale wanaojitahidi kuzipinga Ishara zetu, wakaona watashinda, hao watahudhurishwa kwenye adhabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 39, 'Sema: "Kwa hakika Mola wangu Mlezi humkunjulia riziki amtakaye na humdhikisha amtakaye katika waja wake. Na chochote mtakachokitoa, Yeye atakilipa. Naye ni Mbora wa wanaoruzuku."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 40, 'Na siku atakayowakusanya wote, kisha atawaambia Malaika, "Je, hawa walikuwa wakikuabuduni?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 41, 'Waseme, "Subhanak (umetakasika). Wewe ndiye kipenzi chetu, si hao. Bali wao walikuwa wakiwaabudu majini; wengi wao wakiwaamini hao."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 42, 'Basi hii leo hataweza yeyote kumletea nafuu wala madhara mwenziwe. Na tutawaambia wale waliodhulumu, "Onjeni adhabu ya Moto mliokuwa mkiukadhibisha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 43, 'Na wanaposomewa Aya zetu zilizo wazi, wanasema: "Huyu si chochote isipokuwa ni mtu anayetaka kuwazuia na yale waliyokuwa wakiabudu baba zenu." Na wakasema: "Haya si chochote isipokuwa ni uongo uliozuliwa." Na wale waliokufuru waliiambia haki ilipowajia: "Haya si chochote isipokuwa ni uchawi ulio dhahiri."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 44, 'Wala hatukuwapa Vitabu wavisome, wala hatukuwatumia mwonyaji kabla yako wewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 45, 'Na walikadhibisha wale waliokuwa kabla yao. Na hawakufikia hata sehemu moja katika kumi ya tulivyowapa hao. Nao waliwakadhibisha Mitume wangu. Basi kuangamiza kwangu kulikuwa namna gani!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 46, 'Sema: "Mimi ninawanasihi kwa jambo moja tu - ya kwamba msimame kwa ajili ya Mwenyezi Mungu, wawili wawili na mmoja mmoja; kisha mfikiri. Mwenzenu huyu hana wazimu. Yeye si chochote isipokuwa ni mwonyaji kwenu kabla ya kufika adhabu kali."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 47, 'Sema: "Ujira niliowaomba ni wenu nyinyi. Sina ujira isipokuwa kwa Mwenyezi Mungu. Na Yeye ni Shahidi juu ya kila kitu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 48, 'Sema: "Hakika Mola wangu Mlezi anaondoa upotovu kwa haki. Yeye ndiye Mwenye kujua vyema ya ghaibu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 49, 'Sema: "Kweli imefika, na batili haijitokezi, wala hairudi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 50, 'Sema: "Ikiwa mimi nimepotea, basi nimepotea kwa kudhuru nafsi yangu mwenyewe. Na ikiwa nimeongoka, basi ni kwa sababu ya kunifunulia Mola wangu Mlezi. Hakika Yeye ni Mwenye kusikia, aliye karibu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 51, 'Na lau ungeliona watakapobabaika, basi hapana pa kukimbilia! Na watakamatwa mahala pa karibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 52, 'Na watasema: "Tunaiamini!" Lakini wataipata wapi kutoka huko mahali mbali?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 53, 'Na hapo kabla yake waliikataa, na wakiyatupilia mbali maneno ya ghaibu kutoka mahali mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 54, 'Na watatiliwa kizuizi baina yao na hayo wanayoyatamani, kama walivyofanyiwa wenzao zamani. Hakika hao walikuwa na shaka ya kutia wasiwasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 1, 'Sifa zote njema ni za Mwenyezi Mungu, Muumba wa mbingu na ardhi, aliyewafanya Malaika kuwa wajumbe wenye mbawa mbili mbili, na tatu tatu, na nne nne. Huzidisha katika kuumba apendavyo. Hakika Mwenyezi Mungu ni Muweza wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 2, 'Rehema ambayo Mwenyezi Mungu anawafungulia watu, hapana wa kuizuia. Na anayoizuia, hapana wa kuiachilia isipokuwa Yeye. Naye ndiye Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 3, 'Enyi watu! Kumbukeni neema za Mwenyezi Mungu juu yenu. Ati yupo muumba mwingine asiyekuwa Mwenyezi Mungu anayekupeni riziki kutoka mbinguni na kwenye ardhi? Hapana mungu isipokuwa Yeye tu. Basi wapi mnakogeuzwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 4, 'Na wakikukanusha, basi walikwisha kanushwa Mitume kabla yako. Na mambo yote yatarudishwa kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 5, 'Enyi watu! Hakika ahadi ya Mwenyezi Mungu ni ya kweli. Basi kamwe yasikudanganyeni maisha ya dunia, wala kamwe yule mdanganyifu asikudanganyeni juu ya Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 6, 'Hakika Shetani ni adui yenu, basi mfanyeni kuwa ni adui. Kwani yeye analiita kundi lake liwe katika watu wa Moto wenye mwako mkali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 7, 'Wale waliokufuru watakuwa na adhabu kali; na wale walioamini na wakatenda mema watapata msamaha na ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 8, 'Je, yule aliyepambiwa matendo yake mabaya na akayaona ni mema - basi hakika Mwenyezi Mungu humpoteza amtakaye, na humwongoa amtakaye. Basi, nafsi yako isijihiliki kwa kuwasikitikia. Hakika Mwenyezi Mungu anajua vyema wanayoyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 9, 'Na Mwenyezi Mungu ndiye anayezituma pepo ziyatimue mawingu, nasi tukayafikisha kwenye nchi iliyokufa, tukaifufua ardhi baada ya kufa kwake. Ndivyo kama hivyo kutakavyokuwa kufufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 10, 'Mwenye kutaka utukufu, basi utukufu wote uko kwa Mwenyezi Mungu. Kwake Yeye hupanda neno zuri, na tendo jema Yeye hulitukuza. Na wanaopanga vitimbi vya maovu, watapata adhabu kali. Na vitimbi vyao vitaondokea patupu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 11, 'Na Mwenyezi Mungu amewaumba kutokana na udongo. Kisha kwa tone la manii. Kisha akawafanya mwanamume na mwanamke. Na mwanamke yeyote hachukui mimba, wala hazai, isipokuwa kwa elimu yake. Na wala hapewi umri mwenye umri mrefu, wala hapunguziwi katika umri wake, isipokuwa yamo hayo katika Kitabu. Hakika hayo ni mepesi kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 12, 'Na bahari mbili haziwi sawa; haya ni matamu yenye ladha, mazuri kunywa. Na haya ni ya chumvi, machungu. Na kutokana na bahari zote mnakula nyama mpya (isiyochacha). Na mnatoa mapambo mnayoyavaa. Na unaona ndani yake merikebu zinakata maji ili mtafute fadhila zake, na ili mpate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 13, 'Anauingiza usiku katika mchana, na anauingiza mchana katika usiku. Na amelifanya jua na mwezi kutumikia, kila kimoja kinakwenda kwa muda maalumu. Huyo ndiye Mwenyezi Mungu Mola wenu Mlezi. Ufalme ni wake. Na hao mnaowaomba badala yake hawamiliki hata ugozi wa kokwa ya tende.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 14, 'Mkiwaomba hawasikii maombi yenu, na hata wakisikia, hawawajibu. Na Siku ya Kiyama watakataa ushirikina wenu. Na hapana atakayekupa habari vilivyo kama Yeye Mwenye habari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 15, 'Enyi watu, nyinyi ndio wenye haja kwa Mwenyezi Mungu, na Mwenyezi Mungu ndiye Mwenye kujitosha, Msifiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 16, 'Akitaka, atawaondoa na alete viumbe vipya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 17, 'Na hilo si gumu kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 18, 'Na mbebaji hatabeba mzigo wa mwengine. Na aliyetopewa na mzigo wake akiomba uchukuliwe, hautachukuliwa hata kidogo, hata kama ni jamaa yake. Hakika wewe unawaonya wale wanaomcha Mola wao Mlezi kwa ghaibu, na wanashika Swala. Na mwenye kujitakasa, basi anajitakasa kwa ajili ya nafsi yake. Na marejeo ni kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 19, 'Na kipofu na mwenye kuona hawalingani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 20, 'Wala giza na mwangaza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 21, 'Wala kivuli na joto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 22, 'Wala hawalingani walio hai na maiti. Hakika Mwenyezi Mungu humsikilizisha amtakaye. Wala wewe si wa kuwasikilizisha walio makaburini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 23, 'Hukuwa wewe isipokuwa ni mwonyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 24, 'Hakika Sisi tumekutuma wewe kwa Haki, kuwa ni mbashiri na mwonyaji. Na hapana umma wowote isipokuwa ulipata mwonyaji kati yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 25, 'Na wakikukadhibisha, basi walikwisha kanusha wale waliokuwa kabla yao. Mitume wao waliwajia kwa ushahidi wa waziwazi na kwa maandiko na Kitabu chenye nuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 26, 'Kisha nikawakamata wale waliokufuru. Basi kukemea kwangu kulikuwaje?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 27, 'Je, huoni kwamba Mwenyezi Mungu aliteremsha maji kutoka mbinguni, na kwayo tukayatoa matunda yenye rangi mbalimbali. Na katika milima zimo njia nyeupe na nyekundu, na rangi mbali mbali, na milima mieusi sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 28, 'Na katika watu, na wanyama, na mifugo, pia rangi zao zinahitalifiana. Kwa hakika wanaomcha Mwenyezi Mungu miongoni mwa waja wake ni wanazuoni. Hakika Mwenyezi Mungu ni Mwenye nguvu, Mwenye kusamehe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 29, 'Hakika wale wanaosoma Kitabu cha Mwenyezi Mungu, na wakashika Swala, na wakatoa kwa siri na kwa dhahiri katika vile tulivyowaruzuku, hao hutaraji biashara isiyobwaga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 30, 'Ili Yeye awalipe ujira wao kwa ukamilifu, na awazidishie kutokana na fadhila zake. Hakika Yeye ni Mwenye kusamehe, Mwenye shukrani kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 31, 'Na hayo tuliyokufunulia kutoka Kitabuni ni Kweli, yenye kusadikisha yale yaliyokuwa kabla yake. Hakika Mwenyezi Mungu kwa waja wake ni Mwenye habari na Mwenye kuona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 32, 'Kisha tumewarithisha Kitabu hao ambao tuliwateua miongoni mwa waja wetu. Kati yao yupo aliyejidhulumu, na yupo wa katikati, na yupo aliyetangulia katika mambo ya heri, kwa idhini ya Mwenyezi Mungu. Hiyo ndiyo fadhila kuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 33, 'Mabustani ya milele watayaingia. Huko watavikwa vikuku vya dhahabu na lulu, na nguo zao humo ni za hariri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 34, 'Na watasema: Alhamdulillahi (Sifa njema zote ni za Mwenyezi Mungu) aliyetuondolea huzuni wote. Hakika Mola wetu Mlezi bila ya shaka ni Mwenye kusamehe, Mwenye shukrani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 35, 'Ambaye kwa fadhila yake ametuweka makao ya kukaa daima; humu haitugusi taabu wala humu hakutugusi kuchoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 36, 'Na wale waliokufuru watakuwa na Moto wa Jahannamu. Hawahukumiwi wakafa, wala hawatapunguziwa adhabu yake. Hivyo ndivyo tunavyomlipa kila mwenye kuzidi ukafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 37, 'Na humo watapiga makelele: ''Mola wetu Mlezi! Tutoe tufanye mema siyo yale tuliyokuwa tukiyafanya.'' Kwani hatukukupeni umri wa kutosha kukumbuka mwenye kukumbuka? Na akakukujieni Mwonyaji? Basi onjeni! Kwani wale waliodhulumu hawana wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 38, 'Kwa hakika Mwenyezi Mungu ni Mjuzi wa siri za mbinguni na ardhi. Hakika Yeye ni Mjuzi wa yaliomo vifuani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 39, 'Yeye ndiye aliyekufanyeni wafuatizi (makhalifa) katika ardhi. Na anayekufuru, basi kufuru yake ni juu yake. Na kufuru za makafiri haziwazidishii kwa Mola wao Mlezi ila kuchukiwa. Wala kufuru za makafiri haziwazidishii ila hasara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 40, 'Sema: Mnawaona hawa miungu wenu wa kishirikina mnaowaomba badala ya Mwenyezi Mungu! Nionyesheni wameumba sehemu gani katika ardhi? Au wana ushirika wowote katika mbingu? Au tumewapa Kitabu nao kwa hicho wakawa na hoja zilizo wazi? Lakini madhalimu hawaahidiani wao kwa wao ila udanganyifu tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 41, 'Hakika Mwenyezi Mungu ndiye anayezuilia mbingu na ardhi zisiondoke. Na zikiondoka hapana yeyote wa kuzizuia isipokuwa Yeye. Hakika Yeye ni Mpole Mwenye kusamehe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 42, 'Na waliapa kwa Mwenyezi Mungu ukomo wa kuapa kwao, kwamba akiwajia mwonyaji, bila ya shaka watakuwa waongofu zaidi kuliko taifa jingine lolote. Lakini alipowajia mwonyaji, hakuwazidishia ila kuikimbia hiyo Haki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 43, 'Kwa kutakabari kwao katika nchi, na kufanya vitimbi vya uovu. Na vitimbi viovu havimsibu ila mwenyewe aliyevifanya. Hebu, hawangojei yale yaliowasibu watu wa kale? Basi hutapata mabadiliko katika mtindo wa Mwenyezi Mungu. Wala hutapata mageuko katika mtindo wa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 44, 'Je, hawakusafiri katika ardhi wakaona vipi ulikuwa mwisho wa wale waliokuwa kabla yao? Na hao walikuwa wana nguvu zaidi kuliko wao. Na hapana kitu kinachoweza kumshinda Mwenyezi Mungu mbinguni wala katika ardhi. Hakika Yeye ni Mwenye kujua zaidi, Mwenye uweza wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 45, 'Na lau kuwa Mwenyezi Mungu angeliwachukulia watu kwa yale waliyoyachuma, basi asingelimuacha juu ya ardhi hata mnyama mmoja. Lakini Yeye anawaachilia mpaka ufike muda maalumu. Na muda wao ukifika, basi hakika Mwenyezi Mungu ni Mwenye kuwaona waja wake barabara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 1, 'Ya Sin.[1]', '[1] Herufi hizi "Ya, Sin" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 2, '(Ninaapa) kwa Qur-ani yenye hekima!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 3, 'Hakika wewe ni miongoni mwa waliotumwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 4, 'Juu ya njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 5, 'Uteremsho wa Mwenye nguvu, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 6, 'Ili uwaonye watu ambao baba zao hawakuonywa, basi wao wamekuwa wenye kughafilika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 7, 'Bila ya shaka kauli imekwisha thibiti juu ya wengi katika wao, kwa hivyo hawaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 8, 'Tumeweka makongwa shingoni mwao, yakawafika videvuni. Kwa hivyo vichwa vyao viko juu tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 9, 'Tumeweka kizuizi mbele yao, na kizuizi nyuma yao. Na tumewafunika macho yao, kwa hivyo hawaoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 10, 'Ni sawa sawa kwao ukiwaonya au usiwaonye, hawataamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 11, 'Hakika wewe unamwonya mwenye kufuata ukumbusho, na akamcha Arrahman (Mwingi wa rehema), kwa ghaibu. Basi mbashirie huyo msamaha na ujira mwema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 12, 'Hakika Sisi tunawafufua wafu na tunayaandika wanayoyatanguliza, na wanayoyaacha nyuma. Na kila kitu tumekihifadhi katika daftari la asili lenye kubainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 13, 'Na wapigie mfano wa wakazi wa mji walipojiwa na Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 14, 'Tulipowatumia wawili, wakawakanusha. Basi tukawazidishia nguvu kwa mwingine wa tatu. Wakasema: "Hakika sisi tumetumwa kwenu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 15, 'Wakasema: "Nyinyi si chochote ila ni watu kama sisi. Na Mwingi wa Rehema hakuteremsha kitu. Nyinyi mnasema uongo tu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 16, 'Wakasema: "Mola wetu Mlezi anajua kwamba hakika sisi tumetumwa kwenu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 17, 'Wala si juu yetu ila kufikisha ujumbe ulio wazi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 18, 'Wakasema: "Sisi hakika sisi tunaona mkosi kwenu. Ikiwa hamtaacha basi kwa yakini tutakupigeni mawe, na mtapata adhabu chungu kutoka kwetu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 19, 'Wakasema: "Mkosi wenu mnao wenyewe! Je! Ni kwa kuwa mnakumbushwa? Ama nyinyi ni watu waliopindukia mipaka."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 20, 'Na akaja mtu mbio kutokea upande wa mbali wa mjini, akasema: "Enyi watu wangu! Wafuateni hawa waliotumwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 21, 'Wafuateni ambao hawakutakini ujira, hali ya kuwa wenyewe wameongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 22, 'Na kwa nini nisimuabudu yule aliyeniumba na kwake nitarejeshwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 23, 'Je, niishike miungu mingine badala yake? Arrahmani (Mwingi wa Rehema) akinitakia madhara uombezi wa hao hautanifaa kitu, wala hawataniokoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 24, 'Basi hakika mimi hapo nitakuwa katika upotovu ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 25, 'Hakika mimi nimemuamini Mola wenu Mlezi, basi nisikilizeni!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 26, 'Akaambiwa: "Ingia Peponi!" Akasema: "Laiti kuwa watu wangu wangelijua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 27, 'Jinsi Mola wangu Mlezi alivyonisamehe, na akanifanya miongoni mwa walioheshimiwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 28, 'Na hatukuwateremshia kaumu yake baada yake jeshi kutoka mbinguni, wala si wenye kuteremsha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 29, 'Haukuwa ila ukelele mmoja tu, na mara walizimwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 30, 'Nawasikitikia waja wangu. Hawajii Mtume ila wao humkejeli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 31, 'Je, hawaoni umma ngapi tulizoziangamiza kabla yao? Hakika hao hawarejei tena kwao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 32, 'Na hapana mmoja ila wote watakusanywa waletwe mbele yetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 33, 'Na Ishara hiyo kwao ni ardhi iliyokufa, nasi tukaifufua, na tukatoa ndani yake nafaka, wakawa wanakula katika hizo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 34, 'Na tukafanya ndani yake mabustani ya mitende na mizabibu, na tukatimbua chemichemi ndani yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 35, 'Ili wale katika matunda yake, na hayo hayakufanywa na mikono yao! Basi je, hawashukuru?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 36, 'Ametakasika yule aliyeumba dume na jike vyote katika vinavyomea katika ardhi na katika nafsi zao, na katika wasivyovijua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 37, 'Na usiku ni Ishara kwao. Tunauvua humo mchana, mara wao wanakuwa gizani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 38, 'Na jua linakwenda kwa kiwango chake. Hayo ni makadirio ya Mwenye nguvu, Mwenye kujua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 39, 'Na mwezi tumeupimia vituo, mpaka unakuwa kama karara kongwe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 40, 'Haliwi jua kuufikia mwezi, wala usiku kuupita mchana. Na vyote vinaogelea katika njia zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 41, 'Na ni Ishara kwao kwamba Sisi tuliwapakia dhuria zao katika jahazi lililosheheni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 42, 'Na tukawaumbia kutoka mfano wake wanavyovipanda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 43, 'Na tukitaka, tunawazamisha, wala hapana wa kuwasaidia, wala hawaokolewi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 44, 'Isipokuwa kwa rehema zitokazo kwetu na starehe kwa muda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 45, 'Na wanapoambiwa: Jilindeni kutokana na yaliyoko mbele yenu na yaliyoko nyuma yenu, ili mpate kurehemewa...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 46, 'Na haiwafikii Ishara yoyote katika Ishara za Mola wao Mlezi isipokuwa wao huwa ni wenye kuipa mgongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 47, 'Na wanapoambiwa: "Toeni katika aliyokupeni Mwenyezi Mungu", wale waliokufuru huwaambia wale walioamini: Je, tuwalishe wale ambao Mwenyezi Mungu angependa angeliwalisha mwenyewe? Nyinyi hammo isipokuwa katika upotovu ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 48, 'Na wanasema: Ahadi hii itatokea lini, ikiwa nyinyi ni wakweli?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 49, 'Hawangojei isipokuwa ukelele mmoja tu utakaowachukua nao wamo kuzozana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 50, 'Basi hawataweza kuusia, wala kwa watu wao hawarejei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 51, 'Na litapulizwa baragumu, mara watatoka makaburini wakikimbilia kwa Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 52, 'Watasema: Ole wetu! Ni nani aliyetufufua kwenye malazi yetu? Haya ndiyo aliyoyaahidi Mwingi wa Rehema na wakasema kweli Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 53, 'Haitakuwa isipokuwa ukelele mmoja tu, mara wote watahudhurishwa mbele yetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 54, 'Basi leo nafsi yoyote haitadhulumiwa kitu, wala hamtalipwa isipokuwa yale mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 55, 'Hakika watu wa Bustani ya mbinguni leo wamo shughulini, wamefurahi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 56, 'Wao na wake zao wamo katika vivuli wameegemea juu ya viti vya kifahari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 57, 'Watapata humo kila namna ya matunda na watapata kila watakachokitaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 58, '"Salama!" Hiyo ndiyo kauli itokayo kwa Mola Mlezi Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 59, 'Na enyi wakosefu! Jitengeni leo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 60, 'Je, sikuagana nanyi, enyi wanadamu, kuwa msimuabudu Shetani? Hakika yeye ni adui dhahiri kwenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 61, 'Na ya kwamba mniabudu Mimi? Hii ndiyo Njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 62, 'Na bila ya shaka yeye amekwisha lipoteza kundi kubwa miongoni mwenu. Je, hamkuwa mkifikiri?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 63, 'Hii basi ndiyo Jahannamu mliyokuwa mkiahidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 64, 'Ingieni humo leo kwa vile mlivyokuwa mkikufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 65, 'Leo tunaviziba vinywa vyao, na iseme nasi mikono yao, na itoe ushahidi miguu yao kwa waliyokuwa wakiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 66, 'Na tungelipenda, tungeliyafutilia mbali macho yao, wakawa wanaiwania njia. Lakini wangeionaje?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 67, 'Na tungelitaka, tungewageuza sura hapo hapo walipo, basi wasingeweza kwenda wala kurudi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 68, 'Na tunayemzeesha, tunamrudisha nyuma katika umbo. Basi je, hawazingatii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 69, 'Wala hatukumfundisha (Muhammad) mashairi, wala hayatakikani kwake hayo. Haukuwa huu isipokuwa ni ukumbusho na Qur-ani inayobainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 70, 'Ili imwonye aliye hai, na neno litimie juu ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 71, 'Je, hawaoni kwamba tumewaumbia kutokana na iliyofanya mikono yetu wanyama wa mifugo, na wao wakawa wenye kuwamiliki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 72, 'Na Sisi tukawadhalilishia. Basi baadhi yao wako wanaowapanda, na baadhi yao wanawala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 73, 'Na wao wanapata kwao manufaa na vinywaji. Basi je, hawashukuru?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 74, 'Na wameishika miungu mingine badala ya Mwenyezi Mungu ili ati wapate kusaidiwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 75, 'Hawataweza kuwasaidia. Bali hao ndio askari wao, watahudhurishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 76, 'Basi maneno yao yasikuhuzunishe. Hakika Sisi tunayajua wanayoyaweka siri na wanayoyadhihirisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 77, 'Kwani mwanadamu haoni ya kwamba Sisi tumemuumba yeye kutokana na tone la manii? Kisha sasa yeye ndiyo amekuwa ndiye mgomvi wa dhahiri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 78, 'Na akatupigia mfano, na akasahau kuumbwa kwake, akasema: Ni nani huyo atakayeihuisha mifupa nayo imekwisha mung''unyika?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 79, 'Sema: Ataihuisha huyo huyo aliyeiumba hapo mara ya mwanzo. Na Yeye ni Mjuzi wa kila kuumba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 80, 'Aliyekujaalieni kupata moto kutokana na mti wa kijani nanyi mkawa kwa huo mnawasha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 81, 'Kwani aliyeziumba mbingu na ardhi hawezi kuwaumba mfano wao? Kwani! Naye ndiye Muumbaji Mkuu, Mjuzi mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 82, 'Hakika amri yake anapotaka kitu ni kukiambia tu: Kuwa! Na kikawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 83, 'Basi ametakasika yule ambaye mkononi mwake umo Ufalme wa kila kitu; na kwake Yeye mtarejeshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 1, 'Ninaapa kwa wanaojipanga kwa safu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 2, 'Na kwa wenye kukataza mabaya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 3, 'Na kwa wenye kusoma Ukumbusho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 4, 'Hakika Mungu wenu bila ya shaka ni Mmoja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 5, 'Mola Mlezi wa mbingu na ardhi, na yaliyomo kati yake, na ni Mola Mlezi wa mashariki zote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 6, 'Hakika Sisi tumeipamba mbingu ya karibu kwa pambo la nyota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 7, 'Na kulinda na kila shetani muasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 8, 'Wasiweze kuwasikiliza viumbe watukufu. Na wanafukuzwa huko kila upande.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 9, 'Wakifurushwa. Na wanayo adhabu ya kudumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 10, 'Isipokuwa anayenyakua kitu kidogo, na mara humfwatia kimondo kinachong''ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 11, 'Hebu waulize: Je! Wao ni wenye umbo gumu zaidi au hao wengine tuliowaumba. Hakika Sisi tuliwaumba wao kwa udongo unaonata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 12, 'Bali unastaajabu, na wao wanafanya masihara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 13, 'Na wanapokumbushwa, hawakumbuki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 14, 'Na wanapoona Ishara, wanafanya masihara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 15, 'Na husema: Haya si chochote isipokuwa ni uchawi tu ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 16, 'Ati tukishakufa na tukawa udongo na mifupa ndio kweli tutafufuliwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 17, 'Hata baba zetu wa zamani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 18, 'Sema: Naam! Hali nanyi ni madhalili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 19, 'Huko utapigwa ukelele mmoja tu! Na hapo ndipo wataona!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 20, 'Watasema: Ole wetu! Hii ndiyo Siku ya Malipo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 21, 'Hii ndiyo Siku ya Hukumu mliyokuwa mkiikadhibisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 22, 'Wakusanyeni wale waliodhulumu, na wote walio mfano wao, na hao ambao wao walikuwa wakiwaabudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 23, 'Badala ya Mwenyezi Mungu. Waongozeni njia ya Jahannamu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 24, 'Na wasimamisheni. Hakika hao wataulizwa:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 25, 'Mna nini? Mbona hamsaidiani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 26, 'Bali hii leo, watasalimu amri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 27, 'Wataelekeana wao kwa wao kuulizana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 28, 'Watasema: Kwa hakika nyinyi mlikuwa mkitujia upande wa kulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 29, 'Watasema (wakubwa): Bali nyinyi wenyewe hamkuwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 30, 'Sisi hatukuwa na mamlaka juu yenu, bali nyinyi wenyewe mlikuwa wapotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 31, 'Basi hukumu ya Mola wetu Mlezi imekwisha tuthibitikia. Hakika bila ya shaka tutaonja tu adhabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 32, 'Tulikupotezeni kwa sababu sisi wenyewe tulikuwa wapotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 33, 'Basi wao kwa hakika siku hiyo watashirikiana katika adhabu pamoja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 34, 'Hivyo ndivyo tutakavyowafanyia wahalifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 35, 'Wao walipokuwa wakiambiwa, "La ilaha illallaahu (Hapana mungu ila Mwenyezi Mungu tu)", wanajivuna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 36, 'Na wakisema: Hivyo sisi tuiache miungu yetu kwa ajili ya huyu mtunga mashairi mwendawazimu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 37, 'Bali huyu amekuja kwa haki, na amewasadikisha Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 38, 'Hakika nyinyi bila ya shaka mtaionja adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 39, 'Wala hamlipwi isipokuwa hayo mliyokuwa mkiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 40, 'Isipokuwa waja wa Mwenyezi Mungu walioteuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 41, 'Hao ndio watakaopata riziki maalumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 42, 'Matunda, nao wataheshimiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 43, 'Katika Bustani za neema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 44, 'Wako juu ya viti mfano wa kitanda wameelekeana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 45, 'Wanazungushiwa kikombe chenye kinywaji cha chemchemi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 46, 'Kinywaji cheupe, kitamu kwa wanywao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 47, 'Hakina madhara, wala hakiwaleweshi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 48, 'Na watakuwa nao wanawake wenye macho ya staha, mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 49, 'Hao wanawake kama mayai yaliyohifadhika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 50, 'Basi wakaelekeana kuulizana wenyewe kwa wenyewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 51, 'Aseme msemaji mmoja miongoni mwao: Hakika mimi nilikuwa na rafiki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 52, 'Aliyekuwa akiniambia: Hivyo wewe ni katika wanaosadiki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 53, 'Ati tukishakufa tukawa udongo na mafupa, ndiyo tutalipwa na kufanyiwa hesabu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 54, 'Atasema: Je, nyie mnawaona?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 55, 'Basi atachungulia amwone katikati ya Jahannamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 56, 'Atasema: Wallahi! (Naapa kwa jina la Mwenyezi Mungu) Ulikaribia sana kunipoteza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 57, 'Na lau kuwa si neema ya Mola wangu Mlezi, bila ya shaka ningelikuwa miongoni mwa waliohudhurishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 58, 'Je, sisi hatutakufa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 59, 'Isipokuwa kifo chetu cha kwanza? Wala sisi hatutaadhibiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 60, 'Hakika huku bila ya shaka ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 61, 'Kwa mfano wa haya na watende watendao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 62, 'Je, kukaribishwa hivi si ndiyo bora, au mti wa Zaqqum?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 63, 'Hakika Sisi tumeufanya huo kuwa ni mateso kwa waliodhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 64, 'Hakika huo ni mti unaotoka katikati ya Jahannamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 65, 'Mashada ya matunda yake kama kwamba ni vichwa vya mashetani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 66, 'Basi hakika bila ya shaka hao watayala hayo, na wajaze matumbo kwayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 67, 'Kisha juu yake wanyweshwe mchanganyo wa maji ya moto yaliyochemka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 68, 'Kisha hakika marejeo yao bila ya shaka yatakuwa Jahimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 69, 'Hakika waliwakuta baba zao wamepotea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 70, 'Na wao wakafanya haraka kufuata nyayo zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 71, 'Na bila ya shaka walikwisha potea kabla yao wengi wa watu wa zamani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 72, 'Na Sisi hakika tuliwapelekea waonyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 73, 'Basi hebu angalia ulikuwaje mwisho wa walioonywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 74, 'Isipokuwa waja wa Mwenyezi Mungu waliosafishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 75, 'Na hakika Nuhu alituita, na Sisi ni bora wa waitikiaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 76, 'Na tulimwokoa yeye na ahali zake kutokana na msiba mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 77, 'Na tuliwajaalia dhuria zake ndio wenye kubakia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 78, 'Na tukamwachia (sifa njema) kwa waliokuja baadaye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 79, 'Iwe salama kwa Nuhu ulimwenguni kote!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 80, 'Kwa hakika hivi ndivyo tunavyowalipa wanaofanya mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 81, 'Hakika yeye ni katika waja wetu walioamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 82, 'Kisha tukawazamisha wale wengine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 83, 'Na hakika Ibrahim alikuwa katika kundi lake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 84, 'Alipomjia Mola wake Mlezi kwa moyo mzima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 85, 'Alimwambia baba yake na watu wake: Mnaabudu nini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 86, 'Kwa kuzua tu mnataka miungu mingine badala ya Mwenyezi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 87, 'Mnamdhania nini Mola Mlezi wa walimwengu wote?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 88, 'Kisha akapiga jicho kutazama nyota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 89, 'Akasema: Hakika mimi ni mgonjwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 90, 'Nao wakamwacha, wakampa kisogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 91, 'Basi akaiendea miungu yao kwa siri, akaiambia: Mbona hamli?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 92, 'Mna nini hata hamsemi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 93, 'Kisha akaigeukia kuipiga kwa mkono wa kulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 94, 'Basi wakamjia upesi upesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 95, 'Akasema: Hivyo mnaviabudu vitu mnavyovichonga wenyewe?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 96, 'Na hali Mwenyezi Mungu ndiye aliyekuumbeni nyinyi na hivyo mnavyovifanya!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 97, 'Wakasema: Mjengeeni jengo, na kisha mtupeni motoni humo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 98, 'Basi walitaka kumfanyia vitimbi, lakini tukawafanya wao ndio wa chini zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 99, 'Na akasema: Hakika mimi nahama, nakwenda kwa Mola wangu Mlezi; Yeye ataniongoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 100, 'Ewe Mola wangu Mlezi! Nitunukie aliye miongoni mwa watenda mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 101, 'Basi tukambashiria mwana aliye mpole.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 102, 'Basi alipofika makamo ya kwenda na kurudi pamoja naye, alimwambia: Ewe mwanangu! Hakika mimi nimeona usingizini kuwa ninakuchinja. Basi angalia wewe, waonaje? Akasema: Ewe baba yangu! Tenda unavyoamrishwa, utanikuta mimi, Insha Allah (Mwenyezi Mungu akipenda), katika wanaosubiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 103, 'Basi wote wawili walipojisalimisha, na akamlaza juu ya kipaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 104, 'Tulimwita: Ewe Ibrahim!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 105, 'Umekwisha itimiliza ndoto. Hakika hivi ndivyo tunavyowalipa wanaotenda mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 106, 'Hakika haya ni majaribio yaliyo dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 107, 'Basi tukamtolea fidia kwa dhabihu mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 108, 'Na tukamwachia (sifa njema) kwa watu waliokuja baadaye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 109, 'Iwe salama kwa Ibrahim!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 110, 'Hivi ndivyo tunavyowalipa wanaofanya mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 111, 'Hakika yeye ni katika waja wetu walioamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 112, 'Na tukambashiria kuzaliwa Is-haqa, naye ni Nabii miongoni mwa watu wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 113, 'Na tukambarikia yeye na Is-haqa. Na miongoni mwa dhuria zao walitokea wema na wenye kudhulumu nafsi zao waziwazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 114, 'Na kwa hakika tuliwafanyia hisani Musa na Haruni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 115, 'Na tukawaokoa wao na watu wao kutokana na dhiki kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 116, 'Na tukawanusuru; na wakawa wao ndio wenye kushinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 117, 'Na tukawapa wawili hao Kitabu kinachobainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 118, 'Na tukawaongoa kwenye njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 119, 'Na tukawaachia (sifa njema) katika watu waliokuja baadaye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 120, 'Iwe salama kwa Musa na Haruni!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 121, 'Hakika hivyo ndivyo tunavyowalipa walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 122, 'Hakika wawili hao ni katika waja wetu walioamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 123, 'Na hakika Ilyas bila ya shaka alikuwa miongoni mwa Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 124, 'Alipowaambia watu wake: Hamumchi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 125, 'Mnamwomba Baa''li na mnamwacha Mbora wa waumbaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 126, 'Mwenyezi Mungu, Mola Mlezi wenu na Mola Mlezi wa baba zenu wa zamani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 127, 'Wakamkadhibisha. Basi kwa hakika watahudhurishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 128, 'Isipokuwa waja wa Mwenyezi Mungu waliosafishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 129, 'Na tumemwachia (sifa nzuri) kwa waliokuja baadaye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 130, 'Iwe salama kwa Ilyas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 131, 'Hakika hivyo ndivyo tunavyowalipa walio wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 132, 'Hakika yeye ni katika waja wetu walioamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 133, 'Na hakika Lut''i bila ya shaka ni miongoni mwa Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 134, 'Tulipomwokoa yeye na ahali zake wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 135, 'Isipokuwa mwanamke mkongwe katika wale waliobakia nyuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 136, 'Kisha tukawaangamiza wale wengineo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 137, 'Na hakika nyinyi mnawapitia wakati wa asubuhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 138, 'Na usiku. Basi je, hamyatii akilini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 139, 'Na hakika Yunus alikuwa miongoni mwa Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 140, 'Alipokimbia akenda katika jahazi lililosheheni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 141, 'Akaingia katika kupigiwa kura, na akawa katika walioshindwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 142, 'Samaki akammeza hali ya kuwa ni mwenye kulaumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 143, 'Na ingelikuwa hakuwa katika wanaomtakasa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 144, 'Bila ya shaka angelikaa ndani yake mpaka siku ya kufufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 145, 'Lakini tulimtupa ufukweni patupu, hali yu mgonjwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 146, 'Na tukauotesha juu yake mmea wa aina ya mung''unye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 147, 'Na tulimtuma kwa watu laki moja au zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 148, 'Basi wakaamini, na tukawastarehesha kwa muda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 149, 'Basi waulize: Ati Mola wako Mlezi ndiye mwenye watoto wa kike, na wao wanao watoto wa kiume?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 150, 'Au tumewaumba Malaika kuwa ni wanawake, na wao wakashuhudia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 151, 'Tazama, hakika ni kwa uzushi wao ndio wanasema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 152, 'Mwenyezi Mungu amezaa! Ama hakika bila ya shaka hao ni waongo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 153, 'Ati amehiari watoto wa kike kuliko wanaume?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 154, 'Mna nini? Mnahukumu vipi nyinyi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 155, 'Hamkumbuki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 156, 'Au mnayo hoja iliyo wazi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 157, 'Basi leteni Kitabu chenu kama nyinyi ni wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 158, 'Na wameweka mahusiano ya nasaba baina yake na majini; na majini wamekwishajua bila ya shaka kuwa wao watahudhurishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 159, 'Ametakasika Mwenyezi Mungu mbali na hayo wanayomsingizia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 160, 'Isipokuwa waja wa Mwenyezi Mungu waliosafishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 161, 'Basi hakika nyinyi na mnaowaabudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 162, 'Hamwezi kuwapoteza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 163, 'Isipokuwa yule atakayeingia Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 164, 'Na hapana katika sisi ila anapo mahali pake maalumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 165, 'Na hakika bila ya shaka sisi ndio wajipangao safu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 166, 'Na hakika sisi ndio wenye kutakasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 167, 'Na walikuwapo waliokuwa wakisema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 168, 'Tungelikuwa na Ukumbusho kama wa watu wa zamani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 169, 'Bila ya shaka tungelikuwa ni waja wa Mwenyezi Mungu wenye kumkusudia Yeye tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 170, 'Lakini waliukufuru. Basi watakuja jua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 171, 'Na bila ya shaka neno letu lilikwisha tangulia kwa waja wetu waliotumwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 172, 'Ya kuwa wao bila ya shaka ndio watakaonusuriwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 173, 'Na kwamba jeshi letu ndilo litakaloshinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 174, 'Basi waachilie mbali kwa muda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 175, 'Na watazame, nao wataona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 176, 'Je, wanaiharakishia adhabu yetu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 177, 'Basi itakaposhuka uwanjani kwao, itakuwa asubuhi mbaya kwa walioonywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 178, 'Na waache kwa muda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 179, 'Na tazama, na wao wataona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 180, 'Ametakasika Mola wako Mlezi Mwenye utukufu mbali na yale wanayomzulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 181, 'Na Salamu juu ya Mitume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 182, 'Na sifa njema zote ni za Mwenyezi Mungu Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 1, 'Swad. Ninaapa kwa Qur-ani yenye ukumbusho.[1]', '[1] Herufi hii "Swad" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 2, 'Lakini waliokufuru wamo katika majivuno na upinzani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 3, 'Mataifa mangapi tumeyaangamiza kabla yao, na wakapiga kelele, lakini wakati wa kuokoka ulikwishapita.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 4, 'Na walistaajabu kuwajia mwonyaji anayetokana nao wenyewe, na makafiri wakasema: Huyu ni mchawi, mwongo mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 5, 'Amewafanya miungu wote kuwa ni mungu mmoja tu? Hakika hili ni jambo la ajabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 6, 'Na wakaondoka wakubwa wao wakiwaambia: Nendeni zenu na dumuni na miungu yenu, kwani hili ni jambo lililopangwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 7, 'Sisi hatukusikia haya katika mila hii ya mwisho. Haya si chochote ila ni uzushi tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 8, 'Ati yeye tu ndiye aliyeteremshiwa mawaidha peke yake katika sisi? Lakini hao wana shaka na mawaidha yangu, bali hawajaionja adhabu yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 9, 'Au wanazo wao hazina za rehema za Mola wako Mlezi, Mwenye nguvu, Mpaji?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 10, 'Au wao wana ufalme wa mbingu na ardhi na vilivyo kati yavyo? Basi na wazipande njia za kwendea huko!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 11, 'Hao ni askari watakaoshindwa miongoni mwa makundi yatakayoshindwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 12, 'Walikanusha kabla yao kaumu ya Nuhu, na kina A''adi na Firauni mwenye majengo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 13, 'Na Thamud na kaumu Luti na watu wa Machakani. Hayo ndiyo makundi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 14, 'Hao wote waliwakadhibisha Mitume; basi wakastahiki adhabu yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 15, 'Na hawa hawangojei ila ukelele mmoja tu usio wa kuchelewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 16, 'Na walisema: ‘Mola wetu Mlezi! Tuletee upesi sehemu yetu ya adhabu kabla ya Siku ya Hesabu.’', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 17, 'Subiri kwa hayo wayasemayo, na umkumbuke mja wetu Daudi, mwenye nguvu. Hakika yeye alikuwa mwingi wa kutubia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 18, 'Hakika tuliidhalilisha milima pamoja naye ikisabihi jioni na asubuhi pamoja naye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 19, 'Na pia ndege waliokusanywa makundi kwa makundi; wote walikuwa wanyenyekevu kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 20, 'Na tukautia nguvu ufalme wake, na tukampa hekima, na kukata hukumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 21, 'Na je, imekufikia habari ya wagombanao walipopindukia ukuta kuingia chumbani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 22, 'Walipomuingilia Daudi, naye akawaogopa. Wakasema: Usiogope! Sisi ni wagombanao wawili, mmoja wetu amemdhulumu mwenziwe. Basi tuhukumu kwa haki, wala usipendelee. Na utuongoe kwenye njia iliyo sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 23, 'Hakika huyu ndugu yangu ana kondoo wa kike tisini na tisa; na mimi ninaye kondoo mke mmoja. Akasema: Nipe huyo nikufugie! Na amenishinda kwa maneno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 24, 'Akasema: Kweli amekudhulumu kwa kumtaka kondoo wako mmoja kuongezea kwenye kondoo wake. Na hakika washirika wengi hudhulumiana wao kwa wao, isipokuwa walioamini na wakatenda mema. Na hao ni wachache. Na Daudi akajua kuwa tumemfanyia mtihani. Basi akamwomba msamaha Mola wake Mlezi, na akaanguka kusujudu na kutubia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 25, 'Basi tukamsamehe kwa hayo. Naye kwa hakika anao mkaribisho mkubwa na marejeo mazuri kwetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 26, 'Ewe Daudi! Hakika Sisi tumekufanya wewe uwe Khalifa katika nchi. Basi wahukumu watu kwa haki, wala usifuate matamanio yakakupoteza ambali na Njia ya Mwenyezi Mungu. Hakika wanaoipotea Njia ya Mwenyezi Mungu wakaiacha, watapata adhabu kali kwa sababu ya kusahau kwao Siku ya Hisabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 27, 'Na hatukuziumba mbingu na ardhi na vilivyo kati yake bure. Hiyo ni dhana ya waliokufuru. Ole wao waliokufuru kwa Moto utakaowapata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 28, 'Je, tuwafanye walioamini na wakatenda mema kama wafanyao uharibifu katika nchi? Au tuwafanye wacha Mungu kama waovu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 29, 'Na hiki Kitabu, tumekuteremshia wewe, kimebarikiwa, ili wazizingatie Aya zake, na wawaidhike wenye akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 30, 'Na Daudi tukamtunukia Suleiman. Alikuwa mja mwema. Na hakika alikuwa mwingi wa kutubia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 31, 'Alipopelekewa jioni farasi wasimamao kidete, tayari kutoka shoti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 32, 'Basi akasema: Navipenda vitu vizuri kwa kumkumbuka Mola wangu Mlezi. Kisha wakafichikana nyuma ya boma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 33, '(Akasema:) Nirudishieni hao! Basi akaanza kuwapapasa miguu na shingo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 34, 'Na tulimtia mtihanini Suleiman, na tukauweka mwili juu ya kiti chake, kisha akarejea kwa kutubu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 35, 'Akasema: Mola wangu Mlezi! Nisamehe na unipe ufalme usiomwelekea yeyote baada yangu. Hakika Wewe ndiye Mpaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 36, 'Basi tukaufanya upepo umtumikie, ukenda kwa amri yake, popote alipotaka kufika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 37, 'Na tukayafanya mashetani yamtumikie, wote wajenzi na wapiga mbizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 38, 'Na wengine wafungwao kwa minyororo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 39, 'Hiki ndicho kipawa chetu. Basi toa au zuia, bila ya hisabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 40, 'Na hakika yeye kwetu Sisi ana cheo cha kukaribishwa kwetu, na pahala pazuri pa kurejea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 41, 'Na mkumbuke mja wetu Ayubu alipomwita Mola wake Mlezi akasema: Kwa hakika Shetani amenifikishia udhia na adhabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 42, '(Akaambiwa:) Piga-piga ardhi kwa mguu wako! Basi haya maji baridi ya kuogea na ya kunywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 43, 'Na tukampa ahali zake na wengine kama wao pamoja nao, kuwa ni rehema itokayo kwetu, na iwe kumbusho kwa watu wenye akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 44, 'Na shika kicha cha vijiti tu mkononi mwako, kisha ndio upigie nacho, wala usivunje kiapo. Hakika tulimkuta mwenye subira, mbora wa waja, kwa hakika alikuwa mwingi wa kutubu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 45, 'Na wakumbuke waja wetu, Ibrahim na Is-haqa na Yaa''qubu waliokuwa na nguvu na busara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 46, 'Sisi tumewahusisha wao kwa sifa ya ukumbusho wa Akhera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 47, 'Na hakika wao kwetu sisi ni wateuliwa walio bora.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 48, 'Na mtaje Ismail na Alyasaa na Dhulkifli, na wote hao ni katika walio bora.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 49, 'Huu ni ukumbusho. Na hakika wacha Mungu wana marudio mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 50, 'Bustani za milele zitakazofunguliwa milango yao kwa ajili yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 51, 'Humo wataegemea matakia, wawe wanaagiza humo matunda mengi na vinywaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 52, 'Na pamoja nao wake zao wenye kutuliza macho, hirimu moja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 53, 'Haya ndiyo mliyoahidiwa kwa Siku ya Hisabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 54, 'Hakika hii ndiyo riziki yetu isiyomalizika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 55, 'Ndiyo hivi! Na hakika wenye kuasi bila ya shaka watapata marudio maovu kabisa;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 56, 'Nayo ni Jahannamu! Wataingia humo. Nacho hicho ni kitanda kiovu mno cha kulalia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 57, 'Ndiyo hivi! Basi na wayaonje maji ya moto na ya usaha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 58, 'Na adhabu nyenginezo za namna hii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 59, 'Hili ndilo kundi litakalo ingia pamoja nanyi. Hapana makaribisho mema kwao. Hakika hao wanaingia Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 60, 'Waseme: Lakini nyinyi! Hamna mapokezi mazuri! Nyinyi ndio mliotusababishia haya, napo ni pahala paovu kabisa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 61, 'Waseme: Mola wetu Mlezi aliyetusababishia haya, mzidishie adhabu mara mbili Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 62, 'Watasema: Tuna nini hata hatuwaoni wale watu ambao tukiwahisabu ndio katika waovu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 63, 'Tulikosea tulipowafanyia masihara, au macho yetu tu hayawaoni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 64, 'Hakika hayo bila ya shaka ndiyo mahasimiano ya watu wa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 65, 'Sema: Hakika mimi ni mwonyaji tu; na hapana mungu ila Mwenyezi Mungu Mmoja, Mtenda nguvu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 66, 'Mola Mlezi wa mbingu na ardhi na vilivyo baina yake, Mwenye nguvu, Mwenye kusamehe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 67, 'Sema: Hii ni habari kubwa kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 68, 'Ambayo nyinyi mnaipuuza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 69, 'Sikuwa na elimu ya mambo ya viumbe wakuu watukufu walipokuwa wakishindana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 70, 'Haikufunuliwa kwangu isipokuwa ya kwamba hakika mimi ni mwonyaji dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 71, 'Mola wako Mlezi alipowaambia Malaika: Hakika Mimi nitaumba mtu kutokana na udongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 72, 'Na nitakapomkamilisha na kumpulizia roho inayotokana nami, basi muangukieni kwa kumtii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 73, 'Basi wakasujudu Malaika wote pamoja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 74, 'Isipokuwa Iblisi; alijivuna na akawa katika makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 75, 'Mwenyezi Mungu akamwambia: Ewe Iblisi! Kipi kilichokuzuia kumtii yule niliyemuumba kwa mikono yangu? Je, umejiona mkubwa, au umekuwa katika wakuu kweli?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 76, 'Akasema: Mimi ni bora kuliko yeye. Umeniumba kwa moto, na yeye umemuumba kwa udongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 77, 'Akasema: Basi toka humo, kwani hakika wewe umelaaniwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 78, 'Na hakika laana yangu itakuwa juu yako mpaka Siku ya Malipo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 79, 'Akasema: Mola wangu Mlezi! Nipe muhula mpaka siku watakayofufuliwa viumbe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 80, 'Mwenyezi Mungu akasema: Basi umekwisha kuwa miongoni mwa waliopewa muhula.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 81, 'Mpaka siku ya wakati maalumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 82, 'Akasema (Iblisi): Naapa kwa utukufu wako, bila ya shaka nitawapoteza wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 83, 'Isipokuwa wale waja wako miongoni mwao waliohitariwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 84, 'Akasema: Haki! Na haki ninaisema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 85, 'Bila ya shaka nitaijaza Jahannamu kwa wewe na kwa hao wote wenye kukufuata miongoni mwao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 86, 'Sema (Ewe Mtume): Sikuombeni ujira juu ya haya, wala mimi si katika wadanganyifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 87, 'Hayakuwa haya ila ni mawaidha kwa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 88, 'Na bila ya shaka mtajua habari zake baada ya muda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 1, 'Uteremsho wa Kitabu hiki umetokana na Mwenyezi Mungu, Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 2, 'Hakika Sisi tumekuteremshia Kitabu hiki kwa Haki. Basi muabudu Mwenyezi Mungu ukimsafia Dini Yeye tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 3, 'Hakika Dini Safi ni ya Mwenyezi Mungu tu. Na wale wanaowafanya wenginewe kuwa ni walinzi wakisema: Sisi hatuwaabudu ila wapate kutujongeza tu kumkaribia Mwenyezi Mungu - Hakika Mwenyezi Mungu atahukumu baina yao katika wanayohitalifiana. Hakika Mwenyezi Mungu hamwongoi aliye mwongo kafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 4, 'Lau kuwa Mwenyezi Mungu angelitaka kuwa na mwana, basi bila ya shaka angeliteua amtakaye katika aliowaumba. Ametakasika na hayo! Yeye ni Mwenyezi Mungu Mmoja, Mtenda atakalo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 5, 'Ameumba mbingu na ardhi kwa Haki. Hufunika usiku juu ya mchana, na hufunika mchana juu ya usiku. Na amefanya jua na mwezi vitumike. Kila kimojapo kinakwenda kwa kipindi kilichowekewa. Jueni mtanabahi! Yeye ndiye Mwenye nguvu, Mwenye kusamehe!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 6, 'Amewaumba kutokana na nafsi moja. Kisha akamfanya mwenziwe katika nafsi ile ile. Na akawaletea wanyama wa mifugo jozi nane. Anawaumba katika matumbo ya mama zenu, umbo baada ya umbo, katika viza vitatu. Huyu ndiye Mwenyezi Mungu Mola wenu Mlezi. Ufalme ni wake. Hapana mungu isipokuwa Yeye. Basi nyinyi mnageuzwa wapi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 7, 'Mkikufuru basi Mwenyezi Mungu si mwenye haja nanyi, lakini hafurahii kufuru kwa waja wake. Na mkishukuru Yeye hufurahika nanyi. Wala mbebaji habebi mzigo wa mwingine. Kisha marejeo yenu ni kwa Mola wenu Mlezi. Hapo atawaambia mliyokuwa mkiyafanya. Hakika Yeye ni Mwenye kuyajua vyema yaliyomo vifuani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 8, 'Na taabu inapomfikia mtu humwomba Mola wake Mlezi naye ameelekea kwake. Kisha akimpa neema kutoka kwake, husahau yale aliyokuwa akimwomba zamani, na akamfanyia Mwenyezi Mungu washirika ili apoteze watu mbali na njia yake. Sema: Starehe na ukafiri wako kwa muda mchache. Kwani hakika wewe utakuwa miongoni mwa watu wa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 9, 'Je, afanyaye ibada nyakati za usiku kwa kusujudu na kusimama akitahadhari na Akhera, na akitaraji rehema za Mola wake Mlezi... Sema: Ati watakuwa sawa wale wanaojua na wale wasiojua? Hakika wanaokumbuka ni watu wenye akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 10, 'Sema: Enyi waja wangu mlioamini! Mcheni Mola wenu Mlezi. Wale wafanyao wema katika dunia hii watapata wema. Na ardhi ya Mwenyezi Mungu ni kunjufu. Hakika wenye subira watapewa ujira wao bila ya hisabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 11, 'Sema: Hakika mimi nimeamrishwa nimuabudu Mwenyezi Mungu kwa kumsafishia Dini Yeye tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 12, 'Na nimeamrishwa niwe wa mwanzo wa Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 13, 'Sema: Hakika mimi ninaogopa adhabu ya Siku Kubwa nikimuasi Mola wangu Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 14, 'Sema: Mwenyezi Mungu tu namuabudu kwa kumsafishia Yeye tu Dini yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 15, 'Basi nyinyi abuduni mpendacho badala yake Yeye. Sema: Hakika waliohasirika ni wale waliojihasiri na ahali zao Siku ya Kiyama. Tambueni kuwa hiyo ndiyo hasara iliyo dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 16, 'Yatawekwa juu yao matabaka ya moto, na chini yao matabaka. Kwa hayo Mwenyezi Mungu anawahofisha waja wake. Enyi waja wangu! Nicheni Mimi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 17, 'Na wale wanaojiepusha ibada potovu, na wakarejea kwa Mwenyezi Mungu, watapata bishara njema. Basi wabashirie waja wangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 18, 'Ambao husikiliza maneno, wakafuata lililo bora yake. Hao ndio aliowaongoa Mwenyezi Mungu, na hao ndio wenye akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 19, 'Je, yule mwenye kustahiki hukumu ya adhabu, je, wewe unaweza kumwokoa aliye katika Moto?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 20, 'Lakini waliomcha Mola wao Mlezi watapata ghorofa zilizojengwa juu ya ghorofa; chini yake hupita mito. Ndiyo ahadi ya Mwenyezi Mungu. Mwenyezi Mungu havunji ahadi yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 21, 'Je, huoni kwamba Mwenyezi Mungu ameteremsha maji kutoka mbinguni. Kisha akayapitisha kwenye chemchemi katika ardhi, kisha kwa maji hayo akatoa mimea yenye rangi mbalimbali? Kisha hunyauka ukaiona imekuwa kimanjano, na kisha huifanya mapepe. Bila ya shaka katika hayo upo ukumbusho kwa wenye akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 22, 'Je, yule ambaye Mwenyezi Mungu amemfungulia kifua chake kwa Uislamu, na akawa yuko kwenye nuru itokayo kwa Mola wake Mlezi (ni sawa na mwenye moyo mgumu?) Basi ole wao wenye nyoyo ngumu zisizomkumbuka Mwenyezi Mungu! Hao wamo katika upotovu wa dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 23, 'Mwenyezi Mungu ameteremsha hadithi nzuri kabisa, Kitabu chenye kufanana na kukaririwa; husisimua kwacho ngozi za wenye kumhofu Mola wao Mlezi. Kisha ngozi zao na nyoyo zao hulainika kwa kumkumbuka Mwenyezi Mungu. Huo ndio uongofu wa Mwenyezi Mungu, na kwa huo humwongoa amtakaye. Na ambaye ameachwa na Mwenyezi Mungu kupotea, basi hapana wa kumwongoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 24, 'Je, atakayekuwa anapambana kwa uso wake na adhabu mbaya kabisa Siku ya Kiyama, (ni sawa na watenda wema?) Na wataambiwa wenye kudhulumu: Onjeni hayo mliyokuwa mkiyachuma!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 25, 'Waliokuwa kabla yao walikadhibisha, na ikawajia adhabu kutoka pahala wasipopatambua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 26, 'Basi Mwenyezi Mungu akawaonjesha hizaya katika uhai wa duniani. Na bila ya shaka adhabu ya Akhera ni kubwa zaidi; laiti wangelijua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 27, 'Na bila ya shaka tumewapigia watu mifano ya kila namna katika hii Qur-ani ili wapate kukumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 28, 'Qur-ani ya Kiarabu isiyo na upogo, ili wamche Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 29, 'Mwenyezi Mungu amepiga mfano wa mtu mwenye mabwana washirika wanaogombana, na wa mtu mwingine aliyehusika na bwana mmoja tu. Je, wako sawa katika hali zao? Sifa njema zote ni za Mwenyezi Mungu! Lakini wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 30, 'Kwa hakika wewe utakufa, na wao watakufa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 31, 'Kisha bila ya shaka mtagombana Siku ya Kiyama mbele ya Mola wenu Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 32, 'Basi ni nani dhalimu mkubwa kuliko yule aliyemsingizia uongo Mwenyezi Mungu na akaukadhibisha ukweli ulipomfikia? Je, siyo katika Jahannamu makazi ya hao makafiri?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 33, 'Na aliyeuleta ukweli na akausadiki - hao ndio wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 34, 'Watapata watakachotaka kwa Mola wao Mlezi. Hayo ndiyo malipo ya watendao mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 35, 'Ili Mwenyezi Mungu awafutie ukomo wa uovu walioufanya na awalipe ujira wao kwa mujibu wa ukomo wa wema waliokuwa wakiutenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 36, 'Je, Mwenyezi Mungu si wa kumtosheleza mja wake? Na ati wanakutishia kwa hao wenginewe wasiokuwa Yeye! Na aliyepotezwa na Mwenyezi Mungu, basi hana wa kumwongoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 37, 'Na ambaye Mwenyezi Mungu anamwongoa, basi hana wa kumpotoa. Je, Mwenyezi Mungu si Mwenye nguvu, anayeweza kulipiza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 38, 'Na ukiwauliza: Ni nani aliyeziumba mbingu na ardhi. Bila ya shaka watasema: Mwenyezi Mungu. Sema: Je, mnawaonaje wale mnaowaomba badala ya Mwenyezi Mungu, ikiwa Mwenyezi Mungu akitaka kunidhuru, wao wanaweza kuniondolea dhara yake? Au akitaka kunirehemu, je, wao wanaweza kuzuia rehema yake? Sema: Mwenyezi Mungu ananitosheleza. Kwake Yeye na wategemee wanaotegemea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 39, 'Sema: Enyi watu wangu! Fanyeni muwezavyo, mimi pia nafanya. Basi mtakuja ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 40, 'Ni nani itakayemfikia adhabu ya kumhizi na itakayemshukia adhabu ya daima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 41, 'Hakika Sisi tumekuteremshia Kitabu kwa ajili ya watu wote kwa Haki. Kwa hivyo, mwenye kuongoka, ni kwa faida ya nafsi yake. Na mwenye kupotoka, bila ya shaka amepotoka kwa hasara yake. Na wewe si mlinzi juu yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 42, 'Mwenyezi Mungu huzipokea roho zinapokufa. Na zile zisizokufa wakati wa kulala kwake, huzishika zilizohukumiwa kufa, na huzirudisha nyingine mpaka ufike wakati uliowekwa. Hakika katika hayo bila ya shaka zipo Ishara kwa watu wanaofikiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 43, 'Au ndio wanachukua waombezi badala ya Mwenyezi Mungu? Sema: Ingawa hawana mamlaka juu ya kitu chochote, wala hawatambui lolote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 44, 'Sema: Uombezi wote uko kwa Mwenyezi Mungu. Ni wake Yeye tu ufalme wa mbingu na ardhi. Kisha mtarejeshwa kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 45, 'Na anapotajwa Mwenyezi Mungu peke yake, nyoyo za wasioiamini Akhera huchafuka. Na wanapotajwa wenginewe wasiokuwa Yeye, basi wao hufurahi mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 46, 'Sema: Ewe Mwenyezi Mungu! Muumba mbingu na ardhi! Mjuzi wa yasiyoonekana na yanayoonekana! Wewe utahukumu baina ya waja wako katika yale waliyokuwa wakihitalifiana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 47, 'Na lau kuwa wale waliodhulumu wangelikuwa na vyote vilivyomo duniani na pamoja navyo vingine kama hivyo, bila ya shaka wangelivitoa kujikomboa kutokana na adhabu mbaya hiyo Siku ya Kiyama. Na yatawadhihirikia kwa Mwenyezi Mungu wasiyokuwa wakiyatarajia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 48, 'Na utawadhihirikia ubaya wa yale waliyoyachuma, na yatawazingira na kuwafika yale waliyokuwa wakiyafanyia mzaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 49, 'Na dhara inapomgusa mtu, hutuomba. Kisha tunapompa neema zitokazo kwetu, husema: Nimepewa haya kwa sababu ya elimu yangu. Sivyo! Huo ni mtihani! Lakini wengi wao hawajui!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 50, 'Waliyasema haya wale waliokuwa kabla yao, lakini hayakuwafaa waliyokuwa wakiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 51, 'Basi ukawasibu uovu wa yale waliyoyachuma. Na wale waliodhulumu miongoni mwa hawa utawasibu uovu wa yale waliyoyachuma vile vile. Nao si wenye kushinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 52, 'Kwani wao hawajui kwamba Mwenyezi Mungu humkunjulia riziki amtakaye na kumkunjia? Hakika katika haya bila ya shaka zipo Ishara kwa watu wanaoamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 53, 'Sema: Enyi waja wangu waliojidhulumu nafsi zao! Msikate tamaa na rehema ya Mwenyezi Mungu. Hakika Mwenyezi Mungu husamehe dhambi zote. Hakika Yeye ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 54, 'Na rejeeni kwa Mola wenu Mlezi, na silimuni kwake, kabla ya kuwajieni adhabu. Kisha hapo hamtanusuriwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 55, 'Na fuateni yaliyo bora kabisa katika yale yaliyoteremshwa kwenu kutoka kwa Mola wenu Mlezi, kabla haijakujieni adhabu kwa ghafla, na hali hamtambui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 56, 'Isije ikasema nafsi: Ee majuto yangu kwa yale niliyopoteza upande wa Mwenyezi Mungu, na hakika nilikuwa miongoni mwa wanaofanya maskhara!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 57, 'Au ikasema: Ingelikuwa Mwenyezi Mungu ameniongoa, bila ya shaka ningelikuwa miongoni mwa wenye kumcha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 58, 'Au ikasema inapoona adhabu: Lau kuwa ningelipata fursa nyingine, ningelikuwa miongoni mwa wafanya mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 59, 'Wapi! Bila ya shaka zilikujia Ishara zangu, nawe ukazikadhibisha, na ukajivuna, na ukawa miongoni mwa makafiri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 60, 'Na Siku ya Kiyama utawaona waliomsingizia uongo Mwenyezi Mungu nyuso zao zimesawijika. Je, si katika Jahannamu makazi ya wanaotakabari?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 61, 'Na Mwenyezi Mungu atawaokoa wenye kujikinga kwa ajili ya kufuzu kwao. Hapana uovu utakaowagusa, wala hawatahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 62, 'Mwenyezi Mungu ndiye Muumba wa kila kitu, na Yeye ndiye Mlinzi juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 63, 'Yeye anazo funguo za mbingu na ardhi. Na wale waliozikataa Ishara za Mwenyezi Mungu, hao ndio wenye kuhasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 64, 'Sema: Je, mnaniamrisha nimuabudu asiyekuwa Mwenyezi Mungu, enyi majahili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 65, 'Na kwa yakini yamefunuliwa kwako na kwa waliokuwa kabla yako: Bila ya shaka ukimshirikisha Mwenyezi Mungu matendo yako yataharibika, na lazima utakuwa miongoni mwa wenye kuhasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 66, 'Bali muabudu Mwenyezi Mungu tu, na uwe miongoni mwa wenye kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 67, 'Na wala hawakumheshimu Mwenyezi Mungu kama anavyostahiki kuheshimiwa. Na Siku ya Kiyama ardhi yote itakuwa mkononi mwake, na mbingu zitakunjwa katika mkono wake wa kiume. Ametakasika na Ametukuka na hayo wanayomshirikisha nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 68, 'Na litapulizwa barugumu, wazimie waliomo mbinguni na waliomo katika ardhi, isipokuwa aliyemtaka Mwenyezi Mungu. Kisha litapulizwa mara nyingine. Hapo watainuka wawe wanangojea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 69, 'Na ardhi itang''ara kwa Nuru ya Mola wake Mlezi, na Kitabu kitawekwa, na wataletwa Manabii na mashahidi, na patahukumiwa baina yao kwa haki, wala hawatadhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 70, 'Na kila nafsi italipwa kwa yale iliyoyafanya, na Yeye anayajua sana wanayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 71, 'Na wale waliokufuru wataongozwa kuendea Jahannamu kwa makundi. Mpaka watakapoifikia, itafunguliwa milango yake, na walinzi wake watawaambia: Kwani hawakukujilieni Mitume miongoni mwenu wakikusomeeni Aya za Mola wenu Mlezi na kukuonyeni mkutano wa siku yenu hii? Watasema: Kwani! Lakini limekwisha thibiti neno la adhabu juu ya makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 72, 'Itasemwa: Ingieni milango ya Jahannamu mdumu humo. Basi nayo ni ubaya ulioje wa makazi ya wanaotakabari!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 73, 'Na wale waliomcha Mola wao Mlezi wataongozwa kuendea Peponi kwa makundi, mpaka watakapofikia, nayo milango yake imekwisha funguliwa. Walinzi wake watawaambia: Amani iwe juu yenu! Mmetahirika. Basi ingieni humu mkae milele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 74, 'Nao watasema: Sifa njema zote ni za Mwenyezi Mungu aliyetutimizia ahadi yake, na akaturithisha ardhi, tunakaa katika Bustani popote tupendapo. Basi ni malipo mazuri yaliyoje ya watendao!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 75, 'Na utawaona Malaika wakizunguka pembeni mwa Kiti cha enzi cha Mwenyezi Mungu, wakimtakasa na kumsifu Mola wao Mlezi. Na patahukumiwa baina yao kwa haki na patasemwa: Sifa zote njema ni za Mwenyezi Mungu, Mola Mlezi wa viumbe vyote!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 1, 'Ha Mim.[1]', '[1] Herufi hizi "Ha, Mim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 2, 'Uteremsho wa Kitabu umetoka kwa Mwenyezi Mungu Mwenye nguvu, Mwenye kujua vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 3, 'Anayesamehe dhambi na anayepokea toba, Mkali wa kuadhibu, Mwenye ukarimu, hakuna mungu ila Yeye; marejeo ni kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 4, 'Hawazibishi Ishara za Mwenyezi Mungu ila wale waliokufuru; basi kusikudanganye wewe kutangatanga kwao katika nchi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 5, 'Kabla yao walikadhibisha kaumu ya Nuhu na makundi mengine baada yao. Na kila taifa lilikuwa na hamu juu ya Mtume wao wamkamate. Na walibishana kwa upotovu ili kuipindua haki. Kwa hivyo niliwakamata. Basi ilikuwaje adhabu yangu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 6, 'Namna hivi limewathibitikia makafiri neno la Mola wako Mlezi ya kwamba wao ni watu wa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 7, 'Wale wanaobeba Kiti cha Enzi, na wale walio pembezoni mwake, wanamsabihi na kumhimidi Mola wao Mlezi, na wanamuamini, na wanawaombea msamaha walioamini kwa kusema: Mola wetu Mlezi! Umekienea kila kitu kwa rehema na ujuzi. Basi wasamehe wale waliotubu na wakaifuata Njia yako, na waepushe na adhabu ya Jahanamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 8, 'Mola wetu Mlezi! Na waingize katika Bustani za Milele ulizowaahidi. Na uwape haya pia wale waliofanya mema miongoni mwa wazee wao na wake zao na dhuriya zao. Hakika Wewe ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 9, 'Na waepushe na maovu; kwani umwepushaye maovu siku hiyo, hakika umemrehemu; na huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 10, 'Kwa hakika wale waliokufuru watanadiwa: Bila ya shaka kukuchukieni Mwenyezi Mungu ni kukubwa kuliko kujichukia nyinyi nafsi zenu, mlipokuwa mnaitwa kwenye Imani nanyi mnakufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 11, 'Watasema: Mola wetu Mlezi! Umetufisha mara mbili, na umetuhuisha mara mbili! Basi tunakiri madhambi yetu. Basi je, ipo njia yoyote ya kutoka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 12, 'Hayo ni hivyo kwa sababu mlikuwa akiombwa Mwenyezi Mungu peke yake mnakataa. Na akishirikishwa mnaamini. Basi hukumu ni ya Mwenyezi Mungu Mtukufu Mkuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 13, 'Yeye ndiye anayekuonyesheni Ishara zake, na anakuteremshieni kutoka mbinguni riziki. Na hapana anayekumbuka ila anayerejea kwa toba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 14, 'Basi mwombeni Mwenyezi Mungu mkimsafia Dini Yeye tu, na wangalichukia makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 15, 'Yeye ndiye Mwenye vyeo vya juu, Mwenye ''Arshi. Hutuma Roho kwa amri yake juu ya amtakaye katika waja wake, ili kuonya kwa Siku ya Mkutano.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 16, 'Siku watakayodhihiri wao. Hapana kitakachofichikana chochote chao kwa Mwenyezi Mungu. Ufalme ni wa nani leo? Ni wa Mwenyezi Mungu, Mmoja, Mshindi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 17, 'Leo kila nafsi italipwa kwa yale iliyochuma. Hapana dhuluma leo. Hakika Mwenyezi Mungu ni Mwepesi wa kufanya hesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 18, 'Na waonye siku inayokurubia, wakati nyoyo zitakapofika kooni, nao wamejaa huzuni. Madhalimu hawatakuwa na rafiki, wala mwombezi wa kuitikiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 19, '(Mwenyezi Mungu) anajua hiyana ya macho na yale ambayo vifua vinayaficha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 20, 'Na Mwenyezi Mungu huhukumu kwa haki; lakini hao ambao wao wanawaomba badala yake hawahukumu chochote. Hakika Mwenyezi Mungu ndiye Mwenye kusikia, Mwenye kuona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 21, 'Kwani hawatembei katika ardhi wakaona jinsi ulivyokuwa mwisho wa wale waliokuwa kabla yao? Hao walikuwa wamewazidi hawa kwa nguvu na athari katika nchi. Na Mwenyezi Mungu aliwatia mkononi kwa sababu ya madhambi yao. Na wala hapakuwa wa kuwalinda na Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 22, 'Hayo ni kwa sababu walikuwa Mitume wao walikuwa wanawajia kwa hoja zilizo wazi, lakini wakawakataa, ndipo Mwenyezi Mungu akawakamata. Bila ya shaka Yeye ni Mwenye nguvu, Mkali wa kuadhibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 23, 'Na kwa yakini tulimtuma Musa pamoja na Ishara zetu na uthibitisho ulio wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 24, 'Kumwendea Firauni na Hamana na Qaruni, wakasema: Huyu ni mchawi, mwongo mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 25, 'Basi alipowaletea Haki inayotoka kwetu, walisema: "Waueni watoto wanaume wa wale waliomuamini na wawacheni hai wanawake wao." Na haviwi vitimbi vya makafiri ila katika upotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 26, 'Na Firauni akasema: Niachieni nimuue Musa, naye amwite Mola wake Mlezi! Mimi nachelea asije kubadilishieni dini yenu, au akadhihirisha uharibifu katika nchi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 27, 'Na Musa akasema: Mimi najikinga kwa Mola wangu Mlezi na Mola wenu Mlezi anilinde na kila mwenye jeuri asiyeiamini Siku ya Hesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 28, 'Na akasema mwanamume mmoja Muumini, aliyekuwa mmoja katika watu wa Firauni aliyeficha Imani yake: Mtamuuwa mtu kwa sababu anasema Mola wangu Mlezi ni Mwenyezi Mungu? Na hali naye amekujieni na hoja zilizo wazi? Na akiwa yeye mwongo, basi uongo wake ni juu yake mwenyewe. Na akiwa mkweli, yatakufikieni baadhi ya hayo anayokuahidini. Hakika Mwenyezi Mungu hamwongoi apitilizaye mipaka, mwongo mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 29, 'Enyi watu wangu! Leo mna ufalme, mmeshinda katika nchi; basi ni nani atakayenisaidia kutuokoa na adhabu ya Mwenyezi Mungu kama ikitufikia? Firauni akasema: Sikupeni shauri ila ile niliyoiona, wala siwaongozi ila kwenye njia ya uongofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 30, 'Na akasema yule aliyeamini: Enyi watu wangu! Hakika mimi nawahofia mfano wa siku za makundi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 31, 'Mfano wa hali ya watu wa Nuhu na ''Adi na Thamudi na wale wa baada yao. Na Mwenyezi Mungu hataki kuwadhulumu waja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 32, 'Na enyi watu wangu! Hakika mimi nawahofia Siku ya mayowe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 33, 'Siku mtakapogeuka kurudi nyuma. Hamtakuwa na wa kukulindeni kutokana na Mwenyezi Mungu. Na mwenye kuhukumiwa na Mwenyezi Mungu kupotea, basi huyo hana wa kumwongoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 34, 'Na alikwisha wajieni Yusuf zamani kwa dalili zilizo wazi, lakini nyinyi mliendelea katika shaka kwa yale aliyokuleteeni; mpaka alipokufa, mkasema: Mwenyezi Mungu hataleta kabisa Mtume baada yake. Kama hivyo Mwenyezi Mungu humwacha kupotea anayepindukia mipaka katika maasi anayejitia shaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 35, 'Hao ambao wanajadiliana katika Ishara za Mwenyezi Mungu pasipo ushahidi wowote uliowafikia, ni chukizo kubwa mbele ya Mwenyezi Mungu na mbele ya wale walioamini. Hivi ndivyo Mwenyezi Mungu azibavyo kila moyo wa jeuri anayejivuna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 36, 'Na Firauni akasema: Ewe Hamana! Nijengee mnara ili nipate kuzifikia njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 37, 'Njia za mbinguni ili nikamwone Mungu wa Musa. Na kwa hakika mimi bila ya shaka namjua kuwa ni mwongo tu. Na hivi ndivyo Firauni alivyopambiwa ubaya wa vitendo vyake, na akazuiliwa Njia. Na vitimbi vya Firauni havikuwa ila katika kuangamia tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 38, 'Na yule aliyeamini alisema: Enyi watu wangu! Nifuateni mimi, nitakuongozeni njia ya uongozi mwema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 39, 'Enyi watu wangu! Hakika haya maisha ya dunia ni starehe ipitayo tu, na hakika Akhera ndiyo nyumba ya daima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 40, 'Mwenye kutenda uovu, hatalipwa ila sawa na huo uovu wake. Na anayetenda wema, akiwa mwanamume au mwanamke, naye ni Muumini, basi hao wataingia Peponi, waruzukiwe humo bila ya hesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 41, 'Na enyi watu wangu! Kwa nini mimi nakuiteni kwenye wokovu, nanyi mnaniita kwenye Moto?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 42, 'Mnaniita nimkufuru Mwenyezi Mungu na nimshirikishe na yule ambaye simjui, nami nakuiteni kwa Mwenye nguvu, Mwenye kusamehe mno?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 43, 'Bila ya shaka mnayeniitia kumuabudu hastahiki wito duniani wala Akhera. Na hakika marejeo yetu ni kwa Mwenyezi Mungu. Na wanaopindukia mipaka ndio watu wa Motoni!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 44, 'Basi mtayakumbuka ninayokuambieni. Nami namkabidhi Mwenyezi Mungu mambo yangu. Hakika Mwenyezi Mungu anawaona vyema waja wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 45, 'Basi Mwenyezi Mungu akamlinda kutokana na ubaya wa hila walizozifanya. Na adhabu mbaya itawazingira watu wa Firauni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 46, 'Wanaonyeshwa Moto asubuhi na jioni. Na itapofika Saa ya Kiyama, patasemwa: Waingizeni watu wa Firauni katika adhabu kali kabisa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 47, 'Na watakapohojiana huko Motoni, wanyonge watawaambia wale waliojitukuza: Hakika sisi tulikuwa wafuasi wenu, basi je, hamtuondolei sehemu ya huu Moto?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 48, 'Watasema wale waliojitukuza: Hakika sote sisi tumo humo humo! Kwani Mwenyezi Mungu ameshahukumu baina ya waja!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 49, 'Na wale walio Motoni watawaambia walinzi wa Jahannamu: Mwombeni Mola wenu Mlezi atupunguzie walau siku moja ya adhabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 50, 'Nao watasema: Je, hawakuwa wakikufikieni Mitume wenu kwa hoja zilizo wazi? Watasema: Kwani? Watasema: Basi ombeni! Na maombi ya makafiri hayawi ila ni kupotea bure.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 51, 'Hakika bila ya shaka Sisi tunawanusuru Mitume wetu na wale walioamini katika uhai wa duniani na siku watakaposimama Mashahidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 52, 'Siku ambayo hautawafaa madhalimu udhuru wao, nao watapata laana, na watapata makazi mabaya kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 53, 'Na kwa hakika tulimpa Musa uongofu, na tukawarithisha Wana wa Israili Kitabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 54, 'Ambacho ni Uongofu na Ukumbusho kwa wenye akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 55, 'Basi subiri. Hakika ahadi ya Mwenyezi Mungu ni kweli. Na omba msamaha kwa dhambi zako, na umtakase Mola wako Mlezi kwa kumhimidi jioni na asubuhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 56, 'Hakika hao wanaobishana katika Ishara za Mwenyezi Mungu bila ya uthibitisho wowote uliowajia, hawana vifuani mwao ila kutaka ukubwa tu, na wala huo hawaufikilii. Basi jikinge kwa Mwenyezi Mungu. Hakika Yeye ni Mwenye kusikia, Mwenye kuona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 57, 'Bila ya shaka kuumba mbingu na ardhi ni kukubwa zaidi kuliko kuwaumba watu. Lakini watu wengi hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 58, 'Na kipofu na mwenye kuona hawalingani; na wale walioamini na wakatenda mema hawalingani na muovu. Ni machache mnayoyakumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 59, 'Hakika Saa (ya Kiyama) itafika, nayo haina shaka. Lakini watu wengi hawaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 60, 'Na Mola wenu Mlezi anasema: Niombeni nitakuitikieni. Kwa hakika wale ambao wanajivuna wakaacha kuniabudu Mimi wataingia Jahanamu wadhalilike.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 61, 'Mwenyezi Mungu ndiye aliyewafanyia usiku ili mpate kutulia humo, na mchana wa kuonea. Hakika Mwenyezi Mungu bila ya shaka ni Mwenye fadhila juu ya watu, lakini watu wengi hawashukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 62, 'Huyo ndiye Mwenyezi Mungu Mola wenu Mlezi, Muumba wa kila kitu. Hapana mungu ila Yeye; basi mnageuzwa wapi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 63, 'Namna hivi ndivyo walivyogeuzwa wale waliokuwa wakizikataa Ishara za Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 64, 'Ni Mwenyezi Mungu aliyekufanyieni ardhi kuwa ni pahala pa kukaa, na mbingu kuwa dari. Na akawatia sura, na akazifanya nzuri sura zenu, na akawaruzuku vitu vizuri. Huyo ndiye Mwenyezi Mungu Mola wenu Mlezi. Basi ametukuka Mwenyezi Mungu Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 65, 'Yeye ndiye aliye Hai - hapana mungu isipokuwa Yeye. Basi muabuduni Yeye mkimsafishia Dini Yeye. Sifa njema zote ni za Mwenyezi Mungu, Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 66, 'Sema: Mimi nimekatazwa kuwaabudu hao mnaowaomba badala ya Mwenyezi Mungu, ziliponijia hoja zilizo dhahiri kutokana na Mola wangu Mlezi. Na nimeamrishwa nisilimu kwa Mola wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 67, 'Yeye ndiye aliyewaumba kwa udongo, kisha kwa tone la manii, kisha kwa pande la damu, kisha akawatoa katika hali ya mtoto mchanga, kisha mpate kufikilia utu uzima, kisha mpate kuwa wazee. Na kati yenu wapo wanaokufa kabla, na ili mfikie muda uliokwisha wekwa, na ili mpate kufahamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 68, 'Yeye ndiye anayehuisha na anayefisha. Akihukumu jambo liwe, basi huliambia: "Kuwa!" Likawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 69, 'Je, huwaoni wale wanaobishana katika Ishara za Mwenyezi Mungu? Wanageuziwa wapi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 70, 'Ambao wamekanusha Kitabu na yale tuliyowatuma Mitume wetu. Basi watakuja jua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 71, 'Zitakapokuwa pingu shingoni mwao na minyororo, huku wanabururwa', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 72, 'Katika maji ya moto, kisha wanaunguzwa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 73, 'Tena wataambiwa: Wako wapi wale mliokuwa mkiwashirikisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 74, 'Badala ya Mwenyezi Mungu? Watasema: Wametupotea, bali tangu zamani hatukuwa tukiomba kitu! Hivyo ndivyo Mwenyezi Mungu anawaachia makafiri wapotelee mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 75, 'Haya ni kwa sababu mlikuwa mkijitapa katika ardhi pasipo haki, na kwa sababu mlikuwa mkijishaua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 76, 'Ingieni kwenye milango ya Jahanamu, mdumu humo milele. Basi ni maovu yaliyoje makazi ya wanaotakabari!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 77, 'Basi subiri, hakika ahadi ya Mwenyezi Mungu ni ya kweli. Na ama tukikuonyesha baadhi ya yale tuliyowaahidi au tukikufisha, lakini wao watarudishwa kwetu tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 78, 'Na bila ya shaka tuliwatuma Mitume kabla yako. Wengine katika hao tumekusimulia habari zao, na wengine hatukukusimulia. Na haiwi Mtume alete Ishara yoyote ila kwa idhini ya Mwenyezi Mungu. Basi ikija amri ya Mwenyezi Mungu, huhukumiwa kwa Haki, na hapo wapotovu watahasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 79, 'Mwenyezi Mungu aliyewajaalia nyama hoa, mifugo, ili muwapande baadhi yao, na muwale baadhi yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 80, 'Na katika hao mnayo manufaa kadhaa wa kadhaa, na mnapata kwao haja zilizomo vifuani mwenu; na mnachukuliwa juu yao, na juu ya merikebu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 81, 'Naye anawaonyesha Ishara zake. Basi Ishara gani za Mwenyezi Mungu mnazozikataa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 82, 'Kwani hawatembei katika ardhi wakaona namna ulivyokuwa mwisho wa wale waliokuwa kabla yao? Wao walikuwa wengi kuliko hawa, na wamewashinda kwa nguvu na athari katika nchi. Wala hayakuwafaa hayo waliyokuwa wakiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 83, 'Walipowajia Mitume wao kwa hoja zilizo wazi, walijitapa kwa elimu waliyokuwa nayo. Basi yakawazingira yale waliyokuwa wakiyafanyia masihara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 84, 'Walipoiona adhabu yetu, walisema: Tumemuamini Mwenyezi Mungu kuwa ni wa pekee, na tunaikataa miungu tuliyokuwa tukiishirikisha naye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 85, 'Lakini imani yao haikuwa yenye kuwafaa kitu wakati ambao wamekwisha iona adhabu yetu. Huu ndio mwendo wa Mwenyezi Mungu uliokuwa kwa waja wake. Na hapo waliokufuru walihasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 1, 'Ha Mim.[1]', '[1] Herufi hizi "Ha, Mim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 2, 'Uteremsho huu umetoka kwa Mwingi wa rehema, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 3, 'Hiki ni Kitabu kilichopambanuliwa Aya zake, cha kusomwa kwa Kiarabu kwa watu wanaojua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 4, 'Kitoacho habari njema, na chenye kuonya. Lakini wengi katika wao wamepuuza; kwa hivyo hawasikii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 5, 'Na wakasema: Nyoyo zetu zimo katika vifuniko kwa hayo unayotuitia, na masikio yetu yana uziwi, na baina yetu na wewe lipo pazia. Basi wewe tenda, nasi hakika tunatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 6, 'Sema: Hakika mimi ni mtu kama nyinyi; inafunuliwa kwangu ya kwamba Mungu wenu ni Mungu Mmoja tu. Basi nyookeni sawa kumwendea Yeye, na mumtake msamaha, na ole wao wanaomshirikisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 7, 'Ambao hawatoi Zaka na wanaikataa Akhera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 8, 'Hakika wale walioamini na wakatenda mema, watakuwa na ujira usio na ukomo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 9, 'Sema: Hivyo nyinyi mnamkataa yule aliyeumba ardhi katika siku mbili, na mnamfanyia washirika? Huyu ndiye Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 10, 'Na akaweka humo milima juu yake, na akabarikia humo na akakadiria humo chakula chake katika siku nne. Haya ni sawa kabisa kwa wanaouliza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 11, 'Kisha akazielekea mbingu, na zilikuwa moshi, akaziambia hizo na ardhi: Njooni, kwa hiari au kwa nguvu! Vyote viwili vikasema: Tumekuja nasi ni watiifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 12, 'Basi akazifanya mbingu saba kwa siku mbili, na akazipangia kila mbingu mambo yake. Na tukaipamba mbingu ya chini kwa mataa na kwa ulinzi. Hiki ndicho kipimo cha Mwenye Nguvu, ajuaye zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 13, 'Basi wakipuuza wewe sema: Nakuhadharisheni adhabu mfano wa adhabu ya ''Adi na Thamudi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 14, 'Walipowajia Mitume mbele yao na nyuma yao wakawaambia: Msimuabudu ila Mwenyezi Mungu! Wakasema: Angelitaka Mola wetu Mlezi, bila ya shaka angeliwateremsha Malaika. Basi sisi hakika tunayakataa hayo mliyotumwa nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 15, 'Ama kina ''Adi, hao walijivuna katika nchi bila ya haki, na wakasema: Ni nani mwenye nguvu kushinda sisi? Kwani wao hawakuona kwamba Mwenyezi Mungu aliyewaumba ni Mwenye nguvu kushinda wao? Na wao wakawa wanazikataa Ishara zetu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 16, 'Basi tukawatumia upepo wa kimbunga katika siku za misiba, ili tuwaonjeshe adhabu ya kuwahizi katika uhai wa duniani, na bila ya shaka adhabu ya Akhera ina hizaya zaidi, na wala wao hawatanusuriwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 17, 'Na ama Thamudi, hao tuliwaongoza, lakini walipendelea upofu kuliko uongofu. Basi ukawachukua moto wa adhabu ya kuwafedhehesha kwa sababu ya yale waliyokuwa wakiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 18, 'Na tukawaokoa wale walioamini na wakawa wanamcha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 19, 'Na siku watakapokusanywa maadui wa Mwenyezi Mungu kwenye Moto, nao wakigawanywa kwa makundi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 20, 'Hata watakapoufikia Moto, yatawashuhudia masikio yao, na macho yao na ngozi zao kwa yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 21, 'Na wao wataziambia ngozi zao: Kwa nini mmetushuhudilia? Nazo zitasema: Ametutamkisha Mwenyezi Mungu ambaye alitamkisha kila kitu! Na Yeye ndiye aliyewaumba mara ya kwanza, na kwake Yeye tu mtarejeshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 22, 'Na hamkuwa wenye kujificha hata masikio yenu, na macho yenu, na ngozi zenu, zisikushuhudilieni. Lakini mlidhani kwamba Mwenyezi Mungu hayajui mengi katika yale mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 23, 'Basi hiyo dhana yenu mliyokuwa mkimdhania Mola wenu Mlezi, imekuangamizeni; na mmekuwa miongoni mwa waliohasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 24, 'Basi wakisubiri, Moto ndio maskani yao. Na wakiomba radhi, hawakubaliwi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 25, 'Na tukawawekea marafiki, na wakawapambia yaliyo mbele yao na nyuma yao. Basi ikawathibitikia kauli wawe pamoja na mataifa yaliyopita kabla yao, miongoni mwa majini na watu. Hakika hao wamekuwa ni wenye kuhasirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 26, 'Na wale waliokufuru walisema: Msiisikilize Qur-ani hii, na timueni zogo ndani yake, huenda mkashinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 27, 'Basi hapana shaka tutawaonjesha hao waliokufuru adhabu kali, na hapana shaka tutawalipa malipo mabaya zaidi kwa yale waliyokuwa wakiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 28, 'Hayo ndiyo malipo ya Maadui wa Mwenyezi Mungu - Moto! Humo watakuwa na maskani ya kudumu, ndiyo malipo yao kwa sababu walikuwa wakizikataa Ishara zetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 29, 'Na wale waliokufuru watasema: Mola wetu Mlezi! Tuonyeshe wale waliotupoteza miongoni mwa majini na watu ili tuwaweke chini ya miguu yetu, wapate kuwa miongoni wa walio chini kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 30, 'Hakika wale waliosema: "Mola wetu Mlezi ni Mwenyezi Mungu!" Kisha wakanyooka sawa, hao huwateremkia Malaika wakawaambia: Msiogope, wala msihuzunike; nanyi furahini kwa Bustani mliyokuwa mkiahidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 31, 'Sisi ni vipenzi vyenu katika maisha ya dunia na katika Akhera, na humo mtapata kinachotamaniwa na nafsi zenu, na humo mtapata mtakavyovitaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 32, 'Ni takrima itokayo kwa Mwenye kusamehe, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 33, 'Na ni nani mbora zaidi wa kusema kuliko aitaye kwa Mwenyezi Mungu na akatenda mema, na akasema: Hakika mimi ni katika Waislamu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 34, 'Mema na maovu hayalingani. Pinga uovu kwa lililo jema zaidi. Hapo yule ambaye baina yako naye pana uadui atakuwa kama rafiki jamaa wa kukuonea uchungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 35, 'Lakini hawapewi wema huu ila wanaosubiri, wala hawapewi ila wenye bahati kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 36, 'Na Shetani akikuchochea kwa uchochezi, wewe jikinge kwa Mwenyezi Mungu. Hakika Yeye ni Mwenye kusikia, ajuaye zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 37, 'Na katika Ishara zake ni usiku na mchana, na jua na mwezi. Basi msilisujudie jua wala mwezi, bali msujudieni Mwenyezi Mungu aliyeviumba, ikiwa nyinyi mnamuabudu Yeye tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 38, 'Na ikiwa watajivuna, basi hao walioko kwa Mola wako Mlezi wanamtakasa Yeye usiku na mchana, na wao hawachoki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 39, 'Na katika Ishara zake ni kwamba unaiona ardhi nyonge, lakini tunapoiteremshia maji, mara unaiona inataharaki na kuumuka. Bila ya shaka yule aliyeihuisha ardhi ndiye atakayehuisha wafu. Hakika Yeye ni Muweza mno wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 40, 'Hakika wale wanaopindukia mipaka katika Ishara zetu, hawafichikani kwetu. Je, atakayetupwa Motoni ni bora au atakayekuja kwa amani Siku ya Kiyama? Tendeni mpendavyo, kwa hakika Yeye anayaona vyema mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 41, 'Kwa hakika wale walioyakufuru mawaidha haya yanapowajia (wataangamia), na haya bila ya shaka ni Kitabu chenye nguvu na utukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 42, 'Haukifikii upotovu mbele yake wala nyuma yake. Kimeteremshwa na Mwenye hekima, Msifiwa mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 43, 'Huambiwi ila yale yale waliyoambiwa Mitume wa kabla yako. Hakika Mola wako Mlezi bila ya shaka ni Mwenye maghfira, na ni Mwenye adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 44, 'Na lau tungeliifanya Qur-ani kwa lugha ya kigeni, wangelisema: Kwa nini Aya zake hazikupambanuliwa? Yawaje lugha ya kigeni na Mtume Mwaarabu? Sema: Hii Qur-ani ni uongofu na ponya kwa wenye kuamini. Na wale wasioamini umo uziwi katika masikio yao, nayo kwao imezibwa hawaioni. Hao wanaitwa nao wako pahala mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 45, 'Na hakika tulimpa Musa Kitabu, lakini pakatokea tofauti juu yake. Na lau kuwa halikwisha tangulia neno la Mola wako Mlezi, wangelihukumiwa. Na hakika wao wamo katika shaka yenye kuwatia wasiwasi juu yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 46, 'Anayetenda mema, basi anajitendea mwenyewe nafsi yake. Na mwenye kutenda uovu, basi ni juu ya nafsi yake vile vile; wala Mola wako Mlezi si mwenye kuwadhulumu waja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 47, 'Ujuzi wa kuijua Saa ya Kiyama unarudishwa kwake tu Mwenyezi Mungu. Na matunda hayatoki katika mafumba yake, wala cha kike hakichukui mimba, wala hakizai, ila kwa kujua kwake. Na siku atakayowaita, akawaambia: ''Wako wapi washirika wangu?'' Hapo watasema: ''Tunakiri kwako ya kwamba hapana miongoni mwetu anayeshuhudia hayo.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 48, 'Na wakawapotea wale waliokuwa wakiwaomba hapo kwanza, na wakawa na yakini kuwa hawana pa kukimbilia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 49, 'Mwanadamu hachoki kuomba dua za heri, na inapompata shari, mara huvunjika moyo mno akakata tamaa sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 50, 'Na pindi tukimwonjesha rehema itokayo kwetu baada ya dhara kumgusa, bila ya shaka husema: ''Haya nayastahiki mimi, wala sidhani kuwa Kiyama kitakuja. Na hata nikirudishwa kwa Mola wangu Mlezi, bila ya shaka nina mema yangu kwake!'' Basi kwa yakini tutawaelezea wale waliokufuru hayo waliyoyatenda, na kwa yakini tutawaonjesha adhabu ngumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 51, 'Na tukimneemesha mwanadamu, hugeuka na kujitenga upande, na inapomgusa shari, huwa na madua marefu marefu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 52, 'Sema: ''Mnaonaje! Ikiwa haya yanatoka kwa Mwenyezi Mungu, nanyi ikawa ndio mmeyakataa, ni nani aliyepotea zaidi kuliko aliye katika upinzani wa mbali?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 53, 'Tutawaonyesha Ishara zetu katika upeo wa mbali na katika nafsi zao wenyewe mpaka iwabainikie kwamba haya ni kweli. Je, haikutoshi kwamba Mola wako Mlezi kuwa Yeye ni Shahidi bora wa kila kitu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 54, 'Tanabahi, hakika wao wamo katika shaka ya kukutana na Mola wao Mlezi! Tanabahi, hakika Yeye amekizingira kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 1, 'Ha Mim.[1]', '[1] Herufi hizi "Ha, Mim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 2, 'Ayn Sin Qaf.[1]', '[1] Herufi hizi "Ayn, Sin, Qaf" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi ya Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu. (At-Tafsiir Al-Muyassar)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 3, 'Hivi ndivyo Mwenyezi Mungu Mwenye nguvu na Mwenye hekima anavyokuletea Wahyi wewe na walio kabla yako.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 4, 'Ni vyake vilivyomo mbinguni na vilivyo katika ardhi. Na Yeye ndiye aliye juu zaidi, Mkuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 5, 'Zinakaribia mbingu kupasuka juu huko, na Malaika wakimtakasa Mola wao Mlezi na kumhimidi, na wakiwaombea maghfira waliomo kwenye ardhi. Ama hakika Mwenyezi Mungu ni Mwenye kusamehe mno, Mwenye kurehemu sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 6, 'Na wale waliowafanya walinzi wengine badala yake Yeye, Mwenyezi Mungu ni Mwangalizi bora juu yao. Wala wewe si wakili juu yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 7, 'Na namna hivi tumekufunulia Qur-ani kwa Kiarabu ili uwaonye watu wa Mama wa Miji na wale walio pembezoni mwake. Na uhadharishe na Siku ya Mkutano, haina shaka hiyo. Kundi moja litakuwa Bustanini na kundi jengine katika Moto wenye mwako mkali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 8, 'Na Mwenyezi Mungu angelipenda, angewafanya wote umma mmoja, lakini anamwingiza katika rehema yake amtakaye. Na wenye kudhulumu hawana mlinzi wala msaidizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 9, 'Au wamechukua walinzi wengine badala yake! Lakini Mwenyezi Mungu ndiye Mlinzi hasa. Na Yeye ndiye anayehuisha wafu. Na Yeye ndiye Muweza zaidi wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 10, 'Na mkihitalifiana katika jambo lolote, basi hukumu yake iko kwa Mwenyezi Mungu. Huyo Mwenyezi Mungu ndiye Mola wangu Mlezi ninayemtegemea, na kwake Yeye narejea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 11, 'Yeye ndiye Muumba mbingu na ardhi. Amekujaalieni mke na mume katika nafsi zenu, na katika wanyama wa kufugwa waliwao dume na jike, anakuzidishieni namna hii. Hapana kitu kama mfano wake. Naye ni Mwenye kusikia mno, Mwenye kuona sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 12, 'Yeye ndiye Mwenye funguo za mbingu na ardhi. Humkunjulia riziki amtakaye na humpimia amtakaye. Hakika Yeye ni Mjuzi zaidi wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 13, 'Amekuamrisheni Dini ile ile aliyomuusia Nuhu na tuliyokufunulia wewe, na tuliyowausia Ibrahim na Musa na Isa, kwamba shikeni Dini wala msifarikiane kwayo. Ni magumu kwa washirikina hayo unayowaitia. Mwenyezi Mungu humteua kwake amtakaye, na humwongoa kwake aelekeaye (kwake).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 14, 'Na hawakufarikiana ila baada ya kuwajia elimu kwa sababu ya husuda iliyokuwa baina yao. Na lau kuwa haikwisha tangulia kauli kutoka kwa Mola wako Mlezi ya kuahirisha mpaka muda maalumu, basi bila ya shaka pangelihukumiwa baina yao. Na hakika wale waliorithishwa Kitabu baada yao wanakitilia shaka inayowahangaisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 15, 'Basi kwa haya waite! Nawe simama sawa sawa kama ulivyoamrishwa, wala usiyafuate matamanio yao. Na sema: ''Ninaamini aliyoteremsha Mwenyezi Mungu katika Vitabu. Na nimeamrishwa nifanye uadilifu baina yenu. Mwenyezi Mungu ni Mola wetu Mlezi, na Mola wenu Mlezi. Sisi tuna jukumu kwa vitendo vyetu, na nyinyi mna jukumu kwa vitendo vyenu. Hapana kuhojiana baina yetu na nyinyi. Na Mwenyezi Mungu atatukusanya pamoja, na marejeo ni kwake.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 16, 'Na wale wanaohojiana juu ya Mwenyezi Mungu baada ya kukubaliwa, hoja za hawa ni batili mbele ya Mola wao Mlezi, na juu yao ipo ghadhabu, na itakuwa kwao adhabu kali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 17, 'Mwenyezi Mungu ndiye aliyeteremsha Kitabu kwa Haki na Mizani. Na ni nini kitakachokujulisha ya kwamba pengine Saa ya Kiyama ipo karibu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 18, 'Wale wasioiamini huihimiza hiyo Saa ifike upesi, lakini wale wanaoamini wanaiogopa na wanajua kwamba hakika hiyo ni kweli. Ama kwa hakika hao wanaobishana katika habari za hiyo Saa wamo katika upotovu wa mbali kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 19, 'Mwenyezi Mungu ni Mpole kwa waja wake. Humruzuku amtakaye. Naye ndiye Mwenye nguvu, Mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 20, 'Mwenye kutaka mavuno ya Akhera, tutamzidishia katika mavuno yake. Na mwenye kutaka mavuno ya duniani, tutampa katika hayo, lakini katika Akhera hana fungu lolote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 21, 'Au hao wana miungu ya kishirikina waliowatungia dini asiyoitolea idhini Mwenyezi Mungu? Na lau lisingekuweko neno la kupambanua, basi wangelikatiwa hukumu baina yao. Na hakika wenye kudhulumu watapata adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 22, 'Utawaona hao madhalimu wanavyokuwa na hofu kwa sababu ya waliyoyachuma, nayo yatawafika tu. Na wale walioamini na wakatenda mema watakuwemo katika mabustani ya Peponi. Humo watapata wayatakayo kwa Mola wao Mlezi. Hiyo ndiyo fadhila kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 23, 'Hayo ndiyo aliyowabashiria Mwenyezi Mungu waja wake walioamini na wakatenda mema. Sema: ''Sikuombeni malipo yoyote juu yake ila mapenzi katika kujikurubisha. Na anayefanya wema, tutamzidishia wema. Hakika Mwenyezi Mungu ni Msamehevu mno, Mwenye shukrani sana.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 24, 'Ati wanasema Amemzulia Mwenyezi Mungu uongo? Mwenyezi Mungu akipenda ataziba moyo wako. Na Mwenyezi Mungu anaufuta upotovu na anaithibitisha Haki kwa maneno yake. Hakika Yeye anayajua yaliyomo vifuani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 25, 'Naye ndiye anayepokea toba kwa waja wake, na anasamehe mabaya, na anayajua mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 26, 'Na anawaitikia wanaoamini na wakatenda mema, na anawazidishia fadhila zake. Na makafiri watakuwa na adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 27, 'Na lau kuwa Mwenyezi Mungu angeliwakunjulia riziki waja wake, basi bila ya shaka wangelipanda kiburi katika dunia. Lakini anaiteremsha kwa kipimo akitakacho. Hakika Yeye anawajua vyema waja wake na anawaona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 28, 'Naye ndiye anayeiteremsha mvua baada ya wao kwisha kata tamaa, na hueneza rehema yake. Naye ndiye Mlinzi, Mwenye kusifiwa sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 29, 'Na katika Ishara zake ni kuumba mbingu na ardhi, na wanyama aliowaeneza ndani yake. Naye ni Mwenye uweza mkubwa wa kuwakusanya apendapo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 30, 'Na misiba inayowasibu ni kwa sababu ya vitendo vya mikono yenu. Naye anasamehe mengi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 31, 'Na nyinyi hamwezi kushinda katika ardhi. Na wala nyinyi hamna mlinzi wala msaidizi badala ya Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 32, 'Na katika Ishara zake ni vyombo vinavyokwenda na kurejea baharini kama vilima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 33, 'Akitaka, huutuliza upepo navyo hivyo vyombo husimama tutwe juu ya bahari. Hakika katika hayo zipo Ishara kwa kila mwenye subira kubwa na akashukuru sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 34, 'Au huviangamiza hivyo vyombo kwa sababu ya waliyoyatenda hao watu. Naye husamehe mengi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 35, 'Na ili wajue wanaojadiliana katika Ishara zetu kwamba hawana pahali popote pa kukimbilia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 36, 'Basi vyote mlivyopewa ni starehe ya maisha ya dunia tu, lakini kilichoko kwa Mwenyezi Mungu ni bora na cha kudumu zaidi kwa ajili ya walioamini na wakawa wanamtegemea Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 37, 'Na wanaoyaepuka madhambi makubwa na mambo machafu, na wanapokasirika wao husamehe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 38, 'Na wanaomwitikia Mola wao Mlezi, na wakashika Sala, na mambo yao yakawa ni kwa kushauriana baina yao, na kutokana na tulichowaruzuku wakawa wanatoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 39, 'Na ambao wanapofanyiwa jeuri hujitetea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 40, 'Na malipo ya uovu ni uovu mfano wa huo. Lakini mwenye kusamehe na akasuluhisha, basi huyo malipo yake yapo kwa Mwenyezi Mungu. Hakika Yeye hawapendi wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 41, 'Na wanaojitetea baada ya kudhulumiwa, hao hapana njia ya kuwalaumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 42, 'Bali lawama ipo kwa wale wanaowadhulumu watu, na wanafanya jeuri katika ardhi bila ya haki. Hao watapata adhabu iliyo chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 43, 'Na anayekuwa na subira, na akasamehe, hakika hayo ni katika mambo ya kuazimiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 44, 'Na ambaye Mwenyezi Mungu amemwacha kupotea, hana mlinzi baada yake. Na utawaona wenye kudhulumu watakapoiona adhabu wanasema: ''Je! Ipo njia ya kurudi?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 45, 'Na utawaona wanapelekwa kwenye Moto, nao wamenyenyekea kwa unyonge, wanatazama kwa mtazamo wa kificho. Na walioamini watasema: ''Hakika wapatao hasara ni hao waliohasiri nafsi zao na ahali zao Siku ya Kiyama.'' Ama hakika wenye kudhulumu watakuwa katika adhabu ya daima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 46, 'Wala hawatakuwa na walinzi wa kuwanusuru mbele ya Mwenyezi Mungu. Na ambaye Mwenyezi Mungu amemwacha kupotea, hana njia yoyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 47, 'Muitikieni Mola wenu Mlezi kabla haijafika siku isiyoepukika, itokayo kwa Mwenyezi Mungu. Siku hiyo hamtakuwa na pa kukimbilia wala hamtakuwa na cha kukingia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 48, 'Na wakipuuza, basi Sisi hatukukupeleka ili uwe mwangalizi wao. Si juu yako ila kufikisha Ujumbe tu. Na hakika Sisi tukimwonjesha mtu rehema kutoka kwetu, huifurahia. Na akisibiwa na ovu kwa sababu ya iliyoyatanguliza mikono yao, basi hakika mtu huyu anakufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 49, 'Ufalme wa mbingu na ardhi ni wa Mwenyezi Mungu; anaumba apendavyo, anamtunukia amtakaye watoto wa kike, na anamtunukia amtakaye watoto wa kiume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 50, 'Au huwachanganya wanaume na wanawake, na akamfanya amtakaye tasa. Hakika Yeye ni Mjuzi, Mwenye uweza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 51, 'Na haikuwa kwa mwanadamu kwamba Mwenyezi Mungu amsemeze ila kwa Wahyi (Ufunuo), au kwa nyuma ya kizuizi, au kumtuma Mjumbe. Naye humfunulia ayatakayo kwa idhini yake. Hakika Yeye ni Mtukufu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 52, 'Na namna hivi tumekufunulia Qur-ani kwa amri yetu. Ulikuwa hujui Kitabu ni nini, wala Imani. Lakini tumekifanya kuwa ni Nuru ambayo kwayo tunamwongoa tumtakaye katika waja wetu. Na hakika wewe unaongoza kwenye Njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 53, 'Njia ya Mwenyezi Mungu ambaye ni vyake Yeye tu vilivyomo mbinguni na katika ardhi. Jueni kuwa mambo yote yanarudi kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 1, 'Ha Mim.[1]', '[1] Herufi hizi "Ha, Mim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 2, 'Ninaapa kwa Kitabu kinachobainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 3, 'Hakika Sisi tumeifanya Qur-ani kwa Kiarabu ili mfahamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 4, 'Na hakika hiyo imo katika Asili ya Maandiko yaliyoko kwetu, ni tukufu na yenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 5, 'Je, tuache kuwakumbusha kabisa kwa kuwa nyinyi ni watu mliopita mipaka kwa ukafiri?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 6, 'Na Manabii wangapi tuliwatuma kwa watu wa zamani!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 7, 'Na hawajii Nabii yeyote ila walikuwa wakimkejeli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 8, 'Na tuliwaangamiza waliokuwa na nguvu kushinda wao. Na mfano wa watu wa zamani umekwisha pita.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 9, 'Na ukiwauliza: ''Nani aliyeziumba mbingu na ardhi?'' Bila ya shaka watasema: ''Kaziumba Mwenye nguvu, ajuaye zaidi.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 10, 'Ambaye amewafanyieni ardhi kama tandiko, na akawafanyieni ndani yake njia mpate kuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 11, 'Na ambaye ndiye aliyeteremsha kutoka mbinguni maji kwa kiasi, na kwa hayo tukaifufua nchi iliyokufa. Na namna hivi ndivyo mtakavyotolewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 12, 'Na ambaye ndiye aliyeumba katika kila kitu jike na dume, na akawafanyieni merikebu na wanyama mnaowapanda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 13, 'Ili mkae vizuri migongoni mwao, kisha mkumbuke neema za Mola wenu Mlezi mnapokaa sawa sawa juu yao, na mseme: ''Ametakasika aliyemfanya huyu atutumikie, na tusingeliweza kufanya haya wenyewe.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 14, 'Na hakika sisi tutarudi kwa Mola wetu Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 15, 'Na wanamfanyia katika waja wake fungu. Kwa hakika mwanadamu ni mtovu wa fadhila aliye dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 16, 'Au amejichukulia watoto wanawake katika vile alivyoviumba, na akakuteulieni nyinyi watoto wanaume?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 17, 'Na anapobashiriwa mmoja wao kwa yale aliyompigia mfano Mwenyezi Mungu, uso wake husawijika na hujaa hasira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 18, 'Ati aliyelelewa katika mapambo na katika mabishano hawezi kusema kwa bayana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 19, 'Na wakawafanya Malaika, ambao ni waja wa Mwingi wa Rehema, ni wanawake! Kwani wameshuhudia kuumbwa kwao? Ushahidi wao utaandikwa na wao watahojiwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 20, 'Nao husema: ''Angelipenda Mwingi wa Rehema tusingeliwaabudu sisi.'' Hawana ujuzi wowote wa hayo! Hawana ila kusema uongo tu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 21, 'Kwani tuliwapa Kitabu kabla ya hiki, na ikawa wao wanakishikilia hicho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 22, 'Bali wanasema: ''Hakika sisi tuliwakuta baba zetu wanashika dini mahsusi, basi na sisi tunafuata nyayo zao.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 23, 'Na kadhaalika hatukumtuma mwonyaji kwenye mji wowote ila watu wake waliodeka kwa starehe walisema: ''Hakika sisi tuliwakuta baba zetu wanashika dini mahsusi, na sisi tunafuata nyayo zao.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 24, 'Akasema (Mwonyaji): ''Hata nikiwaletea yenye uwongofu bora kuliko mliowakuta nao baba zenu?'' Wakasema: ''Sisi tunayakataa tu hayo mliyotumwa nayo.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 25, 'Kwa hivyo, tukawalipizia. Basi angalia ulikuwaje mwisho wa waliokadhibisha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 26, 'Na pale Ibrahim alipomwambia baba yake na kaumu yake: ''Hakika mimi ninajitenga mbali na hayo mnayoyaabudu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 27, 'Isipokuwa yule aliyeniumba, kwani Yeye ataniongoa.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 28, 'Na akalifanya hili liwe neno lenye kubaki katika vizazi vyake ili warejee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 29, 'Bali tuliwastarehesha hawa na baba zao mpaka ikawafikia Haki na Mtume aliyebainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 30, 'Na ilipowafikia Haki wakasema: ''Huu ni uchawi, na sisi hakika tunaukataa.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 31, 'Na walisema: ''Kwa nini Qur-ani hii haikuteremshwa kwa mtu mkubwa katika miji miwili hii?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 32, 'Kwani wao ndio wanaogawa rehema za Mola wako Mlezi? Sisi tumewagawanyia baina yao maisha yao katika uhai wa duniani, na tukawanyanyua baadhi yao juu ya wengine kwa daraja nyingi; kwa hivyo baadhi yao wanawafanya wengineo wawatumikie. Na rehema za Mwenyezi Mungu ni bora kuliko hayo wanayoyakusanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 33, 'Na lau isingekuwa watu watakuwa kundi moja, tungeliwajaalia wanaomkufuru Rahmani nyumba zao kuwa na dari ya fedha, na ngazi zao pia wanazopandia', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 34, 'Na milango ya nyumba zao na vitanda wanavyoegemea juu yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 35, 'Na mapambo. Lakini hayo si chochote ila ni starehe ya maisha ya dunia tu, na Akhera iliyoko kwa Mola wako Mlezi ni ya wenye kumcha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 36, 'Anayeyafanyia upofu maneno ya Rahmani tunamwekea Shetani kuwa ndiye rafiki yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 37, 'Na hakika wao wanawazuilia Njia na wenyewe wanadhani kuwa wameongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 38, 'Hata atakapotujia atasema: ''Laiti ungelikuweko baina yangu na wewe kama umbali baina ya mashariki na magharibi. Rafiki mwovu mno wewe!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 39, 'Na kwa kuwa mlidhulumu, haitakufaeni kitu leo kwamba nyinyi mnashirikiana katika adhabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 40, 'Je, unaweza kuwasikilizisha viziwi, au unaweza kuwaongoa vipofu na waliomo katika upotovu ulio wazi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 41, 'Na hata tukikuondoa, Sisi tutalipiza kisasi chetu kwao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 42, 'Au tutakuonyesha tuliyowaahidi. Nasi bila ya shaka tuna uweza juu yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 43, 'Basi wewe yashike yaliyofunuliwa kwako. Hakika wewe uko kwenye Njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 44, 'Na hakika haya ni ukumbusho kwako na kwa kaumu yako. Na mtakuja ulizwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 45, 'Na waulize Mitume wetu tuliowatuma kabla yako: ''Je, tulifanya miungu mingine iabudiwe badala ya Rahmani?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 46, 'Na bila ya shaka tulimtuma Musa kwa Ishara zetu aende kwa Firauni na waheshimiwa wake, na akasema: ''Hakika mimi ni Mtume wa Mola Mlezi wa walimwengu wote!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 47, 'Lakini alipowajia na Ishara zetu, wakaingia kuzicheka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 48, 'Na hatukuwaonyesha Ishara yoyote ila hiyo ilikuwa kubwa zaidi kuliko nyingineye. Na tukawakamata kwa adhabu ili warejee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 49, 'Na wakasema: ''Ewe mchawi! Tuombee kwa Mola wako Mlezi kwa ile ahadi aliyokuahidi; hakika sisi tutakuwa wenye kuongoka.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 50, 'Basi tulipowaondolea adhabu hiyo, mara wakaingia kuvunja ahadi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 51, 'Na Firauni alitangaza kwa watu wake akisema: ''Enyi watu wangu! Kwani mimi si ninao huu ufalme wa Misri, na hii mito inapita chini yangu. Je, hamwoni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 52, 'Au mimi si bora kuliko huyu aliye mnyonge, wala hawezi kusema waziwazi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 53, 'Basi mbona hakuvikwa vikuku vya dhahabu au hawakuja Malaika pamoja naye wakamwandama?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 54, 'Basi aliwachezea watu wake na wakamtii. Kwa hakika hao walikuwa watu wapotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 55, 'Walipotukasirisha, tuliwapatiliza tukawazamisha wote!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 56, 'Kisha tukawafanya kuwa watangulizi na mfano kwa wa baadaye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 57, 'Na alipopigiwa mfano Mwana wa Mariamu, watu wako waliupigia ukelele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 58, 'Wakasema: ''Miungu yetu kwani si bora kuliko huyu?'' Hawakukupigia mfano huo ila kwa ubishi tu. Bali hao ni watu wagomvi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 59, 'Hakuwa yeye (Isa) ila ni Mtumwa tuliyemneemesha na tukamfanya ni mfano kwa Wana wa Israili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 60, 'Na tungelipenda, tungeliwafanyia miongoni mwenu Malaika katika ardhi wakifuatana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 61, 'Na kwa hakika yeye ni alama ya Saa ya Kiyama. Basi usiitilie shaka, na nifuateni. Hii ndiyo Njia Iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 62, 'Wala asiwazuilie Shetani. Hakika yeye ni adui yenu wa dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 63, 'Na alipokuja Isa na ushahidi ulio wazi, alisema: ''Nimewajia na hekima na ili niwaeleze baadhi ya yale mliyokhitalifiana. Basi mcheni Mwenyezi Mungu, na mnitii mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 64, 'Kwa hakika Mwenyezi Mungu ni Mola wangu Mlezi, na ni Mola wenu Mlezi. Basi muabuduni Yeye tu. Hii ndiyo Njia Iliyonyooka.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 65, 'Lakini makundi kwa makundi yao yalikhitalifiana wao kwa wao. Ole wao waliodhulumu kwa adhabu ya siku chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 66, 'Je, nini wanangojea ila Saa iwajie kwa ghafla na wala wao hawatambui?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 67, 'Siku hiyo marafiki watakuwa ni maadui wao kwa wao, isipokuwa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 68, 'Enyi waja wangu! Hamtakuwa na khofu siku hiyo, wala hamtahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 69, 'Ambao waliziamini Ishara zangu na walikuwa Waislamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 70, 'Ingieni Bustanini, nyinyi na wake zenu; mtafurahishwa humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 71, 'Watakuwa wanapitishiwa sahani za dhahabu na vikombe, na vitakuwemo ambavyo nafsi zinavipenda na macho yanavifurahia, na nyinyi mtakaa humo milele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 72, 'Na hiyo ni Bustani ya mbinguni mliyorithishwa kwa mliyokuwa mkiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 73, 'Mnayo humo matunda mengi mtakayoyala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 74, 'Kwa hakika wakosefu watakaa katika adhabu ya Jahannamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 75, 'Hawatapumzishwa nayo, na humo watakata tamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 76, 'Wala Sisi hatukuwadhulumu, bali wao ndio waliokuwa madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 77, 'Nao watapiga kelele waseme: ''Ewe Malik! Na atufishe Mola wako Mlezi!'' Naye aseme: ''Hakika nyinyi mtakaa humo humo!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 78, 'Kwa yakini tulikuleteeni Haki, lakini wengi katika nyinyi mlikuwa mnaichukia Haki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 79, 'Au waliweza kupitisha amri yao? Bali ni Sisi ndio tunaopitisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 80, 'Au wanadhani kwamba hatusikii siri zao na minong''ono yao? Wapi! Na wajumbe wetu wapo karibu nao, wanayaandika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 81, 'Sema: ''Ingelikuwa Rahmani (Mwingi wa Rehema) ana mwana, basi mimi ningelikuwa wa kwanza kumuabudu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 82, 'Ametakasika Mola Mlezi wa mbingu na ardhi, Mola Mlezi wa A''rshi, na hayo wanayomsifia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 83, 'Basi waache wapige porojo wakicheza mpaka wakutwe na hiyo siku yao waliyoahidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 84, 'Na Yeye ndiye Mungu mbinguni, na ndiye Mungu katika ardhi. Naye ndiye Mwenye hekima, Mwenye kujua mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 85, 'Na ametukuka Mwenye ufalme wa mbingu na ardhi na vilivyo kati yake. Na uko kwake ujuzi wa Saa ya Kiyama, na kwake Yeye mtarudishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 86, 'Wala hao mnaowaomba badala yake Yeye hawana uweza wa kumwombea mtu, isipokuwa anayeshuhudia kwa haki, na wao wanajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 87, 'Na ukiwauliza ni nani aliyewaumba. Bila ya shaka watasema ni Mwenyezi Mungu! Basi ni wapi wanakogeuziwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 88, 'Na usemi wake (Mtume) ni: ʻEwe Mola wangu Mlezi! Hakika hawa ni watu wasioamini.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 89, 'Basi wasamehe, na uwaambie maneno ya salama. Watakujajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 1, 'Ha Mim.[1]', '[1] Herufi hizi "Ha, Mim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 2, 'Ninaapa kwa Kitabu kinachobainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 3, 'Hakika Sisi tumekiteremsha katika usiku uliobarikiwa. Hakika Sisi ni Waonyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 4, 'Katika usiku huu hubainishwa kila jambo la hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 5, 'Jambo litokalo kwetu. Hakika Sisi ndio wenye kutuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 6, 'Ni rehema itokayo kwa Mola wako Mlezi. Hakika Yeye ni Mwenye kusikia, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 7, 'Mola Mlezi wa mbingu na ardhi na vilivyo baina yao, ikiwa nyinyi mna yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 8, 'Hakuna mungu ila Yeye; anahuisha na anafisha- Mola Mlezi wenu na Mola Mlezi wa baba zenu wa mwanzo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 9, 'Lakini wao wanacheza katika shaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 10, 'Basi ingoje siku ambayo mbingu zitakapoleta moshi ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 11, 'Utakaowafunika watu. Hii ni adhabu chungu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 12, 'Mola wetu Mlezi! Tuondolee adhabu hii. Hakika tutaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 13, 'Nini faida ya kukumbuka kwao? Na alikwisha wafikia Mtume mwenye kubainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 14, 'Na wao wakamgeuzia uso, na wakasema: ''Huyu amefunzwa, naye ni mwendawazimu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 15, 'Hakika sisi tutaiondoa adhabu kidogo, lakini nyinyi kwa yakini mtarejea vile vile!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 16, 'Siku tutakayoyashambulia mashambulio makubwa, bila ya shaka Sisi ni wenye kutesa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 17, 'Na hakika kabla ya hawa tuliwafanyia mtihani watu wa Firauni, na aliwafikia Mtume Mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 18, 'Akasema: ''Nipeni waja wa Mwenyezi Mungu; kwa hakika mimi kwenu ni Mtume Muaminifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 19, 'Na msimfanyie kiburi Mwenyezi Mungu; hakika mimi nitakuleteeni uthibitisho ulio wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 20, 'Nami najikinga kwa Mola wangu Mlezi na ndiye Mola wenu Mlezi pia, ili msinipige mawe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 21, 'Na ikiwa hamniamini, basi jitengeni nami.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 22, 'Ndipo akamwomba Mola wake Mlezi: ''Hakika watu hawa ni wakosefu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 23, 'Mwenyezi Mungu akasema: ''Basi nenda na waja wangu usiku. Kwa yakini mtafuatwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 24, 'Na iache bahari vivyo hivyo imeachana, hakika wao ni jeshi litakalozamishwa.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 25, 'Mabustani mangapi na chemchemi ngapi waliziacha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 26, 'Na mimea na vyeo vitukufu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 27, 'Na neema walizokuwa wakijistareheshea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 28, 'Ndio hivyo! Na tukawarithisha haya watu wengineo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 29, 'Basi mbingu wala ardhi hazikuwalilia, wala hawakupewa muhula.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 30, 'Na bila ya shaka tuliwaokoa Wana wa Israili katika adhabu ya kuwadhalilisha,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 31, 'Ya Firauni. Hakika yeye alikuwa jeuri katika wenye kupindukia mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 32, 'Na tuliwakhiari kwa ujuzi wetu kuliko walimwengu wengineo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 33, 'Na tukawapa katika ishara zenye majaribio yaliyo wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 34, 'Hakika hawa wanasema:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 35, 'Hapana ila kufa kwetu mara ya kwanza tu, wala sisi hatufufuliwi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 36, 'Basi warudisheni baba zetu, ikiwa nyinyi mnasema kweli.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 37, 'Je, ni wao bora au watu wa Tubbaa'' na waliokuwa kabla yao? Tuliwaangamiza. Hakika hao walikuwa wakosefu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 38, 'Na hatukuziumba mbingu na ardhi na vilivyo baina yake kwa mchezo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 39, 'Hatukuviumba hivyo ila kwa Haki, lakini wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 40, 'Hakika siku ya Uamuzi ni wakati uliowekwa kwa wao wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 41, 'Siku ambayo rafiki hatamfaa rafiki yake kwa chochote, wala hawatanusuriwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 42, 'Isipokuwa yule mbaye Mwenyezi Mungu atamrehemu. Hakika Yeye ndiye Mwenye nguvu, Mwenye kurehemu mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 43, 'Hakika Mti wa Zaqqum', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 44, 'Ni chakula cha mwenye dhambi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 45, 'Kama shaba iliyoyeyushwa, hutokota matumboni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 46, 'Kama kutokota kwa maji ya moto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 47, '(Itasemwa): ''Mkamateni na mtupeni katikati ya Jahannamu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 48, 'Kisha mmwagieni juu ya kichwa chake adhabu ya maji yanayochemka.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 49, 'Onja! Ati wewe ndiye mwenye nguvu, mtukufu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 50, 'Hakika haya ndiyo mliyokuwa mkiyatilia shaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 51, 'Hakika wacha Mungu watakuwa katika mahali pa amani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 52, 'Katika mabustani na chemchemi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 53, 'Watavaa hariri nyepesi na hariri nzito wakielekeana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 54, 'Hivi ndivyo itakavyokuwa, na tutawaoza mahurilaini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 55, 'Humo watataka kila aina ya matunda, na wakae kwa amani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 56, 'Humo hawataonja mauti ila mauti yale ya kwanza, na (Mwenyezi Mungu) atawalinda kutokana na adhabu ya Jahannamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 57, 'Kuwa ni fadhila zitokazo kwa Mola wako Mlezi. Huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 58, 'Basi tumeifanya nyepesi hii Qur-ani kwa ulimi wako, ili wapate kukumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 59, 'Ngoja tu, na wao wangoje pia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 1, 'Ha Mim.[1]', '[1] Herufi hizi "Ha, Mim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 2, 'Uteremsho wa Kitabu umetoka kwa Mwenyezi Mungu, Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 3, 'Hakika katika mbingu na ardhi ziko Ishara kwa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 4, 'Na katika umbo lenu na katika wanyama aliowatawanya, zimo Ishara kwa watu wenye yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 5, 'Na kupishana usiku na mchana, na riziki anayoiteremsha Mwenyezi Mungu kutoka mbinguni, na kwayo akaifufua ardhi baada ya kufa kwake, na mabadiliko ya upepo, ni Ishara kwa watu wenye akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 6, 'Hizi ni Aya za Mwenyezi Mungu tunakusomea kwa haki; basi hadithi gani watakayoiamini baada ya Mwenyezi Mungu na Aya zake?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 7, 'Ole wake kila mzushi mwenye dhambi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 8, 'Anayesikia Aya za Mwenyezi Mungu akisomewa, kisha anashikilia yale yale aliyokatazwa, na anajivuna, kama kwamba hakuzisikia. Basi mbashirie adhabu chungu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 9, 'Na anapokijua kitu kidogo katika Aya zetu, hukifanyia mzaha. Watu hao ndio watakaokuwa na adhabu ya kufedhehesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 10, 'Na nyuma yao ipo Jahanamu. Na waliyoyachuma hayatawafaa hata kidogo, wala walinzi waliowashika badala ya Mwenyezi Mungu. Na watapata adhabu kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 11, 'Huu ni uongofu. Na wale wale waliozikataa Ishara za Mola wao Mlezi watapata adhabu inayotokana na ghadhabu, iliyo chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 12, 'Mwenyezi Mungu ndiye aliyeifanya bahari ikutumikieni, ili humo zipite merikebu kwa amri yake, na ili mtafute fadhila yake, na ili mpate kushukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 13, 'Na amefanya vikutumikieni vilivyomo mbinguni na vilivyo katika ardhi, vyote vimetoka kwake. Hakika katika hayo zimo Ishara kwa watu wanaofikiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 14, 'Waambie walioamini wawasamehe wale wasiozitaraji siku za Mwenyezi Mungu, ili awalipe kwa waliyokuwa wakiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 15, 'Mwenye kutenda mema basi ni kwa ajili ya nafsi yake, na mwenye kutenda uovu ni juu yake mwenyewe. Kisha mtarudishwa kwa Mola wenu Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 16, 'Na hakika tuliwapa Wana wa Israili Kitabu, hukumu na Unabii, na tukawaruzuku vitu vizuri vizuri, na tukawafadhilisha kuliko walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 17, 'Na tukawapa maelezo wazi ya amri. Basi hawakuhitalifiana ila baada ya kuwajia elimu kwa sababu ya uhasidi uliokuwa baina yao. Hakika Mola wako Mlezi atahukumu baina yao Siku ya Kiyama katika mambo waliyokuwa wakihitilafiana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 18, 'Kisha tukakuweka wewe juu ya Njia ya haya mambo, basi ifuate, wala usifuate matamanio ya wasiojua kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 19, 'Kwa hakika hao hawatakufaa kitu mbele ya Mwenyezi Mungu. Na hakika wenye kudhulumu ni marafiki wao kwa wao. Na Mwenyezi Mungu ni rafiki msaidizi wa wamchao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 20, 'Hizi ni dalili zilizo wazi kwa watu wote, na ni uongofu na rehema kwa watu wenye yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 21, 'Je, wanadhani wale wanaotenda maovu kuwa tutawafanya wawe sawasawa na wale walioamini, na wakatenda mema, uhai wao na kufa kwao? Ni hukumu mbaya mno wanayoihukumu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 22, 'Na Mwenyezi Mungu ameziumba mbingu na ardhi kwa haki, na ili kila nafsi ilipwe yale iliyoyachuma. Nao hawatadhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 23, 'Je, umemwona aliyefanya matamanio yake kuwa ndiye mungu wake, na Mwenyezi Mungu akampoteza pamoja na kuwa ana elimu, na akaziba masikio yake, na moyo wake, na akambandika kifuniko kwenye kuona kwake? Basi ni nani atamwongoa huyo baada ya Mwenyezi Mungu? Je, hamkumbuki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 24, 'Na walisema: ''Hapana ila huu uhai wetu wa duniani - twafa na twaishi, na hapana kinachotuangamiza isipokuwa dahari.'' Lakini wao hawana elimu ya hayo, ila wao wanadhani tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 25, 'Na wakisomewa Aya zetu zilizo wazi hawana hoja ila kusema: ''Waleteni baba zetu, ikiwa nyinyi ni wasemao kweli.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 26, 'Sema: ''Mwenyezi Mungu anawahuisha, kisha anawafisha, kisha atawakusanya Siku ya Kiyama isiyo na shaka. Lakini watu wengi hawajui.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 27, 'Na Mwenyezi Mungu ndiye Mwenye ufalme wa mbingu na ardhi. Na siku itakaposimama Saa ya Kiyama, siku hiyo wataangamia wenye kushikamana na upotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 28, 'Na utauona kila umma umepiga magoti, na kila umma utaitwa kwenda kusoma kitabu chake: Leo mtalipwa mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 29, 'Hiki kitabu chetu kinasema juu yenu kwa haki. Hakika Sisi tulikuwa tukiyaandika mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 30, 'Ama walioamini na wakatenda mema, Mola wao Mlezi atawatia katika rehema yake. Huko ndiko kufuzu kuliko wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 31, 'Na ama waliokufuru wataambiwa: ''Kwani hamkuwa mkisomewa Aya zangu nanyi mkapanda kichwa, na mkawa watu wakosefu?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 32, 'Na ikisemwa: Hakika ahadi ya Mwenyezi Mungu ni kweli na Saa haina shaka, nyinyi mlikuwa mkisema: Hatuijui hiyo Saa, tunadhania dhana tu, wala hatuna yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 33, 'Basi ubaya wa yale waliyoyatenda utawadhihirikia, na yatawafika yale waliyokuwa wakiyafanyia masihara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 34, 'Na itasemwa: ''Leo tunawasahau kama nyinyi mlivyosahau mkutano wa siku yenu hii; na mahali penu ni Motoni, wala hamna wowote wa kuwanusuru.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 35, 'Hayo ni kwa sababu nyinyi mlizifanyia mzaha Aya za Mwenyezi Mungu, na maisha ya dunia yakawadanganya. Basi leo hawatatolewa humo wala hao hawatakubaliwa udhuru wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 36, 'Basi sifa njema zote ni za Mwenyezi Mungu, Mola Mlezi wa mbingu na Mola Mlezi wa ardhi, na Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 37, 'Na ukubwa ni wake Yeye tu, mbinguni na katika ardhi, naye ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 1, 'Ha, Mim.[1]', '[1] Herufi hizi "Ha, Mim" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 2, 'Uteremsho wa Kitabu uliotoka kwa Mwenyezi Mungu, Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 3, 'Hatukuziumba mbingu na ardhi wala yaliyo baina yake ila kwa haki na kwa muda maalumu. Na wale waliokufuru wanayapuuza yale wanayoonywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 4, 'Sema: Je, mwawaona wale mnaowaomba badala ya Mwenyezi Mungu? Nionyesheni wameumba nini katika ardhi; au hao wanalo fungu katika mbingu zote? Nileteeni Kitabu kilichokuwa kabla ya hiki, au alama yoyote ya elimu, ikiwa mnasema kweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 5, 'Na ni nani mpotovu mkubwa kuliko hao wanaoomba badala ya Mwenyezi Mungu wale ambao hawatawaitikia mpaka Siku ya Kiyama, na wala hata hawatambui maombi yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 6, 'Na ambao watu watakapokusanywa watakuwa maadui zao, na wataikataa ibada yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 7, 'Na wanaposomewa Aya zetu zilizo wazi, wale waliokufuru husema juu ya haki inapowajia: ''Huu ni uchawi dhahiri.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 8, 'Au wanasema: ''Ameizua mwenyewe!'' Sema: ''Ikiwa nimeizua mimi, basi nyinyi hamwezi kunifaa chochote mbele ya Mwenyezi Mungu. Yeye anajua zaidi hayo mnayoropokwa; anatosha kuwa shahidi baina yangu na nyinyi. Na Yeye ndiye Mwenye kusamehe mno, Mwingi wa kurehemu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 9, 'Sema: ''Mimi si kitu kigeni miongoni mwa Mitume. Wala sijui nitakavyofanywa mimi wala nyinyi. Mimi nafuata niliyofunuliwa tu kwa Wahyi, wala mimi si chochote ila ni mwonyaji wa wazi wazi.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 10, 'Sema: ''Mnaonaje yakiwa haya ni kweli yametoka kwa Mwenyezi Mungu, nanyi mmeyakufuru, na akashuhudia shahidi miongoni mwa Wana wa Israili juu ya mfano wa haya, na akaamini, na nyinyi mnafanya kiburi? Hakika Mwenyezi Mungu hawaongoi watu wenye kudhulumu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 11, 'Na wale waliokufuru waliwaambia wale walioamini: ''Lau kuwa hii ni heri, wasingelitutangulia kuifikia.'' Na walipokosa kuongoka, wakasema: ''Huu ni uzushi mkubwa wa zamani.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 12, 'Na kabla yake kilikuwapo Kitabu cha Musa, chenye uongozi na rehema. Na hiki ni Kitabu cha kusadikisha na kilichokuja kwa lugha ya Kiarabu, ili kiwaonye wale waliodhulumu, na kiwe ni bishara njema kwa watendao mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 13, 'Hakika wale waliosema: ''Mola wetu Mlezi ni Mwenyezi Mungu'' kisha wakanyooka sawasawa, hawatakuwa na hofu, wala hawatahuzunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 14, 'Hao ndio watu wa Bustani za mbinguni, watadumu humo, kuwa ni malipo kwa yale waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 15, 'Na tumemuusia mwanadamu awatendee wema wazazi wake wawili. Mama yake amechukua mimba yake kwa taabu, na akamzaa kwa taabu. Na kuchukua mimba kwake hata kumwachisha ziwa ni miezi thelathini. Hata anapofika utu uzima wake, na akafikilia miaka arubaini, husema: ''Mola wangu Mlezi! Niwezeshe nishukuru neema zako ulizonineemesha mimi na wazazi wangu, na nitende mema unayoyapenda. Na unitengenezee dhuriya zangu. Hakika mimi nimetubu kwako, na hakika mimi ni miongoni mwa Waislamu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 16, 'Hao ndio tunaowapokelea bora ya vitendo vyao walivyovitenda, na tunayasamehe makosa yao. Watakuwa miongoni mwa watu wa Bustani za mbinguni. Miadi ya kweli hiyo waliyokuwa wakiahidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 17, 'Na yule aliyewafyonya wazazi wake: ''Uff kwenu nyote. Ati ndio mnanitisha kuwa nitafufuliwa, na hali vizazi vingi vimekwisha pita kabla yangu!'' Na hao wazazi humwomba msaada Mwenyezi Mungu (na humwambia mtoto wao): ''Ole wako! Amini! Hakika ahadi ya Mwenyezi Mungu ni kweli.'' Na yeye husema: ''Hayakuwa haya ila ni visa vya watu wa kale.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 18, 'Hao ndio ambao imehakikishwa hukumu juu yao kama mataifa yaliyokwisha pita kabla yao miongoni mwa majini na watu. Hakika hao wamekuwa wenye kuhasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 19, 'Na wote watakuwa na daraja zao mbalimbali kwa waliyoyatenda, na ili awalipe kwa ukamilifu kwa vitendo vyao, na wala hawatadhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 20, 'Na siku watakapoletwa wale waliokufuru kwenye Moto, wataambiwa: ''Nyinyi mlitwaa vitu vyenu vizuri katika uhai wa duniani, na mkajistarehesha navyo. Basi leo ndio mnalipwa adhabu ya fedheha kwa yale mlivyokuwa mkitakabari katika ardhi bila ya haki, na kwa sababu mlikuwa mkivuka mipaka.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 21, 'Na mtaje ndugu wa kina ''Adi, alipowaonya watu wake kwenye vilima vya mchanga. Na kwa yakini waonyaji wengi walitokea kabla yake na baada yake kuwaambia: ''Msimuabudu isipokuwa Mwenyezi Mungu. Hakika mimi nawahofia ije kukupateni adhabu ya siku iliyo kuu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 22, 'Wakasema: ''Je, umetujia ili ututenge mbali na miungu yetu? Basi tuletee hayo unayotuahidi ikiwa wewe ni miongoni mwa wasemao kweli.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 23, 'Akasema: ''Hakika ujua wa hayo uko kwa Mwenyezi Mungu. Mimi nawafikishieni yale niliyotumwa nayo. Lakini nawaona kuwa nyinyi mnafanya ujinga tu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 24, 'Basi walipoliona wingu likielekea kwenye mabonde yao, walisema: ''Hili ni wingu la kutunyeshea mvua!'' Kumbe sivyo, haya ni hayo mliyotaka yawajie haraka: upepo ambao ndani yake imo adhabu chungu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 25, 'Unaharibu kila kitu kwa amri ya Mola wake Mlezi. Wakawa hawaonekani ila nyumba zao tu. Hivyo ndivyo tuwalipavyo watu wahalifu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 26, 'Na bila ya shaka tuliwaweka vizuri siyo kama tulivyokuwekeni nyinyi, na tuliwapa uwezo wa kusikia, na kuona na ufahamu wa nyoyo. Na hayakuwafaa uwezo wao wa kusikia, na kuona na ufahamu wa nyoyo kwa lolote. Kwani hao walikuwa wakizikataa Ishara za Mwenyezi Mungu, na yale waliyokuwa wakiyafanyia masihara ndiyo yakawafika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 27, 'Na hakika tuliiangamiza miji iliyo jirani zenu, na tulizitumia Ishara mbalimbali ili wapate kurejea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 28, 'Basi mbona wale waliowashika badala ya Mwenyezi Mungu, kuwa ati hao ndio wawakurubishe, hawakuwanusuru? Bali waliwapotea! Na huo ndio uongo mkubwa waliokuwa wakiuzua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 29, 'Na wakati tulipowaleta kundi la majini kuja kwako kusikiliza Qur-ani. Basi walipoihudhuria, walisema: ''Sikilizeni!'' Na ilipokwisha somwa, walirudi kwa kaumu yao kwenda kuwaonya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 30, 'Wakasema: ''Enyi kaumu yetu! Hakika sisi tumesikia Kitabu kilichoteremshwa baada ya Musa, kinachosadikisha yale yaliyokuwa kabla yake, na kinachoongoza kwenye Haki na kwenye njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 31, 'Enyi kaumu yetu! Muitikieni Mwenye kuitia kwa Mwenyezi Mungu, na muaminini, Mwenyezi Mungu atawasamehe, na atawakinga kutokana na adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 32, 'Na wasiomwitikia Mwitaji wa Mwenyezi Mungu, basi hao hawatashinda katika ardhi, wala hawatakuwa na walinzi mbele yake. Hao wamo katika upotovu ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 33, 'Je, hawaoni ya kwamba Mwenyezi Mungu, aliyeziumba mbingu na ardhi, na hakuchoka kwa kuziumba, kuwa ni Muweza wa kuwafufua wafu? Kwani? Hakika Yeye ni Muweza mno wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 34, 'Na siku watakapoletwa makafiri Motoni, wakaambiwa: ''Je, haya si kweli?'' Watasema: ''Ndivyo? Tunaapa kwa Mola wetu Mlezi, ni kweli!'' Atasema: ''Basi onjeni adhabu kwa sababu ya vile mlivyokuwa mkikufuru.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 35, 'Basi subiri, kama walivyosubiri Mitume wenye stahmala kubwa, wala usiwafanyie haraka. Siku watakayoyaona hayo waliyoahidiwa, itakuwa kama kwamba hawakukaa ulimwenguni ila saa moja ya mchana. Huu ndio ufikisho! Kwani huangamizwa wengine isipokuwa watu wavukao mipaka tu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 1, 'Wale waliokufuru na wakazuilia njia ya Mwenyezi Mungu, Yeye atavipotoa vitendo vyao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 2, 'Na wale walioamini, na wakatenda mema, na wakaamini yale aliyoteremshiwa Muhammad - nayo ni Haki iliyotoka kwa Mola wao Mlezi - atawafutia makosa yao na ataitengeneza hali yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 3, 'Hayo ni kwa sababu wale waliokufuru wamefuata upotovu, na wale walioamini wamefuata Haki iliyotoka kwa Mola wao Mlezi. Hivyo ndivyo Mwenyezi Mungu anavyowapigia watu mifano yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 4, 'Basi mnapowakuta wale waliokufuru, wapigeni shingoni mwao, mpaka mkiwadhoofisha, wafungeni pingu. Tena waachilieni kwa hisani au wajikomboe, mpaka vita vipoe. Ndivyo hivyo. Na lau angelitaka Mwenyezi Mungu, angeliwashinda mwenyewe, lakini haya ni kwa sababu awatie mitihani nyinyi kwa nyinyi. Na wale waliouliwa katika njia ya Mwenyezi Mungu, hatayapoteza matendo yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 5, 'Atawaongoza na awatengezee hali yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 6, 'Na atawaingiza katika Pepo aliyowajuulisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 7, 'Enyi mlioamini! Mkimnusuru Mwenyezi Mungu, naye atakunusuruni na ataiimarisha miguu yenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 8, 'Na wale waliokufuru, basi kwao ni maangamizo, na atavipoteza vitendo vyao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 9, 'Hayo ni kwa sababu waliyachukia yale aliyoyateremsha Mwenyezi Mungu, basi akaviangusha vitendo vyao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 10, 'Kwani hawakutembea katika ardhi wakaona ulikuwaje mwisho wa wale waliokuwa kabla yao? Mwenyezi Mungu aliwaangamiza, na kwa makafiri hawa itakuwa mifano ya hayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 11, 'Hayo ni kwa sababu Mwenyezi Mungu ni Mlinzi wa wale walioamini. Na makafiri hawana mlinzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 12, 'Hakika Mwenyezi Mungu atawaingiza wale walioamini na wakatenda mema katika Bustani za mbinguni zipitiwazo na mito kati yake. Na wale waliokufuru hujifurahisha na hula kama walavyo wanyama, na Moto ndio makazi yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 13, 'Na ni miji mingapi iliyokuwa na nguvu zaidi kuliko mji wako huu uliokutoa? Tuliwateketeza na wala hawakuwa na yeyote wa kuwanusuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 14, 'Je, yule aliye kwenye ubainifu kutoka kwa Mola wake Mlezi ni kama yule aliyepambiwa uovu wa vitendo vyake, na wakafuata matamanio yao?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 15, 'Mfano wa Bustani ya mbinguni waliyoahidiwa wacha Mungu, ina mito ya maji yasiyovunda, na mito ya maziwa yasiyoharibika ladha yake, na mito ya mvinyo wenye ladha kwa wanywao, na mito ya asali iliyosafishwa. Na wao humo watakuwa na kila namna ya matunda, na maghfira kutoka kwa Mola wao Mlezi. Basi hao ni kama watakaodumu Motoni na wakinyweshwa maji yanayochemka ya kuwakatakata matumbo yao?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 16, 'Na wapo miongoni mwao wanaokusikiliza, mpaka wakiondoka kwako, huwauliza waliopewa elimu: ''Amesema nini sasa hivi?'' Hao ndio ambao Mwenyezi Mungu ameziba nyoyo zao, na wakafuata matamanio yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 17, 'Na wale walioongoka anawazidishia uongofu na anawapa ucha Mungu wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 18, 'Kwani wanangojea jengine isipokuwa iwafikie Saa (ya Kiyama) kwa ghafla? Na hakika alama zake zimekwisha kuja. Na itakapowajia, kutawafaa nini kukumbuka kwao?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 19, 'Basi jua ya kwamba hapana mungu ila Mwenyezi Mungu, na omba maghufira kwa dhambi zako na za Waumini wanaume na Waumini wanawake. Na Mwenyezi Mungu anajua mahali penu pa kwenda na kurudi, na mahali penu pa kukaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 20, 'Na Waumini wanasema: ''Kwa nini haiteremshwi Sura?'' Na inapoteremshwa Sura madhubuti na ikatajwa ndani yake habari ya vita, utawaona wenye maradhi katika nyoyo zao wanakutazama mtazamo wa anayezimia kwa sababu ya mauti. Basi ni bora kwao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 21, 'Utiifu na kauli njema. Na jambo likishaazimiwa, basi wakiwa ni wakweli kwa Mwenyezi Mungu, bila ya shaka itakuwa ni heri kwao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 22, 'Basi mnatarajia kwamba mkigeuka mkaenda zenu kwamba ndio mtafanya uharibifu katika nchi na muwatupe jamaa zenu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 23, 'Hao ndio aliowalaani Mwenyezi Mungu, na akawatia uziwi, na akawapofua macho yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 24, 'Je, hawaizingatii hii Qur-ani? Au kwenye nyoyo (zao) zipo kufuli zake?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 25, 'Kwa hakika wale wanaorudi nyuma baada ya uongofu kwisha wabainikia, Shetani huyo amewashawishi na amewaghuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 26, 'Hayo ni kwa sababu waliwaambia wale waliochukia yale aliyoyateremsha Mwenyezi Mungu: ''Tutakutiini katika baadhi ya mambo.'' Na Mwenyezi Mungu anajua siri zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 27, 'Basi itakuwaje Malaika watakapowafisha wakawa wanawapiga nyuso zao na migongo yao!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 28, 'Hayo ni kwa sababu wao waliyafuata yale yaliyomchukiza Mwenyezi Mungu na wakachukia yanayomridhisha, basi akaviangusha vitendo vyao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 29, 'Je, wenye maradhi nyoyoni mwao wanadhani kwamba Mwenyezi Mungu hatazidhihirisha chuki zao?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 30, 'Na tungelipenda, tungelikuonyesha hao na ungeliwatambua kwa alama zao. Lakini bila ya shaka utawajua kwa namna ya msemo wao. Na Mwenyezi Mungu anavijua vitendo vyenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 31, 'Na bila ya shaka tutawajaribu mpaka tuwajue wapiganao Jihadi katika nyinyi na wanaosubiri. Nasi tutazifanyia mtihani habari zenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 32, 'Kwa hakika wale waliokufuru na wakazuilia njia ya Mwenyezi Mungu na wakapingana na Mtume baada ya uongofu kwisha wabainikia, hao hawatamdhuru Mwenyezi Mungu kwa lolote. Naye ataviangusha vitendo vyao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 33, 'Enyi mlioamini! Mtiini Mwenyezi Mungu, na mtiini Mtume, wala msiviharibu vitendo vyenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 34, 'Hakika wale waliokufuru na wakazuilia njia ya Mwenyezi Mungu, kisha wakafa na hali ni makafiri, Mwenyezi Mungu hatawasamehe makosa yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 35, 'Basi msilegee na mkataka suluhu, maana nyinyi ndio mtakaoshinda. Na Mwenyezi Mungu yu pamoja nanyi, wala hatawanyima malipo ya vitendo vyenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 36, 'Hakika uhai wa duniani ni mchezo na pumbao. Na mkiamini na mkamcha Mungu, Mwenyezi Mungu atakupeni ujira wenu, wala hatakutakeni mali zenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 37, 'Na akikutakeni hizo na kukushikilieni, mtafanya ubahili, na atatoa undani wa chuki zenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 38, 'Angalieni! Nyinyi hawa mnaitwa mtumie mali katika njia ya Mwenyezi Mungu, na wapo katika nyinyi wanaofanya ubahili. Na anayefanya ubahili, basi anajifanyia ubahili mwenyewe. Na Mwenyezi Mungu si mhitaji, na nyinyi ndio wahitaji. Na mkigeuka, atawaleta watu wengine badala yenu, nao hawatakuwa kama nyinyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 1, 'Hakika sisi tumekufungulia Ushindi wa dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 2, 'Ili Mwenyezi Mungu akusamehe makosa yako yaliyotangulia na yajayo, na akutimizie neema zake, na akuongoe katika njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 3, 'Na Mwenyezi Mungu akunusuru nusura yenye nguvu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 4, 'Yeye ndiye aliyeteremsha utulivu katika nyoyo za Waumini ili wazidi Imani juu ya Imani yao. Na Mwenyezi Mungu ndiye mwenye majeshi ya mbingu na ardhi. Na Mwenyezi Mungu ni Mwenye elimu mno, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 5, 'Ili awaingize Waumini wanaume na Waumini wanawake katika Bustani za mbinguni zipitazo mito chini yake, wadumu humo, na awafutie makosa yao. Na huko ndiko kufuzu kukubwa mbele ya Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 6, 'Na awape adhabu wanafiki wanaume na wanafiki wanawake, na washirikina wanaume na washirikina wanawake, wanaomdhania Mwenyezi Mungu dhana mbaya. Utawafikia mgeuko mbaya, na Mwenyezi Mungu awakasirikie, na awalaani, na awaandalie Jahanamu. Na hayo ni marudio maovu kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 7, 'Na Mwenyezi Mungu ana majeshi ya mbingu na ardhi. Na Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 8, 'Hakika tumekutuma wewe uwe Shahidi, na Mbashiri, na Mwonyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 9, 'Ili mumuamini Mwenyezi Mungu na Mtume wake, na mumsaidie, na mumheshimu, na mumtakase (Mwenyezi Mungu) asubuhi na jioni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 10, 'Bila ya shaka wale wanaokupa kiapo cha utii, kwa hakika wanampa Mwenyezi Mungu kiapo cha utii. Mkono wa Mwenyezi Mungu uko juu ya mikono yao. Kwa hivyo, avunjaye ahadi hizi, basi anavunja kwa kuidhuru nafsi yake. Na anayetekeleza aliyomuahadi Mwenyezi Mungu, basi Mwenyezi Mungu atamlipa ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 11, 'Watakuambia mabedui waliobaki nyuma: ''Zimetushughulisha mali zetu na ahali zetu, basi tuombee msamaha.'' Wanasema kwa ndimi zao yasiyokuwamo katika nyoyo zao. Sema: ''Ni nani awezaye kukusaidieni chochote kwa Mwenyezi Mungu akitaka Yeye kuwadhuru au akitaka kuwanufaisha? Bali Mwenyezi Mungu anazo habari za mnayoyatenda.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 12, 'Lakini mlidhani kwamba Mtume na Waumini hawatarudi kabisa kwa ahali zao, na mkapambiwa hayo katika nyoyo zenu, na mkadhania dhana mbaya, na mkawa watu wanaoangamia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 13, 'Na asiyemuamini Mwenyezi Mungu na Mtume wake, basi kwa hakika Sisi tumewaandalia makafiri Moto mkali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 14, 'Na Mwenyezi Mungu ndiye mwenye ufalme wa mbingu na ardhi. Humsamehe amtakaye, na humuadhibu amtakaye. Na Mwenyezi Mungu ni Mwenye kusamehe mno, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 15, 'Wale waliobaki nyuma watasema: ''Mtakapokwenda kuchukua ngawira, tuacheni tukufuateni!'' Wanataka kuyabadili maneno ya Mwenyezi Mungu. Sema: ''Hamtatufuata kabisa. Mwenyezi Mungu alikwisha sema hivi zamani.'' Hapo watasema: ''Bali nyinyi mnatuhusudu.'' Sivyo, bali walikuwa hawafahamu ila kidogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 16, 'Waambie wale walioachwa nyuma katika mabedui: ''Mtakuja itwa kwenda kupigana na watu wakali kwa vita, mpigane nao au wasalimu amri. Basi mkimtii, Mwenyezi Mungu atawapa ujira mzuri. Na mkigeuka kama mlivyogeuka kwanza, atawaadhibu kwa adhabu iliyo chungu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 17, 'Kipofu hana lawama, wala kiguru hana lawama, wala mgonjwa hana lawama. Na mwenye kumtii Mwenyezi Mungu na Mtume wake, atamuingiza katika Mabustani ya mbinguni yapitayo mito chini yake. Na atakayegeuka upande, atamuadhibu kwa adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 18, 'Kwa hakika Mwenyezi Mungu amewaridhia Waumini walipokuwa wanakupa ahadi ya utii chini ya mti, na alijua yaliyomo nyoyoni mwao. Basi akateremsha utulivu juu yao, na akawalipa kwa Ushindi wa karibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 19, 'Na ngawira nyingi watakazozichukua. Na Mwenyezi Mungu ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 20, 'Mwenyezi Mungu anawaahidi ngawira nyingi mtakazozichukua, basi amewatangulizia hizi kwanza, na akaizuia mikono ya watu isiwafikie, na ili hayo yawe ni Ishara kwa Waumini, na akawaongoza njia iliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 21, 'Na yale mengine hamwezi kuyapata bado, Mwenyezi Mungu amekwisha yazingira. Na Mwenyezi Mungu ni Muweza mno wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 22, 'Na lau makafiri wangelipigana nanyi, basi bila ya shaka wangeligeuza migongo, kisha wasingelipata mlinzi wala msaidizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 23, 'Huo ndio mwendo wa Mwenyezi Mungu uliokwisha pita zamani, wala hutapata mabadiliko katika mwendo wa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 24, 'Na Yeye ndiye aliyeizuia mikono yao kwenu, na mikono yenu kwao, katika bonde la Makka baada ya kuwapeni Ushindi juu yao. Na Mwenyezi Mungu ni Mwenye kuyaona mno myatendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 25, 'Hao ndio waliokufuru na wakawazuia msiingie Msikiti Mtakatifu, na wakawazuilia dhabihu kufika mahala pao. Na lau si wanaume Waumini na wanawake Waumini msiowajua mkawasaga na mkaingia makosani kutokana nao bila ya kujua... Mwenyezi Mungu (amefanya haya) ili amuingize amtakaye katika rehema yake. Lau wangelitengana, bila ya shaka tungeliwaadhibu wale waliokufuru kwa adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 26, 'Pale wale waliokufuru walipotia katika nyoyo zao hasira, hasira za kijinga, Mwenyezi Mungu aliteremsha utulivu juu ya Mtume wake na juu ya Waumini, na akawalazimisha neno la kumcha Mungu. Na wao walikuwa ndio wenye haki nalo na wenye kustahili. Na Mwenyezi Mungu ni mwenye kujua mno kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 27, 'Hakika Mwenyezi Mungu amemtimizia Mtume wake ndoto ya haki. Bila ya shaka nyinyi mtauingia Msikiti Mtakatifu, Inshallah (Mwenyezi Mungu akipenda), kwa amani, na hali mmenyoa vichwa vyenu na mmepunguza nywele. Hamtakuwa na hofu. Yeye anajua msiyoyajua. Basi atawapea kabla ya haya Ushindi karibuni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 28, 'Yeye ndiye aliyemtuma Mtume wake kwa uwongofu na Dini ya Haki, ili aipe ushindi juu ya dini zote. Na Mwenyezi Mungu anatosha kuwa Shahidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 29, 'Muhammad ni Mtume wa Mwenyezi Mungu. Na wale walio pamoja naye wana nguvu mbele ya makafiri, na wanahurumiana wao kwa wao. Utawaona wakiinama na kusujudu wakitafuta fadhila na radhi za Mwenyezi Mungu. Alama zao zi katika nyuso zao, kutokana na athari ya kusujudu. Huu ndio mfano wao katika Taurati. Na mfano wao katika Injili ni kama mmea uliotoa chipukizi lake, kisha ukalitia nguvu, ukawa mnene, ukasimama sawa juu ya ubuwa wake, ukawafurahisha wakulima, ili kuwakasirisha kwa ajili yao makafiri. Mwenyezi Mungu amewaahidi wale walioamini na wakatenda mema katika wao msamaha na ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 1, 'Enyi mlioamini! Msitangulie mbele ya Mwenyezi Mungu na Mtume wake, na mcheni Mwenyezi Mungu. Hakika Mwenyezi Mungu ni Mwenye kusikia mno, Mwenye kujua zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 2, 'Enyi mlioamini! Msinyanyue sauti zenu kuliko sauti ya Nabii, wala msiseme naye kwa kelele kama mnavyosemezana nyinyi kwa nyinyi, visije vitendo vyenu vikaharibika, na hali hamtambui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 3, 'Kwa hakika wale wanaoteremsha sauti zao mbele ya Mtume wa Mwenyezi Mungu, hao ndio Mwenyezi Mungu amezisafisha nyoyo zao kwa ucha Mungu. Hao watakuwa na maghfira na ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 4, 'Hakika hao wanaokuita nawe uko nyuma ya vyumba, wengi wao hawatumii akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 5, 'Na lau wao wangelingojea mpaka uwatokee, ingelikuwa heri kwao. Na Mwenyezi Mungu ni Mwenye maghfira, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 6, 'Enyi mlioamini! Akikujieni mpotovu na habari yoyote, ichunguzeni, msije mkawasibu watu kwa kutojua, na mkawa tena wenye kujuta kwa mliyoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 7, 'Na jueni kuwa Mtume wa Mwenyezi Mungu yuko nanyi. Lau angeliwatii katika mambo mengi, bila ya shaka mngelitaabika. Lakini Mwenyezi Mungu amewapendezea Imani, na akaipamba katika nyoyo zenu, na amewafanya muuchukie ukafiri, na upotovu, na uasi. Hao ndio walioongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 8, 'Kwa fadhila za Mwenyezi Mungu na neema zake. Na Mwenyezi Mungu ni Mwenye kujua mno, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 9, 'Na ikiwa makundi mawili katika Waumini yanapigana, basi yapatanisheni. Na likiwa moja la hao linamdhulumu mwenziwe, basi lipigeni linalodhulumu mpaka lirejee kwenye amri ya Mwenyezi Mungu. Na likirudi, basi yapatanisheni kwa uadilifu. Na hukumuni kwa haki. Hakika Mwenyezi Mungu anawapenda wanaohukumu kwa haki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 10, 'Hakika Waumini ni ndugu, basi patanisheni baina ya ndugu zenu, na mcheni Mwenyezi Mungu ili mrehemewe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 11, 'Enyi mlioamini! Wanaume wasiwadharau wanaume wenzao, wala wanawake wasiwadharau wanawake wenzao. Huenda hao wakawa bora kuliko wao. Wala msivunjiane heshima, wala msiitane kwa majina ya kejeli. Ni uovu kutumia jina baya baada ya kwisha amini. Na wasiotubu, hao ndio wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 12, 'Enyi mlioamini! Jiepusheni na dhana nyingi, kwani baadhi ya dhana ni dhambi. Wala msipelelezane, wala msisengenyane nyinyi kwa nyinyi. Je, yupo katika nyinyi anayependa kuila nyama ya nduguye aliyekufa? Mnalichukia hilo! Na mcheni Mwenyezi Mungu. Hakika Mwenyezi Mungu ni Mwenye kupokea toba mno, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 13, 'Enyi watu! Hakika Sisi tumewaumba kutokana na mwanamume na mwanamke. Na tumekujaalieni kuwa ni mataifa na makabila ili mjuane. Hakika aliye mtukufu zaidi kati yenu kwa Mwenyezi Mungu ni huyo aliye mcha Mungu zaidi katika nyinyi. Hakika Mwenyezi Mungu ni Mwenye kujua mno, Mwenye habari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 14, 'Mabedui walisema: ''Tumeamini.'' Sema: ''Hamjaamini, lakini semeni: ''Tumesilimu.'' Kwani Imani haijaingia katika nyoyo zenu. Na mkimtii Mwenyezi Mungu na Mtume wake, hatakupunguzieni chochote katika vitendo vyenu. Hakika Mwenyezi Mungu ni Mwenye kusamehe mno, Mwingi wa kurehemu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 15, 'Hakika Waumini ni wale waliomuamini Mwenyezi Mungu na Mtume wake tena wasitie shaka kabisa, na wakapigana Jihadi katika Njia ya Mwenyezi Mungu kwa mali zao na nafsi zao. Hao ndio wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 16, 'Sema: ''Ati ndio mnamfundisha Mwenyezi Mungu Dini yenu, na hali Mwenyezi Mungu anayajua ya katika mbingu na ardhi, na Mwenyezi Mungu anajua vyema kila kitu?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 17, 'Wanakusimbulia kuwa wamesilimu! Sema: ''Msinisimbulie kwa kusilimu kwenu. Bali Mwenyezi Mungu ndiye aliyewafanyia hisani kwa kukuongoeni kwenye Imani, ikiwa nyinyi ni wakweli.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 18, 'Hakika Mwenyezi Mungu anajua siri za mbingu na ardhi. Na Mwenyezi Mungu anayaona mno myatendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 1, 'Qaaf.[1] Ninaapa kwa Qur-ani tukufu!', '[1] Herufi hii "Qaaf" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 2, 'Bali wanastaajabu kwamba amewafikia mwonyaji kutoka miongoni mwao, na wakasema makafiri: ''Hili ni jambo la ajabu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 3, 'Ati tukifa na tukawa udongo...? Kurejea huko kuko mbali!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 4, 'Hakika Sisi tunajua kiasi cha kila kinachopunguzwa na ardhi kutokana nao. Na kwetu kipo Kitabu kinachohifadhi vyema yote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 5, 'Lakini waliikanusha Haki ilipowajia; kwa hivyo wamo katika mambo ya mchanganyiko.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 6, 'Je, hawaangalii mbingu zilizo juu yao! Vipi tulivyozijenga, na tukazipamba. Wala hazina nyufa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 7, 'Na ardhi tumeitandaza na tukaiwekea milima, na tukaiotesha mimea mizuri ya kila namna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 8, 'Yawe haya ni kifumbua macho na ukumbusho kwa kila mja mwenye kurejea (kwa Mwenyezi Mungu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 9, 'Na tumeteremsha kutoka mbinguni maji yaliyobarikiwa, na kwa hayo tukaotesha mabustani na nafaka za kuvunwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 10, 'Na mitende mirefu yenye makole yaliyozaa kwa wingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 11, 'Ili iwe ni riziki kwa waja wangu. Na tukaifufua kwa maji nchi iliyokuwa imekufa. Kama hivyo ndivyo utakavyokuwa ufufuaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 12, 'Kabla yao walikadhibisha kaumu ya Nuhu na wakazi wa Rassi na Thamudi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 13, 'Na A''di na Firauni na kaumu ya Luti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 14, 'Na wakazi wa Machakani, na watu wa Tubbaa''. Wote hao waliwakanusha Mitume, kwa hivyo onyo likathibitika juu yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 15, 'Kwani tulichoka kwa kuumba mara ya kwanza? Bali wao wamo katika shaka tu juu ya umbo jipya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 16, 'Na hakika tulimuumba mtu, nasi tunayajua yanayomtia wasiwasi katika nafsi yake. Na Sisi tuko karibu naye kuliko mshipa wa shingoni mwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 17, 'Wanapopokea wapokeaji wawili, wanaokaa kuliani na kushotoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 18, 'Hatamki neno ila karibu yake yupo mwangalizi tayari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 19, 'Na uchungu wa kutoka roho utamjia kwa haki. Hayo ndiyo uliyokuwa ukiyakimbia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 20, 'Na litapulizwa baragumu. Hiyo ndiyo Siku ya Miadi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 21, 'Na kila nafsi itakuja na pamoja nayo mchungaji na shahidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 22, '(Aambiwe): ''Kwa hakika ulikuwa umeghafilika mbali na haya. Basi leo tumekuondolea pazia lako, na kwa hivyo kuona kwako leo ni kukali mno.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 23, 'Na mwenzake atasema: ''Huyu niliye naye mimi keshatayarishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 24, 'Mtupeni katika Jahanamu kila kafiri mkubwa mkaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 25, 'Akatazaye mno heri, arukaye mipaka, mwenye kutia shaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 26, 'Aliyeweka mungu mwingine pamoja na Mwenyezi Mungu. Basi mtupeni katika adhabu kali.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 27, 'Mwenzake aseme: ''Ewe Mola wetu Mlezi! Sikumpoteza mimi, bali yeye mwenyewe alikuwa katika upotovu wa mbali.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 28, '(Mwenyezi Mungu) aseme: ''Msigombane mbele yangu. Tayari niliwaletea mbele onyo langu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 29, 'Mbele yangu haibadilishwi kauli, wala Mimi siwadhulumu waja wangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 30, 'Siku tutakapoiambia Jahanamu: ''Je, umejaa?'' Nayo itasema: ''Je, kuna ziada?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 31, 'Na Bustani ya mbinguni italetwa karibu mno kwa ajili ya wacha Mungu, haitakuwa mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 32, 'Haya ndiyo mnayoahidiwa kwa kila mwenye kurejea mno kwa Mwenyezi Mungu na akajilinda vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 33, 'Mwenye kumwogopa mno Mwingi wa rehema hali kuwa hamwoni, na akaja kwa moyo uliotubia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 34, '(Ataambiwa) ingieni humo kwa salama. Hiyo ndiyo siku ya kudumu daima dawamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 35, 'Humo watapata wakitakacho, na kwetu yako ya ziada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 36, 'Na kaumu ngapi tuliziangamiza kabla yao, waliokuwa na nguvu zaidi kuliko hawa! Nao walitanga tanga katika nchi nyingi. Je, walipata pa kukimbilia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 37, 'Hakika katika hayo upo ukumbusho kwa mwenye moyo au akatega sikio naye yupo anashuhudia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 38, 'Na bila ya shaka Sisi tumeziumba mbingu na ardhi na vilivyo baina yake katika siku sita; na wala hayakutugusa machovu yoyote.[1]', '[1] Aya hii ilishuka ili kuwapinga Mayahudi na Wakristo wanaodai kwamba Mwenyezi Mungu alipumzika katika siku ya saba baada ya kuumba viumbe.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 39, 'Basi vumilia kwa hayo wasemayo, na mtakase kwa kumsifu Mola wako Mlezi kabla ya kuchomoza jua na kabla ya kuchwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 40, 'Na katika usiku pia mtakase, na baada ya kusujudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 41, 'Na sikiliza siku atakaponadi mwenye kunadi kutoka mahali karibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 42, 'Siku watakaposikia ukelele wa haki. Hiyo ndiyo siku ya kufufuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 43, 'Hakika Sisi tunahuisha na tunafisha, na kwetu Sisi ndio marejeo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 44, 'Siku itapowapasukia ardhi mbio mbio! Mkusanyo huo kwetu ni mwepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 45, 'Sisi tunajua kabisa wayasemayo. Wala wewe si mwenye kuwatawalia kwa ujabari. Basi mkumbushe kwa Qur-ani anayeliogopa onyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 1, 'Ninaapa kwa pepo zinazotawanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 2, 'Na zinazobeba mizigo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 3, 'Na zinazokwenda kwa wepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 4, 'Na zinazogawanya kwa amri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 5, 'Hakika mnayoahidiwa bila ya shaka ni ya ukweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 6, 'Na kwa hakika malipo bila ya shaka yatatokea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 7, 'Ninaapa kwa mbingu zenye njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 8, 'Hakika nyinyi bila ya shaka mmo katika kauli inayohitalifiana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 9, 'Anageuzwa kutokana na haki mwenye kugeuzwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 10, 'Wazushi wameangamizwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 11, 'Ambao wameghafilika katika ujinga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 12, 'Wanauliza: ''Ni lini hiyo siku ya malipo?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 13, 'Hiyo ni siku watakayoadhibiwa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 14, 'Onjeni adhabu yenu! Haya ndiyo mliyokuwa mkiyafanyia haraka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 15, 'Hakika wacha Mungu watakuwa katika Mabustani ya mbinguni na chemchemi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 16, 'Wanapokea yale aliyowapa Mola wao Mlezi. Kwa hakika hao walikuwa kabla ya haya wakifanya mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 17, 'Walikuwa wakilala kidogo tu usiku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 18, 'Na kabla ya alfajiri wakiomba maghfira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 19, 'Na katika mali yao ipo haki ya mwenye kuomba na asiyeomba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 20, 'Na katika ardhi zipo Ishara kwa wenye yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 21, 'Na pia katika nafsi zenu - Je, hamwoni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 22, 'Na katika mbingu ziko riziki zenu na yale mnayoahidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 23, 'Basi ninaapa kwa Mola Mlezi wa mbingu na ardhi, hakika haya ni kweli kama ilivyo kweli kuwa nyinyi mnasema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 24, 'Je, imekufikia hadithi ya wageni wa Ibrahim wanaoheshimiwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 25, 'Walipoingia kwake na wakasema: ''Salama!'' Na yeye akasema: ''Salama! Nyinyi ni watu nisiowajua.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 26, 'Basi akaenda kwa ahali yake na akaja na ndama aliyenona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 27, 'Akawakaribishia, akasema: ''Mbona hamli?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 28, 'Kwa hivyo, akahisi kuwaogopa katika nafsi yake. Wakasema: ''Usiwe na hofu.'' Basi wakambashiria kupata kijana mwenye elimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 29, 'Ndipo mkewe akawaelekea kwa sauti ya kelele huku anajipiga usoni kwa mastaajabu, akasema: "Mimi ni kikongwe na tasa!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 30, 'Wakasema: Ndivyo vivyo hivyo alivyosema Mola wako Mlezi. Hakika Yeye ni Mwenye hekima, Mwenye kujua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 31, 'Akasema: ''Basi ujumbe wenu ni nini, enyi mliotumwa?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 32, 'Wakasema: ''Hakika sisi tumetumwa kwa watu wakosefu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 33, 'Tuwatupie mawe ya udongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 34, 'Yaliyotiwa alama kutoka kwa Mola wako Mlezi kwa ajili ya wanaopindukia mipaka.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 35, 'Kwa hivyo tukawatoa katika hao wale walioamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 36, 'Lakini hatukupata humo ila nyumba moja tu yenye Waislamu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 37, 'Na tukaacha humo Ishara kwa ajili ya wanaoiogopa adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 38, 'Na katika habari za Musa, tulipomtuma kwa Firauni na hoja wazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 39, 'Lakini alipuuza kwa sababu ya nguvu zake na akasema: ''Huyu ni mchawi au mwendawazimu!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 40, 'Basi tukamkamata yeye na majeshi yake na tukawatupa baharini, huku ni wa kulaumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 41, 'Na katika habari za ''Adi tulipowatumia upepo wa kukata uzazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 42, 'Haukuacha chochote ulichokifikia ila ulikifanya kama kilichonyambuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 43, 'Na katika habari za Thamudi walipoambiwa: ''Jifurahisheni kwa muda mdogo tu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 44, 'Wakaasi amri ya Mola wao Mlezi. Basi ukawanyakua moto wa radi nao wanaona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 45, 'Basi hawakuweza kusimama wala hawakuwa wenye kujitetea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 46, 'Na kaumu ya Nuhu hapo mbele. Hakika hao walikuwa watu wapotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 47, 'Na mbingu tumezifanya kwa nguvu na uwezo na hakika Sisi bila ya shaka ndio wenye uwezo wa kuzitanua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 48, 'Na ardhi tumeitandaza; basi watandazaji wazuri namna gani Sisi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 49, 'Na katika kila kitu tumeumba kwa jozi ili mzingatie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 50, 'Basi kimbilieni kwa Mwenyezi Mungu, hakika mimi ni mwonyaji kwenu wa kubainisha nitokae kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 51, 'Wala msifanye kuwa kuna mungu mwengine pamoja na Mwenyezi Mungu. Hakika mimi ni mwonyaji kwenu wa kubainisha nitokae kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 52, 'Basi ndio hivyo hivyo, hakuwajia kabla yao Mtume ila walisema: ''Huyu ni mchawi au mwendawazimu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 53, 'Je, wameambizana kwa haya? Bali hawa ni watu waasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 54, 'Basi waachilie mbali, nawe hulaumiwi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 55, 'Na kumbusha, kwani ukumbusho huwafaa Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 56, 'Nami sikuwaumba majini na watu ila waniabudu Mimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 57, 'Na sitaki kwao riziki, wala sitaki wanilishe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 58, 'Hakika Mwenyezi Mungu ndiye Mwenye kuruzuku, Mwenye nguvu, Madhubuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 59, 'Hakika wale waliodhulumu wana fungu lao la adhabu kama fungu la wenzao. Basi wasiniharakishe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 60, 'Basi ole wao wale walioikanusha siku yao waliyoahidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 1, 'Ninaapa kwa mlima wa T''ur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 2, 'Na Kitabu kilichoandikwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 3, 'Katika ngozi iliyokunjuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 4, 'Na kwa Nyumba iliyojengwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 5, 'Na kwa dari iliyonyanyuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 6, 'Na kwa bahari iliyojazwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 7, 'Hakika adhabu ya Mola wako Mlezi hapana shaka itatokea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 8, 'Hapana wa kuizuia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 9, 'Siku zitakapotikisika mbingu kwa mtikiso.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 10, 'Na milima iwe inakwenda kwa mwendo mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 11, 'Basi ole wao siku hiyo hao wanaokadhibisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 12, 'Ambao wanacheza katika mambo ya upuuzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 13, 'Siku watakaposukumwa kwenye Moto kwa msukumo wa nguvu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 14, '(Waambiwe): Huu ndio ule Moto mliokuwa mkiukadhibisha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 15, 'Je, huu ni uchawi, au hamwoni tu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 16, 'Uingieni, mkistahamili au msistahamili - ni mamoja kwenu. Hakika mnalipwa kwa mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 17, 'Hakika wacha Mungu watakuwa katika Mabustani na neema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 18, 'Wakifurahi kwa yale aliyowapa Mola wao Mlezi. Na Mola wao Mlezi atawalinda kutokana na adhabu ya Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 19, 'Kuleni na kunyweni kwa raha kabisa kwa sababu ya mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 20, 'Watakuwa wameegemea juu ya viti vya enzi vilivyopangwa kwa safu. Na tutawaoza mahurulaini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 21, 'Na wale walioamini na dhuriya zao wakawafuata kwa Imani, tutawakutanisha nao dhuriya zao, na wala hatutawapunja hata kidogo katika vitendo vyao. Kila mtu lazima atapata alichokichuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 22, 'Na tutawapa matunda, na nyama kama watakavyopenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 23, 'Watapeana humo bilauri zisizo na vinywaji vya kuleta maneno ya upuuzi wala dhambi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 24, 'Iwe wanawapitia watumishi wao kama kwamba ni lulu zilizomo katika chaza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 25, 'Wataelekeana wakiulizana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 26, 'Waseme: Hakika tulikuwa zamani pamoja na ahali zetu tukiogopa mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 27, 'Basi Mwenyezi Mungu akatufanyia hisani na akatulinda mbali adhabu ya upepo wa Moto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 28, 'Hakika sisi zamani tulikuwa tukimwomba Yeye tu. Hakika Yeye ndiye Mwema Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 29, 'Basi kumbusha! Kwani wewe, kwa neema ya Mola wako Mlezi, si kuhani wala mwendawazimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 30, 'Au wanasema: Huyu ni mtunga mashairi, tunamtarajia kupatilizwa na dahari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 31, 'Sema: Tarajieni, na mimi pia ni pamoja nanyi katika kutarajia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 32, 'Au hizo akili zao ndio zinawaamrisha haya, au wao basi ni watu majeuri tu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 33, 'Au ndiyo wanasema: ''Ameitunga hii!'' Bali basi tu hawaamini!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 34, 'Basi nawalete masimulizi kama haya ikiwa wao wanasema kweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 35, 'Au wao wameumbwa pasipo kutokana na kitu chochote, au ni wao ndio waumbaji?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 36, 'Au wao wameziumba mbingu na ardhi? Bali hawana yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 37, 'Au wanazo hazina za Mola wako Mlezi au wao ndio wenye madaraka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 38, 'Au wanazo ngazi za kusikilizia? Basi huyo msikilizaji wao na alete hoja iliyo wazi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 39, 'Au Yeye Mwenyezi Mungu ana wasichana, na nyinyi ndio mna wavulana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 40, 'Au wewe unawaomba ujira, na kwa hivyo ndio wanaelemewa na uzito wa gharama?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 41, 'Au wanayo elimu ya ghaibu, nao wameandika?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 42, 'Au wanataka kufanya vitimbi tu? Lakini hao waliokufuru ndio watakaotegeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 43, 'Au wanaye mungu asiyekuwa Mwenyezi Mungu? Ametakasika Mwenyezi Mungu mbali na hao wanaowashirikisha naye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 44, 'Na hata wangeona pande linatoka mbinguni linaanguka wangesema: Ni mawingu yaliyobebana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 45, 'Basi waache mpaka wakutane na siku yao watakapohilikishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 46, 'Siku ambayo hila zao hazitawafaa hata kidogo, wala wao hawatanusuriwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 47, 'Na hakika wale waliodhulumu watapata adhabu nyingine isiyokuwa hii, lakini wengi wao hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 48, 'Na ingojee hukumu ya Mola wako Mlezi. Kwani wewe hakika uko mbele ya macho yetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 49, 'Na usiku pia mtakase, na zinapokuchwa nyota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 1, 'Ninaapa kwa nyota inapotua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 2, 'Mwenzenu huyu hakupotea, wala hakukosea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 3, 'Wala hatamki kwa matamanio.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 4, 'Hayakuwa haya ila ni ufunuo uliofunuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 5, 'Amemfundisha aliye Mwingi wa nguvu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 6, 'Mwenye kutua, akatulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 7, 'Naye yuko juu kabisa upeo wa macho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 8, 'Kisha akakaribia na akateremka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 9, 'Akawa ni kama baina ya mipinde miwili, au karibu zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 10, 'Akamfunulia mja wake (Mwenyezi Mungu) alichomfunulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 11, 'Ufahamu wa moyo wake haukukanusha uliyoyaona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 12, 'Je, mnabishana naye kwa aliyoyaona?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 13, 'Na akamwona mara nyingine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 14, 'Penye Mkunazi wa mwisho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 15, 'Karibu yake ndiyo ipo Bustani ya mbinguni inayokaliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 16, 'Kilipoufunika huo Mkunazi hicho kilichoufunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 17, 'Jicho halikuhangaika wala halikuruka mpaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 18, 'Kwa yakini aliona katika Ishara kubwa kabisa za Mola wake Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 19, 'Je, mmemuona Lata na Uzza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 20, 'Na Manaat, mwingine wa tatu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 21, 'Je, nyinyi mnao wana wanaume na Yeye ndio awe na wanawake?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 22, 'Huo ni mgawanyo wa dhuluma!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 23, 'Hayo hayakuwa ila ni majina mliyowapa nyinyi na baba zenu. Mwenyezi Mungu hakuleta uthibitisho wowote juu ya hayo. Hawafuati ila dhana tu na kipendacho nafsi. Na kwa yakini uongofu ulikwisha wafikia kutoka kwa Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 24, 'Ati mtu anakipata kila anachokitamani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 25, 'Mwenyezi Mungu tu ndiye Mwenye Akhera na dunia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 26, 'Na wako Malaika wangapi mbinguni, ambao uombezi wao hautafaa chochote isipokuwa baada ya Mwenyezi Mungu kutoa idhini kwa amtakaye na kumridhia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 27, 'Hakika wale wasioamini Akhera bila ya shaka wao ndio wanawaita Malaika kwa majina ya kike.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 28, 'Nao hawana elimu yoyote kwa hayo isipokuwa wanafuata dhana tu. Na dhana haisaidii chochote mbele ya haki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 29, 'Basi mwachilie mbali anayeupa kisogo ukumbusho wetu, na wala hataki ila maisha ya dunia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 30, 'Huo ndio mwisho wao wa elimu. Hakika Mola wako Mlezi ndiye anayemjua zaidi mwenye kuipotea njia yake, na Yeye ndiye anayemjua zaidi mwenye kuongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 31, 'Ni vya Mwenyezi Mungu vyote vilivyo mbinguni na vilivyo katika ardhi, ili awalipe wale waliotenda ubaya kwa waliyoyatenda, na wale waliotenda mema awalipe mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 32, 'Ambao wanajiweka mbali na madhambi makuu na vitendo vichafu, isipokuwa makosa hafifu. Hakika Mola wako Mlezi ni Mkunjufu wa maghfira, naye anakujueni sana tangu alipokuumbeni kutoka kwenye ardhi, na mlipokuwa mimba matumboni mwa mama zenu. Basi msijione watakatifu. Yeye anamjua sana mwenye kujikinga akawa mbali na maovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 33, 'Je, umemwona yule aliyegeuka akaenda zake?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 34, 'Na akapeana kidogo, kisha akajizuia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 35, 'Je, anayo huyo elimu ya ghaibu, basi ndiyo anaona?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 36, 'Au hakuambiwa yaliyomo katika Vitabu vya Musa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 37, 'Na vya Ibrahimu aliyetimiza ahadi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 38, 'Ya kwamba hakika nafsi iliyobeba madhambi haibebi madhambi ya mwengine?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 39, 'Na ya kwamba hatapata mtu ila aliyoyafanya mwenyewe?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 40, 'Na kwamba vitendo vyake vitaonekana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 41, 'Kisha ndio atalipwa malipo yake kwa hayo kwa ukamilifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 42, 'Na kwamba kwa Mola wako Mlezi ndiyo mwisho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 43, 'Na kwamba Yeye ndiye anayeleta kicheko na kilio.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 44, 'Na kwamba Yeye ndiye anayefisha na kuhuisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 45, 'Na kwamba Yeye ndiye aliyeumba jozi, dume na jike.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 46, 'Kutokana na mbegu ya uzazi inapomiminwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 47, 'Na kwamba ni juu yake ufufuo mwengine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 48, 'Na kwamba ni Yeye ndiye anayetosheleza na kukinaisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 49, 'Na kwamba hakika Yeye ndiye Mola Mlezi wa nyota ya Shii''ra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 50, 'Na kwamba Yeye ndiye aliyewaangamiza ''Adi wa kwanza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 51, 'Na Thamudi hakuwabakisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 52, 'Na kabla yao kaumu ya Nuhu. Na hao hakika walikuwa ni madhalimu zaidi, na waovu zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 53, 'Na miji iliyopinduliwa, ni Yeye aliyeipindua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 54, 'Vikaifunika vilivyofunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 55, 'Basi neema gani ya Mola wako Mlezi unayoifanyia shaka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 56, 'Hili ni onyo katika maonyo yale yale ya zamani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 57, 'Kiyama kimekaribia!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 58, 'Hapana wa kukifichua isipokuwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 59, 'Je, mnayastaajabia maneno haya?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 60, 'Na mnacheka, wala hamlii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 61, 'Nanyi mmeghafilika?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 62, 'Basi msujudieni Mwenyezi Mungu, na mumuabudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 1, 'Saa imekaribia, na mwezi umepasuka!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 2, 'Na wakiona Ishara, hugeuka upande na husema: ''Huu uchawi tu unazidi kuendelea.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 3, 'Na wamekanusha na wamefuata matamanio yao. Na kila jambo ni lenye kuthibiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 4, 'Na bila ya shaka zimewajia habari zenye makaripio.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 5, 'Hekima kamili; lakini maonyo hayafai kitu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 6, 'Basi jiepushe nao. Siku atakapoita mwitaji kuliendea jambo linalochusha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 7, 'Macho yao yatainama; watatoka makaburini kama nzige waliotawanyika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 8, 'Wanamkimbilia mwitaji, na makafiri wanasema: ''Hii ni siku ngumu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 9, 'Kabla yao kaumu ya Nuhu walikanusha; wakamkanusha mja wetu, na wakasema ni mwendawazimu, na akakaripiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 10, 'Basi akamwomba Mola wake Mlezi akasema: ''Kwa hakika mimi nimeshindwa, basi ninusuru!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 11, 'Basi tukaifungua milango ya mbingu kwa maji yanayomiminika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 12, 'Na tukazipasua ardhi kwa chemichemi, yakakutana maji kwa jambo lililokwisha pangwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 13, 'Na tukambeba kwenye safina ya mbao na kamba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 14, 'Ikawa inakwenda kwa macho yetu, kuwa ni malipo kwa aliyekuwa amekanushwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 15, 'Na bila ya shaka tuliiacha iwe ni Ishara. Lakini je, yupo anayekumbuka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 16, 'Basi ilikuwaje adhabu yangu, na maonyo yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 17, 'Na bila ya shaka Sisi tumeifanya Qur-ani iwe nyepesi kufahamika. Lakini yupo anayekumbuka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 18, 'Kina ''Adi walikanusha. Basi ilikuwaje adhabu yangu na maonyo yangu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 19, 'Hakika Sisi tuliwatumia upepo wa kimbunga katika siku korofi mfululizo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 20, 'Ukiwang''oa watu kama vigogo vya mitende vilivyong''olewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 21, 'Basi ilikuwaje adhabu yangu na maonyo yangu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 22, 'Na bila ya shaka Sisi tumeifanya Qur-ani nyepesi kufahamika; lakini yupo anayekumbuka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 23, 'Thamudi waliwakanusha Waonyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 24, 'Wakasema: ''Ati tumfuate binadamu mmoja katika sisi? Basi hivyo sisi tutakuwa katika upotovu na kichaa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 25, 'Ni yeye tu aliyeteremshiwa huo ukumbusho kati yetu sote? Bali huyu ni mwongo mno, mshari mkubwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 26, 'Kesho watajua ni nani huyo mwongo mno, mshari mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 27, 'Hakika Sisi tutawatumia ngamia jike ili kuwajaribu, basi watazame vyema tu na ustahamili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 28, 'Na waambie kwamba hakika maji yatagawanywa baina yao; kila sehemu ya maji itahudhuriwa na aliyehusika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 29, 'Basi wakamwita mtu wao akaja akamchinja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 30, 'Basi ilikuwaje adhabu yangu na maonyo yangu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 31, 'Hakika Sisi tuliwatumia ukelele mmoja tu, wakawa kama mabuwa ya kujengea ua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 32, 'Na bila ya shaka Sisi tumeifanya Qur-ani iwe nyepesi kwa kukumbuka, lakini yupo akumbukaye?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 33, 'Kaumu Lut''i nao waliwakadhibisha Waonyaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 34, 'Hakika Sisi tukawatumia kimbunga cha vijiwe, isipokuwa wafuasi wa Lut''i. Hao tuliwaokoa karibu na alfajiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 35, 'Kwa neema inayotoka kwetu. Hivyo ndivyo tumlipavyo anayeshukuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 36, 'Na hakika yeye aliwaonya adhabu yetu; lakini wao waliyatilia shaka hayo maonyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 37, 'Na walimtaka awape wageni wake. Tukayapofua macho yao, na tukawaambia: ''Onjeni basi adhabu na maonyo yangu!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 38, 'Na iliwafikia wakati wa asubuhi adhabu yangu ya kuendelea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 39, 'Basi onjeni adhabu na maonyo yangu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 40, 'Na hakika tumeisahilisha Qur-ani kuikumbuka. Lakini yupo anayekumbuka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 41, 'Na Waonyaji waliwajia watu wa Firauni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 42, 'Walizikadhibisha Ishara zetu zote, nasi tukawashika mshiko wa Mwenye nguvu, Mwenye uwezo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 43, 'Je, makafiri wenu ni bora kuliko hao, au yameandikwa vitabuni kuwa nyinyi hamtiwi makosani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 44, 'Au ndiyo wanasema: ''Sisi ni wengi tutashinda tu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 45, 'Wingi wao huu utashindwa, na wao watasukumwa nyuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 46, 'Bali Saa ya Kiyama ndiyo miadi yao, na Saa hiyo ni nzito zaidi na chungu zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 47, 'Hakika wakosefu wamo katika upotovu na wazimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 48, 'Siku watakapokokotwa Motoni kifudifudi waambiwe: ''Onjeni mguso wa Saqar!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 49, 'Kwa hakika Sisi tumekiumba kila kitu kwa kipimo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 50, 'Na amri yetu haikuwa ila ni moja tu, kama kupepesa jicho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 51, 'Na bila ya shaka tumekwisha waangamiza wenzenu. Lakini yupo anayekumbuka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 52, 'Na kila jambo walilolifanya limo vitabuni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 53, 'Na kila kidogo na kikubwa kimeandikwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 54, 'Hakika wacha Mungu watakuwa katika Mabustani na mito.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 55, 'Katika mahali pa kukalia pa haki kwa Mfalme Mwenye uweza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 1, 'Arrah''man (Mwingi wa Rehema).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 2, 'Amefundisha Qur-ani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 3, 'Amemuumba mwanadamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 4, 'Akamfundisha kubaini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 5, 'Jua na mwezi huenda kwa hesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 6, 'Na mimea yenye kutambaa, na miti, inanyenyekea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 7, 'Na mbingu ameziinua, na ameweka mizani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 8, 'Ili msidhulumu katika mizani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 9, 'Na wekeni mizani kwa haki, wala msipunje katika mizani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 10, 'Na ardhi ameiweka kwa ajili ya viumbe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 11, 'Humo yamo matunda na mitende yenye mafumba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 12, 'Na nafaka zenye makapi, na rehani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 13, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 14, 'Amemuumba mtu kwa udongo wa kinamo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 15, 'Na akawaumba majini kwa ulimi wa moto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 16, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 17, 'Mola Mlezi wa mashariki mbili na wa magharibi mbili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 18, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 19, 'Anaziendesha bahari mbili zikutane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 20, 'Baina yake kipo kizuizi, zisiingiliane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 21, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 22, 'Katika hizo bahari mbili zinatoka lulu na marijani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 23, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 24, 'Na ni vyake Yeye hivi viendavyo baharini vilivyoundwa kama milima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 25, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 26, 'Kila kilichoko juu yake kitatoweka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 27, 'Na utabakia uso wa Mola wako Mlezi, wenye utukufu na ukarimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 28, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 29, 'Vinamwomba Yeye vilivyo katika mbingu na ardhi. Kila siku Yeye yumo katika mambo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 30, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 31, 'Tutakufanyieni hesabu enyi makundi mawili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 32, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 33, 'Enyi makundi ya majini na watu! Mkiweza kupenya kwenye mbingu na ardhi, basi penyeni! Hamtapenya ila kwa kupewa mamlaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 34, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 35, 'Mtatumiwa muwako wa moto na shaba; wala hamtashinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 36, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 37, 'Itakapopasuka mbingu ikawa nyekundu kama mafuta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 38, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 39, 'Basi Siku hiyo hataulizwa dhambi zake mtu wala jini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 40, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 41, 'Watajuulikana wahalifu kwa alama zao, basi watashikwa kwa nywele zao za utosini na kwa miguu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 42, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 43, 'Hii ndiyo Jahannamu ambayo wahalifu walikuwa wakiikanusha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 44, 'Watakuwa wakizunguka baina ya hiyo na maji ya moto yanayochemka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 45, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 46, 'Na mwenye kuogopa kusimamishwa mbele ya Mola wake Mlezi atapata Bustani mbili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 47, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 48, 'Bustani zenye matawi yaliyotanda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 49, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 50, 'Ndani yake zimo chemichemi mbili zinazopita.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 51, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 52, 'Humo katika kila matunda zimo namna mbili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 53, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 54, 'Wawe wameegemea matandiko yenye bitana ya hariri nzito; na matunda ya Bustani hizo yapo karibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 55, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 56, 'Humo watakuwamo wanawake watulizao macho yao; hajawagusa mtu kabla yao wala jini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 57, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 58, 'Kama kwamba wao ni yakuti na marijani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 59, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 60, 'Ati yaweza kuwa malipo ya ihsani ila ihsani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 61, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 62, 'Na zaidi ya hizo zipo Bustani nyingine mbili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 63, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 64, 'Za kijani kibivu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 65, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 66, 'Na chemichemi mbili zinazofurika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 67, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 68, 'Imo humo miti ya matunda, na mitende na mikomamanga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 69, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 70, 'Humo wamo wanawake wema wazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 71, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 72, 'Wanawake wazuri wanaotawishwa katika mahema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 73, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 74, 'Hajawagusa mtu wala jini kabla yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 75, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 76, 'Wameegemea juu ya matakia ya kijani na mazulia mazuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 77, 'Basi ni ipi katika neema za Mola wenu Mlezi mnayoikanusha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 78, 'Limetukuka jina la Mola wako Mlezi Mwenye utukufu na ukarimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 1, 'Litakapotokea hilo Tukio.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 2, 'Hapana cha kukanusha kutokea kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 3, 'Literemshalo linyanyualo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 4, 'Itakapotikiswa ardhi kwa mtikiso.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 5, 'Na milima itakaposagwasagwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 6, 'Basi iwe mavumbi yanayopeperushwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 7, 'Na nyinyi mtakuwa namna tatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 8, 'Basi watakuwepo wa kuliani; je, ni wepi wa kuliani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 9, 'Na wa kushotoni; je, ni wepi wa kushotoni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 10, 'Na wa mbele watakuwa mbele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 11, 'Hao ndio watakaowekwa karibu (na Mwenyezi Mungu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 12, 'Katika Bustani zenye neema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 13, 'Fungu kubwa katika wa mwanzo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 14, 'Na wachache katika wa mwisho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 15, 'Watakuwa juu ya viti vya fakhari vilivyotonewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 16, 'Wakiviegemea wakielekeana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 17, 'Wakitumikiwa na wavulana wa ujana wa milele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 18, 'Kwa vikombe na mabirika na bilauri za vinywaji kutoka chemchemi safi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 19, 'Hawataumwa kichwa kwa vinywaji hivyo wala hawatoleweshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 20, 'Na matunda wayapendayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 21, 'Na nyama za ndege kama wanavyotamani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 22, 'Na Mahurulaini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 23, 'Walio kama mfano wa lulu zilizohifadhiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 24, 'Ni malipo kwa waliyokuwa wakiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 25, 'Humo hawatasikia porojo wala maneno ya dhambi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 26, 'Isipokuwa maneno ya Salama, Salama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 27, 'Na wale wa mkono wa kulia, ni yepi yatakuwa ya wa kuliani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 28, 'Katika mikunazi isiyo na miba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 29, 'Na migomba iliyopangiliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 30, 'Na kivuli kilichotanda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 31, 'Na maji yanayomiminika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 32, 'Na matunda mengi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 33, 'Hayatindikii wala hayakatazwi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 34, 'Na matandiko yaliyonyanyuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 35, 'Hakika Sisi tutawaumba (Mahurulaini) upya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 36, 'Na tutawafanya vijana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 37, 'Wanapendana na waume zao, hirimu moja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 38, 'Kwa ajili ya watu wa kuliani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 39, 'Fungu kubwa katika wa mwanzo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 40, 'Na fungu kubwa katika wa mwisho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 41, 'Na watu wa kushotoni; je ni yepi ya wa kushotoni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 42, 'Katika upepo wa moto, na maji yanayochemka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 43, 'Na kivuli cha moshi mweusi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 44, 'Si baridi wala cha kustarehesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 45, 'Hakika hao walikuwa kabla ya haya wakiishi maisha ya anasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 46, 'Na walikuwa wakiendelea tu kufanya madhambi makubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 47, 'Na walikuwa wakisema: ''Tutakapokufa na tukawa udongo na mafupa, ati ndiyo tutafufuliwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 48, 'Au baba zetu wa zamani?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 49, 'Sema: ''Hakika wa zamani na wa mwisho.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 50, 'Bila ya shaka watakusanywa kwa wakati wa siku maalumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 51, 'Kisha nyinyi, mliopotea, mnaokanusha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 52, 'Kwa yakini mtakula mti wa Zaqqumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 53, 'Na kwa mti huo mtajaza matumbo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 54, 'Na juu yake mtakunywa maji yanayochemka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 55, 'Tena mtakunywa kama wanavyokunywa ngamia wenye kiu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 56, 'Hiyo ndiyo karamu yao ya kuwakaribisha Siku ya Malipo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 57, 'Sisi tumekuumbeni; basi hamsadiki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 58, 'Je, mnaiona mbegu ya uzazi mnayoidondokesha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 59, 'Je, mnaiumba nyinyi, au ni Sisi ndio Waumbaji?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 60, 'Sisi tumekuwekeeni mauti; na wala Sisi hatushindwi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 61, 'Kuwaleta wengine badala yenu na kukuumbeni nyinyi kwa umbo msilolijua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 62, 'Na bila ya shaka mlikwisha jua umbo la kwanza, basi kwa nini hamkumbuki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 63, 'Je, mnaona hivyo mnavyovipanda?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 64, 'Je, ni nyinyi mnayoyaotesha au ni Sisi ndio wenye kuotesha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 65, 'Tungelitaka, tungeliyafanya yakawa mapepe, mkabaki mnastaajabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 66, 'Mkisema: ''Hakika sisi tumegharimika.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 67, 'Bali sisi tumenyimwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 68, 'Je, mnayaona maji mnayoyanywa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 69, 'Je, ni nyinyi mnaoyateremsha kutoka mawinguni au ni Sisi ndio wenye kuyateremsha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 70, 'Tungelipenda, tungeliyafanya ya chumvi. Basi mbona hamshukuru?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 71, 'Je, mnauona moto mnaouwasha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 72, 'Ni nyinyi mliouumba mti wake au Sisi ndio Waumbaji?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 73, 'Sisi tumeufanya uwe ni ukumbusho na manufaa kwa walioko nyikani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 74, 'Basi litakase jina la Mola wako Mlezi aliye Mkuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 75, 'Basi ninaapa kwa maanguko ya nyota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 76, 'Na hakika bila ya shaka hiki ni kiapo kikubwa, laiti mngelijua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 77, 'Hakika hii bila ya shaka ni Qur-ani Tukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 78, 'Katika Kitabu kilichohifadhiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 79, 'Hapana akigusaye ila waliotakaswa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 80, 'Ni uteremsho unaotoka kwa Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 81, 'Ni maneno haya ndiyo nyinyi mnayapuuza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 82, 'Na badala ya kushukuru kwa riziki yenu mnafanya kuwa mnakadhibisha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 83, 'Yawaje basi itakapofika roho kwenye koo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 84, 'Na nyinyi wakati huo mnatazama!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 85, 'Na Sisi tuko karibu zaidi naye kuliko nyinyi, lakini hamuoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 86, 'Na lau kuwa nyinyi hamtalipwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 87, 'Kwa nini hamuirudishi hiyo roho, ikiwa nyinyi mnasema kweli?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 88, 'Kwa hivyo, akiwa miongoni mwa wale walio karibu na Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 89, 'Basi ni raha, na manukato, na Bustani zenye neema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 90, 'Na akiwa katika wale wa upande wa kulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 91, 'Basi ni Salamu kwako uliye miongoni mwa wale wa upande wa kulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 92, 'Na ama akiwa katika wale waliokadhibisha, wapotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 93, 'Basi karamu ya makaribisho yake ni maji yanayochemka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 94, 'Na kutiwa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 95, 'Hakika hii ndiyo haki yenye yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 96, 'Basi litakase jina la Mola wako Mlezi aliye Mkuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 1, 'Kinamsabihi kumtakasa Mwenyezi Mungu kila kilichomo ndani ya mbingu na ardhi. Na Yeye ndiye Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 2, 'Yeye ndiye Mwenye ufalme wa mbingu na ardhi. Anahuisha na anafisha. Na Yeye ni Mwenye uwezo mno wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 3, 'Yeye ndiye wa Mwanzo na ndiye wa Mwisho, naye ndiye wa Dhahiri na wa Siri, naye ndiye ajuaye zaidi kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 4, 'Yeye ndiye aliyeziumba mbingu na ardhi katika siku sita; kisha akainuka akawa juu ya Kitu cha Enzi. Anayajua yanayoingia katika ardhi na yanayotoka humo, na yanayoteremka kutoka mbinguni, na yanayopanda humo. Naye yu pamoja nanyi popote mlipo. Na Mwenyezi Mungu ni Mwenye kuyaona mno mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 5, 'Ufalme wa mbingu na ardhi ni wake. Na mambo yote yanarejeshwa kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 6, 'Anaingiza usiku katika mchana, na anaingiza mchana katika usiku. Na Yeye ni Mwenye kuyajua mno yaliyomo vifuani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 7, 'Muaminini Mwenyezi Mungu na Mtume wake; na toeni katika alivyokufanyeni nyinyi kuwa ni waangalizi wake. Basi wale walioamini miongoni mwenu, na wakatoa, wana malipo makubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 8, 'Na mna nini hata hamumuamini Mwenyezi Mungu na hali Mtume anakuiteni mumuamini Mola wenu Mlezi? Naye amekwisha chukua ahadi yenu, ikiwa nyinyi ni Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 9, 'Yeye ndiye anayemteremshia mja wake Aya zinazobainisha wazi ili akutoeni gizani hadi kwenye nuru. Na hakika Mwenyezi Mungu kwenu ni Mpole mno, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 10, 'Na mna nini hata hamtoi katika Njia ya Mwenyezi Mungu, na hali urithi wa mbingu na ardhi ni wa Mwenyezi Mungu? Hawawi sawa miongoni waliotoa kabla ya Ushindi na wakapigana vita. Hao wana daraja kubwa zaidi kuliko wale ambao walitoa baadaye na wakapigana. Na wote hao Mwenyezi Mungu amewaahidia wema. Na Mwenyezi Mungu anazo habari za yote mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 11, 'Ni nani atakayemkopesha Mwenyezi Mungu mkopo mwema, ili amrudishie maradufu, na apate malipo ya ukarimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 12, 'Siku utakapowaona Waumini wanaume na Waumini wanawake, nuru yao iko mbele yao, na kuliani kwao: Furaha yenu leo - Bustani zipitazo mito kati yake, mtakaa humo milele. Huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 13, 'Siku wanafiki wanaume na wanafiki wanawake watakapowaambia wale walioamini: ''Tungojeni ili tupate mwangaza katika nuru yenu.'' Waambiwe: ''Rejeeni nyuma yenu mkaitafute nuru!'' Kisha utatiwa baina yao ukuta wenye mlango - ndani yake mna rehema, na nje upande wake wa mbele kuna adhabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 14, 'Watawaita wawaambie: ''Kwani hatukuwa pamoja nanyi?'' Watawaambia: ''Ndiyo, lakini mlijifitini wenyewe, na mkatazamia mabaya (Waumini), na mkatia shaka, na matamanio ya nafsi zenu yakakudanganyeni mpaka ilipokuja amri ya Mwenyezi Mungu, na mdanganyifu yule[1] akakudanganyeni msimfuate Mwenyezi Mungu.', '[1] Yaani Shetani.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 15, 'Basi leo haitachukuliwa kwenu fidia, wala kwa wale waliokufuru. Makazi yenu ni Motoni, ndio bora kwenu; na ni marejeo maovu yalioje!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 16, 'Je, wakati haujafika bado kwa wale walioamini zikanyenyekea nyoyo zao kwa kumkumbuka Mwenyezi Mungu na haki iliyoteremka? Wala wasiwe kama wale waliopewa Kitabu kabla yao, muda wao ukawa mrefu, kwa hivyo nyoyo zao zikawa ngumu, na wengi wao ni wapotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 17, 'Jueni kwamba Mwenyezi Mungu huifufua ardhi baada ya kufa kwake. Hakika tumekubainishieni Ishara ili mpate kuzingatia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 18, 'Kwa hakika wanaume wanaotoa sadaka, na wanawake wanaotoa sadaka, na wakamkopesha Mwenyezi Mungu mkopo mwema, watazidishiwa maradufu na watapata malipo ya ukarimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 19, 'Na wale waliomuamini Mwenyezi Mungu na Mitume wake, hao ndio Masidiqi (wakweli zaidi) na Mashahidi mbele ya Mola wao Mlezi. Wao watapata malipo yao na nuru yao. Na wale waliokufuru na wakakadhibisha Ishara zetu, hao ndio wana Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 20, 'Jueni ya kwamba maisha ya dunia ni mchezo, na pumbao, na pambo, na kujifahirisha baina yenu na kushindana kwa wingi wa mali na watoto. Mfano wake ni kama mvua ambayo huwafurahisha wakulima mimea yake, kisha hunyauka ukayaona yamepiga manjano kisha yakawa mabua. Na akhera kuna adhabu kali na maghfira kutoka kwa Mwenyezi Mungu na radhi. Na maisha ya dunia si chochote ila ni starehe ya udanganyifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 21, 'Kimbilieni msamaha wa Mola wenu Mlezi, na Bustani ya mbinguni ambayo upana wake ni kama upana wa mbingu na ardhi, iliyoandaliwa kwa ajili ya wale waliomuamini Mwenyezi Mungu na Mitume wake. Hiyo ndiyo fadhila ya Mwenyezi Mungu, humpa amtakaye. Na Mwenyezi Mungu ni Mwenye fadhila kuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 22, 'Hautokei msiba katika ardhi wala katika nafsi zenu ila umekwishaandikwa katika Kitabu kabla ni mepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 23, 'Ili msihuzunike kwa kilichokupoteeni, wala msijitape kwa alichokupeni. Na Mwenyezi Mungu hampendi kila anayejivuna akajifahirisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 24, 'Ambao wanafanya ubahili, na wanaamrisha watu wafanye ubahili. Na anayegeuka, basi Mwenyezi Mungu ndiye Mwenye kujitosha, Msifiwa mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 25, 'Kwa hakika tuliwatuma Mitume wetu na ishara waziwazi, na tukateremsha Kitabu pamoja nao na Mizani, ili watu wasimamie uadilifu, na tumeteremsha chuma chenye nguvu nyingi na manufaa kwa watu, na ili Mwenyezi Mungu amjue anayemnusuru Yeye na Mitume wake kwa ghaibu. Hakika Mwenyezi Mungu ni Mwenye nguvu, Mwenye kushinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 26, 'Na bila ya shaka tulimtuma Nuhu na Ibrahim, na tukaweka katika dhuriya zao Unabii na Kitabu. Basi wapo miongoni mwao walioongoka, na wengi katika wao ni wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 27, 'Tena tukafuatisha nyuma yao Mitume wengine, na tukamfuatisha Isa mwana wa Mariamu, na tukampa Injili. Na tukaweka katika nyoyo za wale waliomfuata upole na rehema. Na umonaki (utawa wa mapadri) wameuzua wao. Sisi hatukuwaandikia hayo, ila kutafuta radhi za Mwenyezi Mungu. Lakini hawakuufuata inavyotakiwa kuufuata. Basi wale walioamini katika wao tuliwapa ujira wao. Na wengi wao ni wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 28, 'Enyi mlioamini! Mcheni Mwenyezi Mungu, na muaminini Mtume wake, atakupeni sehemu mbili katika rehema yake, na atakufanyieni nuru ya kwenda nayo, na atakusameheni. Na Mwenyezi Mungu ni Mwenye kusamehe mno, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 29, 'Ili watu wa Kitabu wajue kwamba wao hawana uwezo wowote juu ya fadhila za Mwenyezi Mungu. Na kwamba fadhila zote zimo mikononi mwa Mwenyezi Mungu. Humpa amtakaye. Na Mwenyezi Mungu ndiye Mwenye fadhila kuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 1, 'Hakika Mwenyezi Mungu amekwishasikia usemi wa mwanamke anayejadiliana nawe juu ya mumewe, na anamlalamikia Mwenyezi Mungu. Na Mwenyezi Mungu anayasikia majibizano yenu. Hakika Mwenyezi Mungu ni Mwenye kusikia mno, Mwenye kuona zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 2, 'Wale miongoni mwenu wanaowasawazisha wake zao na mama zao, hao si mama zao. Hawakuwa mama zao ila wale waliowazaa. Na hakika hao wanasema neno ovu mno, na la uongo. Na Mwenyezi Mungu ni Mwenye kufuta dhambi mno, Mwenye kusamehe zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 3, 'Na wale wanaojitenga na wake zao, kisha wakarudia katika yale waliyoyasema, basi wamkomboe mtumwa kabla hawajagusana. Mnapewa maonyo kwa hayo. Na Mwenyezi Mungu anayajua yote mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 4, 'Na asiyepata mtumwa kumkomboa, basi na afunge saumu miezi miwili mfululizo kabla hawajagusana. Na asiyeweza hayo, basi awalishe masikini sitini. Hayo ni hivyo ili mumuamini Mwenyezi Mungu na Mtume wake. Na hiyo ndiyo mipaka ya Mwenyezi Mungu. Na makafiri watapata adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 5, 'Hakika wanaopinzana na Mwenyezi Mungu na Mtume wake, watadhalilishwa kama walivyodhalilishwa wale waliokuwa kabla yao. Na tulikwishateremsha Ishara zilizo wazi. Na makafiri watapata adhabu ya kufedhehesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 6, 'Siku atakapowafufua Mwenyezi Mungu, na awaambie yale waliyoyatenda. Mwenyezi Mungu ameyadhibiti, na wao wameyasahau! Na Mwenyezi Mungu ni Mwenye kushuhudia kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 7, 'Kwani huoni kwamba Mwenyezi Mungu anajua vilivyo katika mbingu na vilivyo katika ardhi? Hauwi mnong''ono wa watu watatu ila Yeye huwa ni wanne wao, wala wa watano ila Yeye huwa ni wa sita wao. Wala wa wachache kuliko hao, wala walio wengi zaidi, ila Yeye yu pamoja nao popote pale walipo. Kisha Siku ya Kiyama atawaambia waliyoyatenda. Hakika Mwenyezi Mungu anajua zaidi kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 8, 'Kwani huwaoni wale waliokatazwa kunong''onezana, kisha wakayarudia yale yale waliyokatazwa, na wakanong''ona juu ya mambo ya dhambi, na ya uadui, na ya kumuasi Mtume? Na wakikujia, hukuamkua sivyo anavyokuamkua Mwenyezi Mungu. Na husema katika nafsi zao: ''Mbona Mwenyezi Mungu hatuadhibu kwa haya tuyasemayo?'' Basi Jahannamu itawatosha; wataingia humo! Na hayo ndiyo marejeo maovu yaliyoje!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 9, 'Enyi mlioamini! Mnaponong''ona, msinong''one kwa sababu ya mambo ya madhambi, na uadui, na kumuasi Mtume. Bali nong''onezeni kwa kutenda mema na kuacha maovu. Na mcheni Mwenyezi Mungu ambaye kwake mtakusanywa nyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 10, 'Kwa hakika minong''ono hiyo inatokana na Shetani ili awahuzunishe wale walioamini, na wala haitawadhuru chochote ila kwa idhini ya Mwenyezi Mungu. Na juu ya Mwenyezi Mungu tu ndio wategemee Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 11, 'Enyi mlioamini! Mkiambiwa: Fanyeni nafasi katika mabaraza, basi fanyeni nafasi. Na Mwenyezi Mungu atakufanyieni nyinyi nafasi. Na mkiambiwa: "Ondokeni", basi ondokeni. Mwenyezi Mungu atawainua wale walioamini miongoni mwenu, na wale waliopewa elimu daraja za juu. Na Mwenyezi Mungu anazo habari za mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 12, 'Enyi mlioamini! Mnaposema siri na Mtume, basi tangulizeni sadaka kabla ya kusemezana kwenu. Hiyo ni heri kwenu na usafi zaidi. Na ikiwa hamkupata cha kutoa, basi Mwenyezi Mungu ni Mwenye kusamehe mno, Mwenye kurehemu zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 13, 'Mnachelea kutanguliza hiyo sadaka kabla ya kusemezana kwenu kwa siri? Ikiwa hamkufanya hayo, na Mwenyezi Mungu akapokea toba yenu, basi simamisheni Sala, na toeni Zaka, na mtiini Mwenyezi Mungu na Mtume wake. Na Mwenyezi Mungu anazo habari za mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 14, 'Huwaoni wale waliofanya urafiki mwendani na watu ambao Mwenyezi Mungu amewakasirikia? Hao si katika nyinyi, wala si katika wao. Na huapa kwa uongo hali ya kuwa wanajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 15, 'Mwenyezi Mungu amewaandalia adhabu kali. Kwa hakika waliyokuwa wakiyatenda ni maovu kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 16, 'Wamefanya viapo vyao ni ngao, na wakaizuilia Njia ya Mwenyezi Mungu. Basi hao watapata adhabu ya kufedhehesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 17, 'Hayatawafaa kitu mali yao wala watoto wao mbele ya Mwenyezi Mungu. Hao ndio watu wa Motoni. Humo watadumu milele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 18, 'Siku atakayowafufua Mwenyezi Mungu wote, wamuapie kama wanavyokuapieni nyinyi. Na watadhani kuwa wamepata kitu! Kwa hakika hao ndio waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 19, 'Shetani amewatawala na akawasahaulisha kumkumbuka Mwenyezi Mungu. Hao ndio kundi la Shetani. Sikilizeni, hakika kundi la Shetani ndilo lenye kuhasirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 20, 'Hakika wanaompinga Mwenyezi Mungu na Mtume wake, hao ndio miongoni mwa madhalili wa mwisho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 21, 'Mwenyezi Mungu ameandika: Hapana shaka Mimi na Mtume wangu tutashinda. Hakika Mwenyezi Mungu ni Mwenye nguvu, Mwenye kushinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 22, 'Huwakuti watu wanaomuamini Mwenyezi Mungu na Siku ya Mwisho kuwa wanawapenda wanaompinga Mwenyezi Mungu na Mtume wake, hata wakiwa ni baba zao, au watoto wao, au ndugu zao, au jamaa zao. Hao ameandika katika nyoyo zao Imani, na amewapa nguvu kwa Roho itokayo kwake. Na atawaingiza katika Mabustani yapitayo mito kati yake. Humo watakaa daima. Mwenyezi Mungu awe radhi nao, na wao wawe radhi naye. Hao ndio Hizbullahi (Kundi la Mwenyezi Mungu). Hakika Kundi la Mwenyezi Mungu ndilo lenye kufanikiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 1, 'Vinamtakasa Mwenyezi Mungu vilivyo katika mbingu na vilivyo katika ardhi. Naye ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 2, 'Yeye ndiye aliyewatoa wale waliokufuru miongoni mwa Watu wa Kitabu katika nyumba zao wakati wa uhamisho wa kwanza. Hamkudhani kuwa watatoka, nao walidhani kuwa ngome zao zitawalinda dhidi ya Mwenyezi Mungu. Lakini Mwenyezi Mungu akawafikia kwa mahali ambako hawakutazamia, na akatia woga mkubwa katika nyoyo zao. Wakawa wanazibomoa nyumba zao kwa mikono yao na mikono ya Waumini. Basi zingatieni enyi wenye macho!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 3, 'Na lau kuwa Mwenyezi Mungu asingeliwaandikia kutoka, angeliwaadhibu katika dunia. Na katika Akhera watapata adhabu ya Moto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 4, 'Hayo ni kwa sababu walimpinga Mwenyezi Mungu na Mtume wake. Na mwenye kumpinga Mwenyezi Mungu, basi hakika Mwenyezi Mungu ni Mkali wa kuadhibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 5, 'Mtende wowote mlioukata au mliouacha umesimama vile vile juu ya mashina yake, basi ni kwa idhini ya Mwenyezi Mungu, na ili awahizi wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 6, 'Na mali aliyoileta Mwenyezi Mungu kwa Mtume wake kutoka kwao hamkuikimbilia mbio kwa farasi wala ngamia. Lakini Mwenyezi Mungu huwapa mamlaka Mitume wake juu ya wowote awatakao. Na Mwenyezi Mungu ni Muweza mno juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 7, 'Mali aliyoileta Mwenyezi Mungu kwa Mtume wake kutoka kwa watu wa hivi vijiji ni kwa ajili ya Mwenyezi Mungu, na kwa ajili ya Mtume, na jamaa, na mayatima, na masikini, na msafiri, ili isiwe ikizunguka baina ya matajiri tu miongoni mwenu. Na anachokupeni Mtume, kichukueni. Na anachokukatazeni, jiepusheni nacho. Na mcheni Mwenyezi Mungu. Hakika Mwenyezi Mungu ni Mkali wa kuadhibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 8, 'Wapewe mafakiri Wahajiri waliotolewa majumbani mwao na mali yao kwa ajili ya kutafuta fadhila kutoka kwa Mwenyezi Mungu na radhi zake, na wanamsaidia Mwenyezi Mungu na Mtume wake. Hao ndio wakweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 9, 'Na wale walio na maskani zao na Imani yao kabla yao, wanawapenda wale waliohamia kwao, wala hawaoni choyo katika vifua vyao kwa walivyopewa (Wahajiri), bali wanawapendelea kuliko nafsi zao, ingawa wao wenyewe ni wahitaji. Na mwenye kuepushwa uchoyo wa nafsi yake, basi hao ndio wenye kufanikiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 10, 'Na wale waliokuja baada yao wanasema: Mola wetu Mlezi! Tughufirie sisi na ndugu zetu waliotutangulia kwa Imani, wala usijaalie ndani ya nyoyo zetu undani kwa walioamini. Mola wetu Mlezi! Hakika Wewe ni Mpole na Mwenye kurehemu mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 11, 'Huwaoni wale wanaofanya unafiki wanawaambia ndugu zao waliokufuru katika Watu wa Kitabu: Mkitolewa, na sisi lazima tutatoka pamoja nanyi, wala hatutamtii yeyote kabisa dhidi yenu. Na mkipigwa vita, lazima tutakusaidieni. Na Mwenyezi Mungu anashuhudia kuwa hao hakika bila ya shaka ni waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 12, 'Pindi wakitolewa, hawatatoka pamoja nao. Na wakipigwa vita, hawatawasaidia. Na kama wakiwasaidia, basi watageuza mno migongo; kisha hawatanusuriwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 13, 'Hakika nyinyi ni kitisho zaidi katika vifua vyao kuliko Mwenyezi Mungu. Hayo ni kwa kuwa hao ni watu wasiofahamu kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 14, 'Hawatapigana nanyi kwa mkusanyiko isipokuwa katika vijiji vilivyoimarishwa kwa ngome, au nyuma ya kuta. Wao kwa wao vita vyao ni vikali. Utawadhania kuwa wako pamoja, kumbe nyoyo zao ni mbali mbali. Hayo ni kwa kuwa wao ni watu wasiotumia akili.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 15, 'Ni kama mfano wa wale waliokuwa kabla yao hivi karibuni, walionja uovu wa mambo yao. Nao watapata adhabu iliyo chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 16, 'Ni kama mfano wa Shetani anapomwambia mtu: ''Kufuru.'' Na akikufuru, humwambia: ''Hakika mimi niko mbali zaidi nawe. Hakika mimi namwogopa Mwenyezi Mungu, Mola Mlezi wa walimwengu wote.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 17, 'Basi ikawa mwisho wa wote wawili hao ni kuingia Motoni, wadumu humo daima; na hayo ndiyo malipo ya madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 18, 'Enyi mlioamini! Mcheni Mwenyezi Mungu, na kila nafsi iangalie inayoyatanguliza kwa ajili ya Kesho. Na mcheni Mwenyezi Mungu. Hakika Mwenyezi Mungu anazo habari ya mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 19, 'Wala msiwe kama wale waliomsahau Mwenyezi Mungu, na Yeye akawasahaulisha nafsi zao. Hao ndio wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 20, 'Hawawi sawa watu wa Motoni na watu wa Bustani ya mbinguni. Watu wa Bustani ya mbinguni ndio wenye kufuzu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 21, 'Lau kuwa tumeiteremsha hii Qur-ani juu ya mlima, basi bila ya shaka ungeliuona ukinyenyekea, ukipasuka kwa kumhofu Mwenyezi Mungu. Na hiyo mifano tunawapigia watu ili wafikiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 22, 'Yeye ndiye Mwenyezi Mungu, ambaye hapana mungu isipokuwa Yeye tu. Mwenye kuyajua yaliyofichikana na yanayoonekana. Yeye ndiye Mwingi wa rehema, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 23, 'Yeye ndiye Mwenyezi Mungu ambaye hapana mungu isipokuwa Yeye tu. Mfalme, Mtakatifu, Mwenye salama, Mtoaji wa amani, Mwenye kuyaendesha Mwenyewe mambo yake, Mwenye nguvu, anayefanya analolitaka, Mkubwa. Ametakasika Mwenyezi Mungu na hayo wanayomshirikisha nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 24, 'Yeye ndiye Mwenyezi Mungu, Muumbaji, Mtengenezaji, Mtia sura, Mwenye majina mazuri kabisa. Kila kilioko katika mbingu na ardhi kinamtakasa, naye ni Mwenye kushinda, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 1, 'Enyi mlioamini! Msiwafanye adui zangu na adui zenu kuwa marafiki mkiwapa mapenzi, na hali wao wamekwisha ikataa haki iliyokujieni, wakamfukuza Mtume na nyinyi kwa sababu mnamuamini Mwenyezi Mungu, Mola Mlezi wenu. Mnapotoka kwa ajili ya Jihadi katika Njia yangu na kutafuta radhi yangu, mnafanya urafiki nao kwa siri, na Mimi nayajua mnayoyaficha na mnayodhihirisha. Na mwenye kufanya hayo kati yenu, basi ameipotea njia ya sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 2, 'Wakikuwezeni, wanakuwa maadui zenu, na wanakukunjulieni mikono yao na ndimi zao kwa uovu. Na wanapenda muwe makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 3, 'Hawatakufaeni jamaa zenu, wala watoto wenu Siku ya Kiyama. Mwenyezi Mungu atapambanua baina yenu, na Mwenyezi Mungu anayaona mno mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 4, 'Hakika nyinyi mna mfano mzuri kwenu kwa Ibrahim na wale waliokuwa pamoja naye, walipowaambia watu wao: Hakika sisi tumejitenga nanyi na hayo mnayoyaabudu badala ya Mwenyezi Mungu. Tunakukataeni; na umekwisha dhihiri uadui na chuki baina yetu na nyinyi mpaka mtakapomuamini Mwenyezi Mungu peke yake. Isipokuwa kauli ya Ibrahim kumwambia baba yake: Hakika nitakuombea msamaha, wala similiki chochote kwa ajili yako mbele ya Mwenyezi Mungu. Mola wetu Mlezi! Juu yako tumetegemea, na kwako tumeelekea, na kwako ndiyo marejeo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 5, 'Mola wetu Mlezi! Usitufanyie mtihani kwa waliokufuru. Na tusamehe, Mola wetu Mlezi. Hakika Wewe ndiye Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 6, 'Kwa yakini umekuwa mfano mzuri kwenu katika mwendo wao, kwa anayemtarajia Mwenyezi Mungu na Siku ya Mwisho. Na mwenye kugeuka, basi hakika Mwenyezi Mungu ni Mwenye kujitosha, Msifiwa mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 7, 'Asaa Mwenyezi Mungu akatia mapenzi baina yenu na hao maadui zenu, na Mwenyezi Mungu ni Mweza, na Mwenyezi Mungu ni Mwenye kusamehe zaidi, Mwenye kurehemu mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 8, 'Mwenyezi Mungu hakukatazini kuwafanyia wema na uadilifu wale ambao hawakukupigeni vita, wala hawakukutoeni makwenu. Hakika Mwenyezi Mungu huwapenda wafanyao uadilifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 9, 'Hakika Mwenyezi Mungu anakukatazeni kufanya urafiki wa kusaidiana nao, na wale waliokupigeni vita kwa sababu ya dini, na wakakutoeni makwenu, na wakasaidia katika kufukuzwa kwenu. Na wanaowafanya hao marafiki, basi hao ndio madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 10, 'Enyi mlioamini! Wakikujilieni wanawake Waumini waliohama, basi wafanyieni mtihani - Mwenyezi Mungu ndiye Mwenye kujua zaidi Imani yao. Mkiwa mnawajua kuwa ni Waumini, basi msiwarudishe kwa makafiri. Wanawake hao si halali kwa hao makafiri, wala hao makafiri hawahalalikii wanawake Waumini. Na wapeni hao wanaume mahari waliotoa. Wala hapana makosa kwenu kuwaoa mkiwapa mahari yao. Wala msiwaweke wanawake makafiri katika kifungo cha ndoa zenu. Na takeni mlichokitoa, na wao watake walichokitoa. Hiyo ndiyo hukumu ya Mwenyezi Mungu anayokuhukumuni. Na Mwenyezi Mungu ni Mwenye kujua mno, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 11, 'Na akitoroka yeyote katika wake zenu kwenda kwa makafiri, tena ikatokea mkapata ngawira, basi wapeni waliokimbiwa na wake zao kiasi cha mahari waliyoyatoa. Na mcheni Mwenyezi Mungu ambaye mnamuamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 12, 'Ewe Nabii! Watakapokujia wanawake Waumini wanakuahidi ya kwamba hawatamshirikisha Mwenyezi Mungu na chochote, wala hawataiba, wala hawatazini, wala hawatawaua watoto wao, wala hawataleta uzushi wanaouzua tu wenyewe baina ya mikono yao na miguu yao, wala hawatakuasi katika jambo jema, basi peana nao ahadi, na uwatakie maghfira kwa Mwenyezi Mungu. Hakika Mwenyezi Mungu ni Mwingi wa maghfira, Mwenye kurehemu mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 13, 'Enyi mlioamini! Msiwafanye marafiki wa kusaidiana nao katika watu ambao Mwenyezi Mungu amewakasirikia. Hao wamekwisha kata tamaa ya Akhera, kama wamekwishakata makafiri miongoni mwa watu wa makaburini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 1, 'Vinamtakasa Mwenyezi Mungu vilivyo katika mbingu na katika ardhi. Na Yeye ni Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 2, 'Enyi mlioamini! Kwa nini mnasema msiyoyatenda?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 3, 'Yanachukiza vikubwa mno kwa Mwenyezi Mungu kuwa mnasema msiyoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 4, 'Kwa hakika Mwenyezi Mungu anawapenda wanaopigana katika Njia yake kwa safu kama jengo lililokamatana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 5, 'Na Musa alipowaambia watu wake: ''Enyi watu wangu! Kwa nini mnaniudhi, nanyi mnajua kuwa hakika mimi ni Mtume wa Mwenyezi Mungu niliyetumwa kwenu?'' Walipokengeuka, Mwenyezi Mungu akazipotoa nyoyo zao. Na Mwenyezi Mungu hawaongoi watu wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 6, 'Na Isa mwana wa Mariamu aliposema: Enyi Wana wa Israili! Hakika mimi ni Mtume wa Mwenyezi Mungu kwenu, ninayethibitisha yaliyokuwa kabla yangu katika Taurati, na mwenye kubashiria kuja Mtume atakayekuja baada yangu; jina lake ni Ahmad! Lakini alipowaletea hoja zilizo wazi, walisema: Huu ni uchawi ulio dhahiri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 7, 'Na ni nani mwenye kudhulumu zaidi kuliko yule anayemzulia Mwenyezi Mungu uongo, naye anaitwa kwenye Uislamu? Na Mwenyezi Mungu hawaongoi watu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 8, 'Wanataka kuizima nuru ya Mwenyezi Mungu kwa vinywa vyao. Na Mwenyezi Mungu atakamilisha nuru yake ijapokuwa makafiri watachukia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 9, 'Yeye ndiye aliyemtuma Mtume wake kwa uongofu na Dini ya haki ili ipate kuzishinda dini zote, ijapokuwa washirikina watachukia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 10, 'Enyi mlioamini! Nikuonyesheni biashara itakayokuokoeni na adhabu iliyo chungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 11, 'Muaminini Mwenyezi Mungu na Mtume wake, na piganeni Jihadi katika Njia ya Mwenyezi Mungu kwa mali zenu na nafsi zenu. Haya ni bora kwenu, ikiwa nyinyi mnajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 12, 'Atakusameheni dhambi zenu, na atakutieni katika Mabustani yapitiwayo na mito kati yake, na maskani mazuri mazuri katika Bustani za milele. Huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 13, 'Na kinginecho mkipendacho, nacho ni nusura itokayo kwa Mwenyezi Mungu, na ushindi ulio karibu! Na wabashirieni Waumini!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 14, 'Enyi mlioamini! Kuweni wasaidizi wa Mwenyezi Mungu, kama alivyosema Isa mwana Mariamu kuwaambia wanafunzi wake: ''Ni nani wasaidizi wangu kwa Mwenyezi Mungu?'' Wakasema wanafunzi: ''Sisi ni wasaidizi wa Mwenyezi Mungu!'' Basi kundi moja la Wana wa Israili liliamini, na kundi jingine lilikufuru. Basi tukawaunga mkono wale walioamini dhidi ya maadui zao, wakawa wenye kushinda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 1, 'Vilivyomo mbinguni na vilivyo katika ardhi vinamtakasa Mwenyezi Mungu, Mfalme, Mtakatifu, Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 2, 'Yeye ndiye aliyemtuma Mtume kwenye watu wasiojua kusoma na kuandika, awasomee Aya zake na awatakase, na awafunze Kitabu na hekima, ijapokuwa kabla ya haya walikuwa katika upotovu ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 3, 'Na kwa wengine ambao bado hawajaungana nao. Na Yeye ndiye Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 4, 'Hiyo ni fadhila ya Mwenyezi Mungu anayompa amtakaye. Na Mwenyezi Mungu ni Mwenye fadhila kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 5, 'Mfano wa wale waliobebeshwa Taurati kisha wasiibebe, ni mfano wa punda anayebeba vitabu vikubwa vikubwa. Mfano muovu mno wa watu waliokadhibisha Ishara za Mwenyezi Mungu, na Mwenyezi Mungu hawaongoi watu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 6, 'Sema: Enyi Mayahudi! Ikiwa nyinyi mnadai kuwa ni vipenzi vya Mwenyezi Mungu pasipokuwa watu wengine, basi yatamanini mauti, ikiwa mnasema ukweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 7, 'Wala hawatayatamani kabisa, kwa sababu ya iliyokwisha yatanguliza mikono yao. Na Mwenyezi Mungu anawajua mno madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 8, 'Sema: Hayo mauti mnayoyakimbia, bila ya shaka yatakukuteni. Kisha mtarudishwa kwa Mwenye kujua zaidi yaliyofichikana na yanayoonekana. Hapo atakwambieni mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 9, 'Enyi mlioamini! Ikiadhiniwa kwa ajili ya Sala siku ya Ijumaa, nendeni upesi kwenye utajo wa Mwenyezi Mungu, na wacheni biashara. Hayo ni bora kwenu, lau kama mnajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 10, 'Na itakapokwisha Sala, tawanyikeni katika nchi mtafute fadhila za Mwenyezi Mungu, na mkumbukeni Mwenyezi Mungu kwa wingi ili mpate kufanikiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 11, 'Na wanapoiona biashara au pumbao wanayakimbilia hayo na wakakuacha umesimama. Sema: Yaliyoko kwa Mwenyezi Mungu ni bora kuliko pumbao na biashara. Na Mwenyezi Mungu ni Mbora wa watoa riziki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 1, 'Wanapokujia wanafiki husema: Tunashuhudia ya kuwa wewe ni Mtume wa Mwenyezi Mungu. Na Mwenyezi Mungu anajua kuwa wewe ni Mtume wake, na Mwenyezi Mungu anashuhudia ya kuwa hakika wanafiki ni waongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 2, 'Wamevifanya viapo vyao ni ngao, na wao wakaizuia Njia ya Mwenyezi Mungu. Hakika ni mabaya kabisa waliyokuwa wakiyafanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 3, 'Hayo ni kwa sababu ya kuwa waliamini, kisha wakakufuru; kwa hivyo zikazibwa nyoyo zao. Kwa hivyo hawafahamu lolote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 4, 'Na unapowaona, miili yao inakupendeza, na wakisema, unasikiliza usemi wao. Lakini wao ni kama magogo yaliyoegemezwa. Wao hudhania kila ukelele unaopigwa ni kwa ajili yao. Hao ni maadui; tahadhari nao. Mwenyezi Mungu awaangamizilie mbali! Vipi wanapotoka mbali na haki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 5, 'Na wanapoambiwa: Njooni ili Mtume wa Mwenyezi Mungu akuombeeni maghfira, huvigeuza vichwa vyao, na unawaona wanageuka nao wamejaa kiburi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 6, 'Sawa sawa kwao, ukiwatakia maghfira au hukuwatakia maghfira, Mwenyezi Mungu hatawaghufiria. Hakika Mwenyezi Mungu hawaongoi watu wavukao mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 7, 'Hao ndio wanaosema: Msitoe mali kwa ajili ya walioko kwa Mtume wa Mwenyezi Mungu, ili waondokelee mbali! Na Mwenyezi Mungu ndiye Mwenye hazina za mbingu na ardhi, lakini wanafiki hawafahamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 8, 'Wanasema: Tukirejea Madina, mwenye utukufu zaidi bila ya shaka atamfukuza humo aliye mnyonge. Na Mwenyezi Mungu ndiye Mwenye utukufu, na Mtume wake, na Waumini. Lakini wanafiki hawajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 9, 'Enyi mlioamini! Zisikusahaulisheni mali zenu, wala watoto wenu, kumkumbuka Mwenyezi Mungu. Na wenye kufanya hayo, basi hao ndio waliohasiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 10, 'Na toeni katika tulichokupeni kabla hayajamfikia mmoja wenu mauti, tena hapo akasema: ''Mola wangu Mlezi! Huniakhirishi muda kidogo, nipate kutoa sadaka sana, na niwe katika watu wema?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 11, 'Wala Mwenyezi Mungu hataiakhirisha nafsi yoyote unapofika muda wake. Na Mwenyezi Mungu anazo habari za mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 1, 'Kinamtakasa Mwenyezi Mungu kila kilichomo katika mbingu na katika ardhi. Ufalme ni wake, na sifa njema ni zake. Na Yeye ni Mwenye uweza juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 2, 'Yeye ndiye aliyekuumbeni. Miongoni mwenu yupo aliye kafiri, na yupo aliye Muumini. Na Mwenyezi Mungu anayaona mno mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 3, 'Ameziumba mbingu na ardhi kwa haki, na akakupeni sura, na akazifanya nzuri sura zenu. Na marudio ni kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 4, 'Anajua vilivyo katika mbingu na ardhi, na anajua mnayoyaficha na mnayoyaweka hadharani. Na Mwenyezi Mungu ni Mjuzi wa yaliyomo vifuani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 5, 'Kwani haikukujieni habari ya wale waliokufuru kabla, wakaonja matokeo mabaya ya mambo yao? Na wao wana adhabu iliyo chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 6, 'Hayo ni kwa kuwa Mitume wao walikuwa wakiwajia kwa hoja zilizo wazi, nao wakasema: ʻHivyo binadamu ndio atuongoze?ʼ Basi wakakufuru, na wakageuka upande. Mwenyezi Mungu akawa hana haja nao. Na Mwenyezi Mungu ni Mkwasi, si mhitaji, Msifiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 7, 'Wale waliokufuru wanadai kuwa hawatafufuliwa. Sema: Kwani? Ninaapa kwa Mola wangu Mlezi! Hapana shaka mtafufuliwa, na kisha hapana shaka mtaambiwa mliyoyatenda. Na hayo ni mepesi kwa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 8, 'Basi muaminini Mwenyezi Mungu na Mtume wake, na Nuru tuliyoiteremsha. Na Mwenyezi Mungu anazo habari za mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 9, 'Siku atakayokukusanyeni kwa ajili ya Siku ya Mkusanyiko. Hiyo ni siku ya kupunjana. Na anayemuamini Mwenyezi Mungu na akatenda mema, atamfutia maovu yake, na atamuingiza katika Mabustani ya mbinguni yenye kupitiwa kati yake mito, watadumu humo milele. Huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 10, 'Na wale waliokufuru na wakakadhibisha Ishara zetu, hao ni watu wa Motoni, watadumu humo milele. Na hayo ndiyo marejeo mabaya mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 11, 'Haufiki msiba wowote ila kwa idhini ya Mwenyezi Mungu. Na mwenye kumuamini Mwenyezi Mungu, huuongoa moyo wake. Na Mwenyezi Mungu anajua zaidi kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 12, 'Na mtiini Mwenyezi Mungu, na mtiini Mtume. Mkigeuka, basi hakika juu ya Mtume wetu ni kufikisha (Ujumbe wake) kwa uwazi tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 13, 'Mwenyezi Mungu, hapana mungu isipokuwa Yeye. Na juu ya Mwenyezi Mungu, basi na wategemee Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 14, 'Enyi mlioamini! Hakika miongoni mwa wake zenu na watoto wenu wamo maadui zenu. Basi tahadharini nao. Na mkisamehe, na mkapuuza, na mkaghufiria basi hakika Mwenyezi Mungu ni Mwingi wa maghfira, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 15, 'Hakika mali yenu na watoto wenu ni jaribio. Na kwa Mwenyezi Mungu upo ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 16, 'Basi mcheni Mwenyezi Mungu kama mwezavyo, na sikieni, na tiini, na toeni, itakuwa heri kwa nafsi zenu. Na mwenye kuepushwa na uchoyo wa nafsi yake, basi hao ndio waliofanikiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 17, 'Mkimkopesha Mwenyezi Mungu mkopo mzuri, atakuzidishieni maradufu, na atakusameheni. Na Mwenyezi Mungu ni Mwingi wa shukrani, Mstahamilivu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 18, 'Mwenye kujua siri na dhahiri, Mwenye nguvu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 1, 'Ewe Nabii! Mtakapowapa talaka wanawake, basi wapeni talaka katika wakati wanaoweza kuanza eda zao. Na fanyeni hisabu ya eda. Na mcheni Mwenyezi Mungu, Mola wenu Mlezi. Msiwatoe katika nyumba zao, wala wasitoke wenyewe, ila wakifanya jambo la uchafu ulio wazi. Hiyo ndiyo mipaka ya Mwenyezi Mungu, msiikiuke. Na mwenye kuikiuka mipaka ya Mwenyezi Mungu, basi hakika amejidhulumu nafsi yake. Hujui; labda Mwenyezi Mungu ataleta jambo jingine baada ya haya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 2, 'Basi wanapofikia muda wao, ima warejeeni muwaweke kwa wema, au farikianeni nao kwa wema. Na mshuhudishe mashahidi wawili waadilifu miongoni mwenu. Na simamisheni ushahidi kwa ajili ya Mwenyezi Mungu. Hayo anaaidhiwa kwayo anayemuamini Mwenyezi Mungu na Siku ya Mwisho. Na anayemcha Mwenyezi Mungu, humtengezea njia ya kutokea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 3, 'Na humruzuku kutokea asipotazamia. Na anayemtegemea Mwenyezi Mungu, Yeye humtosha. Hakika Mwenyezi Mungu anatimiza amri yake. Mwenyezi Mungu kajaalia kila kitu na kipimo chake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 4, 'Na wale waliosita hedhi miongoni mwa wanawake wenu, ikiwa mnayo shaka, basi muda wa eda yao ni miezi mitatu, pamoja na ambao hawapati hedhi. Na wenye mimba, eda yao ni mpaka watakapozaa. Na anayemcha Mwenyezi Mungu, Mwenyezi Mungu humfanyia mambo yake kuwa mepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 5, 'Hiyo ni amri ya Mwenyezi Mungu amekuteremshieni. Na anayemcha Mwenyezi Mungu, atamfutia maovu yake, na atampa ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 6, 'Wawekeni humo humo mnamokaa nyinyi kwa kiasi cha pato lenu, wala msiwaletee madhara kwa kuwapa dhiki. Na wakiwa wana mimba, wagharimieni mpaka wajifungue. Na wakikunyonyesheeni, basi wapeni ujira wao, na shaurianeni kwa wema. Na mkiona uzito kati yenu, basi amnyonyeshee mwanamke mwingine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 7, 'Mwenye wasaa atoe kiasi ya wasaa wake, na mwenye dhiki, atoe katika kile ambacho Mwenyezi Mungu alimpa. Mwenyezi Mungu hamjukumishi mtu ila kwa kiasi cha alichompa. Mwenyezi Mungu atajaalia baada ya dhiki faraja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 8, 'Na miji mingapi iliyovunja amri ya Mola wake Mlezi na Mitume wake, basi tuliihisabia hisabu ngumu na tukaiadhibu kwa adhabu kali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 9, 'Basi ikauonja ubaya wa mambo yake; na mwisho wa mambo yao ilikuwa hasara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 10, 'Mwenyezi Mungu aliwaandalia adhabu kali. Basi mcheni Mwenyezi Mungu, enyi wenye akili, mlioamini! Hakika Mwenyezi Mungu amekuteremshieni Ukumbusho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 11, 'Mtume anayekusomeeni Aya za Mwenyezi Mungu zinazobainisha, ili kuwatoa wale walioamini na wakatenda mema kutoka vizani kuwapeleka kwenye nuru. Na mwenye kumuamini Mwenyezi Mungu na akatenda mema, atamwingiza katika Bustani za mbinguni zipitazo mito kati yake, wadumu humo milele. Mwenyezi Mungu amekwisha mpa riziki nzuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 12, 'Mwenyezi Mungu ni yule ambaye ameziumba mbingu saba, na ardhi kwa mfano wa hizo. Amri zake zinashuka baina yake, ili mjue kwamba Mwenyezi Mungu ni Mwenye uweza mno juu ya kila kitu, na kwamba Mwenyezi Mungu amekizingira kila kitu kukijua vilivyo kwa elimu yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 1, 'Ewe Nabii! Kwa nini unaharamisha alichokuhalalishia Mwenyezi Mungu? Unatafuta kuwaridhi wake zako. Na Mwenyezi Mungu ni Mwenye kusamehe mno, Mwingi wa kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 2, 'Hakika Mwenyezi Mungu amekupeni Sheria ya kufungua viapo vyenu, na Mwenyezi Mungu ni Mola wenu. Na Yeye ni Mwenye kujua mno, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 3, 'Na Nabii alipomwambia mmoja wa wake zake jambo la siri. Basi alipolitangaza yule mke, na Mwenyezi Mungu akamdhihirishia Mtume, alimjuvya sehemu na akaacha sehemu nyingine. Alipomwambia hayo, huyo mke akasema: ''Ni nani aliyekwambia haya?'' Mtume akasema: ''Kaniambia Yule ajuaye zaidi, Mwenye habari zote!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 4, 'Kama nyinyi wawili hamtatubia kwa Mwenyezi Mungu, basi nyoyo zenu zimekwishaelekea huko. Na mkisaidiana dhidi yake (Mtume), basi hakika Mwenyezi Mungu ndiye kipenzi chake, na Jibrili, na Waumini wema, na zaidi ya hayo Malaika pia watasaidia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 5, 'Asaa Mola wake Mlezi, akikupeni talaka, akampa wake wengine badala yenu nyinyi, walio bora kuliko nyinyi, wanyenyekevu, Waumini, watawa, waliotubu, wenye kushika ibada, wafanyao heri, waliowahi kuoleka na wale ambao hawajawahi kuoleka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 6, 'Enyi mlioamini! Jilindeni nafsi zenu na ahali zenu kutokana na Moto ambao kuni zake ni watu na mawe. Wanausimamia Malaika wakali, wenye nguvu, hawamuasi Mwenyezi Mungu kwa anayowaamrisha, na wanatenda wanayoamrishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 7, 'Enyi mliokufuru! Msilete udhuru leo. Hakika mnalipwa mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 8, 'Enyi mlioamini! Tubuni kwa Mwenyezi Mungu toba iliyo ya kweli! Asaa Mola wenu Mlezi akakufutieni maovu yenu na akakuingizeni katika Bustani zipitazo mito kati yake, siku ambayo Mwenyezi Mungu hatamdhalilisha Nabii na wale walioamini pamoja naye. Nuru yao inakwenda mbele yao na pande zao za kulia, na huku wanasema: ''Mola wetu Mlezi! Tutimilizie nuru yetu, na utughufirie! Hakika Wewe ni Mwenye uweza juu ya kila kitu.''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 9, 'Ewe Nabii! Pambana na makafiri na wanafiki, na kuwa mgumu kwao! Na makazi yao ni Jahannamu. Na hayo ni marejeo mabaya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 10, 'Mwenyezi Mungu amewapigia mfano wale waliokufuru: mke wa Nuhu na mke wa Lut''i. Walikuwa chini ya waja wetu wema wawili miongoni mwa waja wetu. Lakini wakawafanyia uhaini waume zao, nao wasiwafae kitu kutokana na Mwenyezi Mungu. Na ikasemwa: ''Ingieni Motoni pamoja na wanaoingia!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 11, 'Na Mwenyezi Mungu amewapigia mfano wale walioamini - mkewe Firauni, aliposema: Mola wangu Mlezi! Nijengee kwako nyumba katika Bustani ya mbinguni, na uniokoe na Firauni na vitendo vyake, na uniokoe na watu madhalimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 12, 'Na Mariamu binti wa Imrani, aliyelinda ubikira wake, na tukampulizia humo kutoka roho yetu, na akayasadiki maneno ya Mola wake Mlezi na Vitabu vyake, na alikuwa miongoni mwa watiifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 1, 'Ametukuka ambaye mkononi mwake umo Ufalme wote; na Yeye ni Mwenye uwezo mno juu ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 2, 'Ambaye ameumba mauti na uhai ili kukujaribuni ni nani miongoni mwenu mwenye vitendo vizuri zaidi. Na Yeye ni Mwenye nguvu, Mwenye msamaha mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 3, 'Aliyeumba mbingu saba kwa matabaka. Huoni tafauti yoyote katika uumbaji wa Mwingi wa Rehema. Hebu rudia kutazama! Je, unaona kosa lolote?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 4, 'Tena rudia kutazama mara mbili, kutazama kwako kutakurejelea mwenyewe hali ya kuwa kumehizika, kumechoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 5, 'Na kwa hakika tumeipamba mbingu ya chini kabisa kwa mataa, na tumeyafanya ili kuwapigia mashetani, na tumewaandalia adhabu ya Moto wenye mwako mkali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 6, 'Na kwa wale waliomkufuru Mola wao Mlezi ipo adhabu ya Jahannamu. Na ni marejeo maovu yalioje hayo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 7, 'Watakapotupwa humo, watausikia mngurumo wake na huku inafoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 8, 'Inakaribia kupasuka kwa hasira. Kila mara likitupwa kundi humo, walinzi wake huwauliza: ''Kwani hakukujieni mwonyaji?''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 9, 'Watasema: ''Kwani! Ametujia mwonyaji, lakini tulimkadhibisha, na tukasema: ''Mwenyezi Mungu hakuteremsha chochote. Nyinyi hamumo ila katika upotovu mkubwa!''''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 10, 'Na watasema: ''Lau kuwa tungelisikia, au tungelikuwa tukitumia akili, tusingelikuwa katika watu wa Moto wenye mwako mkali!''', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 11, 'Wakakiri dhambi zao. Basi kuangamia ni kwa watu wa Moto wenye mwako mkali!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 12, 'Hakika wale wanaomwogopa Mola wao Mlezi kwa ghaibu, watapata maghfira na ujira mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 13, 'Na ficheni kauli zenu, au zidhihirisheni wazi; hakika Yeye anajua mno yaliyomo vifuani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 14, 'Asijue yule aliyeumba, naye ndiye Mjua siri, Mwenye habari?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 15, 'Yeye ndiye aliyeidhalilisha ardhi kwa faida yenu, basi tembeeni katika pande zake, na kuleni katika riziki zake. Na kwake Yeye ndiyo kufufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 16, 'Je, mmesalimika kutokana na aliyeko juu kuwa hatakudidimizeni kwenye ardhi, na tahamaki hiyo inatikisika!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 17, 'Au mnadhani mko salama kutokana na aliyeko juu ya kuwa Yeye hatakupelekeeni kimbunga chenye changarawe? Basi mtajua vipi maonyo yangu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 18, 'Na bila ya shaka walikwisha kanusha wale waliokuwa kabla yao; basi kulikuwaje kukasirika kwangu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 19, 'Kwani hawawaoni ndege walioko juu yao namna wanavyozikunjua mbawa zao, na kuzikunja? Hawashikilii ila Mwingi wa rehema. Hakika Yeye ni Mwenye kuona mno kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 20, 'Au ni lipi hilo jeshi lenu la kukunusuruni badala ya Mwingi wa Rehema? Hakika makafiri hawamo ila katika udanganyifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 21, 'Au ni nani huyo ambaye atakupeni riziki kama Yeye akizuia riziki yake? Bali wao wanakakamia tu katika jeuri na kujiweka mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 22, 'Je, anayekwenda akisinukia juu ya uso wake ni mwongofu zaidi, au yule anayekwenda sawasawa katika Njia iliyonyooka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 23, 'Sema: Yeye ndiye aliyekuumbeni tangu mwanzo, na akakupeni uwezo wa kusikia na kuona na ufahamu wa nyoyo. Ni kidogo kabisa shukrani zenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 24, 'Sema: Yeye ndiye aliyekutawanyeni katika ardhi, na kwake mtakusanywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 25, 'Na wanasema: Lini ahadi hii, ikiwa mnasema ukweli?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 26, 'Sema: Hakika elimu ya hayo iko kwa Mwenyezi Mungu; na hakika mimi ni mwonyaji wa wazi tu mwenye kubainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 27, 'Lakini watakapoiona karibu, nyuso za wale waliokufuru zitahuzunishwa, na itasemwa: Hayo ndiyo mliyokuwa mkiyaomba mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 28, 'Sema: Mwaonaje, ikiwa Mwenyezi Mungu ataniangamiza mimi na wale walio pamoja nami, au akiturehemu, ni nani atakayewalinda makafiri mbali na adhabu chungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 29, 'Sema: Yeye ndiye Mwingi wa Rehema; tunamuamini Yeye, na juu yake tunategemea. Basi mtakuja jua ni nani aliye katika upotovu ulio dhahiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 30, 'Sema: Mwaonaje, yakiwa maji yenu yamedidimia chini, ni nani atakuleteeni maji yanayomiminika?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 1, 'Nuun. Ninaapa kwa kalamu na yale wayaandikayo.[1]', '[1] Herufi hii "Nuun" na herufi nyinginezo za mkato zilizo mwanzoni mwa sura mbalimbali zinaonyesha hali ya ushindi wa Qur-ani. Kwani, washirikina walipewa changamoto kwayo, lakini wakashindwa na hawakuweza kuipinga, ilhali inajumuisha herufi hizi zinazounda lugha ya Kiarabu. Kwa hivyo, kutoweza kwa Waarabu kuleta kitu kama hicho - ingawa walikuwa ndio watu wenye ufasaha zaidi - kunaonyesha kwamba Qur-ani ni ufunuo (wahyi) kutoka kwa Mwenyezi Mungu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 2, 'Kwa neema ya Mola wako Mlezi wewe si mwendawazimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 3, 'Na kwa hakika wewe una malipo yasiyokatika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 4, 'Na hakika wewe una tabia tukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 5, 'Karibu utaona, na wao wataona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 6, 'Ni nani kati yenu aliyepandwa na wazimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 7, 'Hakika Mola wako Mlezi ndiye ajuaye zaidi ni nani aliyeipotea njia yake, na Yeye ndiye anayewajua zaidi walioongoka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 8, 'Basi usiwatii wanaokadhibisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 9, 'Walitamani lau ungelainisha ili nao wakulainishie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 10, 'Wala usimtii kila mwingi wa kuapa, anayedharauliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 11, 'Mwenye kukejeli mno, anayetangatanga akieneza maneno ya kufitini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 12, 'Mwenye kuzuia mno heri, dhalimu, mwingi wa madhambi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 13, 'Mkatili, na juu ya hayo, ni mshari aliyejipachika tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 14, 'Ati kwa kuwa ana mali na watoto!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 15, 'Anaposomewa Aya zetu, husema: "(Hizi ni) simulizi za uongo za watu wa zamani!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 16, 'Tutamtia alama kwenye pua yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 17, 'Hakika tuliwajaribu hawa kama tulivyowajaribu wale wenye shamba, walipoapa kwamba lazima watayavuna mazao yake itakapokuwa asubuhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 18, 'Wala hawakusema: "Mwenyezi Mungu akipenda!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 19, 'Basi lilitokea tukio juu yake kutoka kwa Mola wako Mlezi, nao wamelala!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 20, 'Likawa kama usiku wa giza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 21, 'Kisha asubuhi wakaitana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 22, 'Ya kwamba: "Nendeni mapema kondeni mwenu ikiwa mnataka kuvuna."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 23, 'Basi walikwenda huku wananong''onezana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 24, 'Ya kuwa: "Leo kamwe masikini mmoja asikuingilieni."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 25, 'Na walikwenda asubuhi, nao wameshikilia azimio hilo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 26, 'Basi walipoliona, wakasema: Hakika tumepotea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 27, 'Bali tumenyimwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 28, 'Mbora wao akasema: Sikukwambieni, kwa nini hamumtakasi Mwenyezi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 29, 'Wakasema: Ametakasika Mola wetu Mlezi! Hakika sisi tulikuwa wenye kudhulumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 30, 'Basi wakaelekeana kulaumiana wao kwa wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 31, 'Wakasema: Ole wetu! Hakika sisi tulikuwa tumeikiuka mipaka!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 32, 'Asaa Mola wetu Mlezi akatubadilishia lililo bora kuliko hili. Hakika sisi ni wenye kurejea kwa Mola wetu Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 33, 'Namna hivi yanakuwa mateso, na bila ya shaka mateso ya Akhera ni makubwa zaidi, laiti wangelijua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 34, 'Hakika wacha Mungu watakuwa na Bustani za neema kwa Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 35, 'Kwani tutawafanya Waislamu kama wahalifu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 36, 'Mna nini? Mnahukumu vipi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 37, 'Au mnacho kitabu ambacho ndani yake mnasoma?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 38, 'Kuwa mtapata humo mnayoyapenda?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 39, 'Au mnazo ahadi za viapo juu yetu za kufika Siku ya Kiyama ya kuwa hakika mtapata kila mnayojihukumia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 40, 'Waulize: Ni nani miongoni mwao mdhamini wa haya?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 41, 'Au wanao washirika? Basi wawalete washirika wao wakiwa wanasema kweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 42, 'Siku utakapowekwa wazi muundi, na wataitwa kusujudu, lakini hawataweza', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 43, 'Macho yao yatainama chini, fedheha itawafunika. Na hakika walikuwa wakiitwa wasujudu walipokuwa wazima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 44, 'Basi niache na wanaokadhibisha maneno haya! Tutawavutia kidogo kidogo kutokea mahali wasipopajua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 45, 'Na ninawapururia muhula; hakika hila zangu ni imara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 46, 'Au unawaomba ujira, na wao wanaemewa na gharama hiyo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 47, 'Au iko kwao siri, basi wao wanaiandika?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 48, 'Basi ingojee hukumu ya Mola wako Mlezi, wala usiwe kama mmezwa na samaki, aliponadi naye kazongwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 49, 'Kama isingelimfikia neema kutoka kwa Mola wake Mlezi, bila ya shaka angelitupwa ufukweni naye ni mwenye kulaumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 50, 'Lakini Mola wake Mlezi alimteua na akamfanya miongoni mwa watu wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 51, 'Na waliokufuru hukaribia kukutelezesha kwa macho yao, wanaposikia mawaidha, na wanasema: Hakika yeye ni mwendawazimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 52, 'Na hayakuwa haya, ila ni ukumbusho kwa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 1, 'Tukio la haki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 2, 'Nini hilo Tukio la haki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 3, 'Na nini kitakachokujulisha nini hilo Tukio la haki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 4, 'Thamudi na A''di waliukadhibisha Msiba unaoshtusha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 5, 'Basi Thamudi waliangamizwa kwa balaa kubwa mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 6, 'Na ama A''di waliangamizwa kwa upepo mkali usiozuilika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 7, 'Aliowapelekea usiku saba, na michana minane, mfululizo bila ya kusita. Utaona watu wamepinduka kama kwamba ni magongo ya mitende yaliyo wazi ndani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 8, 'Basi je! Unamwona mmoja wao aliyebaki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 9, 'Na Firauni na waliomtangulia, na miji iliyopinduliwa chini juu, walileta dhambi kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 10, 'Akamuasi Mtume wa Mola wao Mlezi, ndipo Yeye Mola akawakamata kwa mkamato uliozidi nguvu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 11, 'Maji yalipofurika Sisi tulikupandisheni katika safina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 12, 'Ili tuyafanye hayo kuwa ni waadhi kwenu na kila sikio linalosikia liyahifadhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 13, 'Na litapopulizwa baragumu mpulizo mmoja tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 14, 'Na ardhi na milima ikaondolewa, na ikavunjwa kwa mvunjo mmoja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 15, 'Siku hiyo ndio Tukio litatokea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 16, 'Na mbingu zitapasuka, kwani siku hiyo zitakuwa dhaifu kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 17, 'Na Malaika watakuwa pembezoni mwa mbingu; na wanane juu ya hawa watakuwa wamebeba Kiti cha Enzi cha Mola wako Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 18, 'Siku hiyo mtahudhurishwa - haitafichika siri yoyote yenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 19, 'Basi ama atakayepewa kitabu chake kwa mkono wake wa kulia, atasema: Haya someni kitabu changu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 20, 'Hakika nilijua ya kuwa nitapokea hisabu yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 21, 'Basi yeye atakuwa katika maisha ya kupendeza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 22, 'Katika Bustani ya juu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 23, 'Matunda yake ya karibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 24, 'Waambiwe: Kuleni na mnywe kwa furaha kwa sababu ya mlivyotanguliza katika siku zilizopita.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 25, 'Na ama atakayepewa kitabu chake katika mkono wake wa kushoto, basi yeye atasema: "Laiti nisingelipewa kitabu changu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 26, 'Wala nisingelijua nini hisabu yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 27, 'Laiti mauti ndiyo yangelikuwa ya kunimaliza kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 28, 'Mali yangu hayakunifaa kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 29, 'Madaraka yangu yamenipotea."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 30, '(Pasemwe): Mshikeni! Mtieni pingu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 31, 'Kisha mtupeni Motoni!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 32, 'Tena mtatizeni katika mnyororo wenye urefu wa dhiraa sabini!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 33, 'Kwani huyo hakika alikuwa hamuamini Mwenyezi Mungu Mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 34, 'Wala hahimizi kulisha masikini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 35, 'Basi leo hapa hana jamaa wa kumwonea uchungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 36, 'Wala hana chakula ila usaha wa watu wa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 37, 'Chakula hicho hawakili ila wakosefu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 38, 'Basi ninaapa kwa mnavyoviona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 39, 'Na msivyoviona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 40, 'Kwa hakika hii ni kauli iliyoletwa na Mjumbe mwenye heshima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 41, 'Wala si kauli ya mtunga mashairi. Ni machache sana mnayoyaamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 42, 'Wala si kauli ya kuhani. Ni machache mnayoyakumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 43, 'Ni uteremsho utokao kwa Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 44, 'Na lau kama angelituzulia baadhi ya maneno tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 45, 'Bila ya shaka tungelimshika kwa mkono wa kulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 46, 'Kisha kwa hakika tungelimkata mshipa mkubwa wa moyo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 47, 'Na hapana yeyote katika nyinyi ambaye angeliweza kutuzuia kumfikia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 48, 'Kwa hakika hii ni mawaidha kwa wacha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 49, 'Na hakika Sisi bila ya shaka tunajua kwamba miongoni mwenu wapo wanaokadhibisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 50, 'Na hakika bila ya shaka itakuwa ni majuto kwa wanaokataa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 51, 'Na hakika hii bila ya shaka ni haki ya yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 52, 'Basi litakase jina la Mola wako Mlezi Mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 1, 'Muulizaji aliuliza juu ya adhabu itakayotokea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 2, 'Kwa makafiri - ambayo hapana awezaye kuizuia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 3, 'Kutoka kwa Mwenyezi Mungu Mwenye mbingu za daraja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 4, 'Malaika na Roho hupanda kwenda kwake katika siku ambayo kiasi chake ni miaka hamsini elfu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 5, 'Basi subiri kwa subira njema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 6, 'Hakika wao wanaiona iko mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 7, 'Na Sisi tunaiona iko karibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 8, 'Siku ambayo mbingu zitakapokuwa kama madini iliyoyeyushwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 9, 'Na milima itakuwa kama sufi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 10, 'Wala jamaa hatamuuliza jamaa yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 11, 'Ijapokuwa wataonyeshwa waonane. Atatamani mkosefu lau ajikomboe na adhabu ya siku hiyo kwa kuwatoa fidia wanawe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 12, 'Na mkewe, na nduguye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 13, 'Na jamaa zake waliokuwa wakimkimu,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 14, 'Na wote waliomo duniani, kisha aokoke yeye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 15, 'La, hasha! Kwa hakika huo ni Moto mkali kabisa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 16, 'Unaobambua ngozi ya kichwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 17, 'Utamwita kila aliyegeuza mgongo na akageuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 18, 'Na akakusanya mali, kisha akayahifadhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 19, 'Hakika mtu ameumbwa na papara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 20, 'Inapomgusa shari hupapatika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 21, 'Na inapomgusa kheri huizuilia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 22, 'Isipokuwa wanaosali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 23, 'Ambao wanadumisha Sala zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 24, 'Na ambao katika mali yao iko haki maalumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 25, 'Kwa mwenye kuomba na anayejizuilia kuomba;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 26, 'Na ambao wanaisadiki Siku ya Malipo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 27, 'Na ambao wanaiogopa adhabu itokayo kwa Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 28, 'Hakika adhabu ya Mola wao Mlezi si ya kuwa na amani nayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 29, 'Na ambao wanahifadhi tupu zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 30, 'Isipokuwa kwa wake zao, au iliyowamiliki mikono yao ya kuume, basi hao hawalaumiwi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 31, 'Lakini wanaotaka kinyume cha haya, basi hao ndio wanaoruka mipaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 32, 'Na ambao wanazichunga amana zao na ahadi zao,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 33, 'Na ambao wanasimama imara katika ushahidi wao,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 34, 'Na ambao wanazihifadhi Sala zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 35, 'Hao ndio watakaoheshimiwa katika Bustani ya mbinguni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 36, 'Wana nini wale waliokufuru wanakutumbulia macho tu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 37, 'Makundi kwa makundi upande wa kulia na upande wa kushoto!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 38, 'Kwani kila mmoja wao anatumai kuingizwa katika Bustani ya mbinguni ya neema?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 39, 'La, hasha! Hakika Sisi tumewaumba kutokana na wanachokijua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 40, 'Basi naapa kwa Mola Mlezi wa mashariki zote na magharibi zote kwamba Sisi tunaweza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 41, 'Kuwabadili kwa walio bora kuliko wao; na Sisi hatushindwi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 42, 'Basi waache wapige porojo na wacheze, mpaka wakutane na siku yao wanayoahidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 43, 'Siku watakapotoka makaburini kwa upesi kama kwamba wanakimbilia mfundo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 44, 'Macho yao yatainama, fedheha itawafunika. Hiyo ndiyo Siku waliyokuwa wakiahidiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 1, 'Hakika Sisi tulimtuma Nuhu kwa watu wake: Kwamba waonye kaumu yako kabla ya kuwafikia adhabu chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 2, 'Akasema: Enyi watu wangu! Kwa hakika mimi ni mwonyaji wa dhahiri kwenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 3, 'Ya kwamba mumuabudu Mwenyezi Mungu, na mumche Yeye, na mumtii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 4, 'Atakughufirieni madhambi yenu, na atakuakhirisheni mpaka muda uliowekwa. Hakika muda wa Mwenyezi Mungu utapofika haucheleweshwi. Laiti mngejua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 5, 'Akasema: Ee Mola wangu Mlezi! Hakika mimi nimewaita watu wangu usiku na mchana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 6, 'Lakini wito wangu haukuwazidisha ila kukimbia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 7, 'Na hakika mimi kila nilipowaita ili upate kuwaghufiria, walijiziba masikio yao kwa vidole vyao, na wakajigubika nguo zao, na wakakamia, na wakatakabari vikubwa mno!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 8, 'Tena niliwaita kwa uwazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 9, 'Kisha nikawatangazia hadharani, tena nikasema nao kwa siri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 10, 'Nikasema: Ombeni msamaha kwa Mola wenu Mlezi; hakika Yeye ni Mwingi wa kusamehe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 11, 'Atakuleteeni mvua inyeshe mfululizo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 12, 'Na atakupeni mali na wana, na atakupeni mabustani na atakufanyieni mito.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 13, 'Mna nini hamweki heshima ya Mwenyezi Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 14, 'Na hali Yeye kakuumbeni daraja baada ya daraja?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 15, 'Kwani hamwoni jinsi Mwenyezi Mungu alivyoziumba mbingu saba kwa matabaka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 16, 'Na akaufanya mwezi ndani yake uwe nuru, na akalifanya jua kuwa taa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 17, 'Na Mwenyezi Mungu amekuotesheni katika ardhi kama mimea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 18, 'Kisha atakurudisheni humo na atakutoeni tena.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 19, 'Na Mwenyezi Mungu amekukunjulieni ardhi kama busati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 20, 'Ili mtembee humo katika njia zilizo pana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 21, 'Nuhu akasema: Mola wangu Mlezi! Hakika hao wameniasi, na wamemfuata yule ambaye mali yake na wanawe hawakumzidishia ila hasara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 22, 'Na wakapanga vitimbi vikubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 23, 'Na wakasema: Kamwe msiiache miungu yenu, wala msimwache Wadda wala Suwaa'' wala Yaghutha, wala Yau''qa, wala Nasra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 24, 'Na hao walikwisha wapoteza wengi, wala usiwazidishie waliodhulumu ila kupotea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 25, 'Basi kwa ajili ya makosa yao waligharikishwa wakaingizwa Motoni, wala hawakuwapata wa kuwanusuru badala ya Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 26, 'Na Nuhu akasema: Mola wangu Mlezi! Usimwache juu ya ardhi mkazi wake yeyote katika makafiri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 27, 'Hakika ukiwaacha watawapoteza waja wako, wala wao hawatazaa ila waovu makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 28, 'Mola wangu Mlezi! Nighufirie mimi na wazazi wangu, na kila aliyeingia nyumbani mwangu kuwa ni mwenye kuamini, na Waumini wote wanaume, na Waumini wanawake. Na wala usiwazidishie waliodhulumu ila kupotea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 1, 'Sema: Imefunuliwa kwangu ya kuwa kundi moja la majini lilisikiliza, na likasema: Hakika sisi tumeisikia Qur-ani ya ajabu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 2, 'Inaongoza kwenye uongofu, kwa hivyo tumeiamini, wala hatutamshirikisha yeyote na Mola wetu Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 3, 'Na kwa hakika utukufu wa Mola wetu Mlezi umetukuka kabisa; hana mke wala mwana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 4, 'Na kwa hakika wapumbavu miongoni mwetu walikuwa wakisema uongo uliopindukia mipaka juu ya Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 5, 'Nasi tulidhani kuwa watu na majini hawamzulii uongo Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 6, 'Na hakika walikuwako wanaume katika watu waliokuwa wakitafuta kujikinga kwa wanaume wa kijini; kwa hivyo wakawazidisha madhambi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 7, 'Na kwa hakika wao walidhani, kama mlivyodhani nyinyi, ya kuwa Mwenyezi Mungu hatamleta Mtume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 8, 'Nasi tulifanya bidii kufika kwenye mbingu, lakini tukazikuta zimejaa walinzi wenye nguvu na vimondo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 9, 'Na hakika tulikuwa tukikaa humo katika baadhi ya makao ili kusikiliza; lakini sasa anayetaka kusikiliza atakuta kimondo kinamvizia!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 10, 'Nasi hatujui kama wanatakiwa shari wale wanaokaa kwenye ardhi au Mola wao Mlezi anawatakia uongofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 11, 'Na hakika katika sisi wamo walio wema, na wengine wetu ni kinyume na hivyo. Tumekuwa njia mbali mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 12, 'Nasi tulijua kuwa hatutomshinda Mwenyezi Mungu duniani, wala hatuwezi kumponyoka kwa kukimbia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 13, 'Nasi tulipousikia uongofu tuliuamini. Basi mwenye kumuamini Mola wake Mlezi basi haogopi kupunjwa wala kudhulumiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 14, 'Na hakika wamo katika sisi Waislamu, na wamo kati yetu wanaoacha haki. Basi waliosilimu, hao ndio waliotafuta uongofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 15, 'Na ama wanaoacha haki, hao watakuwa kuni za Jahannamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 16, 'Na lau kama wangelisimama sawasawa juu ya njia tungeliwanywesha maji kwa wingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 17, 'Ili tuwajaribu kwa hayo. Na anayepuuza kumkumbuka Mola wake Mlezi atamsukuma kwenye adhabu ngumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 18, 'Na hakika misikiti ni ya Mwenyezi Mungu, basi msimuabudu yeyote pamoja na Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 19, 'Na hakika Mja wa Mwenyezi Mungu aliposimama kumwomba, wao walikuwa karibu kumzonga!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 20, 'Sema: Hakika mimi namwomba Mola wangu Mlezi, wala simshirikishi Yeye na yeyote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 21, 'Sema: Mimi sina mamlaka ya kukudhuruni wala kukuongozeni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 22, 'Sema: Hakika hapana yeyote awezaye kunilinda na Mwenyezi Mungu, wala sitapata pa kukimbilia isipokuwa kwake Yeye tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 23, 'Ila nifikishe Ujumbe utokao kwa Mwenyezi Mungu na risala zake. Na wenye kumuasi Mwenyezi Mungu na Mtume wake, basi hakika hao watapata Moto wa Jahannamu wadumu humo milele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 24, 'Hata watakapo yaona wanayoahidiwa, ndipo watakapojua ni nani mwenye msaidizi dhaifu, na mchache wa idadi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 25, 'Sema: Sijui kama yapo karibu hayo mnayoahidiwa, au Mola wangu Mlezi atayawekea muda mrefu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 26, 'Yeye ndiye Mwenye kujua ya siri, wala hamdhihirishii yeyote ghaibu yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 27, 'Isipokuwa Mtume wake aliyemridhia. Naye huyo humwekea walinzi mbele yake na nyuma yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 28, 'Ili Yeye ajue kwamba wao wamefikisha ujumbe wa Mola wao Mlezi, na Yeye anayajua vyema yote waliyo nayo, na amedhibiti idadi ya kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 1, 'Ewe uliyejifunika!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 2, 'Kesha usiku kucha, ila kidogo tu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 3, 'Nusu yake, au ipunguze kidogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 4, 'Au izidishe - na soma Qur-ani kwa utaratibu na utungo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 5, 'Hakika Sisi tutakuteremshia kauli nzito.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 6, 'Hakika kuamka usiku kunawafikiana zaidi na moyo, na maneno yake yanatua zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 7, 'Kwani hakika mchana una shughuli nyingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 8, 'Na lidhukuru jina la Mola wako Mlezi, na ujitolee kwake kwa ukamilifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 9, 'Mola Mlezi wa mashariki na magharibi, hapana mungu isipokuwa Yeye, basi mfanye kuwa Mtegemewa wako.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 10, 'Na vumilia hayo wayasemayo, na jitenge nao kwa vizuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 11, 'Na niache Mimi na hao wanaokanusha, walioneemeka; na wape muhula kidogo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 12, 'Hakika Sisi tunazo pingu nzito na Moto unaowaka kwa ukali kabisa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 13, 'Na chakula kinachokwama kooni, na adhabu inayoumiza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 14, 'Siku ambayo ardhi itatikiswa na milima pia, na milima itakuwa kama tifutifu la mchanga!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 15, 'Hakika Sisi tumemtuma kwenu Mtume aliye shahidi juu yenu, kama tulivyomtuma Mtume kwa Firauni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 16, 'Lakini Firauni alimuasi huyo Mtume, basi tukamshika mshiko wa mateso.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 17, 'Basi nyinyi mkikufuru, mtawezaje kujikinga na Siku ambayo itawafanya watoto wadogo waote mvi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 18, 'Hapo mbingu zitapasuka kwa sababu yake! Ahadi yake itakuwa imetekelezwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 19, 'Kwa hakika hili ni kumbusho. Mwenye kutaka atashika Njia ya kwendea kwa Mola wake Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 20, 'Hakika Mola wako Mlezi anajua ya kuwa hakika wewe unakesha karibu na thuluthi mbili za usiku, na nusu yake, na thuluthi yake. Na baadhi ya watu walio pamoja nawe kadhalika. Na Mwenyezi Mungu ndiye anayeukadiria usiku na mchana. Anajua kuwa hamwezi kuweka hisabu, basi amekusameheni. Basi someni kilicho chepesi katika Qur-ani. Anajua ya kuwa baadhi yenu watakuwa wagonjwa, na wengine wanasafiri katika ardhi wakitafuta fadhila ya Mwenyezi Mungu, na wengine wanapigana katika Njia ya Mwenyezi Mungu. Kwa hivyo someni kilicho chepesi humo, na mshike Sala, na toeni Zaka, na mkopesheni Mwenyezi Mungu mkopo mwema. Na kheri yoyote mnayoitanguliza kwa ajili ya nafsi zenu mtaikuta kwa Mwenyezi Mungu, imekuwa bora zaidi, na ina thawabu kubwa sana. Na mtakeni msamaha Mwenyezi Mungu. Hakika Mwenyezi Mungu ni Mwenye kusamehe, Mwenye kurehemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 1, 'Ewe uliyejigubika!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 2, 'Simama uonye!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 3, 'Na Mola wako Mlezi mtukuze!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 4, 'Na nguo zako, zisafishe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 5, 'Na yaliyo machafu yahame!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 6, 'Wala usitoe kwa kutaraji kuzidishiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 7, 'Na kwa ajili ya Mola wako Mlezi, subiri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 8, 'Basi litakapopulizwa baragumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 9, 'Siku hiyo, basi, itakuwa siku ngumu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 10, 'Kwa makafiri haitakuwa nyepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 11, 'Niache peke yangu na niliyemuumba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 12, 'Na nikamjaalia awe na mali mengi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 13, 'Na wana wanaoonekana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 14, 'Na nikamtegenezea mambo vizuri kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 15, 'Kisha anatumai nimzidishie!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 16, 'Hasha! Kwani hakika yeye alikuwa akizifanyia ukaidi Aya zetu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 17, 'Nitamtesa kwa mateso yasiowezekana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 18, 'Kwani hakika yeye alifikiri na akapima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 19, 'Basi ameangamia! Vipi alivyopima!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 20, 'Tena ameangamia! Vipi alivyopima!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 21, 'Kisha akatazama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 22, 'Kisha akakunja kipaji, na akanuna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 23, 'Kisha akaipa kisogo haki, na akatakabari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 24, 'Na akasema: Haya si chochote ila ni uchawi ulionukuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 25, 'Haya si chochote ila kauli ya binadamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 26, 'Nitakuja mtia kwenye Moto wa Saqar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 27, 'Na nini kitakujuulisha ni nini huo Moto wa Saqar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 28, 'Haubakishi wala hausazi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 29, 'Unababua ngozi iwe nyeusi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 30, 'Juu yake wapo kumi na tisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 31, 'Na hatukuwafanya walinzi wa Motoni ila ni Malaika, wala hatukuifanya idadi yao hiyo ila kuwatatanisha waliokufuru, wapate kuwa na yakini waliopewa Kitabu, na wazidi Imani wale walioamini, wala wasiwe na shaka waliopewa Kitabu na Waumini, na wapate kusema wenye maradhi katika nyoyo zao na makafiri: "Mwenyezi Mungu amekusudia nini kwa mfano huu?" Ndiyo kama hivyo Mwenyezi Mungu humwacha apotee amtakaye, na humwongoa amtakaye. Na hapana yeyote anayejua majeshi ya Mola wako Mlezi ila Yeye tu. Na haya si chochote ila ni ukumbusho kwa binadamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 32, 'Hasha! Naapa kwa mwezi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 33, 'Na kwa usiku unapokucha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 34, 'Na kwa asubuhi inapopambazuka!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 35, 'Hakika huo Moto ni katika mambo yaliyo makubwa kabisa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 36, 'Ni onyo kwa binaadamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 37, 'Kwa anayetaka miongoni mwenu kutangulia au kuchelewa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 38, 'Kila nafsi imo rahanini kwa mabaya iliyoyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 39, 'Isipokuwa watu wa kuliani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 40, 'Hao watakuwa katika Mabustani, wawe wanaulizana', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 41, 'Habari za wakosefu:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 42, 'Ni nini kilichokupelekeni Motoni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 43, 'Waseme: Hatukuwa miongoni mwa waliokuwa wakisali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 44, 'Wala hatukuwa tukiwalisha masikini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 45, 'Na tulikuwa tukizama pamoja na waliozama katika maovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 46, 'Na tulikuwa tukiikanusha Siku ya Malipo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 47, 'Mpaka yakini (yaani mauti) ilipotufikia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 48, 'Basi hautawafaa kitu uombezi wa waombezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 49, 'Basi wana nini hata wanapuuza onyo hili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 50, 'Kana kwamba wao ni mapunda waliotimuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 51, 'Wanaomkimbia simba!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 52, 'Ati kila mmoja katika wao anataka apewe nyaraka zilizofunuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 53, 'Hasha! Kwani wao hawaiogopi Akhera?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 54, 'Hasha! Kwa hakika huu ni ukumbusho!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 55, 'Basi anayetaka atakumbuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 56, 'Na hawatakumbuka isipokuwa Mwenyezi Mungu atake. Ucha Mungu ni kwake Yeye, na msamaha ni wake Yeye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 1, 'Ninaapa kwa Siku ya Kiyama!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 2, 'Na ninaapa kwa nafsi inayojilaumu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 3, 'Anadhani mtu kuwa Sisi hatutaikusanya mifupa yake?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 4, 'Kwani! Sisi tunaweza hata kuziweka sawa sawa ncha za vidole vyake!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 5, 'Lakini mtu anataka tu kuendelea na maasi kwa siku zilizoko mbele yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 6, 'Anauliza: Lini itakuwa hiyo Siku ya Kiyama?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 7, 'Basi jicho litakapodawaa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 8, 'Na mwezi utakapopatwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 9, 'Na likakusanywa jua na mwezi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 10, 'Siku hiyo mtu atasema: Yako wapi makimbilio?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 11, 'La! Hapana pa kukimbilia!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 12, 'Siku hiyo pa kutua ni kwa Mola wako Mlezi tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 13, 'Siku hiyo ataambiwa aliyoyatanguliza na aliyoyaakhirisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 14, 'Bali mtu ni hoja juu ya nafsi yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 15, 'Na ingawa atatoa chungu ya udhuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 16, 'Usiutikisie huu wahyi ulimi wako kwa kuufanyia haraka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 17, 'Hakika ni juu yetu kuukusanya na kuusomesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 18, 'Tunapousoma, basi nawe fuatiliza kusoma kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 19, 'Kisha ni juu yetu kuubainisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 20, 'Hasha! Bali nyinyi mnapenda maisha ya duniani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 21, 'Na mnaacha maisha ya Akhera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 22, 'Zipo nyuso siku hiyo zitakazong''ara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 23, 'Zinamwangallia Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 24, 'Na zipo nyuso siku hiyo zitakazokunjana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 25, 'Zitajua ya kuwa zitafikiwa na livunjalo uti wa mgongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 26, 'La, hasha! (Roho) itakapofikia kwenye mafupa ya koo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 27, 'Na pakasemwa: Nani wa kumtibu (apone)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 28, 'Na mwenyewe akajua kwa hakika kuwa huko ndiko kufariki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 29, 'Na utakapoambatishwa muundi kwa muundi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 30, 'Siku hiyo ndiyo kuchungwa kupelekwa kwa Mola wako Mlezi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 31, 'Kwa sababu hakusadiki, wala hakusali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 32, 'Bali alikanusha, na akageuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 33, 'Kisha akenda kwa ahali zake kwa matao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 34, 'Ole wako, ole wako!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 35, 'Kisha ole wako, ole wako!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 36, 'Ati anadhani binadamu kuwa ataachwa bure?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 37, 'Kwani hakuwa yeye tone la manii lililoshushwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 38, 'Kisha akawa kidonge cha damu, tena Mwenyezi Mungu akamuumba na akamtengeneza vilivyo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 39, 'Kisha akamfanya namna mbili, mwanamume na mwanamke.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 40, 'Je, huyo hakuwa ni Muweza wa kufufua wafu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 1, 'Hakika kilimpitia binaadamu kipindi katika zama ambacho kwamba hakuwa kitu kinachotajwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 2, 'Hakika Sisi tumemuumba mtu kutokana na mbegu ya uhai iliyochanganyika, tumfanyie mtihani. Kwa hivyo tukamfanya mwenye kusikia, mwenye kuona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 3, 'Hakika Sisi tumembainishia Njia. Ama ni mwenye kushukuru, au mwenye kukufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 4, 'Hakika Sisi tumewaandalia makafiri minyororo na pingu na Moto mkali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 5, 'Hakika watu wema watakunywa katika vinywaji vilivyochanganyika na kafuri', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 6, 'Ni chemchemi watakayoinywa waja wa Mwenyezi Mungu, wakiifanya imiminike kwa wingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 7, 'Wanatimiza nadhiri, na wanaiogopa siku ambayo shari yake inaenea sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 8, 'Na huwalisha chakula, juu ya kukipenda kwake, masikini, na yatima, na wafungwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 9, 'Hakika sisi tunakulisheni kwa wajihi wa Mwenyezi Mungu. Hatutaki kwenu malipo wala shukrani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 10, 'Hakika sisi tunaiogopa kwa Mola wetu Mlezi hiyo siku yenye shida na taabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 11, 'Basi Mwenyezi Mungu atawalinda kutokana na shari ya siku hiyo, na atawakutanisha na raha na furaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 12, 'Na atawalipa Bustani za mbinguni na maguo ya hariri kwa vile walivyosubiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 13, 'Humo wataegemea juu ya viti vya enzi, hawataona humo jua kali wala baridi kali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 14, 'Na vivuli vyake vitakuwa karibu yao, na mashada ya matunda yataning''inia mpaka chini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 15, 'Na watapitishiwa vyombo vya fedha na vikombe vya vigae.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 16, 'Vya fedha safi kama kiyoo, wamevipima kwa vipimo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 17, 'Na humo watanyweshwa kinywaji kilichochanganyika na tangawizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 18, 'Hiyo ni chemchemi iliyo humo inaitwa Salsabil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 19, 'Na watawazungukia kuwatumikia wavulana wasiopevuka, ukiwaona utawafikiri ni lulu zilizotawanywa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 20, 'Na utakapoyaona, utakuwa umeona neema na ufalme mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 21, 'Juu yao zipo nguo za hariri laini za kijani kibichi, na hariri nzito ya atilasi. Na watavishwa vikuku vya fedha, na Mola wao Mlezi atawanywesha kinywaji safi kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 22, 'Hakika haya ni malipo yenu; na juhudi zenu zimekubaliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 23, 'Hakika Sisi tumekuteremshia Qur-ani kidogo kidogo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 24, 'Basi ngojea hukumu ya Mola wako Mlezi wala usimtii miongoni mwao mwenye dhambi au mwenye kufuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 25, 'Na likumbuke jina la Mola wako Mlezi asubuhi na jioni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 26, 'Na usiku msujudie Yeye, na umtakase usiku, wakati mrefu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 27, 'Kwa hakika watu hawa wanapenda maisha ya kidunia, na wanaiacha nyuma yao siku nzito.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 28, 'Sisi tumewaumba, na tukavitia nguvu viungo vyao. Na tukitaka tutawabadilisha mfano wao wawe badala yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 29, 'Hakika haya ni mawaidha; basi anayetaka, atashika Njia ya kwenda kwa Mola wake Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 30, 'Wala hamwezi kutaka ila atakapo Mwenyezi Mungu. Hakika Mwenyezi Mungu ni Mwenye elimu, Mwenye hekima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 31, 'Humuingiza amtakaye katika rehema yake. Na wenye kudhulumu amewawekea adhabu iliyo chungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 1, 'Ninaapa kwa zinazotumwa kwa upole!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 2, 'Na zinazovuma kwa kasi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 3, 'Na zikaeneza maeneo yote!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 4, 'Na zinazofarikisha zikatawanya!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 5, 'Na zinazopeleka mawaidha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 6, 'Kuwa udhuru au kuonya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 7, 'Hakika mnayoahidiwa bila ya shaka yatakuwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 8, 'Wakati nyota zitakapofutwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 9, 'Na mbingu zitakapopasuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 10, 'Na milima itakapopeperushwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 11, 'Na Mitume watakapowekewa wakati wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 12, 'Kwa siku gani hiyo wamewekewa muda huo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 13, 'Kwa Siku ya kupambanua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 14, 'Na nini kitakachokujuulisha siku ya kupambanua ni nini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 15, 'Ole wao, siku hiyo hao wanaokanusha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 16, 'Kwani hatukuwaangamiza waliotangulia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 17, 'Kisha tukawafuatilizia waliofuatia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 18, 'Ndio kama hivi tuwatendavyo wakosefu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 19, 'Ole wao siku hiyo hao wanaokanusha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 20, 'Kwani hatukukuumbeni kwa maji ya kudharauliwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 21, 'Kisha tukayaweka mahali pa utulivu madhubuti?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 22, 'Mpaka muda maalumu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 23, 'Tukakadiria na Sisi ni wabora wa kukadiria.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 24, 'Ole wao siku hiyo hao wanaokanusha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 25, 'Kwani hatukuifanya ardhi yenye kukusanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 26, 'Walio hai na maiti?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 27, 'Na ndani yake tukaweka milima mirefu yenye kuthibiti, na tunakunywesheni maji matamu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 28, 'Ole wao siku hiyo hao wanaokanusha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 29, 'Nendeni kwenye adhabu mliyokuwa mkiikanusha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 30, 'Nendeni kwenye kivuli chenye mapande matatu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 31, 'Hakikingi moto, wala hakiwaepushi na mwako.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 32, 'Hakika Moto huo unatoa macheche kama majumba!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 33, 'Kama kwamba ni ngamia wa rangi ya manjano!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 34, 'Ole wao siku hiyo hao wanaokanusha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 35, 'Hii ni siku ambayo hawatatamka kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 36, 'Wala hawataruhusiwa kutoa udhuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 37, 'Ole wao siku hiyo hao waliokanusha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 38, 'Hii ndiyo siku ya kupambanua. Tumekukusanyeni nyinyi na waliotangulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 39, 'Ikiwa mnayo hila, nifanyieni hila Mimi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 40, 'Ole wao siku hiyo hao waliokanusha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 41, 'Hakika wacha Mungu watakuwa katika vivuli na chemchemi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 42, 'Na matunda wanayoyapenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 43, 'Kuleni na kunyweni kwa furaha kwa yale mliyokuwa mkiyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 44, 'Hakika ndio kama hivyo tunavyowalipa watendao mema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 45, 'Ole wao siku hiyo hao wanaokanusha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 46, 'Kuleni na mjifurahishe kidogo tu. Hakika nyinyi ni wakosefu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 47, 'Ole wao siku hiyo hao wanaokanusha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 48, 'Na wakiambiwa: "Inameni!" Hawainami.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 49, 'Ole wao siku hiyo hao wanaokanusha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 50, 'Basi maneno gani baada ya haya watayaamini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 1, 'Wanaulizana kuhusu nini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 2, 'Kuhusu Ile habari kuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 3, 'Ambayo kwayo wanahitalifiana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 4, 'La! Karibu watakuja jua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 5, 'Tena la! Karibu watakuja jua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 6, 'Kwani hatukuifanya ardhi kama tandiko?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 7, 'Na milima kama vigingi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 8, 'Na tukakuumbeni kwa jozi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 9, 'Na tukakufanya kulala kwenu ni mapumziko?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 10, 'Na tukaufanya usiku ni nguo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 11, 'Na tukaufanya mchana ni wa kuchumia maisha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 12, 'Na tukajenga juu yenu saba zenye nguvu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 13, 'Na tukaifanya taa yenye mwanga na joto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 14, 'Na tukateremsha maji yanayoanguka kwa kasi kutoka mawinguni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 15, 'Ili tutoe kwayo nafaka na mimea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 16, 'Na mabustani yenye miti iliyokamatana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 17, 'Hakika Siku ya uamuzi imewekewa wakati wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 18, 'Siku litakapopulizwa baragumu, nanyi mtakuja kwa makundi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 19, 'Na mbingu zitafunguliwa, ziwe milango.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 20, 'Na milima itaondolewa na itakuwa kama sarabi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 21, 'Hakika Jahannamu inangojea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 22, 'Kwa walioasi ndio makazi yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 23, 'Wakae humo karne baada ya karne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 24, 'Hawataonja humo chochote kibaridi wala kinywaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 25, 'Ila maji ya moto sana na usaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 26, 'Ndio malipo mwafaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 27, 'Hakika hao hawakuwa wakitaraji kuwa kuna hesabu (juu ya matendo yao).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 28, 'Na wakakanusha Aya zetu kwa nguvu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 29, 'Na kila kitu Sisi tumekidhibiti kwa kukiandika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 30, 'Basi onjeni! Nasi hatutakuzidishieni ila adhabu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 31, 'Hakika wacha Mungu wanastahiki kufuzu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 32, 'Mabustani na mizabibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 33, 'Na wake wazuri waliolingana nao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 34, 'Na bilauri zilizojaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 35, 'Hawatasikia humo upuuzi wala uongo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 36, 'Malipo kutoka kwa Mola wako Mlezi, kipawa cha kutosha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 37, 'Mola Mlezi wa mbingu na ardhi na vilivyo baina yake, Arrahman (Mwingi wa rehema); hawamiliki usemi mbele yake!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 38, 'Siku atakaposimama Roho na Malaika kwa safu. Hawatasema ila yule ambaye Mwingi wa rehema atamruhusu, na atasema yaliyo sawa tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 39, 'Hiyo ndiyo Siku ya haki. Basi anayetaka, na ashike njia arejee kwa Mola wake Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 40, 'Hakika tumekuhadharisheni adhabu iliyo karibu kufika; Siku ambayo mtu ataona yale yaliyotangulizwa na mikono yake; na kafiri atasema: Laiti ningelikuwa udongo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 1, 'Ninaapa kwa wanaokomoa kwa nguvu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 2, 'Na kwa wanaotoa kwa upole.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 3, 'Na wanaoogelea sawasawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 4, 'Wakishindana mbio kweli kweli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 5, 'Wakidabiri mambo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 6, 'Siku kitakapotetemeka cha kutetemeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 7, 'Kifuate cha kufuatia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 8, 'Siku hiyo nyoyo zitapigapiga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 9, 'Macho yatainama chini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 10, 'Sasa wanasema: Ati kweli tutarudishwa kwenye hali ya kwanza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 11, 'Hata tukiwa mifupa iliyobunguliwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 12, 'Wanasema: Basi marejeo hayo ni yenye hasara!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 13, 'Kwa hakika hayo ni ukelele mmoja tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 14, 'Mara watakuwa kwenye Uwanda wa mkutano!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 15, 'Je! Imekufikia hadithi ya Musa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 16, 'Mola wake Mlezi alipomwita katika bonde takatifu la Tuwaa, akamwambia:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 17, 'Nenda kwa Firauni. Hakika yeye amezidi jeuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 18, 'Umwambie: Je! Unapenda kujitakasa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 19, 'Nami nitakuongoza ufike kwa Mola wako Mlezi, upate kumcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 20, 'Basi alimwonyesha Ishara kubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 21, 'Lakini alikadhibisha na akaasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 22, 'Kisha alirudi nyuma, akaingia kufanya juhudi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 23, 'Akakusanya watu akanadi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 24, 'Akasema: Mimi ndiye Mola wenu Mlezi mkuu kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 25, 'Basi hapo Mwenyezi Mungu akamshika kumuadhibu kwa la mwisho na la mwanzo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 26, 'Kwa hakika katika haya yapo mazingatio kwa wanaoogopa Mwenyezi Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 27, 'Je, ni vigumu zaidi kukuumbeni nyinyi au mbingu? Yeye ndiye aliyeijenga!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 28, 'Akainua paa lake, na akaitengeneza vizuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 29, 'Na akautia giza usiku wake, na akautokeza mchana wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 30, 'Na juu ya hivyo ameitandaza ardhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 31, 'Akatoa ndani yake maji yake na malisho yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 32, 'Na milima akaisimamisha imara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 33, 'Kwa manufaa yenu na mifugo yenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 34, 'Basi itakapofika hiyo Balaa kubwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 35, 'Siku ambayo mtu atakumbuka aliyoyafanya,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 36, 'Na Jahannamu itadhihirishwa kwa mwenye kuona,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 37, 'Basi ama yule aliyezidi ujeuri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 38, 'Na akakhiari maisha ya dunia,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 39, 'Kwa hakika Jahannamu ndiyo makazi yake!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 40, 'Na ama yule anayeogopa kusimamishwa mbele ya Mola wake Mlezi, na akajizuilia nafsi yake na matamanio,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 41, 'Basi huyo, Bustani ya mbinguni itakuwa ndiyo makazi yake!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 42, 'Wanakuuliza Saa (ya Kiyama) itakuwa lini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 43, 'Una nini wewe hata uitaje?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 44, 'Kwa Mola wako Mlezi ndio mwisho wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 45, 'Kwa hakika wewe ni mwonyaji tu kwa mwenye kuihofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 46, 'Ni kama kwamba wao siku watakapoiona (hiyo Saa) hawakukaa ila jioni moja tu, au mchana wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 1, 'Alikunja kipaji na akageuka mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 2, 'Kwa sababu alimjia kipofu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 3, 'Na nini kitakachokujulisha pengine yeye atatakasika?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 4, 'Au atawaidhika, na mawaidha yamfae?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 5, 'Ama ajionaye hana haja,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 6, 'Wewe ndiyo unamshughulikia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 7, 'Na si juu yako kama hakutakasika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 8, 'Ama anayekujia kwa juhudi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 9, 'Naye anaogopa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 10, 'Ndiyo wewe unampuuza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 11, 'Sivyo hivyo! Huku ni kukumbushana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 12, 'Basi anayependa akumbuke.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 13, 'Yamo katika kurasa zilizoheshimiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 14, 'Zilizoinuliwa, zilizotakaswa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 15, 'Zimo mikononi mwa Malaika waandishi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 16, 'Watukufu, wema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 17, 'Ameangamia mwanadamu! Nini kinachomkufurisha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 18, 'Kwa kitu gani amemuumba?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 19, 'Kwa tone la manii, amemuumba na akamkadiria.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 20, 'Kisha akamsahilishia njia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 21, 'Kisha akamfisha, akamtia kaburini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 22, 'Kisha apendapo atamfufua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 23, 'La! Hajamaliza aliyomuamuru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 24, 'Hebu mtu na atazame chakula chake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 25, 'Hakika Sisi tumemimina maji kwa nguvu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 26, 'Tena tukaipasua pasua ardhi kwa nguvu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 27, 'Kisha tukaotesha humo nafaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 28, 'Na zabibu, na mimea ya majani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 29, 'Na mizaituni, na mitende.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 30, 'Na bustani zenye miti iliyosongana barabara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 31, 'Na matunda, na malisho ya wanyama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 32, 'Kwa manufaa yenu na mifugo yenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 33, 'Basi utakapokuja Ukelele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 34, 'Siku ambayo mtu atamkimbia nduguye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 35, 'Na mamaye na babaye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 36, 'Na mkewe na wanawe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 37, 'Kila mtu miongoni mwao siku hiyo atakuwa na lake la kumtosha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 38, 'Siku hiyo ziko nyuso zitakazonawiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 39, 'Zitacheka, zitachangamka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 40, 'Na nyuso siku hiyo zitakuwa na mavumbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 41, 'Giza totoro litazifunika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 42, 'Hao ndio makafiri watenda maovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 1, 'Jua litakapokunjwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 2, 'Na nyota zikazimwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 3, 'Na milima ikaondolewa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 4, 'Na ngamia wenye mimba pevu watakapoachwa wasishughulikiwe,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 5, 'Na wanyama wa mwituni wakakusanywa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 6, 'Na bahari zikawaka moto,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 7, 'Na nafsi zikaunganishwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 8, 'Na msichana aliyezikwa hai atakapoulizwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 9, 'Kwa kosa gani aliuliwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 10, 'Na madaftari yatakapoenezwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 11, 'Na mbingu itakapotanduliwa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 12, 'Na Jahannamu itakapochochewa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 13, 'Na Bustani ya mbinguni ikasongezwa karibu,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 14, 'Kila nafsi itajua ilichokihudhurisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 15, 'Ninaapa kwa nyota zinaporejea nyuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 16, 'Zinazokwenda, kisha zikajificha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 17, 'Na kwa usiku unapopungua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 18, 'Na kwa asubuhi inapopambazuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 19, 'Kwamba hakika bila ya shaka hii ni kauli ya Mjumbe mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 20, 'Mwenye nguvu na mwenye cheo kwa huyo Mwenye Kiti cha Enzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 21, 'Anayetiiwa, tena muaminifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 22, 'Na wala huyu mwenzenu hana wazimu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 23, 'Na hakika yeye alimwona kwenye upeo wa macho ulio safi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 24, 'Wala yeye si bahili kwa mambo ya ghaibu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 25, 'Wala hii si kauli ya Shetani aliyelaaniwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 26, 'Basi mnakwenda wapi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 27, 'Haikuwa hii ila ni ukumbusho kwa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 28, 'Kwa yule miongoni mwenu anayetaka kwenda sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 29, 'Wala nyinyi hamtataka isipokuwa atake Mwenyezi Mungu Mola Mlezi wa walimwengu wote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 1, 'Mbingu itakapochanika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 2, 'Na nyota zitakapotawanyika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 3, 'Na bahari zitakapopasuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 4, 'Na makaburi yatakapofukuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 5, 'Hapo kila nafsi itajua ilichotanguliza, na ilichobakisha nyuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 6, 'Ewe mwanadamu! Nini kilichokudanganya ukamwacha Mola wako Mlezi Mtukufu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 7, 'Aliyekuumba, akakuweka sawa, akakunyoosha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 8, 'Katika sura yoyote aliyoipenda akakujenga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 9, 'Sivyo hivyo! Bali nyinyi mnaikanusha Siku ya Malipo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 10, 'Na hakika bila ya shaka wapo walinzi juu yenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 11, 'Waandishi wenye heshima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 12, 'Wanayajua mnayoyatenda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 13, 'Hakika wema bila ya shaka watakuwa katika neema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 14, 'Na hakika waovu bila ya shaka watakuwa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 15, 'Wataingia humo Siku ya Malipo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 16, 'Na hawatoacha kuwamo humo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 17, 'Na nini kitakachokujulisha Siku ya Malipo ni siku gani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 18, 'Tena nini kitakachokujulisha Siku ya Malipo ni siku gani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 19, 'Siku ambayo nafsi haitakuwa na mamlaka yoyote juu ya nafsi nyingine; na amri yote siku hiyo ni ya Mwenyezi Mungu tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 1, 'Ole wao hao wapunjao!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 2, 'Ambao wanapojipimia kwa watu hudai watimiziwe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 3, 'Na wao wanapowapimia watu kwa kipimo au mizani hupunguza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 4, 'Kwani hawadhani hao kwamba watafufuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 5, 'Katika Siku iliyo kuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 6, 'Siku watakapomsimamia watu Mola Mlezi wa walimwengu wote?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 7, 'Hasha! Hakika maandiko ya wakosefu bila ya shaka yamo katika Sijjin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 8, 'Unajua nini Sijjin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 9, 'Kitabu kilichoandikwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 10, 'Ole wao siku hiyo kwa wanaokadhibisha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 11, 'Ambao wanaikadhibisha Siku ya Malipo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 12, 'Wala haikadhibishi ila kila mwenye kuruka mipaka, mwenye dhambi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 13, 'Anaposomewa Aya zetu husema: "Ni visa vya watu wa kale!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 14, 'Hasha! Bali yametia kutu juu ya nyoyo zao hao waliokuwa wakiyachuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 15, 'Hasha! Hakika hao siku hiyo bila ya shaka watazuiliwa mbali na neema za Mola wao Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 16, 'Kisha wataingia Motoni!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 17, 'Kisha waambiwe: Haya ndiyo mliyokuwa mkiyakadhibisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 18, 'Hasha! Hakika maandiko ya watu wema bila ya shaka yamo katika Illiyyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 19, 'Na nini kitakachokujuvya nini Iliyyin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 20, 'Kitabu kilichoandikwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 21, 'Wanakishuhudia waliokaribishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 22, 'Hakika watu wema bila ya shaka watakuwa katika neema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 23, 'Wakae juu ya viti vya enzi wakiangalia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 24, 'Utatambua katika nyuso zao mng''aro wa neema,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 25, 'Watanyweshwa kinywaji safi kilichozibwa vyema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 26, 'Kizibo chake ni miski. Na katika hayo na washindanie wenye kushindana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 27, 'Na mchanganyiko wake ni Tasniim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 28, 'Chemchemi watakayoinywa waliokurubishwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 29, 'Kwa hakika wale waliokuwa wahalifu walikuwa wakiwacheka walioamini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 30, 'Na wanapopita karibu yao wakikonyezana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 31, 'Na wanaporudi kwa watu wao hurudi nao wamefurahi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 32, 'Na wanapowaona husema: Hakika hawa ndio hasa waliopotea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 33, 'Na wao hawakutumwa wawe walinzi juu yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 34, 'Basi leo walioamini ndio watawacheka makafiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 35, 'Nao wako juu ya viti vya enzi wakiangalia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 36, 'Je, makafiri wamelipwa malipo ya yale waliyokuwa wakiyatenda?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 1, 'Itakapochanika mbingu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 2, 'Na ikamsikiliza Mola wake Mlezi, na ikapasiwa kumsikiliza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 3, 'Na ardhi itakapotanuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 4, 'Na kuvitoa vilivyokuwa ndani yake, ikawa tupu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 5, 'Na ikamsikiliza Mola wake Mlezi, na ikapasiwa kumsikiliza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 6, 'Ewe mtu! Hakika wewe unafanya matendo kwa juhudi kumwendea Mola wako Mlezi, basi utamkuta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 7, 'Ama atakayepewa daftari lake kwa mkono wa kulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 8, 'Basi huyo atahisabiwa hisabu nyepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 9, 'Na arudi kwa ahali zake na furaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 10, 'Na ama atakayepewa daftari lake kwa nyuma ya mgongo wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 11, 'Basi huyo ataomba kuteketea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 12, 'Na ataingia Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 13, 'Hakika alikuwa furahani kati ya jamaa zake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 14, 'Huyo hakika alidhani kuwa hatarejea tena.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 15, 'Kwani? Hakika Mola wake Mlezi alikuwa akimwona vyema!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 16, 'Basi ninaapa kwa wekundu wa jua linapokuchwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 17, 'Na kwa usiku na unavyovikusanya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 18, 'Na kwa mwezi unapopevuka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 19, 'Lazima mtapanda tabaka kwa tabaka!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 20, 'Basi wana nini hawaamini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 21, 'Na wanaposomewa Qur-ani hawasujudu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 22, 'Bali waliokufuru wanakanusha tu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 23, 'Na Mwenyezi Mungu anajua wanayoyadhamiria.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 24, 'Basi wabashirie adhabu chungu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 25, 'Isipokuwa wale walioamini na wakatenda mema; hao watakuwa na ujira usiomalizika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 1, 'Ninaapa kwa mbingu yenye nyota kubwa kubwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 2, 'Na kwa Siku iliyoahidiwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 3, 'Na kwa shahidi na kinachoshuhudiwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 4, 'Wameangamizwa watu wa makhandaki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 5, 'Yenye moto wenye kuni nyingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 6, 'Walipokuwa wamekaa hapo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 7, 'Na wao ni mashahidi wa yale waliyokuwa wakiwafanyia Waumini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 8, 'Nao hawakuona baya lolote kwao ila kuwa walikuwa wakimuamini Mwenyezi Mungu, Mwenye nguvu, Msifiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 9, 'Ambaye anao ufalme wa mbingu na ardhi; na Mwenyezi Mungu ni shahidi wa kila kitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 10, 'Hakika waliowafitini Waumini wanaume na Waumini wanawake, kisha hawakutubu, basi watapata adhabu ya Jahannamu na watapata adhabu ya kuungua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 11, 'Hakika walioamini na wakatenda mema watapata Bustani za mbinguni zenye mito ipitayo kati yake. Huko ndiko kufuzu kukubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 12, 'Hakika kutesa kwa Mola wako Mlezi ni kukali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 13, 'Yeye ndiye anayeanzisha na ndiye anayerejesha tena.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 14, 'Naye ni Mwenye kusamehe, Mwenye mapenzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 15, 'Mwenye Kiti cha Enzi, Mtukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 16, 'Atendaye ayatakayo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 17, 'Je! Zimekufikia habari za Majeshi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 18, 'Ya Firauni na Thamudi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 19, 'Lakini waliokufuru wamo katika kukadhibisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 20, 'Na Mwenyezi Mungu nyuma yao amewazingira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 21, 'Bali hii ni Qur-ani tukufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 22, 'Katika Ubao uliohifadhiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 1, 'Ninaapa kwa mbingu na kinachokuja usiku!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 2, 'Na nini kitakachokujulisha ni nini hicho kinachokuja usiku?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 3, 'Ni Nyota yenye mwanga mkali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 4, 'Hapana nafsi ila inaye mwangalizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 5, 'Hebu na ajitazame mwanadamu ameumbwa kwa kitu gani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 6, 'Ameumbwa kwa maji yatokayo kwa kuchupa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 7, 'Yatokayo baina ya mifupa ya mgongo na mbavu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 8, 'Hakika Yeye ana uweza wa kumrudisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 9, 'Siku zitakapodhihirishwa siri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 10, 'Basi hatakuwa na nguvu wala msaidizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 11, 'Ninaapa kwa mbingu yenye marejeo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 12, 'Na kwa ardhi inayopasuka!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 13, 'Hakika hii ni kauli ya kupambanua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 14, 'Wala si mzaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 15, 'Hakika wao wanapanga mpango.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 16, 'Na Mimi napanga mpango.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 17, 'Basi wape muhula makafiri - wape muhula pole pole.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 1, 'Litakase jina la Mola wako Mlezi aliye juu kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 2, 'Aliyeumba, na akaweka sawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 3, 'Na ambaye amekadiria na akaongoa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 4, 'Na aliyeotesha malisho.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 5, 'Kisha akayafanya makavu, meusi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 6, 'Tutakusomesha wala hutasahau.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 7, 'Ila akipenda Mwenyezi Mungu. Hakika Yeye anayajua yaliyo dhahiri na yaliyofichikana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 8, 'Na tutakusahilishia yawe mepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 9, 'Basi kumbusha, kama makumbusho yanafaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 10, 'Atakumbuka mwenye kuogopa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 11, 'Na atajitenga mbali nayo mpotovu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 12, 'Ambaye atauingia Moto mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 13, 'Tena humo hatakufa wala hawi hai.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 14, 'Hakika amekwisha fanikiwa aliyejitakasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 15, 'Na akakumbuka jina la Mola wake Mlezi, na akasali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 16, 'Lakini nyinyi mnapendelea maisha ya dunia!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 17, 'Na Akhera ni bora na yenye kudumu zaidi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 18, 'Hakika haya yamo katika Vitabu vya mwanzo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 19, 'Vitabu vya Ibrahimu na Musa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 1, 'Je, imekufikia habari ya Msiba wa kufudikiza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 2, 'Siku hiyo nyuso zitainama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 3, 'Zikifanya kazi, nazo taabani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 4, 'Ziingie katika Moto unaowaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 5, 'Zikinyweshwa kutoka chemchemi inayochemka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 6, 'Hawatakuwa na chakula isipokuwa kichungu chenye miba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 7, 'Hakinenepeshi wala hakiondoi njaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 8, 'Siku hiyo nyuso nyengine zitakuwa kunjufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 9, 'Zitakuwa radhi kwa juhudi yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 10, 'Katika Bustani ya juu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 11, 'Hawatasikia humo upuuzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 12, 'Humo imo chemchemi inayomiminika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 13, 'Humo vimo viti vilivyonyanyuliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 14, 'Na bilauri zilizopangwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 15, 'Na matakia safu safu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 16, 'Na mazulia yaliyotandikwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 17, 'Je! Hawamtazami ngamia jinsi alivyoumbwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 18, 'Na mbingu jinsi ilivyoinuliwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 19, 'Na milima jinsi ilivyowekwa imara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 20, 'Na ardhi jinsi ilivyotandazwa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 21, 'Basi kumbusha! Hakika wewe ni Mkumbushaji.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 22, 'Wewe si mwenye kuwatawalia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 23, 'Lakini anayerudi nyuma na kukataa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 24, 'Basi Mwenyezi Mungu atamuadhibu kwa adhabu iliyo kubwa kabisa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 25, 'Hakika ni kwetu Sisi ndio marejeo yao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 26, 'Kisha hakika ni juu yetu Sisi hisabu yao!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 1, 'Ninaapa kwa alfajiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 2, 'Na kwa masiku kumi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 3, 'Na kwa viwili viwili na kimoja kimoja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 4, 'Na kwa usiku unapopita.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 5, 'Je, hapana katika haya kiapo kwa mwenye akili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 6, 'Kwani hukuona jinsi Mola wako Mlezi alivyowafanya kina A''di?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 7, 'Wa Iram, wenye majumba marefu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 8, 'Ambao haukuumbwa mfano wake katika nchi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 9, 'Na Thamudi waliochonga majabali huko bondeni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 10, 'Na Firauni mwenye vigingi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 11, 'Ambao walifanya jeuri katika nchi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 12, 'Wakakithirisha humo ufisadi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 13, 'Basi Mola wako Mlezi aliwapiga mjeledi wa adhabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 14, 'Hakika Mola wako Mlezi yupo kwenye mavizio anawavizia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 15, 'Ama mtu anapojaribiwa na Mola wake Mlezi, akamkirimu na akamneemesha, husema: Mola wangu Mlezi amenikirimu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 16, 'Na ama anapomjaribu akampunguzia riziki yake, husema: Mola wangu Mlezi amenitia unyonge!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 17, 'Sivyo hivyo! Bali nyinyi hamuwakirimu mayatima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 18, 'Wala hamhimizani kulisha masikini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 19, 'Na mnakula urithi kwa ulaji wa pupa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 20, 'Na mnapenda mali pendo la kupita kiasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 21, 'Sivyo hivyo! Itakapovunjwa ardhi vipande vipande.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 22, 'Na akaja Mola wako Mlezi na Malaika safu safu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 23, 'Na ikaletwa Jahannamu siku hiyo, siku hiyo mtu atakumbuka! Lakini kukumbuka huko kutamfaa nini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 24, 'Atasema: Laiti ningelijitangulizia kwa uhai wangu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 25, 'Basi siku hiyo hataadhibu yeyote namna ya kuadhibu kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 26, 'Wala hatafunga yeyote kama kufunga kwake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 27, 'Ewe nafsi iliyotua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 28, 'Rejea kwa Mola wako Mlezi umeridhika, na umeridhiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 29, 'Basi ingia miongoni mwa waja wangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 30, 'Na ingia katika Bustani yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 1, 'Ninaapa kwa Mji huu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 2, 'Nawe unaukaa Mji huu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 3, 'Na ninaapa kwa mzazi na alichokizaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 4, 'Hakika tumemuumba mtu katika taabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 5, 'Ati anadhani hapana yeyote atakayemuweza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 6, 'Anasema: Nimeteketeza chungu ya mali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 7, 'Ati anadhani ya kuwa hapana yeyote anayemwona?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 8, 'Kwani hatukumpa macho mawili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 9, 'Na ulimi, na midomo miwili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 10, 'Na tukambainishia zote njia mbili?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 11, 'Lakini hakujitoma kwenye njia ya vikwazo vya milimani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 12, 'Na nini kitakachokujuvya ni nini njia ya vikwazo vya milimani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 13, 'Kumkomboa mtumwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 14, 'Au kumlisha siku ya njaa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 15, 'Yatima aliye jamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 16, 'Au masikini aliye vumbini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 17, 'Tena awe miongoni mwa walioamini na wakausiana kusubiri na wakausiana kuhurumiana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 18, 'Hao ndio watu wa kheri wa kuliani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 19, 'Lakini waliozikataa Ishara zetu, hao ndio watu wa shari wa kushotoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 20, 'Juu yao utakuwa Moto uliofungiwa kila upande.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 1, 'Ninaapa kwa jua na mwangaza wake!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 2, 'Na kwa mwezi unapolifuatia!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 3, 'Na kwa mchana unapolidhihirisha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 4, 'Na kwa usiku unapolifunika!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 5, 'Na kwa mbingu na kwa aliyeijenga!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 6, 'Na kwa ardhi na kwa aliyeitandaza!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 7, 'Na kwa nafsi na kwa aliyeitengeneza!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 8, 'Kisha akaifahamisha uovu wake na wema wake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 9, 'Hakika amefanikiwa aliyeitakasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 10, 'Na hakika amehasiri aliyeiviza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 11, 'Kina Thamudi walikadhibisha kwa sababu ya upotovu wao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 12, 'Aliposimama mwovu wao mkubwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 13, 'Hapo Mtume wa Mwenyezi Mungu alipowaambia: Huyu ni ngamia wa Mwenyezi Mungu, mwacheni anywe maji fungu lake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 14, 'Lakini walimkadhibisha na wakamchinja ngamia, kwa hivyo Mola wao Mlezi aliwaangamiza kwa sababu ya dhambi zao na akawafuta kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 15, 'Wala Yeye haogopi matokeo yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 1, 'Ninaapa kwa usiku unapofunika!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 2, 'Na mchana unapodhihiri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 3, 'Na kwa aliyeumba dume na jike!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 4, 'Hakika juhudi zenu bila ya shaka ni mbali mbali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 5, 'Ama mwenye kutoa na akamcha Mungu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 6, 'Na akalisadiki lililo jema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 7, 'Tutamrahisishia yawe mepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 8, 'Na ama mwenye kufanya ubakhili, na asiwe na haja ya wenzake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 9, 'Na akakanusha lililo jema.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 10, 'Tutamrahisishia yawe mazito!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 11, 'Na mali yake itamfaa nini atakapokuwa anadidimia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 12, 'Hakika ni juu yetu kuonyesha uongofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 13, 'Na hakika ni yetu Sisi Akhera na dunia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 14, 'Basi nakuonyeni kutokana na Moto unaowaka vikali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 15, 'Hatauingia ila mwovu kabisa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 16, 'Anayekadhibisha na akageuka na kwenda zake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 17, 'Na mcha Mungu ataepushwa nao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 18, 'Ambaye hutoa mali yake kwa ajili ya kujitakasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 19, 'Na wala si kwa kuwa yupo yeyote aliyemfanyia hisani ndiyo anamlipa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 20, 'Ila ni kutaka uso wa Mola wake Mlezi aliye juu kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 21, 'Naye atakujaridhia!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 1, 'Ninaapa kwa wakati wa kabla ya adhuhuri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 2, 'Na kwa usiku unapotanda!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 3, 'Mola wako Mlezi hakukuacha, wala hakukasirika nawe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 4, 'Na bila ya shaka wakati ujao utakuwa bora kwako kuliko uliotangulia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 5, 'Na Mola wako Mlezi atakupa mpaka uridhike.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 6, 'Kwani hakukukuta yatima, akakupa makazi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 7, 'Na akakukuta umepotea, akakuongoa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 8, 'Akakukuta mhitaji akakutosheleza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 9, 'Basi yatima usimwonee!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 10, 'Na anayeomba au kuuliza usimkaripie!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 11, 'Na neema za Mola wako Mlezi zisimulie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 1, 'Hatukukunjulia kifua chako?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 2, 'Na tukakuondolea mzigo wako.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 3, 'Uliovunja mgongo wako?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 4, 'Na tukakunyanyulia utajo wako?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 5, 'Basi kwa hakika pamoja na uzito upo wepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 6, 'Hakika pamoja na uzito upo wepesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 7, 'Na ukipata faragha, fanya juhudi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 8, 'Na Mola wako Mlezi ndio mshughulikie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 1, 'Ninaapa kwa tini na zaituni!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 2, 'Na kwa Mlima wa Sinai!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 3, 'Na kwa Mji huu wenye amani mno!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 4, 'Bila ya shaka tumemuumba mtu kwa umbo lilio bora kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 5, 'Kisha tukamrudisha kuwa chini kuliko walio chini!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 6, 'Isipokuwa wale walioamini na wakatenda mema, hao watapata ujira usiokwisha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 7, 'Basi ni kipi baadaye kitakachokukukadhibishia malipo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 8, 'Kwani Mwenyezi Mungu si muadilifu zaidi kuliko wote wanaohukumu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 1, 'Soma kwa jina la Mola wako Mlezi aliyeumba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 2, 'Amemuumba binaadamu kwa tone la damu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 3, 'Soma! Na Mola wako Mlezi ni Karimu kushinda wote!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 4, 'Ambaye amefundisha kwa kalamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 5, 'Kamfundisha mtu aliyokuwa hayajui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 6, 'Kwani! Hakika mtu bila ya shaka huwa jeuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 7, 'Akijiona katajirika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 8, 'Hakika kwa Mola wako Mlezi ndio marejeo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 9, 'Umemuona yule anayemkataza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 10, 'Mja anaposali?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 11, 'Umeona kama yeye yuko juu ya uongofu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 12, 'Au anaamrisha ucha Mungu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 13, 'Umeona kama yeye akikanusha na anarudi nyuma?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 14, 'Hajui ya kwamba Mwenyezi Mungu anaona?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 15, 'Kwani! Kama haachi, tutamkokota kwa shungi la nywele!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 16, 'Shungi la uongo, lenye makosa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 17, 'Basi na awaite wenzake!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 18, 'Nasi tutawaita Mazabania!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 19, 'Hasha! Usimtii! Nawe sujudu na ujongee!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 1, 'Hakika Sisi tumeiteremsha Qur-ani katika Laylatul Qadri (Usiku wa Cheo Kitukufu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 2, 'Na nini kitachokujulisha nini Laylatul Qadri?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 3, 'Laylatul Qadri ni bora kuliko miezi elfu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 4, 'Huteremka Malaika na Roho katika usiku huo kwa idhini ya Mola wao Mlezi kwa kila jambo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 5, 'Amani usiku huo mpaka mapambazuko ya alfajiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 1, 'Hawakuwa waliokufuru miongoni mwa Watu wa Kitabu na washirikina waache waliyo nayo mpaka iwajie bayana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 2, 'Yaani Mtume aliyetoka kwa Mwenyezi Mungu anayewasomea kurasa zilizotakasika.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 3, 'Ndani yake mna maandiko yaliyonyooka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 4, 'Wala hawakufarikiana waliopewa Kitabu ila baada ya kuwajia hiyo bayana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 5, 'Nao hawakuamrishwa kitu ila wamuabudu Mwenyezi Mungu kwa kumtakasia Dini, wawe waongofu, na washike Sala, na watoe Zaka. Na hiyo ndiyo Dini madhubuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 6, 'Hakika waliokufuru miongoni mwa Watu wa Kitabu na washirikina wataingia katika Moto wa Jahannamu wadumu milele humo. Hao ndio viumbe waovu kabisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 7, 'Hakika walioamini na wakatenda mema, hao ndio bora wa viumbe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 8, 'Malipo yao kwa Mola wao Mlezi ni Bustani za mbinguni za daima, zipitazo mito kati yake. Wakae humo milele. Mwenyezi Mungu yu radhi nao, na wao wa radhi naye. Hayo ni kwa anayemwogopa Mola wake Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 1, 'Itakapotetemeshwa ardhi kwa mtetemeko wake!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 2, 'Na itakapotoa ardhi mizigo yake!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 3, 'Na mtu akasema: "Ina nini?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 4, 'Siku hiyo itahadithia habari zake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 5, 'Kwa sababu Mola wake Mlezi ameifunulia!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 6, 'Siku hiyo watu watatoka kwa mfarakano wakaonyweshwe vitendo vyao!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 7, 'Basi anayetenda chembe ya wema, atauona!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 8, 'Na anayetenda chembe ya uovu, atauona!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 1, 'Ninaapa kwa farasi waendao mbio wakipumua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 2, 'Na wakitoa moto kwa kupiga kwato zao chini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 3, 'Wakishambulia wakati wa asubuhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 4, 'Huku wakitimua vumbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 5, 'Na wakijitoma kati ya kundi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 6, 'Hakika mwanadamu ni mtovu wa fadhila kwa Mola wake Mlezi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 7, 'Na hakika yeye mwenyewe bila ya shaka ni shahidi wa hayo!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 8, 'Naye hakika bila ya shaka ana nguvu za kupenda mali!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 9, 'Kwani hajui watakapofufuliwa waliomo makaburini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 10, 'Na yakakusanywa yaliyomo vifuani?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 11, 'Hakika Mola wao Mlezi siku hiyo bila ya shaka atakuwa na habari zao wote!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 1, 'Inayogonga!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 2, 'Ni nini inayogonga?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 3, 'Na ni nini kitachokujulisha ni nini inayogonga?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 4, 'Siku ambayo watu watakuwa kama nondo waliotawanywa;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 5, 'Na milima itakuwa kama sufu zilizochambuliwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 6, 'Basi yule ambaye mizani yake itakuwa nzito.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 7, 'Huyo atakuwa katika maisha ya kupendeza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 8, 'Na yule ambaye mizani zake zitakuwa hafifu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 9, 'Huyo maskani yake yatakuwa Moto wa Hawiya!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 10, 'Na ni nini kitachokujulisha ni nini hiyo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 11, 'Ni Moto mkali!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 1, 'Kumekushughulisheni kutafuta wingi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 2, 'Mpaka mkaja makaburini!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 3, 'Sivyo hivyo! Mtakujajua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 4, 'Tena sivyo hivyo! Mtakujajua!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 5, 'Sivyo hivyo! Lau mngelijua kwa elimu ya yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 6, 'Basi bila ya shaka mtaiona Jahiimu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 7, 'Tena, bila ya shaka, mtaiona kwa jicho la yakini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 8, 'Tena bila ya shaka mtaulizwa siku hiyo juu ya neema zote.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 1, 'Ninaapa kwa Zama!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 2, 'Hakika binadamu bila ya shaka yuko katika hasara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 3, 'Ila wale walioamini, na wakatenda mema, na wakausiana kwa haki, na wakausiana kusubiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 1, 'Ole wake kila anayewakejeli watu kwa ishara na maneno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 2, 'Aliyekusanya mali na kuihesabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 3, 'Anadhani ya kuwa mali yake itambakisha milele!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 4, 'Hasha! Hakika atavurumishwa katika Hutwama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 5, 'Na ni nini kitakachokujulisha ni nini Hutwama?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 6, 'Ni Moto wa Mwenyezi Mungu uliowashwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 7, 'Ambao unapanda nyoyoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 8, 'Hakika huo utafungwa sawasawa nao wako ndani yake.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 9, 'Kwenye nguzo zilizonyooshwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 1, 'Kwani hukuona jinsi Mola wako Mlezi alivyowafanya wale wenye tembo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 2, 'Kwani hakufanya vitimbi vyao kuharibika?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 3, 'Na akawatumia ndege makundi kwa makundi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 4, 'Wakiwatupia mawe ya udongo wa Motoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 5, 'Akawafanya kama majani yaliyoliwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 1, 'Kwa walivyozoea Maqureshi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 2, 'Kuzoea kwao safari za siku za baridi na siku za joto.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 3, 'Basi na wamuabudu Mola Mlezi wa Nyumba hii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 4, 'Ambaye anawalisha kutokana na njaa, na anawalinda kutokana na hofu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 1, 'Je, umemwona anayekadhibisha Malipo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 2, 'Basi huyo ndiye anayemsukuma yatima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 3, 'Wala hahimizi kumlisha masikini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 4, 'Basi, ole wao wanaoswali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 5, 'Ambao wanapuuza Swala zao.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 6, 'Ambao wanajionyesha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 7, 'Na wanazuia msaada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 1, 'Hakika tumekupa Al-Kawthar (heri nyingi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 2, 'Basi swali na uchinje kwa ajili ya Mola wako Mlezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 3, 'Hakika anayekuchukia ndiye aliye mpungufu mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 1, 'Sema: Enyi makafiri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 2, 'Siabudu mnachokiabudu;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 3, 'Wala nyinyi hamuabudu ninayemuabudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 4, 'Wala sitaabudu mnachoabudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 5, 'Wala nyinyi hamuabudu ninayemuabudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 6, 'Nyinyi mna dini yenu, nami nina Dini yangu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 1, 'Itakapokuja nusura ya Mwenyezi Mungu na ushindi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 2, 'Na ukaona watu wanaingia katika Dini ya Mwenyezi Mungu kwa makundi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 3, 'Basi zitakase sifa za Mola wako Mlezi, na umwombe msamaha. Hakika Yeye ndiye anayepokea toba mno.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 1, 'Imeangamia mikono ya Abu Lahab, na yeye pia ameangamia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 2, 'Haitamfaa mali yake, wala alivyovichuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 3, 'Atauingia Moto wenye mwako mkali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 4, 'Na mkewe, mchukuzi mkubwa wa kuni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 5, 'Shingoni mwake iko kamba iliyosokotwa sawasawa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 1, 'Sema: Yeye Mwenyezi Mungu ni wa Pekee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 2, 'Mwenyezi Mungu ndiye Mkusudiwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 3, 'Hakuzaa wala hakuzaliwa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 4, 'Wala hana anayelingana naye hata mmoja.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 1, 'Sema: Ninajikinga kwa Mola Mlezi wa mapambazuko.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 2, 'Kutokana na uovu wa alivyoviumba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 3, 'Na kutokana na uovu wa giza la usiku liingiapo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 4, 'Na kutokana na uovu wa wanaopuliza mafundoni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 5, 'Na kutokana na uovu wa mwenye husuda anapohusudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 1, 'Sema: Ninajikinga kwa Mola Mlezi wa watu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 2, 'Mfalme wa watu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 3, 'Mungu wa watu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 4, 'Kutokana na uovu wa Shetani mtia wasiwasi, ajifichaye mno (Al-Khannaas).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 5, 'Anayetia wasiwasi katika vifua vya watu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 6, 'Kutokana na majini na watu.', '');
